def _tool_component_for_path(path: str) -> str:
    """返回工具路径的最小影响组件。"""

    if path in _ENVIRONMENT_PLANE_TOOL_FILES:
        return "environment"
    if path in _CONTROL_PLANE_TOOL_FILES:
        return "control"
    if (
        path in _EVALUATION_SIDE_FILES
        or path.endswith(".schema.json")
        or path in {"incremental_recovery.py", "codex_upgrade_gate_receipt.py"}
    ):
        return "evaluator"
    basename = path.rsplit("/", 1)[-1]
    if path in _SCENARIO_TOOL_FILES or path.startswith("versions/"):
        return "scenario"
    if basename in _RELAY_TOOL_FILES:
        return "relay"
    if basename in _PRODUCER_TOOL_FILES or basename.startswith("drive_"):
        return "producer"
    if path.startswith(_RUNTIME_TOOL_PREFIXES):
        return "runtime"
    if basename == "codex_upgrade.py":
        return "orchestrator"
    return "shared"


def _tool_component_identities(entries: list[dict[str, Any]]) -> dict[str, Any]:
    """按文件路径生成组件级身份；旧 Campaign 可由 entries 现场补算。"""

    assignments = {
        str(entry["path"]): _tool_component_for_path(str(entry["path"]))
        for entry in entries
    }
    identities = incremental_recovery.build_component_identities(
        entries, assignments, default_component="shared"
    )
    # 组件名固定，空组件也写入摘要，避免删除最后一个文件时无法观察漂移。
    components = dict(identities["components"])
    for name in sorted(_TOOL_COMPONENT_NAMES):
        components.setdefault(
            name,
            {
                "entry_count": 0,
                "entries": [],
                "sha256": incremental_recovery.digest({"entries": []}),
            },
        )
    return {
        "schema_version": identities["schema_version"],
        "component_count": len(components),
        "components": components,
        "all_sha256": identities["all_sha256"],
    }


def _tool_tree_entries(tool_root: Path) -> list[dict[str, Any]]:
    """按受管口径列出一棵工具树的文件摘要。

    抽成独立函数供两处共用：`_tool_identity` 算受管树自身的身份，
    `_verify_execution_tree` 用同一口径比对采集实际执行的那份副本。
    """

    files = sorted(
        path
        for path in tool_root.rglob("*")
        if (
            path.is_file()
            and not path.is_symlink()
            and path.suffix in {".py", ".sh", ".json"}
            and "tests" not in path.relative_to(tool_root).parts
            # 目标版本五件套会在 plan 后由人工审核产生，并由分类阶段独立绑定；
            # 它们不是编排器可执行信任根，不能反向击穿既有 Campaign。
            and "versions" not in path.relative_to(tool_root).parts
            and "__pycache__" not in path.relative_to(tool_root).parts
        )
    )
    return [
        {
            "path": path.relative_to(tool_root).as_posix(),
            "sha256": file_sha256(path),
        }
        for path in files
        if path.is_file() and not path.is_symlink()
    ]


def _verify_execution_tree(capture_root: Path | None) -> None:
    """确认采集实际执行的工具副本与受管树逐字一致。

    `_tool_identity` 只扫描本文件所在的受管树，而采集脚本与 relay 由
    `$CAPTURE_MOUNT/tools/official_client_capture/` 执行——那是**另一份副本**。
    k71 因此出现「工具身份校验通过、跑的却是旧代码」：受管树里
    `upstream_byte_relay.py` 的 `legacy_compact_ordinal`（Cookie 按到达序号下发）
    与 job 定义里写死的 `gpt-5.6-luna`（Lite 轨）都已就位，执行副本却停在更早版本，
    `EP-015`／`EP-022`／`EP-014`／`BODY-006` 四条判据随之必败，且没有任何门禁报警。
    职责边界：本校验只回答「存在的那份执行副本有没有漂移」。执行位置不存在时直接放行
    ——那不是漂移，而是路径配置问题，真实采集会在脚本解析
    `$CAPTURE_MOUNT/tools/...` 时自己失败；把「必须存在」也塞进来，只会让所有用假
    capture_root 的单元测试无法运行。存在但有文件缺失或摘要不符时 fail-close 拒绝。
    """

    if capture_root is None:
        return
    managed_root = Path(__file__).resolve().parent
    execution_root = capture_root / "tools" / "official_client_capture"
    try:
        execution_root_is_dir = execution_root.is_dir()
        execution_root_is_symlink = execution_root.is_symlink()
    except OSError:
        # CI 等普通用户可能连 capture_root 的父目录都无权遍历；这与目录不存在
        # 一样表示当前没有可执行副本可供比较。真实采集仍会在解析脚本时失败。
        return
    if not execution_root_is_dir or execution_root_is_symlink:
        return
    if execution_root.resolve() == managed_root.resolve():
        return
    actual = {
        entry["path"]: entry["sha256"]
        for entry in _tool_tree_entries(execution_root)
    }
    drift = [
        entry["path"]
        for entry in _tool_tree_entries(managed_root)
        if actual.get(entry["path"]) != entry["sha256"]
    ]
    if drift:
        raise ConfigurationError(
            "采集执行位置与受管工具树不一致，实际会跑到未受校验的副本："
            + f"{execution_root}；共 {len(drift)} 个文件漂移，前几个："
            + ", ".join(drift[:5])
        )


def _tool_identity(*, include_git: bool = True) -> dict[str, Any]:
    tool_root = Path(__file__).resolve().parent
    entries = _tool_tree_entries(tool_root)
    components = _tool_component_identities(entries)
    return {
        "git_commit": (
            _git_commit(Path(__file__).resolve().parents[2])
            if include_git
            else None
        ),
        "entry_count": len(entries),
        "files_sha256": _fingerprint({"entries": entries}),
        "entries": entries,
        "components": components["components"],
        "component_identity_sha256": _fingerprint(components),
        **_tool_identity_sides(entries),
    }


def _tool_identity_drift(
    current: Mapping[str, Any],
    expected: Mapping[str, Any],
) -> dict[str, list[str]]:
    """逐文件比对两份工具身份，按证据影响面归类变化路径。"""

    def index(identity: Mapping[str, Any]) -> dict[str, str]:
        raw = identity.get("entries")
        if not isinstance(raw, list):
            return {}
        return {
            str(item.get("path")): str(item.get("sha256"))
            for item in raw
            if isinstance(item, dict)
        }

    now, before = index(current), index(expected)
    changed = sorted(
        path
        for path in set(now) | set(before)
        if now.get(path) != before.get(path)
    )
    return {
        "production": [
            p
            for p in changed
            if p not in _EVALUATION_SIDE_FILES
            and p not in _WATCHDOG_ONLY_TOOL_FILES
        ],
        "evaluation": [
            p
            for p in changed
            if p in _EVALUATION_SIDE_FILES or p in _WATCHDOG_ONLY_TOOL_FILES
        ],
    }


def _tool_component_bundle(identity: Mapping[str, Any]) -> dict[str, Any]:
    """把新旧工具身份都规范化为组件包。"""

    if not isinstance(identity, Mapping):
        raise ConfigurationError("工具身份必须是对象。")
    components = identity.get("components")
    if isinstance(components, Mapping):
        normalized: dict[str, Any] = {}
        for name, value in components.items():
            if not isinstance(name, str) or not isinstance(value, Mapping):
                raise ConfigurationError("工具组件身份字段非法。")
            entries = value.get("entries")
            if not isinstance(entries, list):
                raise ConfigurationError(f"工具组件 {name} 缺少文件清单。")
            entry_count = value.get("entry_count")
            if (
                not isinstance(entry_count, int)
                or isinstance(entry_count, bool)
                or entry_count != len(entries)
            ):
                raise ConfigurationError(f"工具组件 {name} 条目数量非法。")
            if any(not isinstance(item, Mapping) for item in entries):
                raise ConfigurationError(f"工具组件 {name} 文件条目非法。")
            normalized[name] = {
                "entry_count": entry_count,
                "entries": [dict(item) for item in entries],
                "sha256": str(value.get("sha256", "")),
            }
        if normalized:
            bundle = {
                "schema_version": incremental_recovery.SCHEMA_VERSION,
                "component_count": len(normalized),
                "components": normalized,
                "all_sha256": identity.get("files_sha256"),
            }
            try:
                incremental_recovery.component_drift(bundle, bundle)
            except incremental_recovery.IncrementalRecoveryError as error:
                raise ConfigurationError(f"工具组件身份非法：{error}") from error
            recorded_identity = identity.get("component_identity_sha256")
            if recorded_identity is not None and recorded_identity != _fingerprint(bundle):
                raise ConfigurationError("工具组件总摘要不一致。")
            return bundle
    entries = identity.get("entries")
    if not isinstance(entries, list):
        raise ConfigurationError("工具身份缺少组件和文件清单。")
    if any(not isinstance(item, Mapping) for item in entries):
        raise ConfigurationError("工具身份文件条目非法。")
    return _tool_component_identities([dict(item) for item in entries])


def _canonicalize_tool_component_bundle(
    bundle: Mapping[str, Any],
) -> dict[str, Any]:
    """按统一白名单把历史误归入 shared 的评估文件迁移到 evaluator 再比较。

    0.149.1 及更早 Campaign 没有稳定的评估侧边界，直接比较原始组件摘要会把
    “组件归类修正”误判成 shared 产出侧变化，进而使无关 Job 失效。这里仅规范化
    比较视图，保留原始身份和漂移台账，不静默吞掉评估文件的真实内容改动。
    """

    components = bundle.get("components")
    if not isinstance(components, Mapping):
        raise ConfigurationError("工具组件身份缺少 components。")
    entries: list[dict[str, Any]] = []
    assignments: dict[str, str] = {}
    for component, value in components.items():
        if not isinstance(component, str) or not isinstance(value, Mapping):
            raise ConfigurationError("工具组件身份结构非法。")
        raw_entries = value.get("entries")
        if not isinstance(raw_entries, list):
            raise ConfigurationError(f"工具组件 {component} 文件清单非法。")
        for raw_entry in raw_entries:
            if not isinstance(raw_entry, Mapping):
                raise ConfigurationError("工具组件文件条目非法。")
            entry = {
                "path": str(raw_entry.get("path", "")),
                "sha256": str(raw_entry.get("sha256", "")),
            }
            path = entry["path"]
            if path in assignments:
                raise ConfigurationError(f"工具组件文件重复：{path}")
            assignments[path] = (
                _tool_component_for_path(path)
                if path in _EVALUATION_COMPONENT_FILES
                else component
            )
            entries.append(entry)
    try:
        canonical = incremental_recovery.build_component_identities(
            entries,
            assignments,
            default_component="shared",
        )
    except incremental_recovery.IncrementalRecoveryError as error:
        raise ConfigurationError(f"工具组件身份规范化失败：{error}") from error
    # 保持旧摘要中存在的空组件，避免“删除最后一个文件”被误报为组件新增；
    # 当前身份通常已经包含固定组件集合，历史身份则按其原有集合保留。
    for component in components:
        canonical.setdefault(
            "components", {}
        ).setdefault(
            component,
            {
                "entry_count": 0,
                "entries": [],
                "sha256": incremental_recovery.digest({"entries": []}),
            },
        )
    canonical["component_count"] = len(canonical["components"])
    return canonical


def _canonicalize_watchdog_component_bundle(
    bundle: Mapping[str, Any],
) -> dict[str, Any]:
    """兼容旧调用名；实际按全部已登记评估文件规范化。"""

    return _canonicalize_tool_component_bundle(bundle)


def _tool_component_drift(
    expected: Mapping[str, Any], current: Mapping[str, Any]
) -> dict[str, Any]:
    """计算组件摘要变化；兼容没有 components 字段的旧 Campaign。"""
    expected_bundle = _canonicalize_watchdog_component_bundle(
        _tool_component_bundle(expected)
    )
    current_bundle = _canonicalize_watchdog_component_bundle(
        _tool_component_bundle(current)
    )
    return incremental_recovery.component_drift(
        expected_bundle,
        current_bundle,
    )


def _affected_job_ids(
    jobs: Iterable[Job],
    changed_components: Iterable[str],
) -> list[str]:
    """按 Job 直接依赖选择最小失效闭集。

    编排器和纯评估器只影响失败项的判定，不会改变已经生成的抓包字节；
    其余高风险组件会使声明依赖该组件的 Job 失效。
    """

    changed = set(changed_components)
    high_risk = changed.intersection({"producer", "relay", "runtime", "shared", "scenario"})
    affected: list[str] = []
    for job in jobs:
        dependencies = set(_job_tool_components(job))
        if high_risk.intersection(dependencies):
            affected.append(job.job_id)
    return sorted(affected)


def _exact_tool_path_impact(
    jobs: Iterable[Job],
    expected_tool: Mapping[str, Any],
    current_tool: Mapping[str, Any],
) -> tuple[list[str], list[str], list[str]]:
    """按逐文件传递依赖计算 Job 失效集合；未知产出文件保持停线。"""

    planned = list(jobs)
    drift = _tool_identity_drift(current_tool, expected_tool)
    changed_paths = sorted(
        set(drift.get("production", [])) - set(_PHASE_EVALUATION_HYBRID_FILES)
    )
    impact_map = _tool_path_job_map(planned, expected_tool, current_tool)
    affected: set[str] = set()
    unmapped: list[str] = []
    for path in changed_paths:
        mapped = impact_map.get(path)
        if mapped is None:
            unmapped.append(path)
            continue
        affected.update(mapped)
    return sorted(affected), changed_paths, sorted(unmapped)


def _tool_path_job_map(
    jobs: Iterable[Job],
    expected_tool: Mapping[str, Any],
    current_tool: Mapping[str, Any],
) -> dict[str, set[str]]:
    """建立工具路径到计划 Job 的精确反向依赖表。"""

    planned = list(jobs)
    planned_ids = {job.job_id for job in planned}
    impact_map: dict[str, set[str]] = {}
    for job in planned:
        current_files = set(_job_tool_dependency_files(job, current_tool))
        expected_files = set(_job_tool_dependency_files(job, expected_tool))
        for path in current_files | expected_files:
            impact_map.setdefault(path, set()).add(job.job_id)
    for path, job_ids in RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS.items():
        impact_map.setdefault(path, set()).update(
            job_id
            for job_id in job_ids
            if job_id in planned_ids
        )
    return impact_map


def _build_incremental_tool_transition(
    expected_tool: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    impact: Mapping[str, Any],
    *,
    phase: str,
    planned_job_ids: Iterable[str],
) -> dict[str, Any]:
    """为低风险工具修复生成 attempt 绑定的组件过渡事实。"""

    changed = sorted(str(item) for item in impact.get("changed_components", []))
    if not changed or not set(changed).issubset(_LOW_RISK_TOOL_COMPONENTS):
        raise ConfigurationError("只有控制／环境／评估组件可以原地建立增量过渡。")
    core = {
        "schema_version": INCREMENTAL_TOOL_TRANSITION_SCHEMA,
        "phase": phase,
        "from_component_identity_sha256": _fingerprint(
            _tool_component_bundle(expected_tool)
        ),
        "to_component_identity_sha256": _fingerprint(
            _tool_component_bundle(current_tool)
        ),
        "changed_components": changed,
        "changed_paths": impact.get("changed_paths", {}),
        "planned_job_ids": sorted(str(item) for item in planned_job_ids),
        "affected_job_ids": sorted(
            str(item) for item in impact.get("affected_job_ids", [])
        ),
        "raw_evidence_scanned_bytes": 0,
    }
    return {**core, "transition_sha256": _fingerprint(core)}


def _validate_incremental_tool_transition(
    transition: Mapping[str, Any],
    expected_tool: Mapping[str, Any],
    current_tool: Mapping[str, Any],
) -> dict[str, Any]:
    """校验 attempt 中的低风险组件过渡，避免工具漂移被静默放行。"""

    if not isinstance(transition, Mapping):
        raise ConfigurationError("增量工具过渡结构非法。")
    required = {
        "schema_version",
        "phase",
        "from_component_identity_sha256",
        "to_component_identity_sha256",
        "changed_components",
        "changed_paths",
        "planned_job_ids",
        "affected_job_ids",
        "raw_evidence_scanned_bytes",
        "transition_sha256",
    }
    if set(transition) != required:
        raise ConfigurationError("增量工具过渡字段不闭合。")
    unsigned = dict(transition)
    recorded = unsigned.pop("transition_sha256")
    if recorded != _fingerprint(unsigned):
        raise ConfigurationError("增量工具过渡自摘要不一致。")
    changed = transition.get("changed_components")
    if (
        transition.get("schema_version") != INCREMENTAL_TOOL_TRANSITION_SCHEMA
        or not isinstance(changed, list)
        or not all(isinstance(item, str) and item for item in changed)
        or changed != sorted(set(changed))
        or not set(changed).issubset(_LOW_RISK_TOOL_COMPONENTS)
        or transition.get("raw_evidence_scanned_bytes") != 0
        or transition.get("from_component_identity_sha256")
        != _fingerprint(_tool_component_bundle(expected_tool))
        or transition.get("to_component_identity_sha256")
        != _fingerprint(_tool_component_bundle(current_tool))
    ):
        raise ConfigurationError("增量工具过渡身份或风险范围非法。")
    return dict(transition)


def _job_context(arguments: argparse.Namespace) -> dict[str, str]:
    return {
        "baseline_version": arguments.baseline_version,
        "target_version": arguments.target_version,
        "campaign_id": arguments.campaign_id,
        "candidate_id": str(getattr(arguments, "candidate_id", "") or ""),
        "capture_root": str(arguments.capture_root),
        "output": str(arguments.output),
        "campaign_dir": str(arguments.output),
        "repo_root": str(Path(__file__).resolve().parents[2]),
        "model": arguments.model,
        "lite_model": str(getattr(arguments, "lite_model", "") or ""),
        "runtime_image": str(arguments.runtime_image),
        "target_sha256": arguments.target_sha256,
        "profile_id": str(getattr(arguments, "profile_id", "") or ""),
        "profile_digest": str(getattr(arguments, "profile_digest", "") or ""),
        "build_id": str(getattr(arguments, "build_id", "") or ""),
        "deployed_version": str(
            getattr(arguments, "deployed_version", "") or ""
        ),
        "candidate_image_id": str(
            getattr(arguments, "candidate_image_id", "") or ""
        ),
        "source_tree_sha256": str(
            getattr(arguments, "source_tree_sha256", "") or ""
        ),
        "capture_container": arguments.capture_container,
        "service_container": arguments.service_container,
        "keeper_container": arguments.keeper_container,
        "postgres_container": arguments.postgres_container,
        "redis_container": arguments.redis_container,
        "capture_codex_bin": arguments.capture_codex_bin,
        "relay_codex_bin": arguments.relay_codex_bin,
        "codex_account_id": str(arguments.codex_account_id),
        "api_key_id": str(arguments.api_key_id),
        # A11 的 Live attestation 只读进程环境，采集侧需按本轮四元组重建候选服务。
        # Formal production_replacement 在参数校验阶段已禁止缺省为空。
        "live_attestation_compose_dir": str(
            getattr(arguments, "live_attestation_compose_dir", "") or ""
        ),
        "live_attestation_compose_files": str(
            getattr(arguments, "live_attestation_compose_files", "") or ""
        ),
    }


def _validate_jobs(jobs: list[Job], rules: tuple[str, ...]) -> None:
    duplicate_jobs = sorted(
        {
            job.job_id
            for job in jobs
            if sum(item.job_id == job.job_id for item in jobs) > 1
        }
    )
    if duplicate_jobs:
        raise ConfigurationError(f"任务 ID 重复：{duplicate_jobs}")
    evidence_owners: dict[tuple[str, str], list[str]] = {}
    for job in jobs:
        for root in job.evidence_roots:
            evidence_owners.setdefault((job.phase, root), []).append(job.job_id)
    duplicate_roots = {
        f"{phase}:{root}": sorted(set(job_ids))
        for (phase, root), job_ids in evidence_owners.items()
        if len(set(job_ids)) > 1
    }
    if duplicate_roots:
        raise ConfigurationError(
            "同一阶段的证据根必须由单一任务独占："
            f"{duplicate_roots}"
        )
    unknown_rules = sorted({rule for job in jobs for rule in job.covers} - set(rules))
    if unknown_rules:
        raise ConfigurationError(f"任务引用规则清单外编号：{unknown_rules}")
    unbound_jobs = sorted(
        job.job_id for job in jobs if job.covers and not job.scenario_ids
    )
    if unbound_jobs:
        raise ConfigurationError(
            "只有版本化场景清单中的任务可以声明规则覆盖；"
            f"未绑定场景的任务={unbound_jobs}"
        )
    _validate_capture_runtime_ids(jobs)


def _validate_capture_runtime_ids(jobs: Iterable[Job]) -> None:
    """在创建 attempt 前复算 direct／mitm 最终运行 ID 的长度边界。

    场景清单中的 ``RUN_ID_PREFIX`` 不是最终值；mitm 矩阵还会追加主体、
    场景、单场景 attempt 和 16 字符 UTC 窗口。只检查 Campaign 或 candidate ID 会把超长坐标拖到
    真实任务启动后才暴露，既浪费时间又留下必败 attempt，因此这里按脚本
    的确定性拼接规则提前失败关闭。
    """

    invalid: list[str] = []
    for job in jobs:
        for step_index, step in enumerate(job.steps, start=1):
            environment = step.get("environment", {})
            if not isinstance(environment, dict):
                raise ConfigurationError(
                    f"{job.job_id} 第 {step_index} 步的环境变量结构非法。"
                )

            projected: list[tuple[str, str]] = []
            run_id = environment.get("RUN_ID")
            if run_id:
                projected.append(("RUN_ID", str(run_id)))

            run_id_prefix = environment.get("RUN_ID_PREFIX")
            if run_id_prefix:
                subjects = str(environment.get("SUBJECTS", "")).split()
                scenarios = str(environment.get("SCENARIOS", "")).split()
                if not subjects:
                    raise ConfigurationError(
                        f"{job.job_id} 使用 RUN_ID_PREFIX 时必须冻结 SUBJECTS。"
                    )
                if not scenarios:
                    raise ConfigurationError(
                        f"{job.job_id} 使用 RUN_ID_PREFIX 时必须冻结 SCENARIOS。"
                    )
                window_id = str(
                    environment.get("WINDOW_ID", "")
                    or RUNTIME_WINDOW_ID_PLACEHOLDER
                )
                prefix = str(run_id_prefix)
                projected.append(
                    ("RUN_ID_PREFIX/setup", f"{prefix}.setup-a9-{window_id}")
                )
                projected.extend(
                    (
                        f"RUN_ID_PREFIX/{subject}/{scenario}",
                        f"{prefix}-{subject}-{scenario}-a9-{window_id}",
                    )
                    for subject in subjects
                    for scenario in scenarios
                )

            for coordinate, value in projected:
                if not SAFE_ID_RE.fullmatch(value):
                    invalid.append(
                        f"{job.job_id}:step-{step_index}:{coordinate}="
                        f"{len(value)}字符"
                    )

    if invalid:
        raise ConfigurationError(
            "抓包运行坐标超过 direct／mitm 的 128 字符安全边界；必须缩短 "
            "Campaign／candidate ID 后重新生成坐标，禁止先创建必败 attempt："
            + "、".join(invalid)
        )


def _validate_phase_coverage(jobs: list[Job], rules: tuple[str, ...]) -> None:
    required = set(rules)
    missing = {
        phase: sorted(
            required
            - {
                rule
                for job in jobs
                if job.phase == phase and job.required
                for rule in job.covers
            }
        )
        for phase in ("official", "candidate")
    }
    incomplete = {phase: values for phase, values in missing.items() if values}
    if incomplete:
        raise ConfigurationError(f"full 场景清单存在未映射规则：{incomplete}")


def _load_plan_jobs(
    arguments: argparse.Namespace,
    rules: tuple[str, ...],
) -> tuple[list[Job], Path, Path]:
    """同时冻结 baseline 分析场景与 target 正式执行场景。

    baseline 清单只描述升级前已经成立的发现与规则坐标；真正运行目标 CLI 的 official
    Attempt 必须使用 target 清单。两份清单分别校验且都不可缺省，避免目标版本需要的
    entrypoint、分支触发或恢复契约被旧命令模板静默吞掉。
    """

    scenario_manifest = arguments.scenario_manifest
    target_scenario_manifest = arguments.target_scenario_manifest
    for label, path in (
        ("baseline 场景清单", scenario_manifest),
        ("target 场景清单", target_scenario_manifest),
    ):
        if not path.is_file() or path.is_symlink():
            raise ConfigurationError(f"{label}不存在或不可信：{path}")
    context = _job_context(arguments)
    baseline_assertion_profile = Path(__file__).with_name(
        "candidate_rule_expectations_"
        f"{arguments.baseline_version.replace('.', '_')}.json"
    )
    baseline_source_spec_binding = (
        _load_frozen_assertion_source_spec_binding(
            baseline_assertion_profile,
            arguments.baseline_version,
        )
    )
    baseline_jobs = load_scenario_jobs(
        scenario_manifest,
        context,
        expected_version=arguments.baseline_version,
        expected_rule_sha256=file_sha256(arguments.rule_manifest),
        require_bindings=True,
        historical_source_spec_binding=baseline_source_spec_binding,
    )
    target_payload = _read_json(target_scenario_manifest, "target 场景清单")
    target_rule_binding = target_payload.get("rule_manifest")
    if (
        not isinstance(target_rule_binding, dict)
        or target_rule_binding.get("rule_count") != len(rules)
    ):
        raise ConfigurationError(
            "target 场景清单的规则数量与当前升级规则全集不一致。"
        )
    target_jobs = load_scenario_jobs(
        target_scenario_manifest,
        context,
        expected_version=arguments.target_version,
        require_bindings=True,
    )
    extra_jobs = load_extra_jobs(arguments.extra_jobs, context)
    baseline_jobs = [
        job for job in [*baseline_jobs, *extra_jobs] if arguments.suite in job.suites
    ]
    target_jobs = [
        job for job in [*target_jobs, *extra_jobs] if arguments.suite in job.suites
    ]
    _validate_jobs(baseline_jobs, rules)
    _validate_jobs(target_jobs, rules)
    if arguments.suite == "full":
        _validate_phase_coverage(baseline_jobs, rules)
        _validate_phase_coverage(target_jobs, rules)
    return target_jobs, scenario_manifest, target_scenario_manifest


def _control_receipt_relative(root: Path, value: Path, label: str) -> str:
    """把控制收据规范化为其受管根内的 POSIX 相对路径。"""

    if not root.is_absolute() or not root.is_dir() or root.is_symlink():
        raise ConfigurationError(f"{label} 的 evidence root 必须是现有非符号链接绝对目录。")
    resolved_root = root.resolve(strict=True)
    candidate = value if value.is_absolute() else resolved_root / value
    try:
        resolved = candidate.resolve(strict=True)
        relative = resolved.relative_to(resolved_root).as_posix()
    except (OSError, RuntimeError, ValueError) as error:
        raise ConfigurationError(f"{label} 必须位于其受管根内。") from error
    if candidate.is_symlink() or not resolved.is_file():
        raise ConfigurationError(f"{label} 必须是非符号链接普通文件。")
    return relative


def _job_rehearsal_configuration(
    source: Mapping[str, Any] | argparse.Namespace,
) -> dict[str, Any]:
    """提取会改变 Job 实际执行的固定配置。"""

    def value(field: str) -> Any:
        if isinstance(source, Mapping):
            current = source.get(field)
        else:
            current = getattr(source, field, None)
        return str(current) if isinstance(current, Path) else current

    return {
        field: value(field)
        for field in codex_upgrade_job_rehearsal_receipt.EXECUTION_CONFIGURATION_FIELDS
    }


def _job_rehearsal_contract_from_arguments(
    arguments: argparse.Namespace,
) -> dict[str, Any]:
    """按 Formal plan 输入复算应与 preflight 完全一致的执行合同。"""

    target_scenario = _read_json(
        arguments.target_scenario_manifest, "target 正式采集场景清单"
    )
    extra_jobs = (
        _read_json(arguments.extra_jobs, "附加任务清单")
        if arguments.extra_jobs is not None
        else None
    )
    try:
        return codex_upgrade_job_rehearsal_receipt.build_execution_contract(
            target_version=arguments.target_version,
            target_sha256=arguments.target_sha256,
            target_package_sha256=arguments.target_package_sha256,
            target_code_mode_host_sha256=arguments.target_code_mode_host_sha256,
            suite=arguments.suite,
            tool_files_sha256=_tool_identity()["files_sha256"],
            configuration=_job_rehearsal_configuration(arguments),
            target_scenario=target_scenario,
            extra_jobs=extra_jobs,
        )
    except codex_upgrade_job_rehearsal_receipt.JobRehearsalReceiptError as error:
        raise ConfigurationError(f"Formal Job 执行合同非法：{error}") from error


def _job_rehearsal_contract_from_manifest(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    target_scenario_override: Mapping[str, Any] | None = None,
    tool_files_sha256_override: str | None = None,
    recovery_rehearsal_receipt: Mapping[str, Any] | None = None,
    control_receipts_override: Mapping[str, Any] | None = None,
    _allow_historical_tool_identity: bool = False,
    _require_incremental_noop_preflight_active: bool = True,
    _allow_stopped_metadata_only: bool = False,
) -> dict[str, Any]:
    """从已封存 Formal Campaign 复算完整 Job 演练合同。"""

    inputs = manifest.get("inputs")
    if not isinstance(inputs, Mapping):
        raise ConfigurationError("Campaign 缺少输入绑定。")
    scenario_reference = inputs.get("target_discovery_scenarios")
    if not isinstance(scenario_reference, Mapping):
        raise ConfigurationError("Campaign 缺少 target 场景清单绑定。")
    frozen_target_scenario = _read_json(
        _campaign_file(campaign_dir, str(scenario_reference.get("path", ""))),
        "Campaign target 场景清单",
    )
    extra_reference = inputs.get("extra_jobs")
    extra_jobs = (
        _read_json(
            _campaign_file(campaign_dir, str(extra_reference.get("path", ""))),
            "Campaign 附加任务清单",
        )
        if isinstance(extra_reference, Mapping)
        else None
    )
    package = manifest.get("official_identity", {}).get("package")
    configuration = manifest.get("configuration")
    tool_identity = manifest.get("tool_identity")
    if (
        not isinstance(package, Mapping)
        or not isinstance(configuration, Mapping)
        or not isinstance(tool_identity, Mapping)
    ):
        raise ConfigurationError("Campaign 缺少 Job 演练所需身份。")
    def build(target_scenario: Mapping[str, Any]) -> dict[str, Any]:
        current_contract = codex_upgrade_job_rehearsal_receipt.build_execution_contract(
            target_version=str(manifest.get("target_version", "")),
            target_sha256=str(manifest.get("target_sha256", "")),
            target_package_sha256=str(package.get("asset_sha256", "")),
            target_code_mode_host_sha256=str(
                package.get("code_mode_host_sha256", "")
            ),
            suite=str(manifest.get("suite", "")),
            tool_files_sha256=(
                tool_files_sha256_override
                if tool_files_sha256_override is not None
                else str(tool_identity.get("files_sha256", ""))
            ),
            configuration=_job_rehearsal_configuration(configuration),
            target_scenario=target_scenario,
            extra_jobs=extra_jobs,
        )
        if not _allow_historical_tool_identity or not isinstance(
            recovery_rehearsal_receipt, Mapping
        ):
            return current_contract
        historical_contract = recovery_rehearsal_receipt.get(
            "execution_contract"
        )
        if not isinstance(historical_contract, Mapping):
            return current_contract
        historical_contract = dict(historical_contract)
        codex_upgrade_job_rehearsal_receipt.validate_execution_contract(
            historical_contract
        )
        changed = {
            key
            for key in set(current_contract) | set(historical_contract)
            if current_contract.get(key) != historical_contract.get(key)
        }
        if changed == {"evidence_label_declaration_sha256"}:
            # 历史 control epoch 已先重放并绑定这份演练收据。证据标签属于
            # evaluator 身份；只允许承接其旧摘要，Job、场景、环境、工具和
            # 其他合同字段任一变化仍由后续逐字合同校验失败关闭。
            return historical_contract
        return current_contract

    try:
        if target_scenario_override is not None:
            return build(target_scenario_override)
        frozen_contract = build(frozen_target_scenario)
        controls = (
            control_receipts_override
            if control_receipts_override is not None
            else manifest.get("control_receipts")
        )
        rehearsal = (
            controls.get("job_rehearsal")
            if isinstance(controls, Mapping)
            else None
        )
        bound_contract_sha256 = (
            rehearsal.get("execution_contract_sha256")
            if isinstance(rehearsal, Mapping)
            else None
        )
        predecessor = manifest.get("predecessor")
        classification_noop_successor = bool(
            isinstance(predecessor, Mapping)
            and predecessor.get("reason") == "classification_fact_correction"
        )
        control_refresh = bool(
            isinstance(predecessor, Mapping)
            and predecessor.get("reason")
            in {
                "candidate_recovery_control_refresh",
                "candidate_recovery_control_replacement",
            }
        )
        if control_refresh:
            if not isinstance(recovery_rehearsal_receipt, Mapping):
                raise ConfigurationError(
                    "控制刷新必须从绑定的 preflight/no-op 收据复算当前执行合同。"
                )
            control_manifest: Mapping[str, Any] = manifest
            if control_receipts_override is not None:
                current_tool = _tool_identity(include_git=False)
                effective_tool: Mapping[str, Any] = current_tool
                if (
                    tool_files_sha256_override is None
                    or current_tool.get("files_sha256")
                    != tool_files_sha256_override
                ):
                    if not _allow_historical_tool_identity:
                        raise ConfigurationError(
                            "control epoch 当前工具身份与有效控制收据不一致。"
                        )
                    preflight = recovery_rehearsal_receipt.get(
                        "preflight_campaign"
                    )
                    preflight_dir = (
                        Path(str(preflight.get("path", "")))
                        if isinstance(preflight, Mapping)
                        else Path("")
                    )
                    historical_manifest = load_campaign_manifest(preflight_dir)
                    historical_tool = historical_manifest.get("tool_identity")
                    if (
                        not isinstance(historical_tool, Mapping)
                        or historical_tool.get("files_sha256")
                        != tool_files_sha256_override
                    ):
                        raise ConfigurationError(
                            "control epoch 历史 preflight 工具身份与 base epoch 不一致。"
                        )
                    effective_tool = historical_tool
                proxy = json.loads(json.dumps(manifest, ensure_ascii=False))
                proxy["control_receipts"] = json.loads(
                    json.dumps(control_receipts_override, ensure_ascii=False)
                )
                proxy["tool_identity"] = json.loads(
                    json.dumps(effective_tool, ensure_ascii=False)
                )
                control_manifest = proxy
            preflight_dir, preflight_manifest = (
                _recovery_rehearsal_preflight_from_receipt(
                    recovery_rehearsal_receipt,
                    control_manifest,
                )
            )
            current_scenario = _recovery_rehearsal_target_scenario_override(
                campaign_dir,
                manifest,
                preflight_dir,
                preflight_manifest,
            )
            current_contract = build(
                current_scenario
                if current_scenario is not None
                else frozen_target_scenario
            )
            if bound_contract_sha256 != (
                codex_upgrade_job_rehearsal_receipt.execution_contract_sha256(
                    current_contract
                )
            ):
                raise ConfigurationError(
                    "控制刷新绑定的 preflight/no-op 执行合同摘要不一致。"
                )
            return current_contract
        if classification_noop_successor:
            noop_kwargs: dict[str, Any] = {
                # 当前 effective control override 已在外层验证 active；这里
                # 读取的是祖先分类纠正 no-op，只能按历史 checkpoint 重放。
                "require_active": (
                    _require_incremental_noop_preflight_active
                    and control_receipts_override is None
                ),
            }
            if _allow_stopped_metadata_only:
                noop_kwargs["allow_stopped_metadata_only"] = True
            noop_preflight = _successor_incremental_noop_preflight(
                manifest,
                **noop_kwargs,
            )
            if noop_preflight is not None:
                preflight_dir, preflight_manifest = noop_preflight
                current_scenario = _recovery_rehearsal_target_scenario_override(
                    campaign_dir,
                    manifest,
                    preflight_dir,
                    preflight_manifest,
                )
                current_contract = build(
                    current_scenario
                    if current_scenario is not None
                    else frozen_target_scenario
                )
                if bound_contract_sha256 != (
                    codex_upgrade_job_rehearsal_receipt.execution_contract_sha256(
                        current_contract
                    )
                ):
                    raise ConfigurationError(
                        "分类纠正后继绑定的 no-op 执行合同摘要不一致。"
                    )
                return current_contract
        if (
            bound_contract_sha256
            == codex_upgrade_job_rehearsal_receipt.execution_contract_sha256(
                frozen_contract
            )
            or not isinstance(manifest.get("predecessor"), Mapping)
        ):
            return frozen_contract

        # 同版本后继可保留历史 Formal 场景字节，同时由已批准的当前场景
        # 证明执行合同等价。新演练绑定若指向当前批准场景，就按该场景复算。
        classification_path = campaign_dir / "classification" / "result.json"
        if classification_path.is_file() and not classification_path.is_symlink():
            classification = _read_json(
                classification_path,
                "后继 Campaign 分类结果",
            )
            approved_reference = classification.get("scenario_manifest")
            if isinstance(approved_reference, dict):
                historical_binding = (
                    _successor_uses_reclassified_historical_plan_binding(
                        campaign_dir,
                        dict(manifest),
                        {"scenario_manifest": approved_reference},
                        allow_historical_approved_source_spec=(
                            _allow_historical_tool_identity
                        ),
                    )
                )
                if historical_binding is not None:
                    approved_scenario = _read_json(
                        _campaign_file(
                            campaign_dir,
                            str(approved_reference.get("path", "")),
                        ),
                        "后继 Campaign 当前批准场景",
                    )
                    approved_contract = build(approved_scenario)
                    if bound_contract_sha256 == (
                        codex_upgrade_job_rehearsal_receipt.execution_contract_sha256(
                            approved_contract
                        )
                    ):
                        return approved_contract
        return frozen_contract
    except codex_upgrade_job_rehearsal_receipt.JobRehearsalReceiptError as error:
        raise ConfigurationError(f"Campaign Job 执行合同非法：{error}") from error


def _job_rehearsal_control_from_receipt(
    rehearsal_root: Path,
    rehearsal_path: Path,
    expected_contract: Mapping[str, Any],
    *,
    allow_incremental_noop: bool = False,
) -> dict[str, Any]:
    """重放完整 Job 演练并生成可写入 Campaign 的不可变绑定。"""

    rehearsal_relative = _control_receipt_relative(
        rehearsal_root,
        rehearsal_path,
        "ARM64 完整 Job 离线演练收据",
    )
    try:
        rehearsal = codex_upgrade_job_rehearsal_receipt.replay(
            rehearsal_root, rehearsal_relative
        )
        pass_receipt = _assert_job_rehearsal_compatible(
            rehearsal,
            expected_contract,
            allow_incremental_noop=allow_incremental_noop,
        )
    except (
        OSError,
        codex_upgrade_job_rehearsal_receipt.JobRehearsalReceiptError,
    ) as error:
        raise ConfigurationError(
            f"ARM64 完整 Job 离线演练收据未通过：{error}"
        ) from error
    resolved_rehearsal = rehearsal_root.resolve(strict=True)
    rehearsal_file = resolved_rehearsal / rehearsal_relative
    preflight = rehearsal["preflight_campaign"]
    return {
        "evidence_root": str(resolved_rehearsal),
        "receipt": {
            "path": rehearsal_relative,
            "sha256": file_sha256(rehearsal_file),
            "bytes": rehearsal_file.stat().st_size,
        },
        "preflight_campaign_id": preflight["campaign_id"],
        "preflight_campaign_manifest_sha256": preflight["manifest_sha256"],
        "execution_contract_sha256": rehearsal["execution_contract_sha256"],
        # incremental-noop 只证明当前恢复合同无需执行；运行时通过事实必须
        # 继续来自其已重放的原始 passed 收据。
        "runtime_identity_sha256": pass_receipt["runtime_identity_sha256"],
        "job_count": rehearsal["job_count"],
        "job_set_sha256": rehearsal["job_set_sha256"],
    }


def _assert_job_rehearsal_compatible(
    receipt: Mapping[str, Any],
    expected_contract: Mapping[str, Any],
    *,
    allow_incremental_noop: bool,
) -> dict[str, Any]:
    """按普通 Formal 或受管恢复语义返回承载运行时事实的通过收据。"""

    if allow_incremental_noop:
        return codex_upgrade_job_rehearsal_receipt.assert_recovery_compatible(
            receipt,
            dict(expected_contract),
        )
    codex_upgrade_job_rehearsal_receipt.assert_formal_compatible(
        receipt,
        dict(expected_contract),
    )
    return dict(receipt)


def _manifest_allows_incremental_noop_rehearsal(
    manifest: Mapping[str, Any],
) -> bool:
    """只有工具生成的 Formal successor 可以承接恢复 no-op。"""

    predecessor = manifest.get("predecessor")
    return bool(
        manifest.get("campaign_mode") == "formal"
        and isinstance(predecessor, Mapping)
        and predecessor.get("reason") in SUCCESSOR_REASONS
    )


def _plan_control_receipts(arguments: argparse.Namespace) -> dict[str, Any]:
    """在创建 Campaign 前重放并绑定时间、ARM64 与完整 Job 硬门禁。"""

    timing_root = getattr(arguments, "timing_ledger_dir", None)
    timing_receipt_path = getattr(arguments, "timing_receipt", None)
    arm_root = getattr(arguments, "arm64_environment_root", None)
    arm_receipt_path = getattr(arguments, "arm64_environment_receipt", None)
    if not all(
        isinstance(value, Path)
        for value in (timing_root, timing_receipt_path, arm_root, arm_receipt_path)
    ):
        raise ConfigurationError(
            "plan 必须显式提供 UpgradeTimingLedger 与 ARM64 P0 环境收据。"
        )
    assert isinstance(timing_root, Path)
    assert isinstance(timing_receipt_path, Path)
    assert isinstance(arm_root, Path)
    assert isinstance(arm_receipt_path, Path)
    timing_relative = _control_receipt_relative(
        timing_root, timing_receipt_path, "UpgradeTimingLedger checkpoint"
    )
    arm_relative = _control_receipt_relative(
        arm_root, arm_receipt_path, "ARM64 P0 环境收据"
    )
    try:
        timing_checkpoint = codex_upgrade_timing_ledger.replay(
            timing_root, timing_relative
        )
        timing_summary = codex_upgrade_timing_ledger.assert_usable(
            timing_root,
            timing_relative,
            baseline_version=arguments.baseline_version,
            target_version=arguments.target_version,
            campaign_purpose=arguments.campaign_purpose,
            # Formal 只能在 VC-0 新建。preflight_only 不会发送请求或推进
            # Campaign 阶段，允许在后续 active 阶段为工具修复重跑离线 P0。
            required_phase=(
                "VC-0" if arguments.campaign_mode == "formal" else None
            ),
        )
    except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
        raise ConfigurationError(f"UpgradeTimingLedger 未通过：{error}") from error
    try:
        arm_receipt = codex_upgrade_arm64_environment_receipt.replay(
            arm_root, arm_relative
        )
    except (
        OSError,
        codex_upgrade_arm64_environment_receipt.Arm64EnvironmentReceiptError,
    ) as error:
        raise ConfigurationError(f"ARM64 P0 环境收据未通过：{error}") from error
    if (
        arm_receipt.get("status") != "passed"
        or arm_receipt.get("phase") != "p0"
        or arm_receipt.get("subject_id") != timing_summary["upgrade_id"]
    ):
        raise ConfigurationError("ARM64 P0 环境收据与 UpgradeTimingLedger 身份不一致。")
    resolved_timing = timing_root.resolve(strict=True)
    resolved_arm = arm_root.resolve(strict=True)
    timing_file = resolved_timing / timing_relative
    arm_file = resolved_arm / arm_relative
    controls: dict[str, Any] = {
        "upgrade_timing": {
            "ledger_dir": str(resolved_timing),
            "ledger_plan_sha256": file_sha256(resolved_timing / "ledger.json"),
            "receipt": {
                "path": timing_relative,
                "sha256": file_sha256(timing_file),
                "bytes": timing_file.stat().st_size,
            },
            "upgrade_id": timing_summary["upgrade_id"],
            "evidence_decision": timing_summary["evidence_decision"],
            "checkpoint_head_sha256": timing_checkpoint["summary"]["head_sha256"],
        },
        "arm64_environment": {
            "evidence_root": str(resolved_arm),
            "receipt": {
                "path": arm_relative,
                "sha256": file_sha256(arm_file),
                "bytes": arm_file.stat().st_size,
            },
            "subject_id": arm_receipt["subject_id"],
            "contract_sha256": arm_receipt["contract_sha256"],
            "continuity_identity_sha256": arm_receipt[
                "continuity_identity_sha256"
            ],
        },
    }
    if arguments.campaign_mode == "formal":
        rehearsal_root = getattr(arguments, "job_rehearsal_root", None)
        rehearsal_path = getattr(arguments, "job_rehearsal_receipt", None)
        assert isinstance(rehearsal_root, Path)
        assert isinstance(rehearsal_path, Path)
        controls["job_rehearsal"] = _job_rehearsal_control_from_receipt(
            rehearsal_root,
            rehearsal_path,
            _job_rehearsal_contract_from_arguments(arguments),
        )
    return controls


def _metadata_only_stopped_timing_allowed(
    frozen_summary: Mapping[str, Any] | None,
    current_summary: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> bool:
    """只允许承接 VC-0 之后唯一 permanent-stop 且 live=0 的控制链。"""

    if not isinstance(frozen_summary, Mapping):
        return False
    if (
        frozen_summary.get("status") != "active"
        or frozen_summary.get("active_phase") != "VC-0"
        or frozen_summary.get("total_live_request_count") != 0
        or current_summary.get("status") != "stopped"
        or current_summary.get("active_phase") != "VC-0"
        or current_summary.get("total_live_request_count") != 0
        or current_summary.get("head_sequence")
        != frozen_summary.get("head_sequence", 0) + 1
        or not str(current_summary.get("next_action", "")).startswith(
            METADATA_ONLY_STOP_NEXT_ACTION_PREFIX
        )
    ):
        return False
    expected = {
        "baseline_version": str(manifest["baseline_version"]),
        "target_version": str(manifest["target_version"]),
        "campaign_purpose": str(manifest["campaign_purpose"]),
    }
    return all(current_summary.get(key) == value for key, value in expected.items())


def _metadata_only_historical_epoch_fallback_allowed(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    epoch: Mapping[str, Any],
) -> bool:
    """判断历史 control epoch 是否仅因预算到期而可回退到冻结控制。

    该回退只服务于零执行的 metadata-only seal。它不承接任何失败重试、
    live 请求或非零边界，也不改变 epoch 文件本身；后续仍由原始 Campaign
    冻结的 VC-0 permanent-stop 控制收据完成完整校验。
    """

    if epoch.get("boundary") != _control_epoch_zero_boundary():
        return False
    controls = epoch.get("successor_controls")
    timing = controls.get("upgrade_timing") if isinstance(controls, Mapping) else None
    if not isinstance(timing, Mapping):
        return False
    invariants = epoch.get("invariants")
    required_phase = (
        invariants.get("required_active_phase")
        if isinstance(invariants, Mapping)
        else None
    )
    if not isinstance(required_phase, str) or not required_phase:
        return False
    try:
        ledger_root, _checkpoint = _sealed_stage_timing_checkpoint(
            timing,
            label="metadata-only 历史 control epoch",
        )
        current = codex_upgrade_timing_ledger.inspect_ledger(ledger_root)
    except (
        ConfigurationError,
        OSError,
        ValueError,
        codex_upgrade_timing_ledger.TimingLedgerError,
    ):
        return False
    if (
        current.get("status") != "stop_required"
        or current.get("active_phase") != required_phase
        or current.get("total_live_request_count") != 0
        or current.get("same_root_cause_failures") not in ({}, None)
    ):
        return False

    frozen_controls = manifest.get("control_receipts")
    frozen_timing = (
        frozen_controls.get("upgrade_timing")
        if isinstance(frozen_controls, Mapping)
        else None
    )
    if not isinstance(frozen_timing, Mapping):
        return False
    try:
        frozen_root, frozen_checkpoint = _sealed_stage_timing_checkpoint(
            frozen_timing,
            label="metadata-only Campaign 冻结控制",
        )
        frozen_summary = frozen_checkpoint.get("summary")
        frozen_current = codex_upgrade_timing_ledger.inspect_ledger(frozen_root)
    except (
        ConfigurationError,
        OSError,
        ValueError,
        codex_upgrade_timing_ledger.TimingLedgerError,
    ):
        return False
    return _metadata_only_stopped_timing_allowed(
        frozen_summary,
        frozen_current,
        manifest,
    )


def _verify_control_receipts(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    require_active: bool,
    allow_stopped_metadata_only: bool = False,
    _control_override: Mapping[str, Any] | None = None,
    _tool_files_sha256_override: str | None = None,
    _historical_manifest_controls: bool = False,
) -> None:
    """重放 Campaign 当前有效控制收据；执行前额外检查实时墙钟。"""

    controls: Any = _control_override
    tool_files_sha256_override = _tool_files_sha256_override
    historical_control_tool = _historical_manifest_controls
    using_frozen_manifest_controls = False
    metadata_only_fallback_confirmed = False
    if controls is None:
        epoch = _load_control_epoch_receipt(
            campaign_dir,
            manifest,
            _allow_unrepaired_tool_drift=_historical_manifest_controls,
            _historical_ledger_heads=_historical_manifest_controls,
        )
        if epoch is not None:
            controls = epoch["successor_controls"]
            tool_files_sha256_override = str(
                epoch["invariants"]["tool_files_sha256"]
            )
            current_tool = _tool_identity(include_git=False)
            if current_tool.get("files_sha256") != tool_files_sha256_override:
                allowed_epoch_paths = _control_epoch_failed_scope_production_paths(
                    manifest,
                    current_tool,
                    epoch["source"],
                )
                if allowed_epoch_paths:
                    # 当前 data-plane 修复仍须由阶段 transition 批准；这里只把
                    # 既有 no-op 按其冻结工具身份重放，不能拿新摘要伪造旧控制。
                    historical_control_tool = True
            runtime_repair = epoch.get("runtime_repair")
            if isinstance(runtime_repair, Mapping):
                repair_path = _campaign_file(
                    campaign_dir,
                    str(runtime_repair.get("path", "")),
                )
                repair_payload = _read_json(
                    repair_path,
                    "control epoch 最新运行授权修复收据",
                )
                repair_invariants = repair_payload.get("invariants")
                repair_tool_sha256 = (
                    repair_invariants.get("tool_files_sha256")
                    if isinstance(repair_invariants, Mapping)
                    else None
                )
                if not SHA256_RE.fullmatch(str(repair_tool_sha256)):
                    raise ConfigurationError(
                        "control epoch 最新运行授权修复缺少控制工具身份。"
                    )
                # repair-02 之后只允许编排／评估侧变化。epoch 的
                # invariants 继续代表当前执行工具，而旧 no-op 必须按
                # 最新 repair 真实冻结的工具身份只读复核。
                if repair_tool_sha256 != tool_files_sha256_override:
                    tool_files_sha256_override = str(repair_tool_sha256)
                    historical_control_tool = True
            if (
                allow_stopped_metadata_only
                and _metadata_only_historical_epoch_fallback_allowed(
                    campaign_dir,
                    manifest,
                    epoch,
                )
            ):
                # 当前历史 control epoch 已在零执行边界因预算到期停线。
                # 只读承接 Campaign 冻结控制，禁止把 stop_required Ledger
                # 当作 active 使用，也禁止创建新的 epoch／successor。
                frozen_controls = manifest.get("control_receipts")
                if not isinstance(frozen_controls, dict):
                    raise ConfigurationError("Campaign 缺少冻结控制收据。")
                controls = json.loads(
                    json.dumps(frozen_controls, ensure_ascii=False)
                )
                tool_files_sha256_override = None
                historical_control_tool = True
                using_frozen_manifest_controls = True
                metadata_only_fallback_confirmed = True
        else:
            controls = manifest.get("control_receipts")
            using_frozen_manifest_controls = True
    expected_controls = {
        "upgrade_timing",
        "arm64_environment",
    }
    if manifest.get("campaign_mode") == "formal":
        expected_controls.add("job_rehearsal")
    if not isinstance(controls, dict) or set(controls) != expected_controls:
        raise ConfigurationError("Campaign 缺少完整控制收据绑定。")
    timing = controls.get("upgrade_timing")
    arm = controls.get("arm64_environment")
    if not isinstance(timing, dict) or not isinstance(arm, dict):
        raise ConfigurationError("Campaign 控制收据结构非法。")

    def validate_binding(value: Any, label: str) -> tuple[str, str, int]:
        if not isinstance(value, dict) or set(value) != {"path", "sha256", "bytes"}:
            raise ConfigurationError(f"{label}绑定字段不闭合。")
        relative = value.get("path")
        digest = value.get("sha256")
        size = value.get("bytes")
        if (
            not isinstance(relative, str)
            or not SHA256_RE.fullmatch(str(digest))
            or not isinstance(size, int)
            or isinstance(size, bool)
            or size <= 0
        ):
            raise ConfigurationError(f"{label}绑定非法。")
        return relative, str(digest), size

    try:
        timing_root = Path(str(timing["ledger_dir"]))
        timing_relative, timing_sha, timing_bytes = validate_binding(
            timing.get("receipt"), "UpgradeTimingLedger checkpoint"
        )
        timing_path = timing_root / timing_relative
        if (
            file_sha256(timing_root / "ledger.json")
            != timing.get("ledger_plan_sha256")
            or file_sha256(timing_path) != timing_sha
            or timing_path.stat().st_size != timing_bytes
        ):
            raise ConfigurationError("UpgradeTimingLedger 绑定摘要漂移。")
        timing_checkpoint = codex_upgrade_timing_ledger.replay(
            timing_root, timing_relative
        )
        if (
            timing_checkpoint["summary"].get("upgrade_id")
            != timing.get("upgrade_id")
            or timing_checkpoint["summary"].get("evidence_decision")
            != timing.get("evidence_decision")
            or timing_checkpoint["summary"].get("head_sha256")
            != timing.get("checkpoint_head_sha256")
        ):
            raise ConfigurationError("UpgradeTimingLedger checkpoint 身份漂移。")
        if require_active:
            if allow_stopped_metadata_only:
                current_summary = codex_upgrade_timing_ledger.inspect_ledger(
                    timing_root
                )
                safe_stopped_boundary = _metadata_only_stopped_timing_allowed(
                    timing_checkpoint.get("summary"),
                    current_summary,
                    manifest,
                )
                if safe_stopped_boundary:
                    pass
                else:
                    if current_summary.get("status") == "stopped":
                        raise ConfigurationError(
                            "metadata-only seal 只允许承接 VC-0 唯一 permanent-stop 且 live=0 的 Ledger。"
                        )
                    codex_upgrade_timing_ledger.assert_usable(
                        timing_root,
                        timing_relative,
                        baseline_version=str(manifest["baseline_version"]),
                        target_version=str(manifest["target_version"]),
                        campaign_purpose=str(manifest["campaign_purpose"]),
                    )
            else:
                codex_upgrade_timing_ledger.assert_usable(
                    timing_root,
                    timing_relative,
                    baseline_version=str(manifest["baseline_version"]),
                    target_version=str(manifest["target_version"]),
                    campaign_purpose=str(manifest["campaign_purpose"]),
                )
    except (
        KeyError,
        OSError,
        ValueError,
        codex_upgrade_timing_ledger.TimingLedgerError,
    ) as error:
        if isinstance(error, ConfigurationError):
            raise
        raise ConfigurationError(f"UpgradeTimingLedger 无法重放：{error}") from error

    try:
        arm_root = Path(str(arm["evidence_root"]))
        arm_relative, arm_sha, arm_bytes = validate_binding(
            arm.get("receipt"), "ARM64 P0 环境收据"
        )
        arm_path = arm_root / arm_relative
        if file_sha256(arm_path) != arm_sha or arm_path.stat().st_size != arm_bytes:
            raise ConfigurationError("ARM64 P0 环境收据绑定摘要漂移。")
        arm_receipt = codex_upgrade_arm64_environment_receipt.replay(
            arm_root, arm_relative
        )
        if (
            arm_receipt.get("status") != "passed"
            or arm_receipt.get("phase") != "p0"
            or arm_receipt.get("subject_id") != arm.get("subject_id")
            or arm_receipt.get("contract_sha256") != arm.get("contract_sha256")
            or arm_receipt.get("continuity_identity_sha256")
            != arm.get("continuity_identity_sha256")
            or arm.get("subject_id") != timing.get("upgrade_id")
        ):
            raise ConfigurationError("ARM64 P0 环境收据身份漂移。")
    except (
        KeyError,
        OSError,
        ValueError,
        codex_upgrade_arm64_environment_receipt.Arm64EnvironmentReceiptError,
    ) as error:
        if isinstance(error, ConfigurationError):
            raise
        raise ConfigurationError(f"ARM64 P0 环境收据无法重放：{error}") from error

    if manifest.get("campaign_mode") == "formal":
        rehearsal = controls.get("job_rehearsal")
        if not isinstance(rehearsal, dict) or set(rehearsal) != {
            "evidence_root",
            "receipt",
            "preflight_campaign_id",
            "preflight_campaign_manifest_sha256",
            "execution_contract_sha256",
            "runtime_identity_sha256",
            "job_count",
            "job_set_sha256",
        }:
            raise ConfigurationError("Campaign 完整 Job 演练绑定字段不闭合。")
        try:
            rehearsal_root = Path(str(rehearsal["evidence_root"]))
            rehearsal_relative, rehearsal_sha, rehearsal_bytes = validate_binding(
                rehearsal.get("receipt"), "ARM64 完整 Job 离线演练收据"
            )
            rehearsal_path = rehearsal_root / rehearsal_relative
            if (
                file_sha256(rehearsal_path) != rehearsal_sha
                or rehearsal_path.stat().st_size != rehearsal_bytes
            ):
                raise ConfigurationError("完整 Job 演练收据绑定摘要漂移。")
            receipt = codex_upgrade_job_rehearsal_receipt.replay(
                rehearsal_root, rehearsal_relative
            )
            expected_contract = _job_rehearsal_contract_from_manifest(
                campaign_dir,
                manifest,
                recovery_rehearsal_receipt=receipt,
                tool_files_sha256_override=tool_files_sha256_override,
                _allow_historical_tool_identity=historical_control_tool,
                # control-epoch 发布前还没有新 epoch。此时旧控制必须按
                # Campaign 冻结的历史工具身份只读重放；发布后的正常加载
                # 若直接使用 campaign.json 的冻结控制，也必须走原生清单
                # 路径；只有 epoch/runtime-repair 的控制才属于 override。
                control_receipts_override=(
                    None if using_frozen_manifest_controls else controls
                ),
                # 只读加载历史 Campaign 时，no-op 的 preflight 只重放
                # 不可变 checkpoint；真正执行阶段仍要求其当前 active。
                _require_incremental_noop_preflight_active=(
                    require_active and not metadata_only_fallback_confirmed
                ),
                # 只有本层已经确认了 VC-0 唯一 permanent-stop、live=0 的
                # metadata-only fallback，才允许 no-op 内层承接 stopped Ledger。
                _allow_stopped_metadata_only=metadata_only_fallback_confirmed,
            )
            pass_receipt = _assert_job_rehearsal_compatible(
                receipt,
                expected_contract,
                allow_incremental_noop=(
                    _manifest_allows_incremental_noop_rehearsal(manifest)
                ),
            )
            preflight = receipt["preflight_campaign"]
            if (
                preflight.get("campaign_id")
                != rehearsal.get("preflight_campaign_id")
                or preflight.get("manifest_sha256")
                != rehearsal.get("preflight_campaign_manifest_sha256")
                or receipt.get("execution_contract_sha256")
                != rehearsal.get("execution_contract_sha256")
                or pass_receipt.get("runtime_identity_sha256")
                != rehearsal.get("runtime_identity_sha256")
                or receipt.get("job_count") != rehearsal.get("job_count")
                or receipt.get("job_set_sha256")
                != rehearsal.get("job_set_sha256")
            ):
                raise ConfigurationError("Campaign 完整 Job 演练身份漂移。")
        except (
            KeyError,
            OSError,
            ValueError,
            codex_upgrade_job_rehearsal_receipt.JobRehearsalReceiptError,
        ) as error:
            if isinstance(error, ConfigurationError):
                raise
            raise ConfigurationError(
                f"ARM64 完整 Job 离线演练收据无法重放：{error}"
            ) from error


def create_campaign(arguments: argparse.Namespace) -> dict[str, Any]:
    """创建只写一次的 Campaign 核心清单和计划期分析产物。"""

    _validate_arguments(arguments)
    control_receipts = _plan_control_receipts(arguments)
    rules = load_rule_manifest(arguments.rule_manifest, arguments.baseline_version)
    jobs, scenario_manifest, target_scenario_manifest = _load_plan_jobs(
        arguments, rules
    )
    baseline_identity, baseline_source = _source_identity(
        arguments.baseline_source, arguments.baseline_version
    )
    target_identity, target_source = _source_identity(
        arguments.target_source, arguments.target_version
    )
    source_diff = compare_inventory(baseline_source, target_source)
    baseline_surface = scan_evidence(
        [arguments.baseline_evidence], "baseline-official"
    )

    campaign_dir = arguments.campaign_dir
    ensure_private_directory(campaign_dir)
    inputs_root = ensure_private_directory(campaign_dir / "inputs", campaign_dir)
    analysis_root = ensure_private_directory(campaign_dir / "analysis", campaign_dir)
    baseline_rules_payload = _read_json(arguments.rule_manifest, "基线规则清单")
    scenario_payload = _read_json(scenario_manifest, "baseline 发现场景清单")
    target_scenario_payload = _read_json(
        target_scenario_manifest, "target 正式采集场景清单"
    )
    secure_write_json(inputs_root / "baseline-rules.json", baseline_rules_payload)
    secure_write_json(inputs_root / "discovery-scenarios.json", scenario_payload)
    secure_write_json(
        inputs_root / "target-discovery-scenarios.json", target_scenario_payload
    )
    extra_jobs_reference: dict[str, Any] | None = None
    if arguments.extra_jobs is not None:
        extra_payload = _read_json(arguments.extra_jobs, "附加任务清单")
        secure_write_json(inputs_root / "extra-jobs.json", extra_payload)
        extra_jobs_reference = {
            "path": "inputs/extra-jobs.json",
            "sha256": file_sha256(inputs_root / "extra-jobs.json"),
        }
    for name, payload in (
        ("baseline-source.json", baseline_source),
        ("target-source.json", target_source),
        ("source-diff.json", source_diff),
        ("baseline-surface.json", baseline_surface),
    ):
        secure_write_json(analysis_root / name, payload)

    official_identity = {
        "cli_version": arguments.target_version,
        "binary_sha256": arguments.target_sha256,
        "package": arguments.target_package_identity,
        "source_tree_sha256": target_identity["source_tree_sha256"],
        "cargo_lock_sha256": target_identity["cargo_lock_sha256"],
        "git_commit": target_identity["git_commit"],
        "runtime_image": arguments.runtime_image,
        "operating_system": sys.platform,
        "architecture": os.uname().machine,
        "tls_dependencies_sha256": _fingerprint(
            {
                "entries": [
                    item
                    for item in target_source.get("entries", [])
                    if item.get("kind") == "network_dependency"
                ]
            }
        ),
    }
    # 冻结工具身份之前先确认执行副本与受管树一致：这里记进 manifest 的是受管树的
    # 摘要，若执行位置此刻已经漂移，整轮采集都会跑在未受校验的代码上（k71 即此）。
    _verify_execution_tree(getattr(arguments, "capture_root", None))
    plan = _safe_plan(arguments, jobs, rules)
    manifest = {
        "schema_version": CAMPAIGN_SCHEMA,
        "campaign_id": arguments.campaign_id,
        "created_at_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "campaign_mode": arguments.campaign_mode,
        "campaign_purpose": arguments.campaign_purpose,
        "baseline_version": arguments.baseline_version,
        "target_version": arguments.target_version,
        "target_sha256": arguments.target_sha256,
        "suite": arguments.suite,
        "official_identity": official_identity,
        "baseline_identity": baseline_identity,
        "tool_identity": _tool_identity(),
        "control_receipts": control_receipts,
        "inputs": {
            "baseline_rules": {
                "path": "inputs/baseline-rules.json",
                "sha256": file_sha256(inputs_root / "baseline-rules.json"),
            },
            "discovery_scenarios": {
                "path": "inputs/discovery-scenarios.json",
                "sha256": file_sha256(inputs_root / "discovery-scenarios.json"),
            },
            "target_discovery_scenarios": {
                "path": "inputs/target-discovery-scenarios.json",
                "sha256": file_sha256(
                    inputs_root / "target-discovery-scenarios.json"
                ),
            },
            "extra_jobs": extra_jobs_reference,
        },
        "analysis": {
            name: {
                "path": f"analysis/{name}.json",
                "sha256": file_sha256(analysis_root / f"{name}.json"),
            }
            for name in (
                "baseline-source",
                "target-source",
                "source-diff",
                "baseline-surface",
            )
        },
        "configuration": {
            "baseline_source": str(arguments.baseline_source.resolve()),
            "target_source": str(arguments.target_source.resolve()),
            "target_package": str(arguments.target_package.resolve()),
            "baseline_evidence": str(arguments.baseline_evidence.resolve()),
            "runtime_image": arguments.runtime_image,
            "model": arguments.model,
            "lite_model": arguments.lite_model,
            "capture_root": str(arguments.capture_root),
            "capture_container": arguments.capture_container,
            "service_container": arguments.service_container,
            "keeper_container": arguments.keeper_container,
            "postgres_container": arguments.postgres_container,
            "redis_container": arguments.redis_container,
            "capture_codex_bin": arguments.capture_codex_bin,
            "relay_codex_bin": arguments.relay_codex_bin,
            "capture_code_mode_host_bin": arguments.capture_code_mode_host_bin,
            "relay_code_mode_host_bin": arguments.relay_code_mode_host_bin,
            "codex_account_id": arguments.codex_account_id,
            "api_key_id": arguments.api_key_id,
            "live_attestation_compose_dir": str(
                getattr(arguments, "live_attestation_compose_dir", "") or ""
            ),
            "live_attestation_compose_files": str(
                getattr(arguments, "live_attestation_compose_files", "") or ""
            ),
        },
        "required_rules": list(rules),
        "coverage_plan": plan["coverage_plan"],
        "jobs": plan["jobs"],
    }
    manifest_path = campaign_dir / "campaign.json"
    _secure_write_json_once(manifest_path, manifest)
    secure_write_text(
        campaign_dir / "campaign.sha256", file_sha256(manifest_path) + "\n"
    )
    return manifest


_CLASSIFICATION_APPROVAL_FIELDS = (
    "target_rule_manifest",
    "migration_manifest",
    "scenario_manifest",
    "profile_manifest",
    "assertion_profile_manifest",
)

_SUCCESSOR_OFFICIAL_SURFACE_PATH = "imports/official/surface.json"


def _copy_successor_binding(
    predecessor_dir: Path,
    staging_dir: Path,
    reference: Any,
    *,
    kind: str,
    copied_files: dict[str, dict[str, Any]],
    target_relative: str | None = None,
) -> dict[str, str]:
    """把一个前序 Campaign 文件逐字节复制到后继受管路径。"""

    _require_file_binding(reference, f"后继 Campaign {kind}")
    source_relative = str(reference["path"])
    destination_relative = target_relative or source_relative
    source = _campaign_file(predecessor_dir, source_relative)
    if source.is_symlink() or not source.is_file():
        raise ConfigurationError(
            f"前序 Campaign 文件不存在或不可信：{source_relative}"
        )
    expected_sha256 = str(reference["sha256"])
    if file_sha256(source) != expected_sha256:
        raise ConfigurationError(
            f"前序 Campaign 文件摘要漂移：{source_relative}"
        )
    existing = copied_files.get(destination_relative)
    if existing is not None:
        if (
            existing["source_path"] != source_relative
            or existing["sha256"] != expected_sha256
        ):
            raise ConfigurationError(
                "后继 Campaign 复制目标发生摘要冲突："
                + destination_relative
            )
        return {"path": destination_relative, "sha256": expected_sha256}
    destination = _campaign_file(staging_dir, destination_relative)
    copied = _secure_copy_file_once(source, destination)
    if copied["sha256"] != expected_sha256:
        raise ConfigurationError(
            f"后继 Campaign 复制摘要与绑定不一致：{source_relative}"
        )
    copied_files[destination_relative] = {
        "kind": kind,
        "source_path": source_relative,
        "target_path": destination_relative,
        "sha256": expected_sha256,
        "bytes": copied["bytes"],
    }
    return {"path": destination_relative, "sha256": expected_sha256}


def _successor_uses_reclassified_historical_plan_binding(
    staging_dir: Path,
    manifest: dict[str, Any],
    classification_bindings: dict[str, dict[str, str]],
    *,
    allow_historical_approved_source_spec: bool = False,
) -> HistoricalSourceSpecBinding | None:
    """判定已完成分类纠正的后继是否仍需重放历史 Formal 摘要。

    分类事实纠正只会追加批准五件套，不会改写 Formal 时冻结的 target 场景
    清单。因此后续运行时坐标后继可能同时看到：历史 Formal 清单仍绑定旧章节
    摘要，而批准场景已经绑定当前章节摘要。只有批准场景可按当前源码重验、
    且两份清单的官方执行合同完全一致时，才允许计划重建读取历史摘要。
    控制刷新后继禁止改变场景，因此继续冻结历史批准摘要；当前受管摘要由
    已绑定的 preflight/no-op 演练单独证明，不能反向击穿历史批准事实。
    """

    scenario_reference = manifest.get("inputs", {}).get(
        "target_discovery_scenarios"
    )
    if not isinstance(scenario_reference, dict):
        raise ConfigurationError(
            "同版本后继 Campaign 要求前序已冻结 target 场景清单。"
        )
    _require_file_binding(scenario_reference, "后继 Formal target 场景清单")
    frozen_path = _campaign_file(staging_dir, scenario_reference["path"])
    if (
        frozen_path.is_symlink()
        or not frozen_path.is_file()
        or file_sha256(frozen_path) != scenario_reference["sha256"]
    ):
        raise ConfigurationError("后继 Formal target 场景清单摘要不一致。")
    frozen = _read_json(frozen_path, "后继 Formal target 场景清单")
    _validate_scenario_manifest_shape(frozen)
    if frozen.get("codex_version") != manifest.get("target_version"):
        raise ConfigurationError("后继 Formal target 场景版本不一致。")
    frozen_binding = _scenario_source_spec_binding(
        frozen,
        label="后继 Formal target 场景",
    )
    source_path_text, _, fragment = frozen_binding.source_spec.partition("#")
    frozen_sha256 = frozen_binding.source_spec_sha256
    current_source = Path(__file__).resolve().parents[2] / source_path_text
    if not current_source.is_file() or current_source.is_symlink():
        raise ConfigurationError("后继 Formal target 场景规格文件不可信。")
    current_sha256 = source_spec_section_sha256(current_source, fragment)
    if frozen_sha256 == current_sha256:
        return None

    approved_reference = classification_bindings.get("scenario_manifest")
    if not isinstance(approved_reference, dict):
        raise ConfigurationError(
            "历史 Formal 摘要只能由已导入的当前批准场景承接。"
        )
    _require_file_binding(approved_reference, "后继批准场景清单")
    approved_path = _campaign_file(staging_dir, approved_reference["path"])
    if (
        approved_path.is_symlink()
        or not approved_path.is_file()
        or file_sha256(approved_path) != approved_reference["sha256"]
    ):
        raise ConfigurationError("后继批准场景清单摘要不一致。")
    approved = _read_json(approved_path, "后继批准场景清单")
    _validate_scenario_manifest_shape(approved)
    approved_source = approved.get("source_spec")
    control_refresh = (
        isinstance(manifest.get("predecessor"), Mapping)
        and manifest["predecessor"].get("reason")
        in {
            "candidate_recovery_control_refresh",
            "candidate_recovery_control_replacement",
        }
    )
    if (
        approved.get("codex_version") != manifest.get("target_version")
        or not isinstance(approved_source, dict)
        or approved_source.get("path") != source_path_text
        or approved_source.get("fragment") != fragment
        or (
            not control_refresh
            and not allow_historical_approved_source_spec
            and approved_source.get("sha256") != current_sha256
        )
    ):
        raise ConfigurationError(
            "历史 Formal 摘要对应的批准场景未绑定当前规格摘要。"
        )
    if _fingerprint(_official_scenario_execution_contract(frozen)) != _fingerprint(
        _official_scenario_execution_contract(approved)
    ):
        raise ConfigurationError(
            "历史 Formal 场景与当前批准场景的官方执行合同不一致。"
        )
    return frozen_binding


def _rebuild_successor_plan(
    staging_dir: Path,
    final_dir: Path,
    manifest: dict[str, Any],
    *,
    historical_source_spec_binding: HistoricalSourceSpecBinding | None = None,
) -> None:
    """用新 Campaign ID 重算计划坐标，证据与批准输入保持逐字不变。"""

    arguments = _campaign_arguments(staging_dir, manifest)
    arguments.output = final_dir
    arguments.campaign_dir = final_dir
    context = _job_context(arguments)
    scenario_reference = manifest["inputs"].get("target_discovery_scenarios")
    if not isinstance(scenario_reference, dict):
        raise ConfigurationError(
            "同版本后继 Campaign 要求前序已冻结 target 场景清单。"
        )
    scenario_path = _campaign_file(staging_dir, scenario_reference["path"])
    jobs = load_scenario_jobs(
        scenario_path,
        context,
        expected_version=manifest["target_version"],
        require_bindings=True,
        historical_source_spec_binding=historical_source_spec_binding,
    )
    extra_reference = manifest["inputs"].get("extra_jobs")
    if extra_reference is not None:
        jobs.extend(
            load_extra_jobs(
                _campaign_file(staging_dir, extra_reference["path"]),
                context,
            )
        )
    jobs = [job for job in jobs if manifest["suite"] in job.suites]
    rules = load_rule_manifest(
        _campaign_file(staging_dir, manifest["inputs"]["baseline_rules"]["path"]),
        manifest["baseline_version"],
    )
    _validate_jobs(jobs, rules)
    if manifest["suite"] == "full":
        _validate_phase_coverage(jobs, rules)
    plan = _safe_plan(arguments, jobs, rules)
    manifest["coverage_plan"] = plan["coverage_plan"]
    manifest["jobs"] = plan["jobs"]


def _successor_abandoned_attempt(
    predecessor_dir: Path,
    candidate_id: str | None,
    attempt_id: str | None,
    *,
    _historical_manifest_controls: bool = False,
) -> dict[str, Any] | None:
    """可选绑定前序中因不可变时间窗口而放弃的 candidate attempt。"""

    if bool(candidate_id) != bool(attempt_id):
        raise ConfigurationError(
            "--predecessor-candidate-id 与 --predecessor-attempt-id 必须同时提供。"
        )
    if candidate_id is None or attempt_id is None:
        return None
    if not SAFE_ID_RE.fullmatch(candidate_id) or not SAFE_ID_RE.fullmatch(attempt_id):
        raise ConfigurationError("前序 candidate-id 或 attempt-id 格式非法。")
    attempt_root, attempt = _load_capture_attempt(
        predecessor_dir,
        "candidate",
        candidate_id,
        attempt_id,
        _historical_manifest_controls=_historical_manifest_controls,
    )
    attempt_path = attempt_root / "attempt.json"
    return {
        "candidate_id": candidate_id,
        "attempt_id": attempt_id,
        "path": attempt_path.relative_to(predecessor_dir).as_posix(),
        "sha256": file_sha256(attempt_path),
        "attempt_digest": attempt["attempt_digest"],
        "identity_sha256": _fingerprint(attempt["identity"]),
        "status": attempt["status"],
    }


def _validate_failed_job_tool_recovery_source(
    predecessor_dir: Path,
    predecessor_manifest: Mapping[str, Any],
    successor_manifest: Mapping[str, Any],
    *,
    candidate_id: str,
    attempt_id: str,
    reason: str,
) -> None:
    """确认产出工具修复只影响前序 Candidate 的失败 Job 闭集。"""

    attempt_root, attempt = _load_capture_attempt(
        predecessor_dir,
        "candidate",
        candidate_id,
        attempt_id,
    )
    scope = _phase_evaluation_recovery_scope(
        predecessor_dir,
        predecessor_manifest,
        phase="candidate",
        candidate_id=candidate_id,
        attempt_root=attempt_root,
        attempt=attempt,
        allow_empty=False,
        allow_awaiting_failures=True,
    )
    failed_ids = set(scope.get("failed_job_ids", []))
    execute_ids = set(scope.get("execute_job_ids", []))
    if reason == "candidate_recovery_control_refresh":
        if attempt.get("status") != "failed" or not failed_ids:
            raise ConfigurationError(
                "控制刷新只接受已批准 transition 所属的 failed Candidate attempt。"
            )
    elif attempt.get("status") != "awaiting_receipts" or not failed_ids:
        raise ConfigurationError(
            "失败 Job 工具恢复只接受含可选失败项的 awaiting_receipts Candidate attempt。"
        )
    source_tool = predecessor_manifest.get("tool_identity")
    successor_tool = successor_manifest.get("tool_identity")
    if not isinstance(source_tool, Mapping) or not isinstance(
        successor_tool, Mapping
    ):
        raise ConfigurationError("失败 Job 工具恢复缺少源／目标工具身份。")
    drift = _tool_identity_drift(source_tool, successor_tool)
    high_risk_paths = set(drift.get("production", [])) - set(
        _PHASE_EVALUATION_HYBRID_FILES
    )
    target_scenario_path = (
        "codex_upgrade_scenarios_"
        f"{str(successor_manifest.get('target_version', '')).replace('.', '_')}.json"
    )
    if (
        target_scenario_path in high_risk_paths
        and _target_scenario_source_spec_only_drift(
            predecessor_dir,
            predecessor_manifest,
        )
    ):
        high_risk_paths.remove(target_scenario_path)
    unknown_paths = high_risk_paths - set(
        RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS
    )
    if unknown_paths:
        raise ConfigurationError(
            "失败 Job 工具恢复含未登记的产出侧工具变化："
            + "、".join(sorted(unknown_paths))
        )
    affected_ids = {
        job_id
        for path in high_risk_paths
        for job_id in RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS[path]
    }
    if not high_risk_paths:
        raise ConfigurationError("失败 Job 工具恢复没有可验证的产出侧工具变化。")
    if not affected_ids or not affected_ids.issubset(failed_ids):
        raise ConfigurationError(
            "失败 Job 工具恢复的产出侧变化触及复用 Job，禁止扩大重跑闭集。"
        )
    if not failed_ids.issubset(execute_ids):
        raise ConfigurationError("失败 Job 工具恢复遗漏前序失败项。")


def _target_scenario_source_spec_only_drift(
    predecessor_dir: Path,
    predecessor_manifest: Mapping[str, Any],
) -> bool:
    """仅识别目标场景中单独的规范章节摘要更新。"""

    try:
        target_version = str(predecessor_manifest.get("target_version", ""))
        if not VERSION_RE.fullmatch(target_version):
            return False
        inputs = predecessor_manifest.get("inputs")
        reference = (
            inputs.get("target_discovery_scenarios")
            if isinstance(inputs, Mapping)
            else None
        )
        if not isinstance(reference, Mapping):
            return False
        _require_file_binding(reference, "前序目标场景")
        frozen_path = _campaign_file(predecessor_dir, str(reference["path"]))
        current_path = Path(__file__).resolve().with_name(
            f"codex_upgrade_scenarios_{target_version.replace('.', '_')}.json"
        )
        if (
            frozen_path.is_symlink()
            or not frozen_path.is_file()
            or file_sha256(frozen_path) != reference["sha256"]
            or current_path.is_symlink()
            or not current_path.is_file()
        ):
            return False
        frozen = _read_json(frozen_path, "前序目标场景")
        current = _read_json(current_path, "当前目标场景")
        _validate_scenario_manifest_shape(frozen)
        _validate_scenario_manifest_shape(current)
        frozen_source = frozen.get("source_spec")
        current_source = current.get("source_spec")
        if not isinstance(frozen_source, dict) or not isinstance(current_source, dict):
            return False
        normalized = json.loads(json.dumps(frozen, ensure_ascii=False))
        normalized["source_spec"]["sha256"] = current_source.get("sha256")
        return normalized == current and frozen_source.get("sha256") != current_source.get(
            "sha256"
        )
    except (ConfigurationError, OSError, ValueError, TypeError):
        return False


def _successor_runtime_configuration(
    arguments: argparse.Namespace,
    predecessor_configuration: dict[str, Any],
) -> dict[str, str] | None:
    """校验并返回后继 Campaign 的新 Live attestation compose 坐标。

    compose 文件属于 Candidate 运行身份。历史路径已经被前序 Campaign 和
    attempt 引用，不能原位覆盖；只有运行时身份纠正后继可以通过 v4 收据
    冻结一组全新的可信绝对路径。其余配置仍由前序 Campaign 逐字承接。
    """

    compose_dir = getattr(arguments, "live_attestation_compose_dir", None)
    compose_files = str(
        getattr(arguments, "live_attestation_compose_files", "") or ""
    ).strip()
    if (compose_dir is None) != (not compose_files):
        raise ConfigurationError(
            "后继 compose 工作目录与 -f 参数串必须同时提供。"
        )
    if compose_dir is None:
        return None
    if arguments.reason != "candidate_runtime_identity_correction":
        raise ConfigurationError(
            "只有 candidate_runtime_identity_correction 后继可以改变 compose 坐标。"
        )

    resolved_dir = compose_dir.resolve(strict=False)
    if (
        not compose_dir.is_absolute()
        or str(resolved_dir) != str(compose_dir)
        or not SAFE_ABSOLUTE_PATH_RE.fullmatch(str(compose_dir))
        or compose_dir.is_symlink()
        or not compose_dir.is_dir()
    ):
        raise ConfigurationError(
            "--live-attestation-compose-dir 必须是可信的规范绝对目录。"
        )

    tokens = compose_files.split()
    compose_paths: list[str] = []
    expect_file = False
    for token in tokens:
        if expect_file:
            compose_paths.append(token)
            expect_file = False
            continue
        if token in {"-f", "--file"}:
            expect_file = True
            continue
        if token.startswith("-"):
            raise ConfigurationError(
                "--live-attestation-compose-files 只允许 -f/--file 参数。"
            )
        compose_paths.append(token)
    if expect_file or not compose_paths:
        raise ConfigurationError(
            "--live-attestation-compose-files 的 -f 参数串不完整。"
        )
    for raw_path in compose_paths:
        path = Path(raw_path)
        if (
            not path.is_absolute()
            or str(path.resolve(strict=False)) != raw_path
            or not SAFE_ABSOLUTE_PATH_RE.fullmatch(raw_path)
            or path.is_symlink()
            or not path.is_file()
        ):
            raise ConfigurationError(
                "后继 compose 参数必须引用存在、非符号链接的规范绝对文件："
                + raw_path
            )

    successor = {
        "live_attestation_compose_dir": str(compose_dir),
        "live_attestation_compose_files": compose_files,
    }
    if all(
        str(predecessor_configuration.get(field, "") or "") == value
        for field, value in successor.items()
    ):
        raise ConfigurationError("后继 compose 坐标没有发生变化。")
    return successor


def _runtime_codex_binary_bindings(
    scenario: Mapping[str, Any],
) -> tuple[dict[str, Any], frozenset[str]]:
    """移除唯一允许变化的 Candidate 二进制绑定并返回其 Job 集。"""

    normalized = json.loads(json.dumps(scenario, ensure_ascii=False))
    jobs = normalized.get("capture_jobs")
    if not isinstance(jobs, list):
        raise ConfigurationError("运行时纠正目标场景缺少 capture_jobs。")
    present: set[str] = set()
    indexed = {
        str(job.get("id")): job
        for job in jobs
        if isinstance(job, dict) and isinstance(job.get("id"), str)
    }
    if not RUNTIME_CODEX_BINARY_JOB_IDS.issubset(indexed):
        raise ConfigurationError("运行时纠正目标场景缺少固定客户端 Job。")
    for job_id in RUNTIME_CODEX_BINARY_JOB_IDS:
        job = indexed[job_id]
        steps = job.get("steps")
        if not isinstance(steps, list) or len(steps) != 1:
            raise ConfigurationError(
                f"运行时纠正目标场景的 {job_id} 必须只有一个步骤。"
            )
        step = steps[0]
        environment = step.get("environment") if isinstance(step, dict) else None
        if not isinstance(environment, dict):
            raise ConfigurationError(
                f"运行时纠正目标场景的 {job_id} 缺少 environment。"
            )
        if "CODEX_BIN" not in environment:
            continue
        if environment.get("CODEX_BIN") != "{capture_codex_bin}":
            raise ConfigurationError(
                f"运行时纠正目标场景的 {job_id} CODEX_BIN 非法。"
            )
        present.add(job_id)
        del environment["CODEX_BIN"]
    return normalized, frozenset(present)


def _validate_runtime_target_scenario_change(
    predecessor: Mapping[str, Any],
    successor: Mapping[str, Any],
) -> tuple[str, ...]:
    """只允许为固定五个 Candidate Job 补入目标 Codex 绝对路径绑定。"""

    _validate_scenario_manifest_shape(dict(predecessor))
    _validate_scenario_manifest_shape(dict(successor))
    if _fingerprint(_official_scenario_execution_contract(dict(predecessor))) != (
        _fingerprint(_official_scenario_execution_contract(dict(successor)))
    ):
        raise ConfigurationError("运行时纠正不得改变任何官方 Job 执行合同。")
    predecessor_normalized, predecessor_bindings = (
        _runtime_codex_binary_bindings(predecessor)
    )
    successor_normalized, successor_bindings = _runtime_codex_binary_bindings(
        successor
    )
    if predecessor_normalized != successor_normalized:
        raise ConfigurationError(
            "运行时纠正目标场景除固定 CODEX_BIN 外存在其他变化。"
        )
    if predecessor_bindings:
        raise ConfigurationError(
            "运行时纠正前序场景已经包含 CODEX_BIN，不能重复登记同一过渡。"
        )
    if successor_bindings != RUNTIME_CODEX_BINARY_JOB_IDS:
        raise ConfigurationError(
            "运行时纠正目标场景没有为全部固定客户端 Job 冻结 CODEX_BIN。"
        )
    changed = successor_bindings - predecessor_bindings
    if changed != RUNTIME_CODEX_BINARY_JOB_IDS:
        raise ConfigurationError("运行时纠正目标场景没有完整新增固定五个绑定。")
    return tuple(sorted(changed))


def _bound_runtime_scenario_transition_job_ids(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
) -> frozenset[str]:
    """沿只读前序链找到并重放当前 Formal 场景的运行时过渡。"""

    current_dir = campaign_dir.resolve(strict=True)
    current_manifest = dict(manifest)
    seen: set[Path] = set()
    for _ in range(64):
        if current_dir in seen:
            raise ConfigurationError("Campaign 前序链形成循环。")
        seen.add(current_dir)
        predecessor = current_manifest.get("predecessor")
        if not isinstance(predecessor, Mapping):
            return frozenset()
        predecessor_dir = Path(str(predecessor.get("campaign_dir", "")))
        if (
            not predecessor_dir.is_absolute()
            or predecessor_dir.is_symlink()
            or not predecessor_dir.is_dir()
            or predecessor_dir.resolve(strict=True) in seen
        ):
            raise ConfigurationError("运行时场景过渡的前序路径不可信。")
        predecessor_dir = predecessor_dir.resolve(strict=True)
        predecessor_manifest = load_campaign_manifest(
            predecessor_dir,
            # 这里正在重放不可变前序链；每一级都是历史上下文，不能只把
            # 直接控制替代前序切到历史模式后，又用当前源码校验更早祖先。
            _control_epoch_bootstrap=True,
        )
        if (
            predecessor.get("campaign_id")
            != predecessor_manifest.get("campaign_id")
            or predecessor.get("campaign_manifest_sha256")
            != file_sha256(predecessor_dir / "campaign.json")
        ):
            raise ConfigurationError("运行时场景过渡的前序绑定漂移。")
        current_reference = current_manifest.get("inputs", {}).get(
            "target_discovery_scenarios"
        )
        predecessor_reference = predecessor_manifest.get("inputs", {}).get(
            "target_discovery_scenarios"
        )
        _require_file_binding(current_reference, "当前 Formal target 场景")
        _require_file_binding(predecessor_reference, "前序 Formal target 场景")
        assert isinstance(current_reference, dict)
        assert isinstance(predecessor_reference, dict)
        if current_reference == predecessor_reference:
            current_dir = predecessor_dir
            current_manifest = predecessor_manifest
            continue

        receipt_path = current_dir / "predecessor-import.json"
        receipt = _read_json(receipt_path, "运行时场景过渡收据")
        unsigned_receipt = dict(receipt)
        receipt_digest = unsigned_receipt.pop("receipt_digest", None)
        transition = receipt.get("target_scenario_transition")
        if (
            receipt.get("schema_version")
            != PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA
            or receipt.get("reason") != "candidate_runtime_identity_correction"
            or not SHA256_RE.fullmatch(str(receipt_digest))
            or _fingerprint(unsigned_receipt) != receipt_digest
            or not isinstance(transition, Mapping)
            or transition.get("reason")
            != "candidate_codex_binary_binding_correction"
            or transition.get("predecessor") != predecessor_reference
            or transition.get("successor") != current_reference
        ):
            return frozenset()
        predecessor_scenario = _read_json(
            _campaign_file(predecessor_dir, predecessor_reference["path"]),
            "运行时过渡前序场景",
        )
        current_scenario = _read_json(
            _campaign_file(current_dir, current_reference["path"]),
            "运行时过渡当前场景",
        )
        changed_job_ids = _validate_runtime_target_scenario_change(
            predecessor_scenario,
            current_scenario,
        )
        if transition.get("changed_job_ids") != list(changed_job_ids):
            raise ConfigurationError("运行时场景过渡 Job 闭集漂移。")
        return frozenset(changed_job_ids)
    raise ConfigurationError("Campaign 前序链超过 64 层，拒绝继续。")


def _approved_scenario_with_formal_execution_contract(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    approved: Mapping[str, Any],
    formal: Mapping[str, Any],
) -> dict[str, Any]:
    """保留批准评估语义，并承接已获 transition 授权的 Formal 执行字段。"""

    _validate_scenario_manifest_shape(dict(approved))
    _validate_scenario_manifest_shape(dict(formal))
    approved_contract = _scenario_job_execution_contract(approved)
    formal_contract = _scenario_job_execution_contract(formal)
    if approved_contract == formal_contract:
        return json.loads(json.dumps(approved, ensure_ascii=False))

    changed_job_ids = _bound_runtime_scenario_transition_job_ids(
        campaign_dir,
        manifest,
    )
    if changed_job_ids != RUNTIME_CODEX_BINARY_JOB_IDS:
        raise ConfigurationError(
            "批准场景与 Formal Job 执行合同不一致，且无受控运行时过渡。"
        )
    approved_jobs = approved_contract["jobs"]
    formal_jobs = formal_contract["jobs"]
    approved_ids = [job.get("id") for job in approved_jobs]
    formal_ids = [job.get("id") for job in formal_jobs]
    if approved_ids != formal_ids or len(approved_ids) != len(set(approved_ids)):
        raise ConfigurationError("批准场景与 Formal Job 身份或顺序不一致。")

    for approved_job, formal_job in zip(approved_jobs, formal_jobs, strict=True):
        job_id = str(formal_job.get("id", ""))
        normalized_formal = json.loads(
            json.dumps(formal_job, ensure_ascii=False)
        )
        if job_id in changed_job_ids:
            approved_steps = approved_job.get("steps")
            formal_steps = normalized_formal.get("steps")
            if (
                not isinstance(approved_steps, list)
                or len(approved_steps) != 1
                or not isinstance(formal_steps, list)
                or len(formal_steps) != 1
                or not isinstance(approved_steps[0].get("environment"), dict)
                or not isinstance(formal_steps[0].get("environment"), dict)
                or "CODEX_BIN" in approved_steps[0]["environment"]
                or formal_steps[0]["environment"].pop("CODEX_BIN", None)
                != "{capture_codex_bin}"
            ):
                raise ConfigurationError(
                    f"{job_id} 未逐字承接受控 CODEX_BIN 运行时过渡。"
                )
        if normalized_formal != approved_job:
            raise ConfigurationError(
                f"{job_id} 存在未获 transition 批准的执行合同变化。"
            )

    effective = json.loads(json.dumps(approved, ensure_ascii=False))
    effective_jobs = effective.get("capture_jobs")
    formal_raw_jobs = formal.get("capture_jobs")
    if not isinstance(effective_jobs, list) or not isinstance(formal_raw_jobs, list):
        raise ConfigurationError("有效场景缺少 capture_jobs。")
    for effective_job, formal_job in zip(
        effective_jobs,
        formal_raw_jobs,
        strict=True,
    ):
        for field in SCENARIO_JOB_EXECUTION_FIELDS:
            if field in formal_job:
                effective_job[field] = json.loads(
                    json.dumps(formal_job[field], ensure_ascii=False)
                )
            else:
                effective_job.pop(field, None)
    if (
        _scenario_job_execution_contract(effective) != formal_contract
        or _scenario_non_execution_contract(effective)
        != _scenario_non_execution_contract(approved)
    ):
        raise ConfigurationError("批准语义与 Formal 执行合同合成失败。")
    return effective


def _successor_target_scenario_transition(
    arguments: argparse.Namespace,
    predecessor_dir: Path,
    staging_dir: Path,
    predecessor_manifest: Mapping[str, Any],
    copied_files: dict[str, dict[str, Any]],
) -> dict[str, Any] | None:
    """把 Candidate-only 二进制绑定变化复制为后继的不可变输入。"""

    source = getattr(arguments, "target_scenario_manifest", None)
    if source is None:
        return None
    if arguments.reason != "candidate_runtime_identity_correction":
        raise ConfigurationError(
            "--target-scenario-manifest 只允许运行时身份纠正后继使用。"
        )
    resolved = source.resolve(strict=False)
    if (
        not source.is_absolute()
        or resolved != source
        or not SAFE_ABSOLUTE_PATH_RE.fullmatch(str(source))
        or source.is_symlink()
        or not source.is_file()
    ):
        raise ConfigurationError(
            "--target-scenario-manifest 必须是可信的规范绝对文件。"
        )
    inputs = predecessor_manifest.get("inputs")
    predecessor_reference = (
        inputs.get("target_discovery_scenarios")
        if isinstance(inputs, Mapping)
        else None
    )
    _require_file_binding(
        predecessor_reference,
        "运行时纠正前序 target 场景",
    )
    assert isinstance(predecessor_reference, Mapping)
    predecessor_path = _campaign_file(
        predecessor_dir,
        str(predecessor_reference["path"]),
    )
    if (
        predecessor_path.is_symlink()
        or not predecessor_path.is_file()
        or file_sha256(predecessor_path) != predecessor_reference["sha256"]
    ):
        raise ConfigurationError("运行时纠正前序 target 场景摘要漂移。")
    predecessor_scenario = _read_json(
        predecessor_path,
        "运行时纠正前序 target 场景",
    )
    successor_scenario = _read_json(source, "运行时纠正当前 target 场景")
    if successor_scenario.get("codex_version") != predecessor_manifest.get(
        "target_version"
    ):
        raise ConfigurationError("运行时纠正目标场景版本不一致。")
    changed_job_ids = _validate_runtime_target_scenario_change(
        predecessor_scenario,
        successor_scenario,
    )
    target_relative = str(predecessor_reference["path"])
    destination = _campaign_file(staging_dir, target_relative)
    copied = _secure_copy_file_once(source, destination)
    successor_reference = {
        "path": target_relative,
        "sha256": copied["sha256"],
    }
    copied_files[target_relative] = {
        "kind": "runtime_target_scenario",
        "source_path": target_relative,
        "target_path": target_relative,
        "sha256": copied["sha256"],
        "bytes": copied["bytes"],
    }
    return {
        "reason": "candidate_codex_binary_binding_correction",
        "predecessor": dict(predecessor_reference),
        "successor": successor_reference,
        "changed_job_ids": list(changed_job_ids),
    }


def _successor_job_rehearsal_transition(
    arguments: argparse.Namespace,
    staging_dir: Path,
    successor_manifest: dict[str, Any],
    *,
    target_scenario_override: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    """校验后继当前执行合同，并按需替换前序完整 Job 演练绑定。"""

    rehearsal_root = getattr(arguments, "job_rehearsal_root", None)
    rehearsal_receipt = getattr(arguments, "job_rehearsal_receipt", None)
    if (rehearsal_root is None) != (rehearsal_receipt is None):
        raise ConfigurationError(
            "后继 --job-rehearsal-root 与 --job-rehearsal-receipt 必须同时提供。"
        )
    controls = successor_manifest.get("control_receipts")
    predecessor_control = (
        controls.get("job_rehearsal") if isinstance(controls, dict) else None
    )
    if not isinstance(predecessor_control, dict):
        raise ConfigurationError("前序 Formal Campaign 缺少完整 Job 演练绑定。")
    expected_contract = _job_rehearsal_contract_from_manifest(
        staging_dir,
        successor_manifest,
        target_scenario_override=target_scenario_override,
    )
    if rehearsal_root is None or rehearsal_receipt is None:
        try:
            replayed_control = _job_rehearsal_control_from_receipt(
                Path(str(predecessor_control.get("evidence_root", ""))),
                Path(
                    str(
                        predecessor_control.get("receipt", {}).get("path", "")
                        if isinstance(predecessor_control.get("receipt"), dict)
                        else ""
                    )
                ),
                expected_contract,
                allow_incremental_noop=(
                    _manifest_allows_incremental_noop_rehearsal(
                        successor_manifest
                    )
                ),
            )
        except ConfigurationError as error:
            raise ConfigurationError(
                "后继当前执行合同与前序完整 Job 演练不一致；先用当前工具"
                "创建 preflight_only Campaign 并完成离线演练，再向 successor "
                "同时提供 --job-rehearsal-root 与 --job-rehearsal-receipt。"
            ) from error
        if replayed_control != predecessor_control:
            raise ConfigurationError("前序完整 Job 演练绑定无法逐字重建。")
        return None

    assert isinstance(rehearsal_root, Path)
    assert isinstance(rehearsal_receipt, Path)
    successor_control = _job_rehearsal_control_from_receipt(
        rehearsal_root,
        rehearsal_receipt,
        expected_contract,
        allow_incremental_noop=(
            getattr(arguments, "recovery_timing_ledger_dir", None) is not None
            or _manifest_allows_incremental_noop_rehearsal(
                successor_manifest
            )
        ),
    )
    if successor_control == predecessor_control:
        raise ConfigurationError("后继完整 Job 演练绑定没有发生变化。")
    controls["job_rehearsal"] = successor_control
    return {
        "reason": "current_execution_contract_rehearsal",
        "predecessor": predecessor_control,
        "successor": successor_control,
    }


def _successor_stop_phase_allowed(
    arguments: argparse.Namespace,
    active_phase: object,
) -> bool:
    """只为绑定失败 attempt 的控制刷新开放历史 VC-0 停线。"""

    if active_phase in codex_upgrade_timing_ledger.PHASE_ORDER[1:]:
        return True
    return bool(
        active_phase == codex_upgrade_timing_ledger.PHASE_ORDER[0]
        and arguments.reason == "candidate_recovery_control_refresh"
        and arguments.predecessor_candidate_id
        and arguments.predecessor_attempt_id
    )


def _validate_historical_recovery_scope(
    recovery_scope: Any,
    attempt: Mapping[str, Any],
) -> dict[str, Any]:
    """按冻结事实校验历史失败闭集，不用当前评估器重新计算。"""

    required = {
        "schema_version",
        "source_attempt_id",
        "source_attempt_digest",
        "run_nonce",
        "planned_job_ids",
        "completed_job_ids",
        "failed_job_ids",
        "pending_job_ids",
        "execute_job_ids",
        "checkpoint",
        "environment_boundary_sha256",
    }
    if not isinstance(recovery_scope, Mapping) or set(recovery_scope) not in {
        frozenset(required),
        frozenset(required | {"source_mode"}),
    }:
        raise ConfigurationError("控制刷新源 transition 的冻结失败闭集结构非法。")
    if (
        recovery_scope.get("schema_version")
        != "codex-upgrade-failed-attempt-scope/v1"
        or attempt.get("status") != "failed"
        or recovery_scope.get("source_attempt_id") != attempt.get("attempt_id")
        or recovery_scope.get("source_attempt_digest")
        != attempt.get("attempt_digest")
        or recovery_scope.get("run_nonce") != attempt.get("run_nonce")
        or not SHA256_RE.fullmatch(
            str(recovery_scope.get("environment_boundary_sha256", ""))
        )
    ):
        raise ConfigurationError("控制刷新源 transition 的冻结失败闭集身份非法。")

    def scope_ids(name: str) -> list[str]:
        values = recovery_scope.get(name)
        if (
            not isinstance(values, list)
            or values != sorted(set(values))
            or not all(
                isinstance(value, str) and SAFE_ID_RE.fullmatch(value)
                for value in values
            )
        ):
            raise ConfigurationError(
                f"控制刷新源 transition 的冻结 {name} 非法。"
            )
        return [str(value) for value in values]

    planned = set(scope_ids("planned_job_ids"))
    completed = set(scope_ids("completed_job_ids"))
    failed = set(scope_ids("failed_job_ids"))
    pending = set(scope_ids("pending_job_ids"))
    execute = set(scope_ids("execute_job_ids"))
    if (
        not planned
        or not execute
        or completed & execute
        or completed & pending
        or failed & completed
        or failed & pending
        or failed | pending != execute
        or completed | execute != planned
    ):
        raise ConfigurationError("控制刷新源 transition 的冻结 Job 集合关系非法。")

    results = attempt.get("results")
    if not isinstance(results, list):
        raise ConfigurationError("控制刷新源 transition 的源 attempt 结果非法。")
    result_status: dict[str, str] = {}
    for result in results:
        if (
            not isinstance(result, Mapping)
            or not isinstance(result.get("id"), str)
            or result.get("id") not in planned
            or result.get("id") in result_status
            or result.get("status") not in {"complete", "failed"}
        ):
            raise ConfigurationError("控制刷新源 transition 的源 attempt 结果非法。")
        result_status[str(result["id"])] = str(result["status"])
    expected_completed = {
        job_id for job_id, status in result_status.items() if status == "complete"
    }
    expected_failed = {
        job_id for job_id, status in result_status.items() if status == "failed"
    }
    if (
        completed != expected_completed
        or failed != expected_failed
        or pending != planned - set(result_status)
    ):
        raise ConfigurationError("控制刷新源 transition 的冻结 Job 集合已经漂移。")

    checkpoint = recovery_scope.get("checkpoint")
    attempt_checkpoint = attempt.get("job_checkpoint")
    checkpoint_fields = ("path", "record_count", "last_sequence", "last_sha256")
    if (
        not isinstance(checkpoint, Mapping)
        or set(checkpoint) != set(checkpoint_fields)
        or not isinstance(attempt_checkpoint, Mapping)
        or dict(checkpoint)
        != {field: attempt_checkpoint.get(field) for field in checkpoint_fields}
    ):
        raise ConfigurationError("控制刷新源 transition 的冻结 checkpoint 漂移。")
    source_mode = recovery_scope.get("source_mode")
    if source_mode is not None and (
        source_mode != "pre_job_failure"
        or completed
        or failed
        or pending != planned
    ):
        raise ConfigurationError("控制刷新源 transition 的冻结 source_mode 非法。")
    return dict(recovery_scope)


def _candidate_control_refresh_source_transition(
    predecessor_dir: Path,
    predecessor_manifest: Mapping[str, Any],
    *,
    candidate_id: str,
    attempt_id: str,
    source: Path | Mapping[str, Any],
    _historical_manifest_controls: bool = False,
) -> tuple[dict[str, Any], dict[str, str], dict[str, Any]]:
    """重放控制刷新所绑定的历史已批准 transition。

    历史 transition 使用的是当时的工具摘要，不能用当前工具重新生成预览；
    这里改为重放其不可变自摘要、预览投影、源 attempt 和失败闭集，并从中
    取得真正过期的恢复控制链。Formal 原控制只作为上游锚点。
    """

    attempt_root, attempt = _load_capture_attempt(
        predecessor_dir,
        "candidate",
        candidate_id,
        attempt_id,
        _historical_manifest_controls=_historical_manifest_controls,
    )
    if isinstance(source, Mapping):
        _require_file_binding(source, "控制刷新源 transition")
        source_path = _campaign_file(predecessor_dir, str(source["path"]))
        if file_sha256(source_path) != source["sha256"]:
            raise ConfigurationError("控制刷新源 transition 摘要漂移。")
    else:
        if not source.is_absolute():
            raise ConfigurationError("控制刷新源 transition 必须使用绝对路径。")
        source_path = source.resolve(strict=True)
    if source_path.is_symlink() or not source_path.is_file():
        raise ConfigurationError("控制刷新源 transition 路径不可信。")
    try:
        relative = source_path.relative_to(predecessor_dir.resolve(strict=True))
    except (OSError, RuntimeError, ValueError) as error:
        raise ConfigurationError(
            "控制刷新源 transition 必须位于前序 Campaign 内。"
        ) from error
    match = _PHASE_EVALUATION_TRANSITION_FILE_RE.fullmatch(source_path.name)
    transition_index = int(match.group("index") or "1") if match else 0
    expected_path = _evaluation_transition_path(attempt_root, transition_index)
    if (
        transition_index < 1
        or transition_index > MAX_PHASE_EVALUATION_TRANSITIONS
        or source_path.resolve(strict=True) != expected_path.resolve(strict=True)
    ):
        raise ConfigurationError(
            "控制刷新源 transition 未绑定指定 Candidate／attempt 的合法槽位。"
        )

    transition = _read_json(source_path, "控制刷新源 transition")
    unsigned = dict(transition)
    transition_digest = unsigned.pop("transition_digest", None)
    expected_fields = {
        "schema_version",
        "approved_at_utc",
        "campaign_id",
        "campaign_manifest_sha256",
        "phase",
        "candidate_id",
        "attempt_id",
        "attempt_digest",
        "evidence_boundary_sha256",
        "from_tool_files_sha256",
        "to_tool_files_sha256",
        "from_production_sha256",
        "to_production_sha256",
        "from_evaluation_sha256",
        "to_evaluation_sha256",
        "changed_files",
        "allowed_operations",
        "recovery_controls",
        "recovery_scope",
        "preview",
        "review_sha256",
        "raw_evidence_scanned_bytes",
        "status",
        "transition_digest",
    }
    if transition_index == TERMINAL_PHASE_EVALUATION_TRANSITION:
        expected_fields.add("terminal_preflight")
    if (
        set(transition) != expected_fields
        or transition.get("schema_version") != TOOL_EVALUATION_TRANSITION_SCHEMA
        or transition.get("status") != "approved"
        or not _is_rfc3339_timestamp(transition.get("approved_at_utc"))
        or not SHA256_RE.fullmatch(str(transition_digest))
        or _fingerprint(unsigned) != transition_digest
        or transition.get("campaign_id") != predecessor_manifest.get("campaign_id")
        or transition.get("campaign_manifest_sha256")
        != file_sha256(predecessor_dir / "campaign.json")
        or transition.get("phase") != "candidate"
        or transition.get("candidate_id") != candidate_id
        or transition.get("attempt_id") != attempt_id
        or transition.get("attempt_digest") != attempt.get("attempt_digest")
        or transition.get("allowed_operations") != ["capture-run"]
        or transition.get("raw_evidence_scanned_bytes") != 0
    ):
        raise ConfigurationError("控制刷新源 transition 身份或自摘要非法。")

    preview_binding = transition.get("preview")
    _require_file_binding(preview_binding, "控制刷新源 transition 预览")
    assert isinstance(preview_binding, Mapping)
    preview_path = _campaign_file(
        predecessor_dir,
        str(preview_binding["path"]),
    )
    if (
        preview_path != _evaluation_transition_preview_path(
            attempt_root,
            transition_index,
        )
        or preview_path.is_symlink()
        or not preview_path.is_file()
        or file_sha256(preview_path) != preview_binding["sha256"]
    ):
        raise ConfigurationError("控制刷新源 transition 预览绑定漂移。")
    preview = _read_json(preview_path, "控制刷新源 transition 预览")
    preview_core = {
        key: value
        for key, value in preview.items()
        if key not in {"status", "review_sha256"}
    }
    transition_projection = {
        key: value
        for key, value in transition.items()
        if key
        not in {
            "schema_version",
            "approved_at_utc",
            "preview",
            "status",
            "transition_digest",
        }
    }
    preview_projection = {
        key: value
        for key, value in preview.items()
        if key
        not in {
            "schema_version",
            "campaign_mode",
            "campaign_purpose",
            "status",
        }
    }
    if (
        preview.get("schema_version")
        != TOOL_EVALUATION_TRANSITION_PREVIEW_SCHEMA
        or preview.get("status") != "approval_required"
        or preview.get("review_sha256") != _fingerprint(preview_core)
        or transition_projection != preview_projection
    ):
        raise ConfigurationError("控制刷新源 transition 与批准预览不一致。")

    recovery_scope = transition.get("recovery_scope")
    if _historical_manifest_controls:
        # 历史控制链已经由 transition 自摘要、批准预览、源 attempt 摘要和
        # 后续 control epoch 共同冻结。替代 transition 正是用来批准当前
        # 评估规则变化的，不能先用当前规则重算旧闭集而形成自锁。
        current_scope = _validate_historical_recovery_scope(
            recovery_scope,
            attempt,
        )
    else:
        current_scope = _legacy_vc0_phase_recovery_scope(
            predecessor_dir,
            predecessor_manifest,
            phase="candidate",
            candidate_id=candidate_id,
            attempt_root=attempt_root,
            attempt=attempt,
        )
        if current_scope is None or recovery_scope != current_scope:
            raise ConfigurationError("控制刷新源 transition 的失败闭集已经漂移。")

    recovery_controls = transition.get("recovery_controls")
    expected_recovery_fields = {
        "schema_version",
        "predecessor",
        "stop_checkpoint",
        "recovery",
        "current_tool_files_sha256",
        "legacy_vc0_recovery",
    }
    frozen_controls = predecessor_manifest.get("control_receipts")
    frozen_pair = (
        {
            "upgrade_timing": frozen_controls.get("upgrade_timing"),
            "arm64_environment": frozen_controls.get("arm64_environment"),
        }
        if isinstance(frozen_controls, Mapping)
        else None
    )
    source_recovery = (
        recovery_controls.get("recovery")
        if isinstance(recovery_controls, Mapping)
        else None
    )
    legacy = (
        recovery_controls.get("legacy_vc0_recovery")
        if isinstance(recovery_controls, Mapping)
        else None
    )
    if (
        not isinstance(recovery_controls, Mapping)
        or set(recovery_controls) != expected_recovery_fields
        or recovery_controls.get("schema_version")
        != TOOL_EVALUATION_RECOVERY_CONTROLS_SCHEMA
        or recovery_controls.get("predecessor") != frozen_pair
        or recovery_controls.get("current_tool_files_sha256")
        != transition.get("to_tool_files_sha256")
        or not isinstance(source_recovery, dict)
        or set(source_recovery)
        != {"upgrade_timing", "arm64_environment", "job_rehearsal"}
        or legacy
        != {
            "mode": "formal_candidate_attempt",
            "source_attempt_id": attempt_id,
            "source_attempt_digest": attempt.get("attempt_digest"),
            "execute_job_ids": current_scope["execute_job_ids"],
        }
    ):
        raise ConfigurationError("控制刷新源 transition 的恢复控制链非法。")

    binding = {
        "path": relative.as_posix(),
        "sha256": file_sha256(source_path),
    }
    return transition, binding, source_recovery


def _control_epoch_path(campaign_dir: Path, epoch_index: int = 1) -> Path:
    """返回原 Campaign 中指定 control epoch 的固定路径。"""

    if not 1 <= epoch_index <= CONTROL_EPOCH_MAX_COUNT:
        raise ConfigurationError("control epoch 索引超出有界范围。")
    return (
        campaign_dir
        / CONTROL_EPOCH_DIRECTORY
        / f"control-epoch-{epoch_index:02d}.json"
    )


def _control_epoch_runtime_repair_path(campaign_dir: Path) -> Path:
    """返回唯一 control epoch 运行授权修复收据路径。"""

    return (
        campaign_dir
        / CONTROL_EPOCH_DIRECTORY
        / CONTROL_EPOCH_RUNTIME_REPAIR_FILENAME
    )


def _control_epoch_runtime_repair_amendment_path(campaign_dir: Path) -> Path:
    """返回首份失败修复的唯一替代收据路径。"""

    return (
        campaign_dir
        / CONTROL_EPOCH_DIRECTORY
        / CONTROL_EPOCH_RUNTIME_REPAIR_AMENDMENT_FILENAME
    )


def _control_epoch_files(campaign_dir: Path) -> list[Path]:
    """严格列出最多两份连续 control epoch。"""

    root = campaign_dir / CONTROL_EPOCH_DIRECTORY
    if not root.exists():
        return []
    _reject_symlink_components(root, campaign_dir, "control epoch 目录")
    if root.is_symlink() or not root.is_dir():
        raise ConfigurationError("control epoch 目录不可信。")
    paths = sorted(root.iterdir())
    repair_names = {
        CONTROL_EPOCH_RUNTIME_REPAIR_FILENAME,
        CONTROL_EPOCH_RUNTIME_REPAIR_AMENDMENT_FILENAME,
    }
    if any(
        path.is_symlink()
        or not path.is_file()
        or (
            path.name not in repair_names
            and CONTROL_EPOCH_FILENAME_RE.fullmatch(path.name) is None
        )
        for path in paths
    ):
        raise ConfigurationError("control epoch 目录含非法文件。")
    epochs = [
        path
        for path in paths
        if CONTROL_EPOCH_FILENAME_RE.fullmatch(path.name) is not None
    ]
    repairs = [
        path
        for path in paths
        if path.name in repair_names
    ]
    expected_names = [f"control-epoch-{index:02d}.json" for index in range(1, len(epochs) + 1)]
    if (
        len(epochs) > CONTROL_EPOCH_MAX_COUNT
        or [path.name for path in epochs] != expected_names
        or len(repairs) > 2
        or (repairs and (not epochs or epochs[0].name != CONTROL_EPOCH_FILENAME))
        or (
            any(
                path.name == CONTROL_EPOCH_RUNTIME_REPAIR_AMENDMENT_FILENAME
                for path in repairs
            )
            and not any(
                path.name == CONTROL_EPOCH_RUNTIME_REPAIR_FILENAME
                for path in repairs
            )
        )
    ):
        raise ConfigurationError("同一 Campaign 只允许最多两份连续 control epoch。")
    return epochs


def _official_sealed_control_epoch_source_context(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    _enforce_prepublication_boundary: bool = True,
) -> dict[str, Any]:
    """冻结或历史重放 sealed-stage 控制恢复的 official 源边界。"""

    if manifest.get("campaign_mode") != "formal":
        raise ConfigurationError("official control epoch 只允许 Formal Campaign。")
    if _enforce_prepublication_boundary:
        classification_root = campaign_dir / "classification"
        classification_started = False
        if classification_root.exists() or classification_root.is_symlink():
            _reject_symlink_components(
                classification_root,
                campaign_dir,
                "official control epoch 分类边界",
            )
            if classification_root.is_symlink() or not classification_root.is_dir():
                raise ConfigurationError("official control epoch 分类目录不可信。")
            allowed_file = Path("discovery/baseline-to-target-official.json")
            allowed_file_present = False
            for path in classification_root.rglob("*"):
                if path.is_symlink():
                    raise ConfigurationError("official control epoch 分类边界含符号链接。")
                relative = path.relative_to(classification_root)
                if path.is_dir() and relative == allowed_file.parent:
                    continue
                if path.is_file() and relative == allowed_file:
                    allowed_file_present = True
                    continue
                classification_started = True
                break
            classification_started = classification_started or not allowed_file_present
        if classification_started:
            raise ConfigurationError(
                "official control epoch 发布前不得存在分类草案或结果。"
            )
        if (campaign_dir / "candidates").exists():
            raise ConfigurationError("official control epoch 发布前不得存在 Candidate。")
    previous_recovery = _successor_reason_ancestor(
        campaign_dir,
        manifest,
        "sealed_stage_control_recovery",
    )
    if previous_recovery is None:
        raise ConfigurationError(
            "祖先尚未使用 sealed_stage_control_recovery，应创建唯一 successor。"
        )
    official_path = campaign_dir / "official" / "result.json"
    official = _load_stage_result(
        campaign_dir,
        "capture-official",
        _ignore_checkpoint=True,
        _skip_evidence_scan=True,
        _historical_manifest_controls=True,
        _verified_campaign_manifest=manifest,
    )
    if official.get("status") != "complete":
        raise ConfigurationError("official control epoch 要求当前阶段已经完整封存。")
    recovery_context = _sealed_stage_recovery_context(
        campaign_dir,
        manifest,
        official,
        require_active=False,
    )
    previous_controls = recovery_context.get("effective_controls")
    if not isinstance(previous_controls, Mapping):
        raise ConfigurationError(
            "official control epoch 无法解析祖先 sealed-stage recovery 的有效控制。"
        )
    target_scenario = manifest.get("inputs", {}).get(
        "target_discovery_scenarios"
    )
    _require_file_binding(target_scenario, "official control epoch target 场景")
    assert isinstance(target_scenario, Mapping)
    return {
        "mode": "official_sealed",
        "official_stage": {
            "path": "official/result.json",
            "sha256": file_sha256(official_path),
            "package_digest": str(official.get("package_digest", "")),
        },
        "previous_sealed_stage_recovery": previous_recovery,
        "previous_controls": json.loads(
            json.dumps(previous_controls, ensure_ascii=False)
        ),
        "target_scenario": dict(target_scenario),
    }


def _is_official_sealed_control_epoch_source(source: Mapping[str, Any]) -> bool:
    """判断 control epoch 是否为 official_sealed 原地控制恢复。"""

    return source.get("mode") == "official_sealed"


def _control_epoch_required_phase(source: Mapping[str, Any]) -> str:
    """返回 control epoch 新旧 Ledger 必须位于的阶段。"""

    return "VC-2" if _is_official_sealed_control_epoch_source(source) else "VC-4"


def _control_epoch_previous_controls(
    manifest: Mapping[str, Any],
    source: Mapping[str, Any],
    previous_epoch: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """解析 epoch 应续接的控制，official 模式不得退回清单初始控制。"""

    controls = (
        source.get("previous_controls")
        if _is_official_sealed_control_epoch_source(source)
        else (
            previous_epoch.get("successor_controls")
            if isinstance(previous_epoch, Mapping)
            else manifest.get("control_receipts")
        )
    )
    if not isinstance(controls, Mapping):
        raise ConfigurationError("control epoch 缺少可续接的前序控制。")
    return json.loads(json.dumps(controls, ensure_ascii=False))


def _control_epoch_source_context(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    candidate_id: str | None = None,
    attempt_id: str | None = None,
    _enforce_prepublication_boundary: bool = True,
) -> dict[str, Any]:
    """只读重放控制刷新或控制替代后继所绑定的失败闭集。"""

    predecessor = manifest.get("predecessor")
    predecessor_reason = (
        predecessor.get("reason") if isinstance(predecessor, Mapping) else None
    )
    if (
        candidate_id is None
        and attempt_id is None
        and predecessor_reason
        not in {
            "candidate_recovery_control_refresh",
            "candidate_recovery_control_replacement",
        }
    ):
        return _official_sealed_control_epoch_source_context(
            campaign_dir,
            manifest,
            _enforce_prepublication_boundary=_enforce_prepublication_boundary,
        )
    if (
        manifest.get("campaign_mode") != "formal"
        or not isinstance(predecessor, Mapping)
        or predecessor_reason
        not in {
            "candidate_recovery_control_refresh",
            "candidate_recovery_control_replacement",
        }
    ):
        raise ConfigurationError(
            "control epoch 只允许用于唯一控制刷新后继，或零执行控制替代后继。"
        )
    import_path = campaign_dir / "predecessor-import.json"
    if import_path.is_symlink() or not import_path.is_file():
        raise ConfigurationError("control epoch 缺少可信 predecessor-import.json。")
    receipt = _read_json(import_path, "control epoch 前序导入收据")
    unsigned = dict(receipt)
    digest = unsigned.pop("receipt_digest", None)
    if predecessor_reason == "candidate_recovery_control_replacement":
        stored_replacement = receipt.get("control_replacement")
        recovery_transition = receipt.get("recovery_control_transition")
        job_transition = receipt.get("job_rehearsal_transition")
        if (
            receipt.get("schema_version")
            != PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA
            or receipt.get("reason")
            != "candidate_recovery_control_replacement"
            or receipt.get("successor_campaign_id") != manifest.get("campaign_id")
            or receipt.get("successor_campaign_manifest_sha256")
            != file_sha256(campaign_dir / "campaign.json")
            or not SHA256_RE.fullmatch(str(digest))
            or _fingerprint(unsigned) != digest
            or not isinstance(stored_replacement, Mapping)
            or not isinstance(recovery_transition, Mapping)
            or not isinstance(job_transition, Mapping)
        ):
            raise ConfigurationError("控制替代 epoch 导入收据身份或摘要非法。")
        epoch = stored_replacement.get("effective_epoch")
        repair = stored_replacement.get("runtime_repair")
        unpublished = stored_replacement.get("unpublished_stop_checkpoint")
        audit = stored_replacement.get("supervisor_audit")
        source_attempt = stored_replacement.get("source_attempt")
        unpublished_receipt = (
            unpublished.get("receipt") if isinstance(unpublished, Mapping) else None
        )
        if (
            not isinstance(epoch, Mapping)
            or not isinstance(unpublished, Mapping)
            or not isinstance(unpublished_receipt, Mapping)
            or not isinstance(audit, Mapping)
            or not isinstance(source_attempt, Mapping)
            or (repair is not None and not isinstance(repair, Mapping))
        ):
            raise ConfigurationError("控制替代 epoch 审计绑定不闭合。")
        predecessor_dir = Path(str(predecessor.get("campaign_dir", "")))
        if (
            not predecessor_dir.is_absolute()
            or predecessor_dir.is_symlink()
            or not predecessor_dir.is_dir()
        ):
            raise ConfigurationError("控制替代 epoch 前序 Campaign 路径不可信。")
        predecessor_dir = predecessor_dir.resolve(strict=True)
        predecessor_manifest = _require_formal_campaign(
            predecessor_dir,
            load_campaign_manifest(
                predecessor_dir,
                _control_epoch_bootstrap=True,
            ),
        )
        if (
            predecessor_manifest.get("campaign_id")
            != predecessor.get("campaign_id")
            or file_sha256(predecessor_dir / "campaign.json")
            != predecessor.get("campaign_manifest_sha256")
        ):
            raise ConfigurationError("控制替代 epoch 前序 Campaign 身份漂移。")
        replay_arguments = argparse.Namespace(
            reason="candidate_recovery_control_replacement",
            predecessor_candidate_id=source_attempt.get("candidate_id"),
            predecessor_attempt_id=source_attempt.get("attempt_id"),
            predecessor_control_epoch=predecessor_dir / str(epoch.get("path", "")),
            predecessor_control_runtime_repair=(
                predecessor_dir / str(repair.get("path", ""))
                if isinstance(repair, Mapping)
                else None
            ),
            predecessor_unpublished_ledger_dir=Path(
                str(unpublished.get("ledger_dir", ""))
            ),
            predecessor_unpublished_stop_receipt=(
                Path(str(unpublished.get("ledger_dir", "")))
                / str(unpublished_receipt.get("path", ""))
            ),
            predecessor_supervisor_run_dir=Path(str(audit.get("run_dir", ""))),
        )
        replayed = _control_replacement_context(
            replay_arguments,
            predecessor_dir,
            predecessor_manifest,
        )
        source = replayed.get("source")
        controls = manifest.get("control_receipts")
        predecessor_controls = replayed.get("effective_controls")
        if (
            not _control_replacement_context_matches(stored_replacement, replayed)
            or not isinstance(source, Mapping)
            or not isinstance(controls, Mapping)
            or not isinstance(predecessor_controls, Mapping)
            or recovery_transition.get("predecessor")
            != {
                "upgrade_timing": predecessor_controls.get("upgrade_timing"),
                "arm64_environment": predecessor_controls.get("arm64_environment"),
            }
            or recovery_transition.get("successor")
            != {
                "upgrade_timing": controls.get("upgrade_timing"),
                "arm64_environment": controls.get("arm64_environment"),
            }
            or job_transition.get("predecessor")
            != predecessor_controls.get("job_rehearsal")
            or job_transition.get("successor") != controls.get("job_rehearsal")
        ):
            raise ConfigurationError("控制替代 epoch 控制链或失败闭集漂移。")
        source_candidate_id = str(source.get("candidate_id", ""))
        source_attempt_id = str(source.get("attempt_id", ""))
        scenario = manifest.get("inputs", {}).get("target_discovery_scenarios")
        _require_file_binding(scenario, "控制替代 epoch target 场景")
        if (
            not SAFE_ID_RE.fullmatch(source_candidate_id)
            or not SAFE_ID_RE.fullmatch(source_attempt_id)
            or source_attempt.get("candidate_id") != source_candidate_id
            or source_attempt.get("attempt_id") != source_attempt_id
            or (candidate_id is not None and candidate_id != source_candidate_id)
            or (attempt_id is not None and attempt_id != source_attempt_id)
            or source.get("target_scenario") != scenario
        ):
            raise ConfigurationError("控制替代 epoch 源 Candidate／attempt／场景漂移。")
        return json.loads(json.dumps(source, ensure_ascii=False))

    abandoned = receipt.get("abandoned_candidate_attempt")
    control_transition = receipt.get("recovery_control_transition")
    source_transition = (
        control_transition.get("source_transition")
        if isinstance(control_transition, Mapping)
        else None
    )
    if (
        receipt.get("schema_version") != PREDECESSOR_RECOVERY_IMPORT_SCHEMA
        or receipt.get("reason") != "candidate_recovery_control_refresh"
        or receipt.get("successor_campaign_id") != manifest.get("campaign_id")
        or receipt.get("successor_campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or not SHA256_RE.fullmatch(str(digest))
        or _fingerprint(unsigned) != digest
        or not isinstance(abandoned, Mapping)
        or not isinstance(control_transition, Mapping)
        or not isinstance(source_transition, Mapping)
    ):
        raise ConfigurationError("control epoch 前序导入收据身份或摘要非法。")
    source_candidate_id = str(abandoned.get("candidate_id", ""))
    source_attempt_id = str(abandoned.get("attempt_id", ""))
    if (
        not SAFE_ID_RE.fullmatch(source_candidate_id)
        or not SAFE_ID_RE.fullmatch(source_attempt_id)
        or (candidate_id is not None and candidate_id != source_candidate_id)
        or (attempt_id is not None and attempt_id != source_attempt_id)
    ):
        raise ConfigurationError("control epoch 源 Candidate／attempt 身份不一致。")
    predecessor_dir = Path(str(predecessor.get("campaign_dir", "")))
    if (
        not predecessor_dir.is_absolute()
        or predecessor_dir.is_symlink()
        or not predecessor_dir.is_dir()
    ):
        raise ConfigurationError("control epoch 前序 Campaign 路径不可信。")
    predecessor_dir = predecessor_dir.resolve(strict=True)
    # control epoch 的源链属于历史控制重放；该上下文必须继续传给祖先，
    # 否则祖先冻结的批准场景会被错误拿去对比当前文档摘要。
    predecessor_manifest = load_campaign_manifest(
        predecessor_dir,
        _control_epoch_bootstrap=True,
    )
    if (
        predecessor_manifest.get("campaign_id") != predecessor.get("campaign_id")
        or file_sha256(predecessor_dir / "campaign.json")
        != predecessor.get("campaign_manifest_sha256")
    ):
        raise ConfigurationError("control epoch 前序 Campaign 身份漂移。")
    transition, expected_binding, _source_controls = (
        _candidate_control_refresh_source_transition(
            predecessor_dir,
            predecessor_manifest,
            candidate_id=source_candidate_id,
            attempt_id=source_attempt_id,
            source=source_transition,
            _historical_manifest_controls=True,
        )
    )
    if source_transition != expected_binding:
        raise ConfigurationError("control epoch 源 transition 绑定漂移。")
    attempt_root, attempt = _load_capture_attempt(
        predecessor_dir,
        "candidate",
        source_candidate_id,
        source_attempt_id,
        _historical_manifest_controls=True,
    )
    attempt_path = attempt_root / "attempt.json"
    expected_abandoned = {
        "candidate_id": source_candidate_id,
        "attempt_id": source_attempt_id,
        "path": attempt_path.relative_to(predecessor_dir).as_posix(),
        "sha256": file_sha256(attempt_path),
        "attempt_digest": attempt["attempt_digest"],
        "identity_sha256": _fingerprint(attempt["identity"]),
        "status": attempt["status"],
    }
    scope = transition.get("recovery_scope")
    if dict(abandoned) != expected_abandoned or not isinstance(scope, Mapping):
        raise ConfigurationError("control epoch 源 attempt 或恢复闭集漂移。")
    planned = scope.get("planned_job_ids")
    executed = scope.get("execute_job_ids")
    reused = scope.get("completed_job_ids")
    failed = scope.get("failed_job_ids")
    pending = scope.get("pending_job_ids")
    arrays = (planned, executed, reused, failed, pending)
    if any(
        not isinstance(values, list)
        or values != sorted(set(values))
        or not all(isinstance(value, str) and SAFE_ID_RE.fullmatch(value) for value in values)
        for values in arrays
    ):
        raise ConfigurationError("control epoch 源恢复闭集列表非法。")
    planned_set = set(planned)
    execute_set = set(executed)
    reused_set = set(reused)
    if (
        not execute_set
        or execute_set & reused_set
        or execute_set | reused_set != planned_set
        or set(failed) | set(pending) != execute_set
    ):
        raise ConfigurationError("control epoch 源失败／复用闭集不闭合。")
    production_paths = [
        str(row.get("path"))
        for row in transition.get("changed_files", [])
        if isinstance(row, Mapping)
        and row.get("classification") == "failed_job_production"
    ]
    mapped_jobs = {
        job_id
        for path in production_paths
        for job_id in RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS.get(path, ())
    }
    if (
        not production_paths
        or any(path not in RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS for path in production_paths)
        or not mapped_jobs
        or not mapped_jobs.issubset(execute_set)
    ):
        raise ConfigurationError("control epoch 工具产出侧映射越过失败闭集。")
    controls = manifest.get("control_receipts")
    import_job_transition = receipt.get("job_rehearsal_transition")
    if (
        not isinstance(controls, Mapping)
        or set(controls) != {"upgrade_timing", "arm64_environment", "job_rehearsal"}
        or control_transition.get("successor")
        != {
            "upgrade_timing": controls.get("upgrade_timing"),
            "arm64_environment": controls.get("arm64_environment"),
        }
        or not isinstance(import_job_transition, Mapping)
        or import_job_transition.get("successor") != controls.get("job_rehearsal")
    ):
        raise ConfigurationError("control epoch 当前 Campaign 控制链与导入收据不一致。")
    scenario = manifest.get("inputs", {}).get("target_discovery_scenarios")
    _require_file_binding(scenario, "control epoch target 场景")
    assert isinstance(scenario, Mapping)
    return {
        "candidate_id": source_candidate_id,
        "attempt_id": source_attempt_id,
        "attempt_digest": str(attempt["attempt_digest"]),
        "candidate_identity_sha256": str(abandoned["identity_sha256"]),
        "source_transition": dict(expected_binding),
        "recovery_scope_sha256": _fingerprint(dict(scope)),
        "planned_job_ids": list(planned),
        "execute_job_ids": list(executed),
        "reused_job_ids": list(reused),
        "failed_job_ids": list(failed),
        "pending_job_ids": list(pending),
        "production_paths": sorted(production_paths),
        "target_scenario": dict(scenario),
    }


def _control_epoch_empty_boundary(campaign_dir: Path) -> dict[str, int]:
    """在发布 epoch 前证明当前 Campaign 尚未产生任何执行事实。"""

    reservation_count = 0
    attempt_count = 0
    checkpoint_count = 0
    candidates = campaign_dir / "candidates"
    if candidates.exists():
        _reject_symlink_components(candidates, campaign_dir, "control epoch Candidate")
        if candidates.is_symlink() or not candidates.is_dir():
            raise ConfigurationError("control epoch Candidate 目录不可信。")
        for path in candidates.rglob("*"):
            if path.is_symlink():
                raise ConfigurationError("control epoch Candidate 树含符号链接。")
            if not path.is_file():
                continue
            if path.name == "reservation.json":
                reservation_count += 1
            elif path.name == "attempt.json":
                attempt_count += 1
            elif "checkpoints" in path.parts:
                checkpoint_count += 1
    boundary = {
        "reservation_count": reservation_count,
        "attempt_count": attempt_count,
        "checkpoint_count": checkpoint_count,
        "live_request_count": 0,
        "scanned_bytes": 0,
    }
    if any(boundary.values()):
        raise ConfigurationError(
            "control epoch 发布前 reservation／attempt／checkpoint／live／扫描必须全为 0。"
        )
    return boundary


def _control_epoch_stop_checkpoint(
    manifest: Mapping[str, Any],
    ledger_root: Path,
    receipt_path: Path,
    *,
    expected_timing: Mapping[str, Any] | None = None,
    required_phase: str | None = None,
    _historical_ledger_heads: bool = False,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """重放旧 Ledger 停线 checkpoint，并生成不可变停线绑定。"""

    controls = manifest.get("control_receipts")
    timing = expected_timing
    if timing is None:
        timing = (
            controls.get("upgrade_timing")
            if isinstance(controls, Mapping)
            else None
        )
    if not isinstance(timing, Mapping):
        raise ConfigurationError("control epoch 原 Campaign 缺少旧 Ledger 控制。")
    frozen_timing = (
        manifest.get("control_receipts", {}).get("upgrade_timing")
        if isinstance(manifest.get("control_receipts"), Mapping)
        else None
    )
    predecessor = manifest.get("predecessor")
    expected_stop_phase = required_phase or (
        "VC-0"
        if isinstance(predecessor, Mapping)
        and predecessor.get("reason")
        == "candidate_recovery_control_replacement"
        and timing == frozen_timing
        else "VC-4"
    )
    relative = _control_receipt_relative(
        ledger_root,
        receipt_path,
        "control epoch 旧 Ledger stop_the_line checkpoint",
    )
    try:
        checkpoint = codex_upgrade_timing_ledger.replay(ledger_root, relative)
        current = (
            None
            if _historical_ledger_heads
            else codex_upgrade_timing_ledger.inspect_ledger(ledger_root)
        )
    except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
        raise ConfigurationError(f"control epoch 旧 Ledger 无法重放：{error}") from error
    summary = checkpoint.get("summary")
    current_head_valid = _historical_ledger_heads or (
        isinstance(summary, Mapping)
        and isinstance(current, Mapping)
        and current.get("status") == "stopped"
        and current.get("head_sequence") == summary.get("head_sequence")
        and current.get("head_sha256") == summary.get("head_sha256")
        and current.get("total_live_request_count")
        == summary.get("total_live_request_count")
    )
    if (
        not isinstance(summary, Mapping)
        or summary.get("status") != "stopped"
        or summary.get("active_phase") != expected_stop_phase
        or summary.get("upgrade_id") != timing.get("upgrade_id")
        or summary.get("evidence_decision") != timing.get("evidence_decision")
        or str(ledger_root.resolve(strict=True)) != str(timing.get("ledger_dir"))
        or not current_head_valid
    ):
        raise ConfigurationError(
            f"control epoch 旧 Ledger 不是当前 {expected_stop_phase} 停线终态 head。"
        )
    stop_file = ledger_root.resolve(strict=True) / relative
    binding = {
        "ledger_dir": str(ledger_root.resolve(strict=True)),
        "receipt": {
            "path": relative,
            "sha256": file_sha256(stop_file),
            "bytes": stop_file.stat().st_size,
        },
        "upgrade_id": str(summary["upgrade_id"]),
        "active_phase": str(summary["active_phase"]),
        "head_sequence": int(summary["head_sequence"]),
        "head_sha256": str(summary["head_sha256"]),
        "total_elapsed_seconds": int(summary["total_elapsed_seconds"]),
        "total_live_request_count": int(summary["total_live_request_count"]),
        "total_deadline_at_utc": str(summary["total_deadline_at_utc"]),
    }
    return binding, dict(summary)


def _build_control_epoch_successor_controls(
    arguments: argparse.Namespace,
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    *,
    required_phase: str = "VC-4",
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    """绑定新 Ledger／P0／incremental-noop，并要求当前 head 已到指定阶段。"""

    control_arguments = argparse.Namespace(
        campaign_mode="preflight_only",
        campaign_purpose=manifest["campaign_purpose"],
        baseline_version=manifest["baseline_version"],
        target_version=manifest["target_version"],
        timing_ledger_dir=arguments.recovery_timing_ledger_dir,
        timing_receipt=arguments.recovery_timing_receipt,
        arm64_environment_root=arguments.recovery_arm64_environment_root,
        arm64_environment_receipt=arguments.recovery_arm64_environment_receipt,
    )
    controls = _plan_control_receipts(control_arguments)
    proxy_manifest = json.loads(json.dumps(manifest, ensure_ascii=False))
    proxy_manifest["tool_identity"] = dict(current_tool)
    proxy_manifest["control_receipts"] = controls
    preflight_dir, preflight_manifest = _assert_recovery_rehearsal_uses_successor_controls(
        arguments,
        proxy_manifest,
    )
    target_scenario_override = _recovery_rehearsal_target_scenario_override(
        campaign_dir,
        manifest,
        preflight_dir,
        preflight_manifest,
    )
    expected_contract = _job_rehearsal_contract_from_manifest(
        campaign_dir,
        manifest,
        target_scenario_override=target_scenario_override,
        tool_files_sha256_override=str(current_tool.get("files_sha256", "")),
    )
    controls["job_rehearsal"] = _job_rehearsal_control_from_receipt(
        arguments.job_rehearsal_root,
        arguments.job_rehearsal_receipt,
        expected_contract,
        allow_incremental_noop=True,
    )
    rehearsal_relative = _control_receipt_relative(
        arguments.job_rehearsal_root,
        arguments.job_rehearsal_receipt,
        "control epoch incremental-noop 演练收据",
    )
    try:
        rehearsal = codex_upgrade_job_rehearsal_receipt.replay(
            arguments.job_rehearsal_root,
            rehearsal_relative,
        )
    except (OSError, codex_upgrade_job_rehearsal_receipt.JobRehearsalReceiptError) as error:
        raise ConfigurationError(f"control epoch 演练收据无法重放：{error}") from error
    noop = rehearsal.get("incremental_noop")
    if (
        rehearsal.get("status") != "incremental-noop"
        or not isinstance(noop, Mapping)
        or noop.get("new_pass_fact") is not False
        or noop.get("execute_job_ids") != []
        or noop.get("failed_job_ids") != []
        or noop.get("affected_job_ids") != []
        or noop.get("scanned_bytes") != 0
        or noop.get("live_request_count") != 0
    ):
        raise ConfigurationError("control epoch 必须绑定当前合同的零执行 incremental-noop。")
    timing = controls["upgrade_timing"]
    timing_root, checkpoint = _sealed_stage_timing_checkpoint(
        timing,
        label="control epoch 新 Ledger",
    )
    summary = checkpoint["summary"]
    try:
        current = codex_upgrade_timing_ledger.assert_usable(
            timing_root,
            str(timing["receipt"]["path"]),
            baseline_version=str(manifest["baseline_version"]),
            target_version=str(manifest["target_version"]),
            campaign_purpose=str(manifest["campaign_purpose"]),
            required_phase=required_phase,
        )
    except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
        raise ConfigurationError(f"control epoch 新 Ledger 未通过：{error}") from error
    if (
        summary.get("status") != "active"
        or summary.get("active_phase") != required_phase
        or summary.get("total_live_request_count") != 0
        or current.get("head_sequence") != summary.get("head_sequence")
        or current.get("head_sha256") != summary.get("head_sha256")
        or current.get("total_live_request_count") != 0
    ):
        raise ConfigurationError(
            f"control epoch 新 Ledger 必须是当前 {required_phase} active head 且 live=0。"
        )
    return controls, dict(summary), rehearsal


def _control_epoch_invariants(
    manifest: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    *,
    allowed_production_paths: Iterable[str] = (),
    required_active_phase: str = "VC-4",
) -> dict[str, Any]:
    """冻结不会因控制续期而改变的 Candidate、场景、compose 和工具产出身份。"""

    expected_tool = manifest.get("tool_identity")
    if not isinstance(expected_tool, Mapping):
        raise ConfigurationError("control epoch Campaign 缺少工具身份。")
    allowed = {str(path) for path in allowed_production_paths}
    excluded = set(_PHASE_EVALUATION_HYBRID_FILES) | allowed
    if _tool_identity_side_digest_excluding(
        expected_tool,
        "production",
        excluded,
    ) != _tool_identity_side_digest_excluding(current_tool, "production", excluded):
        raise ConfigurationError("control epoch 检测到失败闭集之外的工具产出侧漂移。")
    configuration = manifest.get("configuration")
    if not isinstance(configuration, Mapping):
        raise ConfigurationError("control epoch Campaign 配置非法。")
    return {
        "tool_files_sha256": str(current_tool.get("files_sha256", "")),
        "tool_production_sha256": _control_epoch_production_invariant_digest(
            expected_tool,
            current_tool,
            _PHASE_EVALUATION_HYBRID_FILES,
        ),
        "compose_sha256": _fingerprint(
            {
                "live_attestation_compose_dir": configuration.get(
                    "live_attestation_compose_dir"
                ),
                "live_attestation_compose_files": configuration.get(
                    "live_attestation_compose_files"
                ),
            }
        ),
        "required_active_phase": required_active_phase,
    }


def _control_epoch_production_invariant_digest(
    expected_tool: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    excluded_paths: Iterable[str],
) -> str:
    """计算 control epoch 的稳定产出摘要并兼容旧白名单。

    旧 epoch 曾把 canonical gate／activation 文件计入 production。它们如今
    已明确归入评估侧，但不能因此改写历史收据中的摘要。这里按旧白名单从
    expected 身份重算：兼容路径保留，新增且不在旧 plan 中的同类文件自然不
    进入摘要；真正的产出侧漂移仍由调用方的逐文件闭集门禁 fail-close。
    """

    def entries(identity: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
        raw = identity.get("entries")
        if not isinstance(raw, list):
            components = identity.get("components")
            if not isinstance(components, Mapping):
                raise ConfigurationError("工具身份缺少文件清单。")
            raw = [
                entry
                for value in components.values()
                if isinstance(value, Mapping)
                for entry in value.get("entries", [])
                if isinstance(entry, Mapping)
            ]
        return {
            str(entry["path"]): dict(entry)
            for entry in raw
            if isinstance(entry, Mapping) and isinstance(entry.get("path"), str)
        }

    expected_entries = entries(expected_tool)
    # current_tool 作为参数保留是为了让调用点显式传入当前身份；旧 epoch
    # 的稳定产出摘要必须锚定 plan 时的 expected 字节，不能随评估修复变化。
    _ = current_tool
    excluded = {str(path) for path in excluded_paths}
    legacy_evaluation = (
        set(_EVALUATION_SIDE_FILES) | set(_WATCHDOG_ONLY_TOOL_FILES)
    ) - set(_CANONICAL_EVALUATION_ONLY_FILES)
    stable: list[dict[str, Any]] = []
    for path in sorted(expected_entries):
        if path in excluded or path in legacy_evaluation:
            continue
        stable.append(expected_entries[path])
    return _fingerprint({"entries": stable})


def _control_epoch_failed_scope_production_paths(
    manifest: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    source: Mapping[str, Any],
) -> set[str]:
    """只放行最终 epoch 冻结失败闭集内、已登记到具体 Job 的产出变化。"""

    expected_tool = manifest.get("tool_identity")
    if not isinstance(expected_tool, Mapping):
        raise ConfigurationError("control epoch Campaign 缺少工具身份。")
    production_paths = set(
        _tool_identity_drift(expected_tool, current_tool).get("production", [])
    ) - set(_PHASE_EVALUATION_HYBRID_FILES)
    if not production_paths:
        return set()
    if _is_official_sealed_control_epoch_source(source):
        raise ConfigurationError(
            "official control epoch 检测到产出侧工具变化，必须永久停线。"
        )
    scope = _control_epoch_final_execution_scope(source)
    unknown_paths = production_paths - set(
        RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS
    )
    if unknown_paths:
        raise ConfigurationError(
            "control epoch 包含未登记的失败闭集产出变化："
            + "、".join(sorted(unknown_paths))
        )
    execute_ids = set(scope["execute_job_ids"])
    reused_ids = set(scope["reused_job_ids"])
    affected_ids = {
        job_id
        for path in production_paths
        for job_id in RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS[path]
    }
    if (
        not affected_ids
        or not affected_ids.issubset(execute_ids)
        or affected_ids.intersection(reused_ids)
    ):
        raise ConfigurationError(
            "control epoch 检测到失败闭集之外的工具产出侧漂移。"
        )
    return production_paths


def _control_epoch_final_execution_scope(
    source: Mapping[str, Any],
) -> dict[str, Any]:
    """冻结 replacement 最终执行 epoch 唯一允许的 2 执行／7 复用闭集。"""

    planned = source.get("planned_job_ids")
    executed = source.get("execute_job_ids")
    reused = source.get("reused_job_ids")
    expected_executed = list(CONTROL_EPOCH_FINAL_EXECUTION_JOB_IDS)
    if (
        not isinstance(planned, list)
        or not isinstance(executed, list)
        or not isinstance(reused, list)
        or planned != sorted(set(planned))
        or executed != expected_executed
        or reused != sorted(set(reused))
        or len(planned) != 9
        or len(reused) != 7
        or set(executed) & set(reused)
        or set(executed) | set(reused) != set(planned)
    ):
        raise ConfigurationError(
            "replacement 最终 execution epoch 必须精确保持 2 执行／7 复用闭集。"
        )
    return {
        "planned_job_ids": list(planned),
        "execute_job_ids": list(executed),
        "reused_job_ids": list(reused),
        "execute_count": 2,
        "reused_count": 7,
    }


def _control_epoch_final_execution_authorization(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    source: Mapping[str, Any],
    previous_epoch: Mapping[str, Any],
    supervisor_run_dir: Path,
) -> dict[str, Any]:
    """复算最终 execution epoch 对 repair-02、监督器和冻结闭集的绑定。"""

    predecessor = manifest.get("predecessor")
    if (
        not isinstance(predecessor, Mapping)
        or predecessor.get("reason")
        != "candidate_recovery_control_replacement"
    ):
        raise ConfigurationError("最终 execution epoch 只允许用于 replacement Campaign。")
    repair_path = _control_epoch_runtime_repair_amendment_path(campaign_dir)
    repair_payload = _read_json(repair_path, "最终 execution epoch repair-02")
    repair_binding = {
        **_control_replacement_file_binding(
            campaign_dir,
            repair_path,
            label="最终 execution epoch repair-02",
        ),
        "receipt_sha256": repair_payload.get("receipt_sha256"),
    }
    if (
        repair_payload.get("schema_version")
        != CONTROL_EPOCH_RUNTIME_REPAIR_SCHEMA
        or repair_payload.get("repair_index") != 2
        or not SHA256_RE.fullmatch(str(repair_binding["receipt_sha256"]))
        or previous_epoch.get("runtime_repair") != repair_binding
    ):
        raise ConfigurationError(
            "最终 execution epoch 必须绑定当前有效的 repair-02。"
        )
    supervisor_audit = _control_replacement_supervisor_audit(supervisor_run_dir)
    if supervisor_audit.get("summary", {}).get("state") != "stopped":
        raise ConfigurationError(
            "最终 execution epoch 要求父监督器正常结束且 audit_incomplete=false。"
        )
    return {
        "schema_version": CONTROL_EPOCH_FINAL_EXECUTION_SCHEMA,
        "mode": CONTROL_EPOCH_FINAL_EXECUTION_MODE,
        "previous_runtime_repair": repair_binding,
        "supervisor_audit": supervisor_audit,
        "scope": _control_epoch_final_execution_scope(source),
        "maximum_execution_budget_seconds": (
            CONTROL_EPOCH_FINAL_EXECUTION_MAX_SECONDS
        ),
    }


def _load_control_epoch_receipt(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    _allow_unrepaired_tool_drift: bool = False,
    _historical_ledger_heads: bool = False,
) -> dict[str, Any] | None:
    """加载并严格重放有界追加式 control epoch 链。"""

    paths = _control_epoch_files(campaign_dir)
    if not paths:
        return None
    repair_path = _control_epoch_runtime_repair_path(campaign_dir)
    has_runtime_repair = repair_path.is_file() and not repair_path.is_symlink()
    repair_amendment_path = _control_epoch_runtime_repair_amendment_path(
        campaign_dir
    )
    has_runtime_repair_amendment = (
        repair_amendment_path.is_file()
        and not repair_amendment_path.is_symlink()
    )
    if has_runtime_repair_amendment and not has_runtime_repair:
        raise ConfigurationError("control epoch 修复替代缺少首份运行授权修复。")
    predecessor = manifest.get("predecessor")
    control_replacement_epoch = (
        isinstance(predecessor, Mapping)
        and predecessor.get("reason")
        == "candidate_recovery_control_replacement"
    )
    if control_replacement_epoch and len(paths) > 1 and (
        len(paths) != 2 or not has_runtime_repair_amendment
    ):
        raise ConfigurationError(
            "控制替代后继的第二个 epoch 必须是 repair-02 后的最终执行授权。"
        )
    base_required = {
        "schema_version",
        "status",
        "epoch_index",
        "created_at_utc",
        "campaign_id",
        "campaign_manifest_sha256",
        "previous_epoch_sha256",
        "previous_controls",
        "stop_checkpoint",
        "successor_controls",
        "source",
        "invariants",
        "boundary",
        "budget",
        "receipt_sha256",
    }
    # 已发布 epoch 的历史重放必须允许其后产生的分类和 Candidate；
    # 发布前为空门禁只属于 create_control_epoch 入口。
    source = _control_epoch_source_context(
        campaign_dir,
        manifest,
        _enforce_prepublication_boundary=False,
    )
    official_sealed_epoch = _is_official_sealed_control_epoch_source(source)
    if official_sealed_epoch and (
        len(paths) != 1 or has_runtime_repair_amendment
    ):
        raise ConfigurationError(
            "official_sealed Campaign 只允许一份 control epoch 和至多一份分类控制修复。"
        )
    required_phase = _control_epoch_required_phase(source)
    current_tool = _tool_identity(include_git=False)
    allowed_production_paths = _control_epoch_failed_scope_production_paths(
        manifest,
        current_tool,
        source,
    )
    invariants = _control_epoch_invariants(
        manifest,
        current_tool,
        allowed_production_paths=allowed_production_paths,
        required_active_phase=required_phase,
    )
    previous_controls = _control_epoch_previous_controls(
        manifest,
        source,
        None,
    )
    if not isinstance(previous_controls, Mapping):
        raise ConfigurationError("control epoch 缺少初始控制绑定。")
    previous_epoch_sha256: str | None = None
    previous_cumulative_elapsed = 0
    previous_successor_elapsed = 0
    effective: dict[str, Any] | None = None
    frozen_production_sha256: str | None = None

    for epoch_index, path in enumerate(paths, start=1):
        payload = _read_json(path, f"control epoch {epoch_index} 收据")
        final_execution_epoch = control_replacement_epoch and epoch_index == 2
        required = set(base_required)
        if final_execution_epoch:
            required.add("execution_authorization")
        unsigned = dict(payload)
        digest = unsigned.pop("receipt_sha256", None)
        if (
            set(payload) != required
            or payload.get("schema_version") != CONTROL_EPOCH_SCHEMA
            or payload.get("status") != "active"
            or payload.get("epoch_index") != epoch_index
            or payload.get("previous_epoch_sha256") != previous_epoch_sha256
            or not _is_rfc3339_timestamp(payload.get("created_at_utc"))
            or payload.get("campaign_id") != manifest.get("campaign_id")
            or payload.get("campaign_manifest_sha256")
            != file_sha256(campaign_dir / "campaign.json")
            or not SHA256_RE.fullmatch(str(digest))
            or _fingerprint(unsigned) != digest
            or payload.get("previous_controls") != previous_controls
        ):
            raise ConfigurationError("control epoch 收据结构、链路、身份或自摘要非法。")
        if payload.get("source") != source:
            raise ConfigurationError("control epoch 源 Candidate／闭集发生漂移。")
        if final_execution_epoch:
            authorization = payload.get("execution_authorization")
            supervisor_audit = (
                authorization.get("supervisor_audit")
                if isinstance(authorization, Mapping)
                else None
            )
            if (
                not isinstance(effective, Mapping)
                or not isinstance(supervisor_audit, Mapping)
            ):
                raise ConfigurationError("最终 execution epoch 授权绑定不完整。")
            expected_authorization = _control_epoch_final_execution_authorization(
                campaign_dir,
                manifest,
                source=source,
                previous_epoch=effective,
                supervisor_run_dir=Path(str(supervisor_audit.get("run_dir", ""))),
            )
            if not _supervisor_audit_bound_mapping_matches(
                authorization,
                expected_authorization,
            ):
                raise ConfigurationError("最终 execution epoch 授权绑定发生漂移。")

        frozen_invariants = payload.get("invariants")
        frozen_production = (
            frozen_invariants.get("tool_production_sha256")
            if isinstance(frozen_invariants, Mapping)
            else None
        )
        if (
            not SHA256_RE.fullmatch(str(frozen_production or ""))
            or (
                frozen_production_sha256 is not None
                and frozen_production != frozen_production_sha256
            )
        ):
            raise ConfigurationError("control epoch 历史链的产出侧冻结身份不连续。")
        if frozen_production_sha256 is None:
            frozen_production_sha256 = str(frozen_production)
        authorized_production_drift = (
            control_replacement_epoch and bool(allowed_production_paths)
        )
        historical_runtime = (
            _allow_unrepaired_tool_drift
            or epoch_index < len(paths)
            or (epoch_index == 1 and has_runtime_repair)
        )
        if historical_runtime:
            if (
                not isinstance(frozen_invariants, Mapping)
                or set(frozen_invariants) != set(invariants)
                or not SHA256_RE.fullmatch(
                    str(frozen_invariants.get("tool_files_sha256", ""))
                )
                or (
                    not _allow_unrepaired_tool_drift
                    and not authorized_production_drift
                    and frozen_invariants.get("tool_production_sha256")
                    != invariants.get("tool_production_sha256")
                )
                or frozen_invariants.get("compose_sha256")
                != invariants.get("compose_sha256")
                or frozen_invariants.get("required_active_phase")
                != required_phase
            ):
                raise ConfigurationError("control epoch 历史链越过产出、compose 或阶段边界。")
        elif frozen_invariants != invariants:
            allowed_tool_files_drift = (
                (bool(allowed_production_paths) or official_sealed_epoch)
                and isinstance(frozen_invariants, Mapping)
                and set(frozen_invariants) == set(invariants)
                and SHA256_RE.fullmatch(
                    str(frozen_invariants.get("tool_files_sha256", ""))
                )
                and (
                    authorized_production_drift
                    or frozen_invariants.get("tool_production_sha256")
                    == invariants.get("tool_production_sha256")
                )
                and frozen_invariants.get("compose_sha256")
                == invariants.get("compose_sha256")
                and frozen_invariants.get("required_active_phase")
                == required_phase
            )
            if not allowed_tool_files_drift:
                raise ConfigurationError("control epoch 场景、compose 或工具身份漂移。")
        if payload.get("boundary") != _control_epoch_zero_boundary():
            raise ConfigurationError("control epoch 发布边界不是全零。")

        stop = payload.get("stop_checkpoint")
        stop_receipt = stop.get("receipt") if isinstance(stop, Mapping) else None
        old_timing = previous_controls.get("upgrade_timing")
        if not isinstance(stop, Mapping) or not isinstance(stop_receipt, Mapping):
            raise ConfigurationError("control epoch 旧 Ledger 停线绑定非法。")
        if not isinstance(old_timing, Mapping):
            raise ConfigurationError("control epoch 前序 Ledger 控制绑定非法。")
        stop_required_phase = required_phase
        if (
            _historical_ledger_heads
            and control_replacement_epoch
            and epoch_index == 1
            and old_timing == manifest.get("control_receipts", {}).get(
                "upgrade_timing"
            )
        ):
            # 旧版 control-replacement 首个 epoch 已按文档允许从 VC-0
            # 停线承接；历史重放不得用后继 Ledger 的 VC-4 规则追溯改判。
            stop_required_phase = None
        expected_stop, stop_summary = _control_epoch_stop_checkpoint(
            manifest,
            Path(str(stop.get("ledger_dir", ""))),
            Path(str(stop_receipt.get("path", ""))),
            expected_timing=old_timing,
            required_phase=stop_required_phase,
            _historical_ledger_heads=_historical_ledger_heads,
        )
        if stop != expected_stop:
            raise ConfigurationError("control epoch 旧 Ledger 停线绑定漂移。")

        successor = payload.get("successor_controls")
        if not isinstance(successor, Mapping):
            raise ConfigurationError("control epoch 缺少后继控制绑定。")
        if not (epoch_index == 1 and has_runtime_repair):
            _verify_control_receipts(
                campaign_dir,
                manifest,
                require_active=False,
                _control_override=successor,
                _tool_files_sha256_override=str(
                    frozen_invariants.get("tool_files_sha256", "")
                ),
                _historical_manifest_controls=(
                    historical_runtime or bool(allowed_production_paths)
                ),
            )
        timing = successor.get("upgrade_timing")
        if not isinstance(timing, Mapping):
            raise ConfigurationError("control epoch 后继 Ledger 绑定非法。")
        _, successor_checkpoint = _sealed_stage_timing_checkpoint(
            timing,
            label="control epoch 后继 Ledger",
        )
        successor_summary = successor_checkpoint["summary"]
        stop_elapsed = int(stop_summary["total_elapsed_seconds"])
        successor_elapsed = int(successor_summary["total_elapsed_seconds"])
        if epoch_index > 1 and stop_elapsed < previous_successor_elapsed:
            raise ConfigurationError("control epoch 前序累计耗时发生倒退。")
        cumulative_elapsed = (
            stop_elapsed + successor_elapsed
            if epoch_index == 1
            else previous_cumulative_elapsed
            + stop_elapsed
            - previous_successor_elapsed
            + successor_elapsed
        )
        budget = payload.get("budget")
        expected_budget = {
            "predecessor_total_deadline_at_utc": stop_summary[
                "total_deadline_at_utc"
            ],
            "successor_total_deadline_at_utc": successor_summary[
                "total_deadline_at_utc"
            ],
            "predecessor_elapsed_seconds": stop_summary["total_elapsed_seconds"],
            "successor_elapsed_seconds": successor_summary[
                "total_elapsed_seconds"
            ],
            "cumulative_elapsed_seconds": cumulative_elapsed,
            "predecessor_live_request_count": stop_summary[
                "total_live_request_count"
            ],
            "successor_live_request_count": successor_summary[
                "total_live_request_count"
            ],
            "cumulative_live_request_count": 0,
        }
        predecessor_deadline = _rfc3339_datetime(
            str(stop_summary["total_deadline_at_utc"]),
            "control-epoch.predecessor-total-deadline",
        )
        successor_deadline = _rfc3339_datetime(
            str(successor_summary["total_deadline_at_utc"]),
            "control-epoch.successor-total-deadline",
        )
        created_at = _rfc3339_datetime(
            str(payload["created_at_utc"]),
            "control-epoch.created-at",
        )
        deadline_reset_allowed = final_execution_epoch or official_sealed_epoch
        deadline_invalid = (
            successor_deadline <= created_at
            or successor_deadline
            > created_at
            + timedelta(seconds=CONTROL_EPOCH_FINAL_EXECUTION_MAX_SECONDS)
            if deadline_reset_allowed
            else successor_deadline > predecessor_deadline
        )
        if (
            budget != expected_budget
            or successor_summary.get("status") != "active"
            or successor_summary.get("active_phase") != required_phase
            or successor_summary.get("total_live_request_count") != 0
            or stop_summary.get("total_live_request_count") != 0
            or deadline_invalid
            or timing.get("ledger_dir") == old_timing.get("ledger_dir")
            or timing.get("upgrade_id") == old_timing.get("upgrade_id")
            or timing.get("evidence_decision")
            != old_timing.get("evidence_decision")
        ):
            raise ConfigurationError("control epoch 预算、阶段或新 Ledger 身份非法。")

        effective = json.loads(json.dumps(payload, ensure_ascii=False))
        if epoch_index == 1 and has_runtime_repair:
            effective = _load_control_epoch_runtime_repair(
                campaign_dir,
                manifest,
                payload,
                current_invariants=invariants,
                allow_current_tool_drift=(
                    _allow_unrepaired_tool_drift
                    or authorized_production_drift
                    or official_sealed_epoch
                    or epoch_index < len(paths)
                    or has_runtime_repair_amendment
                ),
                allow_historical_production_drift=(
                    _allow_unrepaired_tool_drift
                    or authorized_production_drift
                ),
            )
            if has_runtime_repair_amendment:
                first_runtime_repair = effective.get("runtime_repair")
                if not isinstance(first_runtime_repair, Mapping):
                    raise ConfigurationError("control epoch 首份运行授权修复绑定缺失。")
                effective = _load_control_epoch_runtime_repair(
                    campaign_dir,
                    manifest,
                    effective,
                    current_invariants=invariants,
                    allow_current_tool_drift=True,
                    allow_historical_production_drift=(
                        _allow_unrepaired_tool_drift
                        or authorized_production_drift
                    ),
                    adopt_current_invariants=True,
                    repair_index=2,
                    path=repair_amendment_path,
                    previous_runtime_repair=first_runtime_repair,
                )
        previous_controls = effective["successor_controls"]
        previous_epoch_sha256 = str(payload["receipt_sha256"])
        previous_cumulative_elapsed = int(budget["cumulative_elapsed_seconds"])
        previous_successor_elapsed = int(budget["successor_elapsed_seconds"])

    return effective


def _control_epoch_zero_boundary() -> dict[str, int]:
    """返回 control epoch 及其运行授权修复共用的零执行边界。"""

    return {
        "reservation_count": 0,
        "attempt_count": 0,
        "checkpoint_count": 0,
        "live_request_count": 0,
        "scanned_bytes": 0,
    }


def _load_control_epoch_runtime_repair(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    base_epoch: Mapping[str, Any],
    *,
    current_invariants: Mapping[str, Any],
    allow_current_tool_drift: bool = False,
    allow_historical_production_drift: bool = False,
    adopt_current_invariants: bool = False,
    repair_index: int = 1,
    path: Path | None = None,
    previous_runtime_repair: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """重放运行授权修复链的一项，并返回下一项可消费的有效 epoch。"""

    if repair_index not in {1, 2}:
        raise ConfigurationError("control epoch 运行授权修复序号非法。")
    source = base_epoch.get("source")
    official_classification_repair = (
        isinstance(source, Mapping)
        and _is_official_sealed_control_epoch_source(source)
    )
    if official_classification_repair and repair_index != 1:
        raise ConfigurationError("official epoch 分类控制修复只允许一份。")
    if adopt_current_invariants and not allow_current_tool_drift:
        raise ConfigurationError("control epoch 历史修复不得无条件采用当前工具身份。")
    if path is None:
        path = _control_epoch_runtime_repair_path(campaign_dir)
    if path.is_symlink() or not path.is_file():
        raise ConfigurationError("control epoch 运行授权修复路径不可信。")
    payload = _read_json(path, "control epoch 运行授权修复收据")
    required = {
        "schema_version",
        "status",
        "repair_index",
        "created_at_utc",
        "campaign_id",
        "campaign_manifest_sha256",
        "control_epoch",
        "previous_tool_files_sha256",
        "successor_controls",
        "source",
        "invariants",
        "boundary",
        "budget",
        "receipt_sha256",
    }
    if repair_index == 2:
        required.add("previous_runtime_repair")
    if official_classification_repair:
        required.add("stop_checkpoint")
    unsigned = dict(payload)
    digest = unsigned.pop("receipt_sha256", None)
    epoch_path = _control_epoch_path(campaign_dir)
    epoch_binding = {
        "path": epoch_path.relative_to(campaign_dir).as_posix(),
        "sha256": file_sha256(epoch_path),
        "bytes": epoch_path.stat().st_size,
        "receipt_sha256": base_epoch.get("receipt_sha256"),
    }
    if (
        set(payload) != required
        or payload.get("schema_version") != CONTROL_EPOCH_RUNTIME_REPAIR_SCHEMA
        or payload.get("status") != "active"
        or payload.get("repair_index") != repair_index
        or not _is_rfc3339_timestamp(payload.get("created_at_utc"))
        or payload.get("campaign_id") != manifest.get("campaign_id")
        or payload.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or payload.get("control_epoch") != epoch_binding
        or payload.get("previous_tool_files_sha256")
        != base_epoch.get("invariants", {}).get("tool_files_sha256")
        or (
            repair_index == 2
            and payload.get("previous_runtime_repair")
            != previous_runtime_repair
        )
        or (repair_index == 1 and previous_runtime_repair is not None)
        or not SHA256_RE.fullmatch(str(digest))
        or _fingerprint(unsigned) != digest
    ):
        raise ConfigurationError("control epoch 运行授权修复结构、身份或自摘要非法。")

    if payload.get("source") != source:
        raise ConfigurationError("control epoch 运行授权修复的源闭集发生漂移。")
    repair_invariants = payload.get("invariants")
    required_phase = (
        _control_epoch_required_phase(source)
        if isinstance(source, Mapping)
        else "VC-4"
    )
    if allow_current_tool_drift:
        if (
            not isinstance(repair_invariants, Mapping)
            or set(repair_invariants) != set(current_invariants)
            or not SHA256_RE.fullmatch(
                str(repair_invariants.get("tool_files_sha256", ""))
            )
            or (
                not allow_historical_production_drift
                and repair_invariants.get("tool_production_sha256")
                != current_invariants.get("tool_production_sha256")
            )
            or repair_invariants.get("compose_sha256")
            != current_invariants.get("compose_sha256")
            or repair_invariants.get("required_active_phase") != required_phase
        ):
            raise ConfigurationError("control epoch 运行修复越过产出、compose 或阶段边界。")
    elif repair_invariants != dict(current_invariants):
        raise ConfigurationError("control epoch 运行授权修复未绑定当前工具身份。")
    if payload.get("boundary") != _control_epoch_zero_boundary():
        raise ConfigurationError("control epoch 运行授权修复边界不是全零。")
    if payload.get("budget") != base_epoch.get("budget"):
        raise ConfigurationError("control epoch 运行授权修复改变了既有预算。")

    base_controls = base_epoch.get("successor_controls")
    controls = payload.get("successor_controls")
    expected_control_names = {
        "upgrade_timing",
        "arm64_environment",
        "job_rehearsal",
    }
    if (
        not isinstance(base_controls, Mapping)
        or not isinstance(controls, Mapping)
        or set(base_controls) != expected_control_names
        or set(controls) != expected_control_names
    ):
        raise ConfigurationError("control epoch 运行授权修复控制字段不闭合。")
    if official_classification_repair:
        stop = payload.get("stop_checkpoint")
        stop_receipt = stop.get("receipt") if isinstance(stop, Mapping) else None
        if not isinstance(stop, Mapping) or not isinstance(stop_receipt, Mapping):
            raise ConfigurationError("official epoch 分类控制修复缺少旧 Ledger 停线绑定。")
        expected_stop, stop_summary = _control_epoch_stop_checkpoint(
            manifest,
            Path(str(stop.get("ledger_dir", ""))),
            Path(str(stop_receipt.get("path", ""))),
            expected_timing=base_controls.get("upgrade_timing"),
            required_phase="VC-2",
        )
        timing = controls.get("upgrade_timing")
        if not isinstance(timing, Mapping):
            raise ConfigurationError("official epoch 分类控制修复缺少新 Ledger。")
        _, checkpoint = _sealed_stage_timing_checkpoint(
            timing,
            label="official epoch 分类控制修复",
        )
        successor_summary = checkpoint.get("summary")
        base_budget = base_epoch.get("budget")
        if (
            stop != expected_stop
            or not isinstance(stop_summary, Mapping)
            or not isinstance(successor_summary, Mapping)
            or not isinstance(base_budget, Mapping)
            or controls.get("upgrade_timing") == base_controls.get("upgrade_timing")
            or controls.get("arm64_environment")
            == base_controls.get("arm64_environment")
            or controls.get("job_rehearsal") == base_controls.get("job_rehearsal")
            or successor_summary.get("status") != "active"
            or successor_summary.get("active_phase") != "VC-2"
            or successor_summary.get("total_live_request_count") != 0
            or stop_summary.get("total_live_request_count") != 0
            or _rfc3339_datetime(
                str(successor_summary.get("total_deadline_at_utc", "")),
                "official-classification-repair.successor-total-deadline",
            )
            > _rfc3339_datetime(
                str(base_budget.get("successor_total_deadline_at_utc", "")),
                "official-classification-repair.epoch-total-deadline",
            )
        ):
            raise ConfigurationError(
                "official epoch 分类控制修复越过零执行、VC-2 或总截止边界。"
            )
    elif (
        controls.get("upgrade_timing") != base_controls.get("upgrade_timing")
        or controls.get("arm64_environment")
        != base_controls.get("arm64_environment")
        or controls.get("job_rehearsal") == base_controls.get("job_rehearsal")
    ):
        raise ConfigurationError(
            "control epoch 运行授权修复只能替换当前工具的 incremental-noop。"
        )
    if (
        payload.get("previous_tool_files_sha256")
        == current_invariants.get("tool_files_sha256")
    ):
        raise ConfigurationError("control epoch 运行授权修复没有工具身份变化。")
    _verify_control_receipts(
        campaign_dir,
        manifest,
        require_active=False,
        _control_override=controls,
        _tool_files_sha256_override=str(
            repair_invariants.get("tool_files_sha256", "")
        ),
        _historical_manifest_controls=allow_current_tool_drift,
    )

    effective = json.loads(json.dumps(base_epoch, ensure_ascii=False))
    effective["successor_controls"] = json.loads(
        json.dumps(controls, ensure_ascii=False)
    )
    effective["invariants"] = dict(
        current_invariants
        if adopt_current_invariants
        else repair_invariants
    )
    effective["runtime_repair"] = {
        "path": path.relative_to(campaign_dir).as_posix(),
        "sha256": file_sha256(path),
        "bytes": path.stat().st_size,
        "receipt_sha256": payload["receipt_sha256"],
    }
    return effective


def _create_control_epoch_runtime_repair(
    arguments: argparse.Namespace,
    campaign_dir: Path,
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    """追加一次零执行运行授权修复，不创建第二份 epoch 或 transition。"""

    first_path = _control_epoch_runtime_repair_path(campaign_dir)
    amendment_path = _control_epoch_runtime_repair_amendment_path(campaign_dir)
    if amendment_path.exists() or amendment_path.is_symlink():
        raise ConfigurationError("同一 control epoch 已有修复替代，禁止第三份。")
    repair_index = 2 if first_path.is_file() and not first_path.is_symlink() else 1
    path = amendment_path if repair_index == 2 else first_path
    base_epoch = _load_control_epoch_receipt(
        campaign_dir,
        manifest,
        _allow_unrepaired_tool_drift=True,
    )
    if base_epoch is None:
        raise ConfigurationError("运行授权修复要求已发布的唯一 control epoch。")
    boundary = _control_epoch_empty_boundary(campaign_dir)
    if boundary != _control_epoch_zero_boundary():
        raise ConfigurationError("control epoch 运行授权修复边界不是全零。")
    source = _control_epoch_source_context(
        campaign_dir,
        manifest,
        candidate_id=arguments.candidate_id,
        attempt_id=arguments.attempt_id,
    )
    if source != base_epoch.get("source"):
        raise ConfigurationError("运行授权修复不得改变 control epoch 源闭集。")
    official_classification_repair = _is_official_sealed_control_epoch_source(
        source
    )
    if official_classification_repair and (
        repair_index != 1 or first_path.exists() or first_path.is_symlink()
    ):
        raise ConfigurationError("official epoch 分类控制修复只允许一份。")
    base_controls = base_epoch.get("successor_controls")
    if not isinstance(base_controls, Mapping):
        raise ConfigurationError("运行授权修复缺少 control epoch 生效控制。")
    if official_classification_repair:
        stop, _stop_summary = _control_epoch_stop_checkpoint(
            manifest,
            arguments.predecessor_stop_ledger_dir,
            arguments.predecessor_stop_receipt,
            expected_timing=base_controls.get("upgrade_timing"),
            required_phase="VC-2",
        )
    else:
        stop, _stop_summary = _control_epoch_stop_checkpoint(
            manifest,
            arguments.predecessor_stop_ledger_dir,
            arguments.predecessor_stop_receipt,
        )
        if stop != base_epoch.get("stop_checkpoint"):
            raise ConfigurationError("运行授权修复不得改变旧 Ledger 停线绑定。")

    current_tool = _tool_identity(include_git=False)
    required_phase = "VC-2" if official_classification_repair else "VC-4"
    invariants = _control_epoch_invariants(
        manifest,
        current_tool,
        required_active_phase=required_phase,
    )
    previous_invariants = base_epoch.get("invariants")
    if (
        not isinstance(previous_invariants, Mapping)
        or previous_invariants.get("tool_files_sha256")
        == invariants.get("tool_files_sha256")
    ):
        raise ConfigurationError("运行授权修复要求工具身份确实发生变化。")
    controls, successor_summary, _rehearsal = (
        _build_control_epoch_successor_controls(
            arguments,
            campaign_dir,
            manifest,
            current_tool,
            required_phase=required_phase,
        )
    )
    if official_classification_repair:
        base_budget = base_epoch.get("budget")
        if (
            not isinstance(base_budget, Mapping)
            or controls.get("upgrade_timing") == base_controls.get("upgrade_timing")
            or controls.get("arm64_environment")
            == base_controls.get("arm64_environment")
            or controls.get("job_rehearsal") == base_controls.get("job_rehearsal")
            or successor_summary.get("status") != "active"
            or successor_summary.get("active_phase") != "VC-2"
            or successor_summary.get("total_live_request_count") != 0
            or _rfc3339_datetime(
                str(successor_summary.get("total_deadline_at_utc", "")),
                "official-classification-repair.successor-total-deadline",
            )
            > _rfc3339_datetime(
                str(base_budget.get("successor_total_deadline_at_utc", "")),
                "official-classification-repair.epoch-total-deadline",
            )
        ):
            raise ConfigurationError(
                "official epoch 分类控制修复越过零执行、VC-2 或总截止边界。"
            )
    elif (
        controls.get("upgrade_timing") != base_controls.get("upgrade_timing")
        or controls.get("arm64_environment")
        != base_controls.get("arm64_environment")
        or controls.get("job_rehearsal") == base_controls.get("job_rehearsal")
        or successor_summary.get("status") != "active"
        or successor_summary.get("active_phase") != "VC-4"
        or successor_summary.get("total_live_request_count") != 0
    ):
        raise ConfigurationError(
            "运行授权修复只能在同一 Ledger/P0 上替换当前 incremental-noop。"
        )

    epoch_path = _control_epoch_path(campaign_dir)
    epoch_binding = {
        "path": epoch_path.relative_to(campaign_dir).as_posix(),
        "sha256": file_sha256(epoch_path),
        "bytes": epoch_path.stat().st_size,
        "receipt_sha256": base_epoch["receipt_sha256"],
    }
    core = {
        "schema_version": CONTROL_EPOCH_RUNTIME_REPAIR_SCHEMA,
        "status": "active",
        "repair_index": repair_index,
        "created_at_utc": _utc_now(),
        "campaign_id": manifest["campaign_id"],
        "campaign_manifest_sha256": file_sha256(campaign_dir / "campaign.json"),
        "control_epoch": epoch_binding,
        "previous_tool_files_sha256": previous_invariants[
            "tool_files_sha256"
        ],
        "successor_controls": controls,
        "source": source,
        "invariants": invariants,
        "boundary": boundary,
        "budget": base_epoch["budget"],
    }
    if official_classification_repair:
        core["stop_checkpoint"] = stop
    if repair_index == 2:
        previous_runtime_repair = base_epoch.get("runtime_repair")
        if not isinstance(previous_runtime_repair, Mapping):
            raise ConfigurationError("修复替代缺少首份 runtime-repair 绑定。")
        core["previous_runtime_repair"] = dict(previous_runtime_repair)
    payload = {**core, "receipt_sha256": _fingerprint(core)}
    _secure_write_json_once(path, payload)
    effective = _load_control_epoch_receipt(campaign_dir, manifest)
    runtime_binding = effective.get("runtime_repair") if effective else None
    if (
        not isinstance(runtime_binding, Mapping)
        or runtime_binding.get("receipt_sha256") != payload["receipt_sha256"]
        or runtime_binding.get("sha256") != file_sha256(path)
    ):
        raise ConfigurationError("control epoch 运行授权修复发布后重放不一致。")
    return {
        "status": (
            "official_classification_control_repaired"
            if official_classification_repair
            else "control_epoch_runtime_repaired"
        ),
        "campaign_id": manifest["campaign_id"],
        "candidate_id": source.get("candidate_id"),
        "attempt_id": source.get("attempt_id"),
        "runtime_repair": {
            "path": str(path),
            "sha256": file_sha256(path),
            "receipt_sha256": payload["receipt_sha256"],
        },
        "repair_index": repair_index,
        "execute_job_ids": source.get("execute_job_ids", []),
        "reused_job_ids": source.get("reused_job_ids", []),
        **boundary,
        "next_command": (
            "classify"
            if official_classification_repair
            else "resume --rerun-failed --preview-recovery"
        ),
    }


def create_control_epoch(arguments: argparse.Namespace) -> dict[str, Any]:
    """在原 Campaign 追加有界控制纪元，不创建执行事实。"""

    campaign_dir = arguments.campaign_dir
    manifest = _require_formal_campaign(
        campaign_dir,
        load_campaign_manifest(campaign_dir, _control_epoch_bootstrap=True),
    )
    phase = str(getattr(arguments, "phase", "candidate"))
    official_sealed_epoch = phase == "official"
    candidate_coordinates = (
        getattr(arguments, "candidate_id", None),
        getattr(arguments, "attempt_id", None),
    )
    if official_sealed_epoch:
        if any(candidate_coordinates):
            raise ConfigurationError(
                "official control epoch 不得提供 Candidate 或 attempt。"
            )
    elif any(value is None for value in candidate_coordinates):
        raise ConfigurationError(
            "candidate control epoch 必须同时提供 Candidate 和 attempt。"
        )
    with _campaign_lock(campaign_dir):
        existing = _control_epoch_files(campaign_dir)
        if (
            official_sealed_epoch
            and existing
            and not arguments.repair_runtime_authorization
        ):
            raise ConfigurationError(
                "official_sealed Campaign 已使用唯一 control epoch。"
            )
        predecessor = manifest.get("predecessor")
        control_replacement_epoch = (
            isinstance(predecessor, Mapping)
            and predecessor.get("reason")
            == "candidate_recovery_control_replacement"
        )
        final_execution_epoch = bool(
            getattr(arguments, "final_execution_epoch", False)
        )
        if official_sealed_epoch and final_execution_epoch:
            raise ConfigurationError(
                "official control epoch 不允许 final-execution。"
            )
        supervisor_run_dir = getattr(
            arguments,
            "predecessor_supervisor_run_dir",
            None,
        )
        replacement_current_tool: Mapping[str, Any] | None = None
        if control_replacement_epoch:
            if not existing and final_execution_epoch:
                raise ConfigurationError(
                    "最终 execution epoch 要求已有第一份 control epoch。"
                )
            if existing and not arguments.repair_runtime_authorization:
                if not final_execution_epoch or len(existing) != 1:
                    raise ConfigurationError(
                        "控制替代后继只允许 repair-02 后追加一次最终 execution epoch。"
                    )
            if not existing:
                replacement_current_tool = _tool_identity(include_git=False)
                frozen_tool = manifest.get("tool_identity")
                if (
                    not isinstance(frozen_tool, Mapping)
                    or replacement_current_tool.get("files_sha256")
                    == frozen_tool.get("files_sha256")
                ):
                    raise ConfigurationError(
                        "控制替代后继的 control epoch 要求编排工具身份确实变化。"
                    )
        elif final_execution_epoch:
            raise ConfigurationError(
                "--final-execution-epoch 只允许用于 replacement Campaign。"
            )
        if final_execution_epoch and arguments.repair_runtime_authorization:
            raise ConfigurationError("最终 execution epoch 不能同时创建 runtime-repair。")
        if (supervisor_run_dir is not None) != final_execution_epoch:
            raise ConfigurationError(
                "父监督器审计目录只能且必须随最终 execution epoch 提供。"
            )
        if existing and arguments.repair_runtime_authorization:
            if len(existing) != 1:
                raise ConfigurationError("运行授权修复只允许绑定第一个 control epoch。")
            return _create_control_epoch_runtime_repair(
                arguments,
                campaign_dir,
                manifest,
            )
        if len(existing) >= CONTROL_EPOCH_MAX_COUNT:
            raise ConfigurationError("同一 Campaign 已用完两个 control epoch。")
        if arguments.repair_runtime_authorization:
            raise ConfigurationError("运行授权修复要求先有第一个 control epoch。")
        previous_epoch = (
            _load_control_epoch_receipt(
                campaign_dir,
                manifest,
                _allow_unrepaired_tool_drift=True,
            )
            if existing
            else None
        )
        boundary = _control_epoch_empty_boundary(campaign_dir)
        source = _control_epoch_source_context(
            campaign_dir,
            manifest,
            candidate_id=arguments.candidate_id,
            attempt_id=arguments.attempt_id,
        )
        previous_controls = _control_epoch_previous_controls(
            manifest,
            source,
            previous_epoch,
        )
        required_phase = _control_epoch_required_phase(source)
        stop, stop_summary = _control_epoch_stop_checkpoint(
            manifest,
            arguments.predecessor_stop_ledger_dir,
            arguments.predecessor_stop_receipt,
            expected_timing=previous_controls.get("upgrade_timing"),
            required_phase=required_phase,
        )
        current_tool = (
            replacement_current_tool
            if replacement_current_tool is not None
            else _tool_identity(include_git=False)
        )
        invariants = _control_epoch_invariants(
            manifest,
            current_tool,
            required_active_phase=required_phase,
        )
        controls, successor_summary, _rehearsal = (
            _build_control_epoch_successor_controls(
                arguments,
                campaign_dir,
                manifest,
                current_tool,
                required_phase=required_phase,
            )
        )
        if (
            int(stop_summary.get("total_live_request_count", -1)) != 0
            or int(successor_summary.get("total_live_request_count", -1)) != 0
        ):
            raise ConfigurationError("control epoch 发布前旧／新 Ledger live 请求必须为 0。")
        predecessor_deadline = _rfc3339_datetime(
            str(stop_summary["total_deadline_at_utc"]),
            "control-epoch.predecessor-total-deadline",
        )
        successor_deadline = _rfc3339_datetime(
            str(successor_summary["total_deadline_at_utc"]),
            "control-epoch.successor-total-deadline",
        )
        created_at_utc = _utc_now()
        created_at = _rfc3339_datetime(
            created_at_utc,
            "control-epoch.created-at",
        )
        if final_execution_epoch or official_sealed_epoch:
            if (
                successor_deadline <= created_at
                or successor_deadline
                > created_at
                + timedelta(seconds=CONTROL_EPOCH_FINAL_EXECUTION_MAX_SECONDS)
            ):
                raise ConfigurationError(
                    "最终 execution epoch 的新总截止必须位于创建后 6 小时内。"
                )
        elif successor_deadline > predecessor_deadline:
            raise ConfigurationError("control epoch 新 Ledger 不得把总截止时间后移。")
        old_timing = previous_controls["upgrade_timing"]
        new_timing = controls["upgrade_timing"]
        if (
            old_timing.get("ledger_dir") == new_timing.get("ledger_dir")
            or old_timing.get("upgrade_id") == new_timing.get("upgrade_id")
            or old_timing.get("evidence_decision")
            != new_timing.get("evidence_decision")
        ):
            raise ConfigurationError("control epoch 必须使用新 Ledger 并保留证据决定。")
        previous_budget = (
            previous_epoch.get("budget")
            if isinstance(previous_epoch, Mapping)
            else None
        )
        previous_cumulative_elapsed = (
            int(previous_budget["cumulative_elapsed_seconds"])
            if isinstance(previous_budget, Mapping)
            else int(stop_summary["total_elapsed_seconds"])
        )
        previous_successor_elapsed = (
            int(previous_budget["successor_elapsed_seconds"])
            if isinstance(previous_budget, Mapping)
            else 0
        )
        stop_elapsed = int(stop_summary["total_elapsed_seconds"])
        if (
            isinstance(previous_budget, Mapping)
            and stop_elapsed < previous_successor_elapsed
        ):
            raise ConfigurationError("control epoch 前序累计耗时发生倒退。")
        cumulative_elapsed = (
            previous_cumulative_elapsed
            + stop_elapsed
            - previous_successor_elapsed
            + int(successor_summary["total_elapsed_seconds"])
            if isinstance(previous_budget, Mapping)
            else stop_elapsed + int(successor_summary["total_elapsed_seconds"])
        )
        budget = {
            "predecessor_total_deadline_at_utc": stop_summary[
                "total_deadline_at_utc"
            ],
            "successor_total_deadline_at_utc": successor_summary[
                "total_deadline_at_utc"
            ],
            "predecessor_elapsed_seconds": stop_summary["total_elapsed_seconds"],
            "successor_elapsed_seconds": successor_summary["total_elapsed_seconds"],
            "cumulative_elapsed_seconds": cumulative_elapsed,
            "predecessor_live_request_count": stop_summary[
                "total_live_request_count"
            ],
            "successor_live_request_count": successor_summary[
                "total_live_request_count"
            ],
            "cumulative_live_request_count": 0,
        }
        core = {
            "schema_version": CONTROL_EPOCH_SCHEMA,
            "status": "active",
            "epoch_index": len(existing) + 1,
            "created_at_utc": created_at_utc,
            "campaign_id": manifest["campaign_id"],
            "campaign_manifest_sha256": file_sha256(campaign_dir / "campaign.json"),
            "previous_epoch_sha256": (
                str(previous_epoch.get("receipt_sha256"))
                if existing and isinstance(previous_epoch, Mapping)
                else None
            ),
            "previous_controls": json.loads(
                json.dumps(previous_controls, ensure_ascii=False)
            ),
            "stop_checkpoint": stop,
            "successor_controls": controls,
            "source": source,
            "invariants": invariants,
            "boundary": boundary,
            "budget": budget,
        }
        if final_execution_epoch:
            assert isinstance(previous_epoch, Mapping)
            assert isinstance(supervisor_run_dir, Path)
            core["execution_authorization"] = (
                _control_epoch_final_execution_authorization(
                    campaign_dir,
                    manifest,
                    source=source,
                    previous_epoch=previous_epoch,
                    supervisor_run_dir=supervisor_run_dir,
                )
            )
        payload = {**core, "receipt_sha256": _fingerprint(core)}
        path = _control_epoch_path(campaign_dir, int(core["epoch_index"]))
        _secure_write_json_once(path, payload)
        validated = _load_control_epoch_receipt(campaign_dir, manifest)
        if validated != payload:
            raise ConfigurationError("control epoch 发布后重放结果不一致。")
    return {
        "status": "control_epoch_active",
        "campaign_id": manifest["campaign_id"],
        "phase": phase,
        "candidate_id": source.get("candidate_id"),
        "attempt_id": source.get("attempt_id"),
        "control_epoch": {
            "path": str(path),
            "sha256": file_sha256(path),
            "receipt_sha256": payload["receipt_sha256"],
        },
        "execute_job_ids": source["execute_job_ids"],
        "reused_job_ids": source["reused_job_ids"],
        "reservation_count": 0,
        "attempt_count": 0,
        "checkpoint_count": 0,
        "live_request_count": 0,
        "scanned_bytes": 0,
        "final_execution_epoch": final_execution_epoch,
        "next_command": (
            "classify"
            if official_sealed_epoch
            else "resume --rerun-failed --preview-recovery"
        ),
    }


def _control_replacement_file_binding(
    root: Path,
    path: Path,
    *,
    label: str,
) -> dict[str, Any]:
    """为控制替代审计文件生成不可变绑定。"""

    if path.is_symlink() or not path.is_file():
        raise ConfigurationError(f"{label}不存在或不可信。")
    try:
        relative = path.resolve(strict=True).relative_to(root.resolve(strict=True))
    except (OSError, RuntimeError, ValueError) as error:
        raise ConfigurationError(f"{label}不在受管根目录内。") from error
    size = path.stat().st_size
    if size <= 0:
        raise ConfigurationError(f"{label}为空。")
    return {
        "path": relative.as_posix(),
        "sha256": file_sha256(path),
        "bytes": size,
    }


def _control_replacement_stopped_ledger(
    ledger_root: Path,
    receipt_path: Path,
    manifest: Mapping[str, Any],
    *,
    expected_evidence_decision: str,
) -> dict[str, Any]:
    """重放零执行替代所绑定的未发布 Ledger 当前停线 head。"""

    relative = _control_receipt_relative(
        ledger_root,
        receipt_path,
        "控制替代未发布 Ledger stop_the_line checkpoint",
    )
    try:
        checkpoint = codex_upgrade_timing_ledger.replay(ledger_root, relative)
        current = codex_upgrade_timing_ledger.inspect_ledger(ledger_root)
    except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
        raise ConfigurationError(
            f"控制替代未发布 Ledger 无法重放：{error}"
        ) from error
    summary = checkpoint.get("summary")
    if (
        not isinstance(summary, Mapping)
        or summary.get("status") != "stopped"
        or summary.get("active_phase") != "VC-4"
        or summary.get("baseline_version") != manifest.get("baseline_version")
        or summary.get("target_version") != manifest.get("target_version")
        or summary.get("campaign_purpose") != manifest.get("campaign_purpose")
        or summary.get("evidence_decision") != expected_evidence_decision
        or summary.get("total_live_request_count") != 0
        or current.get("status") != "stopped"
        or current.get("head_sequence") != summary.get("head_sequence")
        or current.get("head_sha256") != summary.get("head_sha256")
        or current.get("total_live_request_count") != 0
    ):
        raise ConfigurationError(
            "控制替代未发布 Ledger 必须是当前 VC-4 零请求停线 head。"
        )
    resolved_root = ledger_root.resolve(strict=True)
    stop_file = resolved_root / relative
    return {
        "ledger_dir": str(resolved_root),
        "receipt": {
            "path": relative,
            "sha256": file_sha256(stop_file),
            "bytes": stop_file.stat().st_size,
        },
        "upgrade_id": summary["upgrade_id"],
        "evidence_decision": summary["evidence_decision"],
        "active_phase": summary["active_phase"],
        "head_sequence": summary["head_sequence"],
        "head_sha256": summary["head_sha256"],
        "total_elapsed_seconds": summary["total_elapsed_seconds"],
        "total_live_request_count": summary["total_live_request_count"],
        "total_deadline_at_utc": summary["total_deadline_at_utc"],
    }


def _control_replacement_supervisor_audit(run_dir: Path) -> dict[str, Any]:
    """绑定已终止且无缺口的父监督器审计链，不复制日志内容。"""

    if not run_dir.is_absolute():
        raise ConfigurationError("控制替代父监督器目录必须是绝对路径。")
    try:
        resolved = run_dir.resolve(strict=True)
    except (OSError, RuntimeError) as error:
        raise ConfigurationError("控制替代父监督器目录不存在。") from error
    if resolved != run_dir or run_dir.is_symlink() or not run_dir.is_dir():
        raise ConfigurationError("控制替代父监督器目录不可信。")
    try:
        audit = codex_upgrade_supervisor._audit_command(resolved)
    except (OSError, codex_upgrade_supervisor.SupervisorError) as error:
        raise ConfigurationError(f"控制替代父监督器审计失败：{error}") from error
    state_path = resolved / "state.json"
    stop_path = resolved / "stop-receipt.json"
    events_path = resolved / "events.ndjson"
    minute_path = resolved / "minute-ledger.ndjson"
    state = _read_json(state_path, "控制替代父监督器状态")
    stop = _read_json(stop_path, "控制替代父监督器停线收据")
    unsigned_stop = dict(stop)
    stop_digest = unsigned_stop.pop("receipt_sha256", None)
    expected_stop_digest = codex_upgrade_supervisor._sha256(
        codex_upgrade_supervisor._canonical(unsigned_stop)
    )
    terminal_states = {"stopped", "failed"}
    if (
        audit.get("audit_incomplete") is not False
        or audit.get("integrity_errors") != []
        or audit.get("state") not in terminal_states
        or state.get("state") != audit.get("state")
        or state.get("state") not in terminal_states
        or not _is_rfc3339_timestamp(state.get("terminal_at_utc"))
        or stop.get("schema_version")
        != codex_upgrade_supervisor.STOP_SCHEMA
        or not SHA256_RE.fullmatch(str(stop_digest))
        or expected_stop_digest != stop_digest
        or stop.get("campaign_id") != state.get("campaign_id")
        or stop.get("phase") != state.get("phase")
        or stop.get("owner_pid") != state.get("owner_pid")
        or stop.get("owner_nonce") != state.get("owner_nonce")
    ):
        raise ConfigurationError(
            "控制替代要求父监督器已进入可重放终态且 audit_incomplete=false。"
        )
    return {
        "run_dir": str(resolved),
        "state": _control_replacement_file_binding(
            resolved, state_path, label="控制替代父监督器状态"
        ),
        "stop_receipt": _control_replacement_file_binding(
            resolved, stop_path, label="控制替代父监督器停线收据"
        ),
        "events": _control_replacement_file_binding(
            resolved, events_path, label="控制替代父监督器事件账本"
        ),
        "minute_ledger": _control_replacement_file_binding(
            resolved, minute_path, label="控制替代父监督器分钟账本"
        ),
        "summary": audit,
    }


def _supervisor_audit_bound_mapping_matches(
    stored: Mapping[str, Any], replayed: Mapping[str, Any]
) -> bool:
    """比较绑定监督器摘要，并兼容旧监督器缺省的 continuity 字段。

    旧版监督器的 ``_audit_command`` 摘要没有 ``continuity`` 字段；新版在
    没有父监督器续接时会显式写入 ``continuity: null``。这只是摘要形状
    变化，不代表控制链或失败闭集变化。兼容范围仅限于“旧值缺字段且当前
    重放值为 null”，任何真实续接内容或其它字段差异仍然失败关闭。
    """

    if dict(stored) == dict(replayed):
        return True
    normalized = json.loads(json.dumps(stored, ensure_ascii=False))
    stored_audit = normalized.get("supervisor_audit")
    replayed_audit = replayed.get("supervisor_audit")
    if not isinstance(stored_audit, Mapping) or not isinstance(
        replayed_audit, Mapping
    ):
        return False
    stored_summary = stored_audit.get("summary")
    replayed_summary = replayed_audit.get("summary")
    if not isinstance(stored_summary, Mapping) or not isinstance(
        replayed_summary, Mapping
    ):
        return False
    if (
        "continuity" not in stored_summary
        and replayed_summary.get("continuity") is None
    ):
        normalized_audit = dict(stored_audit)
        normalized_audit["summary"] = {
            **dict(stored_summary),
            "continuity": None,
        }
        normalized["supervisor_audit"] = normalized_audit
    return normalized == dict(replayed)


def _control_replacement_context_matches(
    stored: Mapping[str, Any], replayed: Mapping[str, Any]
) -> bool:
    """比较控制替代上下文，并复用监督器摘要的历史兼容规则。"""

    return _supervisor_audit_bound_mapping_matches(stored, replayed)


def _control_replacement_context(
    arguments: argparse.Namespace,
    predecessor_dir: Path,
    predecessor_manifest: Mapping[str, Any],
) -> dict[str, Any]:
    """重放已耗尽 control-refresh，并冻结唯一零执行替代边界。"""

    predecessor = predecessor_manifest.get("predecessor")
    if (
        arguments.reason != "candidate_recovery_control_replacement"
        or not isinstance(predecessor, Mapping)
        or predecessor.get("reason") != "candidate_recovery_control_refresh"
    ):
        raise ConfigurationError(
            "零执行控制替代只允许直接承接唯一 candidate_recovery_control_refresh。"
        )
    required_paths = (
        arguments.predecessor_control_epoch,
        arguments.predecessor_unpublished_ledger_dir,
        arguments.predecessor_unpublished_stop_receipt,
        arguments.predecessor_supervisor_run_dir,
    )
    if not all(isinstance(value, Path) for value in required_paths):
        raise ConfigurationError(
            "零执行控制替代必须绑定有效 epoch、未发布停线 Ledger 和父监督器终态。"
        )
    epoch_paths = _control_epoch_files(predecessor_dir)
    if not epoch_paths:
        raise ConfigurationError("零执行控制替代要求前序已经发布 control epoch。")
    assert isinstance(arguments.predecessor_control_epoch, Path)
    if (
        arguments.predecessor_control_epoch.resolve(strict=True)
        != epoch_paths[-1].resolve(strict=True)
    ):
        raise ConfigurationError("零执行控制替代未绑定最后一份有效 control epoch。")
    effective_epoch = _load_control_epoch_receipt(
        predecessor_dir,
        predecessor_manifest,
        _allow_unrepaired_tool_drift=True,
    )
    if not isinstance(effective_epoch, Mapping):
        raise ConfigurationError("零执行控制替代无法重放有效 control epoch。")
    epoch_payload = _read_json(epoch_paths[-1], "控制替代有效 epoch")
    epoch_binding = {
        "path": epoch_paths[-1].relative_to(predecessor_dir).as_posix(),
        "sha256": file_sha256(epoch_paths[-1]),
        "bytes": epoch_paths[-1].stat().st_size,
        "receipt_sha256": epoch_payload.get("receipt_sha256"),
    }
    repair_path = _control_epoch_runtime_repair_path(predecessor_dir)
    repair_binding: dict[str, Any] | None = None
    if repair_path.exists() or repair_path.is_symlink():
        supplied_repair = arguments.predecessor_control_runtime_repair
        if (
            not isinstance(supplied_repair, Path)
            or supplied_repair.resolve(strict=True) != repair_path.resolve(strict=True)
            or repair_path.is_symlink()
            or not repair_path.is_file()
        ):
            raise ConfigurationError("零执行控制替代必须绑定有效 epoch 的运行授权修复。")
        repair_payload = _read_json(repair_path, "控制替代运行授权修复")
        repair_binding = {
            "path": repair_path.relative_to(predecessor_dir).as_posix(),
            "sha256": file_sha256(repair_path),
            "bytes": repair_path.stat().st_size,
            "receipt_sha256": repair_payload.get("receipt_sha256"),
        }
    elif arguments.predecessor_control_runtime_repair is not None:
        raise ConfigurationError("前序没有运行授权修复，不得提供伪造绑定。")

    boundary = _control_epoch_empty_boundary(predecessor_dir)
    if boundary != _control_epoch_zero_boundary():
        raise ConfigurationError("零执行控制替代边界不是全零。")
    source = effective_epoch.get("source")
    controls = effective_epoch.get("successor_controls")
    timing = controls.get("upgrade_timing") if isinstance(controls, Mapping) else None
    if (
        not isinstance(source, Mapping)
        or not isinstance(controls, Mapping)
        or set(controls)
        != {"upgrade_timing", "arm64_environment", "job_rehearsal"}
        or not isinstance(timing, Mapping)
        or source.get("candidate_id") != arguments.predecessor_candidate_id
        or source.get("attempt_id") != arguments.predecessor_attempt_id
    ):
        raise ConfigurationError("零执行控制替代的源 attempt、闭集或有效控制漂移。")
    planned = set(source.get("planned_job_ids", []))
    executed = set(source.get("execute_job_ids", []))
    reused = set(source.get("reused_job_ids", []))
    failed = set(source.get("failed_job_ids", []))
    pending = set(source.get("pending_job_ids", []))
    if (
        not planned
        or not failed
        or executed != failed | pending
        or executed & reused
        or executed | reused != planned
    ):
        raise ConfigurationError("零执行控制替代的失败／复用 Job 闭集不闭合。")

    source_dir = Path(str(predecessor.get("campaign_dir", "")))
    if (
        not source_dir.is_absolute()
        or str(source_dir.resolve(strict=True)) != str(source_dir)
    ):
        raise ConfigurationError("零执行控制替代的源 Campaign 路径不可信。")
    source_manifest = _require_formal_campaign(
        source_dir,
        load_campaign_manifest(
            source_dir,
            _control_epoch_bootstrap=True,
        ),
    )
    if (
        source_manifest.get("campaign_id") != predecessor.get("campaign_id")
        or file_sha256(source_dir / "campaign.json")
        != predecessor.get("campaign_manifest_sha256")
    ):
        raise ConfigurationError("零执行控制替代的源 Campaign 身份漂移。")
    source_attempt = _successor_abandoned_attempt(
        source_dir,
        arguments.predecessor_candidate_id,
        arguments.predecessor_attempt_id,
        _historical_manifest_controls=True,
    )
    if (
        not isinstance(source_attempt, Mapping)
        or source_attempt.get("status") != "failed"
        or source_attempt.get("attempt_digest") != source.get("attempt_digest")
        or source_attempt.get("identity_sha256")
        != source.get("candidate_identity_sha256")
    ):
        raise ConfigurationError("零执行控制替代的源失败 attempt 绑定漂移。")

    assert isinstance(arguments.predecessor_unpublished_ledger_dir, Path)
    assert isinstance(arguments.predecessor_unpublished_stop_receipt, Path)
    unpublished = _control_replacement_stopped_ledger(
        arguments.predecessor_unpublished_ledger_dir,
        arguments.predecessor_unpublished_stop_receipt,
        predecessor_manifest,
        expected_evidence_decision=str(timing.get("evidence_decision", "")),
    )
    registered_ledgers = {
        str(value.get("ledger_dir"))
        for path in epoch_paths
        for payload in [_read_json(path, "控制替代 epoch 链")]
        for controls_value in (
            payload.get("previous_controls"),
            payload.get("successor_controls"),
        )
        if isinstance(controls_value, Mapping)
        for value in [controls_value.get("upgrade_timing")]
        if isinstance(value, Mapping)
    }
    frozen_timing = predecessor_manifest.get("control_receipts", {}).get(
        "upgrade_timing"
    )
    if isinstance(frozen_timing, Mapping):
        registered_ledgers.add(str(frozen_timing.get("ledger_dir")))
    if unpublished["ledger_dir"] in registered_ledgers:
        raise ConfigurationError("控制替代所谓未发布 Ledger 已出现在 Campaign 控制链中。")

    assert isinstance(arguments.predecessor_supervisor_run_dir, Path)
    supervisor_audit = _control_replacement_supervisor_audit(
        arguments.predecessor_supervisor_run_dir
    )
    return {
        "boundary": boundary,
        "effective_epoch": epoch_binding,
        "runtime_repair": repair_binding,
        "source_campaign": {
            "campaign_dir": str(source_dir),
            "campaign_id": source_manifest["campaign_id"],
            "campaign_manifest_sha256": file_sha256(source_dir / "campaign.json"),
        },
        "source_attempt": dict(source_attempt),
        "source": dict(source),
        "effective_controls": json.loads(json.dumps(controls, ensure_ascii=False)),
        "unpublished_stop_checkpoint": unpublished,
        "supervisor_audit": supervisor_audit,
        "execution_summary": {
            "executed_job_ids": [],
            "scanned_bytes": 0,
            "live_request_count": 0,
        },
    }


def _successor_recovery_control_transition(
    arguments: argparse.Namespace,
    predecessor_dir: Path,
    successor_manifest: dict[str, Any],
) -> dict[str, Any] | None:
    """把已停线 Ledger 精确连接到新的离线恢复 P0 控制收据。"""

    names = (
        "recovery_timing_ledger_dir",
        "recovery_timing_receipt",
        "recovery_arm64_environment_root",
        "recovery_arm64_environment_receipt",
        "predecessor_stop_ledger_dir",
        "predecessor_stop_receipt",
    )
    values = {name: getattr(arguments, name, None) for name in names}
    provided = [value is not None for value in values.values()]
    if not any(provided):
        return None
    if not all(provided):
        raise ConfigurationError("后继恢复控制坐标必须六项同时提供。")
    if (
        getattr(arguments, "job_rehearsal_root", None) is None
        or getattr(arguments, "job_rehearsal_receipt", None) is None
    ):
        raise ConfigurationError("恢复控制重绑必须同时提供新的完整 Job 演练收据。")

    controls = successor_manifest.get("control_receipts")
    if not isinstance(controls, dict):
        raise ConfigurationError("前序 Formal Campaign 缺少控制收据。")
    predecessor_timing = controls.get("upgrade_timing")
    predecessor_arm = controls.get("arm64_environment")
    source_transition_binding: dict[str, str] | None = None
    if arguments.reason == "candidate_recovery_control_refresh":
        assert arguments.predecessor_candidate_id is not None
        assert arguments.predecessor_attempt_id is not None
        source_transition = getattr(
            arguments,
            "predecessor_recovery_transition",
            None,
        )
        if not isinstance(source_transition, Path):
            raise ConfigurationError(
                "控制刷新必须显式绑定已批准的前序恢复 transition。"
            )
        _, source_transition_binding, source_controls = (
            _candidate_control_refresh_source_transition(
                predecessor_dir,
                _require_formal_campaign(predecessor_dir),
                candidate_id=arguments.predecessor_candidate_id,
                attempt_id=arguments.predecessor_attempt_id,
                source=source_transition,
            )
        )
        predecessor_timing = source_controls.get("upgrade_timing")
        predecessor_arm = source_controls.get("arm64_environment")
        controls["job_rehearsal"] = source_controls.get("job_rehearsal")
    elif getattr(arguments, "predecessor_recovery_transition", None) is not None:
        raise ConfigurationError(
            "--predecessor-recovery-transition 只允许控制刷新后继使用。"
        )
    if not isinstance(predecessor_timing, dict) or not isinstance(
        predecessor_arm, dict
    ):
        raise ConfigurationError("前序 Formal Campaign 控制收据不完整。")

    stop_root = values["predecessor_stop_ledger_dir"]
    stop_path = values["predecessor_stop_receipt"]
    assert isinstance(stop_root, Path) and isinstance(stop_path, Path)
    stop_relative = _control_receipt_relative(
        stop_root,
        stop_path,
        "前序 stop_the_line checkpoint",
    )
    try:
        stop_checkpoint = codex_upgrade_timing_ledger.replay(
            stop_root,
            stop_relative,
        )
    except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
        raise ConfigurationError(f"前序停线 checkpoint 未通过：{error}") from error
    stop_summary = stop_checkpoint.get("summary")
    expected_summary = {
        "baseline_version": successor_manifest.get("baseline_version"),
        "target_version": successor_manifest.get("target_version"),
        "campaign_purpose": successor_manifest.get("campaign_purpose"),
    }
    if (
        not isinstance(stop_summary, dict)
        or stop_summary.get("status") != "stopped"
        or not _successor_stop_phase_allowed(
            arguments, stop_summary.get("active_phase")
        )
        or any(stop_summary.get(key) != value for key, value in expected_summary.items())
    ):
        raise ConfigurationError(
            "前序 checkpoint 不是当前升级在 VC-1～VC-6 的停线事实，"
            "也不满足首个 reservation 前 VC-0 控制刷新条件。"
        )
    current_stop_summary = codex_upgrade_timing_ledger.inspect_ledger(stop_root)
    if (
        current_stop_summary.get("status") != "stopped"
        or current_stop_summary.get("head_sequence")
        != stop_summary.get("head_sequence")
        or current_stop_summary.get("head_sha256") != stop_summary.get("head_sha256")
        or current_stop_summary.get("total_elapsed_seconds")
        < stop_summary.get("total_elapsed_seconds", 0)
        or current_stop_summary.get("total_live_request_count")
        != stop_summary.get("total_live_request_count")
    ):
        raise ConfigurationError("前序停线 checkpoint 不是旧 Ledger 的当前终态 head。")
    resolved_stop_root = stop_root.resolve(strict=True)
    if (
        Path(str(predecessor_timing.get("ledger_dir", ""))).resolve(strict=True)
        != resolved_stop_root
        or predecessor_timing.get("upgrade_id") != stop_summary.get("upgrade_id")
    ):
        raise ConfigurationError("前序停线 checkpoint 与 Formal Campaign 的 Ledger 不一致。")

    recovery_arguments = argparse.Namespace(
        campaign_mode="preflight_only",
        campaign_purpose=successor_manifest["campaign_purpose"],
        baseline_version=successor_manifest["baseline_version"],
        target_version=successor_manifest["target_version"],
        timing_ledger_dir=values["recovery_timing_ledger_dir"],
        timing_receipt=values["recovery_timing_receipt"],
        arm64_environment_root=values["recovery_arm64_environment_root"],
        arm64_environment_receipt=values[
            "recovery_arm64_environment_receipt"
        ],
    )
    successor_controls = _plan_control_receipts(recovery_arguments)
    successor_timing = successor_controls["upgrade_timing"]
    if (
        successor_timing["ledger_dir"] == predecessor_timing.get("ledger_dir")
        or successor_timing["upgrade_id"] == predecessor_timing.get("upgrade_id")
    ):
        raise ConfigurationError("恢复 Ledger 必须使用新的目录和 upgrade-id。")

    controls.update(successor_controls)
    stop_file = resolved_stop_root / stop_relative
    result = {
        "reason": "stopped_ledger_recovery",
        "predecessor": {
            "upgrade_timing": predecessor_timing,
            "arm64_environment": predecessor_arm,
        },
        "stop_checkpoint": {
            "ledger_dir": str(resolved_stop_root),
            "receipt": {
                "path": stop_relative,
                "sha256": file_sha256(stop_file),
                "bytes": stop_file.stat().st_size,
            },
            "upgrade_id": stop_summary["upgrade_id"],
            "active_phase": stop_summary["active_phase"],
            "head_sequence": stop_summary["head_sequence"],
            "head_sha256": stop_summary["head_sha256"],
            "total_elapsed_seconds": stop_summary["total_elapsed_seconds"],
            "total_live_request_count": stop_summary["total_live_request_count"],
        },
        "successor": successor_controls,
    }
    if source_transition_binding is not None:
        result["source_transition"] = source_transition_binding
    return result


def _assert_recovery_rehearsal_uses_successor_controls(
    arguments: argparse.Namespace,
    successor_manifest: Mapping[str, Any],
) -> tuple[Path, dict[str, Any]]:
    """确认新演练来自绑定同一恢复 Ledger 和 ARM64 收据的 preflight。"""

    rehearsal_root = arguments.job_rehearsal_root
    rehearsal_path = arguments.job_rehearsal_receipt
    assert isinstance(rehearsal_root, Path) and isinstance(rehearsal_path, Path)
    rehearsal_relative = _control_receipt_relative(
        rehearsal_root,
        rehearsal_path,
        "恢复完整 Job 离线演练收据",
    )
    try:
        rehearsal = codex_upgrade_job_rehearsal_receipt.replay(
            rehearsal_root,
            rehearsal_relative,
        )
    except (OSError, codex_upgrade_job_rehearsal_receipt.JobRehearsalReceiptError) as error:
        raise ConfigurationError(f"恢复完整 Job 演练无法重放：{error}") from error
    preflight_dir, preflight_manifest = _recovery_rehearsal_preflight_from_receipt(
        rehearsal,
        successor_manifest,
    )
    _verify_control_receipts(
        preflight_dir,
        preflight_manifest,
        require_active=True,
    )
    return preflight_dir, preflight_manifest


def _recovery_rehearsal_preflight_from_receipt(
    rehearsal: Mapping[str, Any],
    successor_manifest: Mapping[str, Any],
    *,
    require_successor_controls: bool = True,
) -> tuple[Path, dict[str, Any]]:
    """从已重放的演练收据取得并校验其 preflight 控制合同。"""

    preflight = rehearsal.get("preflight_campaign")
    if not isinstance(preflight, dict):
        raise ConfigurationError("恢复完整 Job 演练缺少 preflight Campaign。")
    preflight_dir = Path(str(preflight.get("path", "")))
    preflight_manifest_path = preflight_dir / "campaign.json"
    if (
        not preflight_dir.is_absolute()
        or not preflight_manifest_path.is_file()
        or preflight_manifest_path.is_symlink()
        or file_sha256(preflight_manifest_path) != preflight.get("manifest_sha256")
    ):
        raise ConfigurationError("恢复完整 Job 演练的 preflight Campaign 绑定非法。")
    preflight_manifest = load_campaign_manifest(preflight_dir)
    expected_controls = successor_manifest.get("control_receipts")
    actual_controls = preflight_manifest.get("control_receipts")
    if (
        preflight_manifest.get("campaign_mode") != "preflight_only"
        or preflight_manifest.get("campaign_id") != preflight.get("campaign_id")
        or any(
            preflight_manifest.get(field) != successor_manifest.get(field)
            for field in ("baseline_version", "target_version", "campaign_purpose")
        )
        or preflight_manifest.get("tool_identity")
        != successor_manifest.get("tool_identity")
        or (
            require_successor_controls
            and (
                not isinstance(expected_controls, dict)
                or not isinstance(actual_controls, dict)
                or actual_controls.get("upgrade_timing")
                != expected_controls.get("upgrade_timing")
                or actual_controls.get("arm64_environment")
                != expected_controls.get("arm64_environment")
            )
        )
    ):
        raise ConfigurationError("恢复 preflight 与后继当前控制合同不一致。")
    return preflight_dir, preflight_manifest


def _recovery_rehearsal_target_scenario_override(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    preflight_dir: Path,
    preflight_manifest: Mapping[str, Any],
) -> dict[str, Any] | None:
    """只允许当前受管场景承接 Formal 的历史规格章节摘要。"""

    target_version = str(manifest.get("target_version", ""))
    if not VERSION_RE.fullmatch(target_version):
        raise ConfigurationError("Formal target_version 非法。")

    def bound_scenario(
        root: Path,
        source_manifest: Mapping[str, Any],
        label: str,
    ) -> dict[str, Any]:
        inputs = source_manifest.get("inputs")
        reference = (
            inputs.get("target_discovery_scenarios")
            if isinstance(inputs, Mapping)
            else None
        )
        if not isinstance(reference, dict):
            raise ConfigurationError(f"{label}缺少 target 场景绑定。")
        _require_file_binding(reference, f"{label} target 场景")
        path = _campaign_file(root, reference["path"])
        if (
            path.is_symlink()
            or not path.is_file()
            or file_sha256(path) != reference["sha256"]
        ):
            raise ConfigurationError(f"{label} target 场景摘要不一致。")
        payload = _read_json(path, f"{label} target 场景")
        _validate_scenario_manifest_shape(payload)
        if payload.get("codex_version") != target_version:
            raise ConfigurationError(f"{label} target 场景版本不一致。")
        return payload

    frozen = bound_scenario(campaign_dir, manifest, "Formal")
    preflight = bound_scenario(
        preflight_dir,
        preflight_manifest,
        "恢复 preflight",
    )
    managed_path = (
        Path(__file__).resolve().parent
        / f"codex_upgrade_scenarios_{target_version.replace('.', '_')}.json"
    )
    if managed_path.is_symlink() or not managed_path.is_file():
        raise ConfigurationError("当前受管版本化 target 场景不存在或不可信。")
    managed = _read_json(managed_path, "当前受管版本化 target 场景")
    _validate_scenario_manifest_shape(managed)
    if managed.get("codex_version") != target_version or preflight != managed:
        raise ConfigurationError(
            "恢复 preflight 必须使用当前受管版本化 target 场景原文件。"
        )
    if frozen == managed:
        return None

    frozen_binding = _scenario_source_spec_binding(
        frozen,
        label="Formal 历史 target 场景",
    )
    managed_binding = _scenario_source_spec_binding(
        managed,
        label="当前受管版本化 target 场景",
    )
    source_path_text, _, fragment = managed_binding.source_spec.partition("#")
    current_source = Path(__file__).resolve().parents[2] / source_path_text
    if (
        frozen_binding.codex_version != managed_binding.codex_version
        or frozen_binding.source_spec != managed_binding.source_spec
        or current_source.is_symlink()
        or not current_source.is_file()
        or source_spec_section_sha256(current_source, fragment)
        != managed_binding.source_spec_sha256
    ):
        raise ConfigurationError("Formal 与当前场景的规格来源身份不一致。")

    normalized_frozen = json.loads(json.dumps(frozen, ensure_ascii=False))
    normalized_source = normalized_frozen.get("source_spec")
    if not isinstance(normalized_source, dict):
        raise ConfigurationError("Formal 历史 target 场景缺少 source_spec。")
    normalized_source["sha256"] = managed_binding.source_spec_sha256
    if normalized_frozen != managed:
        raise ConfigurationError(
            "Formal 历史 target 场景除 source_spec.sha256 外发生变化。"
        )
    return managed


def _successor_rehearsal_target_scenario_override(
    arguments: argparse.Namespace,
    staging_dir: Path,
    successor_manifest: Mapping[str, Any],
    *,
    reclassification_successor: bool,
    recovery_control_transition: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """让分类纠正的显式演练和恢复演练都绑定当前 preflight 场景。"""

    explicit_reclassification_rehearsal = bool(
        reclassification_successor
        and isinstance(getattr(arguments, "job_rehearsal_root", None), Path)
        and isinstance(getattr(arguments, "job_rehearsal_receipt", None), Path)
    )
    recovery_rehearsal = bool(
        recovery_control_transition is not None
        and (
            reclassification_successor
            or arguments.reason
            in {
                "candidate_recovery_control_refresh",
                "candidate_recovery_control_replacement",
            }
        )
    )
    if recovery_rehearsal:
        preflight_dir, preflight_manifest = (
            _assert_recovery_rehearsal_uses_successor_controls(
                arguments,
                successor_manifest,
            )
        )
    elif explicit_reclassification_rehearsal:
        assert isinstance(arguments.job_rehearsal_root, Path)
        assert isinstance(arguments.job_rehearsal_receipt, Path)
        preflight_dir, preflight_manifest = (
            _successor_incremental_noop_preflight_from_coordinates(
                arguments.job_rehearsal_root,
                arguments.job_rehearsal_receipt,
                successor_manifest,
                label="分类纠正后继显式 Job 演练",
            )
        )
    elif reclassification_successor:
        bound_preflight = _successor_incremental_noop_preflight(
            successor_manifest
        )
        if bound_preflight is None:
            return None
        preflight_dir, preflight_manifest = bound_preflight
    else:
        return None
    return _recovery_rehearsal_target_scenario_override(
        staging_dir,
        successor_manifest,
        preflight_dir,
        preflight_manifest,
    )


def _successor_incremental_noop_preflight(
    successor_manifest: Mapping[str, Any],
    *,
    require_active: bool = True,
    allow_stopped_metadata_only: bool = False,
) -> tuple[Path, dict[str, Any]] | None:
    """重放后继直接继承的 no-op，并返回其当前 preflight。"""

    controls = successor_manifest.get("control_receipts")
    rehearsal_control = (
        controls.get("job_rehearsal") if isinstance(controls, Mapping) else None
    )
    if not isinstance(rehearsal_control, Mapping):
        raise ConfigurationError("前序 Formal Campaign 缺少完整 Job 演练绑定。")
    root = Path(str(rehearsal_control.get("evidence_root", "")))
    receipt = rehearsal_control.get("receipt")
    receipt_path = Path(
        str(receipt.get("path", "")) if isinstance(receipt, Mapping) else ""
    )
    coordinate_kwargs: dict[str, Any] = {
        "label": "分类纠正后继继承的 Job 演练",
        "require_active": require_active,
    }
    if allow_stopped_metadata_only:
        coordinate_kwargs["allow_stopped_metadata_only"] = True
    return _successor_incremental_noop_preflight_from_coordinates(
        root,
        receipt_path,
        successor_manifest,
        **coordinate_kwargs,
    )


def _successor_incremental_noop_preflight_from_coordinates(
    root: Path,
    receipt_path: Path,
    successor_manifest: Mapping[str, Any],
    *,
    label: str,
    require_active: bool = True,
    allow_stopped_metadata_only: bool = False,
) -> tuple[Path, dict[str, Any]] | None:
    """重放 no-op 来源；不把其 Ledger/P0 误当成 successor 控制。"""

    relative = _control_receipt_relative(root, receipt_path, f"{label}收据")
    try:
        rehearsal = codex_upgrade_job_rehearsal_receipt.replay(root, relative)
    except (OSError, codex_upgrade_job_rehearsal_receipt.JobRehearsalReceiptError) as error:
        raise ConfigurationError(f"{label}无法重放：{error}") from error
    if rehearsal.get("status") != "incremental-noop":
        return None
    preflight_dir, preflight_manifest = _recovery_rehearsal_preflight_from_receipt(
        rehearsal,
        successor_manifest,
        require_successor_controls=False,
    )
    _verify_control_receipts(
        preflight_dir,
        preflight_manifest,
        require_active=require_active,
        allow_stopped_metadata_only=allow_stopped_metadata_only,
    )
    return preflight_dir, preflight_manifest


def _reject_repeated_successor_reason(
    predecessor_dir: Path,
    predecessor_manifest: Mapping[str, Any],
    reason: str,
) -> None:
    """只读小型 Campaign 清单，拒绝同一根因形成第二层后继链。"""

    current_dir = predecessor_dir.resolve()
    current: Mapping[str, Any] = predecessor_manifest
    visited = {current_dir}
    for _depth in range(64):
        binding = current.get("predecessor")
        if binding is None:
            return
        if (
            not isinstance(binding, dict)
            or set(binding)
            != {
                "campaign_dir",
                "campaign_id",
                "campaign_manifest_sha256",
                "reason",
            }
            or not isinstance(binding.get("campaign_dir"), str)
            or not SAFE_ID_RE.fullmatch(str(binding.get("campaign_id", "")))
            or not SHA256_RE.fullmatch(
                str(binding.get("campaign_manifest_sha256", ""))
            )
            or binding.get("reason") not in SUCCESSOR_REASONS
        ):
            raise ConfigurationError("前序 Campaign 链绑定非法。")
        # 官方证据复用不是失败恢复：同一份已封存官方证据可以被多次只读导入
        # （每次工具变化都需要新 Campaign），不构成「同根因第二层」。
        if binding.get("reason") == reason and reason != OFFICIAL_EVIDENCE_REUSE_REASON:
            raise ConfigurationError(
                "同一根因已经使用过一次 successor，第二层必须停线："
                f"{reason}"
            )
        next_dir = Path(str(binding.get("campaign_dir", "")))
        if (
            not next_dir.is_absolute()
            or str(next_dir.resolve()) != str(next_dir)
            or next_dir.resolve() in visited
        ):
            raise ConfigurationError("前序 Campaign 链路径不可信或形成循环。")
        manifest_path = next_dir / "campaign.json"
        if (
            manifest_path.is_symlink()
            or not manifest_path.is_file()
            or file_sha256(manifest_path)
            != binding.get("campaign_manifest_sha256")
        ):
            raise ConfigurationError("前序 Campaign 链清单摘要漂移。")
        current = _read_json(manifest_path, "前序 Campaign 链清单")
        if (
            current.get("schema_version") != CAMPAIGN_SCHEMA
            or current.get("campaign_id") != binding.get("campaign_id")
            or not SAFE_ID_RE.fullmatch(str(current.get("campaign_id", "")))
        ):
            raise ConfigurationError("前序 Campaign 链 ID 漂移。")
        _campaign_coordinates(current)
        current_dir = next_dir.resolve()
        visited.add(current_dir)
    raise ConfigurationError("前序 Campaign 链超过 64 层，拒绝继续 successor。")


def _successor_reason_ancestor(
    campaign_dir: Path,
    campaign_manifest: Mapping[str, Any],
    reason: str,
) -> dict[str, str] | None:
    """返回使用过指定原因的可信祖先后继，不重放控制或证据。"""

    current_dir = campaign_dir.resolve(strict=True)
    current: Mapping[str, Any] = campaign_manifest
    visited = {current_dir}
    for _depth in range(64):
        binding = current.get("predecessor")
        if binding is None:
            return None
        if (
            not isinstance(binding, dict)
            or set(binding)
            != {
                "campaign_dir",
                "campaign_id",
                "campaign_manifest_sha256",
                "reason",
            }
            or not isinstance(binding.get("campaign_dir"), str)
            or not SAFE_ID_RE.fullmatch(str(binding.get("campaign_id", "")))
            or not SHA256_RE.fullmatch(
                str(binding.get("campaign_manifest_sha256", ""))
            )
            or binding.get("reason") not in SUCCESSOR_REASONS
        ):
            raise ConfigurationError("前序 Campaign 链绑定非法。")
        next_dir = Path(str(binding["campaign_dir"]))
        if (
            not next_dir.is_absolute()
            or str(next_dir.resolve()) != str(next_dir)
            or next_dir.resolve() in visited
        ):
            raise ConfigurationError("前序 Campaign 链路径不可信或形成循环。")
        manifest_path = next_dir / "campaign.json"
        if (
            manifest_path.is_symlink()
            or not manifest_path.is_file()
            or file_sha256(manifest_path)
            != binding.get("campaign_manifest_sha256")
        ):
            raise ConfigurationError("前序 Campaign 链清单摘要漂移。")
        predecessor = _read_json(manifest_path, "前序 Campaign 链清单")
        if (
            predecessor.get("schema_version") != CAMPAIGN_SCHEMA
            or predecessor.get("campaign_id") != binding.get("campaign_id")
            or not SAFE_ID_RE.fullmatch(str(predecessor.get("campaign_id", "")))
        ):
            raise ConfigurationError("前序 Campaign 链 ID 漂移。")
        _campaign_coordinates(predecessor)
        if binding.get("reason") == reason:
            current_manifest_path = current_dir / "campaign.json"
            return {
                "campaign_dir": str(current_dir),
                "campaign_id": str(current.get("campaign_id", "")),
                "campaign_manifest_sha256": file_sha256(current_manifest_path),
                "reason": reason,
            }
        current_dir = next_dir.resolve()
        current = predecessor
        visited.add(current_dir)
    raise ConfigurationError("前序 Campaign 链超过 64 层，拒绝继续 control epoch。")


def _imported_stage_evaluation_transition_source(
    campaign_dir: Path,
    stage_payload: Mapping[str, Any],
    binding: Mapping[str, Any],
) -> tuple[Path, Path, dict[str, Any]]:
    """沿已验证的导入链定位 official evaluation transition 原件。

    导入阶段只投影 transition 的原始相对路径；该路径属于真正签发
    transition 的祖先 Campaign。这里只读重放最多 64 级
    predecessor-import 摘要链，不复制 transition，也不读取原始证据。
    """

    if (
        stage_payload.get("stage") != "capture-official"
        or not isinstance(stage_payload.get("predecessor_import"), Mapping)
    ):
        raise ConfigurationError("评估 transition 只能从 official 导入链解析。")
    _require_file_binding(binding, "导入 official 评估 transition")
    current_dir = campaign_dir.resolve(strict=True)
    seen: set[Path] = set()
    for _depth in range(64):
        if current_dir in seen:
            raise ConfigurationError("评估 transition 导入链形成循环。")
        seen.add(current_dir)
        manifest_path = current_dir / "campaign.json"
        stage_path = current_dir / "official" / "result.json"
        if (
            current_dir.is_symlink()
            or manifest_path.is_symlink()
            or not manifest_path.is_file()
            or stage_path.is_symlink()
            or not stage_path.is_file()
        ):
            raise ConfigurationError("评估 transition 导入链的 Campaign 不可信。")
        manifest = _read_json(manifest_path, "评估 transition 导入链 Campaign")
        local_stage = _read_json(stage_path, "评估 transition 导入链 official")
        unsigned_stage = dict(local_stage)
        package_digest = unsigned_stage.pop("package_digest", None)
        if (
            local_stage.get("stage") != "capture-official"
            or local_stage.get("campaign_id") != manifest.get("campaign_id")
            or local_stage.get("campaign_manifest_sha256")
            != file_sha256(manifest_path)
            or not SHA256_RE.fullmatch(str(package_digest))
            or package_digest != _fingerprint(unsigned_stage)
        ):
            raise ConfigurationError("评估 transition 导入链的 official 摘要非法。")
        local_binding = local_stage.get("evaluation_transition")
        if local_binding is not None:
            _require_file_binding(local_binding, "official 评估 transition 原始绑定")
            if dict(local_binding) != dict(binding):
                raise ConfigurationError("评估 transition 导入链的原始绑定漂移。")
            source = _campaign_file(current_dir, str(binding["path"]))
            if (
                source.is_symlink()
                or not source.is_file()
                or file_sha256(source) != binding["sha256"]
            ):
                raise ConfigurationError("评估 transition 导入链的原文件漂移。")
            return source, current_dir, manifest
        import_binding = local_stage.get("predecessor_import")
        _require_file_binding(import_binding, "评估 transition predecessor-import")
        _verify_predecessor_import_shallow(current_dir, manifest, local_stage)
        receipt_path = _campaign_file(current_dir, str(import_binding["path"]))
        receipt = _read_json(receipt_path, "评估 transition predecessor-import")
        predecessor = receipt.get("predecessor_campaign")
        if (
            not isinstance(predecessor, Mapping)
            or set(predecessor)
            != {"campaign_dir", "campaign_id", "campaign_manifest_sha256"}
        ):
            raise ConfigurationError("评估 transition 导入链缺少前序坐标。")
        predecessor_dir = Path(str(predecessor["campaign_dir"]))
        if not predecessor_dir.is_absolute():
            raise ConfigurationError("评估 transition 导入链前序路径非法。")
        try:
            predecessor_dir = predecessor_dir.resolve(strict=True)
        except (OSError, RuntimeError) as error:
            raise ConfigurationError("评估 transition 导入链前序不存在。") from error
        predecessor_manifest_path = predecessor_dir / "campaign.json"
        if (
            predecessor_dir.is_symlink()
            or predecessor_manifest_path.is_symlink()
            or not predecessor_manifest_path.is_file()
        ):
            raise ConfigurationError("评估 transition 导入链前序不可信。")
        predecessor_manifest = _read_json(
            predecessor_manifest_path,
            "评估 transition 导入链前序 Campaign",
        )
        if (
            predecessor_manifest.get("campaign_id") != predecessor["campaign_id"]
            or file_sha256(predecessor_manifest_path)
            != predecessor["campaign_manifest_sha256"]
        ):
            raise ConfigurationError("评估 transition 导入链前序摘要漂移。")
        current_dir = predecessor_dir
    raise ConfigurationError("评估 transition 导入链超过 64 级上限。")


def _sealed_stage_recovery_context(
    predecessor_dir: Path,
    predecessor_manifest: Mapping[str, Any],
    official: Mapping[str, Any],
    *,
    require_active: bool,
) -> dict[str, Any]:
    """读取已封存 official 阶段实际使用的恢复控制链。

    Campaign 清单不可改写，因此 official seal 之后的阶段必须显式承接
    seal 所绑定 transition 的 recovery 控制，而不能退回已经停线的 plan
    Ledger。这里只重放小型控制收据，不读取原始证据。
    """

    transition_binding = official.get("evaluation_transition")
    _require_file_binding(transition_binding, "已封存 official 评估 transition")
    transition_path = _campaign_file(
        predecessor_dir,
        str(transition_binding["path"]),
    )
    transition_origin_dir = predecessor_dir.resolve(strict=True)
    transition_origin_manifest = dict(predecessor_manifest)
    if (
        not transition_path.exists()
        and not transition_path.is_symlink()
        and isinstance(official.get("predecessor_import"), Mapping)
    ):
        (
            transition_path,
            transition_origin_dir,
            transition_origin_manifest,
        ) = _imported_stage_evaluation_transition_source(
            predecessor_dir,
            official,
            transition_binding,
        )
    if (
        transition_path.is_symlink()
        or not transition_path.is_file()
        or file_sha256(transition_path) != transition_binding["sha256"]
    ):
        raise ConfigurationError("已封存 official 评估 transition 摘要漂移。")
    transition = _read_json(transition_path, "已封存 official 评估 transition")
    unsigned = dict(transition)
    transition_digest = unsigned.pop("transition_digest", None)
    recovery_controls = transition.get("recovery_controls")
    effective_controls = (
        recovery_controls.get("recovery")
        if isinstance(recovery_controls, Mapping)
        else None
    )
    if (
        transition.get("schema_version") != TOOL_EVALUATION_TRANSITION_SCHEMA
        or transition.get("status") != "approved"
        or transition.get("phase") != "official"
        or transition.get("campaign_id")
        != transition_origin_manifest.get("campaign_id")
        or transition.get("campaign_manifest_sha256")
        != file_sha256(transition_origin_dir / "campaign.json")
        or not SHA256_RE.fullmatch(str(transition_digest))
        or _fingerprint(unsigned) != transition_digest
        or not isinstance(effective_controls, Mapping)
        or set(effective_controls)
        != {"upgrade_timing", "arm64_environment", "job_rehearsal"}
    ):
        raise ConfigurationError("已封存 official 评估 transition 控制链非法。")
    if not isinstance(official.get("evidence_manifest"), Mapping):
        raise ConfigurationError("已封存 official 阶段缺少 EvidenceManifest。")

    current_tool = _tool_identity()
    expected_tool = predecessor_manifest.get("tool_identity")
    if not isinstance(expected_tool, Mapping):
        raise ConfigurationError("前序 Campaign 缺少可分级工具身份。")
    changed = _phase_evaluation_changed_files(expected_tool, current_tool)
    allowed_paths = _SEALED_STAGE_RECOVERY_ALLOWED_FILES
    if not changed or any(item["path"] not in allowed_paths for item in changed):
        raise ConfigurationError(
            "已封存阶段控制恢复只允许评估／编排白名单内的工具变化。"
        )
    drift = _tool_identity_drift(current_tool, expected_tool)
    if set(drift["production"]) - set(_PHASE_EVALUATION_HYBRID_FILES):
        raise ConfigurationError("已封存阶段控制恢复检测到产出侧工具变化。")

    proxy_manifest = dict(predecessor_manifest)
    proxy_manifest["campaign_mode"] = "preflight_only"
    proxy_manifest["control_receipts"] = {
        "upgrade_timing": effective_controls["upgrade_timing"],
        "arm64_environment": effective_controls["arm64_environment"],
    }
    _verify_control_receipts(
        predecessor_dir,
        proxy_manifest,
        require_active=require_active,
        _control_override=proxy_manifest["control_receipts"],
    )
    official_path = _stage_path(predecessor_dir, "capture-official")[1]
    return {
        "effective_controls": json.loads(
            json.dumps(effective_controls, ensure_ascii=False)
        ),
        "evaluation_transition": {
            "path": str(transition_binding["path"]),
            "sha256": str(transition_binding["sha256"]),
        },
        "source_stage": {
            "path": official_path.relative_to(predecessor_dir).as_posix(),
            "sha256": file_sha256(official_path),
            "package_digest": official["package_digest"],
        },
    }


def _sealed_stage_timing_checkpoint(
    control: Mapping[str, Any],
    *,
    label: str,
) -> tuple[Path, dict[str, Any]]:
    """重放已封存阶段控制中的 Ledger checkpoint。"""

    expected_fields = {
        "ledger_dir",
        "ledger_plan_sha256",
        "receipt",
        "upgrade_id",
        "evidence_decision",
        "checkpoint_head_sha256",
    }
    receipt = control.get("receipt")
    if (
        set(control) != expected_fields
        or not isinstance(receipt, Mapping)
        or set(receipt) != {"path", "sha256", "bytes"}
    ):
        raise ConfigurationError(f"{label} Ledger 控制字段不闭合。")
    root = Path(str(control.get("ledger_dir", "")))
    relative = str(receipt.get("path", ""))
    digest = receipt.get("sha256")
    size = receipt.get("bytes")
    if (
        not root.is_absolute()
        or str(root.resolve(strict=True)) != str(root)
        or not relative
        or not SHA256_RE.fullmatch(str(digest))
        or isinstance(size, bool)
        or not isinstance(size, int)
        or size <= 0
    ):
        raise ConfigurationError(f"{label} Ledger 控制坐标非法。")
    receipt_relative = _control_receipt_relative(
        root,
        root / relative,
        f"{label} Ledger checkpoint",
    )
    receipt_path = root / receipt_relative
    if (
        file_sha256(root / "ledger.json")
        != control.get("ledger_plan_sha256")
        or file_sha256(receipt_path) != digest
        or receipt_path.stat().st_size != size
    ):
        raise ConfigurationError(f"{label} Ledger 控制摘要漂移。")
    try:
        checkpoint = codex_upgrade_timing_ledger.replay(root, receipt_relative)
    except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
        raise ConfigurationError(f"{label} Ledger checkpoint 未通过：{error}") from error
    summary = checkpoint.get("summary")
    if (
        not isinstance(summary, dict)
        or summary.get("upgrade_id") != control.get("upgrade_id")
        or summary.get("evidence_decision") != control.get("evidence_decision")
        or summary.get("head_sha256")
        != control.get("checkpoint_head_sha256")
    ):
        raise ConfigurationError(f"{label} Ledger checkpoint 身份漂移。")
    return root, checkpoint


def _assert_sealed_stage_checkpoint_progression(
    predecessor_timing: Mapping[str, Any],
    successor_timing: Mapping[str, Any],
    predecessor_arm: Mapping[str, Any],
    successor_arm: Mapping[str, Any],
    *,
    baseline_version: str,
    target_version: str,
    campaign_purpose: str,
    require_current_head: bool,
) -> None:
    """只允许同一 Ledger 从封存 checkpoint 单调前进到当前 VC-2。"""

    if predecessor_arm != successor_arm:
        raise ConfigurationError("已封存阶段控制恢复必须逐字沿用原 ARM64 P0。")
    invariant_fields = (
        "ledger_dir",
        "ledger_plan_sha256",
        "upgrade_id",
        "evidence_decision",
    )
    if any(
        predecessor_timing.get(field) != successor_timing.get(field)
        for field in invariant_fields
    ):
        raise ConfigurationError(
            "已封存阶段控制恢复必须沿用同一 Ledger、upgrade-id、计划和证据决定。"
        )
    predecessor_root, predecessor_checkpoint = _sealed_stage_timing_checkpoint(
        predecessor_timing,
        label="封存 transition",
    )
    successor_root, successor_checkpoint = _sealed_stage_timing_checkpoint(
        successor_timing,
        label="当前 active",
    )
    if predecessor_root != successor_root:
        raise ConfigurationError("已封存阶段控制恢复不得切换 Ledger 目录。")
    predecessor_summary = predecessor_checkpoint["summary"]
    successor_summary = successor_checkpoint["summary"]
    expected_identity = {
        "baseline_version": baseline_version,
        "target_version": target_version,
        "campaign_purpose": campaign_purpose,
    }
    if any(
        predecessor_summary.get(field) != value
        or successor_summary.get(field) != value
        for field, value in expected_identity.items()
    ):
        raise ConfigurationError("已封存阶段控制恢复的 Ledger 版本或用途漂移。")
    predecessor_phase = predecessor_summary.get("active_phase")
    successor_phase = successor_summary.get("active_phase")
    phase_order = codex_upgrade_timing_ledger.PHASE_ORDER
    if (
        predecessor_summary.get("status") != "active"
        or successor_summary.get("status") != "active"
        or predecessor_phase not in phase_order
        or successor_phase != "VC-2"
        or phase_order.index(str(successor_phase))
        < phase_order.index(str(predecessor_phase))
        or successor_summary.get("head_sequence", 0)
        <= predecessor_summary.get("head_sequence", 0)
        or successor_summary.get("total_elapsed_seconds", -1)
        < predecessor_summary.get("total_elapsed_seconds", 0)
        or successor_summary.get("total_live_request_count")
        != predecessor_summary.get("total_live_request_count")
    ):
        raise ConfigurationError(
            "已封存阶段控制恢复必须从封存 checkpoint 单调前进到 VC-2，"
            "且不得增加 live 请求。"
        )
    if require_current_head:
        try:
            current = codex_upgrade_timing_ledger.assert_usable(
                successor_root,
                str(successor_timing["receipt"]["path"]),
                baseline_version=baseline_version,
                target_version=target_version,
                campaign_purpose=campaign_purpose,
                required_phase="VC-2",
            )
        except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
            raise ConfigurationError(
                f"当前 VC-2 Ledger checkpoint 未通过：{error}"
            ) from error
        if (
            current.get("head_sequence") != successor_summary.get("head_sequence")
            or current.get("head_sha256") != successor_summary.get("head_sha256")
            or current.get("total_live_request_count")
            != successor_summary.get("total_live_request_count")
        ):
            raise ConfigurationError("提供的 VC-2 checkpoint 不是 Ledger 当前 head。")


def _sealed_stage_active_controls(
    arguments: argparse.Namespace,
    successor_manifest: dict[str, Any],
    effective_controls: Mapping[str, Any],
) -> None:
    """用显式当前 checkpoint 更新后继，但保持同一 Ledger 与原 P0。"""

    names = (
        "active_timing_ledger_dir",
        "active_timing_receipt",
        "active_arm64_environment_root",
        "active_arm64_environment_receipt",
    )
    values = {name: getattr(arguments, name, None) for name in names}
    if not all(isinstance(value, Path) for value in values.values()):
        raise ConfigurationError(
            "已封存阶段控制恢复必须显式提供当前 VC-2 Ledger checkpoint "
            "和原 ARM64 P0 四项坐标。"
        )
    current_arguments = argparse.Namespace(
        campaign_mode="preflight_only",
        campaign_purpose=successor_manifest["campaign_purpose"],
        baseline_version=successor_manifest["baseline_version"],
        target_version=successor_manifest["target_version"],
        timing_ledger_dir=values["active_timing_ledger_dir"],
        timing_receipt=values["active_timing_receipt"],
        arm64_environment_root=values["active_arm64_environment_root"],
        arm64_environment_receipt=values[
            "active_arm64_environment_receipt"
        ],
    )
    current_controls = _plan_control_receipts(current_arguments)
    predecessor_timing = effective_controls.get("upgrade_timing")
    predecessor_arm = effective_controls.get("arm64_environment")
    if not isinstance(predecessor_timing, Mapping) or not isinstance(
        predecessor_arm, Mapping
    ):
        raise ConfigurationError("封存 transition 缺少有效 Ledger 或 ARM64 P0。")
    _assert_sealed_stage_checkpoint_progression(
        predecessor_timing,
        current_controls["upgrade_timing"],
        predecessor_arm,
        current_controls["arm64_environment"],
        baseline_version=str(successor_manifest["baseline_version"]),
        target_version=str(successor_manifest["target_version"]),
        campaign_purpose=str(successor_manifest["campaign_purpose"]),
        require_current_head=True,
    )
    controls = successor_manifest.get("control_receipts")
    if not isinstance(controls, dict):
        raise ConfigurationError("后继 Campaign 缺少控制收据。")
    controls.update(current_controls)


def _sealed_stage_control_mode(arguments: argparse.Namespace) -> str:
    """要求已封存阶段恢复只选择一套完整控制坐标。"""

    active_names = (
        "active_timing_ledger_dir",
        "active_timing_receipt",
        "active_arm64_environment_root",
        "active_arm64_environment_receipt",
    )
    stopped_names = (
        "recovery_timing_ledger_dir",
        "recovery_timing_receipt",
        "recovery_arm64_environment_root",
        "recovery_arm64_environment_receipt",
        "predecessor_stop_ledger_dir",
        "predecessor_stop_receipt",
    )
    active_values = [getattr(arguments, name, None) for name in active_names]
    stopped_values = [getattr(arguments, name, None) for name in stopped_names]
    active_any = any(value is not None for value in active_values)
    stopped_any = any(value is not None for value in stopped_values)
    if active_any and stopped_any:
        raise ConfigurationError(
            "已封存阶段控制恢复的 active 与 stopped 控制坐标不得混用。"
        )
    if active_any:
        if not all(isinstance(value, Path) for value in active_values):
            raise ConfigurationError(
                "已封存阶段 active 恢复必须完整提供 Ledger checkpoint 和原 ARM64 P0 四项坐标。"
            )
        return "active"
    if stopped_any:
        if not all(isinstance(value, Path) for value in stopped_values):
            raise ConfigurationError(
                "已封存阶段 stopped 恢复必须完整提供旧停线 checkpoint、新 Ledger 和新 ARM64 P0 六项坐标。"
            )
        return "stopped"
    raise ConfigurationError(
        "已封存阶段控制恢复必须选择 active 四项坐标或 stopped 六项坐标。"
    )


def _assert_sealed_stage_stopped_recovery(
    recovery_transition: Mapping[str, Any],
    successor_manifest: Mapping[str, Any],
) -> None:
    """确认新 Ledger 位于当前 VC-2 head，且没有产生新的 live 请求。"""

    controls = successor_manifest.get("control_receipts")
    successor_timing = (
        controls.get("upgrade_timing") if isinstance(controls, Mapping) else None
    )
    if not isinstance(successor_timing, Mapping):
        raise ConfigurationError("已封存阶段 stopped 恢复缺少新 Ledger 控制。")
    successor_root, checkpoint = _sealed_stage_timing_checkpoint(
        successor_timing,
        label="已封存阶段 stopped 恢复",
    )
    summary = checkpoint["summary"]
    current = codex_upgrade_timing_ledger.inspect_ledger(successor_root)
    if (
        recovery_transition.get("reason") != "stopped_ledger_recovery"
        or summary.get("status") != "active"
        or summary.get("active_phase") != "VC-2"
        or summary.get("total_live_request_count") != 0
        or current.get("status") != "active"
        or current.get("active_phase") != "VC-2"
        or current.get("head_sequence") != summary.get("head_sequence")
        or current.get("head_sha256") != summary.get("head_sha256")
        or current.get("total_live_request_count") != 0
    ):
        raise ConfigurationError(
            "已封存阶段 stopped 恢复的新 Ledger 必须是当前 VC-2 head，且 live 请求数为 0。"
        )


def create_successor_campaign(arguments: argparse.Namespace) -> dict[str, Any]:
    """创建同版本后继 Campaign，并按原因选择承接边界。

    普通运行时纠正会承接官方阶段和批准分类；若现有批准事实与原始官方
    证据冲突，分类纠正后继只承接官方阶段，并要求在新 Campaign 内重新
    生成、审核和批准五件套。两种模式都不会复制或改写历史 attempt。
    """

    predecessor_dir = arguments.predecessor_campaign_dir
    successor_dir = arguments.campaign_dir
    _validate_existing_campaign_path(predecessor_dir)
    _validate_output_path(successor_dir)
    if predecessor_dir.resolve() == successor_dir.resolve(strict=False):
        raise ConfigurationError("后继 Campaign 目录不得等于前序 Campaign。")
    if not SAFE_ID_RE.fullmatch(str(arguments.campaign_id)):
        raise ConfigurationError("--campaign-id 格式非法。")
    if arguments.codex_account_id <= 0:
        raise ConfigurationError("--codex-account-id 必须为正整数。")
    if arguments.reason not in SUCCESSOR_REASONS:
        raise ConfigurationError("--reason 不是受管的同版本后继原因。")
    control_replacement_successor = (
        arguments.reason == "candidate_recovery_control_replacement"
    )
    failed_job_tool_recovery = arguments.reason in {
        "candidate_failed_job_tool_recovery",
        "candidate_recovery_control_refresh",
        "candidate_recovery_control_replacement",
    }
    if failed_job_tool_recovery:
        required = (
            arguments.predecessor_candidate_id,
            arguments.predecessor_attempt_id,
            arguments.job_rehearsal_root,
            arguments.job_rehearsal_receipt,
            arguments.recovery_timing_ledger_dir,
            arguments.recovery_timing_receipt,
            arguments.recovery_arm64_environment_root,
            arguments.recovery_arm64_environment_receipt,
            arguments.predecessor_stop_ledger_dir,
            arguments.predecessor_stop_receipt,
        )
        if not all(value is not None for value in required):
            raise ConfigurationError(
                "Candidate 失败闭集恢复必须同时绑定前序失败 attempt、"
                "旧停线 checkpoint、新 Ledger／P0 和当前闭集演练收据。"
            )
        if (
            arguments.reason == "candidate_recovery_control_refresh"
            and arguments.predecessor_recovery_transition is None
        ):
            raise ConfigurationError(
                "控制刷新必须同时绑定前序已批准恢复 transition。"
            )
        if (
            arguments.reason != "candidate_recovery_control_refresh"
            and arguments.predecessor_recovery_transition is not None
        ):
            raise ConfigurationError(
                "前序恢复 transition 只允许控制刷新后继使用。"
            )
        replacement_paths = (
            arguments.predecessor_control_epoch,
            arguments.predecessor_unpublished_ledger_dir,
            arguments.predecessor_unpublished_stop_receipt,
            arguments.predecessor_supervisor_run_dir,
        )
        if control_replacement_successor and not all(
            isinstance(value, Path) for value in replacement_paths
        ):
            raise ConfigurationError(
                "零执行控制替代必须绑定有效 epoch、未发布停线 Ledger 和父监督器终态。"
            )
        if (
            arguments.live_attestation_compose_dir is not None
            or bool(str(arguments.live_attestation_compose_files or "").strip())
            or arguments.target_scenario_manifest is not None
        ):
            raise ConfigurationError(
                "Candidate 失败闭集恢复不得改变 compose 或 target 场景。"
            )
    replacement_argument_names = (
        "predecessor_control_epoch",
        "predecessor_control_runtime_repair",
        "predecessor_unpublished_ledger_dir",
        "predecessor_unpublished_stop_receipt",
        "predecessor_supervisor_run_dir",
    )
    if not control_replacement_successor and any(
        getattr(arguments, name, None) is not None
        for name in replacement_argument_names
    ):
        raise ConfigurationError("控制替代审计参数只允许零执行控制替代后继使用。")
    reclassification_successor = (
        arguments.reason in RECLASSIFICATION_SUCCESSOR_REASONS
    )
    sealed_stage_recovery_successor = (
        arguments.reason in SEALED_STAGE_RECOVERY_SUCCESSOR_REASONS
    )
    sealed_stage_control_mode = (
        _sealed_stage_control_mode(arguments)
        if sealed_stage_recovery_successor
        else None
    )
    official_only_successor = (
        reclassification_successor or sealed_stage_recovery_successor
    )
    active_control_names = (
        "active_timing_ledger_dir",
        "active_timing_receipt",
        "active_arm64_environment_root",
        "active_arm64_environment_receipt",
    )
    if not sealed_stage_recovery_successor and any(
        getattr(arguments, name, None) is not None
        for name in active_control_names
    ):
        raise ConfigurationError(
            "当前 active checkpoint 参数只允许 sealed_stage_control_recovery 使用。"
        )

    predecessor_manifest = _require_formal_campaign(
        predecessor_dir,
        load_campaign_manifest(
            predecessor_dir,
            _control_epoch_bootstrap=control_replacement_successor,
        ),
    )
    _reject_repeated_successor_reason(
        predecessor_dir,
        predecessor_manifest,
        arguments.reason,
    )
    predecessor_configuration = predecessor_manifest.get("configuration")
    if not isinstance(predecessor_configuration, dict):
        raise ConfigurationError("前序 Campaign 的运行配置不是对象。")
    predecessor_account_id = predecessor_configuration.get("codex_account_id")
    if (
        isinstance(predecessor_account_id, bool)
        or not isinstance(predecessor_account_id, int)
        or predecessor_account_id <= 0
    ):
        raise ConfigurationError("前序 Campaign 的 Codex 账号坐标非法。")
    if arguments.campaign_id == predecessor_manifest["campaign_id"]:
        raise ConfigurationError("后继 Campaign 必须使用新的 campaign-id。")
    runtime_configuration = _successor_runtime_configuration(
        arguments,
        predecessor_configuration,
    )
    # 后继承接只重放前序阶段封印、证据 inventory/security 与批准清单。
    # 历史机器收据绑定的是当时 finalizer 的绝对路径和摘要；用当前 finalizer
    # 强行重放会把合法的只读历史路径迁移误判为篡改。当前后继不会借用这些
    # 收据生成新事实，因此保留阶段级逐字节校验，但不重新绑定历史 finalizer。
    official = _load_stage_result(
        predecessor_dir,
        "capture-official",
        _replay_machine_receipts=False,
        _historical_manifest_controls=control_replacement_successor,
    )
    if official.get("status") != "complete":
        raise ConfigurationError("前序 Campaign 官方阶段尚未完整封存。")
    classification: dict[str, Any] | None = None
    sealed_stage_context: dict[str, Any] | None = None
    if sealed_stage_recovery_successor:
        if (predecessor_dir / "classification" / "result.json").exists():
            raise ConfigurationError("已封存阶段控制恢复要求前序尚未产生分类结果。")
        predecessor_status = campaign_status(predecessor_dir)
        if predecessor_status.get("status") != "official_sealed":
            raise ConfigurationError(
                "已封存阶段控制恢复只允许从 official_sealed 状态执行。"
            )
        if (
            arguments.job_rehearsal_root is None
            or arguments.job_rehearsal_receipt is None
        ):
            raise ConfigurationError(
                "已封存阶段控制恢复必须绑定当前工具生成的完整 Job 演练收据。"
            )
        sealed_stage_context = _sealed_stage_recovery_context(
            predecessor_dir,
            predecessor_manifest,
            official,
            require_active=sealed_stage_control_mode == "active",
        )
    else:
        classification_result_path = predecessor_dir / "classification" / "result.json"
        if (
            arguments.reason == OFFICIAL_EVIDENCE_REUSE_REASON
            and not classification_result_path.exists()
            and not classification_result_path.is_symlink()
        ):
            # 官方证据复用允许前序停在 official_sealed（例如上一次复用后尚未分类，
            # 或分类前又发生了工具变化）：没有分类结果就不承接分类事实，
            # 新 Campaign 从 classify 开始。
            classification = None
        else:
            classification = _load_stage_result(
                predecessor_dir,
                "classify",
                _historical_manifest_controls=control_replacement_successor,
            )
            if (
                classification.get("status") != "complete"
                or classification.get("migration", {}).get("unclassified_count") != 0
            ):
                raise ConfigurationError("前序 Campaign 分类未完整批准或仍有阻断。")
    control_replacement_context = (
        _control_replacement_context(
            arguments,
            predecessor_dir,
            predecessor_manifest,
        )
        if control_replacement_successor
        else None
    )
    abandoned_attempt = (
        dict(control_replacement_context["source_attempt"])
        if control_replacement_context is not None
        else _successor_abandoned_attempt(
            predecessor_dir,
            arguments.predecessor_candidate_id,
            arguments.predecessor_attempt_id,
        )
    )

    if successor_dir.parent.exists():
        if successor_dir.parent.is_symlink() or not successor_dir.parent.is_dir():
            raise ConfigurationError("后继 Campaign 的父目录不可信。")
    else:
        ensure_private_directory(successor_dir.parent)
    staging_dir = Path(
        tempfile.mkdtemp(
            prefix=f".{successor_dir.name}.successor-",
            dir=successor_dir.parent,
        )
    )
    staging_dir.chmod(0o700)
    published = False
    try:
        copied_files: dict[str, dict[str, Any]] = {}
        for group_name in ("inputs", "analysis"):
            for field, reference in predecessor_manifest[group_name].items():
                if reference is None:
                    continue
                if (
                    group_name == "inputs"
                    and field == "target_discovery_scenarios"
                    and getattr(arguments, "target_scenario_manifest", None)
                    is not None
                ):
                    continue
                _copy_successor_binding(
                    predecessor_dir,
                    staging_dir,
                    reference,
                    kind=f"plan_{group_name}",
                    copied_files=copied_files,
                )

        target_scenario_transition = _successor_target_scenario_transition(
            arguments,
            predecessor_dir,
            staging_dir,
            predecessor_manifest,
            copied_files,
        )

        classification_bindings: dict[str, dict[str, str]] = {}
        if not official_only_successor:
            assert classification is not None
            for field in _CLASSIFICATION_APPROVAL_FIELDS:
                classification_bindings[field] = _copy_successor_binding(
                    predecessor_dir,
                    staging_dir,
                    classification.get(field),
                    kind="approved_classification",
                    copied_files=copied_files,
                )
        surface_binding = _copy_successor_binding(
            predecessor_dir,
            staging_dir,
            official.get("surface"),
            kind="official_surface",
            copied_files=copied_files,
            target_relative=_SUCCESSOR_OFFICIAL_SURFACE_PATH,
        )

        predecessor_manifest_sha256 = file_sha256(
            predecessor_dir / "campaign.json"
        )
        successor_manifest = json.loads(
            json.dumps(predecessor_manifest, ensure_ascii=False)
        )
        successor_manifest["configuration"]["codex_account_id"] = (
            arguments.codex_account_id
        )
        if runtime_configuration is not None:
            successor_manifest["configuration"].update(runtime_configuration)
        if target_scenario_transition is not None:
            successor_manifest["inputs"]["target_discovery_scenarios"] = (
                target_scenario_transition["successor"]
            )
        successor_manifest.update(
            {
                "campaign_id": arguments.campaign_id,
                "created_at_utc": _utc_now(),
                "tool_identity": _tool_identity(),
                "predecessor": {
                    "campaign_dir": str(predecessor_dir.resolve()),
                    "campaign_id": predecessor_manifest["campaign_id"],
                    "campaign_manifest_sha256": predecessor_manifest_sha256,
                    "reason": arguments.reason,
                },
            }
        )
        if control_replacement_context is not None:
            successor_manifest["control_receipts"] = json.loads(
                json.dumps(
                    control_replacement_context["effective_controls"],
                    ensure_ascii=False,
                )
            )
        if sealed_stage_context is not None:
            successor_manifest["control_receipts"] = json.loads(
                json.dumps(
                    sealed_stage_context["effective_controls"],
                    ensure_ascii=False,
                )
            )
            if sealed_stage_control_mode == "active":
                _sealed_stage_active_controls(
                    arguments,
                    successor_manifest,
                    sealed_stage_context["effective_controls"],
                )
        if official_only_successor:
            scenario_reference = successor_manifest["inputs"].get(
                "target_discovery_scenarios"
            )
            if not isinstance(scenario_reference, dict):
                raise ConfigurationError(
                    "分类纠正后继缺少冻结 target 场景清单。"
                )
            _require_file_binding(
                scenario_reference,
                "分类纠正后继 target 场景清单",
            )
            scenario_path = _campaign_file(
                staging_dir,
                scenario_reference["path"],
            )
            if (
                scenario_path.is_symlink()
                or not scenario_path.is_file()
                or file_sha256(scenario_path) != scenario_reference["sha256"]
            ):
                raise ConfigurationError(
                    "分类纠正后继 target 场景清单摘要不一致。"
                )
            frozen_scenario = _read_json(
                scenario_path,
                "分类纠正后继 target 场景清单",
            )
            _validate_scenario_manifest_shape(frozen_scenario)
            if frozen_scenario.get("codex_version") != successor_manifest.get(
                "target_version"
            ):
                raise ConfigurationError(
                    "分类纠正后继 target 场景版本不一致。"
                )
            historical_source_spec_binding = _scenario_source_spec_binding(
                frozen_scenario,
                label="分类纠正后继 target 场景清单",
            )
        else:
            historical_source_spec_binding = (
                _successor_uses_reclassified_historical_plan_binding(
                    staging_dir,
                    successor_manifest,
                    classification_bindings,
                )
            )
        rehearsal_scenario_override: Mapping[str, Any] | None = None
        if historical_source_spec_binding is not None and not official_only_successor:
            assert classification is not None
            approved_scenario_reference = classification_bindings[
                "scenario_manifest"
            ]
            rehearsal_scenario_override = _read_json(
                _campaign_file(
                    staging_dir,
                    approved_scenario_reference["path"],
                ),
                "后继 Campaign 当前批准场景",
            )
        recovery_control_transition = _successor_recovery_control_transition(
            arguments,
            predecessor_dir,
            successor_manifest,
        )
        if sealed_stage_control_mode == "active" and recovery_control_transition is not None:
            raise ConfigurationError("已封存阶段 active 恢复不得重绑 stopped 控制。")
        if sealed_stage_control_mode == "stopped":
            if recovery_control_transition is None:
                raise ConfigurationError("已封存阶段 stopped 恢复缺少控制过渡。")
            _assert_sealed_stage_stopped_recovery(
                recovery_control_transition,
                successor_manifest,
            )
        # 分类事实纠正后继可能继续承接历史 Formal 的 target 场景字节，
        # 但恢复 preflight 必须使用当前受管场景。两者只要存在合法的
        # source_spec 摘要差异，完整 Job 演练合同就应以恢复 preflight
        # 的当前场景重算；否则会把同一组 Job 错误判成工具／合同漂移。
        recovery_scenario_override = (
            _successor_rehearsal_target_scenario_override(
                arguments,
                staging_dir,
                successor_manifest,
                reclassification_successor=reclassification_successor,
                recovery_control_transition=recovery_control_transition,
            )
        )
        if recovery_scenario_override is not None:
            rehearsal_scenario_override = recovery_scenario_override
        if failed_job_tool_recovery:
            _assert_recovery_rehearsal_uses_successor_controls(
                arguments,
                successor_manifest,
            )
        if sealed_stage_recovery_successor:
            _assert_recovery_rehearsal_uses_successor_controls(
                arguments,
                successor_manifest,
            )
        job_rehearsal_transition = _successor_job_rehearsal_transition(
            arguments,
            staging_dir,
            successor_manifest,
            target_scenario_override=rehearsal_scenario_override,
        )
        if failed_job_tool_recovery and not control_replacement_successor:
            assert arguments.predecessor_candidate_id is not None
            assert arguments.predecessor_attempt_id is not None
            _validate_failed_job_tool_recovery_source(
                predecessor_dir,
                predecessor_manifest,
                successor_manifest,
                candidate_id=arguments.predecessor_candidate_id,
                attempt_id=arguments.predecessor_attempt_id,
                reason=arguments.reason,
            )
        if sealed_stage_recovery_successor and job_rehearsal_transition is None:
            raise ConfigurationError("已封存阶段控制恢复没有形成新的 Job 演练绑定。")
        _rebuild_successor_plan(
            staging_dir,
            successor_dir,
            successor_manifest,
            historical_source_spec_binding=historical_source_spec_binding,
        )
        manifest_path = staging_dir / "campaign.json"
        _secure_write_json_once(manifest_path, successor_manifest)
        secure_write_text(
            staging_dir / "campaign.sha256", file_sha256(manifest_path) + "\n"
        )

        official_path = _stage_path(
            predecessor_dir, "capture-official"
        )[1]
        classification_path = (
            _stage_path(predecessor_dir, "classify")[1]
            if classification is not None
            else None
        )
        import_receipt: dict[str, Any] = {
            "schema_version": (
                PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA
                if control_replacement_successor
                else (
                    PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA
                    if target_scenario_transition is not None
                    else (
                        PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMA
                        if sealed_stage_recovery_successor
                        else (
                            PREDECESSOR_RECOVERY_IMPORT_SCHEMA
                            if recovery_control_transition is not None
                            else (
                                PREDECESSOR_REHEARSAL_IMPORT_SCHEMA
                                if job_rehearsal_transition is not None
                                else (
                                    PREDECESSOR_RECLASSIFICATION_IMPORT_SCHEMA
                                    if reclassification_successor
                                    else (
                                        PREDECESSOR_RUNTIME_IMPORT_SCHEMA
                                        if runtime_configuration is not None
                                        else PREDECESSOR_IMPORT_SCHEMA
                                    )
                                )
                            )
                        )
                    )
                )
            ),
            "created_at_utc": _utc_now(),
            "reason": arguments.reason,
            "successor_campaign_id": arguments.campaign_id,
            "successor_campaign_manifest_sha256": file_sha256(manifest_path),
            "predecessor_campaign": {
                "campaign_dir": str(predecessor_dir.resolve()),
                "campaign_id": predecessor_manifest["campaign_id"],
                "campaign_manifest_sha256": predecessor_manifest_sha256,
            },
            "stages": {
                "capture-official": {
                    "path": official_path.relative_to(predecessor_dir).as_posix(),
                    "sha256": file_sha256(official_path),
                    "package_digest": official["package_digest"],
                    "evidence_inventory_digest": official[
                        "evidence_inventory"
                    ]["digest"],
                    "security_sha256": _fingerprint(official["security"]),
                },
            },
            "copied_files": sorted(
                copied_files.values(), key=lambda item: item["target_path"]
            ),
            "configuration_transition": {
                "codex_account_id": {
                    "predecessor": predecessor_account_id,
                    "successor": arguments.codex_account_id,
                    "reason": "operator_selected_active_account",
                }
            },
            "abandoned_candidate_attempt": abandoned_attempt,
        }
        if classification is not None and classification_path is not None:
            import_receipt["stages"]["classify"] = {
                "path": classification_path.relative_to(
                    predecessor_dir
                ).as_posix(),
                "sha256": file_sha256(classification_path),
                "package_digest": classification["package_digest"],
                "joint_manifest_sha256": classification[
                    "joint_manifest_sha256"
                ],
            }
        if job_rehearsal_transition is not None:
            import_receipt["job_rehearsal_transition"] = (
                job_rehearsal_transition
            )
        if target_scenario_transition is not None:
            import_receipt["target_scenario_transition"] = (
                target_scenario_transition
            )
        if recovery_control_transition is not None:
            import_receipt["recovery_control_transition"] = (
                recovery_control_transition
            )
        if control_replacement_context is not None:
            import_receipt["control_replacement"] = control_replacement_context
        if sealed_stage_context is not None:
            import_receipt["stage_control_transition"] = {
                "reason": "sealed_stage_control_recovery",
                "source_stage": sealed_stage_context["source_stage"],
                "evaluation_transition": sealed_stage_context[
                    "evaluation_transition"
                ],
                "predecessor": sealed_stage_context["effective_controls"],
                "successor": successor_manifest["control_receipts"],
            }
            import_receipt["execution_summary"] = {
                "executed_job_ids": [],
                "scanned_bytes": 0,
                "live_request_count": 0,
            }
        if runtime_configuration is not None:
            import_receipt["configuration_transition"].update(
                {
                    field: {
                        "predecessor": str(
                            predecessor_configuration.get(field, "") or ""
                        ),
                        "successor": value,
                        "reason": "candidate_runtime_identity_correction",
                    }
                    for field, value in runtime_configuration.items()
                }
            )
        if reclassification_successor:
            import_receipt["import_mode"] = "official_only_reclassification"
        elif sealed_stage_recovery_successor:
            import_receipt["import_mode"] = (
                "official_only_sealed_stage_control_recovery"
            )
        import_receipt["receipt_digest"] = _fingerprint(import_receipt)
        import_path = staging_dir / "predecessor-import.json"
        _secure_write_json_once(import_path, import_receipt)
        import_binding = {
            "path": import_path.relative_to(staging_dir).as_posix(),
            "sha256": file_sha256(import_path),
        }

        save_stage_result(
            staging_dir,
            "capture-official",
            {
                "status": "complete",
                "predecessor_import": import_binding,
                "predecessor_package_digest": official["package_digest"],
                "surface": surface_binding,
            },
            _successor_manifest=successor_manifest,
        )
        if not official_only_successor:
            assert classification is not None
            imported_classification = {
                "status": "complete",
                "predecessor_import": import_binding,
                "predecessor_package_digest": classification["package_digest"],
                **classification_bindings,
            }
            for field in (
                "joint_manifest_sha256",
                "baseline_rule_count",
                "target_rule_count",
                "migration",
                "source_diff_sha256",
                "official_diff_sha256",
            ):
                imported_classification[field] = classification[field]
            save_stage_result(
                staging_dir,
                "classify",
                imported_classification,
                _successor_manifest=successor_manifest,
            )

        if successor_dir.exists():
            raise ConfigurationError("后继 Campaign 目录在发布前已被占用。")
        os.rename(staging_dir, successor_dir)
        published = True
    finally:
        if not published:
            shutil.rmtree(staging_dir, ignore_errors=True)

    status = campaign_status(successor_dir)
    return {
        "status": status["status"],
        "campaign_id": arguments.campaign_id,
        "campaign_dir": str(successor_dir),
        "predecessor_campaign_id": predecessor_manifest["campaign_id"],
        "predecessor_campaign_dir": str(predecessor_dir.resolve()),
        "reason": arguments.reason,
        "official_imported": True,
        "classification_imported": not official_only_successor,
        "classification_reapproval_required": reclassification_successor,
        "sealed_stage_control_recovered": sealed_stage_recovery_successor,
        "control_replaced": control_replacement_successor,
        "executed_job_count": (
            0
            if sealed_stage_recovery_successor or control_replacement_successor
            else None
        ),
        "scanned_bytes": (
            0
            if sealed_stage_recovery_successor or control_replacement_successor
            else None
        ),
        "live_request_count": (
            0
            if sealed_stage_recovery_successor or control_replacement_successor
            else None
        ),
        "official_recapture_required": False,
        "codex_account_id": arguments.codex_account_id,
        "runtime_configuration_rebound": runtime_configuration is not None,
        "target_scenario_rebound": target_scenario_transition is not None,
        "job_rehearsal_rebound": job_rehearsal_transition is not None,
        "recovery_controls_rebound": recovery_control_transition is not None,
        "next_command": status["next_command"],
    }


def load_campaign_manifest(
    path: Path,
    *,
    _control_epoch_bootstrap: bool = False,
    _skip_control_validation: bool = False,
) -> dict[str, Any]:
    """加载 Campaign，并验证核心清单及其计划期输入未被改写。"""

    campaign_dir = path.parent if path.name == "campaign.json" else path
    _validate_existing_campaign_path(campaign_dir)
    manifest_path = campaign_dir / "campaign.json"
    digest_path = campaign_dir / "campaign.sha256"
    if not manifest_path.is_file() or not digest_path.is_file():
        raise ConfigurationError("Campaign 缺少 campaign.json 或 campaign.sha256。")
    expected = digest_path.read_text(encoding="utf-8").strip()
    if not SHA256_RE.fullmatch(expected) or file_sha256(manifest_path) != expected:
        raise ConfigurationError("Campaign 核心清单摘要不一致，拒绝继续。")
    manifest = _read_json(manifest_path, "Campaign 核心清单")
    if manifest.get("schema_version") != CAMPAIGN_SCHEMA:
        raise ConfigurationError("Campaign schema_version 不受支持。")
    _campaign_coordinates(manifest)
    predecessor = manifest.get("predecessor")
    if predecessor is not None:
        if (
            not isinstance(predecessor, dict)
            or set(predecessor)
            != {
                "campaign_dir",
                "campaign_id",
                "campaign_manifest_sha256",
                "reason",
            }
            or not isinstance(predecessor.get("campaign_dir"), str)
            or not Path(predecessor["campaign_dir"]).is_absolute()
            or not SAFE_ID_RE.fullmatch(str(predecessor.get("campaign_id", "")))
            or not SHA256_RE.fullmatch(
                str(predecessor.get("campaign_manifest_sha256", ""))
            )
            or predecessor.get("reason") not in SUCCESSOR_REASONS
        ):
            raise ConfigurationError("Campaign 前序绑定非法。")
    for group_name in ("inputs", "analysis"):
        for reference in manifest.get(group_name, {}).values():
            if reference is None:
                continue
            relative = reference.get("path")
            expected_sha = reference.get("sha256")
            if not isinstance(relative, str) or not SHA256_RE.fullmatch(
                str(expected_sha)
            ):
                raise ConfigurationError(f"Campaign {group_name} 引用非法。")
            target = _campaign_file(campaign_dir, relative)
            if not target.is_file() or file_sha256(target) != expected_sha:
                raise ConfigurationError(f"Campaign 输入摘要漂移：{relative}")
    if not _skip_control_validation:
        _verify_control_receipts(
            campaign_dir,
            manifest,
            require_active=False,
            _historical_manifest_controls=_control_epoch_bootstrap,
        )
    return manifest


def _campaign_coordinates(manifest: Mapping[str, Any]) -> tuple[str, str]:
    """读取并严格校验 Campaign 创建时冻结的模式与用途。"""

    mode = manifest.get("campaign_mode")
    purpose = manifest.get("campaign_purpose")
    if mode not in CAMPAIGN_MODES:
        raise ConfigurationError("Campaign 缺少或携带非法 campaign_mode。")
    if purpose not in CANDIDATE_PURPOSES:
        raise ConfigurationError("Campaign 缺少或携带非法 campaign_purpose。")
    return str(mode), str(purpose)


def _require_formal_campaign(
    campaign_dir: Path,
    manifest: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """阻止 P0 计划通过任何直接或 continuation 入口进入正式阶段。"""

    current = manifest or load_campaign_manifest(campaign_dir)
    mode, _ = _campaign_coordinates(current)
    if mode != "formal":
        raise ConfigurationError(
            "preflight_only Campaign 只允许 plan/status；不得进入正式或 live 阶段，"
            "请以 formal 模式创建全新 Campaign。"
        )
    return current


def _stage_path(
    campaign_dir: Path,
    stage: str,
    candidate_id: str | None = None,
) -> tuple[str, Path]:
    aliases = {
        "official": "capture-official",
        "candidate": "capture-candidate",
        "classification": "classify",
        "comparison": "compare",
        "acceptance": "accept",
    }
    canonical = aliases.get(stage, stage)
    if canonical == "capture-official":
        return canonical, campaign_dir / "official" / "result.json"
    if canonical == "classify":
        return canonical, campaign_dir / "classification" / "result.json"
    if canonical in {"capture-candidate", "compare", "accept"}:
        if not candidate_id or not SAFE_ID_RE.fullmatch(candidate_id):
            raise ConfigurationError(f"{canonical} 必须提供合法 candidate-id。")
        roots = {
            "capture-candidate": "candidates",
            "compare": "comparisons",
            "accept": "acceptance",
        }
        return canonical, campaign_dir / roots[canonical] / candidate_id / "result.json"
    raise ConfigurationError(f"未知 Campaign 阶段：{stage}")


def _require_file_binding(value: Any, label: str) -> None:
    if (
        not isinstance(value, dict)
        or set(value) != {"path", "sha256"}
        or not isinstance(value.get("path"), str)
        or not value["path"]
        or not SHA256_RE.fullmatch(str(value.get("sha256")))
    ):
        raise ConfigurationError(f"{label}文件绑定非法。")


def _stage_inventory_binding_matches(
    document: dict[str, Any],
    reference: Any,
    *,
    label: str,
) -> bool:
    """校验阶段绑定；兼容旧 draft 的当前 attempt 相对路径。"""

    _require_file_binding(reference, label)
    inventory = document.get("evidence_inventory")
    entries = inventory.get("entries") if isinstance(inventory, dict) else None
    if not isinstance(entries, list):
        return False
    inventory_index = {
        entry.get("path"): entry.get("sha256")
        for entry in entries
        if isinstance(entry, dict)
    }
    path = reference["path"]
    digest = reference["sha256"]
    if inventory_index.get(path) == digest:
        return True
    prefix = "evidence/"
    if not path.startswith(prefix):
        return False
    relative = PurePosixPath(path[len(prefix) :])
    if (
        relative.is_absolute()
        or "\\" in path
        or not relative.parts
        or str(PurePosixPath(path)) != path
        or any(part in {"", ".", ".."} for part in relative.parts)
    ):
        return False
    attempt_reference = document.get("attempt")
    attempt_path = (
        attempt_reference.get("path")
        if isinstance(attempt_reference, Mapping)
        else None
    )
    if not isinstance(attempt_path, str):
        return False
    attempt_parts = PurePosixPath(attempt_path).parts
    if len(attempt_parts) < 3 or attempt_parts[-1] != "attempt.json":
        return False
    attempt_id = attempt_parts[-2]
    roots = document.get("evidence_roots")
    if not isinstance(roots, list):
        return False
    root_paths = [Path(raw_root) for raw_root in roots if isinstance(raw_root, str)]
    candidates: list[str] = []
    for root, root_prefix in _evidence_root_map(root_paths):
        if root.name == "evidence" and root.parent.name == attempt_id:
            candidates.append(f"{root_prefix}/{relative.as_posix()}")
    return len(candidates) == 1 and inventory_index.get(candidates[0]) == digest


def _validate_stage_contract(document: dict[str, Any]) -> None:
    """对运行期阶段收据执行失败关闭的核心契约校验。"""

    if document.get("schema_version") != STAGE_SCHEMA:
        raise ConfigurationError("阶段收据 schema_version 不受支持。")
    if document.get("campaign_mode") != "formal":
        raise ConfigurationError("阶段收据只能属于 formal Campaign。")
    if document.get("campaign_purpose") not in CANDIDATE_PURPOSES:
        raise ConfigurationError("阶段收据缺少或携带非法 Campaign 用途。")
    stage = document.get("stage")
    status = document.get("status")
    if stage not in {"capture-official", "classify", "capture-candidate", "compare", "accept"}:
        raise ConfigurationError("阶段收据 stage 非法。")
    if status not in {"complete", "blocked", "failed"}:
        raise ConfigurationError("阶段收据 status 非法。")
    candidate_stage = stage in {"capture-candidate", "compare", "accept"}
    expected_candidate_purpose = (
        document.get("campaign_purpose") if candidate_stage else None
    )
    if document.get("candidate_purpose") != expected_candidate_purpose:
        raise ConfigurationError("阶段收据 candidate purpose 与阶段／Campaign 不一致。")
    predecessor_import = document.get("predecessor_import")
    if predecessor_import is not None:
        if stage not in {"capture-official", "classify"} or status != "complete":
            raise ConfigurationError("前序导入只允许完整的官方或分类阶段。")
        _require_file_binding(predecessor_import, "前序导入收据")
        if not SHA256_RE.fullmatch(
            str(document.get("predecessor_package_digest", ""))
        ):
            raise ConfigurationError("前序导入缺少原阶段 package digest。")
        if stage == "capture-official":
            _require_file_binding(document.get("surface"), "导入的官方表面")
            return
    elif "predecessor_package_digest" in document:
        raise ConfigurationError("阶段收据不得携带未绑定收据的前序摘要。")
    if stage in {"capture-official", "capture-candidate"} and status == "complete":
        required = {
            "identity",
            "attempt",
            "seal_preview",
            "results",
            "evidence_roots",
            "evidence_inventory",
            "surface",
            "client_bindings",
            "assertion_context",
            "assertion_gate",
            "restoration",
            "security",
        }
        missing = sorted(required - set(document))
        if missing:
            raise ConfigurationError(f"抓包阶段收据缺少字段：{missing}")
        try:
            validate_gate_receipt(
                document.get("assertion_gate"),
                side="official" if stage == "capture-official" else "candidate",
            )
        except AssertionGateError as error:
            raise ConfigurationError(
                f"抓包阶段断言门禁收据非法：{error}"
            ) from error
        if not isinstance(document["results"], list) or not document["results"]:
            raise ConfigurationError("抓包阶段 results 不能为空。")
        _require_file_binding(document.get("attempt"), "抓包 attempt")
        _require_file_binding(document.get("seal_preview"), "seal 预览")
        evaluation_transition = document.get("evaluation_transition")
        if evaluation_transition is not None:
            _require_file_binding(evaluation_transition, "评估工具 transition")
        evidence_manifest = document.get("evidence_manifest")
        if evidence_manifest is not None:
            _require_file_binding(evidence_manifest, "EvidenceManifest")
            scan_summary = document.get("scan_summary")
            if (
                not isinstance(scan_summary, dict)
                or set(scan_summary)
                != {
                    "full_scan_count",
                    "scanned_bytes",
                    "reused_bytes",
                    "total_bytes",
                    "elapsed_seconds",
                }
                or scan_summary.get("full_scan_count") != 1
                or not all(
                    isinstance(scan_summary.get(field), int)
                    and scan_summary[field] >= 0
                    for field in ("scanned_bytes", "reused_bytes", "total_bytes")
                )
                or scan_summary["scanned_bytes"] + scan_summary["reused_bytes"]
                != scan_summary["total_bytes"]
                or not isinstance(scan_summary.get("elapsed_seconds"), (int, float))
                or scan_summary["elapsed_seconds"] < 0
            ):
                raise ConfigurationError("抓包阶段 scan_summary 非法。")
        elif "scan_summary" in document:
            raise ConfigurationError("抓包阶段不得携带无 manifest 的 scan_summary。")
        if not isinstance(document["evidence_roots"], list) or not document["evidence_roots"]:
            raise ConfigurationError("抓包阶段 evidence_roots 不能为空。")
        inventory = document["evidence_inventory"]
        if (
            not isinstance(inventory, dict)
            or not isinstance(inventory.get("entries"), list)
            or not inventory["entries"]
            or inventory.get("entry_count") != len(inventory["entries"])
            or inventory.get("digest") != _fingerprint({"entries": inventory["entries"]})
        ):
            raise ConfigurationError("抓包阶段 evidence_inventory 非法。")
        inventory_index = {
            entry.get("path"): entry.get("sha256")
            for entry in inventory["entries"]
            if isinstance(entry, dict)
        }
        _require_file_binding(document["surface"], "抓包表面")
        restoration = document["restoration"]
        if (
            not isinstance(restoration, dict)
            or restoration.get("passed") is not True
            or not isinstance(restoration.get("checks"), list)
            or not restoration["checks"]
        ):
            raise ConfigurationError("抓包阶段恢复门禁未通过。")
        _require_file_binding(restoration.get("report"), "环境恢复报告")
        if not _stage_inventory_binding_matches(
            document,
            restoration["report"],
            label="环境恢复报告",
        ):
            raise ConfigurationError("环境恢复报告未绑定封存证据清单。")
        security = document["security"]
        if (
            not isinstance(security, dict)
            or security.get("raw_evidence_private") is not True
            or security.get("known_secret_scan_passed") is not True
        ):
            raise ConfigurationError("抓包阶段秘密扫描门禁未通过。")
        context = document["assertion_context"]
        if (
            not isinstance(context, dict)
            or not isinstance(context.get("capture_manifest_path"), str)
            or not isinstance(context.get("evidence_root"), str)
            or not isinstance(context.get("evidence_prefix"), str)
        ):
            raise ConfigurationError("抓包阶段 assertion_context 非法。")
        _require_file_binding(context.get("capture_manifest"), "capture manifest")
        if not _stage_inventory_binding_matches(
            document,
            context["capture_manifest"],
            label="capture manifest",
        ):
            raise ConfigurationError("capture manifest 未绑定封存证据清单。")
        if stage == "capture-candidate":
            capture_identity = document.get("identity")
            if (
                not isinstance(capture_identity, dict)
                or capture_identity.get("candidate_purpose")
                != document.get("candidate_purpose")
            ):
                raise ConfigurationError("候选阶段身份用途与阶段用途不一致。")
            post_client = restoration.get("post_client")
            if (
                not isinstance(post_client, dict)
                or post_client.get("passed") is not True
                or not isinstance(post_client.get("checks"), list)
                or not post_client["checks"]
            ):
                raise ConfigurationError("候选阶段缺少 Kilo 后环境恢复门禁。")
            _require_file_binding(
                post_client.get("report"), "Kilo 后环境恢复报告"
            )
            if not _stage_inventory_binding_matches(
                document,
                post_client["report"],
                label="Kilo 后环境恢复报告",
            ):
                raise ConfigurationError("Kilo 后恢复报告未绑定封存证据清单。")
            _require_file_binding(document.get("observed_profile"), "运行画像观测")
            if not _stage_inventory_binding_matches(
                document,
                document["observed_profile"],
                label="运行画像观测",
            ):
                raise ConfigurationError("运行画像观测未绑定封存证据清单。")
            client_bindings = document.get("client_bindings")
            client_ids = {
                item.get("client_id")
                for item in client_bindings
                if isinstance(item, dict)
            } if isinstance(client_bindings, list) else set()
            if not REQUIRED_CLIENT_BINDINGS.issubset(client_ids):
                raise ConfigurationError("候选阶段缺少两种必需 Kilo 客户端绑定。")
        else:
            binary_verification = document.get("binary_verification")
            if (
                not isinstance(binary_verification, dict)
                or binary_verification.get("passed") is not True
                or not SHA256_RE.fullmatch(
                    str(binary_verification.get("expected_sha256", ""))
                )
                or not VERSION_RE.fullmatch(
                    str(binary_verification.get("expected_version", ""))
                )
                or not IMMUTABLE_IMAGE_RE.fullmatch(
                    str(binary_verification.get("runtime_image_reference", ""))
                )
                or not IMAGE_ID_RE.fullmatch(
                    str(binary_verification.get("runtime_image_id", ""))
                )
                or not isinstance(binary_verification.get("identities"), list)
                or len(binary_verification["identities"]) < 3
            ):
                raise ConfigurationError("官方阶段缺少完整二进制身份验证。")
    if stage == "classify" and status in {"complete", "blocked"}:
        for field in (
            "target_rule_manifest",
            "migration_manifest",
            "scenario_manifest",
            "profile_manifest",
            "assertion_profile_manifest",
        ):
            _require_file_binding(document.get(field), field)
    if stage == "compare" and status == "complete":
        for field in (
            "official_package_digest",
            "candidate_package_digest",
            "classification_package_digest",
        ):
            if not SHA256_RE.fullmatch(str(document.get(field))):
                raise ConfigurationError(f"比较阶段 {field} 非法。")
        if document.get("offline_only") is not True:
            raise ConfigurationError("比较阶段必须是纯离线。")
    if stage == "accept" and status == "complete":
        _require_file_binding(document.get("assertion_result"), "逐规则断言结果")
        _require_file_binding(document.get("evidence_seal"), "验收证据封印")
        external_gate = document.get("candidate_external_gate")
        if (
            not isinstance(external_gate, dict)
            or set(external_gate) != {"evidence_root", "receipt"}
            or not isinstance(external_gate.get("evidence_root"), str)
            or not isinstance(external_gate.get("receipt"), dict)
            or set(external_gate["receipt"]) != {"path", "sha256", "bytes"}
        ):
            raise ConfigurationError("验收阶段缺少 candidate 外部门禁绑定。")
        identity = document.get("candidate_identity")
        if (
            not isinstance(identity, dict)
            or set(identity)
            != {
                "source_tree_sha256",
                "image_id",
                "image_reference",
                "build_id",
                "deployed_version",
                "candidate_purpose",
            }
            or not SHA256_RE.fullmatch(str(identity.get("source_tree_sha256", "")))
            or not IMAGE_ID_RE.fullmatch(str(identity.get("image_id", "")))
            or not IMMUTABLE_IMAGE_RE.fullmatch(str(identity.get("image_reference", "")))
            or identity.get("candidate_purpose") != document.get("candidate_purpose")
        ):
            raise ConfigurationError("验收阶段 candidate 身份投影非法。")
        if document.get("production_state") != "accepted_not_activated":
            raise ConfigurationError("验收阶段必须显式记录 accepted_not_activated。")


def save_stage_result(
    campaign_dir: Path,
    stage: str,
    payload: dict[str, Any],
    candidate_id: str | None = None,
    *,
    _successor_manifest: dict[str, Any] | None = None,
) -> Path:
    """封存阶段结果；同一阶段和候选编号永不覆盖。"""

    if _successor_manifest is None:
        manifest = _require_formal_campaign(campaign_dir)
    else:
        # successor 在未发布暂存区内需要先同时写入 official/classify 导入结果；
        # 此时历史场景的当前批准绑定尚未形成完整阶段闭环，不能提前走普通重放。
        stored_manifest = _read_json(
            campaign_dir / "campaign.json",
            "后继暂存 Campaign manifest",
        )
        if (
            stored_manifest != _successor_manifest
            or not isinstance(_successor_manifest.get("predecessor"), dict)
            or ".successor-" not in campaign_dir.name
        ):
            raise ConfigurationError("后继暂存 Campaign manifest 非法。")
        manifest = _require_formal_campaign(
            campaign_dir,
            _successor_manifest,
        )
    canonical, path = _stage_path(campaign_dir, stage, candidate_id)
    _reject_symlink_components(path.parent, campaign_dir, f"{canonical} 阶段目录")
    if path.exists():
        raise ConfigurationError(f"阶段结果已存在，禁止覆盖：{path}")
    if path.parent.exists() and path.parent.is_symlink():
        raise ConfigurationError(f"阶段目录不可信：{path.parent}")
    ensure_private_directory(path.parent, campaign_dir)
    document = dict(payload)
    for field in ("campaign_mode", "campaign_purpose"):
        provided = document.get(field)
        if provided is not None and provided != manifest[field]:
            raise ConfigurationError(f"阶段收据 {field} 与 Campaign 不一致。")
        document[field] = manifest[field]
    expected_candidate_purpose = (
        manifest["campaign_purpose"]
        if canonical in {"capture-candidate", "compare", "accept"}
        else None
    )
    if document.get("candidate_purpose") not in {
        None,
        expected_candidate_purpose,
    }:
        raise ConfigurationError("阶段收据 candidate purpose 与 Campaign 不一致。")
    document["candidate_purpose"] = expected_candidate_purpose
    evidence_roots = [Path(value) for value in document.get("evidence_roots", [])]
    has_evidence_manifest = isinstance(document.get("evidence_manifest"), dict)
    if canonical in {"capture-official", "capture-candidate"} and evidence_roots:
        if has_evidence_manifest:
            _stage_evidence_manifest(
                campaign_dir,
                document,
                verify_boundary=True,
            )
        else:
            document.setdefault("evidence_inventory", _evidence_inventory(evidence_roots))
            security = document.setdefault("security", _evidence_security(evidence_roots))
            if not security.get("known_secret_scan_passed"):
                raise ConfigurationError(f"{canonical} 证据秘密扫描未通过。")
    result_schema = document.pop("schema_version", None)
    document["schema_version"] = STAGE_SCHEMA
    if result_schema and result_schema != STAGE_SCHEMA:
        document["result_schema_version"] = result_schema
    document["stage"] = canonical
    document["campaign_id"] = manifest["campaign_id"]
    if candidate_id is not None:
        document["candidate_id"] = candidate_id
    document["campaign_manifest_sha256"] = file_sha256(
        campaign_dir / "campaign.json"
    )
    with _campaign_lock(campaign_dir):
        _reject_contaminated_campaign(campaign_dir)
        _reject_symlink_components(path.parent, campaign_dir, f"{canonical} 阶段目录")
        if path.exists() or path.is_symlink():
            raise ConfigurationError(f"阶段结果已存在，禁止覆盖：{path}")
        if canonical in {"capture-official", "capture-candidate"} and evidence_roots:
            if has_evidence_manifest:
                _stage_evidence_manifest(
                    campaign_dir,
                    document,
                    verify_boundary=True,
                )
            else:
                current_inventory = _evidence_inventory(evidence_roots)
                if current_inventory != document.get("evidence_inventory"):
                    raise ConfigurationError(
                        f"{canonical} 证据在封存审批后发生变化，禁止写入。"
                    )
                current_security = _evidence_security(evidence_roots)
                expected_security = document.get("security")
                if not isinstance(expected_security, dict) or any(
                    expected_security.get(key) != value
                    for key, value in current_security.items()
                ):
                    raise ConfigurationError(
                        f"{canonical} 证据秘密扫描结果在封存审批后发生变化。"
                    )
                if (
                    expected_security.get("raw_evidence_private") is not True
                    or not _evidence_permissions_private(evidence_roots)
                ):
                    raise ConfigurationError(
                        f"{canonical} 原始证据权限在封存审批后发生变化。"
                    )
        document["sealed_at_utc"] = time.strftime(
            "%Y-%m-%dT%H:%M:%SZ", time.gmtime()
        )
        _validate_stage_contract(document)
        document["package_digest"] = _fingerprint(document)
        _secure_write_json_once(path, document)
    return path


def _successor_copy_expectations(
    campaign_dir: Path,
    manifest: dict[str, Any],
    predecessor_dir: Path,
    predecessor_manifest: dict[str, Any],
    official: dict[str, Any],
    classification: dict[str, Any] | None,
    *,
    include_classification: bool = True,
    replace_target_scenario: bool = False,
) -> dict[str, dict[str, Any]]:
    """重建后继 Campaign 必须逐字复制的完整文件闭集。"""

    expected: dict[str, dict[str, Any]] = {}

    def add(
        reference: Any,
        kind: str,
        *,
        target_relative: str | None = None,
    ) -> None:
        _require_file_binding(reference, f"前序 {kind}")
        source_relative = str(reference["path"])
        destination_relative = target_relative or source_relative
        source = _campaign_file(predecessor_dir, source_relative)
        if source.is_symlink() or not source.is_file():
            raise ConfigurationError(
                f"前序复制源不存在或不可信：{source_relative}"
            )
        digest = file_sha256(source)
        if digest != reference["sha256"]:
            raise ConfigurationError(
                f"前序复制源摘要漂移：{source_relative}"
            )
        row = {
            "kind": kind,
            "source_path": source_relative,
            "target_path": destination_relative,
            "sha256": digest,
            "bytes": source.stat().st_size,
        }
        previous = expected.get(destination_relative)
        if previous is not None and previous != row:
            raise ConfigurationError(
                "前序复制闭集出现路径摘要冲突：" + destination_relative
            )
        expected.setdefault(destination_relative, row)

    for group_name in ("inputs", "analysis"):
        for field, reference in predecessor_manifest[group_name].items():
            if reference is not None:
                if (
                    replace_target_scenario
                    and group_name == "inputs"
                    and field == "target_discovery_scenarios"
                ):
                    continue
                add(reference, f"plan_{group_name}")
    if replace_target_scenario:
        reference = manifest.get("inputs", {}).get(
            "target_discovery_scenarios"
        )
        _require_file_binding(reference, "后继运行时 target 场景")
        assert isinstance(reference, dict)
        relative = str(reference["path"])
        target = _campaign_file(campaign_dir, relative)
        if (
            target.is_symlink()
            or not target.is_file()
            or file_sha256(target) != reference["sha256"]
        ):
            raise ConfigurationError("后继运行时 target 场景摘要漂移。")
        expected[relative] = {
            "kind": "runtime_target_scenario",
            "source_path": relative,
            "target_path": relative,
            "sha256": reference["sha256"],
            "bytes": target.stat().st_size,
        }
    if include_classification:
        if classification is None:
            raise ConfigurationError("前序批准分类缺失，无法重建复制闭集。")
        for field in _CLASSIFICATION_APPROVAL_FIELDS:
            add(classification.get(field), "approved_classification")
    add(
        official.get("surface"),
        "official_surface",
        target_relative=_SUCCESSOR_OFFICIAL_SURFACE_PATH,
    )
    return expected


def _validate_direct_predecessor_official_attempt(
    predecessor_dir: Path,
    predecessor_official: dict[str, Any],
    *,
    _historical_manifest_controls: bool = False,
) -> None:
    """重放直接前序的官方 attempt 与原子预约。

    若前序 official 自身来自更早 Campaign，调用方已通过递归
    ``_load_stage_result`` 在其原始绝对目录完成相同校验；不得把投影结果中保留的
    上游相对 attempt 路径再次拼到当前前序目录。
    """

    attempt_reference = predecessor_official.get("attempt")
    _require_file_binding(attempt_reference, "前序官方 attempt")
    attempt_path = _campaign_file(predecessor_dir, attempt_reference["path"])
    attempt_root, attempt = _load_capture_attempt(
        predecessor_dir,
        "official",
        None,
        attempt_path.parent.name,
        _historical_manifest_controls=_historical_manifest_controls,
    )
    reservation = _load_capture_reservation(
        predecessor_dir,
        attempt_root,
        phase="official",
        candidate_id=None,
        _historical_manifest_controls=_historical_manifest_controls,
    )
    planned = {
        item["id"]: item
        for item in reservation["planned_jobs"]
        if item["required"]
    }
    completed = {
        item.get("id"): item
        for item in predecessor_official.get("results", [])
        if isinstance(item, dict)
    }
    if any(
        job_id not in completed
        or completed[job_id].get("status") != "complete"
        or completed[job_id].get("execution_sha256")
        != planned_job["execution_sha256"]
        for job_id, planned_job in planned.items()
    ) or attempt.get("results") != predecessor_official.get("results"):
        raise ConfigurationError("前序官方任务未按原子预约完整执行或结果漂移。")


def _validate_predecessor_import_receipt(
    campaign_dir: Path,
    manifest: dict[str, Any],
    stage_payload: dict[str, Any],
    canonical: str,
    import_chain: frozenset[Path],
    *,
    import_cache: dict[tuple[str, str, str | None], dict[str, Any]] | None = None,
    skip_evidence_scan: bool = False,
    _historical_manifest_controls: bool = False,
) -> dict[str, Any]:
    """重放前序 Campaign、官方证据、安全门禁和批准五件套。"""

    import_binding = stage_payload.get("predecessor_import")
    _verify_campaign_binding(campaign_dir, import_binding, "前序导入收据")
    import_path = _campaign_file(campaign_dir, import_binding["path"])
    receipt = _read_json(import_path, "前序导入收据")
    receipt_schema = receipt.get("schema_version")
    expected_receipt_fields = {
        "schema_version",
        "created_at_utc",
        "reason",
        "successor_campaign_id",
        "successor_campaign_manifest_sha256",
        "predecessor_campaign",
        "stages",
        "copied_files",
        "abandoned_candidate_attempt",
        "receipt_digest",
    }
    if receipt_schema in {
        PREDECESSOR_IMPORT_SCHEMA,
        PREDECESSOR_RECLASSIFICATION_IMPORT_SCHEMA,
        PREDECESSOR_RUNTIME_IMPORT_SCHEMA,
        PREDECESSOR_REHEARSAL_IMPORT_SCHEMA,
        PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
        PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA,
        PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA,
        *PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMAS,
    }:
        expected_receipt_fields.add("configuration_transition")
    if receipt_schema in {
        PREDECESSOR_REHEARSAL_IMPORT_SCHEMA,
        PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
        PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA,
        PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA,
        *PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMAS,
    }:
        expected_receipt_fields.add("job_rehearsal_transition")
    if receipt_schema == PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA:
        expected_receipt_fields.add("target_scenario_transition")
    if (
        receipt_schema
        in {
            PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
            PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA,
            PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA,
        }
        and "recovery_control_transition" in receipt
    ) or (
        receipt_schema == PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMA
        and "recovery_control_transition" in receipt
    ):
        expected_receipt_fields.add("recovery_control_transition")
    if receipt_schema == PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA:
        expected_receipt_fields.add("control_replacement")
    if receipt_schema in PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMAS:
        expected_receipt_fields.update(
            {"stage_control_transition", "execution_summary", "import_mode"}
        )
    if receipt_schema == PREDECESSOR_RECLASSIFICATION_IMPORT_SCHEMA or (
        receipt_schema in {
            PREDECESSOR_REHEARSAL_IMPORT_SCHEMA,
            PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
        }
        and receipt.get("reason") in RECLASSIFICATION_SUCCESSOR_REASONS
    ):
        expected_receipt_fields.add("import_mode")
    unsigned_receipt = dict(receipt)
    receipt_digest = unsigned_receipt.pop("receipt_digest", None)
    if (
        set(receipt) != expected_receipt_fields
        or receipt_schema
        not in {
            PREDECESSOR_IMPORT_SCHEMA_V1,
            PREDECESSOR_IMPORT_SCHEMA,
            PREDECESSOR_RECLASSIFICATION_IMPORT_SCHEMA,
            PREDECESSOR_RUNTIME_IMPORT_SCHEMA,
            PREDECESSOR_REHEARSAL_IMPORT_SCHEMA,
            PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
            PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA,
            PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA,
            *PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMAS,
        }
        or not _is_rfc3339_timestamp(receipt.get("created_at_utc"))
        or receipt.get("reason") not in SUCCESSOR_REASONS
        or receipt.get("successor_campaign_id") != manifest["campaign_id"]
        or receipt.get("successor_campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or not SHA256_RE.fullmatch(str(receipt_digest))
        or _fingerprint(unsigned_receipt) != receipt_digest
    ):
        raise ConfigurationError("前序导入收据身份、时间或摘要非法。")
    reclassification_import = receipt_schema in {
        PREDECESSOR_RECLASSIFICATION_IMPORT_SCHEMA,
        PREDECESSOR_REHEARSAL_IMPORT_SCHEMA,
        PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
    } and receipt.get("reason") in RECLASSIFICATION_SUCCESSOR_REASONS
    sealed_stage_recovery_import = (
        receipt_schema in PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMAS
        and receipt.get("reason") in SEALED_STAGE_RECOVERY_SUCCESSOR_REASONS
    )
    control_refresh_import = (
        receipt_schema == PREDECESSOR_RECOVERY_IMPORT_SCHEMA
        and receipt.get("reason") == "candidate_recovery_control_refresh"
    )
    control_replacement_import = (
        receipt_schema == PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA
        and receipt.get("reason") == "candidate_recovery_control_replacement"
    )
    official_only_import = reclassification_import or sealed_stage_recovery_import
    if reclassification_import:
        if (
            receipt.get("reason") not in RECLASSIFICATION_SUCCESSOR_REASONS
            or receipt.get("import_mode")
            != "official_only_reclassification"
            or canonical != "capture-official"
        ):
            raise ConfigurationError("分类纠正后继的导入模式或阶段边界非法。")
    elif sealed_stage_recovery_import:
        if (
            receipt.get("import_mode")
            != "official_only_sealed_stage_control_recovery"
            or canonical != "capture-official"
            or receipt.get("execution_summary")
            != {
                "executed_job_ids": [],
                "scanned_bytes": 0,
                "live_request_count": 0,
            }
        ):
            raise ConfigurationError("已封存阶段控制恢复的导入边界非法。")
    elif receipt.get("reason") in (
        RECLASSIFICATION_SUCCESSOR_REASONS
        | SEALED_STAGE_RECOVERY_SUCCESSOR_REASONS
    ):
        raise ConfigurationError("分类纠正后继必须使用 official-only 受管收据。")

    manifest_predecessor = manifest.get("predecessor")
    predecessor_binding = receipt.get("predecessor_campaign")
    if (
        not isinstance(manifest_predecessor, dict)
        or not isinstance(predecessor_binding, dict)
        or set(predecessor_binding)
        != {"campaign_dir", "campaign_id", "campaign_manifest_sha256"}
        or manifest_predecessor
        != {
            **predecessor_binding,
            "reason": receipt["reason"],
        }
    ):
        raise ConfigurationError("前序导入收据与 Campaign 前序绑定不一致。")
    predecessor_dir = Path(str(predecessor_binding["campaign_dir"]))
    if (
        not predecessor_dir.is_absolute()
        or str(predecessor_dir.resolve()) != str(predecessor_dir)
        or predecessor_dir.resolve() in import_chain
        or predecessor_dir.resolve() == campaign_dir.resolve()
    ):
        raise ConfigurationError("前序 Campaign 路径不可信或导入链形成循环。")
    _validate_existing_campaign_path(predecessor_dir)
    predecessor_manifest = _require_formal_campaign(
        predecessor_dir,
        load_campaign_manifest(
            predecessor_dir,
            # predecessor-import 读取的永远是不可变祖先；即使当前边不是
            # control-replacement，也必须保留更早 epoch 的历史阶段规则。
            _control_epoch_bootstrap=True,
        ),
    )
    if (
        predecessor_binding.get("campaign_id")
        != predecessor_manifest.get("campaign_id")
        or predecessor_binding.get("campaign_manifest_sha256")
        != file_sha256(predecessor_dir / "campaign.json")
    ):
        raise ConfigurationError("前序 Campaign 清单身份或摘要漂移。")

    runtime_scenario_import = (
        receipt_schema == PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA
    )
    if runtime_scenario_import:
        transition = receipt.get("target_scenario_transition")
        predecessor_reference = predecessor_manifest.get("inputs", {}).get(
            "target_discovery_scenarios"
        )
        successor_reference = manifest.get("inputs", {}).get(
            "target_discovery_scenarios"
        )
        if (
            receipt.get("reason") != "candidate_runtime_identity_correction"
            or not isinstance(transition, dict)
            or set(transition)
            != {"reason", "predecessor", "successor", "changed_job_ids"}
            or transition.get("reason")
            != "candidate_codex_binary_binding_correction"
            or transition.get("predecessor") != predecessor_reference
            or transition.get("successor") != successor_reference
        ):
            raise ConfigurationError("后继 target 场景过渡收据非法。")
        _require_file_binding(
            predecessor_reference,
            "后继 target 场景过渡的前序绑定",
        )
        _require_file_binding(
            successor_reference,
            "后继 target 场景过渡的当前绑定",
        )
        assert isinstance(predecessor_reference, dict)
        assert isinstance(successor_reference, dict)
        predecessor_scenario_path = _campaign_file(
            predecessor_dir,
            str(predecessor_reference["path"]),
        )
        successor_scenario_path = _campaign_file(
            campaign_dir,
            str(successor_reference["path"]),
        )
        if (
            predecessor_scenario_path.is_symlink()
            or not predecessor_scenario_path.is_file()
            or file_sha256(predecessor_scenario_path)
            != predecessor_reference["sha256"]
            or successor_scenario_path.is_symlink()
            or not successor_scenario_path.is_file()
            or file_sha256(successor_scenario_path)
            != successor_reference["sha256"]
        ):
            raise ConfigurationError("后继 target 场景过渡文件摘要漂移。")
        changed_job_ids = _validate_runtime_target_scenario_change(
            _read_json(
                predecessor_scenario_path,
                "后继 target 场景过渡的前序文件",
            ),
            _read_json(
                successor_scenario_path,
                "后继 target 场景过渡的当前文件",
            ),
        )
        if transition.get("changed_job_ids") != list(changed_job_ids):
            raise ConfigurationError("后继 target 场景过渡 Job 集漂移。")

    replayed_control_replacement: dict[str, Any] | None = None
    if control_replacement_import:
        stored_replacement = receipt.get("control_replacement")
        if not isinstance(stored_replacement, Mapping):
            raise ConfigurationError("零执行控制替代缺少审计绑定。")
        epoch = stored_replacement.get("effective_epoch")
        repair = stored_replacement.get("runtime_repair")
        unpublished = stored_replacement.get("unpublished_stop_checkpoint")
        audit = stored_replacement.get("supervisor_audit")
        source_attempt = stored_replacement.get("source_attempt")
        if (
            not isinstance(epoch, Mapping)
            or not isinstance(unpublished, Mapping)
            or not isinstance(audit, Mapping)
            or not isinstance(source_attempt, Mapping)
            or (repair is not None and not isinstance(repair, Mapping))
        ):
            raise ConfigurationError("零执行控制替代审计字段不闭合。")
        unpublished_receipt = unpublished.get("receipt")
        if not isinstance(unpublished_receipt, Mapping):
            raise ConfigurationError("零执行控制替代未发布 Ledger 绑定非法。")
        replay_arguments = argparse.Namespace(
            reason="candidate_recovery_control_replacement",
            predecessor_candidate_id=source_attempt.get("candidate_id"),
            predecessor_attempt_id=source_attempt.get("attempt_id"),
            predecessor_control_epoch=predecessor_dir / str(epoch.get("path", "")),
            predecessor_control_runtime_repair=(
                predecessor_dir / str(repair.get("path", ""))
                if isinstance(repair, Mapping)
                else None
            ),
            predecessor_unpublished_ledger_dir=Path(
                str(unpublished.get("ledger_dir", ""))
            ),
            predecessor_unpublished_stop_receipt=(
                Path(str(unpublished.get("ledger_dir", "")))
                / str(unpublished_receipt.get("path", ""))
            ),
            predecessor_supervisor_run_dir=Path(str(audit.get("run_dir", ""))),
        )
        replayed_control_replacement = _control_replacement_context(
            replay_arguments,
            predecessor_dir,
            predecessor_manifest,
        )
        if not _supervisor_audit_bound_mapping_matches(
            stored_replacement,
            replayed_control_replacement,
        ):
            raise ConfigurationError("零执行控制替代的 Campaign、epoch 或审计终态漂移。")

    predecessor_controls = predecessor_manifest.get("control_receipts")
    successor_controls = manifest.get("control_receipts")
    effective_predecessor_controls = predecessor_controls
    if sealed_stage_recovery_import:
        stage_control = receipt.get("stage_control_transition")
        if not isinstance(stage_control, dict) or set(stage_control) != {
            "reason",
            "source_stage",
            "evaluation_transition",
            "predecessor",
            "successor",
        }:
            raise ConfigurationError("已封存阶段控制过渡字段不闭合。")
        source_stage = stage_control.get("source_stage")
        evaluation_transition = stage_control.get("evaluation_transition")
        if (
            stage_control.get("reason") != "sealed_stage_control_recovery"
            or not isinstance(source_stage, dict)
            or set(source_stage) != {"path", "sha256", "package_digest"}
            or source_stage.get("path") != "official/result.json"
            or not isinstance(evaluation_transition, dict)
            or set(evaluation_transition) != {"path", "sha256"}
        ):
            raise ConfigurationError("已封存阶段控制过渡身份非法。")
        predecessor_official_path = predecessor_dir / "official" / "result.json"
        predecessor_official_raw = _read_json(
            predecessor_official_path,
            "已封存阶段控制恢复的前序 official",
        )
        transition_path = _campaign_file(
            predecessor_dir,
            str(evaluation_transition.get("path", "")),
        )
        transition_origin_dir = predecessor_dir.resolve(strict=True)
        transition_origin_manifest = predecessor_manifest
        transition_binding_matches = (
            predecessor_official_raw.get("evaluation_transition")
            == evaluation_transition
        )
        if (
            predecessor_official_raw.get("evaluation_transition") is None
            and not transition_path.exists()
            and not transition_path.is_symlink()
            and isinstance(
                predecessor_official_raw.get("predecessor_import"), Mapping
            )
        ):
            (
                transition_path,
                transition_origin_dir,
                transition_origin_manifest,
            ) = _imported_stage_evaluation_transition_source(
                predecessor_dir,
                predecessor_official_raw,
                evaluation_transition,
            )
            transition_binding_matches = True
        transition_payload = _read_json(
            transition_path,
            "已封存阶段控制恢复的评估 transition",
        )
        transition_unsigned = dict(transition_payload)
        transition_digest = transition_unsigned.pop("transition_digest", None)
        recovery_controls = transition_payload.get("recovery_controls")
        transition_recovery = (
            recovery_controls.get("recovery")
            if isinstance(recovery_controls, Mapping)
            else None
        )
        expected_source_stage = {
            "path": "official/result.json",
            "sha256": file_sha256(predecessor_official_path),
            "package_digest": predecessor_official_raw.get("package_digest"),
        }
        if (
            source_stage != expected_source_stage
            or not transition_binding_matches
            or transition_path.is_symlink()
            or not transition_path.is_file()
            or file_sha256(transition_path) != evaluation_transition.get("sha256")
            or transition_payload.get("schema_version")
            != TOOL_EVALUATION_TRANSITION_SCHEMA
            or transition_payload.get("status") != "approved"
            or transition_payload.get("phase") != "official"
            or transition_payload.get("campaign_id")
            != transition_origin_manifest.get("campaign_id")
            or transition_payload.get("campaign_manifest_sha256")
            != file_sha256(transition_origin_dir / "campaign.json")
            or not SHA256_RE.fullmatch(str(transition_digest))
            or _fingerprint(transition_unsigned) != transition_digest
            or not isinstance(transition_recovery, dict)
            or stage_control.get("predecessor") != transition_recovery
            or stage_control.get("successor") != successor_controls
        ):
            raise ConfigurationError("已封存阶段控制过渡摘要或控制链漂移。")
        effective_predecessor_controls = transition_recovery
    elif control_refresh_import:
        control_transition = receipt.get("recovery_control_transition")
        source_transition = (
            control_transition.get("source_transition")
            if isinstance(control_transition, Mapping)
            else None
        )
        abandoned = receipt.get("abandoned_candidate_attempt")
        if (
            not isinstance(abandoned, Mapping)
            or not isinstance(abandoned.get("candidate_id"), str)
            or not isinstance(abandoned.get("attempt_id"), str)
            or not isinstance(source_transition, Mapping)
        ):
            raise ConfigurationError(
                "控制刷新导入缺少源 Candidate／attempt／transition 绑定。"
            )
        _, expected_source_binding, transition_recovery = (
            _candidate_control_refresh_source_transition(
                predecessor_dir,
                predecessor_manifest,
                candidate_id=str(abandoned["candidate_id"]),
                attempt_id=str(abandoned["attempt_id"]),
                source=source_transition,
                _historical_manifest_controls=_historical_manifest_controls,
            )
        )
        if source_transition != expected_source_binding:
            raise ConfigurationError("控制刷新导入的源 transition 绑定漂移。")
        effective_predecessor_controls = transition_recovery
    elif control_replacement_import:
        assert replayed_control_replacement is not None
        effective_predecessor_controls = replayed_control_replacement[
            "effective_controls"
        ]
    predecessor_rehearsal = (
        effective_predecessor_controls.get("job_rehearsal")
        if isinstance(effective_predecessor_controls, dict)
        else None
    )
    successor_rehearsal = (
        successor_controls.get("job_rehearsal")
        if isinstance(successor_controls, dict)
        else None
    )
    if not isinstance(predecessor_rehearsal, dict) or not isinstance(
        successor_rehearsal, dict
    ):
        raise ConfigurationError("前序或后继 Campaign 缺少完整 Job 演练绑定。")
    if receipt_schema in {
        PREDECESSOR_REHEARSAL_IMPORT_SCHEMA,
        PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
        PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA,
        PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA,
        *PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMAS,
    }:
        expected_rehearsal_transition = {
            "reason": "current_execution_contract_rehearsal",
            "predecessor": predecessor_rehearsal,
            "successor": successor_rehearsal,
        }
        if (
            receipt.get("job_rehearsal_transition")
            != expected_rehearsal_transition
            or predecessor_rehearsal == successor_rehearsal
        ):
            raise ConfigurationError("后继完整 Job 演练过渡收据非法。")
    elif successor_rehearsal != predecessor_rehearsal:
        raise ConfigurationError("后继未登记完整 Job 演练绑定变化。")

    predecessor_timing = (
        effective_predecessor_controls.get("upgrade_timing")
        if isinstance(effective_predecessor_controls, dict)
        else None
    )
    predecessor_arm = (
        effective_predecessor_controls.get("arm64_environment")
        if isinstance(effective_predecessor_controls, dict)
        else None
    )
    successor_timing = (
        successor_controls.get("upgrade_timing")
        if isinstance(successor_controls, dict)
        else None
    )
    successor_arm = (
        successor_controls.get("arm64_environment")
        if isinstance(successor_controls, dict)
        else None
    )
    if not all(
        isinstance(value, dict)
        for value in (
            predecessor_timing,
            predecessor_arm,
            successor_timing,
            successor_arm,
        )
    ):
        raise ConfigurationError("前序或后继 Campaign 的计时／ARM64 控制绑定非法。")
    sealed_stage_stopped_recovery = (
        receipt_schema == PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMA
        and receipt.get("recovery_control_transition") is not None
    )
    if (
        receipt_schema in PREDECESSOR_SEALED_STAGE_RECOVERY_IMPORT_SCHEMAS
        and not sealed_stage_stopped_recovery
    ):
        _assert_sealed_stage_checkpoint_progression(
            predecessor_timing,
            successor_timing,
            predecessor_arm,
            successor_arm,
            baseline_version=str(manifest["baseline_version"]),
            target_version=str(manifest["target_version"]),
            campaign_purpose=str(manifest["campaign_purpose"]),
            require_current_head=False,
        )
    elif (
        receipt_schema
        in {
            PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
            PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA,
            PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA,
        }
        and receipt.get("recovery_control_transition") is not None
        or sealed_stage_stopped_recovery
    ):
        control_transition = receipt.get("recovery_control_transition")
        expected_control_fields = {
            "reason",
            "predecessor",
            "stop_checkpoint",
            "successor",
        }
        if control_refresh_import:
            expected_control_fields.add("source_transition")
        if (
            not isinstance(control_transition, dict)
            or set(control_transition)
            != expected_control_fields
            or control_transition.get("reason") != "stopped_ledger_recovery"
            or control_transition.get("predecessor")
            != {
                "upgrade_timing": predecessor_timing,
                "arm64_environment": predecessor_arm,
            }
            or control_transition.get("successor")
            != {
                "upgrade_timing": successor_timing,
                "arm64_environment": successor_arm,
            }
            or predecessor_timing == successor_timing
            or predecessor_arm == successor_arm
        ):
            raise ConfigurationError("后继恢复控制过渡收据非法。")
        stop_binding = control_transition.get("stop_checkpoint")
        if not isinstance(stop_binding, dict) or set(stop_binding) != {
            "ledger_dir",
            "receipt",
            "upgrade_id",
            "active_phase",
            "head_sequence",
            "head_sha256",
            "total_elapsed_seconds",
            "total_live_request_count",
        }:
            raise ConfigurationError("后继恢复停线绑定字段不闭合。")
        stop_root = Path(str(stop_binding.get("ledger_dir", "")))
        stop_receipt = stop_binding.get("receipt")
        if (
            not isinstance(stop_receipt, dict)
            or set(stop_receipt) != {"path", "sha256", "bytes"}
            or not stop_root.is_absolute()
            or str(stop_root.resolve()) != str(stop_root)
            or str(predecessor_timing.get("ledger_dir", "")) != str(stop_root)
        ):
            raise ConfigurationError("后继恢复停线坐标非法。")
        try:
            stop_relative = _control_receipt_relative(
                stop_root,
                Path(str(stop_receipt.get("path", ""))),
                "后继恢复停线 checkpoint",
            )
            stop_path = stop_root / stop_relative
            stop_checkpoint = codex_upgrade_timing_ledger.replay(
                stop_root,
                stop_relative,
            )
        except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
            raise ConfigurationError(f"后继恢复停线 checkpoint 未通过：{error}") from error
        stop_summary = stop_checkpoint.get("summary")
        expected_stop = {
            "ledger_dir": str(stop_root),
            "receipt": {
                "path": stop_relative,
                "sha256": file_sha256(stop_path),
                "bytes": stop_path.stat().st_size,
            },
            "upgrade_id": stop_summary.get("upgrade_id"),
            "active_phase": stop_summary.get("active_phase"),
            "head_sequence": stop_summary.get("head_sequence"),
            "head_sha256": stop_summary.get("head_sha256"),
            "total_elapsed_seconds": stop_summary.get("total_elapsed_seconds"),
            "total_live_request_count": stop_summary.get(
                "total_live_request_count"
            ),
        }
        if (
            not isinstance(stop_summary, dict)
            or stop_summary.get("status") != "stopped"
            or stop_binding != expected_stop
            or stop_summary.get("upgrade_id")
            != predecessor_timing.get("upgrade_id")
            or (
                stop_summary.get("active_phase")
                not in codex_upgrade_timing_ledger.PHASE_ORDER[1:]
                and not (
                    control_refresh_import
                    and stop_summary.get("active_phase") == "VC-0"
                )
            )
        ):
            raise ConfigurationError("后继恢复停线 checkpoint 事实非法。")
        if sealed_stage_stopped_recovery:
            _, recovery_checkpoint = _sealed_stage_timing_checkpoint(
                successor_timing,
                label="已封存阶段 stopped 恢复",
            )
            recovery_summary = recovery_checkpoint["summary"]
            if (
                recovery_summary.get("status") != "active"
                or recovery_summary.get("active_phase") != "VC-2"
                or recovery_summary.get("total_live_request_count") != 0
            ):
                raise ConfigurationError(
                    "已封存阶段 stopped 恢复的新 checkpoint 必须位于 VC-2，且 live 请求数为 0。"
                )
    elif (
        successor_timing != predecessor_timing
        or successor_arm != predecessor_arm
    ):
        raise ConfigurationError("后继未登记计时／ARM64 控制绑定变化。")

    invariant_fields = (
        "campaign_mode",
        "campaign_purpose",
        "baseline_version",
        "target_version",
        "target_sha256",
        "suite",
        "official_identity",
        "baseline_identity",
        "analysis",
        "required_rules",
    )
    mismatches = [
        field
        for field in invariant_fields
        if manifest.get(field) != predecessor_manifest.get(field)
    ]
    if mismatches:
        raise ConfigurationError(
            "同版本后继 Campaign 改变了禁止承接的前序坐标："
            + "、".join(mismatches)
        )
    predecessor_inputs = predecessor_manifest.get("inputs")
    successor_inputs = manifest.get("inputs")
    if not isinstance(predecessor_inputs, dict) or not isinstance(
        successor_inputs, dict
    ):
        raise ConfigurationError("同版本后继 Campaign 输入绑定不是对象。")
    predecessor_fixed_inputs = dict(predecessor_inputs)
    successor_fixed_inputs = dict(successor_inputs)
    if runtime_scenario_import:
        predecessor_fixed_inputs.pop("target_discovery_scenarios", None)
        successor_fixed_inputs.pop("target_discovery_scenarios", None)
    if predecessor_fixed_inputs != successor_fixed_inputs or (
        not runtime_scenario_import and predecessor_inputs != successor_inputs
    ):
        raise ConfigurationError("同版本后继 Campaign 改变了未授权的输入绑定。")

    predecessor_configuration = predecessor_manifest.get("configuration")
    successor_configuration = manifest.get("configuration")
    if not isinstance(predecessor_configuration, dict) or not isinstance(
        successor_configuration, dict
    ):
        raise ConfigurationError("同版本后继 Campaign 配置不是对象。")
    predecessor_account_id = predecessor_configuration.get("codex_account_id")
    successor_account_id = successor_configuration.get("codex_account_id")
    runtime_fields = (
        "live_attestation_compose_dir",
        "live_attestation_compose_files",
    )
    runtime_configuration_changed = any(
        str(predecessor_configuration.get(field, "") or "")
        != str(successor_configuration.get(field, "") or "")
        for field in runtime_fields
    )
    allowed_configuration_fields = {"codex_account_id"}
    if receipt_schema == PREDECESSOR_RUNTIME_IMPORT_SCHEMA or (
        receipt_schema
        in {
            PREDECESSOR_REHEARSAL_IMPORT_SCHEMA,
            PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
            PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA,
            PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA,
        }
        and runtime_configuration_changed
    ):
        allowed_configuration_fields.update(runtime_fields)
    predecessor_fixed_configuration = dict(predecessor_configuration)
    successor_fixed_configuration = dict(successor_configuration)
    for field in allowed_configuration_fields:
        predecessor_fixed_configuration.pop(field, None)
        successor_fixed_configuration.pop(field, None)
    if predecessor_fixed_configuration != successor_fixed_configuration:
        raise ConfigurationError("同版本后继 Campaign 改变了未授权的运行配置。")
    if receipt_schema == PREDECESSOR_IMPORT_SCHEMA_V1:
        if successor_account_id != predecessor_account_id:
            raise ConfigurationError("历史 v1 后继收据不允许改变 Codex 账号。")
    else:
        configuration_transition = receipt.get("configuration_transition")
        expected_transition: dict[str, Any] = {
            "codex_account_id": {
                "predecessor": predecessor_account_id,
                "successor": successor_account_id,
                "reason": "operator_selected_active_account",
            }
        }
        if receipt_schema == PREDECESSOR_RUNTIME_IMPORT_SCHEMA or (
            receipt_schema
            in {
                PREDECESSOR_REHEARSAL_IMPORT_SCHEMA,
                PREDECESSOR_RECOVERY_IMPORT_SCHEMA,
                PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA,
                PREDECESSOR_CONTROL_REPLACEMENT_IMPORT_SCHEMA,
            }
            and runtime_configuration_changed
        ):
            if receipt.get("reason") != "candidate_runtime_identity_correction":
                raise ConfigurationError("后继收据原因不是运行时身份纠正。")
            successor_runtime_configuration = {
                field: str(successor_configuration.get(field, "") or "")
                for field in runtime_fields
            }
            try:
                validated_runtime_configuration = _successor_runtime_configuration(
                    argparse.Namespace(
                        live_attestation_compose_dir=Path(
                            successor_runtime_configuration[
                                "live_attestation_compose_dir"
                            ]
                        ),
                        live_attestation_compose_files=(
                            successor_runtime_configuration[
                                "live_attestation_compose_files"
                            ]
                        ),
                        reason="candidate_runtime_identity_correction",
                    ),
                    predecessor_configuration,
                )
            except ConfigurationError as error:
                raise ConfigurationError(
                    "后继 Campaign 的 compose 坐标非法。"
                ) from error
            if validated_runtime_configuration != successor_runtime_configuration:
                raise ConfigurationError("后继 Campaign 的 compose 坐标漂移。")
            expected_transition.update(
                {
                    field: {
                        "predecessor": str(
                            predecessor_configuration.get(field, "") or ""
                        ),
                        "successor": value,
                        "reason": "candidate_runtime_identity_correction",
                    }
                    for field, value in successor_runtime_configuration.items()
                }
            )
        if (
            isinstance(predecessor_account_id, bool)
            or not isinstance(predecessor_account_id, int)
            or predecessor_account_id <= 0
            or isinstance(successor_account_id, bool)
            or not isinstance(successor_account_id, int)
            or successor_account_id <= 0
            or configuration_transition != expected_transition
        ):
            raise ConfigurationError("后继 Campaign 的运行配置过渡收据非法。")

    next_chain = frozenset({*import_chain, campaign_dir.resolve()})
    cache = import_cache if import_cache is not None else {}

    def load_predecessor_stage(stage: str) -> dict[str, Any]:
        key = (str(predecessor_dir.resolve()), stage, None)
        cached = cache.get(key)
        if cached is not None:
            return dict(cached)
        loaded = _load_stage_result(
            predecessor_dir,
            stage,
            _import_chain=next_chain,
            _replay_machine_receipts=(stage != "capture-official"),
            _import_cache=cache,
            _skip_evidence_scan=skip_evidence_scan,
            # 祖先阶段递归不得因中间 successor 类型不同而丢失历史上下文。
            _historical_manifest_controls=True,
        )
        cache[key] = dict(loaded)
        return loaded

    predecessor_official = load_predecessor_stage("capture-official")
    # 官方证据复用允许前序停在 official_sealed：导入收据没有登记 classify 阶段时，
    # 不加载也不要求前序分类；有登记时仍逐字校验。
    official_reuse_without_classification = (
        receipt.get("reason") == OFFICIAL_EVIDENCE_REUSE_REASON
        and reclassification_import
        and isinstance(receipt.get("stages"), dict)
        and "classify" not in receipt["stages"]
    )
    predecessor_classification = (
        None
        if sealed_stage_recovery_import or official_reuse_without_classification
        else load_predecessor_stage("classify")
    )
    if predecessor_official.get("status") != "complete":
        raise ConfigurationError("前序官方阶段已不满足完整承接条件。")
    if (
        not sealed_stage_recovery_import
        and not official_reuse_without_classification
        and (
            predecessor_classification is None
            or predecessor_classification.get("status") != "complete"
            or predecessor_classification.get("migration", {}).get(
                "unclassified_count"
            )
            != 0
        )
    ):
        raise ConfigurationError("前序批准分类已不满足完整承接条件。")

    stage_receipts = receipt.get("stages")
    expected_stage_ids = (
        {"capture-official"}
        if sealed_stage_recovery_import or official_reuse_without_classification
        else {"capture-official", "classify"}
    )
    if not isinstance(stage_receipts, dict) or set(stage_receipts) != expected_stage_ids:
        raise ConfigurationError("前序导入收据阶段闭集非法。")
    stage_expectations = {
        "capture-official": {
            "path": "official/result.json",
            "sha256": file_sha256(predecessor_dir / "official" / "result.json"),
            "package_digest": predecessor_official["package_digest"],
            "evidence_inventory_digest": predecessor_official[
                "evidence_inventory"
            ]["digest"],
            "security_sha256": _fingerprint(predecessor_official["security"]),
        },
    }
    if predecessor_classification is not None:
        stage_expectations["classify"] = {
            "path": "classification/result.json",
            "sha256": file_sha256(
                predecessor_dir / "classification" / "result.json"
            ),
            "package_digest": predecessor_classification["package_digest"],
            "joint_manifest_sha256": predecessor_classification[
                "joint_manifest_sha256"
            ],
        }
    if stage_receipts != stage_expectations:
        raise ConfigurationError("前序导入收据的阶段摘要或证据门禁发生漂移。")

    copied = receipt.get("copied_files")
    if not isinstance(copied, list):
        raise ConfigurationError("前序导入收据缺少复制文件闭集。")
    expected_copies = _successor_copy_expectations(
        campaign_dir,
        manifest,
        predecessor_dir,
        predecessor_manifest,
        predecessor_official,
        predecessor_classification,
        include_classification=not official_only_import,
        replace_target_scenario=(
            receipt_schema == PREDECESSOR_RUNTIME_SCENARIO_IMPORT_SCHEMA
        ),
    )
    copied_index: dict[str, dict[str, Any]] = {}
    for row in copied:
        if (
            not isinstance(row, dict)
            or set(row)
            != {
                "kind",
                "source_path",
                "target_path",
                "sha256",
                "bytes",
            }
            or not isinstance(row.get("source_path"), str)
            or not isinstance(row.get("target_path"), str)
            or row["target_path"] in copied_index
        ):
            raise ConfigurationError("前序导入复制文件条目非法或重复。")
        copied_index[row["target_path"]] = row
    if copied_index != expected_copies:
        raise ConfigurationError("前序导入复制文件闭集不完整或摘要漂移。")
    for relative, row in copied_index.items():
        target = _campaign_file(campaign_dir, relative)
        if (
            target.is_symlink()
            or not target.is_file()
            or file_sha256(target) != row["sha256"]
            or target.stat().st_size != row["bytes"]
        ):
            raise ConfigurationError(f"后继 Campaign 复制文件漂移：{relative}")

    abandoned = receipt.get("abandoned_candidate_attempt")
    if abandoned is not None:
        if (
            not isinstance(abandoned, dict)
            or set(abandoned)
            != {
                "candidate_id",
                "attempt_id",
                "path",
                "sha256",
                "attempt_digest",
                "identity_sha256",
                "status",
            }
        ):
            raise ConfigurationError("前序放弃 attempt 绑定结构非法。")
        attempt_campaign_dir = (
            Path(
                str(
                    replayed_control_replacement["source_campaign"][
                        "campaign_dir"
                    ]
                )
            )
            if control_replacement_import
            and replayed_control_replacement is not None
            else predecessor_dir
        )
        attempt_root, attempt = _load_capture_attempt(
            attempt_campaign_dir,
            "candidate",
            str(abandoned.get("candidate_id", "")),
            str(abandoned.get("attempt_id", "")),
            _historical_manifest_controls=(
                control_replacement_import or _historical_manifest_controls
            ),
        )
        expected_abandoned = {
            "candidate_id": attempt["candidate_id"],
            "attempt_id": attempt["attempt_id"],
            "path": (attempt_root / "attempt.json")
            .relative_to(attempt_campaign_dir)
            .as_posix(),
            "sha256": file_sha256(attempt_root / "attempt.json"),
            "attempt_digest": attempt["attempt_digest"],
            "identity_sha256": _fingerprint(attempt["identity"]),
            "status": attempt["status"],
        }
        if abandoned != expected_abandoned:
            raise ConfigurationError("前序放弃 attempt 身份或摘要漂移。")

    # 直接前序必须按其原始预约坐标重放；import 前序已经在递归加载时于自身
    # 原始绝对目录完成相同校验，不能把上游相对路径重新解释到当前目录。
    if predecessor_official.get("predecessor_import") is None:
        _validate_direct_predecessor_official_attempt(
            predecessor_dir,
            predecessor_official,
            _historical_manifest_controls=(
                control_replacement_import or _historical_manifest_controls
            ),
        )

    predecessor_stage = (
        predecessor_official
        if canonical == "capture-official"
        else predecessor_classification
    )
    if predecessor_stage is None:
        raise ConfigurationError("official-only 后继不得投影分类阶段。")
    if stage_payload.get("predecessor_package_digest") != predecessor_stage.get(
        "package_digest"
    ):
        raise ConfigurationError("导入阶段未绑定前序阶段 package digest。")
    projected = dict(predecessor_stage)
    for field in (
        "schema_version",
        "stage",
        "campaign_id",
        "campaign_mode",
        "campaign_purpose",
        "candidate_purpose",
        "campaign_manifest_sha256",
        "sealed_at_utc",
        "package_digest",
        "status",
        "predecessor_import",
        "predecessor_package_digest",
    ):
        projected[field] = stage_payload[field]
    if canonical == "capture-official":
        projected["surface"] = stage_payload["surface"]
    else:
        for field in (
            *_CLASSIFICATION_APPROVAL_FIELDS,
            "joint_manifest_sha256",
            "baseline_rule_count",
            "target_rule_count",
            "migration",
            "source_diff_sha256",
            "official_diff_sha256",
        ):
            projected[field] = stage_payload[field]
    _validate_stage_contract(projected)
    return projected


def _verify_predecessor_import_shallow(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> None:
    """只验证本 Campaign 的导入摘要，不打开前序目录。"""

    binding = payload.get("predecessor_import")
    _verify_campaign_binding(campaign_dir, binding, "前序导入收据")
    receipt_path = _campaign_file(campaign_dir, str(binding["path"]))
    receipt = _read_json(receipt_path, "前序导入收据")
    unsigned = dict(receipt)
    digest = unsigned.pop("receipt_digest", None)
    predecessor = manifest.get("predecessor")
    predecessor_binding = receipt.get("predecessor_campaign")
    if (
        not isinstance(predecessor, dict)
        or not isinstance(predecessor_binding, dict)
        or predecessor
        != {
            **predecessor_binding,
            "reason": receipt.get("reason"),
        }
        or receipt.get("successor_campaign_id") != manifest.get("campaign_id")
        or receipt.get("successor_campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or not SHA256_RE.fullmatch(str(digest))
        or digest != _fingerprint(unsigned)
    ):
        raise ConfigurationError("前序导入收据的本地摘要链不一致。")


def _imported_stage_checkpoint_path(
    campaign_dir: Path,
    canonical: str,
    candidate_id: str | None,
) -> Path:
    suffix = canonical if candidate_id is None else f"{canonical}-{candidate_id}"
    return campaign_dir / "verification-checkpoints" / f"{suffix}.json"


def _load_imported_stage_checkpoint(
    campaign_dir: Path,
    canonical: str,
    candidate_id: str | None,
    local_payload: Mapping[str, Any],
    *,
    _historical_manifest_controls: bool = False,
) -> dict[str, Any] | None:
    path = _imported_stage_checkpoint_path(campaign_dir, canonical, candidate_id)
    if not path.exists():
        return None
    if path.is_symlink() or not path.is_file():
        raise ConfigurationError("导入阶段 checkpoint 路径不可信。")
    payload = _read_json(path, "导入阶段 checkpoint")
    unsigned = dict(payload)
    digest = unsigned.pop("checkpoint_digest", None)
    projected = payload.get("projected_stage")
    _, local_stage_path = _stage_path(campaign_dir, canonical, candidate_id)
    import_binding = local_payload.get("predecessor_import")
    _require_file_binding(import_binding, "前序导入收据")
    import_path = _campaign_file(campaign_dir, str(import_binding["path"]))
    if (
        set(payload)
        != {
            "schema_version",
            "created_at_utc",
            "campaign_id",
            "campaign_manifest_sha256",
            "stage",
            "candidate_id",
            "local_stage_sha256",
            "predecessor_import_sha256",
            "projected_stage",
            "projected_stage_sha256",
            "checkpoint_digest",
        }
        or payload.get("schema_version") != IMPORTED_STAGE_CHECKPOINT_SCHEMA
        or payload.get("campaign_id")
        != load_campaign_manifest(
            campaign_dir,
            _control_epoch_bootstrap=_historical_manifest_controls,
        ).get("campaign_id")
        or payload.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or payload.get("stage") != canonical
        or payload.get("candidate_id") != candidate_id
        or payload.get("local_stage_sha256") != file_sha256(local_stage_path)
        or payload.get("predecessor_import_sha256") != file_sha256(import_path)
        or not isinstance(projected, dict)
        or payload.get("projected_stage_sha256") != _fingerprint(projected)
        or digest != _fingerprint(unsigned)
    ):
        raise ConfigurationError("导入阶段 checkpoint 身份或摘要不一致。")
    _validate_stage_contract(projected)
    if canonical == "capture-official" and projected.get("evidence_manifest") is not None:
        _stage_evidence_manifest(
            campaign_dir,
            projected,
            verify_boundary=True,
        )
    return dict(projected)


def _write_imported_stage_checkpoint(
    campaign_dir: Path,
    canonical: str,
    candidate_id: str | None,
    local_payload: Mapping[str, Any],
    projected: Mapping[str, Any],
) -> Path:
    existing_path = _imported_stage_checkpoint_path(
        campaign_dir,
        canonical,
        candidate_id,
    )
    if existing_path.exists() or existing_path.is_symlink():
        existing = _load_imported_stage_checkpoint(
            campaign_dir,
            canonical,
            candidate_id,
            local_payload,
        )
        if existing != dict(projected):
            raise ConfigurationError("导入阶段 checkpoint 与当前显式复验结果不一致。")
        return existing_path
    _, local_stage_path = _stage_path(campaign_dir, canonical, candidate_id)
    import_binding = local_payload.get("predecessor_import")
    _require_file_binding(import_binding, "前序导入收据")
    import_path = _campaign_file(campaign_dir, str(import_binding["path"]))
    core: dict[str, Any] = {
        "schema_version": IMPORTED_STAGE_CHECKPOINT_SCHEMA,
        "created_at_utc": _utc_now(),
        "campaign_id": load_campaign_manifest(campaign_dir)["campaign_id"],
        "campaign_manifest_sha256": file_sha256(campaign_dir / "campaign.json"),
        "stage": canonical,
        "candidate_id": candidate_id,
        "local_stage_sha256": file_sha256(local_stage_path),
        "predecessor_import_sha256": file_sha256(import_path),
        "projected_stage": dict(projected),
        "projected_stage_sha256": _fingerprint(projected),
    }
    checkpoint = {**core, "checkpoint_digest": _fingerprint(core)}
    path = existing_path
    ensure_private_directory(path.parent, campaign_dir)
    _write_or_verify_json(path, checkpoint)
    return path


def _load_stage_result(
    campaign_dir: Path,
    stage: str,
    candidate_id: str | None = None,
    *,
    _import_chain: frozenset[Path] | None = None,
    _replay_machine_receipts: bool = True,
    _shallow: bool = False,
    _ignore_checkpoint: bool = False,
    _import_cache: dict[tuple[str, str, str | None], dict[str, Any]] | None = None,
    _skip_evidence_scan: bool = False,
    _historical_manifest_controls: bool = False,
    _verified_campaign_manifest: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    # control epoch 的源上下文由外层清单校验触发。重放已写入 epoch 时若在这里
    # 再加载同一清单，会重新进入 control receipt 校验并形成无限递归。
    campaign_manifest = _require_formal_campaign(
        campaign_dir,
        (
            dict(_verified_campaign_manifest)
            if _verified_campaign_manifest is not None
            else load_campaign_manifest(
                campaign_dir,
                _control_epoch_bootstrap=_historical_manifest_controls,
            )
        ),
    )
    canonical, path = _stage_path(campaign_dir, stage, candidate_id)
    _reject_symlink_components(path, campaign_dir, f"{canonical} 阶段结果")
    if not path.is_file() or path.is_symlink():
        raise ConfigurationError(f"阶段尚未封存：{canonical}")
    payload = _read_json(path, f"{canonical} 阶段结果")
    expected = payload.get("package_digest")
    unsigned = dict(payload)
    unsigned.pop("package_digest", None)
    if not SHA256_RE.fullmatch(str(expected)) or _fingerprint(unsigned) != expected:
        raise ConfigurationError(f"{canonical} 阶段结果摘要不一致。")
    if payload.get("campaign_manifest_sha256") != file_sha256(
        campaign_dir / "campaign.json"
    ):
        raise ConfigurationError(f"{canonical} 未绑定当前 Campaign。")
    if (
        payload.get("stage") != canonical
        or payload.get("campaign_id") != campaign_manifest.get("campaign_id")
        or payload.get("campaign_mode") != campaign_manifest.get("campaign_mode")
        or payload.get("campaign_purpose")
        != campaign_manifest.get("campaign_purpose")
    ):
        raise ConfigurationError(f"{canonical} 阶段身份与路径不一致。")
    candidate_stage = canonical in {"capture-candidate", "compare", "accept"}
    if candidate_stage and payload.get("candidate_id") != candidate_id:
        raise ConfigurationError(f"{canonical} candidate-id 与路径不一致。")
    if not candidate_stage and "candidate_id" in payload:
        raise ConfigurationError(f"{canonical} 不得携带 candidate-id。")
    expected_candidate_purpose = (
        campaign_manifest.get("campaign_purpose") if candidate_stage else None
    )
    if payload.get("candidate_purpose") != expected_candidate_purpose:
        raise ConfigurationError(f"{canonical} candidate purpose 与 Campaign 不一致。")
    _validate_stage_contract(payload)
    if _shallow:
        if payload.get("predecessor_import") is not None:
            _verify_predecessor_import_shallow(
                campaign_dir,
                campaign_manifest,
                payload,
            )
        elif canonical in {"capture-official", "capture-candidate"}:
            _verify_campaign_binding(campaign_dir, payload.get("attempt"), "抓包 attempt")
            _verify_campaign_binding(campaign_dir, payload.get("seal_preview"), "seal 预览")
            if payload.get("evaluation_transition") is not None:
                _verify_campaign_binding(
                    campaign_dir,
                    payload.get("evaluation_transition"),
                    "评估工具 transition",
                )
            if payload.get("evidence_manifest") is not None:
                _stage_evidence_manifest(
                    campaign_dir,
                    payload,
                    verify_boundary=False,
                )
        elif canonical == "classify" and payload.get("status") in {
            "complete",
            "blocked",
        }:
            for field in (
                "target_rule_manifest",
                "migration_manifest",
                "scenario_manifest",
                "profile_manifest",
                "assertion_profile_manifest",
            ):
                _verify_campaign_binding(campaign_dir, payload.get(field), field)
        elif canonical == "accept" and payload.get("status") == "complete":
            candidate = _load_stage_result(
                campaign_dir,
                "capture-candidate",
                candidate_id,
                _replay_machine_receipts=False,
                _shallow=True,
                _historical_manifest_controls=_historical_manifest_controls,
            )
            _replay_bound_candidate_external_gate(
                payload.get("candidate_external_gate"),
                manifest=campaign_manifest,
                candidate_id=str(candidate_id),
                candidate=candidate,
            )
            _verify_campaign_binding(
                campaign_dir,
                payload.get("assertion_result"),
                "逐规则断言结果",
            )
            _verify_campaign_binding(
                campaign_dir,
                payload.get("evidence_seal"),
                "验收证据封印",
            )
        return payload
    if payload.get("predecessor_import") is not None:
        if not _ignore_checkpoint:
            checkpoint = _load_imported_stage_checkpoint(
                campaign_dir,
                canonical,
                candidate_id,
                payload,
                _historical_manifest_controls=_historical_manifest_controls,
            )
            if checkpoint is not None:
                return checkpoint
        projected = _validate_predecessor_import_receipt(
            campaign_dir,
            campaign_manifest,
            payload,
            canonical,
            _import_chain or frozenset(),
            import_cache=_import_cache,
            skip_evidence_scan=_skip_evidence_scan,
            _historical_manifest_controls=_historical_manifest_controls,
        )
        return projected
    if canonical in {"capture-official", "capture-candidate"}:
        _verify_campaign_binding(campaign_dir, payload.get("attempt"), "抓包 attempt")
        _verify_campaign_binding(
            campaign_dir, payload.get("seal_preview"), "seal 预览"
        )
        if payload.get("evaluation_transition") is not None:
            _verify_campaign_binding(
                campaign_dir,
                payload.get("evaluation_transition"),
                "评估工具 transition",
            )
        _verify_capture_seal_preview(
            campaign_dir,
            payload,
            canonical,
            _historical_manifest_controls=_historical_manifest_controls,
        )
        if _replay_machine_receipts:
            _replay_capture_stage_receipts(campaign_dir, payload, canonical)
        if _skip_evidence_scan:
            if payload.get("evidence_manifest") is not None:
                _stage_evidence_manifest(
                    campaign_dir,
                    payload,
                    verify_boundary=True,
                )
        else:
            _verify_stage_evidence(
                payload,
                "官方" if canonical == "capture-official" else "候选",
                campaign_dir=campaign_dir,
            )
    if canonical == "classify" and payload.get("status") in {"complete", "blocked"}:
        fields = (
            "target_rule_manifest",
            "migration_manifest",
            "scenario_manifest",
            "profile_manifest",
            "assertion_profile_manifest",
        )
        for field in fields:
            _verify_campaign_binding(campaign_dir, payload.get(field), field)
        expected_joint = _fingerprint(
            {field: payload[field]["sha256"] for field in fields}
        )
        if payload.get("joint_manifest_sha256") != expected_joint:
            raise ConfigurationError("分类五件套联合摘要不一致。")
    if canonical == "accept" and payload.get("status") == "complete":
        candidate = _load_stage_result(
            campaign_dir,
            "capture-candidate",
            candidate_id,
            _historical_manifest_controls=_historical_manifest_controls,
        )
        _replay_bound_candidate_external_gate(
            payload.get("candidate_external_gate"),
            manifest=campaign_manifest,
            candidate_id=str(candidate_id),
            candidate=candidate,
        )
        seal_path = _campaign_file(
            campaign_dir,
            str(payload["evidence_seal"]["path"]),
        )
        seal = _read_json(seal_path, "验收证据封印")
        expected_seal_coordinates = {
            "campaign_mode": payload.get("campaign_mode"),
            "campaign_purpose": payload.get("campaign_purpose"),
            "candidate_purpose": payload.get("candidate_purpose"),
            "production_state": payload.get("production_state"),
            "candidate_external_gate": payload.get("candidate_external_gate"),
        }
        if any(
            seal.get(field) != value
            for field, value in expected_seal_coordinates.items()
        ):
            raise ConfigurationError("验收证据封印的用途、状态或外部门禁绑定不一致。")
    return payload


def _verify_campaign_binding(
    campaign_dir: Path,
    reference: Any,
    label: str,
) -> None:
    _require_file_binding(reference, label)
    path = _campaign_file(campaign_dir, reference["path"])
    if path.is_symlink() or not path.is_file() or file_sha256(path) != reference["sha256"]:
        raise ConfigurationError(f"{label}在封存后漂移或丢失。")


def _verify_capture_seal_preview(
    campaign_dir: Path,
    stage: dict[str, Any],
    canonical: str,
    *,
    _historical_manifest_controls: bool = False,
) -> None:
    """证明阶段 payload 仍是人工批准的同一组机器事实。"""

    phase = "candidate" if canonical == "capture-candidate" else "official"
    candidate_id = stage.get("candidate_id") if phase == "candidate" else None
    attempt_path = _campaign_file(
        campaign_dir,
        str(stage["attempt"]["path"]),
    )
    attempt_payload = _read_json(attempt_path, "抓包 attempt")
    attempt_id = attempt_payload.get("attempt_id")
    if not isinstance(attempt_id, str):
        raise ConfigurationError("抓包 attempt 缺少 attempt-id。")
    attempt_root, attempt = _load_capture_attempt(
        campaign_dir,
        phase,
        candidate_id,
        attempt_id,
        _historical_manifest_controls=_historical_manifest_controls,
    )
    preview_path = _campaign_file(
        campaign_dir,
        str(stage["seal_preview"]["path"]),
    )
    if preview_path.parent != attempt_root:
        raise ConfigurationError("seal 预览与抓包 attempt 不在同一目录。")
    preview = _read_json(preview_path, "seal 预览")
    preview_schema = preview.get("schema_version")
    if preview_schema not in {LEGACY_SEAL_PREVIEW_SCHEMA, SEAL_PREVIEW_SCHEMA}:
        raise ConfigurationError("seal 预览 schema_version 不受支持。")

    envelope_fields = {
        "schema_version",
        "stage",
        "campaign_id",
        "candidate_id",
        "campaign_manifest_sha256",
        "sealed_at_utc",
        "package_digest",
        "result_schema_version",
        "seal_preview",
    }
    stage_payload = {
        key: value for key, value in stage.items() if key not in envelope_fields
    }
    transition_index = _seal_transition_index(
        stage_payload.get("evaluation_transition")
    )
    if preview_path != _seal_preview_path(attempt_root, transition_index):
        raise ConfigurationError("seal 预览与当前 transition 槽位不一致。")
    expected_core: dict[str, Any] = {
        "schema_version": preview_schema,
        "campaign_id": attempt["campaign_id"],
        "campaign_mode": attempt["campaign_mode"],
        "campaign_purpose": attempt["campaign_purpose"],
        "phase": phase,
        "candidate_id": candidate_id,
        "candidate_purpose": attempt["candidate_purpose"],
        "attempt_id": attempt_id,
        "attempt_digest": attempt["attempt_digest"],
        "stage_payload_sha256": _fingerprint(stage_payload),
        "evidence_inventory_digest": stage_payload["evidence_inventory"]["digest"],
        "assertion_manifest_sha256": stage_payload["assertion_context"][
            "capture_manifest"
        ]["sha256"],
        "restoration_report_sha256": stage_payload["restoration"]["report"][
            "sha256"
        ],
    }
    if preview_schema == SEAL_PREVIEW_SCHEMA:
        manifest = _stage_evidence_manifest(
            campaign_dir,
            stage_payload,
            verify_boundary=True,
        )
        draft = _load_seal_draft(
            campaign_dir,
            attempt_root,
            phase=phase,
            candidate_id=candidate_id,
            attempt=attempt,
            transition_index=transition_index,
        )
        if draft["stage_payload"] != stage_payload:
            raise ConfigurationError("阶段收据与冻结 seal 草案不一致。")
        expected_core.update(
            {
                "evidence_manifest_sha256": stage_payload["evidence_manifest"][
                    "sha256"
                ],
                "evidence_manifest_digest": manifest["manifest_digest"],
                "seal_draft_sha256": file_sha256(
                    _seal_draft_path(attempt_root, transition_index)
                ),
                "scan_summary": stage_payload["scan_summary"],
            }
        )
    if phase == "candidate":
        expected_core.update(
            {
                "post_client_restoration_sha256": stage_payload["restoration"]
                ["post_client"]["report"]["sha256"],
                "observed_profile_sha256": stage_payload["observed_profile"][
                    "sha256"
                ],
                "client_receipt_sha256": {
                    item["client_id"]: item["receipt"]["sha256"]
                    for item in stage_payload["client_bindings"]
                },
            }
        )
    review_sha256 = _fingerprint(expected_core)
    expected_preview = {
        **expected_core,
        "status": "approval_required",
        "review_sha256": review_sha256,
    }
    if preview != expected_preview:
        raise ConfigurationError("阶段收据与人工批准的 seal 预览不一致。")


def _latest_attempt_summary(
    campaign_dir: Path,
    phase: str,
    candidate_id: str | None,
    *,
    _manifest: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    """返回指定抓包边界最近一个可验证 attempt 的摘要。"""

    for path, reservation in _ordered_capture_attempts(
        campaign_dir,
        phase,
        candidate_id,
        _manifest=_manifest,
    ):
        attempt_path = path / "attempt.json"
        if not attempt_path.exists():
            return {
                "attempt_id": path.name,
                "status": "reserved_or_interrupted",
                "seal_preview": False,
                "run_nonce": reservation["run_nonce"],
                "attempt_started_at_utc": reservation["started_at_utc"],
                "evidence_root": None,
            }
        _, attempt = _load_capture_attempt(
            campaign_dir,
            phase,
            candidate_id,
            path.name,
            _verified_campaign_manifest=_manifest,
        )
        client_checkpoint_at: str | None = None
        if phase == "candidate":
            environment = attempt.get("environment")
            evidence_root = Path(
                str(environment.get("evidence_root", ""))
                if isinstance(environment, dict)
                else ""
            )
            checkpoint_receipt = (
                evidence_root / "receipts" / "client-restoration-report.json"
            )
            checkpoint_manifest = (
                evidence_root
                / "environment"
                / "client-after"
                / "probe-manifest.json"
            )
            checkpoint_present = checkpoint_receipt.exists() or checkpoint_manifest.exists()
            if checkpoint_present:
                if (
                    not checkpoint_receipt.is_file()
                    or checkpoint_receipt.is_symlink()
                    or not checkpoint_manifest.is_file()
                    or checkpoint_manifest.is_symlink()
                ):
                    raise ConfigurationError("Kilo 后检查点材料不完整或不可信。")
                _validate_restoration_report(
                    checkpoint_receipt,
                    [evidence_root],
                    phase="candidate",
                    candidate_id=str(candidate_id),
                )
                checkpoint = _read_json(
                    checkpoint_manifest, "Kilo 后探针清单"
                )
                if checkpoint.get("phase") != "after" or not _is_rfc3339_timestamp(
                    checkpoint.get("observed_at_utc")
                ):
                    raise ConfigurationError("Kilo 后探针清单身份或时间非法。")
                client_checkpoint_at = str(checkpoint["observed_at_utc"])
        preview_paths = [
            _seal_preview_path(path, index)
            for index in range(1, MAX_PHASE_EVALUATION_TRANSITIONS + 1)
            if _seal_preview_path(path, index).exists()
            or _seal_preview_path(path, index).is_symlink()
        ]
        preview_exists = bool(preview_paths)
        for preview_path in preview_paths:
            if preview_path.is_symlink() or not preview_path.is_file():
                raise ConfigurationError("seal 预览路径不可信。")
            preview = _read_json(preview_path, "seal 预览")
            core = {
                key: value
                for key, value in preview.items()
                if key not in {"status", "review_sha256"}
            }
            if (
                preview.get("schema_version")
                not in {LEGACY_SEAL_PREVIEW_SCHEMA, SEAL_PREVIEW_SCHEMA}
                or preview.get("campaign_id") != attempt.get("campaign_id")
                or preview.get("phase") != phase
                or preview.get("candidate_id") != candidate_id
                or preview.get("attempt_id") != path.name
                or preview.get("attempt_digest") != attempt.get("attempt_digest")
                or preview.get("status") != "approval_required"
                or preview.get("review_sha256") != _fingerprint(core)
            ):
                raise ConfigurationError("seal 预览身份或复核摘要不一致。")
        return {
            "attempt_id": path.name,
            "status": attempt["status"],
            "failed_job_ids": _failed_job_ids(attempt.get("results")),
            "seal_preview": preview_exists,
            "client_checkpoint_at_utc": client_checkpoint_at,
            "run_nonce": attempt["run_nonce"],
            "attempt_started_at_utc": attempt["started_at_utc"],
            "evidence_root": (
                attempt.get("environment", {}).get("evidence_root")
                if isinstance(attempt.get("environment"), dict)
                else None
            ),
        }
    return None


def _ordered_capture_attempts(
    campaign_dir: Path,
    phase: str,
    candidate_id: str | None,
    *,
    _historical_manifest_controls: bool = False,
    _manifest: Mapping[str, Any] | None = None,
) -> list[tuple[Path, dict[str, Any]]]:
    """按预约微秒时间倒序排列 attempt，编号仅作为同刻平局键。"""

    relative = _capture_attempt_relative(phase, candidate_id)
    root = campaign_dir / relative / "attempts"
    if not root.is_dir() or root.is_symlink():
        return []
    attempts: list[tuple[Path, dict[str, Any]]] = []
    for path in root.iterdir():
        if not path.is_dir() or path.is_symlink() or not SAFE_ID_RE.fullmatch(path.name):
            continue
        reservation = _load_capture_reservation(
            campaign_dir,
            path,
            phase=phase,
            candidate_id=candidate_id,
            _manifest=_manifest,
            _historical_manifest_controls=_historical_manifest_controls,
        )
        attempts.append((path, reservation))
    return sorted(
        attempts,
        key=lambda item: (
            _rfc3339_datetime(
                item[1]["started_at_utc"], "抓包预约 started_at_utc"
            ),
            item[0].name,
        ),
        reverse=True,
    )


def _campaign_attempt_roots(
    campaign_dir: Path,
) -> list[tuple[str, str | None, Path]]:
    """枚举 Campaign 内全部正式 attempt 目录，忽略未发布的隐藏临时目录。"""

    scopes: list[tuple[str, str | None, Path]] = [
        ("official", None, campaign_dir / "official" / "attempts")
    ]
    candidates_root = campaign_dir / "candidates"
    if candidates_root.exists():
        if candidates_root.is_symlink() or not candidates_root.is_dir():
            raise ConfigurationError("候选抓包目录不可信。")
        for candidate_root in sorted(candidates_root.iterdir()):
            if not candidate_root.is_dir() or candidate_root.is_symlink():
                continue
            if not SAFE_ID_RE.fullmatch(candidate_root.name):
                raise ConfigurationError("候选抓包目录包含非法 candidate-id。")
            scopes.append(
                (
                    "candidate",
                    candidate_root.name,
                    candidate_root / "attempts",
                )
            )

    attempts: list[tuple[str, str | None, Path]] = []
    for phase, current_candidate_id, attempts_root in scopes:
        if not attempts_root.exists():
            continue
        if attempts_root.is_symlink() or not attempts_root.is_dir():
            raise ConfigurationError("抓包 attempts 目录不可信。")
        for attempt_root in sorted(attempts_root.iterdir()):
            if not attempt_root.is_dir() or attempt_root.is_symlink():
                continue
            if not SAFE_ID_RE.fullmatch(attempt_root.name):
                if attempt_root.name.startswith(".reservation-"):
                    continue
                raise ConfigurationError("抓包目录包含非法 attempt-id。")
            attempts.append((phase, current_candidate_id, attempt_root))
    return attempts


def _campaign_contamination_records(
    campaign_dir: Path,
    *,
    _manifest: Mapping[str, Any] | None = None,
) -> list[str]:
    """从主 attempt／seal 失败事实推导污染，旁路 marker 仅作冗余提示。"""

    records: list[str] = []
    marker = campaign_dir / "environment-contaminated.json"
    if marker.exists() or marker.is_symlink():
        records.append("campaign-marker")
    for phase, current_candidate_id, attempt_root in _campaign_attempt_roots(
        campaign_dir
    ):
        _load_capture_reservation(
            campaign_dir,
            attempt_root,
            phase=phase,
            candidate_id=current_candidate_id,
            _manifest=_manifest,
        )
        attempt_path = attempt_root / "attempt.json"
        if attempt_path.exists() or attempt_path.is_symlink():
            if attempt_path.is_symlink() or not attempt_path.is_file():
                raise ConfigurationError("抓包 attempt 收据路径不可信。")
            _, attempt = _load_capture_attempt(
                campaign_dir,
                phase,
                current_candidate_id,
                attempt_root.name,
                _verified_campaign_manifest=_manifest,
            )
            if attempt.get("status") == "environment_contaminated":
                records.append(
                    f"{current_candidate_id or phase}:{attempt_root.name}:attempt"
                )
        seal_failure = attempt_root / "seal-failure.json"
        if seal_failure.exists() or seal_failure.is_symlink():
            if seal_failure.is_symlink() or not seal_failure.is_file():
                raise ConfigurationError("候选 seal 失败收据路径不可信。")
            failure = _read_json(seal_failure, "候选 seal 失败收据")
            failure_digest = failure.get("failure_digest")
            unsigned_failure = dict(failure)
            unsigned_failure.pop("failure_digest", None)
            reservation = _load_capture_reservation(
                campaign_dir,
                attempt_root,
                phase=phase,
                candidate_id=current_candidate_id,
                _manifest=_manifest,
            )
            if (
                phase != "candidate"
                or failure.get("schema_version") != SEAL_FAILURE_SCHEMA
                or failure.get("campaign_id") != reservation.get("campaign_id")
                or failure.get("campaign_mode") != reservation.get("campaign_mode")
                or failure.get("campaign_purpose")
                != reservation.get("campaign_purpose")
                or failure.get("candidate_purpose")
                != reservation.get("candidate_purpose")
                or failure.get("campaign_manifest_sha256")
                != reservation.get("campaign_manifest_sha256")
                or failure.get("phase") != "candidate"
                or failure.get("candidate_id") != current_candidate_id
                or failure.get("attempt_id") != attempt_root.name
                or failure.get("run_nonce") != reservation.get("run_nonce")
                or not _is_rfc3339_timestamp(failure.get("failed_at_utc"))
                or failure.get("reason") != "Kilo 后环境恢复门禁失败"
                or not isinstance(failure.get("error_type"), str)
                or not failure["error_type"]
                or not SHA256_RE.fullmatch(str(failure_digest))
                or _fingerprint(unsigned_failure) != failure_digest
            ):
                raise ConfigurationError("候选 seal 失败收据身份或摘要不一致。")
            records.append(
                f"{current_candidate_id or phase}:{attempt_root.name}:seal"
            )
    # 旧工具可能把 metadata-only attempt 缺少恢复收据误记成污染。收据已经
    # 由受管修复路径生成并可独立重放后，该冗余 marker／seal-failure 不再
    # 阻断后续的 canonical seal；其他污染事实仍原样保留。
    if records:
        for phase, current_candidate_id, attempt_root in _campaign_attempt_roots(
            campaign_dir
        ):
            if phase != "candidate" or current_candidate_id is None:
                continue
            attempt_path = attempt_root / "attempt.json"
            if not attempt_path.is_file() or attempt_path.is_symlink():
                continue
            try:
                _, attempt = _load_capture_attempt(
                    campaign_dir,
                    phase,
                    current_candidate_id,
                    attempt_root.name,
                    _historical_manifest_controls=True,
                )
            except (ConfigurationError, OSError, ValueError):
                continue
            seal_record = f"{current_candidate_id}:{attempt_root.name}:seal"
            if (
                seal_record in records
                and "campaign-marker" in records
                and _metadata_only_seal_repair_allowed(
                    campaign_dir,
                    attempt_root,
                    attempt,
                    {"campaign-marker", seal_record},
                )
                and _metadata_only_repair_receipt_complete(attempt_root, attempt)
            ):
                records = [
                    item
                    for item in records
                    if item not in {"campaign-marker", seal_record}
                ]
                break
    return records


def _metadata_only_seal_repair_allowed(
    campaign_dir: Path,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    contamination_records: Iterable[str],
) -> bool:
    """判断旧工具留下的 metadata-only 恢复收据缺口是否可安全修复。

    旧版在 metadata-only seal 尚未生成 ``client-restoration-report.json``
    时，会把缺少收据误记为环境污染。只有零执行、九项全复用、没有任何
    深度扫描／seal 草案，且污染事实只来自该 attempt 的 seal 失败时，才
    允许进入一次性收据修复；真实环境探针失败或其他 attempt 的污染仍拒绝。
    """

    records = set(str(item) for item in contamination_records)
    candidate_id = attempt.get("candidate_id")
    attempt_id = attempt.get("attempt_id")
    if (
        attempt.get("phase") != "candidate"
        or attempt.get("status") != "awaiting_receipts"
        or not isinstance(candidate_id, str)
        or not isinstance(attempt_id, str)
        or records
        != {"campaign-marker", f"{candidate_id}:{attempt_id}:seal"}
        or not isinstance(attempt.get("classification_candidate_reuse_transition"), Mapping)
    ):
        return False
    plan = attempt.get("incremental_plan")
    results = attempt.get("results")
    if (
        not isinstance(plan, Mapping)
        or any(plan.get(name) for name in ("executed_job_ids", "failed_job_ids", "pending_job_ids"))
        or not isinstance(results, list)
        or not results
        or any(
            not isinstance(result, Mapping)
            or result.get("status") != "complete"
            or result.get("disposition") != "reused"
            for result in results
        )
    ):
        return False
    environment = attempt.get("environment")
    if not isinstance(environment, Mapping):
        return False
    expected_environment_fields = {
        "evidence_root",
        "before_probe",
        "after_probe",
        "restoration_report",
        "arm64_before_receipt",
        "arm64_after_receipt",
    }
    if (
        set(environment) != expected_environment_fields
        or any(environment.get(name) is not None for name in expected_environment_fields - {"evidence_root"})
    ):
        return False
    evidence_root_raw = environment.get("evidence_root")
    if not isinstance(evidence_root_raw, str) or not Path(evidence_root_raw).is_absolute():
        return False
    evidence_root = Path(evidence_root_raw)
    restoration_report = evidence_root / "receipts" / "client-restoration-report.json"
    client_after = evidence_root / "environment" / "client-after"
    if restoration_report.is_symlink() or not client_after.is_dir():
        return False
    # deep-verify 与首次 seal 可能已经为这个零执行 attempt 生成了来源清单、
    # draft 或 preview。只要来源 EvidenceManifest 已显式封存，且恢复收据可重放，
    # 这些派生文件仍属于同一 metadata-only 链；批准阶段必须能够承接它们，
    # 不能被旧的污染 marker 再次自锁。来源清单缺失时仍保持旧的 fail-closed。
    derived_artifacts = (
        attempt_root / "evidence-manifest.json",
        attempt_root / "seal-draft.json",
        attempt_root / "seal-preview.json",
        attempt_root / "seal-preview-1.json",
    )
    if any(path.exists() or path.is_symlink() for path in derived_artifacts):
        source_manifest = (
            attempt_root / CLASSIFICATION_CANDIDATE_REUSE_SOURCE_MANIFEST_FILENAME
        )
        if source_manifest.is_symlink() or not source_manifest.is_file():
            return False
    return True


def _metadata_only_repair_receipt_complete(
    attempt_root: Path,
    attempt: Mapping[str, Any],
) -> bool:
    """验证 metadata-only 修复已经生成可重放的 Kilo 后恢复收据。"""

    environment = attempt.get("environment")
    if not isinstance(environment, Mapping):
        return False
    evidence_root_raw = environment.get("evidence_root")
    if not isinstance(evidence_root_raw, str) or not Path(evidence_root_raw).is_absolute():
        return False
    evidence_root = Path(evidence_root_raw)
    receipt_path = evidence_root / "receipts" / "client-restoration-report.json"
    probe_path = evidence_root / "environment" / "client-after" / "probe-manifest.json"
    if (
        receipt_path.is_symlink()
        or not receipt_path.is_file()
        or probe_path.is_symlink()
        or not probe_path.is_file()
    ):
        return False
    try:
        replay_receipt(
            receipt_path,
            evidence_root,
            expected_subcommand="restoration",
        )
        probe = _read_json(probe_path, "metadata-only Kilo 后探针清单")
    except (ReceiptFinalizerError, OSError, ValueError, ConfigurationError):
        return False
    return (
        probe.get("phase") == "after"
        and _is_rfc3339_timestamp(probe.get("observed_at_utc"))
    )


def _reject_contaminated_campaign(
    campaign_dir: Path,
    *,
    allow_metadata_only_repair: bool = False,
    attempt_root: Path | None = None,
    attempt: Mapping[str, Any] | None = None,
) -> None:
    """任何主污染事实存在时，除只读 status 外禁止继续使用 Campaign。

    ``allow_metadata_only_repair`` 只由候选 seal 的一次性收据修复路径传入，
    且必须再次通过零执行边界校验；它不放宽普通 run、resume、compare 或
    production 写入入口。
    """

    records = _campaign_contamination_records(campaign_dir)
    if records:
        if (
            allow_metadata_only_repair
            and attempt_root is not None
            and attempt is not None
            and _metadata_only_seal_repair_allowed(
                campaign_dir,
                attempt_root,
                attempt,
                records,
            )
        ):
            return
        raise ConfigurationError(
            "环境恢复失败已封锁 Campaign；只能只读 status，并在人工恢复后新建 "
            f"Campaign。污染事实={records}"
        )


def _campaign_lease_status(
    campaign_dir: Path,
    *,
    campaign_id: str | None = None,
) -> dict[str, Any]:
    """生成只读租约摘要；不会续租、接管或修改任何文件。"""

    payload = _read_campaign_lease(campaign_dir)
    stop_receipts = _read_campaign_lease_stop_receipts(
        campaign_dir,
        campaign_id=campaign_id,
    )
    if payload is None:
        return {
            "present": False,
            "state": None,
            "stale": False,
            "owner_alive": False,
            "deadline_expired": False,
            "stop_receipt_count": len(stop_receipts),
        }
    stale, reason, owner_alive, deadline_expired = _campaign_lease_staleness(payload)
    return {
        "present": True,
        "state": payload["state"],
        "phase": payload["phase"],
        "candidate_id": payload["candidate_id"],
        "attempt_id": payload["attempt_id"],
        "owner_pid": payload["owner_pid"],
        "owner_nonce": payload["owner_nonce"],
        "started_at_utc": payload["started_at_utc"],
        "deadline_at_utc": payload["deadline_at_utc"],
        "last_heartbeat_at_utc": payload["last_heartbeat_at_utc"],
        "operation": payload["operation"],
        "stale": stale,
        "stale_reason": reason or None,
        "owner_alive": owner_alive,
        "deadline_expired": deadline_expired,
        "stop_receipt_count": len(stop_receipts),
    }


def campaign_status(
    campaign_dir: Path,
    candidate_id: str | None = None,
) -> dict[str, Any]:
    """从不可变阶段收据推导状态，不回写 Campaign 核心清单。"""

    if candidate_id is not None and not SAFE_ID_RE.fullmatch(candidate_id):
        raise ConfigurationError("status --candidate-id 格式非法。")
    # status 是只读浅检查：阶段和 attempt 会做廉价摘要校验，完整 control
    # epoch 链由正式写入／seal／VC-6 动作重放；不能让历史链递归扫描阻塞状态查询。
    manifest = load_campaign_manifest(campaign_dir, _skip_control_validation=True)
    mode, purpose = _campaign_coordinates(manifest)
    lease_status = _campaign_lease_status(
        campaign_dir,
        campaign_id=str(manifest.get("campaign_id", "")),
    )
    lease_stop_receipts = _read_campaign_lease_stop_receipts(
        campaign_dir,
        campaign_id=str(manifest.get("campaign_id", "")),
    )
    if mode == "preflight_only":
        forbidden = [
            name
            for name in (
                "official",
                "classification",
                "candidates",
                "comparisons",
                "acceptance",
                "assertions",
            )
            if (campaign_dir / name).exists() or (campaign_dir / name).is_symlink()
        ]
        if forbidden:
            raise ConfigurationError(
                "preflight_only Campaign 出现正式阶段制品，拒绝 continuation："
                f"{forbidden}"
            )
        return {
            "schema_version": "codex-upgrade-status/v2",
            "verification_mode": "shallow",
            "raw_evidence_scanned_bytes": 0,
            "campaign_id": manifest["campaign_id"],
            "campaign_mode": mode,
            "campaign_purpose": purpose,
            "status": "preflight_complete",
            "stages": {},
            "candidates": [],
            "comparisons": [],
            "accepted_candidates": [],
            "candidate_states": {},
            "candidate_purposes": {},
            "candidate_production_states": {},
            "production_status": None,
            "official_attempt": None,
            "candidate_attempt": None,
            "selected_candidate_id": candidate_id,
            "active_unsealed_attempts": {"official": [], "candidate": []},
            "failed_attempts": {"official": [], "candidate": []},
            "contamination_records": [],
            "campaign_lease": lease_status,
            "campaign_lease_stop_receipts": lease_stop_receipts,
            "next_command": (
                "P0 结果通过后，以 --campaign-mode formal 和同一 "
                "--campaign-purpose 创建新的持久 Campaign"
            ),
        }
    stage_status: dict[str, Any] = {}
    for stage in ("capture-official", "classify"):
        try:
            stage_status[stage] = _load_stage_result(
                campaign_dir,
                stage,
                _replay_machine_receipts=False,
                _shallow=True,
                _verified_campaign_manifest=manifest,
            ).get(
                "status", "unknown"
            )
        except ConfigurationError as error:
            if "尚未封存" not in str(error):
                raise
            stage_status[stage] = "pending"
    candidates_root = campaign_dir / "candidates"
    candidates = sorted(
        path.name
        for path in candidates_root.iterdir()
        if (
            path.is_dir()
            and not path.is_symlink()
            and SAFE_ID_RE.fullmatch(path.name)
            and (path / "result.json").is_file()
            and not (path / "result.json").is_symlink()
        )
    ) if candidates_root.is_dir() else []
    comparisons: list[str] = []
    acceptance: list[str] = []
    candidate_states: dict[str, str] = {}
    candidate_purposes: dict[str, str] = {}
    candidate_production_states: dict[str, str] = {}
    for current_candidate_id in candidates:
        candidate_stage = _load_stage_result(
            campaign_dir,
            "capture-candidate",
            current_candidate_id,
            _replay_machine_receipts=False,
            _shallow=True,
            _verified_campaign_manifest=manifest,
        )
        if candidate_stage.get("status") != "complete":
            raise ConfigurationError("候选抓包阶段尚未完整封存。")
        candidate_purposes[current_candidate_id] = str(
            candidate_stage["candidate_purpose"]
        )
        candidate_states[current_candidate_id] = "candidate_sealed"
        for stage, output in (("compare", comparisons), ("accept", acceptance)):
            try:
                value = _load_stage_result(
                    campaign_dir,
                    stage,
                    current_candidate_id,
                    _replay_machine_receipts=False,
                    _shallow=True,
                    _verified_campaign_manifest=manifest,
                )
            except ConfigurationError as error:
                if "尚未封存" not in str(error):
                    raise
                continue
            if value.get("status") == "complete":
                output.append(current_candidate_id)
                candidate_states[current_candidate_id] = (
                    "ready" if stage == "accept" else "compared"
                )
                if stage == "accept":
                    candidate_production_states[current_candidate_id] = str(
                        value["production_state"]
                    )
                    _verify_campaign_binding(
                        campaign_dir, value.get("assertion_result"), "逐规则断言结果"
                    )
                    _verify_campaign_binding(
                        campaign_dir, value.get("evidence_seal"), "验收证据封印"
                    )
    contamination_records = _campaign_contamination_records(
        campaign_dir,
        _manifest=manifest,
    )
    contaminated = bool(contamination_records)
    active_unsealed = {
        "official": _active_unsealed_attempts(
            campaign_dir,
            "official",
            _manifest=manifest,
        ),
        "candidate": _active_unsealed_attempts(
            campaign_dir,
            "candidate",
            _manifest=manifest,
        ),
    }
    failed_attempts = {
        "official": _failed_capture_attempts(
            campaign_dir,
            "official",
            _manifest=manifest,
        ),
        "candidate": _failed_capture_attempts(
            campaign_dir,
            "candidate",
            _manifest=manifest,
        ),
    }
    official_attempt = (
        None
        if stage_status["capture-official"] == "complete"
        else _latest_attempt_summary(
            campaign_dir,
            "official",
            None,
            _manifest=manifest,
        )
    )
    candidate_attempt = (
        _latest_attempt_summary(
            campaign_dir,
            "candidate",
            candidate_id,
            _manifest=manifest,
        )
        if candidate_id is not None and candidate_id not in candidate_states
        else None
    )
    if contaminated:
        status = "environment_contaminated"
        next_command = "人工恢复并证明环境洁净后新建 Campaign"
    elif (
        stage_status["capture-official"] == "complete"
        and active_unsealed["official"]
    ) or (
        candidate_id is not None
        and candidate_id in candidate_states
        and active_unsealed["candidate"]
    ):
        status = "capture_state_inconsistent"
        next_command = "人工审计额外未封存预约并新建 Campaign"
    elif candidate_id is not None and candidate_id in candidate_states:
        status = candidate_states[candidate_id]
        if status == "ready":
            next_command = (
                "validation_only 已验收交付，禁止进入生产激活"
                if candidate_purposes[candidate_id] == "validation_only"
                else (
                    "必须继续 Codex 手册 §4.6；在 promotion、canary、activation "
                    "和 rollback 收据完成前不得宣称生产升级完成"
                )
            )
        else:
            next_command = {
                "candidate_sealed": "compare",
                "compared": "accept",
            }[status]
    elif candidate_attempt is not None:
        if candidate_attempt["status"] == "reserved_or_interrupted":
            status = "candidate_capture_interrupted"
            next_command = "人工审计孤儿预约并新建 Campaign；不得自动重跑"
        elif candidate_attempt["status"] == "awaiting_receipts":
            if candidate_attempt.get("failed_job_ids"):
                status = "candidate_capture_failed"
                next_command = (
                    "存在失败 Job，禁止 seal；使用 resume --rerun-failed，"
                    "产出侧变化须先建立同版本后继"
                )
            elif candidate_attempt["seal_preview"]:
                status = "candidate_awaiting_seal_approval"
                next_command = (
                    "capture-candidate seal --approve-seal-sha256 <review_sha256>"
                )
            elif candidate_attempt.get("client_checkpoint_at_utc"):
                status = "candidate_client_checkpoint_created"
                next_command = "生成 nonce／时间绑定收据后重新执行 capture-candidate seal"
            else:
                status = "candidate_awaiting_client_checkpoint"
                next_command = "Kilo 两入口完成后执行首次 capture-candidate seal"
        else:
            status = "candidate_capture_failed"
            next_command = "修复失败任务后使用 resume --rerun-failed"
    elif candidate_id is None and (
        active_unsealed["candidate"] or failed_attempts["candidate"]
    ):
        status = "candidate_selection_required"
        next_command = "从 attempt 列表选择原 candidate-id 执行 status／seal／resume"
    elif candidate_id is not None and stage_status["classify"] == "complete":
        status = "profile_approved"
        next_command = "capture-candidate"
    elif acceptance:
        status = "ready"
        next_command = "指定 --candidate-id 查看或续跑单个候选"
    elif comparisons:
        status = "compared"
        next_command = "指定 --candidate-id 执行 accept"
    elif candidates:
        status = "candidate_sealed"
        next_command = "指定 --candidate-id 执行 compare"
    elif stage_status["classify"] == "blocked":
        status = "blocked"
        next_command = "解决阻塞并创建新的分类 revision"
    elif stage_status["classify"] == "complete":
        status = "profile_approved"
        next_command = "capture-candidate"
    elif stage_status["capture-official"] == "complete":
        status = "official_sealed"
        next_command = "classify"
    elif official_attempt is not None:
        if official_attempt["status"] == "reserved_or_interrupted":
            status = "official_capture_interrupted"
            next_command = "人工审计孤儿预约并新建 Campaign；不得自动重跑"
        elif official_attempt["status"] == "awaiting_receipts":
            status = (
                "official_awaiting_seal_approval"
                if official_attempt["seal_preview"]
                else "official_awaiting_receipts"
            )
            next_command = (
                "capture-official seal --approve-seal-sha256 <review_sha256>"
                if official_attempt["seal_preview"]
                else "完成机器 finalizer 后执行 capture-official seal"
            )
        else:
            status = "official_capture_failed"
            next_command = "修复失败任务后使用 resume --rerun-failed"
    else:
        status = "planned"
        next_command = "capture-official"
    return {
        "schema_version": "codex-upgrade-status/v2",
        "verification_mode": "shallow",
        "raw_evidence_scanned_bytes": 0,
        "campaign_id": manifest["campaign_id"],
        "campaign_mode": mode,
        "campaign_purpose": purpose,
        "status": status,
        "stages": stage_status,
        "candidates": candidates,
        "comparisons": comparisons,
        "accepted_candidates": acceptance,
        "candidate_states": candidate_states,
        "candidate_purposes": candidate_purposes,
        "candidate_production_states": candidate_production_states,
        "production_status": (
            candidate_production_states.get(candidate_id)
            if candidate_id is not None
            else None
        ),
        "official_attempt": official_attempt,
        "candidate_attempt": candidate_attempt,
        "selected_candidate_id": candidate_id,
        "active_unsealed_attempts": active_unsealed,
        "failed_attempts": failed_attempts,
        "contamination_records": contamination_records,
        "campaign_lease": lease_status,
        "campaign_lease_stop_receipts": lease_stop_receipts,
        "next_command": next_command,
    }


def _campaign_arguments(
    campaign_dir: Path,
    manifest: dict[str, Any],
    *,
    candidate_id: str | None = None,
    runtime_image: str | None = None,
    profile_id: str | None = None,
    profile_digest: str | None = None,
    build_id: str | None = None,
    deployed_version: str | None = None,
    candidate_image_id: str | None = None,
    source_tree_sha256: str | None = None,
    candidate_purpose: str | None = None,
) -> argparse.Namespace:
    configuration = manifest["configuration"]
    run_id = manifest["campaign_id"]
    if candidate_id:
        run_id = f"{run_id}-{candidate_id}"
    inputs = manifest.get("inputs", {})
    extra_reference = inputs.get("extra_jobs")
    # v2 历史 Campaign 没有双清单坐标，仍允许只读重放其冻结事实；新 Campaign
    # 一律由 plan 写入 target_discovery_scenarios，并以它生成 official jobs。
    target_scenario_reference = inputs.get("target_discovery_scenarios")
    execution_scenario_reference = (
        target_scenario_reference or inputs["discovery_scenarios"]
    )
    return argparse.Namespace(
        command="capture-candidate" if candidate_id else "capture-official",
        baseline_version=manifest["baseline_version"],
        target_version=manifest["target_version"],
        baseline_source=Path(configuration["baseline_source"]),
        target_source=Path(configuration["target_source"]),
        baseline_evidence=Path(configuration["baseline_evidence"]),
        target_sha256=manifest["target_sha256"],
        target_package=Path(configuration["target_package"]),
        target_package_sha256=manifest["official_identity"]["package"][
            "asset_sha256"
        ],
        target_code_mode_host_sha256=manifest["official_identity"]["package"][
            "code_mode_host_sha256"
        ],
        target_package_identity=manifest["official_identity"]["package"],
        runtime_image=runtime_image or configuration["runtime_image"],
        output=campaign_dir,
        campaign_dir=campaign_dir,
        rule_manifest=_campaign_file(
            campaign_dir, inputs["baseline_rules"]["path"]
        ),
        scenario_manifest=_campaign_file(
            campaign_dir, execution_scenario_reference["path"]
        ),
        target_scenario_manifest=(
            _campaign_file(campaign_dir, target_scenario_reference["path"])
            if target_scenario_reference
            else None
        ),
        extra_jobs=(
            _campaign_file(campaign_dir, extra_reference["path"])
            if extra_reference
            else None
        ),
        suite=manifest["suite"],
        campaign_id=run_id,
        campaign_mode=manifest["campaign_mode"],
        campaign_purpose=manifest["campaign_purpose"],
        model=configuration["model"],
        # 历史 Campaign Schema 尚无 lite_model；只按其冻结 target_version
        # 恢复当时受管轨道。新 Campaign 在 plan 阶段必须显式写入该字段。
        lite_model=(
            configuration.get("lite_model")
            or track_models_for_version(manifest["target_version"], "lite")[0]
        ),
        capture_root=Path(configuration["capture_root"]),
        capture_container=configuration["capture_container"],
        service_container=configuration["service_container"],
        keeper_container=configuration["keeper_container"],
        postgres_container=configuration["postgres_container"],
        redis_container=configuration["redis_container"],
        capture_codex_bin=configuration["capture_codex_bin"],
        relay_codex_bin=configuration["relay_codex_bin"],
        capture_code_mode_host_bin=configuration["capture_code_mode_host_bin"],
        relay_code_mode_host_bin=configuration["relay_code_mode_host_bin"],
        codex_account_id=int(configuration["codex_account_id"]),
        api_key_id=int(configuration["api_key_id"]),
        live_attestation_compose_dir=str(
            configuration.get("live_attestation_compose_dir", "") or ""
        ),
        live_attestation_compose_files=str(
            configuration.get("live_attestation_compose_files", "") or ""
        ),
        candidate_id=candidate_id,
        profile_id=profile_id,
        profile_digest=profile_digest,
        build_id=build_id,
        deployed_version=deployed_version,
        candidate_image_id=candidate_image_id,
        source_tree_sha256=source_tree_sha256,
        candidate_purpose=candidate_purpose,
        max_wall_seconds=None,
        heartbeat_seconds=None,
    )


def _approved_rules(
    campaign_dir: Path,
    manifest: dict[str, Any],
    *,
    require_approved: bool,
) -> tuple[str, ...]:
    if require_approved:
        classification = _load_stage_result(campaign_dir, "classify")
        if classification.get("status") != "complete":
            raise ConfigurationError("目标规则迁移尚未批准。")
        reference = classification.get("target_rule_manifest")
        if not isinstance(reference, dict):
            raise ConfigurationError("分类收据缺少目标规则清单。")
        path = _campaign_file(campaign_dir, str(reference.get("path", "")))
        if not path.is_file() or file_sha256(path) != reference.get("sha256"):
            raise ConfigurationError("目标规则清单摘要不一致。")
        return load_rule_manifest(path, manifest["target_version"])
    reference = manifest["inputs"]["baseline_rules"]
    return load_rule_manifest(
        _campaign_file(campaign_dir, reference["path"]),
        manifest["baseline_version"],
    )


def _campaign_jobs(
    campaign_dir: Path,
    manifest: dict[str, Any],
    phase: str,
    *,
    candidate_id: str | None = None,
    runtime_image: str | None = None,
    profile_id: str | None = None,
    profile_digest: str | None = None,
    build_id: str | None = None,
    deployed_version: str | None = None,
    candidate_image_id: str | None = None,
    source_tree_sha256: str | None = None,
    candidate_purpose: str | None = None,
    use_approved_scenario: bool | None = None,
) -> list[Job]:
    arguments = _campaign_arguments(
        campaign_dir,
        manifest,
        candidate_id=candidate_id,
        runtime_image=runtime_image,
        profile_id=profile_id,
        profile_digest=profile_digest,
        build_id=build_id,
        deployed_version=deployed_version,
        candidate_image_id=candidate_image_id,
        source_tree_sha256=source_tree_sha256,
        candidate_purpose=candidate_purpose,
    )
    approved_target = (
        phase == "candidate"
        if use_approved_scenario is None
        else use_approved_scenario
    )
    historical_source_spec_binding: HistoricalSourceSpecBinding | None = None
    execution_scenario_override: dict[str, Any] | None = None
    if approved_target:
        classification = _load_stage_result(campaign_dir, "classify")
        if classification.get("status") != "complete":
            raise ConfigurationError("目标版本场景尚未批准。")
        scenario_reference = classification.get("scenario_manifest")
        if not isinstance(scenario_reference, dict):
            raise ConfigurationError("分类收据缺少目标场景清单。")
        scenario_path = _campaign_file(
            campaign_dir, str(scenario_reference.get("path", ""))
        )
        if (
            not scenario_path.is_file()
            or scenario_path.is_symlink()
            or file_sha256(scenario_path) != scenario_reference.get("sha256")
        ):
            raise ConfigurationError("目标场景清单摘要不一致。")
        arguments.scenario_manifest = scenario_path
        selected_scenario = _read_json(scenario_path, "Campaign 批准场景清单")
        selected_binding = _scenario_source_spec_binding(
            selected_scenario,
            label="Campaign 批准场景清单",
        )
        source_path_text, _, fragment = selected_binding.source_spec.partition("#")
        current_source = Path(__file__).resolve().parents[2] / source_path_text
        if current_source.is_file() and not current_source.is_symlink():
            current_source_sha256 = source_spec_section_sha256(
                current_source,
                fragment,
            )
            if selected_binding.source_spec_sha256 != current_source_sha256:
                # 控制刷新后继会逐字保留前序批准场景。只有 Formal 冻结场景
                # 与当前受管场景除 source_spec.sha256 外完全相同，且当前批准
                # 场景仍等于 Formal 冻结字节时，恢复读取才可承接历史摘要。
                # Job 命令、环境、超时或其他任一字段变化都必须失败关闭。
                if not _target_scenario_source_spec_only_drift(
                    campaign_dir,
                    manifest,
                ):
                    raise ConfigurationError(
                        "Campaign 历史场景除 source_spec.sha256 外发生变化。"
                    )
                authorized_binding = (
                    _successor_uses_reclassified_historical_plan_binding(
                        campaign_dir,
                        manifest,
                        {"scenario_manifest": scenario_reference},
                    )
                )
                frozen_reference = manifest.get("inputs", {}).get(
                    "target_discovery_scenarios"
                )
                if not isinstance(frozen_reference, dict):
                    raise ConfigurationError("Campaign 缺少 Formal target 场景绑定。")
                _require_file_binding(
                    frozen_reference,
                    "Campaign Formal target 场景",
                )
                frozen_scenario = _read_json(
                    _campaign_file(campaign_dir, frozen_reference["path"]),
                    "Campaign Formal target 场景",
                )
                if authorized_binding != selected_binding:
                    raise ConfigurationError(
                        "Campaign 批准历史场景未承接受控 Formal 摘要。"
                    )
                execution_scenario_override = (
                    _approved_scenario_with_formal_execution_contract(
                        campaign_dir,
                        manifest,
                        approved=selected_scenario,
                        formal=frozen_scenario,
                    )
                )
                historical_source_spec_binding = selected_binding
    context = _job_context(arguments)
    uses_frozen_target_scenario = (
        manifest.get("inputs", {}).get("target_discovery_scenarios") is not None
    )
    jobs = load_scenario_jobs(
        arguments.scenario_manifest,
        context,
        expected_version=(
            manifest["target_version"]
            if approved_target or uses_frozen_target_scenario
            else manifest["baseline_version"]
        ),
        require_bindings=True,
        historical_source_spec_binding=historical_source_spec_binding,
        execution_scenario_override=execution_scenario_override,
    )
    if not approved_target:
        jobs.extend(load_extra_jobs(arguments.extra_jobs, context))
    jobs = [
        job
        for job in jobs
        if job.phase == phase and manifest["suite"] in job.suites
    ]
    rules = _approved_rules(
        campaign_dir, manifest, require_approved=approved_target
    )
    _validate_jobs(jobs, rules)
    if not jobs:
        raise ConfigurationError(f"场景清单没有 {phase} 阶段任务。")
    return jobs


def _official_epoch_allows_classification_tool_drift(
    manifest: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    expected_tool: Mapping[str, Any],
    effective_epoch: Mapping[str, Any],
    *,
    operation: str | None,
) -> bool:
    """仅为已重放的 official epoch 放行分类期评估／控制面修复。"""

    source = effective_epoch.get("source")
    if operation != "classify" or not isinstance(source, Mapping):
        return False
    if not _is_official_sealed_control_epoch_source(source):
        return False
    drift = _tool_identity_drift(current_tool, expected_tool)
    changed_paths = set(drift.get("production", [])) | set(
        drift.get("evaluation", [])
    )
    if not changed_paths:
        return False
    disallowed = changed_paths - set(_SEALED_STAGE_RECOVERY_ALLOWED_FILES)
    if disallowed:
        raise ConfigurationError(
            "official epoch 分类期工具变化超出已批准的评估／控制面闭集："
            + "、".join(sorted(disallowed))
        )
    frozen = effective_epoch.get("invariants")
    if not isinstance(frozen, Mapping):
        raise ConfigurationError("official epoch 缺少分类期冻结边界。")
    current = _control_epoch_invariants(
        manifest,
        current_tool,
        required_active_phase="VC-2",
    )
    invariant_fields = {
        "tool_production_sha256",
        "compose_sha256",
        "required_active_phase",
    }
    if any(frozen.get(field) != current.get(field) for field in invariant_fields):
        raise ConfigurationError(
            "official epoch 分类期变化越过产出、compose 或 VC-2 阶段边界。"
        )
    return True


def _verify_stopped_classification_draft_approval(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    effective_epoch: Mapping[str, Any],
) -> dict[str, Any]:
    """只读验证阶段截止前已写入的唯一分类草案。"""

    source = effective_epoch.get("source")
    if (
        not isinstance(source, Mapping)
        or not _is_official_sealed_control_epoch_source(source)
        or not isinstance(effective_epoch.get("runtime_repair"), Mapping)
        or effective_epoch.get("boundary") != _control_epoch_zero_boundary()
    ):
        raise ConfigurationError(
            "离线分类批准要求唯一 official epoch、runtime-repair 和全零边界。"
        )

    classification_root = campaign_dir / "classification"
    draft_root = classification_root / "draft"
    result_path = classification_root / "result.json"
    approved_root = classification_root / "approved"
    if result_path.exists() or result_path.is_symlink():
        raise ConfigurationError("离线分类批准前已存在分类结果。")
    if approved_root.exists() or approved_root.is_symlink():
        raise ConfigurationError("离线分类批准前已存在批准目录。")
    if draft_root.is_symlink() or not draft_root.is_dir():
        raise ConfigurationError("离线分类批准缺少可信的既有 draft。")
    revisions = list(draft_root.iterdir())
    if (
        len(revisions) != 1
        or revisions[0].is_symlink()
        or not revisions[0].is_dir()
    ):
        raise ConfigurationError("离线分类批准只允许唯一不可覆盖 draft。")
    draft = revisions[0]
    expected_files = {
        "target-rules.json",
        "rule-migration.json",
        "scenarios.json",
        "profile.json",
        "assertion-profile.json",
        "draft.json",
    }
    actual_files = {path.name for path in draft.iterdir()}
    if actual_files != expected_files or any(
        path.is_symlink() or not path.is_file() for path in draft.iterdir()
    ):
        raise ConfigurationError("离线分类 draft 文件闭集不完整或含不可信路径。")
    receipt = _read_json(draft / "draft.json", "离线分类 draft 收据")
    revision = draft.name
    revision_match = re.fullmatch(
        r"(?P<second>\d{8}T\d{6}Z)-(?P<nanosecond>\d{9})",
        revision,
    )
    if (
        revision_match is None
        or receipt.get("status") != "draft"
        or receipt.get("revision") != revision
        or receipt.get("path") != str(draft)
    ):
        raise ConfigurationError("离线分类 draft 身份或时间坐标非法。")
    try:
        draft_created_at = datetime.strptime(
            revision_match.group("second"),
            "%Y%m%dT%H%M%SZ",
        ).replace(tzinfo=timezone.utc) + timedelta(
            microseconds=int(revision_match.group("nanosecond")) // 1_000
        )
    except ValueError as error:
        raise ConfigurationError("离线分类 draft 时间坐标非法。") from error

    candidates_root = campaign_dir / "candidates"
    if candidates_root.is_symlink() or (
        candidates_root.exists()
        and (
            not candidates_root.is_dir()
            or any(candidates_root.iterdir())
        )
    ):
        raise ConfigurationError("离线分类批准前已存在 Candidate。")

    controls = effective_epoch.get("successor_controls")
    timing = controls.get("upgrade_timing") if isinstance(controls, Mapping) else None
    if not isinstance(timing, Mapping):
        raise ConfigurationError("离线分类批准缺少 runtime-repair Ledger。")
    ledger_root, frozen_checkpoint = _sealed_stage_timing_checkpoint(
        timing,
        label="离线分类批准",
    )
    frozen = frozen_checkpoint.get("summary")
    try:
        current = codex_upgrade_timing_ledger.inspect_ledger(ledger_root)
    except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
        raise ConfigurationError(f"离线分类批准无法重放 Ledger：{error}") from error
    identity = {
        "baseline_version": manifest.get("baseline_version"),
        "target_version": manifest.get("target_version"),
        "campaign_purpose": manifest.get("campaign_purpose"),
    }
    if (
        not isinstance(frozen, Mapping)
        or frozen.get("status") != "active"
        or frozen.get("active_phase") != "VC-2"
        or frozen.get("total_live_request_count") != 0
        or current.get("status") != "stop_required"
        or current.get("active_phase") != "VC-2"
        or current.get("total_live_request_count") != 0
        or any(current.get(field) != value for field, value in identity.items())
    ):
        raise ConfigurationError(
            "离线分类批准要求仅因 VC-2 阶段截止的 stop_required Ledger，且 live=0。"
        )
    if (
        current.get("head_sequence") != frozen.get("head_sequence")
        or current.get("head_sha256") != frozen.get("head_sha256")
        or current.get("stage_deadline_at_utc")
        != frozen.get("stage_deadline_at_utc")
        or current.get("total_deadline_at_utc")
        != frozen.get("total_deadline_at_utc")
    ):
        raise ConfigurationError("离线分类批准期间 Ledger 新增事件或截止边界漂移。")
    stage_deadline = _rfc3339_datetime(
        str(current.get("stage_deadline_at_utc", "")),
        "离线分类批准 VC-2 截止",
    )
    total_deadline = _rfc3339_datetime(
        str(current.get("total_deadline_at_utc", "")),
        "离线分类批准总截止",
    )
    now = datetime.now(timezone.utc)
    if now < stage_deadline or now >= total_deadline:
        raise ConfigurationError("离线分类批准不在阶段到期后、总截止前的窗口内。")
    if draft_created_at >= stage_deadline:
        raise ConfigurationError("离线分类 draft 不是在 VC-2 截止前生成。")
    return {
        "draft_revision": revision,
        "draft_created_at_utc": draft_created_at.isoformat(),
        "stage_deadline_at_utc": current["stage_deadline_at_utc"],
        "total_deadline_at_utc": current["total_deadline_at_utc"],
        "ledger_head_sha256": current["head_sha256"],
        "live_request_count": 0,
        "boundary": _control_epoch_zero_boundary(),
    }


def _verify_plan_identity(
    campaign_dir: Path,
    manifest: dict[str, Any],
    *,
    operation: str | None = None,
    attempt_root: Path | None = None,
    attempt: Mapping[str, Any] | None = None,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
    allow_stopped_classification_draft_approval: bool = False,
) -> dict[str, Any] | None:
    # 先重放原 Campaign 的冻结控制事实，但暂不要求旧 Ledger 仍 active。
    # 工具缺陷恢复时旧 Ledger 必须已经 stop_the_line，批准后的 transition
    # 会另行绑定并重放新的 active 控制链；其他路径仍在下方要求旧控制 active。
    _verify_control_receipts(campaign_dir, manifest, require_active=False)
    target_source = Path(manifest["configuration"]["target_source"])
    expected = manifest["official_identity"]
    cargo_lock = target_source / "Cargo.lock"
    current_identity = {
        "source_tree_sha256": _directory_tree_digest(target_source),
        "cargo_lock_sha256": file_sha256(cargo_lock) if cargo_lock.is_file() else None,
    }
    for field, value in current_identity.items():
        if value != expected.get(field):
            raise ConfigurationError(f"官方目标身份漂移：{field}")
    package_identity = expected.get("package")
    if not isinstance(package_identity, dict):
        raise ConfigurationError("官方目标身份缺少 package 闭包。")
    if deadline is not None:
        deadline.check("plan-identity:start")
    current_package_identity = _verify_codex_package(
        Path(manifest["configuration"]["target_package"]),
        expected_version=manifest["target_version"],
        expected_package_sha256=str(package_identity.get("asset_sha256", "")),
        expected_binary_sha256=manifest["target_sha256"],
        expected_code_mode_host_sha256=str(
            package_identity.get("code_mode_host_sha256", "")
        ),
        deadline=deadline,
        heartbeat=heartbeat,
    )
    if current_package_identity != package_identity:
        raise ConfigurationError("官方目标 package 身份漂移。")
    current_tool = _tool_identity(include_git=False)
    if deadline is not None:
        deadline.check("plan-identity:tool-summary")
    expected_tool = manifest["tool_identity"]
    if allow_stopped_classification_draft_approval:
        if operation != "classify":
            raise ConfigurationError("离线 draft 批准仅允许 classify 操作。")
        effective_epoch = _load_control_epoch_receipt(campaign_dir, manifest)
        if isinstance(effective_epoch, Mapping):
            controls = effective_epoch.get("successor_controls")
            timing = (
                controls.get("upgrade_timing")
                if isinstance(controls, Mapping)
                else None
            )
            if isinstance(timing, Mapping):
                ledger_root, _ = _sealed_stage_timing_checkpoint(
                    timing,
                    label="分类批准当前状态",
                )
                try:
                    current_ledger = codex_upgrade_timing_ledger.inspect_ledger(
                        ledger_root
                    )
                except (
                    OSError,
                    codex_upgrade_timing_ledger.TimingLedgerError,
                ) as error:
                    raise ConfigurationError(
                        f"分类批准无法检查当前 Ledger：{error}"
                    ) from error
                if current_ledger.get("status") == "stop_required":
                    official_epoch_classification_drift = (
                        _official_epoch_allows_classification_tool_drift(
                            manifest,
                            current_tool,
                            expected_tool,
                            effective_epoch,
                            operation=operation,
                        )
                    )
                    if (
                        current_tool.get("files_sha256")
                        != effective_epoch.get("invariants", {}).get(
                            "tool_files_sha256"
                        )
                        and not official_epoch_classification_drift
                    ):
                        raise ConfigurationError(
                            "离线 draft 批准未绑定唯一 official epoch 的当前工具身份。"
                        )
                    authorization = (
                        _verify_stopped_classification_draft_approval(
                            campaign_dir,
                            manifest,
                            effective_epoch,
                        )
                    )
                    if official_epoch_classification_drift:
                        changed_paths = sorted(
                            path
                            for paths in _tool_component_drift(
                                expected_tool,
                                current_tool,
                            ).get("changed_paths", {}).values()
                            for path in paths
                        )
                        _record_evaluation_side_drift(
                            campaign_dir,
                            current_tool,
                            expected_tool,
                            {"evaluation": changed_paths},
                        )
                    if deadline is not None:
                        deadline.check("plan-identity:complete")
                    return {
                        "kind": "stopped_classification_draft_approval",
                        "authorization": authorization,
                    }
    if current_tool["files_sha256"] == expected_tool["files_sha256"]:
        _verify_control_receipts(campaign_dir, manifest, require_active=True)
        if deadline is not None:
            deadline.check("plan-identity:complete")
        return None
    component_drift = _tool_component_drift(expected_tool, current_tool)
    changed_components = set(component_drift.get("changed_components", []))
    effective_epoch = _load_control_epoch_receipt(campaign_dir, manifest)
    official_epoch_classification_drift = (
        isinstance(effective_epoch, Mapping)
        and _official_epoch_allows_classification_tool_drift(
            manifest,
            current_tool,
            expected_tool,
            effective_epoch,
            operation=operation,
        )
    )
    if (
        effective_epoch is not None
        and (
            current_tool.get("files_sha256")
            == effective_epoch.get("invariants", {}).get("tool_files_sha256")
            or official_epoch_classification_drift
        )
    ):
        source = effective_epoch.get("source")
        if not isinstance(source, Mapping):
            raise ConfigurationError("control epoch 缺少可验证的源闭集。")
        source_candidate_id = str(source.get("candidate_id", ""))
        source_attempt_id = str(source.get("attempt_id", ""))
        if operation == "capture-run":
            predecessor = manifest.get("predecessor")
            if (
                not isinstance(predecessor, Mapping)
                or not isinstance(attempt, Mapping)
                or attempt_root is None
                or attempt.get("phase") != "candidate"
                or attempt.get("candidate_id") != source_candidate_id
                or attempt.get("attempt_id") != source_attempt_id
                or attempt.get("attempt_digest") != source.get("attempt_digest")
            ):
                raise ConfigurationError(
                    "control epoch 恢复执行未绑定原失败 Candidate／attempt。"
                )
            expected_source_root = _capture_attempt_path(
                _control_epoch_source_campaign_dir(campaign_dir, manifest),
                "candidate",
                source_candidate_id,
                source_attempt_id,
            )
            try:
                supplied_source_root = attempt_root.resolve(strict=True)
            except (OSError, RuntimeError) as error:
                raise ConfigurationError("control epoch 源 attempt 路径不可信。") from error
            if supplied_source_root != expected_source_root.resolve(strict=True):
                raise ConfigurationError("control epoch 源 attempt 路径发生漂移。")
        elif attempt is not None or attempt_root is not None:
            if (
                operation
                not in {
                    "capture-candidate-seal",
                    "compare",
                    "accept",
                    "deep-verify",
                }
                or not isinstance(attempt, Mapping)
                or attempt_root is None
                or attempt.get("campaign_id") != manifest.get("campaign_id")
                or attempt.get("phase") != "candidate"
                or attempt.get("candidate_id") != source_candidate_id
            ):
                raise ConfigurationError("control epoch 不授权当前阶段或 attempt。")
            plan = attempt.get("incremental_plan")
            if (
                not isinstance(plan, Mapping)
                or set(plan.get("planned_job_ids", []))
                != set(source.get("planned_job_ids", []))
                or set(plan.get("reused_job_ids", []))
                != set(source.get("reused_job_ids", []))
                or set(plan.get("executed_job_ids", []))
                != set(source.get("execute_job_ids", []))
            ):
                raise ConfigurationError("control epoch 后继 attempt 的执行闭集发生漂移。")
        elif operation not in {None, "classify"}:
            raise ConfigurationError("control epoch 不授权无 attempt 的当前操作。")
        _verify_control_receipts(campaign_dir, manifest, require_active=True)
        if official_epoch_classification_drift:
            changed_paths = sorted(
                path
                for paths in component_drift.get("changed_paths", {}).values()
                for path in paths
            )
            _record_evaluation_side_drift(
                campaign_dir,
                current_tool,
                expected_tool,
                {"evaluation": changed_paths},
            )
        if deadline is not None:
            deadline.check("plan-identity:complete")
        epoch_path = _control_epoch_path(campaign_dir)
        return {
            "kind": "control_epoch",
            "changed_components": sorted(changed_components),
            "changed_paths": component_drift.get("changed_paths", {}),
            "affected_job_ids": list(source.get("execute_job_ids", [])),
            "control_epoch": {
                "path": epoch_path.relative_to(campaign_dir).as_posix(),
                "sha256": file_sha256(epoch_path),
                "receipt_sha256": effective_epoch.get("receipt_sha256"),
                "runtime_repair": effective_epoch.get("runtime_repair"),
            },
            "from_component_identity_sha256": _fingerprint(
                _tool_component_bundle(expected_tool)
            ),
            "to_component_identity_sha256": _fingerprint(
                _tool_component_bundle(current_tool)
            ),
        }
    # 失败 attempt 或新 attempt 上显式绑定的 transition 是唯一允许绕过旧
    # active Ledger 的路径。transition 自身会重放新 Ledger、ARM64 P0 和
    # 完整 Job 演练；这里不能再要求已经 stop_the_line 的旧 Ledger active。
    if (
        operation is not None
        and isinstance(attempt, Mapping)
        and attempt_root is not None
        # 跨 Campaign 的 v9 abandoned attempt 只是增量来源，不是当前
        # Campaign 的 evaluation-transition 源；它必须走下面的低风险
        # capture-run 分支。否则会错误要求前序 attempt 存在当前工具的
        # transition，并在 reservation 前永久阻断合法恢复。
        and attempt.get("campaign_id") == manifest.get("campaign_id")
        and (
            attempt.get("evaluation_transition") is not None
            or (
                operation == "capture-run"
                and attempt.get("status") == "failed"
            )
        )
    ):
        transition = _load_phase_evaluation_transition(
            campaign_dir,
            manifest,
            attempt_root=attempt_root,
            attempt=attempt,
            operation=operation,
            current_tool=current_tool,
            drift=_tool_identity_drift(current_tool, expected_tool),
        )
        source_root, source_attempt, _, _ = _phase_evaluation_transition_source(
            campaign_dir,
            phase=str(attempt.get("phase", "")),
            candidate_id=(
                str(attempt.get("candidate_id"))
                if attempt.get("candidate_id") is not None
                else None
            ),
            attempt_root=attempt_root,
            attempt=attempt,
        )
        recovery_scope = None
        if source_attempt.get("status") == "failed":
            recovery_scope = _phase_evaluation_recovery_scope(
                campaign_dir,
                manifest,
                phase=str(source_attempt.get("phase", "")),
                candidate_id=(
                    str(source_attempt.get("candidate_id"))
                    if source_attempt.get("candidate_id") is not None
                    else None
                ),
                attempt_root=source_root,
                attempt=source_attempt,
            )
        _record_evaluation_side_drift(
            campaign_dir,
            current_tool,
            expected_tool,
            {
                "evaluation": sorted(
                    path
                    for paths in component_drift.get("changed_paths", {}).values()
                    for path in paths
                )
            },
        )
        return {
            "kind": "phase_evaluation_transition",
            "changed_components": sorted(changed_components),
            "changed_paths": component_drift.get("changed_paths", {}),
            "affected_job_ids": (
                list(recovery_scope.get("execute_job_ids", []))
                if recovery_scope is not None
                else []
            ),
            "evaluation_transition": transition,
            "recovery_scope": recovery_scope,
            "from_component_identity_sha256": _fingerprint(
                _tool_component_bundle(expected_tool)
            ),
            "to_component_identity_sha256": _fingerprint(
                _tool_component_bundle(current_tool)
            ),
        }
    if (
        changed_components
        and changed_components.issubset({"orchestrator", "evaluator"})
        and isinstance(attempt, Mapping)
        and attempt.get("incremental_tool_transition") is not None
    ):
        transition = _validate_incremental_tool_transition(
            attempt["incremental_tool_transition"],
            expected_tool,
            current_tool,
        )
        _verify_control_receipts(campaign_dir, manifest, require_active=True)
        if deadline is not None:
            deadline.check("plan-identity:complete")
        return transition
    # 编排／评估修复只改变结果判定或任务调度，不改变已经封存的官方字节。
    # 这类变化不再把整个 Campaign 拦在全局 files_sha256 门禁上；调用方会
    # 根据 Job／门禁依赖闭集决定需要补跑的项目。旧 Campaign 没有组件包时，
    # _tool_component_bundle 会从历史 entries 现场推导，仍保持 fail-close。
    if (
        operation == "capture-run"
        and changed_components
        and changed_components.issubset({"orchestrator", "evaluator"})
    ):
        _verify_control_receipts(campaign_dir, manifest, require_active=True)
        _record_evaluation_side_drift(
            campaign_dir,
            current_tool,
            expected_tool,
            {
                "evaluation": sorted(
                    path
                    for paths in component_drift.get("changed_paths", {}).values()
                    for path in paths
                )
            },
        )
        if deadline is not None:
            deadline.check("plan-identity:complete")
        return {
            "kind": "component_drift",
            "changed_components": sorted(changed_components),
            "changed_paths": component_drift.get("changed_paths", {}),
            "affected_job_ids": [],
            "from_component_identity_sha256": _fingerprint(
                _tool_component_bundle(expected_tool)
            ),
            "to_component_identity_sha256": _fingerprint(
                _tool_component_bundle(current_tool)
            ),
        }
    # 工具确实变了。按证据影响面分级判定，而不是一律拒绝：产出侧改动会改变证据字节，
    # 必须整轮重来；评估侧改动只改变「怎么判断」，已封存证据逐字节不变，重新评估即可。
    #
    # 兼容：plan 时未记录分组摘要的旧 Campaign 无法证明其分级前提，退回严格拒绝。
    if "production_sha256" not in expected_tool:
        raise ConfigurationError(
            "升级工具摘要在 plan 后发生变化（该 Campaign 的 plan 未记录分组摘要，"
            "无法分级判定，只能整轮重建）。"
        )
    drift = _tool_identity_drift(current_tool, expected_tool)
    # 候选已经完成全部 Job 且仅等待 Kilo／seal 时，控制面、评估器和编排器的
    # 修复不会改变既有请求字节。新流程禁止再写 evaluation-transition；在这个
    # 明确的 metadata-only 边界内只记录评估侧漂移，并继续执行 seal。只要存在
    # 任何执行、失败、待执行 Job，或已经开始 evidence manifest／seal，就必须
    # 回到严格 transition 路径，避免把真正的产出变化伪装成廉价修复。
    metadata_only_seal_repair = False
    derived_artifacts = (
        attempt_root / "evidence-manifest.json"
        if attempt_root is not None
        else None,
        attempt_root / "seal-draft.json"
        if attempt_root is not None
        else None,
        attempt_root / "seal-preview.json"
        if attempt_root is not None
        else None,
        attempt_root / "seal-preview-1.json"
        if attempt_root is not None
        else None,
    )
    source_manifest = (
        attempt_root / CLASSIFICATION_CANDIDATE_REUSE_SOURCE_MANIFEST_FILENAME
        if attempt_root is not None
        else None
    )
    metadata_only_derived_artifacts_allowed = (
        not any(
            path is not None and (path.exists() or path.is_symlink())
            for path in derived_artifacts
        )
        or (
            source_manifest is not None
            and not source_manifest.is_symlink()
            and source_manifest.is_file()
        )
    )
    if (
        operation in {"capture-candidate-seal", "compare", "accept", "deep-verify"}
        and isinstance(attempt, Mapping)
        and attempt_root is not None
        and attempt.get("campaign_id") == manifest.get("campaign_id")
        and attempt.get("phase") == "candidate"
        and attempt.get("status") == "awaiting_receipts"
        and attempt.get("evaluation_transition") is None
        and changed_components
        and changed_components.issubset({"control", "orchestrator", "evaluator"})
    ):
        plan = attempt.get("incremental_plan")
        results = attempt.get("results")
        metadata_only_seal_repair = (
            isinstance(plan, Mapping)
            and not any(plan.get(field) for field in ("executed_job_ids", "failed_job_ids", "pending_job_ids"))
            and isinstance(results, list)
            and bool(results)
            and all(
                isinstance(result, Mapping)
                and result.get("status") == "complete"
                and result.get("disposition") == "reused"
                for result in results
            )
        and metadata_only_derived_artifacts_allowed
        )
    if metadata_only_seal_repair:
        changed_paths = sorted(
            path
            for paths in component_drift.get("changed_paths", {}).values()
            for path in paths
        )
        _verify_control_receipts(
            campaign_dir,
            manifest,
            require_active=True,
            allow_stopped_metadata_only=True,
        )
        _record_evaluation_side_drift(
            campaign_dir,
            current_tool,
            expected_tool,
            {"evaluation": changed_paths},
        )
        if deadline is not None:
            deadline.check("plan-identity:metadata-only-seal-repair")
        return {
            "kind": "metadata_only_seal_repair",
            "changed_components": sorted(changed_components),
            "changed_paths": component_drift.get("changed_paths", {}),
            "affected_job_ids": [],
            "from_component_identity_sha256": _fingerprint(
                _tool_component_bundle(expected_tool)
            ),
            "to_component_identity_sha256": _fingerprint(
                _tool_component_bundle(current_tool)
            ),
        }
    # status、plan 后的廉价阶段校验也必须能观察纯编排器／评估器漂移；
    # 这里不要求旧 Ledger 继续 active，也不触碰证据正文。带 attempt 的
    # seal／deep-verify 仍走上面的 transition 分支，保留阶段边界。
    if (
        operation is None
        and changed_components
        and changed_components.issubset({"orchestrator", "evaluator"})
    ):
        low_risk_paths = sorted(
            path
            for paths in component_drift.get("changed_paths", {}).values()
            for path in paths
        )
        _verify_control_receipts(campaign_dir, manifest, require_active=True)
        _record_evaluation_side_drift(
            campaign_dir,
            current_tool,
            expected_tool,
            {"evaluation": low_risk_paths},
        )
        if deadline is not None:
            deadline.check("plan-identity:complete")
        return {
            "kind": "component_drift",
            "changed_components": sorted(changed_components),
            "changed_paths": component_drift.get("changed_paths", {}),
            "affected_job_ids": [],
            "from_component_identity_sha256": _fingerprint(
                _tool_component_bundle(expected_tool)
            ),
            "to_component_identity_sha256": _fingerprint(
                _tool_component_bundle(current_tool)
            ),
        }
    expected_production_sha256 = _tool_identity_side_digest(
        expected_tool, "production"
    )
    current_production_sha256 = _tool_identity_side_digest(
        current_tool, "production"
    )
    if drift["production"] or current_production_sha256 != expected_production_sha256:
        if operation is None or attempt_root is None or attempt is None:
            raise ConfigurationError(
                "升级工具的产出侧在 plan 后发生变化，证据字节前提已不成立："
                + "、".join(
                    drift["production"] or ["<摘要不一致但无法定位文件>"]
                )
            )
        transition = _load_phase_evaluation_transition(
            campaign_dir,
            manifest,
            attempt_root=attempt_root,
            attempt=attempt,
            operation=operation,
            current_tool=current_tool,
            drift=drift,
        )
        _record_evaluation_side_drift(
            campaign_dir,
            current_tool,
            expected_tool,
            drift,
        )
        if deadline is not None:
            deadline.check("plan-identity:complete")
        return transition
    # 只有评估侧变化：放行，但把变化清单落进台账供审计，避免静默放行。
    _verify_control_receipts(campaign_dir, manifest, require_active=True)
    _record_evaluation_side_drift(campaign_dir, current_tool, expected_tool, drift)
    if deadline is not None:
        deadline.check("plan-identity:complete")
    return None


TOOL_EVALUATION_DRIFT_SCHEMA = "codex-upgrade-tool-evaluation-drift/v1"
INCREMENTAL_TOOL_TRANSITION_SCHEMA = "codex-upgrade-incremental-tool-transition/v1"


def _record_evaluation_side_drift(
    campaign_dir: Path,
    current_tool: Mapping[str, Any],
    expected_tool: Mapping[str, Any],
    drift: Mapping[str, list[str]],
) -> None:
    """把被放行的评估侧漂移追加进独立台账，作为不可省略的审计痕迹。

    放行不等于无痕：每次评估侧改动都要留下「改了哪些文件、放行时的新摘要」，
    否则 accept 阶段无法解释某轮结果是用哪一版判据算出来的。

    台账另立文件而不写回 `campaign.json`——后者由 `campaign.sha256` 保护且一次封存
    不可变，追加内容会直接破坏 Campaign 完整性校验。
    """

    if not drift["evaluation"]:
        return
    path = campaign_dir / "tool-evaluation-drift.json"
    if path.is_symlink():
        raise ConfigurationError("评估侧漂移台账不允许是符号链接。")
    if path.is_file():
        ledger = _read_json(path, "评估侧漂移台账")
        if ledger.get("schema_version") != TOOL_EVALUATION_DRIFT_SCHEMA:
            raise ConfigurationError("评估侧漂移台账 schema_version 不受支持。")
        records = ledger.get("records")
        if not isinstance(records, list):
            raise ConfigurationError("评估侧漂移台账结构非法。")
    else:
        records = []
    record = {
        "changed_files": list(drift["evaluation"]),
        "plan_evaluation_sha256": _tool_identity_side_digest(
            expected_tool, "evaluation"
        ),
        "current_evaluation_sha256": _tool_identity_side_digest(
            current_tool, "evaluation"
        ),
        "production_sha256": _tool_identity_side_digest(
            current_tool, "production"
        ),
        "files_sha256": current_tool["files_sha256"],
    }
    # 同一份评估侧状态重复进入不再追加，台账按「不同的评估侧版本」计数。
    if records and records[-1].get("current_evaluation_sha256") == (
        record["current_evaluation_sha256"]
    ):
        return
    records.append(record)
    payload = {
        "schema_version": TOOL_EVALUATION_DRIFT_SCHEMA,
        "plan_production_sha256": _tool_identity_side_digest(
            expected_tool, "production"
        ),
        "records": records,
    }
    ensure_private_directory(path.parent)
    descriptor, temporary_name = tempfile.mkstemp(
        prefix=f".{path.name}.", suffix=".tmp", dir=path.parent
    )
    temporary = Path(temporary_name)
    try:
        os.fchmod(descriptor, 0o600)
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            stream.write(
                json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True)
                + "\n"
            )
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    except BaseException:
        temporary.unlink(missing_ok=True)
        raise


_PHASE_EVALUATION_OPERATIONS = {
    "official": ("capture-official-seal", "deep-verify"),
    "candidate": ("capture-candidate-seal", "compare", "accept", "deep-verify"),
}
STANDARD_PHASE_EVALUATION_TRANSITIONS = 3
TERMINAL_PHASE_EVALUATION_TRANSITION = 4
MAX_PHASE_EVALUATION_TRANSITIONS = TERMINAL_PHASE_EVALUATION_TRANSITION
_PHASE_EVALUATION_TRANSITION_FILE_RE = re.compile(
    r"^evaluation-transition(?:-(?P<index>[0-9]{2}))?\.json$"
)


def _phase_evaluation_allowed_operations(
    phase: str,
    attempt_status: Any,
) -> tuple[str, ...]:
    """返回与 attempt 状态匹配的 transition 操作白名单。

    失败 attempt 的 transition 是恢复专用授权，只能创建新的 capture-run
    并执行失败／未完成闭集；不能借此直接 seal、compare 或 accept。
    """

    if phase not in _PHASE_EVALUATION_OPERATIONS:
        raise ConfigurationError("评估 transition phase 非法。")
    if attempt_status == "failed":
        return ("capture-run",)
    return tuple(_PHASE_EVALUATION_OPERATIONS[phase])


def _evaluation_transition_preview_path(
    attempt_root: Path,
    transition_index: int = 1,
) -> Path:
    if transition_index == 1:
        return attempt_root / "evaluation-transition-preview.json"
    return attempt_root / f"evaluation-transition-{transition_index:02d}-preview.json"


def _evaluation_transition_path(
    attempt_root: Path,
    transition_index: int = 1,
) -> Path:
    if transition_index == 1:
        return attempt_root / "evaluation-transition.json"
    return attempt_root / f"evaluation-transition-{transition_index:02d}.json"


def _phase_evaluation_transition_index(
    attempt_root: Path,
    current_tool: Mapping[str, Any],
    *,
    allocate: bool,
) -> int:
    """选择当前工具的只追加 transition 槽位；第 4 槽另受终端预检约束。"""

    current_sha256 = str(current_tool.get("files_sha256", ""))
    if not SHA256_RE.fullmatch(current_sha256):
        raise ConfigurationError("当前评估工具身份非法。")
    occupied: list[int] = []
    matching: list[int] = []
    for index in range(1, MAX_PHASE_EVALUATION_TRANSITIONS + 1):
        paths = (
            _evaluation_transition_preview_path(attempt_root, index),
            _evaluation_transition_path(attempt_root, index),
        )
        targets: set[str] = set()
        present = False
        for path in paths:
            if path.is_symlink() or (path.exists() and not path.is_file()):
                raise ConfigurationError("评估 transition 路径不可信。")
            if not path.is_file():
                continue
            present = True
            payload = _read_json(path, "评估工具 transition 槽位")
            target = str(payload.get("to_tool_files_sha256", ""))
            if not SHA256_RE.fullmatch(target):
                raise ConfigurationError("评估 transition 槽位缺少目标工具摘要。")
            targets.add(target)
        if not present:
            continue
        occupied.append(index)
        if len(targets) != 1:
            raise ConfigurationError("同一评估 transition 槽位的工具摘要不一致。")
        if current_sha256 in targets:
            matching.append(index)
    if occupied and occupied != list(range(1, max(occupied) + 1)):
        raise ConfigurationError("评估 transition 槽位不连续。")
    if len(matching) > 1:
        raise ConfigurationError("当前评估工具重复绑定多个 transition。")
    if matching:
        return matching[0]
    if not allocate:
        raise ConfigurationError(
            "当前工具含阶段限定变化；先执行 evaluation-transition 并批准摘要。"
        )
    for index in range(1, MAX_PHASE_EVALUATION_TRANSITIONS + 1):
        if index not in occupied:
            return index
    raise ConfigurationError("评估 transition 已使用终端第 4 槽，必须永久停线。")


def _legacy_vc0_phase_recovery_scope(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    phase: str | None,
    candidate_id: str | None,
    attempt_root: Path | None,
    attempt: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """验证历史 Formal 已运行 Candidate、但 Ledger 遗留在 VC-0 的窄例外。"""

    if (
        phase != "candidate"
        or not isinstance(candidate_id, str)
        or not SAFE_ID_RE.fullmatch(candidate_id)
        or not isinstance(attempt_root, Path)
        or not isinstance(attempt, Mapping)
        or attempt.get("status") != "failed"
        or attempt.get("phase") != "candidate"
        or attempt.get("candidate_id") != candidate_id
        or attempt.get("campaign_id") != manifest.get("campaign_id")
        or attempt.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
    ):
        return None
    try:
        resolved_attempt = attempt_root.resolve(strict=True)
    except (OSError, RuntimeError):
        return None
    matching_attempts = [
        root
        for current_phase, current_candidate_id, root in _campaign_attempt_roots(
            campaign_dir
        )
        if current_phase == "candidate" and current_candidate_id == candidate_id
    ]
    if len(matching_attempts) != 1:
        return None
    try:
        if matching_attempts[0].resolve(strict=True) != resolved_attempt:
            return None
    except (OSError, RuntimeError):
        return None
    _, stage_path = _stage_path(campaign_dir, "candidate", candidate_id)
    if stage_path.exists() or stage_path.is_symlink():
        return None
    try:
        scope = _phase_evaluation_recovery_scope(
            campaign_dir,
            manifest,
            phase="candidate",
            candidate_id=candidate_id,
            attempt_root=attempt_root,
            attempt=attempt,
        )
    except ConfigurationError:
        return None
    if not scope.get("execute_job_ids"):
        return None
    return scope


def _final_execution_epoch_phase_recovery_context(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    phase: str | None,
    candidate_id: str | None,
    attempt_root: Path | None,
    attempt: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """验证最终 execution epoch 后唯一的失败 producer 恢复边界。"""

    if (
        phase != "candidate"
        or not isinstance(candidate_id, str)
        or not isinstance(attempt_root, Path)
        or not isinstance(attempt, Mapping)
        or attempt.get("status") != "failed"
        or attempt.get("phase") != "candidate"
        or attempt.get("candidate_id") != candidate_id
        or attempt.get("campaign_id") != manifest.get("campaign_id")
        or attempt.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
    ):
        return None

    epoch = _load_control_epoch_receipt(campaign_dir, manifest)
    if not isinstance(epoch, Mapping) or epoch.get("epoch_index") != 2:
        return None
    authorization = epoch.get("execution_authorization")
    scope = (
        authorization.get("scope")
        if isinstance(authorization, Mapping)
        else None
    )
    controls = epoch.get("successor_controls")
    timing = controls.get("upgrade_timing") if isinstance(controls, Mapping) else None
    arm64 = controls.get("arm64_environment") if isinstance(controls, Mapping) else None
    plan = attempt.get("incremental_plan")
    if (
        epoch.get("status") != "active"
        or not isinstance(authorization, Mapping)
        or authorization.get("schema_version")
        != CONTROL_EPOCH_FINAL_EXECUTION_SCHEMA
        or authorization.get("mode") != CONTROL_EPOCH_FINAL_EXECUTION_MODE
        or not isinstance(scope, Mapping)
        or not isinstance(timing, Mapping)
        or not isinstance(arm64, Mapping)
        or not isinstance(plan, Mapping)
    ):
        raise ConfigurationError("最终 execution epoch 的 producer 恢复授权不完整。")

    expected_execute = sorted(str(value) for value in scope.get("execute_job_ids", []))
    expected_reused = sorted(str(value) for value in scope.get("reused_job_ids", []))
    expected_planned = sorted(str(value) for value in scope.get("planned_job_ids", []))
    if (
        expected_execute
        != ["candidate-compact-mitm", "candidate-core-mitm"]
        or len(expected_reused) != 7
        or len(expected_planned) != 9
        or sorted(str(value) for value in plan.get("planned_job_ids", []))
        != expected_planned
        or sorted(str(value) for value in plan.get("executed_job_ids", []))
        != expected_execute
        or sorted(str(value) for value in plan.get("failed_job_ids", []))
        != expected_execute
        or list(plan.get("pending_job_ids", []))
        or sorted(str(value) for value in plan.get("reused_job_ids", []))
        != expected_reused
    ):
        raise ConfigurationError(
            "最终 execution epoch 的失败 attempt 不是固定 2 执行／7 复用闭集。"
        )
    if (
        not _is_rfc3339_timestamp(epoch.get("created_at_utc"))
        or not _is_rfc3339_timestamp(attempt.get("started_at_utc"))
        or _rfc3339_datetime(attempt.get("started_at_utc"), "失败 attempt 开始时间")
        < _rfc3339_datetime(epoch.get("created_at_utc"), "最终 epoch 创建时间")
    ):
        raise ConfigurationError("失败 attempt 不是由最终 execution epoch 创建。")

    epoch_path = _control_epoch_path(campaign_dir, 2)
    return {
        "predecessor_timing": dict(timing),
        "predecessor_arm64": dict(arm64),
        "marker": {
            "mode": "single-failed-producer-recovery",
            "epoch_index": 2,
            "epoch": {
                "path": epoch_path.relative_to(campaign_dir).as_posix(),
                "sha256": file_sha256(epoch_path),
            },
            "source_attempt_id": str(attempt.get("attempt_id")),
            "source_attempt_digest": str(attempt.get("attempt_digest")),
            "execute_job_ids": expected_execute,
            "reused_job_ids": expected_reused,
        },
    }


def _phase_recovery_controls_from_arguments(
    arguments: argparse.Namespace,
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    *,
    phase: str | None = None,
    candidate_id: str | None = None,
    attempt_root: Path | None = None,
    attempt: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """绑定旧停线事实与当前工具的新计时、P0 和完整演练收据。"""

    required_names = (
        "predecessor_stop_ledger_dir",
        "predecessor_stop_receipt",
        "recovery_timing_ledger_dir",
        "recovery_timing_receipt",
        "recovery_arm64_environment_root",
        "recovery_arm64_environment_receipt",
        "job_rehearsal_root",
        "job_rehearsal_receipt",
    )
    values = {name: getattr(arguments, name, None) for name in required_names}
    if not all(isinstance(value, Path) for value in values.values()):
        raise ConfigurationError("评估 transition 必须完整提供八项恢复控制坐标。")

    _verify_control_receipts(campaign_dir, manifest, require_active=False)
    frozen_controls = manifest.get("control_receipts")
    if not isinstance(frozen_controls, Mapping):
        raise ConfigurationError("原 Formal Campaign 缺少冻结控制收据。")
    predecessor_timing = frozen_controls.get("upgrade_timing")
    predecessor_arm = frozen_controls.get("arm64_environment")
    if not isinstance(predecessor_timing, Mapping) or not isinstance(
        predecessor_arm, Mapping
    ):
        raise ConfigurationError("原 Formal Campaign 的计时或 ARM64 控制收据不完整。")
    final_execution_context = _final_execution_epoch_phase_recovery_context(
        campaign_dir,
        manifest,
        phase=phase,
        candidate_id=candidate_id,
        attempt_root=attempt_root,
        attempt=attempt,
    )
    if final_execution_context is not None:
        predecessor_timing = final_execution_context["predecessor_timing"]
        predecessor_arm = final_execution_context["predecessor_arm64"]

    stop_root = values["predecessor_stop_ledger_dir"]
    stop_receipt = values["predecessor_stop_receipt"]
    assert isinstance(stop_root, Path) and isinstance(stop_receipt, Path)
    stop_relative = _control_receipt_relative(
        stop_root,
        stop_receipt,
        "原 Campaign stop_the_line checkpoint",
    )
    try:
        stop_checkpoint = codex_upgrade_timing_ledger.replay(
            stop_root,
            stop_relative,
        )
    except (OSError, codex_upgrade_timing_ledger.TimingLedgerError) as error:
        raise ConfigurationError(f"原 Campaign 停线 checkpoint 未通过：{error}") from error
    stop_summary = stop_checkpoint.get("summary")
    stop_phase = stop_summary.get("active_phase") if isinstance(
        stop_summary, Mapping
    ) else None
    legacy_vc0_scope: dict[str, Any] | None = None
    if stop_phase == codex_upgrade_timing_ledger.PHASE_ORDER[0]:
        legacy_vc0_scope = _legacy_vc0_phase_recovery_scope(
            campaign_dir,
            manifest,
            phase=phase,
            candidate_id=candidate_id,
            attempt_root=attempt_root,
            attempt=attempt,
        )
    if (
        not isinstance(stop_summary, Mapping)
        or stop_summary.get("status") != "stopped"
        or (
            stop_summary.get("active_phase")
            not in codex_upgrade_timing_ledger.PHASE_ORDER[1:]
            and legacy_vc0_scope is None
        )
        or any(
            stop_summary.get(field) != manifest.get(field)
            for field in (
                "baseline_version",
                "target_version",
                "campaign_purpose",
            )
        )
        or stop_summary.get("upgrade_id") != predecessor_timing.get("upgrade_id")
        or stop_summary.get("evidence_decision")
        != predecessor_timing.get("evidence_decision")
    ):
        raise ConfigurationError(
            "停线 checkpoint 不是原 Campaign 在 VC-1～VC-6 的事实，"
            "也不满足历史 Formal Candidate 的 VC-0 兼容恢复条件。"
        )
    resolved_stop_root = stop_root.resolve(strict=True)
    try:
        frozen_ledger_root = Path(
            str(predecessor_timing.get("ledger_dir", ""))
        ).resolve(strict=True)
    except (OSError, RuntimeError) as error:
        raise ConfigurationError("原 Campaign 的 Ledger 路径不可信。") from error
    if frozen_ledger_root != resolved_stop_root:
        raise ConfigurationError("停线 checkpoint 与原 Campaign 绑定的 Ledger 不一致。")
    if final_execution_context is not None:
        try:
            current_stop = codex_upgrade_timing_ledger.inspect_ledger(
                resolved_stop_root
            )
        except (
            OSError,
            codex_upgrade_timing_ledger.TimingLedgerError,
        ) as error:
            raise ConfigurationError("最终 epoch 停线 Ledger 无法读取。") from error
        if (
            current_stop.get("status") != "stopped"
            or current_stop.get("head_sequence") != stop_summary.get("head_sequence")
            or current_stop.get("head_sha256") != stop_summary.get("head_sha256")
        ):
            raise ConfigurationError("最终 epoch 停线 checkpoint 不是当前终态 head。")

    recovery_arguments = argparse.Namespace(
        campaign_mode="preflight_only",
        campaign_purpose=manifest["campaign_purpose"],
        baseline_version=manifest["baseline_version"],
        target_version=manifest["target_version"],
        timing_ledger_dir=values["recovery_timing_ledger_dir"],
        timing_receipt=values["recovery_timing_receipt"],
        arm64_environment_root=values["recovery_arm64_environment_root"],
        arm64_environment_receipt=values[
            "recovery_arm64_environment_receipt"
        ],
    )
    recovery_controls = _plan_control_receipts(recovery_arguments)
    recovery_timing = recovery_controls["upgrade_timing"]
    if (
        recovery_timing["ledger_dir"] == predecessor_timing.get("ledger_dir")
        or recovery_timing["upgrade_id"] == predecessor_timing.get("upgrade_id")
        or recovery_timing["evidence_decision"]
        != predecessor_timing.get("evidence_decision")
    ):
        raise ConfigurationError(
            "恢复 Ledger 必须使用新的目录和 upgrade-id，并保留证据复用决定。"
        )
    if final_execution_context is not None:
        recovery_ledger_root = Path(str(recovery_timing["ledger_dir"]))
        recovery_plan = _read_json(
            recovery_ledger_root / "ledger.json",
            "最终 epoch producer 恢复 Ledger",
        )
        if (
            recovery_plan.get("total_budget_minutes") != 180
            or stop_summary.get("total_live_request_count") != 0
        ):
            raise ConfigurationError(
                "最终 epoch producer 恢复必须使用 180 分钟 Ledger，且前序 live 计数为 0。"
            )

    current_tool_sha256 = str(current_tool.get("files_sha256", ""))
    if not SHA256_RE.fullmatch(current_tool_sha256):
        raise ConfigurationError("当前评估工具身份非法。")
    recovery_tool_identity = _tool_identity()
    if recovery_tool_identity["files_sha256"] != current_tool_sha256:
        raise ConfigurationError("恢复演练工具身份与当前评估工具不一致。")

    # 先证明演练来自同一新 Ledger、ARM64 P0 和当前工具的 preflight，
    # 再读取其受管版本化场景。Formal 只允许承接历史 source_spec 摘要，
    # 不能把 Campaign 内规范化副本反向当成新预检输入。
    recovery_manifest = json.loads(json.dumps(manifest, ensure_ascii=False))
    recovery_manifest["tool_identity"] = recovery_tool_identity
    recovery_manifest["control_receipts"] = recovery_controls
    preflight_dir, preflight_manifest = (
        _assert_recovery_rehearsal_uses_successor_controls(
            arguments,
            recovery_manifest,
        )
    )
    target_scenario_override = _recovery_rehearsal_target_scenario_override(
        campaign_dir,
        manifest,
        preflight_dir,
        preflight_manifest,
    )
    expected_rehearsal_contract = _job_rehearsal_contract_from_manifest(
        campaign_dir,
        manifest,
        target_scenario_override=target_scenario_override,
        tool_files_sha256_override=current_tool_sha256,
    )
    rehearsal_root = values["job_rehearsal_root"]
    rehearsal_receipt = values["job_rehearsal_receipt"]
    assert isinstance(rehearsal_root, Path) and isinstance(rehearsal_receipt, Path)
    recovery_controls["job_rehearsal"] = _job_rehearsal_control_from_receipt(
        rehearsal_root,
        rehearsal_receipt,
        expected_rehearsal_contract,
        allow_incremental_noop=True,
    )

    stop_file = resolved_stop_root / stop_relative
    result = {
        "schema_version": TOOL_EVALUATION_RECOVERY_CONTROLS_SCHEMA,
        "predecessor": {
            "upgrade_timing": dict(predecessor_timing),
            "arm64_environment": dict(predecessor_arm),
        },
        "stop_checkpoint": {
            "ledger_dir": str(resolved_stop_root),
            "receipt": {
                "path": stop_relative,
                "sha256": file_sha256(stop_file),
                "bytes": stop_file.stat().st_size,
            },
            "upgrade_id": stop_summary["upgrade_id"],
            "evidence_decision": stop_summary["evidence_decision"],
            "active_phase": stop_summary["active_phase"],
            "head_sequence": stop_summary["head_sequence"],
            "head_sha256": stop_summary["head_sha256"],
            "total_elapsed_seconds": stop_summary["total_elapsed_seconds"],
            "total_live_request_count": stop_summary[
                "total_live_request_count"
            ],
        },
        "recovery": recovery_controls,
        "current_tool_files_sha256": current_tool_sha256,
    }
    if legacy_vc0_scope is not None:
        result["legacy_vc0_recovery"] = {
            "mode": "formal_candidate_attempt",
            "source_attempt_id": legacy_vc0_scope["source_attempt_id"],
            "source_attempt_digest": legacy_vc0_scope["source_attempt_digest"],
            "execute_job_ids": list(legacy_vc0_scope["execute_job_ids"]),
        }
    if final_execution_context is not None:
        result["final_execution_epoch_recovery"] = final_execution_context[
            "marker"
        ]
    return result


def _control_path_from_recovery_binding(
    value: Any,
    *,
    root_field: str,
    label: str,
) -> tuple[Path, Path]:
    if not isinstance(value, Mapping):
        raise ConfigurationError(f"{label}控制绑定不是对象。")
    root = Path(str(value.get(root_field, "")))
    receipt = value.get("receipt")
    if (
        not isinstance(receipt, Mapping)
        or set(receipt) != {"path", "sha256", "bytes"}
        or not isinstance(receipt.get("path"), str)
        or not SHA256_RE.fullmatch(str(receipt.get("sha256", "")))
        or not isinstance(receipt.get("bytes"), int)
        or isinstance(receipt.get("bytes"), bool)
        or int(receipt["bytes"]) <= 0
    ):
        raise ConfigurationError(f"{label}收据绑定非法。")
    return root, root / str(receipt["path"])


def _validate_phase_recovery_controls(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    payload: Any,
    current_tool: Mapping[str, Any],
    *,
    phase: str | None = None,
    candidate_id: str | None = None,
    attempt_root: Path | None = None,
    attempt: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """从 transition 内的路径重建恢复控制链并要求逐字段一致。"""

    if not isinstance(payload, Mapping) or set(payload) not in ({
        "schema_version",
        "predecessor",
        "stop_checkpoint",
        "recovery",
        "current_tool_files_sha256",
    }, {
        "schema_version",
        "predecessor",
        "stop_checkpoint",
        "recovery",
        "current_tool_files_sha256",
        "legacy_vc0_recovery",
    }, {
        "schema_version",
        "predecessor",
        "stop_checkpoint",
        "recovery",
        "current_tool_files_sha256",
        "final_execution_epoch_recovery",
    }):
        raise ConfigurationError("评估 transition 的恢复控制结构非法。")
    if payload.get("schema_version") != TOOL_EVALUATION_RECOVERY_CONTROLS_SCHEMA:
        raise ConfigurationError("评估 transition 的恢复控制版本不受支持。")
    stop = payload.get("stop_checkpoint")
    recovery = payload.get("recovery")
    if not isinstance(stop, Mapping) or not isinstance(recovery, Mapping):
        raise ConfigurationError("评估 transition 缺少停线或恢复控制。")
    stop_root, stop_receipt = _control_path_from_recovery_binding(
        stop,
        root_field="ledger_dir",
        label="原 Campaign 停线 checkpoint",
    )
    timing_root, timing_receipt = _control_path_from_recovery_binding(
        recovery.get("upgrade_timing"),
        root_field="ledger_dir",
        label="恢复 UpgradeTimingLedger",
    )
    arm_root, arm_receipt = _control_path_from_recovery_binding(
        recovery.get("arm64_environment"),
        root_field="evidence_root",
        label="恢复 ARM64 P0",
    )
    rehearsal_root, rehearsal_receipt = _control_path_from_recovery_binding(
        recovery.get("job_rehearsal"),
        root_field="evidence_root",
        label="恢复完整 Job 演练",
    )
    arguments = argparse.Namespace(
        predecessor_stop_ledger_dir=stop_root,
        predecessor_stop_receipt=stop_receipt,
        recovery_timing_ledger_dir=timing_root,
        recovery_timing_receipt=timing_receipt,
        recovery_arm64_environment_root=arm_root,
        recovery_arm64_environment_receipt=arm_receipt,
        job_rehearsal_root=rehearsal_root,
        job_rehearsal_receipt=rehearsal_receipt,
    )
    expected = _phase_recovery_controls_from_arguments(
        arguments,
        campaign_dir,
        manifest,
        current_tool,
        phase=phase,
        candidate_id=candidate_id,
        attempt_root=attempt_root,
        attempt=attempt,
    )
    if dict(payload) != expected:
        raise ConfigurationError("评估 transition 的恢复控制身份或摘要漂移。")
    return expected


def _validate_frozen_phase_recovery_controls(
    payload: Any,
    *,
    attempt: Mapping[str, Any],
    transition: Mapping[str, Any],
    recovery_scope: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """只校验历史恢复控制的冻结结构，不重放其当前运行状态。"""

    allowed_fields = (
        {
            "schema_version",
            "predecessor",
            "stop_checkpoint",
            "recovery",
            "current_tool_files_sha256",
        },
        {
            "schema_version",
            "predecessor",
            "stop_checkpoint",
            "recovery",
            "current_tool_files_sha256",
            "legacy_vc0_recovery",
        },
        {
            "schema_version",
            "predecessor",
            "stop_checkpoint",
            "recovery",
            "current_tool_files_sha256",
            "final_execution_epoch_recovery",
        },
    )
    if (
        not isinstance(payload, Mapping)
        or set(payload) not in allowed_fields
        or payload.get("schema_version")
        != TOOL_EVALUATION_RECOVERY_CONTROLS_SCHEMA
        or not SHA256_RE.fullmatch(
            str(payload.get("current_tool_files_sha256", ""))
        )
    ):
        raise ConfigurationError("历史评估 transition 的冻结恢复控制结构非法。")

    predecessor = payload.get("predecessor")
    recovery = payload.get("recovery")
    stop = payload.get("stop_checkpoint")
    if (
        not isinstance(predecessor, Mapping)
        or set(predecessor) != {"upgrade_timing", "arm64_environment"}
        or not isinstance(recovery, Mapping)
        or set(recovery)
        != {"upgrade_timing", "arm64_environment", "job_rehearsal"}
        or not isinstance(stop, Mapping)
    ):
        raise ConfigurationError("历史评估 transition 的冻结控制绑定不闭合。")

    bindings = (
        (predecessor.get("upgrade_timing"), "ledger_dir", "历史前序 Ledger"),
        (predecessor.get("arm64_environment"), "evidence_root", "历史前序 ARM64 P0"),
        (stop, "ledger_dir", "历史停线 checkpoint"),
        (recovery.get("upgrade_timing"), "ledger_dir", "历史恢复 Ledger"),
        (recovery.get("arm64_environment"), "evidence_root", "历史恢复 ARM64 P0"),
        (recovery.get("job_rehearsal"), "evidence_root", "历史恢复 Job 演练"),
    )
    for value, root_field, label in bindings:
        root, _ = _control_path_from_recovery_binding(
            value,
            root_field=root_field,
            label=label,
        )
        if not root.is_absolute():
            raise ConfigurationError(f"{label}根目录不是绝对路径。")

    predecessor_timing = predecessor["upgrade_timing"]
    recovery_timing = recovery["upgrade_timing"]
    assert isinstance(predecessor_timing, Mapping)
    assert isinstance(recovery_timing, Mapping)
    required_stop_fields = {
        "ledger_dir",
        "receipt",
        "upgrade_id",
        "evidence_decision",
        "active_phase",
        "head_sequence",
        "head_sha256",
        "total_elapsed_seconds",
        "total_live_request_count",
    }
    if (
        set(stop) != required_stop_fields
        or stop.get("ledger_dir") != predecessor_timing.get("ledger_dir")
        or stop.get("upgrade_id") != predecessor_timing.get("upgrade_id")
        or stop.get("evidence_decision")
        != predecessor_timing.get("evidence_decision")
        or stop.get("active_phase") not in codex_upgrade_timing_ledger.PHASE_ORDER
        or not isinstance(stop.get("head_sequence"), int)
        or isinstance(stop.get("head_sequence"), bool)
        or int(stop["head_sequence"]) < 1
        or not SHA256_RE.fullmatch(str(stop.get("head_sha256", "")))
        or not isinstance(stop.get("total_elapsed_seconds"), int)
        or isinstance(stop.get("total_elapsed_seconds"), bool)
        or int(stop["total_elapsed_seconds"]) < 0
        or not isinstance(stop.get("total_live_request_count"), int)
        or isinstance(stop.get("total_live_request_count"), bool)
        or int(stop["total_live_request_count"]) < 0
        or recovery_timing.get("ledger_dir") == predecessor_timing.get("ledger_dir")
        or recovery_timing.get("upgrade_id") == predecessor_timing.get("upgrade_id")
        or recovery_timing.get("evidence_decision")
        != predecessor_timing.get("evidence_decision")
    ):
        raise ConfigurationError("历史评估 transition 的冻结 Ledger 关系非法。")

    scope_execute = (
        list(recovery_scope.get("execute_job_ids", []))
        if isinstance(recovery_scope, Mapping)
        else []
    )
    legacy = payload.get("legacy_vc0_recovery")
    if legacy is not None and legacy != {
        "mode": "formal_candidate_attempt",
        "source_attempt_id": attempt.get("attempt_id"),
        "source_attempt_digest": attempt.get("attempt_digest"),
        "execute_job_ids": scope_execute,
    }:
        raise ConfigurationError("历史评估 transition 的 VC-0 恢复标记非法。")

    final_epoch = payload.get("final_execution_epoch_recovery")
    if final_epoch is not None:
        epoch_binding = (
            final_epoch.get("epoch") if isinstance(final_epoch, Mapping) else None
        )
        if (
            not isinstance(final_epoch, Mapping)
            or set(final_epoch)
            != {
                "mode",
                "epoch_index",
                "epoch",
                "source_attempt_id",
                "source_attempt_digest",
                "execute_job_ids",
                "reused_job_ids",
            }
            or final_epoch.get("mode") != "single-failed-producer-recovery"
            or final_epoch.get("epoch_index") != 2
            or final_epoch.get("source_attempt_id") != attempt.get("attempt_id")
            or final_epoch.get("source_attempt_digest")
            != attempt.get("attempt_digest")
            or final_epoch.get("execute_job_ids") != scope_execute
            or final_epoch.get("reused_job_ids")
            != list(
                recovery_scope.get("completed_job_ids", [])
                if isinstance(recovery_scope, Mapping)
                else []
            )
        ):
            raise ConfigurationError("历史评估 transition 的最终 epoch 恢复标记非法。")
        _require_file_binding(epoch_binding, "历史最终 execution epoch")
    return dict(payload)


def _tool_entry_index(identity: Mapping[str, Any]) -> dict[str, str]:
    entries = identity.get("entries")
    if not isinstance(entries, list):
        return {}
    return {
        str(item.get("path")): str(item.get("sha256"))
        for item in entries
        if isinstance(item, dict)
        and isinstance(item.get("path"), str)
        and SHA256_RE.fullmatch(str(item.get("sha256", "")))
    }


def _phase_evaluation_changed_files(
    expected_tool: Mapping[str, Any],
    current_tool: Mapping[str, Any],
) -> list[dict[str, Any]]:
    before = _tool_entry_index(expected_tool)
    after = _tool_entry_index(current_tool)
    changed: list[dict[str, Any]] = []
    for path in sorted(set(before) | set(after)):
        if before.get(path) == after.get(path):
            continue
        changed.append(
            {
                "path": path,
                "from_sha256": before.get(path),
                "to_sha256": after.get(path),
                "classification": (
                    "phase_scoped_hybrid"
                    if path in _PHASE_EVALUATION_HYBRID_FILES
                    else (
                        "evaluation"
                        if path in _EVALUATION_SIDE_FILES
                        or path in _WATCHDOG_ONLY_TOOL_FILES
                        else "failed_job_production"
                    )
                ),
            }
        )
    return changed


def _phase_evaluation_failed_job_production_changes(
    drift: Mapping[str, list[str]],
    *,
    phase: str,
    attempt: Mapping[str, Any],
    recovery_scope: Mapping[str, Any] | None,
) -> set[str]:
    """仅放行完全落入冻结失败闭集的已登记产出侧变化。"""

    production_paths = set(drift.get("production", [])) - set(
        _PHASE_EVALUATION_HYBRID_FILES
    )
    if not production_paths:
        return set()
    if (
        phase != "candidate"
        or attempt.get("status") != "failed"
        or not isinstance(recovery_scope, Mapping)
    ):
        raise ConfigurationError(
            "评估 transition 包含产出侧变化，且不属于失败 Candidate 闭集恢复。"
        )
    unknown_paths = production_paths - set(
        RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS
    )
    if unknown_paths:
        raise ConfigurationError(
            "评估 transition 包含未登记的产出侧变化："
            + "、".join(sorted(unknown_paths))
        )
    execute_ids = set(recovery_scope.get("execute_job_ids", []))
    completed_ids = set(recovery_scope.get("completed_job_ids", []))
    affected_ids = {
        job_id
        for path in production_paths
        for job_id in RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS[path]
    }
    if (
        not execute_ids
        or not affected_ids
        or not affected_ids.issubset(execute_ids)
        or affected_ids.intersection(completed_ids)
    ):
        raise ConfigurationError(
            "评估 transition 的产出侧变化超出冻结失败／待执行 Job 闭集。"
        )
    return production_paths


def _authorize_phase_recovery_production_paths(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    phase: str,
    candidate_id: str | None,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    recovery_scope: Mapping[str, Any],
) -> set[str]:
    """在复用历史结果前验证 transition，并返回可排除的精确产出文件。"""

    expected_tool = manifest.get("tool_identity")
    if not isinstance(expected_tool, Mapping):
        raise ConfigurationError("Campaign 缺少可分级的工具身份。")
    drift = _tool_identity_drift(current_tool, expected_tool)
    allowed_paths = _phase_evaluation_failed_job_production_changes(
        drift,
        phase=phase,
        attempt=attempt,
        recovery_scope=recovery_scope,
    )
    if allowed_paths:
        _load_phase_evaluation_transition(
            campaign_dir,
            manifest,
            attempt_root=attempt_root,
            attempt=attempt,
            operation="capture-run",
            current_tool=current_tool,
            drift=drift,
        )
    return allowed_paths


def _phase_recovery_exact_affected_job_ids(
    production_paths: Iterable[str],
    *,
    planned_job_ids: Iterable[str],
    recovery_scope: Mapping[str, Any],
) -> set[str]:
    """把已批准的产出文件变化收窄为冻结恢复闭集内的精确 Job。

    transition 已逐文件验证产出侧变化后，早期组件级影响结果不再可信：
    一个 ``relay`` 组件可能同时服务多个互不相干的 Job。这里必须重新从
    文件白名单计算，并用结果替换粗粒度集合，不能与其取并集。
    """

    paths = {str(path) for path in production_paths}
    unknown_paths = paths - set(RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS)
    if unknown_paths:
        raise ConfigurationError(
            "恢复 transition 包含没有 Job 映射的产出文件："
            + "、".join(sorted(unknown_paths))
        )
    affected = {
        job_id
        for path in paths
        for job_id in RUNTIME_SUCCESSOR_CHANGED_TOOL_PATH_JOB_IDS[path]
    }
    planned = {str(job_id) for job_id in planned_job_ids}
    execute = {
        str(job_id) for job_id in recovery_scope.get("execute_job_ids", [])
    }
    completed = {
        str(job_id) for job_id in recovery_scope.get("completed_job_ids", [])
    }
    if (
        not affected.issubset(planned)
        or not affected.issubset(execute)
        or affected.intersection(completed)
    ):
        raise ConfigurationError(
            "恢复 transition 的精确产出文件映射超出冻结 recovery_scope。"
        )
    return affected


def _phase_evaluation_environment_boundary(
    campaign_dir: Path,
    attempt_root: Path,
    attempt: Mapping[str, Any],
) -> str:
    """校验失败 attempt 的小型前后环境收据，不读取原始抓包证据。

    评估 transition 只能承接已经完成且可恢复的 attempt。这里只读取
    probe／ARM64／restoration 收据和其摘要，任何 pcap、JSONL 或二进制正文
    都留到显式 seal/deep-verify 阶段处理。
    """

    environment = attempt.get("environment")
    if not isinstance(environment, Mapping):
        raise ConfigurationError("失败 attempt 缺少环境探针绑定。")
    raw_evidence_root = environment.get("evidence_root")
    evidence_root = Path(str(raw_evidence_root))
    if (
        not evidence_root.is_absolute()
        or evidence_root.is_symlink()
        or not evidence_root.is_dir()
    ):
        raise ConfigurationError("失败 attempt 的环境证据根不存在或不可信。")
    try:
        resolved_evidence_root = evidence_root.resolve(strict=True)
        resolved_attempt_root = attempt_root.resolve(strict=True)
        resolved_evidence_root.relative_to(resolved_attempt_root)
    except (OSError, RuntimeError, ValueError) as error:
        raise ConfigurationError("失败 attempt 的环境证据根越出 attempt。") from error

    required_bindings = (
        "before_probe",
        "after_probe",
        "arm64_before_receipt",
        "arm64_after_receipt",
        "restoration_report",
    )
    bindings: dict[str, dict[str, Any]] = {}
    paths: dict[str, Path] = {}
    for name in required_bindings:
        value = environment.get(name)
        if (
            not isinstance(value, Mapping)
            or set(value) != {"path", "sha256", "bytes"}
            or not isinstance(value.get("path"), str)
            or not value.get("path")
            or Path(str(value["path"])).is_absolute()
            or "\\" in str(value["path"])
            or str(PurePosixPath(str(value["path"]))) != str(value["path"])
            or any(
                part in {"", ".", ".."}
                for part in PurePosixPath(str(value["path"])).parts
            )
            or not SHA256_RE.fullmatch(str(value.get("sha256", "")))
            or not isinstance(value.get("bytes"), int)
            or isinstance(value.get("bytes"), bool)
            or int(value.get("bytes", 0)) <= 0
        ):
            raise ConfigurationError(f"失败 attempt 缺少完整 {name} 收据绑定。")
        path = evidence_root / str(value["path"])
        try:
            path.resolve(strict=True).relative_to(resolved_evidence_root)
        except (OSError, RuntimeError, ValueError) as error:
            raise ConfigurationError(f"失败 attempt 的 {name} 越出证据根。") from error
        if (
            path.is_symlink()
            or not path.is_file()
            or path.stat().st_size != value["bytes"]
            or file_sha256(path) != value["sha256"]
        ):
            raise ConfigurationError(f"失败 attempt 的 {name} 摘要漂移。")
        bindings[name] = dict(value)
        paths[name] = path

    # probe manifest 只验证结构和快照绑定，绝不遍历快照之外的证据目录。
    for name, expected_phase in (("before_probe", "before"), ("after_probe", "after")):
        probe = _read_json(paths[name], f"失败 attempt {name}")
        if (
            probe.get("schema_version")
            != codex_upgrade_environment_probe.PROBE_MANIFEST_SCHEMA
            or probe.get("phase") != expected_phase
            or not _is_rfc3339_timestamp(probe.get("observed_at_utc"))
            or not isinstance(probe.get("snapshots"), list)
        ):
            raise ConfigurationError(f"失败 attempt 的 {name} 内容不完整。")
        snapshot_kinds = {
            item.get("kind")
            for item in probe["snapshots"]
            if isinstance(item, Mapping)
        }
        if not {"service", "containers", "database", "account", "configuration"}.issubset(
            snapshot_kinds
        ):
            raise ConfigurationError(f"失败 attempt 的 {name} 缺少环境快照。")

    arm64_values: dict[str, Mapping[str, Any]] = {}
    for name, expected_phase in (
        ("arm64_before_receipt", "attempt_before"),
        ("arm64_after_receipt", "attempt_after"),
    ):
        try:
            receipt = codex_upgrade_arm64_environment_receipt.replay(
                paths[name].parent,
                paths[name].name,
            )
        except (
            OSError,
            codex_upgrade_arm64_environment_receipt.Arm64EnvironmentReceiptError,
        ) as error:
            raise ConfigurationError(f"失败 attempt 的 {name} 无法重放。") from error
        if (
            receipt.get("status") != "passed"
            or receipt.get("phase") != expected_phase
            or receipt.get("subject_id") != attempt.get("attempt_id")
        ):
            raise ConfigurationError(f"失败 attempt 的 {name} 身份不一致。")
        arm64_values[name] = receipt
    if (
        arm64_values["arm64_before_receipt"].get("continuity_identity_sha256")
        != arm64_values["arm64_after_receipt"].get("continuity_identity_sha256")
    ):
        raise ConfigurationError("失败 attempt 前后 ARM64 环境身份不连续。")

    try:
        _validate_restoration_report(
            paths["restoration_report"],
            [resolved_evidence_root],
            phase=str(attempt.get("phase")),
            candidate_id=(
                str(attempt.get("candidate_id"))
                if attempt.get("candidate_id") is not None
                else None
            ),
        )
    except ConfigurationError as error:
        raise ConfigurationError("失败 attempt 的环境恢复收据无法重放。") from error

    return _fingerprint(
        {
            "evidence_root": str(resolved_evidence_root),
            "bindings": bindings,
            "arm64_continuity_identity_sha256": arm64_values[
                "arm64_before_receipt"
            ].get("continuity_identity_sha256"),
        }
    )


def _phase_evaluation_pre_job_environment_boundary(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    attempt_root: Path,
    attempt: Mapping[str, Any],
    *,
    planned_job_ids: set[str],
    checkpoint_path: Path,
) -> str:
    """校验首个 Job 前失败的严格边界，不读取任何抓包正文。

    该特例不会复用 Job 结果；它只证明运行停在 ``attempt:reserved``、没有
    Job／日志／checkpoint 产物，并绑定唯一 after 探针。目录枚举和小文件
    读取均有固定上限，不能退化为对历史证据树的递归扫描。
    """

    def directory_names(path: Path, label: str, *, maximum: int) -> list[str]:
        if path.is_symlink() or not path.is_dir():
            raise ConfigurationError(f"首个 Job 前失败的 {label} 不存在或不可信。")
        names: list[str] = []
        with os.scandir(path) as entries:
            for entry in entries:
                if len(names) >= maximum:
                    raise ConfigurationError(f"首个 Job 前失败的 {label} 超出有界目录上限。")
                names.append(entry.name)
        return sorted(names)

    _validate_attempt_incremental_fields(attempt, planned_job_ids)
    plan = attempt.get("incremental_plan")
    if (
        attempt.get("results") != []
        or not isinstance(plan, Mapping)
        or plan.get("planned_job_ids") != sorted(planned_job_ids)
        or plan.get("pending_job_ids") != sorted(planned_job_ids)
        or any(
            plan.get(name) != []
            for name in (
                "changed_components",
                "affected_job_ids",
                "reused_job_ids",
                "executed_job_ids",
                "failed_job_ids",
            )
        )
        or attempt.get("continuity") is not None
    ):
        raise ConfigurationError("首个 Job 前失败的增量计划不是全量 pending 闭集。")

    execution_error = attempt.get("execution_error")
    restoration_error = attempt.get("restoration_error")
    if (
        not isinstance(execution_error, Mapping)
        or not isinstance(execution_error.get("type"), str)
        or not execution_error.get("type")
        or not isinstance(execution_error.get("message"), str)
        or not execution_error.get("message")
        or not isinstance(restoration_error, Mapping)
    ):
        raise ConfigurationError("首个 Job 前失败缺少执行或恢复失败事实。")

    checkpoint = attempt.get("job_checkpoint")
    watchdog = attempt.get("watchdog")
    if (
        not isinstance(checkpoint, Mapping)
        or checkpoint.get("record_count") != 0
        or checkpoint.get("last_sequence") is not None
        or checkpoint.get("last_sha256") is not None
        or not isinstance(watchdog, Mapping)
        or watchdog.get("last_completed_job_id") is not None
        or watchdog.get("timeout_checkpoint") is not None
    ):
        raise ConfigurationError("首个 Job 前失败的 checkpoint 或 watchdog 不是空边界。")
    if directory_names(checkpoint_path, "checkpoint 目录", maximum=1):
        raise ConfigurationError("首个 Job 前失败的 checkpoint 目录不为空。")

    _validate_attempt_watchdog_bindings(
        campaign_dir,
        attempt_root,
        attempt,
        planned_job_ids=planned_job_ids,
    )
    heartbeat_path = _resolve_attempt_binding(
        campaign_dir,
        attempt_root,
        watchdog.get("heartbeat"),
        label="首个 Job 前失败 watchdog heartbeat",
        expected_name="watchdog-heartbeat.json",
    )
    assert heartbeat_path is not None
    heartbeat = _read_json(heartbeat_path, "首个 Job 前失败 watchdog heartbeat")
    if (
        heartbeat.get("operation") != "attempt:reserved"
        or heartbeat.get("last_completed_job_id") is not None
    ):
        raise ConfigurationError("首个 Job 前失败的 heartbeat 已进入 Job 或其它操作。")

    if attempt_root.is_symlink() or not attempt_root.is_dir():
        raise ConfigurationError("首个 Job 前失败的 attempt 根不存在或不可信。")
    evidence_root = attempt_root / "evidence"
    log_root = attempt_root / "logs"
    for path, label in ((evidence_root, "evidence 目录"), (log_root, "logs 目录")):
        _reject_symlink_components(path, attempt_root, f"首个 Job 前失败 {label}")
        if path.is_symlink() or not path.is_dir():
            raise ConfigurationError(f"首个 Job 前失败的 {label} 不存在或不可信。")
    expected_evidence_roots = [
        str(evidence_root.resolve(strict=True)),
        str(log_root.resolve(strict=True)),
    ]
    if attempt.get("evidence_roots") != expected_evidence_roots:
        raise ConfigurationError("首个 Job 前失败的证据根不是固定空运行边界。")
    if directory_names(log_root, "logs 目录", maximum=1):
        raise ConfigurationError("首个 Job 前失败的 logs 目录不为空。")
    if any(
        name.startswith("job-") and name.endswith(".json")
        for name in directory_names(attempt_root, "attempt 根目录", maximum=32)
    ):
        raise ConfigurationError("首个 Job 前失败却存在 Job 收据。")

    environment = attempt.get("environment")
    expected_environment_fields = {
        "evidence_root",
        "before_probe",
        "after_probe",
        "restoration_report",
        "arm64_before_receipt",
        "arm64_after_receipt",
    }
    if (
        not isinstance(environment, Mapping)
        or set(environment) != expected_environment_fields
        or environment.get("evidence_root") != expected_evidence_roots[0]
        or any(
            environment.get(name) is not None
            for name in (
                "before_probe",
                "restoration_report",
                "arm64_before_receipt",
                "arm64_after_receipt",
            )
        )
    ):
        raise ConfigurationError("首个 Job 前失败的环境边界不闭合。")

    after_binding = environment.get("after_probe")
    if (
        not isinstance(after_binding, Mapping)
        or set(after_binding) != {"path", "sha256", "bytes"}
        or after_binding.get("path") != "environment/after/probe-manifest.json"
        or not SHA256_RE.fullmatch(str(after_binding.get("sha256", "")))
        or not isinstance(after_binding.get("bytes"), int)
        or isinstance(after_binding.get("bytes"), bool)
        or not 0 < int(after_binding.get("bytes", 0)) <= 1024 * 1024
    ):
        raise ConfigurationError("首个 Job 前失败缺少可信 after 探针绑定。")

    environment_root = evidence_root / "environment"
    receipts_root = evidence_root / "receipts"
    after_root = environment_root / "after"
    arm64_before_root = environment_root / "arm64-before"
    arm64_after_root = environment_root / "arm64-after"
    if directory_names(evidence_root, "evidence 目录", maximum=3) != [
        "environment",
        "receipts",
    ]:
        raise ConfigurationError("首个 Job 前失败的 evidence 目录存在额外产物。")
    if directory_names(environment_root, "environment 目录", maximum=4) != [
        "after",
        "arm64-after",
        "arm64-before",
    ]:
        raise ConfigurationError("首个 Job 前失败的 environment 目录存在额外阶段。")
    for path, label in (
        (receipts_root, "receipts 目录"),
        (arm64_before_root, "arm64-before 目录"),
        (arm64_after_root, "arm64-after 目录"),
    ):
        if directory_names(path, label, maximum=1):
            raise ConfigurationError(f"首个 Job 前失败的 {label} 不为空。")

    after_path = evidence_root / str(after_binding["path"])
    if (
        after_path.is_symlink()
        or not after_path.is_file()
        or after_path.stat().st_size != after_binding["bytes"]
        or file_sha256(after_path) != after_binding["sha256"]
    ):
        raise ConfigurationError("首个 Job 前失败的 after 探针摘要漂移。")
    probe = _read_json(after_path, "首个 Job 前失败 after 探针")
    configuration = manifest.get("configuration")
    expected_targets = (
        {
            "service": configuration.get("service_container"),
            "keeper": configuration.get("keeper_container"),
            "postgres": configuration.get("postgres_container"),
            "redis": configuration.get("redis_container"),
            "capture": configuration.get("capture_container"),
        }
        if isinstance(configuration, Mapping)
        else None
    )
    snapshots = probe.get("snapshots")
    if (
        set(probe)
        != {
            "observed_at_utc",
            "phase",
            "schema_version",
            "selected_account_id",
            "selected_key_id",
            "snapshots",
            "targets",
        }
        or probe.get("schema_version")
        != codex_upgrade_environment_probe.PROBE_MANIFEST_SCHEMA
        or probe.get("phase") != "after"
        or not _is_rfc3339_timestamp(probe.get("observed_at_utc"))
        or not isinstance(configuration, Mapping)
        or probe.get("selected_account_id") != configuration.get("codex_account_id")
        or probe.get("selected_key_id") != configuration.get("api_key_id")
        or probe.get("targets") != expected_targets
        or not isinstance(snapshots, list)
        or len(snapshots) != len(ENVIRONMENT_STATE_FILES)
    ):
        raise ConfigurationError("首个 Job 前失败的 after 探针身份不完整。")

    snapshot_bindings: dict[str, dict[str, Any]] = {}
    expected_after_names = {"probe-manifest.json"}
    for snapshot in snapshots:
        if not isinstance(snapshot, Mapping):
            raise ConfigurationError("首个 Job 前失败的 after 快照绑定非法。")
        kind = snapshot.get("kind")
        expected_name = ENVIRONMENT_STATE_FILES.get(str(kind))
        if (
            set(snapshot) != {"bytes", "comparison", "kind", "path", "sha256"}
            or expected_name is None
            or snapshot.get("path") != expected_name
            or str(kind) in snapshot_bindings
            or not isinstance(snapshot.get("comparison"), Mapping)
            or not isinstance(snapshot.get("bytes"), int)
            or isinstance(snapshot.get("bytes"), bool)
            or not 0 < int(snapshot.get("bytes", 0)) <= 1024 * 1024
            or not SHA256_RE.fullmatch(str(snapshot.get("sha256", "")))
        ):
            raise ConfigurationError("首个 Job 前失败的 after 快照绑定非法。")
        snapshot_path = after_root / expected_name
        if (
            snapshot_path.is_symlink()
            or not snapshot_path.is_file()
            or snapshot_path.stat().st_size != snapshot["bytes"]
            or file_sha256(snapshot_path) != snapshot["sha256"]
        ):
            raise ConfigurationError("首个 Job 前失败的 after 快照摘要漂移。")
        expected_after_names.add(expected_name)
        snapshot_bindings[str(kind)] = dict(snapshot)
    if set(snapshot_bindings) != set(ENVIRONMENT_STATE_FILES):
        raise ConfigurationError("首个 Job 前失败的 after 快照种类不完整。")
    if set(directory_names(after_root, "after 目录", maximum=8)) != expected_after_names:
        raise ConfigurationError("首个 Job 前失败的 after 目录存在额外产物。")

    return _fingerprint(
        {
            "source_mode": "pre_job_failure",
            "evidence_root": expected_evidence_roots[0],
            "after_probe": dict(after_binding),
            "snapshots": [snapshot_bindings[kind] for kind in sorted(snapshot_bindings)],
            "watchdog_heartbeat": dict(watchdog["heartbeat"]),
            "checkpoint": {
                "path": checkpoint.get("path"),
                "record_count": 0,
                "last_sequence": None,
                "last_sha256": None,
            },
            "execution_error": dict(execution_error),
            "restoration_error": dict(restoration_error),
        }
    )


def _phase_evaluation_recovery_scope(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    phase: str,
    candidate_id: str | None,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    allow_empty: bool = False,
    allow_awaiting_failures: bool = False,
) -> dict[str, Any]:
    """建立失败 attempt 的确定性重跑闭集。

    普通 partial attempt 只有至少一个 Job 已完成时才允许恢复；首个 Job 前
    失败则必须满足严格空边界，并把全部冻结 Job 纳入执行闭集。返回值会写入
    transition 摘要，使下一轮不能扩大执行范围。
    """

    source_status = attempt.get("status")
    if source_status != "failed" and not (
        allow_awaiting_failures and source_status == "awaiting_receipts"
    ):
        raise ConfigurationError("只有 failed attempt 可以建立恢复 transition。")
    if (
        attempt.get("phase") != phase
        or attempt.get("candidate_id") != candidate_id
        or attempt.get("campaign_id") != manifest.get("campaign_id")
        or attempt.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or not isinstance(attempt.get("attempt_id"), str)
        or not SHA256_RE.fullmatch(str(attempt.get("run_nonce", "")))
        or not SHA256_RE.fullmatch(str(attempt.get("attempt_digest", "")))
    ):
        raise ConfigurationError("失败 attempt 的 Campaign／phase／nonce 身份不完整。")

    reservation = _load_capture_reservation(
        campaign_dir,
        attempt_root,
        phase=phase,
        candidate_id=candidate_id,
        _manifest=manifest,
    )
    planned_rows = reservation.get("planned_jobs")
    if not isinstance(planned_rows, list) or not planned_rows:
        raise ConfigurationError("失败 attempt 缺少已冻结 Job 计划。")
    planned: dict[str, str] = {}
    for row in planned_rows:
        if (
            not isinstance(row, Mapping)
            or not isinstance(row.get("id"), str)
            or not SAFE_ID_RE.fullmatch(str(row.get("id")))
            or not SHA256_RE.fullmatch(str(row.get("execution_sha256", "")))
            or row["id"] in planned
        ):
            raise ConfigurationError("失败 attempt 的 Job 计划身份非法。")
        planned[str(row["id"])] = str(row["execution_sha256"])

    results = attempt.get("results")
    if not isinstance(results, list):
        raise ConfigurationError("失败 attempt 缺少 Job 结果。")
    result_by_id: dict[str, Mapping[str, Any]] = {}
    for result in results:
        if not isinstance(result, Mapping) or not isinstance(result.get("id"), str):
            raise ConfigurationError("失败 attempt 的 Job 结果身份非法。")
        job_id = str(result["id"])
        if job_id in result_by_id or job_id not in planned:
            raise ConfigurationError("失败 attempt 的 Job 结果不在冻结计划内。")
        if result.get("execution_sha256") != planned[job_id]:
            raise ConfigurationError("失败 attempt 的 Job 执行摘要漂移。")
        if result.get("status") not in {"complete", "failed"}:
            raise ConfigurationError("失败 attempt 的 Job 状态非法。")
        result_by_id[job_id] = result
    completed_ids = sorted(
        job_id for job_id, result in result_by_id.items() if result.get("status") == "complete"
    )
    failed_ids = sorted(
        job_id for job_id, result in result_by_id.items() if result.get("status") == "failed"
    )
    pending_ids = sorted(set(planned) - set(result_by_id))
    execute_ids = sorted(set(failed_ids) | set(pending_ids))
    if source_status == "awaiting_receipts":
        if phase != "candidate" or not failed_ids:
            raise ConfigurationError(
                "awaiting_receipts 只有包含失败 Candidate Job 时才能作为后继恢复源。"
            )
        if any(
            bool(result_by_id[job_id].get("required")) for job_id in failed_ids
        ):
            raise ConfigurationError(
                "awaiting_receipts 的失败项必须全部是可选 Job。"
            )
        client_after = (
            attempt_root
            / "evidence"
            / "environment"
            / "client-after"
            / "probe-manifest.json"
        )
        client_receipt = (
            attempt_root
            / "evidence"
            / "receipts"
            / "client-restoration-report.json"
        )
        seal_files = [
            path
            for pattern in ("seal-draft*.json", "seal-preview*.json")
            for path in attempt_root.glob(pattern)
        ]
        if client_after.exists() or client_receipt.exists() or seal_files:
            raise ConfigurationError(
                "awaiting_receipts 已进入 Kilo／seal 边界，禁止改作产出工具后继恢复源。"
            )
    pre_job_failure = (
        not completed_ids
        and not failed_ids
        and not result_by_id
        and pending_ids == sorted(planned)
    )
    if not completed_ids and not pre_job_failure:
        raise ConfigurationError("失败 attempt 没有已完成 Job，禁止原地 transition。")
    if not execute_ids and not allow_empty:
        raise ConfigurationError("失败 attempt 没有可重跑 Job，禁止建立 transition。")

    checkpoint = attempt.get("job_checkpoint")
    if not isinstance(checkpoint, Mapping) or (
        pre_job_failure
        and int(checkpoint.get("record_count", -1)) != 0
        or not pre_job_failure
        and int(checkpoint.get("record_count", 0)) <= 0
    ):
        raise ConfigurationError("失败 attempt 缺少可重放 Job checkpoint。")
    checkpoint_path = _resolve_attempt_binding(
        campaign_dir,
        attempt_root,
        checkpoint,
        label="失败 attempt Job checkpoint",
        expected_name="checkpoints",
        directory=True,
    )
    assert checkpoint_path is not None
    try:
        records = incremental_recovery.CheckpointStore(
            checkpoint_path,
            create=False,
        ).records()
    except incremental_recovery.IncrementalRecoveryError as error:
        raise ConfigurationError("失败 attempt Job checkpoint 链无法重放。") from error
    if len(records) != checkpoint.get("record_count"):
        raise ConfigurationError("失败 attempt Job checkpoint 数量漂移。")
    _validate_checkpoint_records(
        records,
        attempt,
        planned_job_ids=set(planned),
        strict_context=True,
    )
    if pre_job_failure:
        environment_boundary_sha256 = (
            _phase_evaluation_pre_job_environment_boundary(
                campaign_dir,
                manifest,
                attempt_root,
                attempt,
                planned_job_ids=set(planned),
                checkpoint_path=checkpoint_path,
            )
        )
    else:
        environment_boundary_sha256 = _phase_evaluation_environment_boundary(
            campaign_dir,
            attempt_root,
            attempt,
        )
    scope = {
        "schema_version": "codex-upgrade-failed-attempt-scope/v1",
        "source_attempt_id": str(attempt["attempt_id"]),
        "source_attempt_digest": str(attempt["attempt_digest"]),
        "run_nonce": str(attempt["run_nonce"]),
        "planned_job_ids": sorted(planned),
        "completed_job_ids": completed_ids,
        "failed_job_ids": failed_ids,
        "pending_job_ids": pending_ids,
        "execute_job_ids": execute_ids,
        "checkpoint": {
            "path": str(checkpoint.get("path")),
            "record_count": int(checkpoint["record_count"]),
            "last_sequence": checkpoint.get("last_sequence"),
            "last_sha256": checkpoint.get("last_sha256"),
        },
        "environment_boundary_sha256": environment_boundary_sha256,
    }
    if pre_job_failure:
        scope["source_mode"] = "pre_job_failure"
    return scope


def _validate_recovery_scope_plan(
    campaign_dir: Path,
    *,
    phase: str,
    candidate_id: str | None,
    source_root: Path,
    scope: Mapping[str, Any],
    planned_jobs: Iterable[Job],
    allow_empty: bool = False,
) -> tuple[set[str], set[str]]:
    """把 transition 的冻结计划与当前 Job 定义逐项对齐。

    ``recovery_scope`` 是恢复执行集合的唯一事实源。当前工具摘要、廉价
    影响分析或重新展开场景都不能自行扩大／缩小该集合；同时仍要确认当前
    Job 的 execution_sha256 与源 reservation 一致，避免把修改后的命令套在
    历史证据上。
    """

    def ids(name: str) -> set[str]:
        values = scope.get(name)
        if (
            not isinstance(values, list)
            or values != sorted(set(values))
            or not all(
                isinstance(value, str) and SAFE_ID_RE.fullmatch(value)
                for value in values
            )
        ):
            raise ConfigurationError(f"恢复 transition 的 {name} 非法。")
        return {str(value) for value in values}

    # ``planned_jobs`` 可能由场景展开器返回生成器；恢复校验需要在同一份
    # 冻结计划上先做集合校验、再逐项验证摘要，不能因重复迭代而重新展开。
    planned_jobs = list(planned_jobs)

    planned_ids = ids("planned_job_ids")
    completed_ids = ids("completed_job_ids")
    failed_ids = ids("failed_job_ids")
    pending_ids = ids("pending_job_ids")
    execute_ids = ids("execute_job_ids")
    if (
        not planned_ids
        or (not execute_ids and not allow_empty)
        or completed_ids & execute_ids
        or completed_ids & pending_ids
        or failed_ids & completed_ids
        or failed_ids & pending_ids
        or failed_ids | pending_ids != execute_ids
        or completed_ids | execute_ids != planned_ids
    ):
        raise ConfigurationError("恢复 transition 的 Job 闭集不一致。")

    source_reservation = _load_capture_reservation(
        campaign_dir,
        source_root,
        phase=phase,
        candidate_id=candidate_id,
    )
    source_plan: dict[str, str] = {}
    for row in source_reservation.get("planned_jobs", []):
        if not isinstance(row, Mapping):
            raise ConfigurationError("失败 source attempt 的 Job 计划非法。")
        job_id = row.get("id")
        execution_sha256 = row.get("execution_sha256")
        if (
            not isinstance(job_id, str)
            or not SAFE_ID_RE.fullmatch(job_id)
            or not isinstance(execution_sha256, str)
            or not SHA256_RE.fullmatch(execution_sha256)
            or job_id in source_plan
        ):
            raise ConfigurationError("失败 source attempt 的 Job 计划身份非法。")
        source_plan[job_id] = execution_sha256
    current_plan = {
        job.job_id: _job_execution_sha256(job) for job in planned_jobs
    }
    if set(current_plan) != set(source_plan) or set(current_plan) != planned_ids:
        raise ConfigurationError(
            "恢复 transition 的冻结 Job 定义与当前计划不一致；禁止改用当前摘要重算。"
        )

    # 历史 Campaign 可能由旧版 ``_safe_plan`` 写出：其 Job 投影不含
    # ``environment`` 等完整执行字段；同时受管 producer 工作树也可能已迁移。
    # 这种情况下不能直接比较当前摘要，但只能放行已由封闭迁移规则逐字证明的
    # 坐标变化。其它任何差异仍 fail-close，且不改写历史 reservation。
    frozen_manifest: Mapping[str, Any] | None = None
    for job in planned_jobs:
        recorded_sha256 = source_plan[job.job_id]
        current_sha256 = current_plan[job.job_id]
        if current_sha256 == recorded_sha256:
            continue
        if frozen_manifest is None:
            frozen_manifest = load_campaign_manifest(campaign_dir)
        frozen_job = _frozen_job_definition(frozen_manifest, job.job_id)
        if not _relocated_job_execution_matches(
            job,
            recorded_sha256,
            frozen_job,
        ):
            raise ConfigurationError(
                "恢复 transition 的冻结 Job 定义与当前计划不一致；"
                "仅允许受管工作树路径迁移。"
            )
    return completed_ids, execute_ids


def _phase_evaluation_transition_source(
    campaign_dir: Path,
    *,
    phase: str,
    candidate_id: str | None,
    attempt_root: Path,
    attempt: Mapping[str, Any],
) -> tuple[Path, dict[str, Any], Path | None, int | None]:
    """解析新 attempt 上的 transition 绑定，返回真正的源 attempt。"""

    binding = attempt.get("evaluation_transition")
    if binding is None:
        return attempt_root, dict(attempt), None, None
    _require_file_binding(binding, "attempt 评估工具 transition")
    raw_path = str(binding["path"])
    parsed = PurePosixPath(raw_path)
    if (
        parsed.is_absolute()
        or str(parsed) != raw_path
        or "\\" in raw_path
        or any(part in {"", ".", ".."} for part in parsed.parts)
    ):
        raise ConfigurationError("attempt 评估工具 transition 路径非法。")
    bound_path = _campaign_file(campaign_dir, raw_path)
    if (
        bound_path.is_symlink()
        or not bound_path.is_file()
        or file_sha256(bound_path) != binding["sha256"]
    ):
        raise ConfigurationError("attempt 评估工具 transition 摘要漂移。")
    match = _PHASE_EVALUATION_TRANSITION_FILE_RE.fullmatch(bound_path.name)
    if match is None:
        raise ConfigurationError("attempt 评估工具 transition 文件名非法。")
    index = int(match.group("index") or "1")
    if index < 1 or index > MAX_PHASE_EVALUATION_TRANSITIONS:
        raise ConfigurationError("attempt 评估 transition 序号非法。")

    matches: list[Path] = []
    for current_phase, current_candidate_id, root in _campaign_attempt_roots(
        campaign_dir
    ):
        if current_phase != phase or current_candidate_id != candidate_id:
            continue
        try:
            if root.resolve(strict=True) == bound_path.parent.resolve(strict=True):
                matches.append(root)
        except (OSError, RuntimeError):
            continue
    if len(matches) != 1:
        raise ConfigurationError("attempt 评估 transition 未绑定同 Campaign 的唯一源 attempt。")
    source_root = matches[0]
    if source_root.resolve(strict=True) == attempt_root.resolve(strict=True):
        raise ConfigurationError("attempt 评估 transition 不得自绑定当前 attempt。")
    expected_path = _evaluation_transition_path(source_root, index)
    if expected_path.resolve(strict=True) != bound_path.resolve(strict=True):
        raise ConfigurationError("attempt 评估 transition 路径与序号不一致。")
    source_root, source_attempt = _load_capture_attempt(
        campaign_dir,
        phase,
        candidate_id,
        source_root.name,
    )
    return source_root, source_attempt, bound_path, index


def _phase_evaluation_recovery_successor_operations(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    phase: str,
    candidate_id: str | None,
    source_root: Path,
    source_attempt: Mapping[str, Any],
    successor_root: Path,
    successor_attempt: Mapping[str, Any],
    transition: Mapping[str, Any],
    current_tool: Mapping[str, Any] | None = None,
) -> tuple[str, ...]:
    """验证失败 attempt 的补跑闭集，并返回后继可用的离线操作。

    失败源 attempt 的 transition 本身只授权 ``capture-run``。补跑完成后，
    新 attempt 必须逐项承接源 attempt 的已完成结果、只执行源 attempt 的
    失败／未完成闭集，并以完整 checkpoint 进入 ``awaiting_receipts``；只有
    这些事实全部成立，才能把同一份 transition 用于 seal、compare、accept
    或 deep-verify。这里仅读取 attempt、reservation 和 checkpoint 等小型
    控制收据，不读取原始抓包证据。
    """

    if phase not in _PHASE_EVALUATION_OPERATIONS:
        raise ConfigurationError("评估 transition phase 非法。")
    if source_attempt.get("status") != "failed":
        raise ConfigurationError(
            "只有 failed source attempt 可以把 transition 承接到后继 attempt。"
        )
    if successor_root.resolve(strict=True) == source_root.resolve(strict=True):
        raise ConfigurationError("失败 source attempt 不得直接执行离线后续操作。")
    if successor_attempt.get("status") != "awaiting_receipts":
        raise ConfigurationError(
            "恢复后继 attempt 未完成闭集，暂不允许 seal／compare／accept。"
        )
    if (
        successor_attempt.get("phase") != phase
        or successor_attempt.get("candidate_id") != candidate_id
        or source_attempt.get("phase") != phase
        or source_attempt.get("candidate_id") != candidate_id
        or successor_attempt.get("campaign_id") != manifest.get("campaign_id")
        or source_attempt.get("campaign_id") != manifest.get("campaign_id")
        or _fingerprint(successor_attempt.get("identity"))
        != _fingerprint(source_attempt.get("identity"))
    ):
        raise ConfigurationError("恢复后继 attempt 与失败 source 身份不一致。")

    scope = transition.get("recovery_scope")
    if not isinstance(scope, Mapping):
        raise ConfigurationError("失败 transition 缺少恢复闭集。")

    def _scope_ids(name: str) -> list[str]:
        values = scope.get(name)
        if (
            not isinstance(values, list)
            or values != sorted(set(values))
            or not all(
                isinstance(value, str) and SAFE_ID_RE.fullmatch(value)
                for value in values
            )
        ):
            raise ConfigurationError(f"失败 transition 的 {name} 非法。")
        return [str(value) for value in values]

    planned_ids = _scope_ids("planned_job_ids")
    completed_ids = _scope_ids("completed_job_ids")
    failed_ids = _scope_ids("failed_job_ids")
    pending_ids = _scope_ids("pending_job_ids")
    execute_ids = _scope_ids("execute_job_ids")
    planned_set = set(planned_ids)
    completed_set = set(completed_ids)
    failed_set = set(failed_ids)
    pending_set = set(pending_ids)
    execute_set = set(execute_ids)
    if (
        not planned_set
        or completed_set & execute_set
        or completed_set & pending_set
        or failed_set & completed_set
        or failed_set & pending_set
        or failed_set | pending_set != execute_set
        or completed_set | execute_set != planned_set
    ):
        raise ConfigurationError("失败 transition 的 Job 闭集关系非法。")

    def _planned(reservation: Mapping[str, Any], label: str) -> dict[str, str]:
        rows = reservation.get("planned_jobs")
        if not isinstance(rows, list) or not rows:
            raise ConfigurationError(f"{label}缺少冻结 Job 计划。")
        output: dict[str, str] = {}
        for row in rows:
            if (
                not isinstance(row, Mapping)
                or not isinstance(row.get("id"), str)
                or not SAFE_ID_RE.fullmatch(str(row.get("id")))
                or not SHA256_RE.fullmatch(str(row.get("execution_sha256", "")))
                or row["id"] in output
            ):
                raise ConfigurationError(f"{label}的 Job 计划身份非法。")
            output[str(row["id"])] = str(row["execution_sha256"])
        return output

    source_reservation = _load_capture_reservation(
        campaign_dir,
        source_root,
        phase=phase,
        candidate_id=candidate_id,
    )
    successor_reservation = _load_capture_reservation(
        campaign_dir,
        successor_root,
        phase=phase,
        candidate_id=candidate_id,
    )
    source_planned = _planned(source_reservation, "失败 source attempt ")
    successor_planned = _planned(successor_reservation, "恢复后继 attempt ")
    if set(source_planned) != planned_set or successor_planned != source_planned:
        raise ConfigurationError("恢复后继 attempt 的 Job 计划超出失败闭集。")

    def _results(payload: Mapping[str, Any], label: str) -> dict[str, Mapping[str, Any]]:
        values = payload.get("results")
        if not isinstance(values, list):
            raise ConfigurationError(f"{label}缺少 Job 结果。")
        output: dict[str, Mapping[str, Any]] = {}
        for value in values:
            if (
                not isinstance(value, Mapping)
                or not isinstance(value.get("id"), str)
                or value["id"] in output
                or value["id"] not in planned_set
                or value.get("execution_sha256") != source_planned[value["id"]]
            ):
                raise ConfigurationError(f"{label}的 Job 结果身份非法。")
            output[str(value["id"])] = value
        return output

    source_results = _results(source_attempt, "失败 source attempt ")
    successor_results = _results(successor_attempt, "恢复后继 attempt ")
    if set(source_results) != completed_set | failed_set:
        raise ConfigurationError("失败 source attempt 的结果未与恢复闭集对齐。")
    if set(successor_results) != planned_set:
        raise ConfigurationError("恢复后继 attempt 未覆盖全部冻结 Job。")
    if any(source_results[item].get("status") != "complete" for item in completed_ids):
        raise ConfigurationError("失败 source attempt 的已完成 Job 状态非法。")
    if any(source_results[item].get("status") != "failed" for item in failed_ids):
        raise ConfigurationError("失败 source attempt 的失败 Job 状态非法。")

    expected_source_receipt = {
        "path": str((source_root / "attempt.json").relative_to(campaign_dir)),
        "sha256": file_sha256(source_root / "attempt.json"),
        "bytes": (source_root / "attempt.json").stat().st_size,
    }

    def _without_reuse_metadata(value: Mapping[str, Any]) -> dict[str, Any]:
        output = dict(value)
        for key in ("carried_from_attempt", "disposition", "source_receipt"):
            output.pop(key, None)
        return output

    current_jobs: dict[str, Job] | None = None

    def _matches_source_or_authorized_rebase(
        source_result: Mapping[str, Any],
        successor_result: Mapping[str, Any],
    ) -> bool:
        """接受逐字复用，或接受绑定当前工具身份的确定性元数据重算。"""

        nonlocal current_jobs
        source_without_reuse = _without_reuse_metadata(source_result)
        successor_without_reuse = _without_reuse_metadata(successor_result)
        if successor_without_reuse == source_without_reuse:
            return True
        if current_tool is None:
            return False
        if current_jobs is None:
            identity = successor_attempt.get("identity")
            if not isinstance(identity, Mapping):
                raise ConfigurationError("恢复后继 attempt 缺少不可变身份。")
            if phase == "candidate":
                jobs = _campaign_jobs(
                    campaign_dir,
                    dict(manifest),
                    "candidate",
                    candidate_id=candidate_id,
                    runtime_image=str(identity.get("image_reference", "")),
                    profile_id=str(identity.get("profile_id", "")),
                    profile_digest=str(identity.get("profile_digest", "")),
                    build_id=str(identity.get("build_id", "")),
                    deployed_version=str(identity.get("deployed_version", "")),
                    candidate_image_id=str(identity.get("image_id", "")),
                    source_tree_sha256=str(identity.get("source_tree_sha256", "")),
                    candidate_purpose=str(identity.get("candidate_purpose", "")),
                )
            else:
                jobs = _campaign_jobs(campaign_dir, dict(manifest), "official")
            current_jobs = {job.job_id: job for job in jobs}
        job = current_jobs.get(str(source_result.get("id")))
        identity = successor_attempt.get("identity")
        if job is None or not isinstance(identity, Mapping):
            return False
        expected = _rebase_reused_result(
            source_result,
            job,
            identity=identity,
            tool_identity=current_tool,
        )
        return successor_without_reuse == _without_reuse_metadata(expected)

    for job_id in completed_ids:
        source_result = source_results[job_id]
        successor_result = successor_results[job_id]
        if (
            successor_result.get("status") != "complete"
            or successor_result.get("disposition") != "reused"
            or successor_result.get("carried_from_attempt") != source_root.name
            or successor_result.get("source_receipt") != expected_source_receipt
            or not _matches_source_or_authorized_rebase(
                source_result,
                successor_result,
            )
        ):
            raise ConfigurationError(
                f"恢复后继 attempt 未只读承接已完成 Job：{job_id}"
            )
    for job_id in execute_ids:
        result = successor_results[job_id]
        if result.get("status") != "complete" or result.get("disposition") != "executed":
            raise ConfigurationError(
                f"恢复后继 attempt 的闭集 Job 未成功执行：{job_id}"
            )

    plan = successor_attempt.get("incremental_plan")
    if not isinstance(plan, Mapping):
        raise ConfigurationError("恢复后继 attempt 缺少增量计划。")
    if (
        set(plan.get("planned_job_ids", [])) != planned_set
        or set(plan.get("reused_job_ids", [])) != completed_set
        or set(plan.get("executed_job_ids", [])) != execute_set
        or set(plan.get("failed_job_ids", []))
        or set(plan.get("pending_job_ids", []))
    ):
        raise ConfigurationError("恢复后继 attempt 的增量计划未完成闭集。")

    checkpoint = successor_attempt.get("job_checkpoint")
    if not isinstance(checkpoint, Mapping) or int(checkpoint.get("record_count", 0)) <= 0:
        raise ConfigurationError("恢复后继 attempt 缺少完整 Job checkpoint。")
    checkpoint_path = _resolve_attempt_binding(
        campaign_dir,
        successor_root,
        checkpoint,
        label="恢复后继 Job checkpoint",
        expected_name="checkpoints",
        directory=True,
    )
    assert checkpoint_path is not None
    try:
        records = incremental_recovery.CheckpointStore(
            checkpoint_path,
            create=False,
        ).records()
    except incremental_recovery.IncrementalRecoveryError as error:
        raise ConfigurationError("恢复后继 Job checkpoint 链无法重放。") from error
    if len(records) != checkpoint.get("record_count"):
        raise ConfigurationError("恢复后继 Job checkpoint 数量漂移。")
    _validate_checkpoint_records(
        records,
        successor_attempt,
        planned_job_ids=planned_set,
        strict_context=True,
    )
    checkpoint_by_id = {str(record.get("item_id")): record for record in records}
    if set(checkpoint_by_id) != planned_set:
        raise ConfigurationError("恢复后继 Job checkpoint 未覆盖闭集。")
    for job_id in completed_ids:
        if checkpoint_by_id[job_id].get("disposition") != "reused":
            raise ConfigurationError(
                f"恢复后继 Job checkpoint 未记录 reused：{job_id}"
            )
    for job_id in execute_ids:
        if checkpoint_by_id[job_id].get("disposition") != "executed":
            raise ConfigurationError(
                f"恢复后继 Job checkpoint 未记录 executed：{job_id}"
            )
    return tuple(_PHASE_EVALUATION_OPERATIONS[phase])


_TERMINAL_TRANSITION_REQUIRED_OPERATIONS = {
    "isolation-clone",
    "isolation-transition-03-preview",
    "isolation-transition-03-approve",
    "isolation-seal-preview",
    "isolation-seal-approve",
    "isolation-compare",
    "isolation-accept",
}


def _terminal_transition_file_binding(
    root: Path,
    path: Path,
    *,
    label: str,
) -> dict[str, str]:
    """生成终端预检使用的根内只读文件绑定。"""

    if path.is_symlink() or not path.is_file():
        raise ConfigurationError(f"{label}不存在或不可信。")
    try:
        relative = path.resolve(strict=True).relative_to(root.resolve(strict=True))
    except (OSError, RuntimeError, ValueError) as error:
        raise ConfigurationError(f"{label}不在受管根目录内。") from error
    return {"path": relative.as_posix(), "sha256": file_sha256(path)}


def _terminal_transition_attempt_inventory(campaign_dir: Path) -> str:
    """摘要化 attempt 内不可变执行事实，排除本轮新增的离线封存文件。"""

    entries: list[dict[str, Any]] = []
    attempt_roots: list[Path] = []
    official_attempts = campaign_dir / "official" / "attempts"
    if official_attempts.is_dir() and not official_attempts.is_symlink():
        attempt_roots.extend(
            path
            for path in official_attempts.iterdir()
            if path.is_dir() and not path.is_symlink()
        )
    candidates_root = campaign_dir / "candidates"
    if candidates_root.is_dir() and not candidates_root.is_symlink():
        for candidate_root in candidates_root.iterdir():
            attempts = candidate_root / "attempts"
            if attempts.is_dir() and not attempts.is_symlink():
                attempt_roots.extend(
                    path
                    for path in attempts.iterdir()
                    if path.is_dir() and not path.is_symlink()
                )
    for root in sorted(attempt_roots):
        relative_root = root.relative_to(campaign_dir).as_posix()
        entries.append({"path": relative_root + "/", "bytes": 0, "sha256": None})
        for path in sorted(root.iterdir()):
            if path.is_symlink():
                raise ConfigurationError("终端预检 attempt 顶层含符号链接。")
            if not path.is_file() or not (
                path.name in {"attempt.json", "reservation.json"}
                or path.name.startswith("job-") and path.name.endswith(".json")
            ):
                continue
            entries.append(
                {
                    "path": path.relative_to(campaign_dir).as_posix(),
                    "bytes": path.stat().st_size,
                    "sha256": file_sha256(path),
                }
            )
    if not entries:
        raise ConfigurationError("终端预检缺少可比较的 attempt 执行事实。")
    return _fingerprint({"entries": entries})


def _terminal_transition_supervisor_audit(run_dir: Path) -> dict[str, Any]:
    """重放隔离全链父监督器，并要求七个动作均成功且无审计缺口。"""

    audit = _control_replacement_supervisor_audit(run_dir)
    if audit.get("summary", {}).get("state") != "stopped":
        raise ConfigurationError("终端预检父监督器必须正常 stopped。")
    events_path = run_dir / "events.ndjson"
    try:
        events = [
            json.loads(line)
            for line in events_path.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ConfigurationError("终端预检父监督器事件无法读取。") from error
    completed = {
        str(event.get("operation", "")).split(":", 1)[-1]
        for event in events
        if isinstance(event, Mapping)
        and event.get("event_type") == "action-finished"
        and event.get("status") == "passed"
    }
    missing = sorted(_TERMINAL_TRANSITION_REQUIRED_OPERATIONS - completed)
    if missing:
        raise ConfigurationError(
            "终端预检父监督器缺少已通过动作：" + "、".join(missing)
        )
    return audit


def _terminal_transition_preflight_facts(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    phase: str,
    candidate_id: str | None,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    successor_attempt_id: str,
    isolated_campaign_dir: Path,
    supervisor_run_dir: Path,
    current_tool: Mapping[str, Any],
) -> dict[str, Any]:
    """重放正式源、第 3 槽、隔离全链和父监督器，返回闭合预检事实。"""

    if (
        phase != "candidate"
        or not isinstance(candidate_id, str)
        or not SAFE_ID_RE.fullmatch(candidate_id)
        or attempt.get("status") != "failed"
    ):
        raise ConfigurationError("终端第 4 槽只适用于 failed Candidate source attempt。")
    if not SAFE_ID_RE.fullmatch(successor_attempt_id):
        raise ConfigurationError("终端预检 successor attempt-id 非法。")
    formal_transition_path = _evaluation_transition_path(
        attempt_root,
        STANDARD_PHASE_EVALUATION_TRANSITIONS,
    )
    _historical_phase_evaluation_transition_frozen_state(
        campaign_dir,
        manifest,
        attempt_root=attempt_root,
        attempt=attempt,
        transition_index=STANDARD_PHASE_EVALUATION_TRANSITIONS,
    )
    formal_transition = _read_json(
        formal_transition_path,
        "正式 Campaign transition-03",
    )

    try:
        isolated_root = isolated_campaign_dir.resolve(strict=True)
        formal_root = campaign_dir.resolve(strict=True)
        supervisor_root = supervisor_run_dir.resolve(strict=True)
    except (OSError, RuntimeError) as error:
        raise ConfigurationError("终端预检目录不存在。") from error
    if (
        isolated_campaign_dir.is_symlink()
        or not isolated_campaign_dir.is_dir()
        or isolated_root == formal_root
        or supervisor_run_dir.is_symlink()
        or not supervisor_run_dir.is_dir()
    ):
        raise ConfigurationError("终端预检隔离副本或监督器目录不可信。")
    try:
        isolated_root.relative_to(supervisor_root / "evidence")
    except ValueError as error:
        raise ConfigurationError("终端预检隔离副本不在父监督器 evidence 内。") from error

    isolated_manifest = _require_formal_campaign(isolated_root)
    if (
        file_sha256(isolated_root / "campaign.json")
        != file_sha256(formal_root / "campaign.json")
        or _fingerprint(isolated_manifest) != _fingerprint(manifest)
    ):
        raise ConfigurationError("终端预检隔离副本的 Campaign 清单漂移。")
    isolated_source_root, isolated_source = _load_capture_attempt(
        isolated_root,
        phase,
        candidate_id,
        str(attempt.get("attempt_id", "")),
    )
    formal_successor_root, formal_successor = _load_capture_attempt(
        formal_root,
        phase,
        candidate_id,
        successor_attempt_id,
    )
    isolated_successor_root, isolated_successor = _load_capture_attempt(
        isolated_root,
        phase,
        candidate_id,
        successor_attempt_id,
    )
    if (
        file_sha256(attempt_root / "attempt.json")
        != file_sha256(isolated_source_root / "attempt.json")
        or file_sha256(formal_successor_root / "attempt.json")
        != file_sha256(isolated_successor_root / "attempt.json")
        or _fingerprint(isolated_source) != _fingerprint(attempt)
        or _fingerprint(isolated_successor) != _fingerprint(formal_successor)
        or _terminal_transition_attempt_inventory(formal_root)
        != _terminal_transition_attempt_inventory(isolated_root)
    ):
        raise ConfigurationError("终端预检隔离副本改写了 attempt、Job 或预约事实。")

    isolated_transition = _validate_phase_evaluation_transition(
        isolated_root,
        isolated_manifest,
        attempt_root=isolated_source_root,
        attempt=isolated_source,
        current_tool=current_tool,
        transition_index=STANDARD_PHASE_EVALUATION_TRANSITIONS,
    )
    candidate = _load_stage_result(
        isolated_root,
        "capture-candidate",
        candidate_id,
    )
    comparison = _load_stage_result(isolated_root, "compare", candidate_id)
    acceptance = _load_stage_result(isolated_root, "accept", candidate_id)
    status = campaign_status(isolated_root, candidate_id)
    expected_transition_binding = _terminal_transition_file_binding(
        isolated_root,
        _evaluation_transition_path(
            isolated_source_root,
            STANDARD_PHASE_EVALUATION_TRANSITIONS,
        ),
        label="隔离 transition-03",
    )
    expected_attempt_binding = _terminal_transition_file_binding(
        isolated_root,
        isolated_successor_root / "attempt.json",
        label="隔离 successor attempt",
    )
    seal_preview_path = _seal_preview_path(
        isolated_successor_root,
        STANDARD_PHASE_EVALUATION_TRANSITIONS,
    )
    if (
        candidate.get("status") != "complete"
        or candidate.get("evaluation_transition") != expected_transition_binding
        or candidate.get("attempt") != expected_attempt_binding
        or candidate.get("seal_preview")
        != _terminal_transition_file_binding(
            isolated_root,
            seal_preview_path,
            label="隔离 seal-preview-03",
        )
        or comparison.get("status") != "complete"
        or comparison.get("offline_only") is not True
        or acceptance.get("status") != "complete"
        or acceptance.get("accepted") is not True
        or acceptance.get("production_state") != "accepted_not_activated"
        or status.get("status") != "ready"
    ):
        raise ConfigurationError("终端预检隔离副本未完整通过 seal／compare／accept。")

    supervisor_audit = _terminal_transition_supervisor_audit(supervisor_root)
    return {
        "formal_campaign": {
            "campaign_id": manifest.get("campaign_id"),
            "campaign_manifest_sha256": file_sha256(formal_root / "campaign.json"),
        },
        "phase": phase,
        "candidate_id": candidate_id,
        "source_attempt": {
            "attempt_id": attempt.get("attempt_id"),
            "attempt_digest": attempt.get("attempt_digest"),
        },
        "source_transition": {
            **_terminal_transition_file_binding(
                formal_root,
                formal_transition_path,
                label="正式 transition-03",
            ),
            "transition_index": STANDARD_PHASE_EVALUATION_TRANSITIONS,
            "transition_digest": formal_transition.get("transition_digest"),
        },
        "candidate_tool": {
            "files_sha256": current_tool.get("files_sha256"),
            "production_sha256": current_tool.get("production_sha256"),
            "evaluation_sha256": current_tool.get("evaluation_sha256"),
        },
        "isolated_validation": {
            "campaign_dir": str(isolated_root),
            "campaign_manifest_sha256": file_sha256(
                isolated_root / "campaign.json"
            ),
            "source_attempt_sha256": file_sha256(
                isolated_source_root / "attempt.json"
            ),
            "successor_attempt_id": successor_attempt_id,
            "successor_attempt_sha256": file_sha256(
                isolated_successor_root / "attempt.json"
            ),
            "immutable_attempt_files_sha256": (
                _terminal_transition_attempt_inventory(isolated_root)
            ),
            "transition": {
                **expected_transition_binding,
                "transition_index": STANDARD_PHASE_EVALUATION_TRANSITIONS,
                "transition_digest": isolated_transition.get("transition_digest"),
            },
            "seal_preview": _terminal_transition_file_binding(
                isolated_root,
                seal_preview_path,
                label="隔离 seal-preview-03",
            ),
            "candidate_result": _terminal_transition_file_binding(
                isolated_root,
                _stage_path(isolated_root, "capture-candidate", candidate_id)[1],
                label="隔离 Candidate 阶段收据",
            ),
            "comparison_result": _terminal_transition_file_binding(
                isolated_root,
                _stage_path(isolated_root, "compare", candidate_id)[1],
                label="隔离 compare 收据",
            ),
            "acceptance_result": _terminal_transition_file_binding(
                isolated_root,
                _stage_path(isolated_root, "accept", candidate_id)[1],
                label="隔离 accept 收据",
            ),
            "successor_projection": {"changed_fields": []},
            "status": "ready",
        },
        "supervisor_audit": supervisor_audit,
        "executed_job_count": 0,
        "live_request_count": 0,
        "raw_evidence_scanned_bytes": 0,
    }


def create_terminal_transition_preflight(
    arguments: argparse.Namespace,
) -> dict[str, Any]:
    """签发终端第 4 槽预检；只读重放正式与隔离 Campaign。"""

    campaign_dir = arguments.campaign_dir
    manifest = _require_formal_campaign(campaign_dir)
    phase = arguments.phase
    candidate_id = arguments.candidate_id if phase == "candidate" else None
    if phase != "candidate" or not candidate_id:
        raise ConfigurationError("终端 transition 预检只支持 Candidate phase。")
    attempt_root, attempt = _load_capture_attempt(
        campaign_dir,
        phase,
        candidate_id,
        arguments.attempt_id,
    )
    current_tool = _tool_identity(include_git=False)
    facts = _terminal_transition_preflight_facts(
        campaign_dir,
        manifest,
        phase=phase,
        candidate_id=candidate_id,
        attempt_root=attempt_root,
        attempt=attempt,
        successor_attempt_id=arguments.successor_attempt_id,
        isolated_campaign_dir=arguments.isolated_campaign_dir,
        supervisor_run_dir=arguments.supervisor_run_dir,
        current_tool=current_tool,
    )
    core = {
        "schema_version": TOOL_EVALUATION_TERMINAL_PREFLIGHT_SCHEMA,
        "created_at_utc": _utc_now(),
        **facts,
    }
    payload = {**core, "receipt_sha256": _fingerprint(core)}
    _secure_write_json_once(arguments.output, payload)
    return {
        "status": "passed",
        "receipt": str(arguments.output),
        "receipt_sha256": payload["receipt_sha256"],
        "executed_job_count": 0,
        "live_request_count": 0,
        "raw_evidence_scanned_bytes": 0,
    }


def _validate_terminal_transition_preflight_receipt(
    receipt_path: Path | None,
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    phase: str,
    candidate_id: str | None,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    current_tool: Mapping[str, Any],
) -> dict[str, str]:
    """重放一次性终端预检收据，并返回 transition 可冻结的外部绑定。"""

    if receipt_path is None or receipt_path.is_symlink() or not receipt_path.is_file():
        raise ConfigurationError("终端第 4 槽缺少隔离全链预检收据。")
    receipt = _read_json(receipt_path, "终端 transition 预检收据")
    expected_fields = {
        "schema_version",
        "created_at_utc",
        "formal_campaign",
        "phase",
        "candidate_id",
        "source_attempt",
        "source_transition",
        "candidate_tool",
        "isolated_validation",
        "supervisor_audit",
        "executed_job_count",
        "live_request_count",
        "raw_evidence_scanned_bytes",
        "receipt_sha256",
    }
    unsigned = dict(receipt)
    digest = unsigned.pop("receipt_sha256", None)
    if (
        set(receipt) != expected_fields
        or receipt.get("schema_version")
        != TOOL_EVALUATION_TERMINAL_PREFLIGHT_SCHEMA
        or not _is_rfc3339_timestamp(receipt.get("created_at_utc"))
        or digest != _fingerprint(unsigned)
        or receipt.get("executed_job_count") != 0
        or receipt.get("live_request_count") != 0
        or receipt.get("raw_evidence_scanned_bytes") != 0
    ):
        raise ConfigurationError("终端 transition 预检收据结构、自摘要或计数非法。")
    isolated = receipt.get("isolated_validation")
    if not isinstance(isolated, Mapping):
        raise ConfigurationError("终端 transition 预检缺少隔离验证事实。")
    successor_attempt_id = isolated.get("successor_attempt_id")
    isolated_campaign_dir = isolated.get("campaign_dir")
    supervisor = receipt.get("supervisor_audit")
    if (
        not isinstance(successor_attempt_id, str)
        or not isinstance(isolated_campaign_dir, str)
        or not isinstance(supervisor, Mapping)
        or not isinstance(supervisor.get("run_dir"), str)
    ):
        raise ConfigurationError("终端 transition 预检坐标非法。")
    facts = _terminal_transition_preflight_facts(
        campaign_dir,
        manifest,
        phase=phase,
        candidate_id=candidate_id,
        attempt_root=attempt_root,
        attempt=attempt,
        successor_attempt_id=successor_attempt_id,
        isolated_campaign_dir=Path(isolated_campaign_dir),
        supervisor_run_dir=Path(str(supervisor["run_dir"])),
        current_tool=current_tool,
    )
    for key, value in facts.items():
        if receipt.get(key) != value:
            raise ConfigurationError(f"终端 transition 预检事实漂移：{key}")
    return {"path": str(receipt_path.resolve(strict=True)), "sha256": file_sha256(receipt_path)}


def _build_phase_evaluation_transition_preview(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    phase: str,
    candidate_id: str | None,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    recovery_controls: Mapping[str, Any],
    transition_index: int = 1,
    frozen_recovery_scope: Mapping[str, Any] | None = None,
    reuse_frozen_recovery_scope: bool = False,
    terminal_preflight: Mapping[str, str] | None = None,
) -> dict[str, Any]:
    expected_tool = manifest.get("tool_identity")
    if not isinstance(expected_tool, Mapping):
        raise ConfigurationError("Campaign 缺少可分级的工具身份。")
    drift = _tool_identity_drift(current_tool, expected_tool)
    changed = _phase_evaluation_changed_files(expected_tool, current_tool)
    changed_paths = {item["path"] for item in changed}
    if (
        current_tool.get("files_sha256") == expected_tool.get("files_sha256")
        or not changed
    ):
        raise ConfigurationError("当前工具与 Campaign 冻结身份一致，无需 transition。")
    if phase not in _PHASE_EVALUATION_OPERATIONS:
        raise ConfigurationError("评估 transition phase 非法。")
    recovery_scope: dict[str, Any] | None = None
    if attempt.get("status") == "failed":
        if reuse_frozen_recovery_scope:
            recovery_scope = _validate_historical_recovery_scope(
                frozen_recovery_scope,
                attempt,
            )
        else:
            # 首槽只允许在所有小型控制收据完整、checkpoint 可重放且至少有
            # 一个已完成 Job 时原地恢复；具体执行闭集写入 transition 摘要。
            recovery_scope = _phase_evaluation_recovery_scope(
                campaign_dir,
                manifest,
                phase=phase,
                candidate_id=candidate_id,
                attempt_root=attempt_root,
                attempt=attempt,
            )
    elif attempt.get("status") != "awaiting_receipts":
        raise ConfigurationError("评估 transition 只允许 awaiting_receipts 或可恢复的 failed attempt。")
    elif reuse_frozen_recovery_scope and frozen_recovery_scope is not None:
        raise ConfigurationError("非失败 transition 不得继承 recovery_scope。")
    allowed_production_paths = _phase_evaluation_failed_job_production_changes(
        drift,
        phase=phase,
        attempt=attempt,
        recovery_scope=recovery_scope,
    )
    allowed_paths = (
        set(_EVALUATION_SIDE_FILES)
        | set(_WATCHDOG_ONLY_TOOL_FILES)
        | set(_PHASE_EVALUATION_HYBRID_FILES)
        | allowed_production_paths
    )
    if changed_paths - allowed_paths:
        raise ConfigurationError(
            "评估 transition 包含未分类的工具变化："
            + "、".join(sorted(changed_paths - allowed_paths))
        )
    if (
        attempt.get("phase") != phase
        or attempt.get("candidate_id") != candidate_id
        or attempt.get("campaign_id") != manifest.get("campaign_id")
        or attempt.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
    ):
        raise ConfigurationError("评估 transition 与 Campaign／attempt 身份不一致。")
    transition_path = _evaluation_transition_path(
        attempt_root,
        transition_index,
    ).resolve(strict=False)
    for raw_root in attempt.get("evidence_roots", []):
        root = Path(str(raw_root)).resolve(strict=False)
        if transition_path == root or transition_path.is_relative_to(root):
            raise ConfigurationError("评估 transition 输出不得写入原始证据边界。")
    core: dict[str, Any] = {
        "schema_version": TOOL_EVALUATION_TRANSITION_PREVIEW_SCHEMA,
        "campaign_id": manifest["campaign_id"],
        "campaign_mode": manifest["campaign_mode"],
        "campaign_purpose": manifest["campaign_purpose"],
        "campaign_manifest_sha256": file_sha256(campaign_dir / "campaign.json"),
        "phase": phase,
        "candidate_id": candidate_id,
        "attempt_id": attempt["attempt_id"],
        "attempt_digest": attempt["attempt_digest"],
        "evidence_boundary_sha256": _fingerprint(
            {
                "attempt_digest": attempt["attempt_digest"],
                "evidence_roots": attempt.get("evidence_roots"),
            }
        ),
        "from_tool_files_sha256": expected_tool["files_sha256"],
        "to_tool_files_sha256": current_tool["files_sha256"],
        "from_production_sha256": expected_tool["production_sha256"],
        "to_production_sha256": current_tool["production_sha256"],
        "from_evaluation_sha256": expected_tool["evaluation_sha256"],
        "to_evaluation_sha256": current_tool["evaluation_sha256"],
        "changed_files": changed,
        "allowed_operations": list(
            _phase_evaluation_allowed_operations(phase, attempt.get("status"))
        ),
        "recovery_controls": dict(recovery_controls),
        "raw_evidence_scanned_bytes": 0,
    }
    if recovery_scope is not None:
        core["recovery_scope"] = recovery_scope
    if transition_index == TERMINAL_PHASE_EVALUATION_TRANSITION:
        if terminal_preflight is None:
            raise ConfigurationError("终端第 4 槽缺少隔离全链预检绑定。")
        _require_file_binding(dict(terminal_preflight), "终端 transition 预检")
        core["terminal_preflight"] = dict(terminal_preflight)
    elif terminal_preflight is not None:
        raise ConfigurationError("普通 transition 不得绑定终端预检收据。")
    return {
        **core,
        "status": "approval_required",
        "review_sha256": _fingerprint(core),
    }


def _historical_phase_evaluation_transition_frozen_state(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    transition_index: int,
) -> tuple[dict[str, Any], dict[str, Any] | None]:
    """重放已批准 transition 的小型冻结事实，不检查控制的当前状态。"""

    if transition_index < 1 or transition_index > MAX_PHASE_EVALUATION_TRANSITIONS:
        raise ConfigurationError("历史评估 transition 序号非法。")
    path = _evaluation_transition_path(attempt_root, transition_index)
    if path.is_symlink() or not path.is_file():
        raise ConfigurationError("替代 transition 缺少紧邻的上一已批准槽位。")
    receipt = _read_json(path, "历史评估 transition")
    unsigned = dict(receipt)
    digest = unsigned.pop("transition_digest", None)
    expected_fields = {
        "schema_version",
        "approved_at_utc",
        "campaign_id",
        "campaign_manifest_sha256",
        "phase",
        "candidate_id",
        "attempt_id",
        "attempt_digest",
        "evidence_boundary_sha256",
        "from_tool_files_sha256",
        "to_tool_files_sha256",
        "from_production_sha256",
        "to_production_sha256",
        "from_evaluation_sha256",
        "to_evaluation_sha256",
        "changed_files",
        "allowed_operations",
        "recovery_controls",
        "preview",
        "review_sha256",
        "raw_evidence_scanned_bytes",
        "status",
        "transition_digest",
    }
    if transition_index == TERMINAL_PHASE_EVALUATION_TRANSITION:
        expected_fields.add("terminal_preflight")
    if attempt.get("status") == "failed":
        expected_fields.add("recovery_scope")
    expected_tool = manifest.get("tool_identity")
    expected_boundary = _fingerprint(
        {
            "attempt_digest": attempt.get("attempt_digest"),
            "evidence_roots": attempt.get("evidence_roots"),
        }
    )
    if (
        set(receipt) != expected_fields
        or receipt.get("schema_version") != TOOL_EVALUATION_TRANSITION_SCHEMA
        or receipt.get("status") != "approved"
        or not _is_rfc3339_timestamp(receipt.get("approved_at_utc"))
        or digest != _fingerprint(unsigned)
        or not isinstance(expected_tool, Mapping)
        or receipt.get("campaign_id") != manifest.get("campaign_id")
        or receipt.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or receipt.get("phase") != attempt.get("phase")
        or receipt.get("candidate_id") != attempt.get("candidate_id")
        or receipt.get("attempt_id") != attempt.get("attempt_id")
        or receipt.get("attempt_digest") != attempt.get("attempt_digest")
        or receipt.get("evidence_boundary_sha256") != expected_boundary
        or receipt.get("from_tool_files_sha256")
        != expected_tool.get("files_sha256")
        or receipt.get("from_production_sha256")
        != expected_tool.get("production_sha256")
        or receipt.get("from_evaluation_sha256")
        != expected_tool.get("evaluation_sha256")
        or not SHA256_RE.fullmatch(str(receipt.get("to_tool_files_sha256", "")))
        or not SHA256_RE.fullmatch(str(receipt.get("to_production_sha256", "")))
        or not SHA256_RE.fullmatch(str(receipt.get("to_evaluation_sha256", "")))
        or receipt.get("allowed_operations")
        != list(
            _phase_evaluation_allowed_operations(
                str(attempt.get("phase")),
                attempt.get("status"),
            )
        )
        or receipt.get("raw_evidence_scanned_bytes") != 0
    ):
        raise ConfigurationError("历史评估 transition 身份或自摘要非法。")

    changed = receipt.get("changed_files")
    before = _tool_entry_index(expected_tool)
    if (
        not isinstance(changed, list)
        or not changed
        or [item.get("path") for item in changed if isinstance(item, Mapping)]
        != sorted(
            {
                str(item.get("path"))
                for item in changed
                if isinstance(item, Mapping)
            }
        )
    ):
        raise ConfigurationError("历史评估 transition 的工具变化清单非法。")
    for item in changed:
        if (
            not isinstance(item, Mapping)
            or set(item)
            != {"path", "from_sha256", "to_sha256", "classification"}
            or not isinstance(item.get("path"), str)
            or item.get("from_sha256") != before.get(str(item["path"]))
            or (
                item.get("to_sha256") is not None
                and not SHA256_RE.fullmatch(str(item.get("to_sha256")))
            )
            or item.get("classification")
            not in {"evaluation", "phase_scoped_hybrid", "failed_job_production"}
        ):
            raise ConfigurationError("历史评估 transition 的工具变化绑定非法。")

    preview_binding = receipt.get("preview")
    _require_file_binding(preview_binding, "历史评估 transition 预览")
    assert isinstance(preview_binding, Mapping)
    preview_path = _campaign_file(campaign_dir, str(preview_binding["path"]))
    if (
        preview_path
        != _evaluation_transition_preview_path(attempt_root, transition_index)
        or preview_path.is_symlink()
        or not preview_path.is_file()
        or file_sha256(preview_path) != preview_binding["sha256"]
    ):
        raise ConfigurationError("历史评估 transition 预览绑定漂移。")
    preview = _read_json(preview_path, "历史评估 transition 预览")
    preview_core = {
        key: value
        for key, value in preview.items()
        if key not in {"status", "review_sha256"}
    }
    receipt_projection = {
        key: value
        for key, value in receipt.items()
        if key
        not in {
            "schema_version",
            "approved_at_utc",
            "preview",
            "status",
            "transition_digest",
        }
    }
    preview_projection = {
        key: value
        for key, value in preview.items()
        if key not in {"schema_version", "campaign_mode", "campaign_purpose", "status"}
    }
    if (
        preview.get("schema_version")
        != TOOL_EVALUATION_TRANSITION_PREVIEW_SCHEMA
        or preview.get("status") != "approval_required"
        or preview.get("campaign_mode") != manifest.get("campaign_mode")
        or preview.get("campaign_purpose") != manifest.get("campaign_purpose")
        or preview.get("review_sha256") != _fingerprint(preview_core)
        or receipt_projection != preview_projection
    ):
        raise ConfigurationError("历史评估 transition 与批准预览不一致。")

    scope_value = receipt.get("recovery_scope")
    recovery_scope = (
        _validate_historical_recovery_scope(scope_value, attempt)
        if attempt.get("status") == "failed"
        else None
    )
    recovery_controls = _validate_frozen_phase_recovery_controls(
        receipt.get("recovery_controls"),
        attempt=attempt,
        transition=receipt,
        recovery_scope=recovery_scope,
    )
    return recovery_controls, recovery_scope


def _validate_phase_evaluation_transition(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    current_tool: Mapping[str, Any],
    transition_index: int | None = None,
) -> dict[str, Any]:
    if transition_index is None:
        transition_index = _phase_evaluation_transition_index(
            attempt_root,
            current_tool,
            allocate=False,
        )
    path = _evaluation_transition_path(attempt_root, transition_index)
    if path.is_symlink() or not path.is_file():
        raise ConfigurationError(
            "当前工具含阶段限定变化；先执行 evaluation-transition 并批准摘要。"
        )
    receipt = _read_json(path, "评估工具 transition")
    unsigned = dict(receipt)
    digest = unsigned.pop("transition_digest", None)
    preview_binding = receipt.get("preview")
    expected_fields = {
        "schema_version",
        "approved_at_utc",
        "campaign_id",
        "campaign_manifest_sha256",
        "phase",
        "candidate_id",
        "attempt_id",
        "attempt_digest",
        "evidence_boundary_sha256",
        "from_tool_files_sha256",
        "to_tool_files_sha256",
        "from_production_sha256",
        "to_production_sha256",
        "from_evaluation_sha256",
        "to_evaluation_sha256",
        "changed_files",
        "allowed_operations",
        "recovery_controls",
        "preview",
        "review_sha256",
        "raw_evidence_scanned_bytes",
        "status",
        "transition_digest",
    }
    if transition_index == TERMINAL_PHASE_EVALUATION_TRANSITION:
        expected_fields.add("terminal_preflight")
    if attempt.get("status") == "failed":
        expected_fields.add("recovery_scope")
    if (
        set(receipt) != expected_fields
        or receipt.get("schema_version") != TOOL_EVALUATION_TRANSITION_SCHEMA
        or receipt.get("status") != "approved"
        or not _is_rfc3339_timestamp(receipt.get("approved_at_utc"))
        or digest != _fingerprint(unsigned)
    ):
        raise ConfigurationError("评估工具 transition 结构或自摘要非法。")
    _require_file_binding(preview_binding, "评估工具 transition 预览")
    preview_path = _campaign_file(campaign_dir, str(preview_binding["path"]))
    if (
        preview_path
        != _evaluation_transition_preview_path(attempt_root, transition_index)
        or preview_path.is_symlink()
        or not preview_path.is_file()
        or file_sha256(preview_path) != preview_binding["sha256"]
    ):
        raise ConfigurationError("评估工具 transition 预览绑定漂移。")
    preview = _read_json(preview_path, "评估工具 transition 预览")
    phase = str(attempt.get("phase"))
    candidate_id = attempt.get("candidate_id")
    terminal_preflight: dict[str, str] | None = None
    if transition_index == 1:
        recovery_controls = _validate_phase_recovery_controls(
            campaign_dir,
            manifest,
            preview.get("recovery_controls"),
            current_tool,
            phase=phase,
            candidate_id=(str(candidate_id) if candidate_id is not None else None),
            attempt_root=attempt_root,
            attempt=attempt,
        )
        frozen_recovery_scope = None
        reuse_frozen_recovery_scope = False
    else:
        recovery_scope_value = preview.get("recovery_scope")
        frozen_recovery_scope = (
            _validate_historical_recovery_scope(recovery_scope_value, attempt)
            if attempt.get("status") == "failed"
            else None
        )
        recovery_controls = _validate_frozen_phase_recovery_controls(
            preview.get("recovery_controls"),
            attempt=attempt,
            transition=preview,
            recovery_scope=frozen_recovery_scope,
        )
        reuse_frozen_recovery_scope = True
        if transition_index > 1:
            previous_controls, previous_scope = (
                _historical_phase_evaluation_transition_frozen_state(
                    campaign_dir,
                    manifest,
                    attempt_root=attempt_root,
                    attempt=attempt,
                    transition_index=transition_index - 1,
                )
            )
            if (
                recovery_controls != previous_controls
                or frozen_recovery_scope != previous_scope
            ):
                raise ConfigurationError(
                    "替代 transition 未原样继承上一槽冻结控制与恢复闭集。"
                )
        if transition_index == TERMINAL_PHASE_EVALUATION_TRANSITION:
            preflight_value = preview.get("terminal_preflight")
            _require_file_binding(preflight_value, "终端 transition 预检")
            assert isinstance(preflight_value, Mapping)
            terminal_preflight = _validate_terminal_transition_preflight_receipt(
                Path(str(preflight_value["path"])),
                campaign_dir,
                manifest,
                phase=phase,
                candidate_id=(
                    str(candidate_id) if candidate_id is not None else None
                ),
                attempt_root=attempt_root,
                attempt=attempt,
                current_tool=current_tool,
            )
            if terminal_preflight != dict(preflight_value):
                raise ConfigurationError("终端 transition 预检文件绑定漂移。")
    expected_preview = _build_phase_evaluation_transition_preview(
        campaign_dir,
        manifest,
        phase=phase,
        candidate_id=(str(candidate_id) if candidate_id is not None else None),
        attempt_root=attempt_root,
        attempt=attempt,
        current_tool=current_tool,
        recovery_controls=recovery_controls,
        transition_index=transition_index,
        frozen_recovery_scope=frozen_recovery_scope,
        reuse_frozen_recovery_scope=reuse_frozen_recovery_scope,
        terminal_preflight=terminal_preflight,
    )
    projected = {
        key: value
        for key, value in receipt.items()
        if key
        not in {
            "schema_version",
            "approved_at_utc",
            "preview",
            "status",
            "transition_digest",
        }
    }
    preview_projection = {
        key: value
        for key, value in preview.items()
        if key not in {"schema_version", "campaign_mode", "campaign_purpose", "status"}
    }
    if (
        preview != expected_preview
        or projected != preview_projection
        or receipt.get("campaign_id") != manifest.get("campaign_id")
        or receipt.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or receipt.get("attempt_id") != attempt.get("attempt_id")
        or receipt.get("attempt_digest") != attempt.get("attempt_digest")
        or receipt.get("raw_evidence_scanned_bytes") != 0
    ):
        raise ConfigurationError("评估工具 transition 身份、范围或工具摘要漂移。")
    return receipt


def _load_phase_evaluation_transition(
    campaign_dir: Path,
    manifest: Mapping[str, Any],
    *,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    operation: str,
    current_tool: Mapping[str, Any],
    drift: Mapping[str, list[str]],
) -> dict[str, str]:
    source_root, source_attempt, bound_path, bound_index = (
        _phase_evaluation_transition_source(
            campaign_dir,
            phase=str(attempt.get("phase", "")),
            candidate_id=(
                str(attempt.get("candidate_id"))
                if attempt.get("candidate_id") is not None
                else None
            ),
            attempt_root=attempt_root,
            attempt=attempt,
        )
    )
    transition_index = _phase_evaluation_transition_index(
        source_root,
        current_tool,
        allocate=False,
    )
    uses_replacement_transition = False
    if bound_index is not None and transition_index != bound_index:
        # successor 的 attempt.json 是不可变事实，只能继续保留创建它时使用的
        # transition 作为来源锚点。若之后仅修复评估侧并在同一失败 source
        # attempt 追加了更高序号的替代 transition，已完成闭集的 successor
        # 应直接使用当前工具摘要对应的新槽位做离线 seal，不能重写 attempt，
        # 更不能再次执行已经完成的 Job。
        if not (
            bound_path is not None
            and source_attempt.get("status") == "failed"
            and attempt.get("status") == "awaiting_receipts"
            and transition_index > bound_index
        ):
            raise ConfigurationError(
                "attempt 评估 transition 当前工具摘要不匹配绑定槽位。"
            )
        uses_replacement_transition = True
    receipt = _validate_phase_evaluation_transition(
        campaign_dir,
        manifest,
        attempt_root=source_root,
        attempt=source_attempt,
        current_tool=current_tool,
        transition_index=transition_index,
    )
    recovery_scope = receipt.get("recovery_scope")
    _phase_evaluation_failed_job_production_changes(
        drift,
        phase=str(source_attempt.get("phase", "")),
        attempt=source_attempt,
        recovery_scope=(
            recovery_scope if isinstance(recovery_scope, Mapping) else None
        ),
    )
    allowed_operations = set(receipt.get("allowed_operations", []))
    if source_attempt.get("status") == "failed" and bound_path is not None:
        # 失败源 attempt 的 transition 默认只授权 capture-run。新 attempt
        # 只有在完整承接／补跑闭集后，才获得本 phase 的离线后续授权；源
        # attempt 本身永远不能借 transition 直接 seal 或 accept。
        allowed_operations.update(
            _phase_evaluation_recovery_successor_operations(
                campaign_dir,
                manifest,
                phase=str(attempt.get("phase", "")),
                candidate_id=(
                    str(attempt.get("candidate_id"))
                    if attempt.get("candidate_id") is not None
                    else None
                ),
                source_root=source_root,
                source_attempt=source_attempt,
                successor_root=attempt_root,
                successor_attempt=attempt,
                transition=receipt,
                current_tool=current_tool,
            )
        )
    if operation not in allowed_operations:
        raise ConfigurationError(f"评估 transition 未授权当前操作：{operation}")
    path = _evaluation_transition_path(source_root, transition_index)
    if (
        bound_path is not None
        and not uses_replacement_transition
        and path.resolve(strict=True) != bound_path.resolve(strict=True)
    ):
        raise ConfigurationError("attempt 评估 transition 绑定路径漂移。")
    return {
        "path": path.relative_to(campaign_dir).as_posix(),
        "sha256": file_sha256(path),
    }


def _stage_evaluation_transition_binding(
    tool_impact: Mapping[str, Any] | None,
) -> dict[str, str] | None:
    """把计划身份校验结果收口为阶段收据允许的 transition 文件绑定。

    ``_verify_plan_identity`` 在恢复 attempt 上返回带影响闭集的包装对象，
    而阶段收据只允许保存不可变的 ``path``／``sha256``。直接把包装对象写入
    stage 会在批准 seal 时被 Schema 拒绝；这里与 run 路径使用同一收口规则。
    """

    if tool_impact is None:
        return None
    bound: Any = tool_impact.get("evaluation_transition")
    if bound is None and set(tool_impact) == {"path", "sha256"}:
        bound = tool_impact
    if bound is None:
        return None
    _require_file_binding(bound, "评估工具 transition")
    return {
        "path": str(bound["path"]),
        "sha256": str(bound["sha256"]),
    }


def create_phase_evaluation_transition(arguments: argparse.Namespace) -> dict[str, Any]:
    """两步审批只影响评估阶段的工具过渡，绝不读取原始证据内容。"""

    campaign_dir = arguments.campaign_dir
    manifest = _require_formal_campaign(campaign_dir)
    phase = arguments.phase
    candidate_id = arguments.candidate_id if phase == "candidate" else None
    if phase == "official" and arguments.candidate_id is not None:
        raise ConfigurationError("official transition 不得携带 --candidate-id。")
    if phase == "candidate" and not candidate_id:
        raise ConfigurationError("candidate transition 必须提供 --candidate-id。")
    attempt_root, attempt = _load_capture_attempt(
        campaign_dir,
        phase,
        candidate_id,
        arguments.attempt_id,
    )
    _bind_active_lease_attempt(
        campaign_dir,
        phase=phase,
        candidate_id=candidate_id,
        attempt_id=attempt.get("attempt_id"),
    )
    current_tool = _tool_identity(include_git=False)
    transition_index = _phase_evaluation_transition_index(
        attempt_root,
        current_tool,
        allocate=True,
    )
    terminal_preflight_path = getattr(
        arguments,
        "terminal_transition_preflight_receipt",
        None,
    )
    terminal_preflight: dict[str, str] | None = None
    if transition_index == TERMINAL_PHASE_EVALUATION_TRANSITION:
        terminal_preflight = _validate_terminal_transition_preflight_receipt(
            terminal_preflight_path,
            campaign_dir,
            manifest,
            phase=phase,
            candidate_id=candidate_id,
            attempt_root=attempt_root,
            attempt=attempt,
            current_tool=current_tool,
        )
    elif terminal_preflight_path is not None:
        raise ConfigurationError("第 1～3 槽不得提供终端 transition 预检收据。")
    if transition_index == 1:
        recovery_controls = _phase_recovery_controls_from_arguments(
            arguments,
            campaign_dir,
            manifest,
            current_tool,
            phase=phase,
            candidate_id=candidate_id,
            attempt_root=attempt_root,
            attempt=attempt,
        )
        frozen_recovery_scope = None
        reuse_frozen_recovery_scope = False
    else:
        recovery_controls, frozen_recovery_scope = (
            _historical_phase_evaluation_transition_frozen_state(
                campaign_dir,
                manifest,
                attempt_root=attempt_root,
                attempt=attempt,
                transition_index=transition_index - 1,
            )
        )
        reuse_frozen_recovery_scope = True
    preview = _build_phase_evaluation_transition_preview(
        campaign_dir,
        manifest,
        phase=phase,
        candidate_id=candidate_id,
        attempt_root=attempt_root,
        attempt=attempt,
        current_tool=current_tool,
        recovery_controls=recovery_controls,
        transition_index=transition_index,
        frozen_recovery_scope=frozen_recovery_scope,
        reuse_frozen_recovery_scope=reuse_frozen_recovery_scope,
        terminal_preflight=terminal_preflight,
    )
    preview_path = _evaluation_transition_preview_path(
        attempt_root,
        transition_index,
    )
    _write_or_verify_json(preview_path, preview)
    approval = arguments.approve_transition_sha256
    if approval is None:
        return {
            "status": "approval_required",
            "phase": phase,
            "candidate_id": candidate_id,
            "attempt_id": attempt["attempt_id"],
            "preview": str(preview_path),
            "transition_index": transition_index,
            "review_sha256": preview["review_sha256"],
            "changed_files": preview["changed_files"],
            "raw_evidence_scanned_bytes": 0,
        }
    if not SHA256_RE.fullmatch(str(approval)) or approval != preview["review_sha256"]:
        raise ConfigurationError("评估 transition 批准摘要与预览不一致。")
    receipt_path = _evaluation_transition_path(attempt_root, transition_index)
    if receipt_path.is_file() and not receipt_path.is_symlink():
        receipt = _validate_phase_evaluation_transition(
            campaign_dir,
            manifest,
            attempt_root=attempt_root,
            attempt=attempt,
            current_tool=current_tool,
            transition_index=transition_index,
        )
    else:
        preview_projection = {
            key: value
            for key, value in preview.items()
            if key not in {"schema_version", "campaign_mode", "campaign_purpose", "status"}
        }
        core: dict[str, Any] = {
            "schema_version": TOOL_EVALUATION_TRANSITION_SCHEMA,
            "approved_at_utc": _utc_now(),
            "campaign_id": manifest["campaign_id"],
            "campaign_manifest_sha256": file_sha256(campaign_dir / "campaign.json"),
            "phase": phase,
            "candidate_id": candidate_id,
            "attempt_id": attempt["attempt_id"],
            "attempt_digest": attempt["attempt_digest"],
            "evidence_boundary_sha256": preview["evidence_boundary_sha256"],
            "from_tool_files_sha256": preview["from_tool_files_sha256"],
            "to_tool_files_sha256": preview["to_tool_files_sha256"],
            "from_production_sha256": preview["from_production_sha256"],
            "to_production_sha256": preview["to_production_sha256"],
            "from_evaluation_sha256": preview["from_evaluation_sha256"],
            "to_evaluation_sha256": preview["to_evaluation_sha256"],
            "changed_files": preview["changed_files"],
            "allowed_operations": preview["allowed_operations"],
            "recovery_controls": preview["recovery_controls"],
            "preview": {
                "path": preview_path.relative_to(campaign_dir).as_posix(),
                "sha256": file_sha256(preview_path),
            },
            "review_sha256": preview["review_sha256"],
            "raw_evidence_scanned_bytes": 0,
            "status": "approved",
        }
        if "recovery_scope" in preview:
            # 失败源 attempt 的 transition 必须把冻结的失败／未完成闭集
            # 原样写入批准收据；后继 attempt 只能按这份不可变摘要补跑。
            core["recovery_scope"] = preview["recovery_scope"]
        if "terminal_preflight" in preview:
            core["terminal_preflight"] = preview["terminal_preflight"]
        receipt = {**core, "transition_digest": _fingerprint(core)}
        _write_or_verify_json(receipt_path, receipt)
        receipt = _validate_phase_evaluation_transition(
            campaign_dir,
            manifest,
            attempt_root=attempt_root,
            attempt=attempt,
            current_tool=current_tool,
            transition_index=transition_index,
        )
    return {
        "status": "approved",
        "phase": phase,
        "candidate_id": candidate_id,
        "attempt_id": attempt["attempt_id"],
        "transition": str(receipt_path),
        "transition_index": transition_index,
        "transition_digest": receipt["transition_digest"],
        "raw_evidence_scanned_bytes": 0,
    }


def _directory_tree_digest(root: Path) -> str:
    if not root.is_dir() or root.is_symlink():
        raise ConfigurationError(f"候选源码目录不存在或不可信：{root}")
    entries: list[dict[str, Any]] = []
    for path in sorted(root.rglob("*")):
        if not path.is_file() or path.is_symlink():
            continue
        relative = path.relative_to(root)
        if any(part in SKIP_DIRECTORIES for part in relative.parts):
            continue
        entries.append(
            {
                "path": relative.as_posix(),
                "size": path.stat().st_size,
                "sha256": file_sha256(path),
            }
        )
    return _fingerprint({"entries": entries})


def _file_sha256_bounded(
    path: Path,
    *,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
    operation: str = "file-hash",
) -> str:
    """分块计算大文件摘要，并在每个块边界检查 attempt deadline。"""

    if path.is_symlink() or not path.is_file():
        raise ConfigurationError(f"摘要文件不存在或不可信：{path}")
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while True:
            if deadline is not None:
                deadline.check(operation)
            chunk = stream.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
            if heartbeat is not None:
                heartbeat(operation)
    if deadline is not None:
        deadline.check(operation)
    return digest.hexdigest()


def _container_image_id(
    container: str,
    *,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
) -> str | None:
    try:
        command = ["docker", "inspect", "--format", "{{.Image}}", container]
        result = _run_external_command(
            command,
            timeout_seconds=30,
            deadline=deadline,
            operation=f"docker:inspect:{container}",
            check=True,
            capture_output=True,
            text=True,
            heartbeat=heartbeat,
        )
    except incremental_recovery.WallClockTimeoutError:
        raise
    except (OSError, subprocess.SubprocessError):
        return None
    value = result.stdout.strip()
    return value if value.startswith("sha256:") else None


def _image_repo_digests(
    image_id: str,
    *,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
) -> set[str]:
    """读取 Docker config image ID 对应的 OCI 仓库摘要集合。"""

    try:
        command = [
            "docker",
            "image",
            "inspect",
            "--format",
            "{{json .RepoDigests}}",
            image_id,
        ]
        result = _run_external_command(
            command,
            timeout_seconds=30,
            deadline=deadline,
            operation=f"docker:image-inspect:{image_id}",
            check=True,
            capture_output=True,
            text=True,
            heartbeat=heartbeat,
        )
        payload = json.loads(result.stdout)
    except incremental_recovery.WallClockTimeoutError:
        raise
    except (OSError, subprocess.SubprocessError, json.JSONDecodeError) as error:
        raise ConfigurationError("无法读取候选镜像 RepoDigests。") from error
    if (
        not isinstance(payload, list)
        or not payload
        or any(
            not isinstance(value, str)
            or not IMMUTABLE_IMAGE_RE.fullmatch(value)
            for value in payload
        )
    ):
        raise ConfigurationError("候选镜像缺少合法、不可变的 RepoDigests。")
    return set(payload)


def _verify_container_image_reference(
    container: str,
    image_reference: str,
    expected_image_id: str | None = None,
    *,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
) -> str:
    """分别验证运行容器 config image ID 与其 OCI 仓库摘要。"""

    actual_image_id = _container_image_id(
        container,
        deadline=deadline,
        heartbeat=heartbeat,
    )
    if not actual_image_id or not IMAGE_ID_RE.fullmatch(actual_image_id):
        raise ConfigurationError("无法读取运行容器的实际 image ID。")
    if expected_image_id is not None and actual_image_id != expected_image_id:
        raise ConfigurationError("运行容器实际 image ID 与冻结身份不一致。")
    if image_reference not in _image_repo_digests(
        actual_image_id,
        deadline=deadline,
        heartbeat=heartbeat,
    ):
        raise ConfigurationError(
            "--runtime-image 不是运行镜像实际 RepoDigests 中的不可变引用。"
        )
    return actual_image_id


def _validate_codex_identity(
    *,
    path: str,
    sha256: str,
    version_output: str,
    expected_sha256: str,
    expected_version: str,
    label: str,
) -> dict[str, str]:
    match = re.fullmatch(r"codex-cli (?P<version>[0-9]+\.[0-9]+\.[0-9]+)", version_output)
    if sha256 != expected_sha256 or not match or match.group("version") != expected_version:
        raise ConfigurationError(f"{label} Codex 二进制版本或 SHA-256 不一致。")
    return {
        "label": label,
        "path": path,
        "version": match.group("version"),
        "version_output": version_output,
        "sha256": sha256,
    }


def _is_world_traversable_executable(path: Path) -> bool:
    """确认宿主执行副本及全部父目录可被无特权 bubblewrap 子进程读取。"""

    if path.is_symlink() or not path.is_file():
        return False
    mode = stat.S_IMODE(path.stat().st_mode)
    if mode & (stat.S_IROTH | stat.S_IXOTH) != (stat.S_IROTH | stat.S_IXOTH):
        return False
    return all(
        not parent.is_symlink()
        and parent.is_dir()
        and stat.S_IMODE(parent.stat().st_mode) & stat.S_IXOTH
        for parent in path.parents
    )


def _verify_official_binaries(
    manifest: dict[str, Any],
    *,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
) -> dict[str, Any]:
    """在任何真实官方请求前验证所有可能执行的 Codex 二进制。"""

    configuration = manifest["configuration"]
    expected_sha256 = manifest["target_sha256"]
    expected_version = manifest["target_version"]
    container = configuration["capture_container"]
    runtime_image_reference = str(manifest["official_identity"]["runtime_image"])
    runtime_image_id = _verify_container_image_reference(
        container,
        runtime_image_reference,
        deadline=deadline,
        heartbeat=heartbeat,
    )
    container_probe = (
        "import hashlib,json,pathlib,stat,subprocess,sys;"
        "p=pathlib.Path(sys.argv[1]);"
        "m=stat.S_IMODE(p.stat().st_mode);"
        "parents=list(p.parents);"
        "h=hashlib.sha256(p.read_bytes()).hexdigest();"
        "r=subprocess.run([str(p),'--version'],capture_output=True,text=True,timeout=30);"
        "print(json.dumps({'sha256':h,'version':(r.stdout or r.stderr).strip(),"
        "'return_code':r.returncode,'world_readable_executable':"
        "(m & (stat.S_IROTH|stat.S_IXOTH)) == (stat.S_IROTH|stat.S_IXOTH),"
        "'parents_world_traversable':all((not x.is_symlink()) and x.is_dir() and "
        "(stat.S_IMODE(x.stat().st_mode) & stat.S_IXOTH) for x in parents)}))"
    )
    identities: list[dict[str, str]] = []
    for name in ("capture_codex_bin", "relay_codex_bin"):
        binary = str(configuration[name])
        try:
            command = [
                "docker",
                "exec",
                container,
                "python3",
                "-c",
                container_probe,
                binary,
            ]
            result = _run_external_command(
                command,
                timeout_seconds=60,
                deadline=deadline,
                operation=f"official-binary:{name}",
                check=True,
                capture_output=True,
                text=True,
                heartbeat=heartbeat,
            )
            payload = json.loads(result.stdout)
        except incremental_recovery.WallClockTimeoutError:
            raise
        except (OSError, subprocess.SubprocessError, json.JSONDecodeError) as error:
            raise ConfigurationError(f"无法验证容器内 {name}：{error}") from error
        if (
            not isinstance(payload, dict)
            or payload.get("return_code") != 0
            or payload.get("world_readable_executable") is not True
            or payload.get("parents_world_traversable") is not True
        ):
            raise ConfigurationError(
                f"容器内 {name} 无法由无特权 bubblewrap 子进程安全执行。"
            )
        identities.append(
            _validate_codex_identity(
                path=binary,
                sha256=str(payload.get("sha256", "")),
                version_output=str(payload.get("version", "")),
                expected_sha256=expected_sha256,
                expected_version=expected_version,
                label=f"container:{name}",
            )
        )

    host_relay = Path(configuration["relay_codex_bin"])
    if (
        not _is_world_traversable_executable(host_relay)
        or not os.access(host_relay, os.X_OK)
    ):
        raise ConfigurationError(
            "宿主机 relay_codex_bin 不存在、不可信，或无法由无特权 bubblewrap 子进程执行。"
        )
    try:
        command = [str(host_relay), "--version"]
        host_version = _run_external_command(
            command,
            timeout_seconds=30,
            deadline=deadline,
            operation="official-binary:host-relay",
            check=True,
            capture_output=True,
            text=True,
            heartbeat=heartbeat,
        )
    except incremental_recovery.WallClockTimeoutError:
        raise
    except (OSError, subprocess.SubprocessError) as error:
        raise ConfigurationError(f"无法验证宿主机 relay_codex_bin：{error}") from error
    identities.append(
        _validate_codex_identity(
            path=str(host_relay),
            sha256=file_sha256(host_relay),
            version_output=(host_version.stdout or host_version.stderr).strip(),
            expected_sha256=expected_sha256,
            expected_version=expected_version,
            label="host:relay_codex_bin",
        )
    )
    package_identity = manifest["official_identity"].get("package")
    if not isinstance(package_identity, dict):
        raise ConfigurationError("官方目标身份缺少 package 闭包。")
    expected_helper_sha256 = str(
        package_identity.get("code_mode_host_sha256", "")
    )
    helper_probe = (
        "import hashlib,json,os,pathlib,stat,sys;"
        "p=pathlib.Path(sys.argv[1]);"
        "m=stat.S_IMODE(p.stat().st_mode) if p.is_file() else 0;"
        "parents=list(p.parents);"
        "print(json.dumps({'is_file':p.is_file(),'is_symlink':p.is_symlink(),"
        "'executable':os.access(p,os.X_OK),'sha256':"
        "hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() else '',"
        "'world_readable_executable':"
        "(m & (stat.S_IROTH|stat.S_IXOTH)) == (stat.S_IROTH|stat.S_IXOTH),"
        "'parents_world_traversable':all((not x.is_symlink()) and x.is_dir() and "
        "(stat.S_IMODE(x.stat().st_mode) & stat.S_IXOTH) for x in parents)}))"
    )
    helpers: list[dict[str, str]] = []
    for name in ("capture_code_mode_host_bin", "relay_code_mode_host_bin"):
        helper = str(configuration[name])
        try:
            command = [
                "docker",
                "exec",
                container,
                "python3",
                "-c",
                helper_probe,
                helper,
            ]
            result = _run_external_command(
                command,
                timeout_seconds=60,
                deadline=deadline,
                operation=f"official-helper:{name}",
                check=True,
                capture_output=True,
                text=True,
                heartbeat=heartbeat,
            )
            payload = json.loads(result.stdout)
        except incremental_recovery.WallClockTimeoutError:
            raise
        except (OSError, subprocess.SubprocessError, json.JSONDecodeError) as error:
            raise ConfigurationError(f"无法验证容器内 {name}：{error}") from error
        if (
            not isinstance(payload, dict)
            or payload.get("is_file") is not True
            or payload.get("is_symlink") is not False
            or payload.get("executable") is not True
            or payload.get("world_readable_executable") is not True
            or payload.get("parents_world_traversable") is not True
            or payload.get("sha256") != expected_helper_sha256
        ):
            raise ConfigurationError(f"容器内 {name} 与官方 package 不一致。")
        helpers.append(
            {
                "label": f"container:{name}",
                "path": helper,
                "sha256": expected_helper_sha256,
            }
        )

    host_helper = Path(configuration["relay_code_mode_host_bin"])
    if (
        not _is_world_traversable_executable(host_helper)
        or not os.access(host_helper, os.X_OK)
        or file_sha256(host_helper) != expected_helper_sha256
    ):
        raise ConfigurationError(
            "宿主机 relay_code_mode_host_bin 与官方 package 不一致。"
        )
    helpers.append(
        {
            "label": "host:relay_code_mode_host_bin",
            "path": str(host_helper),
            "sha256": expected_helper_sha256,
        }
    )
    return {
        "passed": True,
        "expected_version": expected_version,
        "expected_sha256": expected_sha256,
        "runtime_image_reference": runtime_image_reference,
        "runtime_image_id": runtime_image_id,
        "identities": identities,
        "package": package_identity,
        "helpers": helpers,
    }


def _evidence_files(roots: Iterable[Path]) -> list[tuple[str, Path]]:
    root_map = _evidence_root_map(roots)
    output: dict[Path, str] = {}
    for root, prefix in root_map:
        if not root.exists() or root.is_symlink():
            continue
        files = [root] if root.is_file() else sorted(root.rglob("*"))
        for path in files:
            if not path.is_file() or path.is_symlink():
                continue
            relative = path.name if root.is_file() else path.relative_to(root).as_posix()
            output[path.resolve()] = f"{prefix}/{relative}"
    return [(output[path], path) for path in sorted(output)]


def _evidence_root_map(roots: Iterable[Path]) -> list[tuple[Path, str]]:
    """为多个证据根生成稳定且无冲突的逻辑前缀。"""

    resolved = sorted({path.resolve(strict=False) for path in roots})
    counts: dict[str, int] = {}
    for root in resolved:
        counts[root.name] = counts.get(root.name, 0) + 1
    return [
        (
            root,
            root.name if counts[root.name] == 1 else f"{index:03d}-{root.name}",
        )
        for index, root in enumerate(resolved, 1)
    ]


def _evidence_file_binding(
    path: Path,
    roots: Iterable[Path],
    *,
    label: str,
) -> tuple[dict[str, str], Path, str]:
    """把非符号链接证据文件绑定到唯一证据根和逻辑清单路径。"""

    if not path.is_absolute() or path.is_symlink() or not path.is_file():
        raise ConfigurationError(f"{label}必须是证据根内的非符号链接普通文件。")
    resolved = path.resolve(strict=True)
    matches: list[tuple[Path, str, Path]] = []
    for root, prefix in _evidence_root_map(roots):
        if not root.is_dir() or root.is_symlink():
            continue
        try:
            relative = resolved.relative_to(root.resolve(strict=True))
        except ValueError:
            continue
        matches.append((root.resolve(strict=True), prefix, relative))
    if len(matches) != 1:
        raise ConfigurationError(f"{label}必须唯一归属于一个已收集证据根。")
    root, prefix, relative = matches[0]
    logical = f"{prefix}/{relative.as_posix()}"
    return {"path": logical, "sha256": file_sha256(resolved)}, root, prefix


def _evidence_inventory(roots: Iterable[Path]) -> dict[str, Any]:
    entries = [
        {
            "path": relative,
            "size": path.stat().st_size,
            "sha256": file_sha256(path),
        }
        for relative, path in _evidence_files(roots)
    ]
    return {
        "entry_count": len(entries),
        "entries": entries,
        "digest": _fingerprint({"entries": entries}),
    }


def _evidence_security(roots: Iterable[Path]) -> dict[str, Any]:
    secret_names = [
        name
        for name in (
            "ADMIN_BEARER_TOKEN",
            "OPENAI_API_KEY",
            "ANTHROPIC_API_KEY",
            "SUB2API_API_KEY",
        )
        if os.environ.get(name)
    ]
    report = scan_files_for_secrets(
        _evidence_files(roots), secret_env_names=secret_names
    )
    return {
        "known_secret_scan_passed": bool(report["passed"]),
        "known_secret_env_names": report["known_secret_env_names"],
        "file_count": report["file_count"],
        "scanned_bytes": report["scanned_bytes"],
        "findings": report["findings"],
        "limitation": (
            None
            if secret_names
            else "未读取容器内 OAuth 凭据值；仍执行令牌形态启发式扫描。"
        ),
    }


def _evidence_permissions_private(roots: Iterable[Path]) -> bool:
    """确认原始证据根、目录和文件均未向 group/other 开放。"""

    for root in {path.resolve(strict=False) for path in roots}:
        if not root.exists() or root.is_symlink():
            return False
        paths = [root] if root.is_file() else [root, *root.rglob("*")]
        for path in paths:
            if path.is_symlink() or path.stat().st_mode & 0o077:
                return False
    return True


def _resolve_receipt(
    explicit: Path | None,
    roots: list[Path],
    filename: str,
    *,
    label: str,
) -> Path:
    if explicit is not None:
        return explicit
    matches = sorted(
        path
        for root in roots
        if root.is_dir() and not root.is_symlink()
        for path in root.rglob(filename)
        if path.is_file() and not path.is_symlink()
    )
    if len(matches) != 1:
        raise ConfigurationError(f"{label}必须显式提供或在证据根内唯一发现。")
    return matches[0]


def _capture_assertion_context(
    manifest_path: Path | None,
    requested_root: Path | None,
    evidence_roots: list[Path],
    *,
    target_version: str,
) -> dict[str, Any]:
    """定位断言证据包并返回单根断言上下文。

    主手册 §4.4.3 规定：断言器只读取一个证据根，即 attempt 内的
    `assertion-bundle/`；它由 ACC-02 从各 job 根只读收口而来，自包含 manifest、
    原件与派生观测。因此这里返回的 `evidence_root` 是 bundle 目录本身，而
    `evidence_prefix` 是 bundle 在封存 inventory 中的逻辑前缀（`<所属根>/
    assertion-bundle`）——这是此前路径空间失配的修复点：
    机器 check 的相对路径加上该前缀后，必须逐字命中 inventory 条目。
    """

    path = _resolve_receipt(
        manifest_path,
        evidence_roots,
        "capture-manifest.json",
        label="统一 capture manifest",
    )
    binding, owning_root, owning_prefix = _evidence_file_binding(
        path, evidence_roots, label="统一 capture manifest"
    )
    bundle_dir = path.parent.resolve(strict=True)
    if bundle_dir.name != ASSERTION_BUNDLE_DIR_NAME:
        raise ConfigurationError(
            "统一 capture manifest 必须位于 attempt 的 "
            f"{ASSERTION_BUNDLE_DIR_NAME}/ 断言证据包内。"
        )
    if bundle_dir == owning_root:
        raise ConfigurationError(
            f"{ASSERTION_BUNDLE_DIR_NAME}/ 必须是已收集证据根内的子目录，"
            "不能自成独立证据根。"
        )
    relative_bundle = bundle_dir.relative_to(owning_root).as_posix()
    prefix = f"{owning_prefix}/{relative_bundle}"
    if requested_root is not None and requested_root.resolve(strict=True) != bundle_dir:
        raise ConfigurationError(
            "--assertion-evidence-root 与断言证据包目录不一致。"
        )
    try:
        load_assertion_observations(path, bundle_dir, target_version)
    except (OSError, ValueError) as error:
        raise ConfigurationError(f"统一 capture manifest 验证失败：{error}") from error
    return {
        "capture_manifest": binding,
        "capture_manifest_path": str(path.resolve(strict=True)),
        "evidence_root": str(bundle_dir),
        "evidence_prefix": prefix,
    }


def _run_seal_assertion_gate(
    assertion_context: dict[str, Any],
    roots: list[Path],
    *,
    phase: str,
    target_version: str,
) -> dict[str, Any]:
    """ACC-03：seal 前按分侧验收契约执行断言门禁，任一失败拒绝封存。"""

    bundle_dir = Path(assertion_context["evidence_root"])
    # provenance 里的 source_root 名即封存 inventory 的逻辑前缀，重放时按同一
    # 映射回到真实目录；bundle 是某个根内的子目录，不单独充当来源根。
    source_roots = {prefix: root for root, prefix in _evidence_root_map(roots)}
    try:
        profile = load_acceptance_profile(acceptance_profile_path())
        contract = verify_frozen_contract(profile)
        return run_assertion_gate(
            bundle_dir=bundle_dir,
            source_roots=source_roots,
            side="official" if phase == "official" else "candidate",
            profile=profile,
            contract=contract,
            target_version=target_version,
        )
    except (AcceptanceContractError, AssertionGateError) as error:
        raise ConfigurationError(
            f"{phase} seal 断言门禁失败：{error}"
        ) from error


def _validate_restoration_report(
    report_path: Path | None,
    evidence_roots: list[Path],
    *,
    phase: str,
    candidate_id: str | None,
) -> dict[str, Any]:
    path = _resolve_receipt(
        report_path,
        evidence_roots,
        "restoration-report.json",
        label="环境恢复报告",
    )
    binding, root, _ = _evidence_file_binding(
        path, evidence_roots, label="环境恢复报告"
    )
    try:
        report = replay_receipt(path, root, expected_subcommand="restoration")
    except (ReceiptFinalizerError, OSError, ValueError) as error:
        raise ConfigurationError(f"环境恢复报告无法由机器 finalizer 重放：{error}") from error
    if (
        report.get("schema_version") != RESTORATION_SCHEMA
        or report.get("phase") != phase
        or report.get("candidate_id") != candidate_id
        or report.get("status") != "restored"
    ):
        raise ConfigurationError("环境恢复报告身份或状态不一致。")
    checks = report.get("checks")
    required_checks = {
        "service_state_restored",
        "container_state_restored",
        "database_state_preserved",
        "account_state_preserved",
        "configuration_state_restored",
    }
    if not isinstance(checks, list):
        raise ConfigurationError("环境恢复报告 checks 必须是数组。")
    seen: set[str] = set()
    for check in checks:
        if not isinstance(check, dict):
            raise ConfigurationError("环境恢复检查结构非法。")
        check_id = check.get("id")
        if (
            not isinstance(check_id, str)
            or check_id in seen
            or check.get("passed") is not True
        ):
            raise ConfigurationError("环境恢复检查缺失、重复或未通过。")
        seen.add(check_id)
    if seen != required_checks:
        raise ConfigurationError(
            "环境恢复报告检查集合不闭合："
            f"缺少={sorted(required_checks - seen)}，多余={sorted(seen - required_checks)}"
        )
    return {"passed": True, "report": binding, "checks": checks}


def _validate_observed_profile_receipt(
    receipt_path: Path | None,
    evidence_roots: list[Path],
    *,
    campaign_id: str,
    attempt_id: str,
    run_nonce: str,
    attempt_started_at_utc: str,
    client_checkpoint_at_utc: str,
    candidate_id: str,
    target_version: str,
    expected_profile_id: str,
    expected_profile_digest: str,
    image_id: str,
    image_reference: str,
    source_tree_sha256: str,
    build_id: str,
    deployed_version: str,
) -> tuple[dict[str, str], dict[str, Any]]:
    path = _resolve_receipt(
        receipt_path,
        evidence_roots,
        "observed-profile.json",
        label="运行画像观测收据",
    )
    binding, root, _ = _evidence_file_binding(
        path, evidence_roots, label="运行画像观测收据"
    )
    try:
        receipt = replay_receipt(
            path, root, expected_subcommand="observed-profile"
        )
    except (ReceiptFinalizerError, OSError, ValueError) as error:
        raise ConfigurationError(
            f"运行画像观测收据无法由机器 finalizer 重放：{error}"
        ) from error
    expected = {
        "schema_version": OBSERVED_PROFILE_SCHEMA,
        "status": "active",
        "campaign_id": campaign_id,
        "attempt_id": attempt_id,
        "run_nonce": run_nonce,
        "attempt_started_at_utc": attempt_started_at_utc,
        "client_checkpoint_at_utc": client_checkpoint_at_utc,
        "candidate_id": candidate_id,
        "target_version": target_version,
        "profile_id": expected_profile_id,
        "profile_digest": expected_profile_digest,
        "image_id": image_id,
        "image_reference": image_reference,
        "source_tree_sha256": source_tree_sha256,
        "build_id": build_id,
        "deployed_version": deployed_version,
        "source": "sub2api-runtime",
    }
    for field, value in expected.items():
        if receipt.get(field) != value:
            raise ConfigurationError(f"运行画像观测收据 {field} 不一致。")
    return binding, receipt


def _third_party_client_model(configuration: Mapping[str, Any]) -> str:
    """返回第三方客户端验证使用的冻结模型。

    Kilo 双入口用于验证兼容客户端经 HTTP／Responses 进入同一候选画像，模型坐标
    应与 Campaign 的 Lite 轨一致；主轨 ``model`` 属于官方／候选场景任务，不能
    再被隐式复用于第三方客户端。历史 Campaign 尚无 ``lite_model`` 时才回退主轨，
    以便只读重放既有制品。
    """

    model = configuration.get("lite_model") or configuration.get("model")
    if not isinstance(model, str) or not model.strip():
        raise ConfigurationError("Campaign 缺少第三方客户端冻结模型。")
    return model


def _parse_client_evidence(
    values: Iterable[str],
    evidence_roots: list[Path],
    *,
    campaign_id: str,
    attempt_id: str,
    run_nonce: str,
    attempt_started_at_utc: str,
    client_checkpoint_at_utc: str,
    candidate_id: str,
    target_version: str,
    model: str,
    identity: dict[str, Any],
) -> list[dict[str, Any]]:
    bindings: list[dict[str, Any]] = []
    seen: set[str] = set()
    for value in values:
        client_id, separator, raw_path = value.partition("=")
        if (
            not separator
            or not SAFE_ID_RE.fullmatch(client_id)
            or client_id in seen
        ):
            raise ConfigurationError(f"--client-evidence 格式非法或重复：{value}")
        path = Path(raw_path)
        binding, root, _ = _evidence_file_binding(
            path, evidence_roots, label=f"第三方入口 {client_id} 收据"
        )
        try:
            receipt = replay_receipt(
                path, root, expected_subcommand="kilo-binding"
            )
        except (ReceiptFinalizerError, OSError, ValueError) as error:
            raise ConfigurationError(
                f"第三方入口 {client_id} 收据无法由机器 finalizer 重放：{error}"
            ) from error
        expected_protocols = {
            "kilo-compatible": "openai-compatible",
            "kilo-responses": "openai-responses",
        }
        expected_entrypoints = {
            "kilo-compatible": "/v1/chat/completions",
            "kilo-responses": "/v1/responses",
        }
        expected = {
            "schema_version": CLIENT_BINDING_SCHEMA,
            "status": "success",
            "campaign_id": campaign_id,
            "attempt_id": attempt_id,
            "run_nonce": run_nonce,
            "attempt_started_at_utc": attempt_started_at_utc,
            "client_checkpoint_at_utc": client_checkpoint_at_utc,
            "client_id": client_id,
            "protocol": expected_protocols.get(client_id),
            "entrypoint": expected_entrypoints.get(client_id),
            "model": model,
            "candidate_id": candidate_id,
            "target_version": target_version,
            "profile_id": identity.get("profile_id"),
            "profile_digest": identity.get("profile_digest"),
            "candidate_image_id": identity.get("image_id"),
            "source_tree_sha256": identity.get("source_tree_sha256"),
            "build_id": identity.get("build_id"),
            "deployed_version": identity.get("deployed_version"),
        }
        if expected["protocol"] is None:
            raise ConfigurationError(f"第三方入口 {client_id} 未声明协议契约。")
        for field, expected_value in expected.items():
            if receipt.get(field) != expected_value:
                raise ConfigurationError(f"第三方入口 {client_id} 的 {field} 不一致。")
        if not isinstance(receipt.get("client_version"), str) or not receipt["client_version"].strip():
            raise ConfigurationError(f"第三方入口 {client_id} 缺少客户端版本。")
        seen.add(client_id)
        bindings.append(
            {
                "client_id": client_id,
                "status": "success",
                "campaign_id": receipt["campaign_id"],
                "attempt_id": receipt["attempt_id"],
                "run_nonce": receipt["run_nonce"],
                "attempt_started_at_utc": receipt["attempt_started_at_utc"],
                "client_checkpoint_at_utc": receipt[
                    "client_checkpoint_at_utc"
                ],
                "client_version": receipt["client_version"],
                "protocol": receipt["protocol"],
                "entrypoint": receipt["entrypoint"],
                "model": receipt["model"],
                "profile_id": receipt["profile_id"],
                "profile_digest": receipt["profile_digest"],
                "receipt": binding,
                "source_tree_sha256": receipt["source_tree_sha256"],
                "build_id": receipt["build_id"],
                "deployed_version": receipt["deployed_version"],
                "request_evidence": receipt["request_evidence"],
                "response_evidence": receipt["response_evidence"],
                "request_proof": receipt["request_proof"],
                "response_proof": receipt["response_proof"],
                "raw_evidence": receipt["raw_evidence"],
            }
        )
    return bindings


def _load_capture_reservation(
    campaign_dir: Path,
    attempt_root: Path,
    *,
    phase: str,
    candidate_id: str | None,
    _manifest: Mapping[str, Any] | None = None,
    _historical_manifest_controls: bool = False,
) -> dict[str, Any]:
    """读取 attempt 原子发布前即存在的不可变预约收据。"""

    path = attempt_root / "reservation.json"
    _reject_symlink_components(path, campaign_dir, "抓包预约收据")
    if not path.is_file() or path.is_symlink():
        raise ConfigurationError(f"抓包 attempt 缺少原子预约收据：{attempt_root.name}")
    payload = _read_json(path, "抓包预约收据")
    required = {
        "schema_version",
        "campaign_id",
        "campaign_mode",
        "campaign_purpose",
        "campaign_manifest_sha256",
        "phase",
        "candidate_id",
        "candidate_purpose",
        "attempt_id",
        "run_nonce",
        "started_at_utc",
        "identity_sha256",
        "planned_jobs",
        "reservation_digest",
    }
    digest = payload.get("reservation_digest")
    unsigned = dict(payload)
    unsigned.pop("reservation_digest", None)
    manifest = (
        dict(_manifest)
        if isinstance(_manifest, Mapping)
        else load_campaign_manifest(
            campaign_dir,
            _control_epoch_bootstrap=_historical_manifest_controls,
        )
    )
    if (
        not set(payload).issubset(required | {"campaign_lease"})
        or not required.issubset(set(payload))
        or payload.get("schema_version") != CAPTURE_RESERVATION_SCHEMA
        or payload.get("campaign_id") != manifest["campaign_id"]
        or payload.get("campaign_mode") != manifest["campaign_mode"]
        or payload.get("campaign_purpose") != manifest["campaign_purpose"]
        or payload.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or payload.get("phase") != phase
        or payload.get("candidate_id")
        != (candidate_id if phase == "candidate" else None)
        or payload.get("candidate_purpose")
        != (manifest["campaign_purpose"] if phase == "candidate" else None)
        or payload.get("attempt_id") != attempt_root.name
        or not RUN_NONCE_RE.fullmatch(str(payload.get("run_nonce", "")))
        or not _is_rfc3339_timestamp(payload.get("started_at_utc"))
        or not SHA256_RE.fullmatch(str(payload.get("identity_sha256", "")))
        or not SHA256_RE.fullmatch(str(digest))
        or _fingerprint(unsigned) != digest
    ):
        raise ConfigurationError("抓包预约身份或摘要不一致。")
    lease_binding = payload.get("campaign_lease")
    if lease_binding is not None:
        if (
            not isinstance(lease_binding, Mapping)
            or set(lease_binding) != {"path", "owner_nonce", "deadline_at_utc"}
            or lease_binding.get("path") != CAMPAIGN_LEASE_FILENAME
            or not SHA256_RE.fullmatch(str(lease_binding.get("owner_nonce", "")))
            or not _is_rfc3339_timestamp(lease_binding.get("deadline_at_utc"))
        ):
            raise ConfigurationError("抓包预约 Campaign lease 绑定非法。")
    planned_jobs = payload.get("planned_jobs")
    if not isinstance(planned_jobs, list) or not planned_jobs:
        raise ConfigurationError("抓包预约缺少计划任务。")
    seen: set[str] = set()
    for item in planned_jobs:
        if (
            not isinstance(item, dict)
            or set(item) != {"id", "required", "execution_sha256"}
            or not SAFE_ID_RE.fullmatch(str(item.get("id", "")))
            or item.get("id") in seen
            or not isinstance(item.get("required"), bool)
            or not SHA256_RE.fullmatch(str(item.get("execution_sha256", "")))
        ):
            raise ConfigurationError("抓包预约计划任务非法、重复或摘要缺失。")
        seen.add(str(item["id"]))
    return payload


def _tool_component_digest_map(
    identity: Mapping[str, Any] | None,
    *,
    canonical: bool = False,
) -> dict[str, str] | None:
    """提取工具组件摘要；可选地应用历史 watchdog 组件归类兼容。"""

    if not isinstance(identity, Mapping):
        return None
    try:
        bundle = _tool_component_bundle(identity)
        if canonical:
            bundle = _canonicalize_tool_component_bundle(bundle)
    except (ConfigurationError, incremental_recovery.IncrementalRecoveryError):
        return None
    components = bundle.get("components")
    if not isinstance(components, Mapping):
        return None
    output: dict[str, str] = {}
    for name, value in components.items():
        if not isinstance(name, str) or not isinstance(value, Mapping):
            return None
        digest = value.get("sha256")
        if not SHA256_RE.fullmatch(str(digest)):
            return None
        output[name] = str(digest)
    return output


def _historical_result_metadata_matches(
    result: Mapping[str, Any],
    job: Job,
    identity: Mapping[str, Any],
    frozen_tool: Mapping[str, Any] | None,
    execution_sha256: str,
    *,
    current_tool: Mapping[str, Any],
    allowed_high_risk_path_changes: Iterable[str] = (),
    validated_current_production_sha256: str | None = None,
) -> bool:
    """校验旧结果的增量元数据仍属于同一 Job／工具依赖闭集。

    评估器／编排器属于低风险组件：它们可以改变结果键，但不能改变已经
    生成的请求字节。历史结果因此先按冻结工具的原始或规范化组件摘要验真，
    再由调用方重绑到当前键；产出侧组件仍要求规范化摘要逐字相同。
    """

    if result.get("execution_sha256") != execution_sha256:
        return False
    metadata_fields = {
        "tool_components",
        "tool_component_digests",
        "input_sha256",
        "environment_sha256",
        "dependency_sha256",
        "incremental_result_key",
    }
    if not metadata_fields.issubset(result):
        return False
    names = sorted(_job_tool_components(job))
    recorded_names = result.get("tool_components")
    recorded_digests = result.get("tool_component_digests")
    if (
        recorded_names != names
        or not isinstance(recorded_digests, Mapping)
        or set(recorded_digests) != set(names)
    ):
        return False
    if not isinstance(current_tool, Mapping):
        return False
    allowed_high_risk_paths = {
        str(path) for path in allowed_high_risk_path_changes
    }
    if any(
        not path
        or path.startswith("/")
        or "\\" in path
        or any(part in {"", ".", ".."} for part in PurePosixPath(path).parts)
        for path in allowed_high_risk_paths
    ):
        return False
    allowed_high_risk = {
        _tool_component_for_path(path) for path in allowed_high_risk_paths
    }
    if not allowed_high_risk.issubset(
        {"producer", "relay", "runtime", "shared", "scenario"}
    ):
        return False
    historical_raw = _tool_component_digest_map(frozen_tool)
    historical_canonical = _tool_component_digest_map(frozen_tool, canonical=True)
    current_raw = _tool_component_digest_map(current_tool)
    current_canonical = _tool_component_digest_map(current_tool, canonical=True)
    if not all(
        isinstance(value, str) and SHA256_RE.fullmatch(value)
        for value in recorded_digests.values()
    ):
        return False
    for name in names:
        if not all(
            name in values
            for values in (
                historical_raw or {},
                historical_canonical or {},
                current_raw or {},
                current_canonical or {},
            )
        ):
            return False
        # 旧组件摘要可能因评估文件从 shared 移入 evaluator 而变化；只要
        # 收据中的值确实来自冻结身份，便可在当前 attempt 重绑。高风险组件
        # 仍必须逐字保持规范化摘要，防止把真实 producer 改动放行。
        if (
            name not in _LOW_RISK_TOOL_COMPONENTS
            and name not in allowed_high_risk
            and historical_canonical[name] != current_canonical[name]
        ):
            return False
        if str(recorded_digests[name]) not in {
            historical_raw[name],
            historical_canonical[name],
        }:
            return False
    # 全局产出摘要只作审计。调用方已经用逐文件反向依赖表证明这里排除的路径
    # 不影响当前 Job；未登记路径在进入本函数前停线，不能退化为全量重跑。
    try:
        excluded_production_paths = set(_PHASE_EVALUATION_HYBRID_FILES)
        excluded_production_paths.update(allowed_high_risk_paths)
        if validated_current_production_sha256 is not None:
            if (
                not SHA256_RE.fullmatch(validated_current_production_sha256)
                or _tool_identity_side_digest_excluding(
                    current_tool,
                    "production",
                    _PHASE_EVALUATION_HYBRID_FILES,
                )
                != validated_current_production_sha256
            ):
                return False
        elif _tool_identity_side_digest_excluding(
            frozen_tool or {},
            "production",
            excluded_production_paths,
        ) != _tool_identity_side_digest_excluding(
            current_tool,
            "production",
            excluded_production_paths,
        ):
            return False
    except (ConfigurationError, incremental_recovery.IncrementalRecoveryError):
        return False
    recorded_dependency_files = result.get("tool_dependency_files")
    if recorded_dependency_files is not None:
        if not isinstance(recorded_dependency_files, Mapping):
            return False
        try:
            frozen_files = _tool_entry_digest_map(frozen_tool or {})
            current_files = _tool_entry_digest_map(current_tool)
        except ConfigurationError:
            return False
        if any(
            frozen_files.get(str(path)) != digest
            or current_files.get(str(path)) != digest
            for path, digest in recorded_dependency_files.items()
        ):
            return False
        dependency_rows = [
            {
                "id": "tool-file:"
                + hashlib.sha256(str(path).encode("utf-8")).hexdigest()[:24],
                "status": "passed",
                "result_sha256": str(digest),
            }
            for path, digest in sorted(recorded_dependency_files.items())
        ]
    else:
        dependency_rows = [
            {
                "id": f"tool:{name}",
                "status": "passed",
                "result_sha256": str(recorded_digests[name]),
            }
            for name in names
        ]
    try:
        dependency_sha256 = incremental_recovery.dependency_digest(dependency_rows)
        environment_sha256 = _fingerprint(
            {
                "phase": job.phase,
                "track": getattr(job, "track", "main"),
                "model_id": getattr(job, "model_id", ""),
                "identity_sha256": _fingerprint(dict(identity)),
            }
        )
        result_key = incremental_recovery.result_key(
            component="job",
            item_id=job.job_id,
            input_sha256=execution_sha256,
            environment_sha256=environment_sha256,
            dependency_sha256=dependency_sha256,
        )
    except incremental_recovery.IncrementalRecoveryError:
        return False
    return (
        result.get("input_sha256") == execution_sha256
        and result.get("environment_sha256") == environment_sha256
        and result.get("dependency_sha256") == dependency_sha256
        and result.get("incremental_result_key") == result_key
    )


def _rebase_reused_result(
    result: Mapping[str, Any],
    job: Job,
    *,
    identity: Mapping[str, Any],
    tool_identity: Mapping[str, Any],
) -> dict[str, Any]:
    """把承接结果绑定到本轮 Job 摘要，历史收据本身保持只读。"""

    incremental = _job_incremental_metadata(
        job,
        identity=identity,
        tool_identity=tool_identity,
    )
    rebased = dict(result)
    rebased.update(
        {
            "execution_sha256": incremental["input_sha256"],
            "tool_components": incremental["components"],
            "tool_component_digests": incremental["component_digests"],
            "tool_dependency_files": incremental["tool_dependency_files"],
            "input_sha256": incremental["input_sha256"],
            "environment_sha256": incremental["environment_sha256"],
            "dependency_sha256": incremental["dependency_sha256"],
            "incremental_result_key": incremental["result_key"],
        }
    )
    return rebased


def _reserve_capture_attempt(
    campaign_dir: Path,
    *,
    phase: str,
    candidate_id: str | None,
    identity: dict[str, Any],
    jobs: list[Job],
    allow_failed_rerun: bool = False,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    lease: CampaignLease | None = None,
) -> tuple[Path, dict[str, Any]]:
    """在跨进程锁内原子发布预约，关闭 check-then-create 与空目录窗口。"""

    relative = _capture_attempt_relative(phase, candidate_id)
    if deadline is not None:
        deadline.check("attempt:reserve:start")
    if lease is not None:
        lease.check("attempt:reserve:start")
    with _campaign_lock(campaign_dir, deadline=deadline):
        _reject_contaminated_campaign(campaign_dir)
        canonical = "capture-official" if phase == "official" else "capture-candidate"
        _, result_path = _stage_path(campaign_dir, canonical, candidate_id)
        if result_path.exists() or result_path.is_symlink():
            raise ConfigurationError(f"{canonical} 已封存，禁止创建新 attempt。")
        active = _active_unsealed_attempts(campaign_dir, phase)
        if active:
            raise ConfigurationError(
                f"Campaign 存在未封存预约或 attempt，禁止并行 run：{active}"
            )
        failed = _failed_capture_attempts(campaign_dir, phase)
        if phase == "candidate":
            # candidate 身份变化必须新建 candidate，但旧 candidate 的失败事实仍须
            # 只读保留。失败门只阻止同一 candidate 绕过显式 resume；其他 candidate
            # 仍受全局并发预约门约束，却不能被无关失败永久锁死。
            failed = [
                item
                for item in failed
                if item.partition(":")[0] == candidate_id
            ]
        if failed and not allow_failed_rerun:
            raise ConfigurationError(
                "存在失败 attempt；只能显式使用 resume --rerun-failed，禁止直接 "
                f"capture-* run 绕过：{failed}"
            )

        attempts_root = ensure_private_directory(
            campaign_dir / relative / "attempts", campaign_dir
        )
        attempt_id = (
            time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
            + f"-{secrets.token_hex(8)}"
        )
        if lease is not None:
            # 先绑定计划中的 attempt-id，再发布 reservation；这样即使发布过程
            # 被中断，持久 lease 仍能指出当前命令正在创建哪个 attempt。
            lease.bind_attempt(attempt_id)
        final_root = attempts_root / attempt_id
        if final_root.exists() or final_root.is_symlink():
            raise ConfigurationError("随机 attempt-id 发生冲突。")
        run_nonce = secrets.token_hex(32)
        manifest = _require_formal_campaign(campaign_dir)
        if phase == "candidate" and identity.get("candidate_purpose") != manifest.get(
            "campaign_purpose"
        ):
            raise ConfigurationError(
                "候选预约身份用途与 Campaign 冻结用途不一致。"
            )
        reservation: dict[str, Any] = {
            "schema_version": CAPTURE_RESERVATION_SCHEMA,
            "campaign_id": manifest["campaign_id"],
            "campaign_mode": manifest["campaign_mode"],
            "campaign_purpose": manifest["campaign_purpose"],
            "campaign_manifest_sha256": file_sha256(
                campaign_dir / "campaign.json"
            ),
            "phase": phase,
            "candidate_id": candidate_id if phase == "candidate" else None,
            "candidate_purpose": (
                manifest["campaign_purpose"] if phase == "candidate" else None
            ),
            "attempt_id": attempt_id,
            "run_nonce": run_nonce,
            "started_at_utc": _utc_now(),
            "identity_sha256": _fingerprint(identity),
            "planned_jobs": [
                {
                    "id": job.job_id,
                    "required": job.required,
                    "execution_sha256": _job_execution_sha256(job),
                }
                for job in jobs
            ],
        }
        if lease is not None:
            if not lease.acquired:
                raise ConfigurationError("reservation 缺少 active Campaign lease。")
            lease_payload = lease.payload
            if lease_payload.get("campaign_id") != manifest.get("campaign_id"):
                raise ConfigurationError("reservation 与 Campaign lease 身份不一致。")
            reservation["campaign_lease"] = {
                "path": CAMPAIGN_LEASE_FILENAME,
                "owner_nonce": str(lease_payload["owner_nonce"]),
                "deadline_at_utc": str(lease_payload["deadline_at_utc"]),
            }
        reservation["reservation_digest"] = _fingerprint(reservation)

        temporary_root = Path(
            tempfile.mkdtemp(prefix=".reservation-", dir=attempts_root)
        )
        temporary_root.chmod(0o700)
        try:
            _secure_write_json_once(
                temporary_root / "reservation.json", reservation
            )
            os.rename(temporary_root, final_root)
            directory_descriptor = os.open(
                attempts_root,
                os.O_RDONLY
                | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_CLOEXEC", 0),
            )
            try:
                os.fsync(directory_descriptor)
            finally:
                os.close(directory_descriptor)
        except BaseException:
            if temporary_root.exists() and not temporary_root.is_symlink():
                (temporary_root / "reservation.json").unlink(missing_ok=True)
                try:
                    temporary_root.rmdir()
                except OSError:
                    pass
            raise
        if deadline is not None:
            deadline.check("attempt:reserve:complete")
        return final_root, reservation


def _prior_complete_results(
    campaign_dir: Path,
    relative: Path,
    jobs: list[Job],
    *,
    phase: str,
    candidate_id: str | None,
    identity: dict[str, Any],
    tool_identity: Mapping[str, Any] | None = None,
    affected_job_ids: Iterable[str] = (),
    expected_reuse_job_ids: Iterable[str] | None = None,
    source_attempt_id: str | None = None,
    source_campaign_dir: Path | None = None,
    source_candidate_id: str | None = None,
    source_receipt_binding: Mapping[str, Any] | None = None,
    allowed_high_risk_path_changes: Iterable[str] = (),
    validated_current_production_sha256: str | None = None,
    allowed_source_statuses: Iterable[str] = ("failed",),
    allow_unbound_cross_campaign_preview: bool = False,
    source_tool_identity: Mapping[str, Any] | None = None,
) -> list[dict[str, Any]]:
    """承接可复用结果，只返回未受影响且已经通过的 Job。

    旧收据没有组件键时仅在全局工具摘要完全相同的情况下承接；新收据按
    每个 Job 的组件依赖键判断。这样工具修复只会让失败项或真正受影响的
    Job 进入下一轮，已经通过且依赖未变的结果保持只读复用。
    """

    history_campaign_dir = (
        source_campaign_dir.resolve(strict=True)
        if source_campaign_dir is not None
        else campaign_dir.resolve(strict=True)
    )
    history_candidate_id = (
        source_candidate_id if source_campaign_dir is not None else candidate_id
    )
    history_relative = _capture_attempt_relative(phase, history_candidate_id)
    attempts_root = history_campaign_dir / history_relative / "attempts"
    if not attempts_root.is_dir() or attempts_root.is_symlink():
        raise ConfigurationError("--rerun-failed 找不到先前失败 attempt。")
    expected_jobs = {job.job_id: job for job in jobs}
    expected_reuse = (
        {str(item) for item in expected_reuse_job_ids}
        if expected_reuse_job_ids is not None
        else None
    )
    if expected_reuse is not None and not expected_reuse.issubset(expected_jobs):
        raise ConfigurationError("恢复闭集包含当前计划之外的已完成 Job。")
    if validated_current_production_sha256 is not None and (
        expected_reuse is None
        or not SHA256_RE.fullmatch(validated_current_production_sha256)
    ):
        raise ConfigurationError("恢复闭集的当前产出侧身份非法。")
    # 这些身份只读取一次：恢复规划必须基于同一份冻结 Campaign 和同一份
    # 当前工具摘要，不能在遍历多个历史 attempt 时出现坐标漂移。
    cross_campaign_source = history_campaign_dir != campaign_dir.resolve(strict=True)
    if allow_unbound_cross_campaign_preview and (
        not cross_campaign_source
        or source_attempt_id is None
        or expected_reuse is None
        or source_receipt_binding is not None
    ):
        raise ConfigurationError("无绑定跨 Campaign 复用只允许严格预览模式。")
    if (
        cross_campaign_source
        and source_receipt_binding is None
        and not allow_unbound_cross_campaign_preview
    ):
        raise ConfigurationError("跨 Campaign 复用缺少当前 Campaign 来源 transition。")
    trusted_source_transition = False
    if source_receipt_binding is not None:
        if (
            set(source_receipt_binding) != {"path", "sha256", "bytes"}
            or not isinstance(source_receipt_binding.get("path"), str)
            or Path(str(source_receipt_binding["path"])).is_absolute()
            or not SHA256_RE.fullmatch(str(source_receipt_binding.get("sha256", "")))
            or not isinstance(source_receipt_binding.get("bytes"), int)
            or isinstance(source_receipt_binding.get("bytes"), bool)
            or int(source_receipt_binding["bytes"]) <= 0
        ):
            raise ConfigurationError("跨 Campaign 复用来源绑定非法。")
        source_binding_path = _campaign_file(
            campaign_dir, str(source_receipt_binding["path"])
        )
        if (
            source_binding_path.is_symlink()
            or not source_binding_path.is_file()
            or file_sha256(source_binding_path) != source_receipt_binding["sha256"]
            or source_binding_path.stat().st_size != source_receipt_binding["bytes"]
        ):
            raise ConfigurationError("跨 Campaign 复用来源绑定漂移。")
        trusted_source_transition = True
    explicit_historical_source = (
        cross_campaign_source
        and source_attempt_id is not None
        and (allow_unbound_cross_campaign_preview or trusted_source_transition)
    )
    if source_tool_identity is not None and not explicit_historical_source:
        raise ConfigurationError(
            "来源 attempt 工具身份只允许用于严格跨 Campaign 预览或已绑定来源 transition。"
        )
    historical_source_controls = explicit_historical_source
    frozen_manifest = load_campaign_manifest(
        history_campaign_dir,
        _control_epoch_bootstrap=historical_source_controls,
    )
    current_manifest = load_campaign_manifest(campaign_dir)
    current_tool = tool_identity or _tool_identity(include_git=False)
    if not isinstance(current_tool, Mapping):
        raise ConfigurationError("当前工具身份不是对象，拒绝增量恢复。")
    frozen_tool = (
        source_tool_identity
        if source_tool_identity is not None
        else frozen_manifest.get("tool_identity")
    )
    frozen_tool_files_sha256 = (
        frozen_tool.get("files_sha256")
        if isinstance(frozen_tool, Mapping)
        else None
    )
    global_tool_unchanged = (
        current_tool.get("files_sha256") == frozen_tool_files_sha256
    )
    changed_production_paths: list[str] = []
    path_job_map: dict[str, set[str]] = {}
    if isinstance(frozen_tool, Mapping):
        (
            exact_affected_job_ids,
            changed_production_paths,
            unmapped_production_paths,
        ) = _exact_tool_path_impact(jobs, frozen_tool, current_tool)
        if unmapped_production_paths:
            raise ConfigurationError(
                "历史结果复用发现未登记的产出侧工具变化："
                + "、".join(unmapped_production_paths)
                + "；禁止扩大为全量重跑。"
            )
        path_job_map = _tool_path_job_map(jobs, frozen_tool, current_tool)
    else:
        exact_affected_job_ids = []
    allowed_statuses = {str(value) for value in allowed_source_statuses}
    if not allowed_statuses or not allowed_statuses.issubset(
        {"failed", "awaiting_receipts"}
    ):
        raise ConfigurationError("增量恢复源 attempt 状态白名单非法。")
    authorized_runtime_transition_ids: frozenset[str] | None = None
    for attempt, _ in _ordered_capture_attempts(
        history_campaign_dir,
        phase,
        history_candidate_id,
        _historical_manifest_controls=historical_source_controls,
    ):
        if source_attempt_id is not None and attempt.name != source_attempt_id:
            continue
        receipt = attempt / "attempt.json"
        if not receipt.is_file() or receipt.is_symlink():
            continue
        _, payload = _load_capture_attempt(
            history_campaign_dir,
            phase,
            history_candidate_id,
            attempt.name,
            _historical_manifest_controls=historical_source_controls,
        )
        if payload.get("status") not in allowed_statuses:
            continue
        if _fingerprint(payload.get("identity")) != _fingerprint(identity):
            raise ConfigurationError(
                "先前失败 attempt 身份与本次重跑不一致；不得在同一 Campaign 混用身份，"
                "请新建 Campaign。"
            )
        results = payload.get("results")
        if not isinstance(results, list):
            continue
        completed = []
        affected = set(str(item) for item in affected_job_ids)
        affected.update(exact_affected_job_ids)
        for item in results:
            if not isinstance(item, dict) or item.get("status") != "complete":
                continue
            job_id = item.get("id")
            if not isinstance(job_id, str) or job_id not in expected_jobs:
                raise ConfigurationError("先前失败 attempt 的已完成任务定义漂移。")
            expected_job = expected_jobs[job_id]
            expected_execution_sha256 = _job_execution_sha256(expected_job)
            recorded_execution_sha256 = item.get("execution_sha256")
            relocated = False
            if recorded_execution_sha256 != expected_execution_sha256:
                # 历史 attempt 可能是在另一棵受管工作树中执行的。只有当
                # 冻结 Job 的 hash 恰好等于“当前定义迁移回历史根”后的 hash
                # 时才允许承接；任何脚本、参数、环境或证据根变化都继续
                # 走原有的 fail-close 漂移错误。
                frozen_job = _frozen_job_definition(frozen_manifest, job_id)
                coordinate_matches = (
                    _successor_job_execution_matches(
                        expected_job,
                        recorded_execution_sha256,
                        frozen_job,
                        current_campaign_id=str(current_manifest["campaign_id"]),
                        predecessor_campaign_id=str(
                            frozen_manifest["campaign_id"]
                        ),
                        current_candidate_id=candidate_id,
                        predecessor_candidate_id=history_candidate_id,
                    )
                    if cross_campaign_source
                    else _relocated_job_execution_matches(
                        expected_job,
                        recorded_execution_sha256,
                        frozen_job,
                    )
                )
                if (
                    not coordinate_matches
                    and cross_campaign_source
                    and job_id in LEGACY_DEFAULT_CODEX_BIN_JOB_SCRIPTS
                ):
                    if authorized_runtime_transition_ids is None:
                        authorized_runtime_transition_ids = (
                            _bound_runtime_scenario_transition_job_ids(
                                history_campaign_dir,
                                frozen_manifest,
                            )
                        )
                    coordinate_matches = (
                        _legacy_default_codex_bin_execution_matches(
                            expected_job,
                            recorded_execution_sha256,
                            frozen_manifest,
                            item,
                            authorized_job_ids=(
                                authorized_runtime_transition_ids
                            ),
                            current_campaign_id=str(
                                current_manifest["campaign_id"]
                            ),
                            predecessor_campaign_id=str(
                                frozen_manifest["campaign_id"]
                            ),
                            current_candidate_id=candidate_id,
                            predecessor_candidate_id=history_candidate_id,
                        )
                    )
                if not coordinate_matches:
                    raise ConfigurationError("先前失败 attempt 的已完成任务定义漂移。")
                relocated = True
            # 组件身份存在时做精确的 Job 级命中；旧 attempt 只在工具树
            # 完全不变时兼容承接，避免把旧代码产出的结果误当成新代码结果。
            if expected_reuse is not None and job_id not in expected_reuse:
                # recovery_scope 是唯一事实源；其它“受影响”推导不能把闭集
                # 外的结果带入本轮。
                continue
            if expected_reuse is None and job_id in affected:
                continue
            expected_incremental = _job_incremental_metadata(
                expected_job, identity=identity, tool_identity=current_tool
            )
            unrelated_changed_paths = {
                path
                for path in changed_production_paths
                if job_id not in path_job_map.get(path, set())
            }
            permitted_rebase_paths = set(allowed_high_risk_path_changes)
            permitted_rebase_paths.update(unrelated_changed_paths)
            recorded_key = item.get("incremental_result_key")
            needs_rebase = False
            if recorded_key is None:
                if not global_tool_unchanged:
                    continue
            elif relocated or recorded_key != expected_incremental["result_key"]:
                # 路径迁移、组件重新归类或低风险评估修复都会改变当前键。
                # 先按冻结身份验证历史键，成功后只在新 attempt 中重绑当前
                # execution／component／result key，绝不回写历史收据。
                if not _historical_result_metadata_matches(
                    item,
                    expected_job,
                    identity,
                    frozen_tool if isinstance(frozen_tool, Mapping) else None,
                    str(recorded_execution_sha256),
                    current_tool=current_tool,
                    allowed_high_risk_path_changes=(
                        permitted_rebase_paths
                    ),
                    validated_current_production_sha256=(
                        validated_current_production_sha256
                    ),
                ):
                    continue
                needs_rebase = True
            else:
                # 当前键命中时仍保留轻量元数据校验；缺少旧字段的历史收据
                # 走兼容路径，由全局摘要相等性负责保护。
                if {
                    "tool_components",
                    "tool_component_digests",
                    "input_sha256",
                    "environment_sha256",
                    "dependency_sha256",
                }.issubset(item):
                    if not _historical_result_metadata_matches(
                        item,
                        expected_job,
                        identity,
                        frozen_tool if isinstance(frozen_tool, Mapping) else None,
                        str(recorded_execution_sha256),
                        current_tool=current_tool,
                        allowed_high_risk_path_changes=(
                            permitted_rebase_paths
                        ),
                        validated_current_production_sha256=(
                            validated_current_production_sha256
                        ),
                    ):
                        continue
            reused_item = (
                _rebase_reused_result(
                    item,
                    expected_job,
                    identity=identity,
                    tool_identity=current_tool,
                )
                if relocated or needs_rebase
                else dict(item)
            )
            completed.append(reused_item)
        if len({item["id"] for item in completed}) != len(completed):
            raise ConfigurationError("先前失败 attempt 含重复任务收据。")
        # 承接上一轮已完成的任务，只重跑失败项。这不是无条件复用：调用方必须在本轮
        # before 探针采完后调用 _verify_environment_continuity，证明「上一轮 after」到
        # 「本轮 before」之间环境没有漂移。窗口因此首尾相接，被承接的证据仍处在探针
        # 证明范围内；一旦环境变了，旧证据的前提就不成立，必须整轮重采。
        for item in completed:
            item["carried_from_attempt"] = attempt.name
            item["disposition"] = "reused"
            if source_receipt_binding is not None:
                item["source_receipt"] = dict(source_receipt_binding)
            elif not allow_unbound_cross_campaign_preview:
                item["source_receipt"] = {
                    "path": receipt.relative_to(campaign_dir).as_posix(),
                    "sha256": file_sha256(receipt),
                    "bytes": receipt.stat().st_size,
                }
        if expected_reuse is not None:
            actual_reuse = {str(item["id"]) for item in completed}
            if actual_reuse != expected_reuse:
                raise ConfigurationError(
                    "恢复 transition 的已完成 Job 无法安全复用："
                    f"expected={sorted(expected_reuse)}, actual={sorted(actual_reuse)}"
                )
        return completed
    raise ConfigurationError("--rerun-failed 找不到同身份失败 attempt。")


# 承接旧结果时要求逐字相同的探针种类。database 必然随采集增长（usage_logs 等水位表），
# 由 restoration 的 before_subset 规则单独覆盖，不在此处比较。
CONTINUITY_PROBE_KINDS = ("service", "containers", "account", "configuration")


def _probe_snapshot_digests(manifest: Mapping[str, Any]) -> dict[str, str]:
    digests: dict[str, str] = {}
    for snapshot in manifest.get("snapshots") or []:
        if not isinstance(snapshot, dict):
            continue
        kind = snapshot.get("kind")
        digest = snapshot.get("sha256")
        if isinstance(kind, str) and isinstance(digest, str):
            digests[kind] = digest
    return digests


def _verify_environment_continuity(
    campaign_dir: Path,
    relative: Path,
    carried_attempt_ids: set[str],
    before_manifest: Mapping[str, Any],
    *,
    source_campaign_dir: Path | None = None,
    source_relative: Path | None = None,
) -> dict[str, Any] | None:
    """证明被承接 attempt 的收尾环境与本轮起始环境一致。

    承接旧任务结果的前提是环境没有在两轮之间发生漂移——否则那些证据描述的是另一套
    环境。比较 service／containers／account／configuration 四类探针快照；database 会随
    采集自然增长，由 restoration 的 before_subset 规则单独覆盖。
    """

    if not carried_attempt_ids:
        return None
    if len(carried_attempt_ids) != 1:
        raise ConfigurationError("承接结果必须全部来自同一个先前 attempt。")
    source_attempt = next(iter(carried_attempt_ids))
    history_campaign_dir = (
        source_campaign_dir.resolve(strict=True)
        if source_campaign_dir is not None
        else campaign_dir.resolve(strict=True)
    )
    history_relative = source_relative if source_relative is not None else relative
    after_path = (
        history_campaign_dir
        / history_relative
        / "attempts"
        / source_attempt
        / "evidence"
        / "environment"
        / "after"
        / "probe-manifest.json"
    )
    if after_path.is_symlink() or not after_path.is_file():
        raise ConfigurationError("被承接 attempt 缺少 after 环境探针，无法证明连续性。")
    after_manifest = _read_json(after_path, "被承接 attempt 的 after 探针")
    previous = _probe_snapshot_digests(after_manifest)
    current = _probe_snapshot_digests(before_manifest)
    drifted = [
        kind
        for kind in CONTINUITY_PROBE_KINDS
        if previous.get(kind) != current.get(kind)
    ]
    if drifted:
        raise ConfigurationError(
            "承接失败：上一轮结束后环境已漂移（"
            + "、".join(drifted)
            + "），被承接任务的证据前提不再成立，请不带 --rerun-failed 整轮重采。"
        )
    return {
        "schema_version": "codex-upgrade-attempt-continuity/v1",
        "source_attempt_id": source_attempt,
        "compared_kinds": list(CONTINUITY_PROBE_KINDS),
        "source_after_probe_sha256": file_sha256(after_path),
    }


def _capture_attempt_relative(phase: str, candidate_id: str | None) -> Path:
    """返回抓包 attempt 的阶段相对目录。"""

    if phase == "official":
        return Path("official")
    if not candidate_id or not SAFE_ID_RE.fullmatch(candidate_id):
        raise ConfigurationError("候选 attempt 必须绑定合法 candidate-id。")
    return Path("candidates") / candidate_id


def _capture_attempt_path(
    campaign_dir: Path,
    phase: str,
    candidate_id: str | None,
    attempt_id: str,
) -> Path:
    """解析并约束一个既有抓包 attempt 路径。"""

    if not SAFE_ID_RE.fullmatch(attempt_id):
        raise ConfigurationError("--attempt-id 格式非法。")
    relative = _capture_attempt_relative(phase, candidate_id)
    path = campaign_dir / relative / "attempts" / attempt_id
    _reject_symlink_components(path, campaign_dir, "抓包 attempt")
    if not path.is_dir() or path.is_symlink():
        raise ConfigurationError(f"抓包 attempt 不存在或不可信：{attempt_id}")
    return path


def _validate_attempt_incremental_fields(
    payload: Mapping[str, Any],
    planned_job_ids: set[str],
) -> None:
    """校验 attempt 的增量计划和 Job 结果元数据。"""

    components = payload.get("tool_components")
    if components is not None:
        if not isinstance(components, Mapping):
            raise ConfigurationError("attempt 工具组件摘要必须是对象。")
        for name, value in components.items():
            if (
                not isinstance(name, str)
                or not isinstance(value, Mapping)
                or not isinstance(value.get("entries"), list)
                or not isinstance(value.get("entry_count"), int)
                or value.get("entry_count") != len(value["entries"])
                or not SHA256_RE.fullmatch(str(value.get("sha256", "")))
            ):
                raise ConfigurationError("attempt 工具组件摘要非法。")
    plan = payload.get("incremental_plan")
    if plan is not None:
        if not isinstance(plan, Mapping):
            raise ConfigurationError("attempt 增量计划必须是对象。")
        required = {
            "schema_version",
            "planned_job_ids",
            "changed_components",
            "affected_job_ids",
            "reused_job_ids",
            "executed_job_ids",
            "failed_job_ids",
            "pending_job_ids",
            "plan_sha256",
        }
        if set(plan) != required:
            raise ConfigurationError("attempt 增量计划字段不闭合。")
        arrays = [
            plan.get("changed_components"),
            plan.get("planned_job_ids"),
            plan.get("affected_job_ids"),
            plan.get("reused_job_ids"),
            plan.get("executed_job_ids"),
            plan.get("failed_job_ids"),
            plan.get("pending_job_ids"),
        ]
        if any(
            not isinstance(value, list)
            or not all(isinstance(item, str) and item for item in value)
            or value != sorted(set(value))
            for value in arrays
        ):
            raise ConfigurationError("attempt 增量计划列表非法。")
        if (
            plan.get("schema_version") != incremental_recovery.SCHEMA_VERSION
            or set(plan["planned_job_ids"]) != planned_job_ids
            or not set(plan["affected_job_ids"]).issubset(planned_job_ids)
            or not set(plan["reused_job_ids"]).issubset(planned_job_ids)
            or not set(plan["executed_job_ids"]).issubset(planned_job_ids)
            or set(plan["reused_job_ids"]) & set(plan["executed_job_ids"])
            or set(plan["failed_job_ids"]) - set(plan["executed_job_ids"])
            or set(plan["pending_job_ids"]) - planned_job_ids
            or set(plan["pending_job_ids"])
            & (set(plan["reused_job_ids"]) | set(plan["executed_job_ids"]))
            or (
                set(plan["reused_job_ids"])
                | set(plan["executed_job_ids"])
                | set(plan["pending_job_ids"])
            ) != planned_job_ids
            or not set(plan["affected_job_ids"]).issubset(
                set(plan["executed_job_ids"]) | set(plan["pending_job_ids"])
            )
            or not SHA256_RE.fullmatch(str(plan.get("plan_sha256", "")))
        ):
            raise ConfigurationError("attempt 增量计划身份或集合非法。")
        unsigned_plan = dict(plan)
        unsigned_plan.pop("plan_sha256", None)
        if plan.get("plan_sha256") != incremental_recovery.digest(unsigned_plan):
            raise ConfigurationError("attempt 增量计划摘要不一致。")
    results = payload.get("results", [])
    if not isinstance(results, list):
        raise ConfigurationError("attempt results 必须是数组。")
    for result in results:
        if not isinstance(result, Mapping):
            raise ConfigurationError("attempt Job 结果必须是对象。")
        _validate_incremental_job_result(result, label=f"attempt:{result.get('id', '')}")
    evaluation_transition = payload.get("evaluation_transition")
    if evaluation_transition is not None:
        _require_file_binding(evaluation_transition, "attempt 评估工具 transition")
        raw_path = str(evaluation_transition.get("path", ""))
        parsed = PurePosixPath(raw_path)
        if (
            parsed.is_absolute()
            or str(parsed) != raw_path
            or "\\" in raw_path
            or any(part in {"", ".", ".."} for part in parsed.parts)
            or _PHASE_EVALUATION_TRANSITION_FILE_RE.fullmatch(parsed.name) is None
        ):
            raise ConfigurationError("attempt 评估工具 transition 路径非法。")
    candidate_reuse_transition = payload.get(
        "classification_candidate_reuse_transition"
    )
    if candidate_reuse_transition is not None:
        _require_file_binding(
            candidate_reuse_transition,
            "attempt 分类 Candidate 复用 transition",
        )
        if (
            candidate_reuse_transition.get("path")
            != CLASSIFICATION_CANDIDATE_REUSE_TRANSITION_FILENAME
        ):
            raise ConfigurationError("attempt 分类 Candidate 复用 transition 路径非法。")
        environment = payload.get("environment")
        expected_environment_fields = {
            "evidence_root",
            "before_probe",
            "after_probe",
            "restoration_report",
            "arm64_before_receipt",
            "arm64_after_receipt",
        }
        result_ids = {
            str(item.get("id"))
            for item in results
            if isinstance(item, Mapping) and item.get("id")
        }
        if (
            payload.get("phase") != "candidate"
            or payload.get("status") != "awaiting_receipts"
            or payload.get("execution_error") is not None
            or payload.get("restoration_error") is not None
            or not isinstance(environment, Mapping)
            or set(environment) != expected_environment_fields
            or not isinstance(environment.get("evidence_root"), str)
            or not Path(str(environment["evidence_root"])).is_absolute()
            or any(
                environment.get(name) is not None
                for name in expected_environment_fields - {"evidence_root"}
            )
            or not isinstance(plan, Mapping)
            or set(plan.get("planned_job_ids", []))
            != CLASSIFICATION_CANDIDATE_REUSE_JOB_IDS
            or set(plan.get("reused_job_ids", []))
            != CLASSIFICATION_CANDIDATE_REUSE_JOB_IDS
            or any(
                plan.get(name) != []
                for name in (
                    "affected_job_ids",
                    "executed_job_ids",
                    "failed_job_ids",
                    "pending_job_ids",
                )
            )
            or result_ids != CLASSIFICATION_CANDIDATE_REUSE_JOB_IDS
            or any(
                not isinstance(item, Mapping)
                or item.get("status") != "complete"
                or item.get("disposition") != "reused"
                or not isinstance(item.get("source_receipt"), Mapping)
                for item in results
            )
        ):
            raise ConfigurationError("metadata-only attempt 的零执行边界不闭合。")
    _validate_attempt_watchdog_fields(payload, planned_job_ids)


def _write_capture_attempt(
    campaign_dir: Path,
    attempt_root: Path,
    payload: dict[str, Any],
) -> dict[str, Any]:
    """只写一次封存 run 阶段 attempt，不允许 seal 回写。"""

    _require_formal_campaign(campaign_dir)
    phase = str(payload.get("phase", ""))
    candidate_id = payload.get("candidate_id")
    reservation = _load_capture_reservation(
        campaign_dir,
        attempt_root,
        phase=phase,
        candidate_id=(str(candidate_id) if candidate_id is not None else None),
    )
    identity = payload.get("identity")
    if not isinstance(identity, dict) or _fingerprint(identity) != reservation.get(
        "identity_sha256"
    ):
        raise ConfigurationError("抓包 attempt 身份与原子预约不一致。")
    planned = {
        item["id"]: item["execution_sha256"]
        for item in reservation["planned_jobs"]
    }
    for result in payload.get("results", []):
        if (
            not isinstance(result, dict)
            or result.get("id") not in planned
            or result.get("execution_sha256") != planned[result["id"]]
        ):
            raise ConfigurationError("抓包 attempt 任务不在原子预约内或执行摘要漂移。")
    _validate_attempt_incremental_fields(payload, set(planned))

    document = dict(payload)
    document["schema_version"] = CAPTURE_ATTEMPT_SCHEMA
    document["campaign_mode"] = reservation["campaign_mode"]
    document["campaign_purpose"] = reservation["campaign_purpose"]
    document["candidate_purpose"] = reservation["candidate_purpose"]
    document["campaign_manifest_sha256"] = file_sha256(
        campaign_dir / "campaign.json"
    )
    document["attempt_id"] = attempt_root.name
    document["run_nonce"] = reservation["run_nonce"]
    document["started_at_utc"] = reservation["started_at_utc"]
    document["completed_at_utc"] = _utc_now()
    document["reservation"] = {
        "path": str((attempt_root / "reservation.json").relative_to(campaign_dir)),
        "sha256": file_sha256(attempt_root / "reservation.json"),
    }
    document["attempt_digest"] = _fingerprint(document)
    _secure_write_json_once(attempt_root / "attempt.json", document)
    return document


def _load_capture_attempt(
    campaign_dir: Path,
    phase: str,
    candidate_id: str | None,
    attempt_id: str,
    *,
    _historical_manifest_controls: bool = False,
    _verified_campaign_manifest: Mapping[str, Any] | None = None,
) -> tuple[Path, dict[str, Any]]:
    """读取并重验 run 阶段的不可变 attempt。"""

    manifest = (
        dict(_verified_campaign_manifest)
        if isinstance(_verified_campaign_manifest, Mapping)
        else load_campaign_manifest(
            campaign_dir,
            _control_epoch_bootstrap=_historical_manifest_controls,
        )
    )
    _require_formal_campaign(campaign_dir, manifest)
    attempt_root = _capture_attempt_path(
        campaign_dir, phase, candidate_id, attempt_id
    )
    path = attempt_root / "attempt.json"
    _reject_symlink_components(path, campaign_dir, "抓包 attempt 收据")
    payload = _read_json(path, "抓包 attempt 收据")
    identity = payload.get("identity")
    reservation = _load_capture_reservation(
        campaign_dir,
        attempt_root,
        phase=phase,
        candidate_id=candidate_id,
        _manifest=manifest,
    )
    expected_digest = payload.get("attempt_digest")
    unsigned = dict(payload)
    unsigned.pop("attempt_digest", None)
    expected_candidate = candidate_id if phase == "candidate" else None
    if (
        payload.get("schema_version") != CAPTURE_ATTEMPT_SCHEMA
        or payload.get("campaign_id") != manifest["campaign_id"]
        or payload.get("campaign_mode") != manifest["campaign_mode"]
        or payload.get("campaign_purpose") != manifest["campaign_purpose"]
        or payload.get("candidate_purpose")
        != (manifest["campaign_purpose"] if phase == "candidate" else None)
        or payload.get("campaign_mode") != reservation.get("campaign_mode")
        or payload.get("campaign_purpose") != reservation.get("campaign_purpose")
        or payload.get("candidate_purpose")
        != reservation.get("candidate_purpose")
        or payload.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or payload.get("attempt_id") != attempt_id
        or payload.get("phase") != phase
        or payload.get("candidate_id") != expected_candidate
        or payload.get("run_nonce") != reservation.get("run_nonce")
        or payload.get("started_at_utc") != reservation.get("started_at_utc")
        or not _is_rfc3339_timestamp(payload.get("completed_at_utc"))
        or not isinstance(identity, Mapping)
        or _fingerprint(identity)
        != reservation.get("identity_sha256")
        or payload.get("reservation")
        != {
            "path": str((attempt_root / "reservation.json").relative_to(campaign_dir)),
            "sha256": file_sha256(attempt_root / "reservation.json"),
        }
        or not SHA256_RE.fullmatch(str(expected_digest))
        or _fingerprint(unsigned) != expected_digest
    ):
        raise ConfigurationError("抓包 attempt 身份或摘要不一致。")
    if _rfc3339_datetime(
        payload["completed_at_utc"], "attempt.completed_at_utc"
    ) < _rfc3339_datetime(
        payload["started_at_utc"], "attempt.started_at_utc"
    ):
        raise ConfigurationError("抓包 attempt 完成时间早于原子预约时间。")
    if payload.get("status") not in {
        "awaiting_receipts",
        "failed",
        "environment_contaminated",
    }:
        raise ConfigurationError("抓包 attempt 状态非法。")
    _validate_attempt_incremental_fields(
        payload,
        {str(item["id"]) for item in reservation["planned_jobs"]},
    )
    _validate_attempt_watchdog_bindings(
        campaign_dir,
        attempt_root,
        payload,
        planned_job_ids={str(item["id"]) for item in reservation["planned_jobs"]},
    )
    evaluation_transition = payload.get("evaluation_transition")
    if evaluation_transition is not None:
        transition_path = _campaign_file(
            campaign_dir,
            str(evaluation_transition["path"]),
        )
        if (
            transition_path.is_symlink()
            or not transition_path.is_file()
            or file_sha256(transition_path) != evaluation_transition["sha256"]
        ):
            raise ConfigurationError("attempt 评估工具 transition 文件丢失或摘要漂移。")
    candidate_reuse_transition = payload.get(
        "classification_candidate_reuse_transition"
    )
    if candidate_reuse_transition is not None:
        if phase != "candidate" or not isinstance(candidate_id, str):
            raise ConfigurationError("分类 Candidate 复用 transition 只能绑定候选 attempt。")
        _load_classification_candidate_reuse_transition(
            campaign_dir,
            manifest,
            candidate_reuse_transition,
            candidate_id=candidate_id,
            identity=identity,
        )
    return attempt_root, payload


def _active_unsealed_attempts(
    campaign_dir: Path,
    phase: str,
    *,
    _manifest: Mapping[str, Any] | None = None,
) -> list[str]:
    """列出未完成预约或未被阶段结果绑定的 attempt。"""

    scopes: list[tuple[str | None, Path]] = []
    if phase == "official":
        scopes.append((None, campaign_dir / "official"))
    else:
        candidates_root = campaign_dir / "candidates"
        if not candidates_root.exists():
            return []
        if candidates_root.is_symlink() or not candidates_root.is_dir():
            raise ConfigurationError("候选抓包目录不可信。")
        for candidate_root in sorted(candidates_root.iterdir()):
            if not candidate_root.is_dir() or candidate_root.is_symlink():
                continue
            if not SAFE_ID_RE.fullmatch(candidate_root.name):
                raise ConfigurationError("候选抓包目录包含非法 candidate-id。")
            scopes.append((candidate_root.name, candidate_root))

    active: list[str] = []
    for candidate_id, scope in scopes:
        sealed_attempt_id: str | None = None
        result_path = scope / "result.json"
        if result_path.exists() or result_path.is_symlink():
            if result_path.is_symlink() or not result_path.is_file():
                raise ConfigurationError("抓包阶段结果路径不可信。")
            stage_kwargs: dict[str, Any] = {
                "_historical_manifest_controls": True,
            }
            if _manifest is not None:
                stage_kwargs["_verified_campaign_manifest"] = _manifest
            stage = _load_stage_result(
                campaign_dir,
                "capture-official" if phase == "official" else "capture-candidate",
                candidate_id,
                **stage_kwargs,
            )
            attempt_reference = stage.get("attempt")
            if not isinstance(attempt_reference, dict):
                raise ConfigurationError("已封存抓包阶段缺少 attempt 绑定。")
            sealed_attempt_id = Path(str(attempt_reference.get("path", ""))).parent.name
        attempts_root = scope / "attempts"
        if not attempts_root.exists():
            continue
        if attempts_root.is_symlink() or not attempts_root.is_dir():
            raise ConfigurationError("抓包 attempts 目录不可信。")
        for attempt_root in sorted(attempts_root.iterdir()):
            if not attempt_root.is_dir() or attempt_root.is_symlink():
                continue
            if not SAFE_ID_RE.fullmatch(attempt_root.name):
                # 原子发布前的隐藏临时目录不属于可见 attempt 命名空间。
                if attempt_root.name.startswith(".reservation-"):
                    continue
                raise ConfigurationError("抓包目录包含非法 attempt-id。")
            _load_capture_reservation(
                campaign_dir,
                attempt_root,
                phase=phase,
                candidate_id=candidate_id,
                _manifest=_manifest,
            )
            attempt_path = attempt_root / "attempt.json"
            if not attempt_path.exists():
                active.append(
                    f"{candidate_id or 'official'}:{attempt_root.name}:reserved_or_interrupted"
                )
                continue
            if attempt_path.is_symlink() or not attempt_path.is_file():
                raise ConfigurationError("抓包 attempt 收据路径不可信。")
            _, attempt = _load_capture_attempt(
                campaign_dir,
                phase,
                candidate_id,
                attempt_root.name,
                _verified_campaign_manifest=_manifest,
            )
            if (
                attempt.get("status") == "awaiting_receipts"
                and attempt_root.name != sealed_attempt_id
            ):
                active.append(
                    f"{candidate_id or 'official'}:{attempt_root.name}"
                )
    return active


def _failed_capture_attempts(
    campaign_dir: Path,
    phase: str,
    *,
    _manifest: Mapping[str, Any] | None = None,
) -> list[str]:
    """列出尚未通过显式 resume 处理的失败 attempt。"""

    failed: list[str] = []
    for current_phase, candidate_id, attempt_root in _campaign_attempt_roots(
        campaign_dir
    ):
        if current_phase != phase or not (attempt_root / "attempt.json").is_file():
            continue
        _, attempt = _load_capture_attempt(
            campaign_dir,
            phase,
            candidate_id,
            attempt_root.name,
            _verified_campaign_manifest=_manifest,
        )
        if attempt.get("status") == "failed":
            failed.append(f"{candidate_id or 'official'}:{attempt_root.name}")
    return failed


def _candidate_runtime_override_path(campaign_dir: Path, candidate_id: str) -> Path:
    return campaign_dir / "candidates" / candidate_id / CANDIDATE_RUNTIME_OVERRIDE_FILENAME


def _on_disk_campaign_configuration(campaign_dir: Path) -> tuple[dict[str, Any], str]:
    """读取磁盘上的 Campaign 清单并复核摘要，返回其 configuration 与文件摘要。

    候选运行坐标覆盖只承认磁盘清单里冻结的值作为 ``predecessor``；内存里可能已经
    应用过覆盖，不能拿它当基准。
    """

    manifest_path = campaign_dir / "campaign.json"
    digest_path = campaign_dir / "campaign.sha256"
    if not manifest_path.is_file() or not digest_path.is_file():
        raise ConfigurationError("Campaign 缺少 campaign.json 或 campaign.sha256。")
    expected = digest_path.read_text(encoding="utf-8").strip()
    actual = file_sha256(manifest_path)
    if not SHA256_RE.fullmatch(expected) or actual != expected:
        raise ConfigurationError("Campaign 核心清单摘要不一致，拒绝继续。")
    manifest = _read_json(manifest_path, "Campaign 核心清单")
    configuration = manifest.get("configuration")
    if not isinstance(configuration, dict):
        raise ConfigurationError("Campaign 清单缺少 configuration。")
    return configuration, actual


def _validate_candidate_runtime_override_value(key: str, value: Any) -> Any:
    """按键类型校验单个覆盖值；compose 一对键另行联合校验。"""

    if key not in CANDIDATE_RUNTIME_OVERRIDE_KEYS:
        raise ConfigurationError(
            f"运行坐标 {key} 不允许在候选层覆盖；证据语义字段只能通过新 Campaign 改变。"
        )
    if key in CANDIDATE_RUNTIME_OVERRIDE_INT_KEYS:
        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise ConfigurationError(f"候选运行坐标 {key} 必须是正整数。")
        return value
    if not isinstance(value, str) or not value.strip():
        raise ConfigurationError(f"候选运行坐标 {key} 必须是非空字符串。")
    if key in CANDIDATE_RUNTIME_OVERRIDE_CONTAINER_KEYS and not SAFE_ID_RE.fullmatch(value):
        raise ConfigurationError(f"候选运行坐标 {key} 不是合法容器名。")
    if key in CANDIDATE_RUNTIME_OVERRIDE_BINARY_KEYS and not SAFE_ABSOLUTE_PATH_RE.fullmatch(
        value
    ):
        raise ConfigurationError(f"候选运行坐标 {key} 必须是规范绝对路径。")
    return value


def _load_candidate_runtime_override(
    campaign_dir: Path, candidate_id: str
) -> tuple[dict[str, Any], dict[str, Any]] | None:
    """读取并复核候选运行坐标覆盖收据；不存在时返回 ``None``。"""

    if not SAFE_ID_RE.fullmatch(str(candidate_id)):
        raise ConfigurationError("--candidate-id 格式非法。")
    path = _candidate_runtime_override_path(campaign_dir, candidate_id)
    if not path.exists() and not path.is_symlink():
        return None
    _reject_symlink_components(path, campaign_dir, "候选运行坐标覆盖收据")
    if path.is_symlink() or not path.is_file():
        raise ConfigurationError("候选运行坐标覆盖收据不是普通文件。")
    receipt = _read_json(path, "候选运行坐标覆盖收据")
    expected_fields = {
        "schema_version",
        "campaign_id",
        "campaign_manifest_sha256",
        "candidate_id",
        "issued_at_utc",
        "reason",
        "overrides",
        "receipt_digest",
    }
    if set(receipt) != expected_fields:
        raise ConfigurationError("候选运行坐标覆盖收据字段不闭合。")
    unsigned = dict(receipt)
    digest = unsigned.pop("receipt_digest", None)
    if (
        receipt.get("schema_version") != CANDIDATE_RUNTIME_OVERRIDE_SCHEMA
        or not SHA256_RE.fullmatch(str(digest))
        or _fingerprint(unsigned) != digest
    ):
        raise ConfigurationError("候选运行坐标覆盖收据摘要或 schema 非法。")
    configuration, manifest_sha256 = _on_disk_campaign_configuration(campaign_dir)
    if (
        receipt.get("campaign_manifest_sha256") != manifest_sha256
        or receipt.get("candidate_id") != candidate_id
        or not isinstance(receipt.get("reason"), str)
        or not str(receipt.get("reason")).strip()
    ):
        raise ConfigurationError("候选运行坐标覆盖收据未绑定当前 Campaign 与候选。")
    overrides = receipt.get("overrides")
    if not isinstance(overrides, dict) or not overrides:
        raise ConfigurationError("候选运行坐标覆盖收据没有任何覆盖项。")
    for key, entry in overrides.items():
        if (
            not isinstance(entry, dict)
            or set(entry) != {"predecessor", "successor"}
            or entry.get("predecessor") != configuration.get(key)
            or entry.get("predecessor") == entry.get("successor")
        ):
            raise ConfigurationError(f"候选运行坐标覆盖项 {key} 与 Campaign 冻结值不衔接。")
        _validate_candidate_runtime_override_value(key, entry["successor"])
    compose_present = set(overrides) & CANDIDATE_RUNTIME_OVERRIDE_COMPOSE_KEYS
    if compose_present and compose_present != CANDIDATE_RUNTIME_OVERRIDE_COMPOSE_KEYS:
        raise ConfigurationError("compose 目录与 -f 参数串必须同时覆盖。")
    binding = {
        "path": path.relative_to(campaign_dir).as_posix(),
        "sha256": file_sha256(path),
        "bytes": path.stat().st_size,
    }
    return receipt, binding


def _apply_candidate_runtime_override(
    campaign_dir: Path, manifest: dict[str, Any], candidate_id: str | None
) -> dict[str, Any]:
    """返回应用了候选运行坐标覆盖的清单副本；没有覆盖时原样返回。

    该函数幂等：覆盖值始终来自磁盘收据并与磁盘清单衔接，重复应用得到同一结果。
    调用方必须把返回值作为本次 run／seal 全程使用的清单，使 Job 模板、环境探针、
    二进制校验与容器身份都读取同一组生效坐标。
    """

    if not candidate_id:
        return manifest
    loaded = _load_candidate_runtime_override(campaign_dir, str(candidate_id))
    if loaded is None:
        return manifest
    receipt, _ = loaded
    if receipt.get("campaign_id") != manifest.get("campaign_id"):
        raise ConfigurationError("候选运行坐标覆盖收据的 Campaign ID 与清单不一致。")
    effective = json.loads(json.dumps(manifest, ensure_ascii=False))
    configuration = effective["configuration"]
    for key, entry in receipt["overrides"].items():
        configuration[key] = entry["successor"]
    return effective


def create_candidate_runtime_override(arguments: argparse.Namespace) -> dict[str, Any]:
    """在候选首个 attempt 前登记一份写一次的运行坐标覆盖收据。

    允许覆盖的只有账号／API Key ID、五个容器名、四个二进制路径和 Live attestation
    compose 坐标。目标源码树、官方包、运行镜像、模型与证据根属于证据语义，
    仍只能通过新 Campaign 改变。候选一旦有 attempt 或已封存，覆盖只能登记到新的
    candidate-id 上。
    """

    campaign_dir = arguments.campaign_dir
    manifest = _require_formal_campaign(campaign_dir)
    candidate_id = str(arguments.candidate_id)
    if not SAFE_ID_RE.fullmatch(candidate_id):
        raise ConfigurationError("--candidate-id 格式非法。")
    reason = str(getattr(arguments, "reason", "") or "").strip()
    if not reason or len(reason) > 512:
        raise ConfigurationError("--reason 必须是 1～512 字符的非空说明。")
    _, result_path = _stage_path(campaign_dir, "capture-candidate", candidate_id)
    if result_path.exists() or result_path.is_symlink():
        raise ConfigurationError(
            "candidate-id 已封存，运行坐标不可再覆盖；请使用新 candidate-id。"
        )
    candidate_root = campaign_dir / "candidates" / candidate_id
    if (candidate_root / "attempts").exists():
        raise ConfigurationError(
            "候选已有 attempt，运行坐标覆盖必须在首个 attempt 前登记；请使用新 candidate-id。"
        )
    path = _candidate_runtime_override_path(campaign_dir, candidate_id)
    if path.exists() or path.is_symlink():
        raise ConfigurationError(
            "候选运行坐标覆盖收据已存在，不可覆盖；请使用新 candidate-id。"
        )
    configuration, manifest_sha256 = _on_disk_campaign_configuration(campaign_dir)
    raw_items = list(getattr(arguments, "set", None) or [])
    if not raw_items:
        raise ConfigurationError("至少提供一个 --set KEY=VALUE。")
    pending: dict[str, Any] = {}
    for item in raw_items:
        key, separator, raw_value = str(item).partition("=")
        key = key.strip()
        if not separator or not key:
            raise ConfigurationError(f"--set 必须是 KEY=VALUE：{item}")
        if key in pending:
            raise ConfigurationError(f"--set 重复指定 {key}。")
        if key not in CANDIDATE_RUNTIME_OVERRIDE_KEYS:
            raise ConfigurationError(
                f"运行坐标 {key} 不允许在候选层覆盖；证据语义字段只能通过新 Campaign 改变。"
            )
        value: Any = raw_value.strip()
        if key in CANDIDATE_RUNTIME_OVERRIDE_INT_KEYS:
            try:
                value = int(value)
            except ValueError as error:
                raise ConfigurationError(f"候选运行坐标 {key} 必须是正整数。") from error
        pending[key] = _validate_candidate_runtime_override_value(key, value)
    compose_present = set(pending) & CANDIDATE_RUNTIME_OVERRIDE_COMPOSE_KEYS
    if compose_present:
        if compose_present != CANDIDATE_RUNTIME_OVERRIDE_COMPOSE_KEYS:
            raise ConfigurationError("compose 目录与 -f 参数串必须同时覆盖。")
        validated = _successor_runtime_configuration(
            argparse.Namespace(
                live_attestation_compose_dir=Path(pending["live_attestation_compose_dir"]),
                live_attestation_compose_files=pending["live_attestation_compose_files"],
                reason="candidate_runtime_identity_correction",
            ),
            configuration,
        )
        if validated is None:
            raise ConfigurationError("compose 坐标校验失败。")
        pending.update(validated)
    overrides: dict[str, dict[str, Any]] = {}
    for key in sorted(pending):
        current = configuration.get(key)
        if current == pending[key]:
            raise ConfigurationError(f"运行坐标 {key} 与 Campaign 冻结值相同，无需覆盖。")
        overrides[key] = {"predecessor": current, "successor": pending[key]}
    receipt: dict[str, Any] = {
        "schema_version": CANDIDATE_RUNTIME_OVERRIDE_SCHEMA,
        "campaign_id": str(manifest["campaign_id"]),
        "campaign_manifest_sha256": manifest_sha256,
        "candidate_id": candidate_id,
        "issued_at_utc": _utc_now(),
        "reason": reason,
        "overrides": overrides,
    }
    receipt["receipt_digest"] = _fingerprint(receipt)
    candidates_root = campaign_dir / "candidates"
    candidates_root.mkdir(mode=0o700, exist_ok=True)
    candidate_root.mkdir(mode=0o700, exist_ok=True)
    encoded = (
        json.dumps(receipt, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    flags = (
        os.O_WRONLY
        | os.O_CREAT
        | os.O_EXCL
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    descriptor = os.open(path, flags, 0o600)
    with os.fdopen(descriptor, "wb") as stream:
        stream.write(encoded)
        stream.flush()
        os.fsync(stream.fileno())
    return {
        "status": "recorded",
        "campaign_id": receipt["campaign_id"],
        "candidate_id": candidate_id,
        "path": str(path),
        "receipt_digest": receipt["receipt_digest"],
        "overrides": overrides,
    }


def _candidate_identity_for_run(
    arguments: argparse.Namespace,
    manifest: dict[str, Any],
    classification: dict[str, Any],
    *,
    verify_image: bool = True,
    image_id_override: str | None = None,
    source_tree_sha256_override: str | None = None,
    git_commit_override: str | None = None,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
) -> dict[str, Any]:
    """在任何候选请求发出前冻结实际候选身份。

    ``verify_image=False`` 只用于增量计划阶段：它不触碰 Docker，只使用调用方
    提供的 image ID（或前序失败 attempt 的只读身份提示）生成计划坐标。只要计划
    确定仍有任务需要执行，调用方必须随后以 ``verify_image=True`` 重验运行容器。
    """

    if deadline is not None:
        deadline.check("candidate-identity:start")
    required = {
        "runtime_image": getattr(arguments, "runtime_image", None),
        "build_id": getattr(arguments, "build_id", None),
        "deployed_version": getattr(arguments, "deployed_version", None),
        "profile_id": getattr(arguments, "profile_id", None),
        "profile_digest": getattr(arguments, "profile_digest", None),
        "candidate_purpose": getattr(arguments, "candidate_purpose", None),
    }
    missing = sorted(field for field, value in required.items() if not value)
    if missing:
        raise ConfigurationError(f"候选 run 缺少身份参数：{missing}")
    if not IMMUTABLE_IMAGE_RE.fullmatch(str(arguments.runtime_image)):
        raise ConfigurationError(
            "候选 --runtime-image 必须是 repository@sha256:<manifest-digest>。"
        )
    if not SHA256_RE.fullmatch(str(arguments.profile_digest)):
        raise ConfigurationError("--profile-digest 必须是 64 位小写 SHA-256。")
    if arguments.candidate_purpose not in CANDIDATE_PURPOSES:
        raise ConfigurationError(
            "--candidate-purpose 必须显式为 validation_only 或 "
            "production_replacement。"
        )
    if arguments.candidate_purpose != manifest.get("campaign_purpose"):
        raise ConfigurationError(
            "candidate purpose 与 Campaign 冻结用途不一致；必须新建 Campaign。"
        )
    for field in ("profile_id", "build_id", "deployed_version"):
        if not SAFE_ID_RE.fullmatch(str(getattr(arguments, field))):
            raise ConfigurationError(f"--{field.replace('_', '-')} 格式非法。")
    approved_profile_id, approved_profile_digest = _profile_binding_from_manifest(
        arguments.campaign_dir, classification
    )
    if (
        arguments.profile_id != approved_profile_id
        or arguments.profile_digest != approved_profile_digest
    ):
        raise ConfigurationError("候选运行画像 ID／digest 与批准画像不一致。")
    supplied_image_id = getattr(arguments, "candidate_image_id", None)
    if supplied_image_id and not IMAGE_ID_RE.fullmatch(
        str(supplied_image_id)
    ):
        raise ConfigurationError("--candidate-image-id 格式非法。")
    source_root = arguments.candidate_source or Path(__file__).resolve().parents[2]
    if not source_root.is_dir() or source_root.is_symlink():
        raise ConfigurationError("--candidate-source 不存在或不是可信目录。")
    image_id = image_id_override or supplied_image_id
    if verify_image:
        image_id = _verify_container_image_reference(
            manifest["configuration"]["service_container"],
            str(arguments.runtime_image),
            supplied_image_id,
            deadline=deadline,
            heartbeat=heartbeat,
        )
    elif not image_id or not IMAGE_ID_RE.fullmatch(str(image_id)):
        raise ConfigurationError(
            "增量计划阶段缺少候选 image ID；请提供 --candidate-image-id，"
            "或绑定可读取的前序失败 attempt。"
        )
    if source_tree_sha256_override is not None and not SHA256_RE.fullmatch(
        str(source_tree_sha256_override)
    ):
        raise ConfigurationError("候选 source_tree_sha256_override 非法。")
    if git_commit_override is not None and not SAFE_ID_RE.fullmatch(
        str(git_commit_override)
    ):
        raise ConfigurationError("候选 git_commit_override 非法。")
    result = {
        "git_commit": git_commit_override or _git_commit(source_root),
        "source_root": str(source_root.resolve(strict=True)),
        "source_tree_sha256": source_tree_sha256_override
        or _directory_tree_digest(source_root),
        "image_reference": arguments.runtime_image,
        "image_digest": "sha256:"
        + arguments.runtime_image.rsplit("sha256:", 1)[-1],
        "image_id": image_id,
        "build_id": arguments.build_id,
        "deployed_version": arguments.deployed_version,
        "profile_id": arguments.profile_id,
        "profile_digest": arguments.profile_digest,
        "candidate_purpose": arguments.candidate_purpose,
    }
    if deadline is not None:
        deadline.check("candidate-identity:complete")
    return result


def _verify_candidate_attempt_identity(
    manifest: dict[str, Any], identity: dict[str, Any]
) -> None:
    """seal 前重验源码树和运行容器，防止 run／seal 间换包。"""

    source_root = Path(str(identity.get("source_root", "")))
    if (
        identity.get("candidate_purpose") not in CANDIDATE_PURPOSES
        or identity.get("candidate_purpose") != manifest.get("campaign_purpose")
    ):
        raise ConfigurationError("候选 attempt 用途与 Campaign 冻结用途不一致。")
    if (
        not source_root.is_absolute()
        or not source_root.is_dir()
        or source_root.is_symlink()
        or _directory_tree_digest(source_root) != identity.get("source_tree_sha256")
    ):
        raise ConfigurationError("候选源码树在 run／seal 之间发生漂移。")
    _verify_container_image_reference(
        manifest["configuration"]["service_container"],
        str(identity.get("image_reference", "")),
        str(identity.get("image_id", "")),
    )


def _deduplicate_evidence_roots(
    values: Iterable[Path], *, require_nonempty: bool = True
) -> list[Path]:
    """解析证据根并拒绝符号链接、文件和重复别名。"""

    roots: list[Path] = []
    seen: set[Path] = set()
    for value in values:
        if not value.is_absolute() or value.is_symlink() or not value.is_dir():
            raise ConfigurationError(f"证据根不存在或不可信：{value}")
        resolved = value.resolve(strict=True)
        if resolved in seen:
            continue
        seen.add(resolved)
        roots.append(resolved)
    if require_nonempty and not roots:
        raise ConfigurationError("抓包 attempt 没有可封存证据根。")
    return roots


def _environment_probe_arguments(
    manifest: dict[str, Any],
    output_dir: Path,
    phase: str,
) -> EnvironmentProbeArguments:
    """只从不可变 Campaign 配置构造环境探针参数。"""

    configuration = manifest["configuration"]
    return EnvironmentProbeArguments(
        output_dir=output_dir,
        service_container=configuration["service_container"],
        keeper_container=configuration["keeper_container"],
        postgres_container=configuration["postgres_container"],
        redis_container=configuration["redis_container"],
        capture_container=configuration["capture_container"],
        account_id=configuration["codex_account_id"],
        api_key_id=configuration["api_key_id"],
        phase=phase,
    )


def _invoke_with_optional_deadline(
    target: Any,
    *args: Any,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
    **kwargs: Any,
) -> Any:
    """调用可选 deadline 接口，并兼容旧的离线适配器签名。

    只在真正调用前检查签名；绝不通过捕获调用后的 ``TypeError`` 重试，避免
    一个已经触碰外部环境的操作被重复执行。
    """

    if deadline is not None or heartbeat is not None:
        callable_target = getattr(target, "side_effect", None)
        if not callable(callable_target):
            callable_target = target
        try:
            signature = inspect.signature(callable_target)
            accepts_kwargs = any(
                parameter.kind == inspect.Parameter.VAR_KEYWORD
                for parameter in signature.parameters.values()
            )
            if deadline is not None and (
                accepts_kwargs or "deadline" in signature.parameters
            ):
                kwargs["deadline"] = deadline
            if heartbeat is not None and (
                accepts_kwargs or "heartbeat" in signature.parameters
            ):
                kwargs["heartbeat"] = heartbeat
        except (TypeError, ValueError):
            # 无法反射的真实 callable 仍按新接口传递；调用失败应直接停线。
            if deadline is not None:
                kwargs["deadline"] = deadline
            if heartbeat is not None:
                kwargs["heartbeat"] = heartbeat
    return target(*args, **kwargs)


def _probe_capture_environment(
    manifest: dict[str, Any],
    output_dir: Path,
    phase: str,
    *,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
) -> dict[str, Any]:
    """执行独立只读探针；单独包装便于离线测试替换执行边界。"""

    if deadline is not None:
        deadline.check(f"environment-probe:{phase}:start")
    result = run_environment_probe(
        _environment_probe_arguments(manifest, output_dir, phase),
        deadline=deadline,
        heartbeat=heartbeat,
    )
    if deadline is not None:
        deadline.check(f"environment-probe:{phase}:complete")
    return result


def _capture_arm64_environment_receipt(
    output_root: Path,
    *,
    phase: str,
    subject_id: str,
    deadline: incremental_recovery.WallClockDeadline | None = None,
    heartbeat: Any | None = None,
) -> tuple[Path, dict[str, Any]]:
    """只读采集并立即重放一次 ARM64 固定网络与磁盘收据。"""

    if deadline is not None:
        deadline.check(f"arm64-receipt:{phase}:start")
    ensure_private_directory(output_root)
    codex_upgrade_arm64_environment_receipt.collect(
        output_root,
        "facts.json",
        phase=phase,
        subject_id=subject_id,
        deadline=deadline,
        heartbeat=heartbeat,
    )
    receipt = codex_upgrade_arm64_environment_receipt.finalize(
        output_root,
        "facts.json",
        "receipt.json",
    )
    replayed = codex_upgrade_arm64_environment_receipt.replay(
        output_root, "receipt.json"
    )
    if deadline is not None:
        deadline.check(f"arm64-receipt:{phase}:complete")
    if replayed != receipt:
        raise ConfigurationError("ARM64 环境收据 finalize／replay 结果不一致。")
    return output_root / "receipt.json", receipt


def _finalize_attempt_restoration(
    evidence_root: Path,
    *,
    phase: str,
    candidate_id: str | None,
    before_directory: str = "before",
    after_directory: str = "after",
    output_name: str = "restoration-report.json",
) -> tuple[Path, dict[str, Any]]:
    """只根据自动探针的十份快照生成恢复收据。"""

    receipts_root = ensure_private_directory(evidence_root / "receipts", evidence_root)
    output = receipts_root / output_name
    state_names = {
        "service": ENVIRONMENT_STATE_FILES["service"],
        "container": ENVIRONMENT_STATE_FILES["containers"],
        "database": ENVIRONMENT_STATE_FILES["database"],
        "account": ENVIRONMENT_STATE_FILES["account"],
        "configuration": ENVIRONMENT_STATE_FILES["configuration"],
    }
    values: dict[str, Any] = {
        "evidence_root": evidence_root,
        "output": output.relative_to(evidence_root),
        "phase": phase,
        "candidate_id": candidate_id,
    }
    for _, before_name, after_name, _ in RESTORATION_INPUTS:
        state_key = before_name.removesuffix("_before")
        filename = state_names[state_key]
        values[before_name] = Path("environment") / before_directory / filename
        values[after_name] = Path("environment") / after_directory / filename
    receipt = finalize_restoration(argparse.Namespace(**values))
    return output, receipt


def _materialize_metadata_only_after_snapshot(
    source_evidence_root: Path,
    target_evidence_root: Path,
    source_environment: Mapping[str, Any],
) -> None:
    """把来源 attempt 的 after 快照复制到 metadata-only attempt。

    metadata-only attempt 没有重新执行环境探针，不能把来源快照冒充为本轮
    探针。这里仅按来源 attempt 的不可变绑定逐文件复制，目标已存在时只接受
    字节级相同的文件；任何缺失、漂移、额外文件或符号链接都 fail-close。
    """

    source_after = source_evidence_root / "environment" / "after"
    target_after = target_evidence_root / "environment" / "after"
    expected_names = {
        "probe-manifest.json",
        *ENVIRONMENT_STATE_FILES.values(),
    }
    if source_after.is_symlink() or not source_after.is_dir():
        raise ConfigurationError("metadata-only 来源 after 目录不存在或不可信。")
    names = sorted(entry.name for entry in os.scandir(source_after))
    if names != sorted(expected_names):
        raise ConfigurationError("metadata-only 来源 after 目录内容不完整或包含额外文件。")

    after_binding = source_environment.get("after_probe")
    if (
        not isinstance(after_binding, Mapping)
        or set(after_binding) != {"path", "sha256", "bytes"}
        or after_binding.get("path") != "environment/after/probe-manifest.json"
        or not SHA256_RE.fullmatch(str(after_binding.get("sha256", "")))
        or not isinstance(after_binding.get("bytes"), int)
        or isinstance(after_binding.get("bytes"), bool)
        or int(after_binding.get("bytes", 0)) <= 0
    ):
        raise ConfigurationError("metadata-only 来源缺少可信 after 探针绑定。")
    source_probe = source_after / "probe-manifest.json"
    if (
        source_probe.is_symlink()
        or not source_probe.is_file()
        or source_probe.stat().st_size != after_binding["bytes"]
        or file_sha256(source_probe) != after_binding["sha256"]
    ):
        raise ConfigurationError("metadata-only 来源 after 探针摘要漂移。")
    probe = _read_json(source_probe, "metadata-only 来源 after 探针")
    if probe.get("phase") != "after" or not _is_rfc3339_timestamp(
        probe.get("observed_at_utc")
    ):
        raise ConfigurationError("metadata-only 来源 after 探针身份或时间非法。")
    snapshots = probe.get("snapshots")
    if not isinstance(snapshots, list) or len(snapshots) != len(
        ENVIRONMENT_STATE_FILES
    ):
        raise ConfigurationError("metadata-only 来源 after 快照清单不完整。")
    snapshot_bindings: dict[str, Mapping[str, Any]] = {}
    for snapshot in snapshots:
        if (
            not isinstance(snapshot, Mapping)
            or set(snapshot)
            != {"bytes", "comparison", "kind", "path", "sha256"}
            or not isinstance(snapshot.get("kind"), str)
            or snapshot["kind"] not in ENVIRONMENT_STATE_FILES
            or snapshot["kind"] in snapshot_bindings
            or snapshot.get("path") != ENVIRONMENT_STATE_FILES[snapshot["kind"]]
            or not isinstance(snapshot.get("bytes"), int)
            or isinstance(snapshot.get("bytes"), bool)
            or int(snapshot.get("bytes", 0)) <= 0
            or not SHA256_RE.fullmatch(str(snapshot.get("sha256", "")))
        ):
            raise ConfigurationError("metadata-only 来源 after 快照绑定非法。")
        snapshot_bindings[str(snapshot["kind"])] = snapshot
    if set(snapshot_bindings) != set(ENVIRONMENT_STATE_FILES):
        raise ConfigurationError("metadata-only 来源 after 快照种类不完整。")

    if target_after.exists() or target_after.is_symlink():
        if target_after.is_symlink() or not target_after.is_dir():
            raise ConfigurationError("metadata-only 当前 after 目录不可信。")
    else:
        ensure_private_directory(target_after, target_evidence_root)
    for name in sorted(expected_names):
        source = source_after / name
        destination = target_after / name
        if source.is_symlink() or not source.is_file():
            raise ConfigurationError(f"metadata-only 来源 after 文件不可信：{name}")
        source_digest = file_sha256(source)
        source_bytes = source.stat().st_size
        if name != "probe-manifest.json":
            kind = next(
                key for key, value in ENVIRONMENT_STATE_FILES.items() if value == name
            )
            snapshot = snapshot_bindings[kind]
            if (
                source_bytes != snapshot["bytes"]
                or source_digest != snapshot["sha256"]
            ):
                raise ConfigurationError(
                    f"metadata-only 来源 after 快照摘要漂移：{name}"
                )
        if destination.exists() or destination.is_symlink():
            if (
                destination.is_symlink()
                or not destination.is_file()
                or destination.stat().st_size != source_bytes
                or file_sha256(destination) != source_digest
            ):
                raise ConfigurationError(
                    f"metadata-only 当前 after 文件与来源不一致：{name}"
                )
            continue
        _secure_copy_file_once(source, destination)


def _candidate_post_client_restoration(
    manifest: dict[str, Any],
    evidence_root: Path,
    candidate_id: str,
    *,
    source_evidence_root: Path | None = None,
    source_environment: Mapping[str, Any] | None = None,
) -> tuple[Path, dict[str, Any], str, bool]:
    """在 Kilo 两入口完成后，再证明其间没有丢失环境或持久数据。"""

    metadata_only = source_evidence_root is not None
    if metadata_only:
        if source_environment is None:
            raise ConfigurationError("metadata-only seal 缺少来源环境绑定。")
        _materialize_metadata_only_after_snapshot(
            source_evidence_root,
            evidence_root,
            source_environment,
        )
    client_after = evidence_root / "environment" / "client-after"
    receipt_path = evidence_root / "receipts" / "client-restoration-report.json"
    if metadata_only and (client_after.is_symlink() or not client_after.is_dir()):
        raise ConfigurationError("metadata-only attempt 缺少既有 Kilo 后探针。")
    if receipt_path.exists():
        if receipt_path.is_symlink() or not receipt_path.is_file():
            raise ConfigurationError("Kilo 后恢复收据路径不可信。")
        try:
            receipt = replay_receipt(
                receipt_path,
                evidence_root,
                expected_subcommand="restoration",
            )
        except (ReceiptFinalizerError, OSError, ValueError) as error:
            raise ConfigurationError(f"Kilo 后恢复收据无法重放：{error}") from error
        probe_manifest = _read_json(
            client_after / "probe-manifest.json", "Kilo 后探针清单"
        )
        checkpoint_at = probe_manifest.get("observed_at_utc")
        if probe_manifest.get("phase") != "after" or not _is_rfc3339_timestamp(
            checkpoint_at
        ):
            raise ConfigurationError("Kilo 后探针清单缺少可信检查点时间。")
        return receipt_path, receipt, str(checkpoint_at), False
    if (client_after.exists() or client_after.is_symlink()) and not metadata_only:
        raise ConfigurationError("Kilo 后探针已存在但没有可重放恢复收据。")
    if not metadata_only:
        _probe_capture_environment(manifest, client_after, "after")
    receipt_path, receipt = _finalize_attempt_restoration(
        evidence_root,
        phase="candidate",
        candidate_id=candidate_id,
        before_directory="after",
        after_directory="client-after",
        output_name="client-restoration-report.json",
    )
    probe_manifest = _read_json(
        client_after / "probe-manifest.json", "Kilo 后探针清单"
    )
    checkpoint_at = probe_manifest.get("observed_at_utc")
    if probe_manifest.get("phase") != "after" or not _is_rfc3339_timestamp(
        checkpoint_at
    ):
        raise ConfigurationError("Kilo 后探针清单缺少可信检查点时间。")
    return receipt_path, receipt, str(checkpoint_at), True


def _record_candidate_seal_failure(
    campaign_dir: Path,
    attempt_root: Path,
    attempt: dict[str, Any],
    error: BaseException,
) -> None:
    """把 Kilo 后恢复失败写入 attempt 主证据；Campaign marker 仅作冗余。"""

    document: dict[str, Any] = {
        "schema_version": SEAL_FAILURE_SCHEMA,
        "campaign_id": attempt["campaign_id"],
        "campaign_mode": attempt["campaign_mode"],
        "campaign_purpose": attempt["campaign_purpose"],
        "candidate_purpose": attempt["candidate_purpose"],
        "campaign_manifest_sha256": attempt["campaign_manifest_sha256"],
        "phase": "candidate",
        "candidate_id": attempt["candidate_id"],
        "attempt_id": attempt["attempt_id"],
        "run_nonce": attempt["run_nonce"],
        "failed_at_utc": _utc_now(),
        "error_type": type(error).__name__,
        "reason": "Kilo 后环境恢复门禁失败",
    }
    document["failure_digest"] = _fingerprint(document)
    _secure_write_json_once(attempt_root / "seal-failure.json", document)
    marker = campaign_dir / "environment-contaminated.json"
    if marker.exists() or marker.is_symlink():
        return
    try:
        _secure_write_json_once(
            marker,
            {
                "schema_version": "codex-upgrade-environment-contamination/v1",
                "phase": "candidate",
                "candidate_id": attempt["candidate_id"],
                "attempt_id": attempt["attempt_id"],
                "reason": document["reason"],
            },
        )
    except (ConfigurationError, OSError):
        # 主 seal-failure 收据已经落盘；旁路提示写失败不得抹掉污染事实。
        pass


def _attempt_evidence_binding(evidence_root: Path, path: Path) -> dict[str, Any]:
    """生成相对 attempt 证据根且含字节数的稳定文件绑定。"""

    if path.is_symlink() or not path.is_file():
        raise ConfigurationError(f"attempt 派生证据不存在或不可信：{path}")
    return {
        "path": path.relative_to(evidence_root).as_posix(),
        "sha256": file_sha256(path),
        "bytes": path.stat().st_size,
    }


def _write_or_verify_json(path: Path, payload: dict[str, Any]) -> None:
    """创建派生 JSON；已存在时只允许逐字段一致。"""

    if path.exists():
        if path.is_symlink() or _read_json(path, "派生封存文件") != payload:
            raise ConfigurationError(f"派生封存文件已经存在且内容不一致：{path}")
        return
    _secure_write_json_once(path, payload)


def _evidence_manifest_path(attempt_root: Path) -> Path:
    return attempt_root / "evidence-manifest.json"


def _evidence_manifest_checkpoint_path(attempt_root: Path) -> Path:
    return attempt_root / "evidence-manifest.checkpoint.json"


def _seal_transition_index(value: Any) -> int:
    """从阶段绑定中选择 seal 追加槽位；无 transition 时使用首槽。"""

    if value is None:
        return 1
    _require_file_binding(value, "评估工具 transition")
    raw_path = str(value["path"])
    parsed = PurePosixPath(raw_path)
    if (
        parsed.is_absolute()
        or str(parsed) != raw_path
        or "\\" in raw_path
        or any(part in {"", ".", ".."} for part in parsed.parts)
    ):
        raise ConfigurationError("评估工具 transition 路径非法，无法选择 seal 槽位。")
    match = _PHASE_EVALUATION_TRANSITION_FILE_RE.fullmatch(parsed.name)
    if match is None:
        raise ConfigurationError("评估工具 transition 文件名非法，无法选择 seal 槽位。")
    index = int(match.group("index") or "1")
    if index < 1 or index > MAX_PHASE_EVALUATION_TRANSITIONS:
        raise ConfigurationError("评估工具 transition 序号非法，无法选择 seal 槽位。")
    return index


def _seal_draft_path(attempt_root: Path, transition_index: int = 1) -> Path:
    if transition_index == 1:
        return attempt_root / "seal-draft.json"
    return attempt_root / f"seal-draft-{transition_index:02d}.json"


def _seal_preview_path(attempt_root: Path, transition_index: int = 1) -> Path:
    if transition_index == 1:
        return attempt_root / "seal-preview.json"
    return attempt_root / f"seal-preview-{transition_index:02d}.json"


def _secret_environment_names() -> list[str]:
    return [
        name
        for name in (
            "ADMIN_BEARER_TOKEN",
            "OPENAI_API_KEY",
            "ANTHROPIC_API_KEY",
            "SUB2API_API_KEY",
        )
        if os.environ.get(name)
    ]


def _load_evidence_manifest(path: Path) -> dict[str, Any]:
    if path.is_symlink() or not path.is_file():
        raise ConfigurationError(f"EvidenceManifest 不存在或路径不可信：{path}")
    payload = _read_json(path, "EvidenceManifest")
    try:
        return codex_upgrade_evidence_manifest.validate_manifest_document(payload)
    except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
        raise ConfigurationError(str(error)) from error


def _imported_stage_evidence_manifest_path(
    campaign_dir: Path,
    stage_payload: Mapping[str, Any],
    binding: Mapping[str, Any],
) -> Path:
    """沿已验证的导入链定位 official EvidenceManifest 原件。

    导入阶段的投影保留原 manifest 相对路径；该路径属于真正
    产生 manifest 的祖先 Campaign，不得相对当前 Campaign 重新解析。
    这里只读重放最多 64 级 predecessor-import 摘要链，不复制
    manifest，也不读取原始证据正文。
    """

    if (
        stage_payload.get("stage") != "capture-official"
        or not isinstance(stage_payload.get("predecessor_import"), Mapping)
    ):
        raise ConfigurationError("EvidenceManifest 只能从 official 导入链解析。")
    _require_file_binding(binding, "导入 EvidenceManifest")
    current_dir = campaign_dir.resolve(strict=True)
    seen: set[Path] = set()
    for _depth in range(64):
        if current_dir in seen:
            raise ConfigurationError("EvidenceManifest 导入链形成循环。")
        seen.add(current_dir)
        manifest_path = current_dir / "campaign.json"
        stage_path = current_dir / "official" / "result.json"
        if (
            current_dir.is_symlink()
            or manifest_path.is_symlink()
            or not manifest_path.is_file()
            or stage_path.is_symlink()
            or not stage_path.is_file()
        ):
            raise ConfigurationError("EvidenceManifest 导入链的 Campaign 不可信。")
        manifest = _read_json(manifest_path, "EvidenceManifest 导入链 Campaign")
        local_stage = _read_json(stage_path, "EvidenceManifest 导入链 official")
        unsigned_stage = dict(local_stage)
        package_digest = unsigned_stage.pop("package_digest", None)
        if (
            local_stage.get("stage") != "capture-official"
            or local_stage.get("campaign_id") != manifest.get("campaign_id")
            or local_stage.get("campaign_manifest_sha256")
            != file_sha256(manifest_path)
            or not SHA256_RE.fullmatch(str(package_digest))
            or package_digest != _fingerprint(unsigned_stage)
        ):
            raise ConfigurationError("EvidenceManifest 导入链的 official 摘要非法。")
        local_binding = local_stage.get("evidence_manifest")
        if local_binding is not None:
            _require_file_binding(local_binding, "EvidenceManifest 原始绑定")
            if dict(local_binding) != dict(binding):
                raise ConfigurationError("EvidenceManifest 导入链的原始绑定漂移。")
            source = _campaign_file(current_dir, str(binding["path"]))
            if (
                source.is_symlink()
                or not source.is_file()
                or file_sha256(source) != binding["sha256"]
            ):
                raise ConfigurationError("EvidenceManifest 导入链的原文件漂移。")
            return source
        import_binding = local_stage.get("predecessor_import")
        _require_file_binding(import_binding, "EvidenceManifest predecessor-import")
        _verify_predecessor_import_shallow(current_dir, manifest, local_stage)
        receipt_path = _campaign_file(current_dir, str(import_binding["path"]))
        receipt = _read_json(receipt_path, "EvidenceManifest predecessor-import")
        predecessor = receipt.get("predecessor_campaign")
        if (
            not isinstance(predecessor, Mapping)
            or set(predecessor)
            != {"campaign_dir", "campaign_id", "campaign_manifest_sha256"}
        ):
            raise ConfigurationError("EvidenceManifest 导入链缺少前序坐标。")
        predecessor_dir = Path(str(predecessor["campaign_dir"]))
        if not predecessor_dir.is_absolute():
            raise ConfigurationError("EvidenceManifest 导入链前序路径非法。")
        try:
            predecessor_dir = predecessor_dir.resolve(strict=True)
        except (OSError, RuntimeError) as error:
            raise ConfigurationError("EvidenceManifest 导入链前序不存在。") from error
        predecessor_manifest_path = predecessor_dir / "campaign.json"
        if (
            predecessor_dir.is_symlink()
            or predecessor_manifest_path.is_symlink()
            or not predecessor_manifest_path.is_file()
        ):
            raise ConfigurationError("EvidenceManifest 导入链前序不可信。")
        predecessor_manifest = _read_json(
            predecessor_manifest_path,
            "EvidenceManifest 导入链前序 Campaign",
        )
        if (
            predecessor_manifest.get("campaign_id") != predecessor["campaign_id"]
            or file_sha256(predecessor_manifest_path)
            != predecessor["campaign_manifest_sha256"]
        ):
            raise ConfigurationError("EvidenceManifest 导入链前序摘要漂移。")
        current_dir = predecessor_dir
    raise ConfigurationError("EvidenceManifest 导入链超过 64 级上限。")


def _stage_evidence_manifest(
    campaign_dir: Path,
    stage_payload: Mapping[str, Any],
    *,
    verify_boundary: bool,
) -> dict[str, Any]:
    binding = stage_payload.get("evidence_manifest")
    _require_file_binding(binding, "EvidenceManifest")
    path = _campaign_file(campaign_dir, str(binding["path"]))
    if not path.exists() and isinstance(
        stage_payload.get("predecessor_import"), Mapping
    ):
        path = _imported_stage_evidence_manifest_path(
            campaign_dir,
            stage_payload,
            binding,
        )
    if path.is_symlink() or not path.is_file() or file_sha256(path) != binding["sha256"]:
        raise ConfigurationError("EvidenceManifest 文件绑定漂移。")
    manifest = _load_evidence_manifest(path)
    roots = [Path(value) for value in stage_payload.get("evidence_roots", [])]
    if not roots:
        raise ConfigurationError("EvidenceManifest 阶段缺少证据根。")
    manifest_inventory = manifest.get("inventory")
    stage_inventory = stage_payload.get("evidence_inventory")
    if manifest_inventory != stage_inventory and (
        stage_payload.get("predecessor_import") is None
        or not _inventory_contents_equal(manifest_inventory, stage_inventory)
    ):
        raise ConfigurationError("EvidenceManifest 与阶段 inventory 不一致。")
    expected_security = stage_payload.get("security")
    manifest_security = manifest.get("security")
    if (
        not isinstance(expected_security, dict)
        or not isinstance(manifest_security, dict)
        or expected_security
        != {"raw_evidence_private": True, **manifest_security}
    ):
        raise ConfigurationError("EvidenceManifest 与阶段安全收据不一致。")
    if verify_boundary:
        try:
            codex_upgrade_evidence_manifest.verify_manifest_boundary(
                manifest,
                roots,
            )
        except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
            raise ConfigurationError(str(error)) from error
    return manifest


def _seal_draft(
    campaign_dir: Path,
    attempt_root: Path,
    *,
    phase: str,
    candidate_id: str | None,
    attempt: Mapping[str, Any],
    stage_payload: Mapping[str, Any],
) -> dict[str, Any]:
    transition_index = _seal_transition_index(
        stage_payload.get("evaluation_transition")
    )
    core: dict[str, Any] = {
        "schema_version": SEAL_DRAFT_SCHEMA,
        "campaign_id": attempt["campaign_id"],
        "phase": phase,
        "candidate_id": candidate_id,
        "attempt_id": attempt["attempt_id"],
        "attempt_digest": attempt["attempt_digest"],
        "campaign_manifest_sha256": file_sha256(campaign_dir / "campaign.json"),
        "stage_payload": dict(stage_payload),
        "stage_payload_sha256": _fingerprint(stage_payload),
    }
    draft = {**core, "draft_digest": _fingerprint(core)}
    _write_or_verify_json(
        _seal_draft_path(attempt_root, transition_index),
        draft,
    )
    return draft


def _load_seal_draft(
    campaign_dir: Path,
    attempt_root: Path,
    *,
    phase: str,
    candidate_id: str | None,
    attempt: Mapping[str, Any],
    transition_index: int = 1,
) -> dict[str, Any]:
    path = _seal_draft_path(attempt_root, transition_index)
    if path.is_symlink() or not path.is_file():
        raise ConfigurationError(f"seal 批准缺少当前槽位冻结草案：{path.name}。")
    draft = _read_json(path, "seal 冻结草案")
    unsigned = dict(draft)
    digest = unsigned.pop("draft_digest", None)
    stage_payload = draft.get("stage_payload")
    if (
        set(draft)
        != {
            "schema_version",
            "campaign_id",
            "phase",
            "candidate_id",
            "attempt_id",
            "attempt_digest",
            "campaign_manifest_sha256",
            "stage_payload",
            "stage_payload_sha256",
            "draft_digest",
        }
        or draft.get("schema_version") != SEAL_DRAFT_SCHEMA
        or draft.get("campaign_id") != attempt.get("campaign_id")
        or draft.get("phase") != phase
        or draft.get("candidate_id") != candidate_id
        or draft.get("attempt_id") != attempt.get("attempt_id")
        or draft.get("attempt_digest") != attempt.get("attempt_digest")
        or draft.get("campaign_manifest_sha256")
        != file_sha256(campaign_dir / "campaign.json")
        or not isinstance(stage_payload, dict)
        or _seal_transition_index(stage_payload.get("evaluation_transition"))
        != transition_index
        or draft.get("stage_payload_sha256") != _fingerprint(stage_payload)
        or digest != _fingerprint(unsigned)
    ):
        raise ConfigurationError("seal 冻结草案身份或摘要不一致。")
    return draft


def _verification_manifest_paths(
    campaign_dir: Path,
    canonical: str,
    candidate_id: str | None,
) -> tuple[Path, Path]:
    suffix = canonical if candidate_id is None else f"{canonical}-{candidate_id}"
    root = campaign_dir / "verification-checkpoints" / "evidence-manifests"
    return root / f"{suffix}.json", root / f"{suffix}.checkpoint.json"


def _inventory_content_index(value: Any) -> dict[str, tuple[int, str]] | None:
    """忽略条目顺序比较历史 Inventory 内容，同时拒绝重复路径。"""

    if not isinstance(value, Mapping):
        return None
    entries = value.get("entries")
    if (
        not isinstance(entries, list)
        or value.get("entry_count") != len(entries)
    ):
        return None
    output: dict[str, tuple[int, str]] = {}
    for entry in entries:
        if not isinstance(entry, Mapping) or set(entry) != {
            "path",
            "size",
            "sha256",
        }:
            return None
        path = entry.get("path")
        size = entry.get("size")
        sha256 = entry.get("sha256")
        if (
            not isinstance(path, str)
            or not path
            or path in output
            or not isinstance(size, int)
            or isinstance(size, bool)
            or size < 0
            or not isinstance(sha256, str)
            or not SHA256_RE.fullmatch(sha256)
        ):
            return None
        output[path] = (size, sha256)
    return output


def _inventory_contents_equal(left: Any, right: Any) -> bool:
    left_index = _inventory_content_index(left)
    right_index = _inventory_content_index(right)
    return (
        left_index is not None
        and right_index is not None
        and left_index == right_index
    )


def _materialize_stage_evidence_manifest(
    campaign_dir: Path,
    canonical: str,
    candidate_id: str | None,
    projected: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """用一次联合 hash／secret 扫描为历史阶段建立本地 manifest 投影。"""

    roots = [Path(value) for value in projected.get("evidence_roots", [])]
    if not roots:
        raise ConfigurationError(f"{canonical} 历史阶段缺少证据根。")
    manifest_path, scanner_checkpoint = _verification_manifest_paths(
        campaign_dir,
        canonical,
        candidate_id,
    )
    ensure_private_directory(manifest_path.parent, campaign_dir)
    if manifest_path.exists() or manifest_path.is_symlink():
        evidence_manifest = _load_evidence_manifest(manifest_path)
        try:
            codex_upgrade_evidence_manifest.verify_manifest_boundary(
                evidence_manifest,
                roots,
            )
        except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
            raise ConfigurationError(str(error)) from error
    else:
        try:
            evidence_manifest = codex_upgrade_evidence_manifest.build_evidence_manifest(
                roots,
                checkpoint_path=scanner_checkpoint,
                secret_env_names=_secret_environment_names(),
            )
        except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
            raise ConfigurationError(str(error)) from error
        _write_or_verify_json(manifest_path, evidence_manifest)
    expected_security = projected.get("security")
    if (
        not _inventory_contents_equal(
            evidence_manifest.get("inventory"),
            projected.get("evidence_inventory"),
        )
        or not isinstance(expected_security, dict)
        or expected_security
        != {"raw_evidence_private": True, **evidence_manifest["security"]}
        or evidence_manifest["security"].get("known_secret_scan_passed") is not True
    ):
        raise ConfigurationError(
            f"{canonical} 历史阶段与新 EvidenceManifest 的清单或安全结论不一致。"
        )
    overlay = dict(projected)
    overlay["evidence_manifest"] = {
        "path": manifest_path.relative_to(campaign_dir).as_posix(),
        "sha256": file_sha256(manifest_path),
    }
    overlay["scan_summary"] = evidence_manifest["scan"]
    _validate_stage_contract(overlay)
    return overlay, evidence_manifest


def _deep_verify_receipt_path(
    campaign_dir: Path,
    canonical: str,
    candidate_id: str | None,
) -> Path:
    suffix = canonical if candidate_id is None else f"{canonical}-{candidate_id}"
    return campaign_dir / "verification-checkpoints" / f"deep-verify-{suffix}.json"


def _write_deep_verify_receipt(
    campaign_dir: Path,
    canonical: str,
    candidate_id: str | None,
    *,
    stage_path: Path,
    evidence_manifest_binding: Mapping[str, Any] | None,
    imported_checkpoint: Path | None,
    scan: Mapping[str, Any],
    evaluation_transition: Mapping[str, Any] | None,
) -> dict[str, Any]:
    core: dict[str, Any] = {
        "schema_version": DEEP_VERIFY_RECEIPT_SCHEMA,
        "completed_at_utc": _utc_now(),
        "campaign_id": load_campaign_manifest(campaign_dir)["campaign_id"],
        "campaign_manifest_sha256": file_sha256(campaign_dir / "campaign.json"),
        "stage": canonical,
        "candidate_id": candidate_id,
        "stage_result_sha256": file_sha256(stage_path),
        "evidence_manifest": (
            dict(evidence_manifest_binding)
            if evidence_manifest_binding is not None
            else None
        ),
        "imported_checkpoint": (
            {
                "path": imported_checkpoint.relative_to(campaign_dir).as_posix(),
                "sha256": file_sha256(imported_checkpoint),
            }
            if imported_checkpoint is not None
            else None
        ),
        "scan": dict(scan),
        "evaluation_transition": (
            dict(evaluation_transition)
            if evaluation_transition is not None
            else None
        ),
        "status": "passed",
    }
    receipt = {**core, "receipt_digest": _fingerprint(core)}
    path = _deep_verify_receipt_path(campaign_dir, canonical, candidate_id)
    if path.is_file() and not path.is_symlink():
        existing = _read_json(path, "deep-verify 收据")
        existing_completed_at = existing.get("completed_at_utc")
        if not _is_rfc3339_timestamp(existing_completed_at):
            raise ConfigurationError("deep-verify 收据完成时间非法。")
        expected_core = {
            **core,
            "completed_at_utc": existing_completed_at,
        }
        expected = {
            **expected_core,
            "receipt_digest": _fingerprint(expected_core),
        }
        if existing != expected:
            raise ConfigurationError("deep-verify 收据与当前预期事实不一致。")
        return existing
    _write_or_verify_json(path, receipt)
    return receipt


def deep_verify_campaign(
    campaign_dir: Path,
    *,
    candidate_id: str | None,
    attempt_id: str | None,
) -> dict[str, Any]:
    """显式建立历史导入 checkpoint，并按需重哈希已封存 candidate。"""

    _reject_contaminated_campaign(campaign_dir)
    manifest = _require_formal_campaign(campaign_dir)
    evaluation_transition: dict[str, str] | None = None
    if attempt_id is not None:
        if not candidate_id:
            raise ConfigurationError("deep-verify 绑定 attempt 时必须提供 --candidate-id。")
        attempt_root, attempt = _load_capture_attempt(
            campaign_dir,
            "candidate",
            candidate_id,
            attempt_id,
        )
        _bind_active_lease_attempt(
            campaign_dir,
            phase="candidate",
            candidate_id=candidate_id,
            attempt_id=attempt.get("attempt_id"),
        )
        evaluation_transition = _verify_plan_identity(
            campaign_dir,
            manifest,
            operation="deep-verify",
            attempt_root=attempt_root,
            attempt=attempt,
        )
        if _is_classification_candidate_metadata_only_attempt(attempt):
            _source_dir, source_root, source_attempt, _transition = (
                _classification_candidate_reuse_attempt_source(
                    campaign_dir,
                    manifest,
                    attempt,
                )
            )
            source_roots = _deduplicate_evidence_roots(
                Path(value) for value in source_attempt.get("evidence_roots", [])
            )
            historical_manifest_path = _evidence_manifest_path(source_root)
            local_manifest_path = (
                attempt_root
                / CLASSIFICATION_CANDIDATE_REUSE_SOURCE_MANIFEST_FILENAME
            )
            selected_path = historical_manifest_path
            scan = {
                "full_scan_count": 0,
                "scanned_bytes": 0,
                "reused_bytes": 0,
                "total_bytes": 0,
                "elapsed_seconds": 0.0,
            }
            if historical_manifest_path.is_file() and not historical_manifest_path.is_symlink():
                source_manifest = _load_evidence_manifest(historical_manifest_path)
            elif local_manifest_path.is_file() and not local_manifest_path.is_symlink():
                selected_path = local_manifest_path
                source_manifest = _load_evidence_manifest(local_manifest_path)
            else:
                selected_path = local_manifest_path
                try:
                    source_manifest = codex_upgrade_evidence_manifest.build_evidence_manifest(
                        source_roots,
                        checkpoint_path=(attempt_root / "source-evidence-manifest.checkpoint.json"),
                        secret_env_names=_secret_environment_names(),
                    )
                except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
                    raise ConfigurationError(str(error)) from error
                _write_or_verify_json(local_manifest_path, source_manifest)
                scan = dict(source_manifest["scan"])
            try:
                boundary = codex_upgrade_evidence_manifest.verify_manifest_boundary(
                    source_manifest,
                    source_roots,
                )
            except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
                raise ConfigurationError(str(error)) from error
            if scan["full_scan_count"] == 0:
                scan["reused_bytes"] = int(source_manifest["total_bytes"])
                scan["total_bytes"] = int(source_manifest["total_bytes"])
            return {
                "schema_version": "codex-upgrade-deep-verify-result/v1",
                "status": "passed",
                "campaign_id": manifest["campaign_id"],
                "candidate_id": candidate_id,
                "attempt_id": attempt_id,
                "source_evidence_manifest": {
                    "path": str(selected_path),
                    "sha256": file_sha256(selected_path),
                    "manifest_digest": source_manifest["manifest_digest"],
                },
                "boundary": boundary,
                **scan,
            }
    else:
        _verify_plan_identity(campaign_dir, manifest)

    cache: dict[tuple[str, str, str | None], dict[str, Any]] = {}
    rows: list[dict[str, Any]] = []
    for canonical in ("capture-official", "classify"):
        try:
            local = _load_stage_result(
                campaign_dir,
                canonical,
                _replay_machine_receipts=False,
                _shallow=True,
            )
        except ConfigurationError as error:
            if "尚未封存" in str(error):
                continue
            raise
        if local.get("predecessor_import") is None:
            if canonical == "capture-official" and local.get("evidence_manifest") is not None:
                manifest_path = _campaign_file(
                    campaign_dir,
                    str(local["evidence_manifest"]["path"]),
                )
                evidence_manifest = _load_evidence_manifest(manifest_path)
                _, scanner_checkpoint = _verification_manifest_paths(
                    campaign_dir,
                    canonical,
                    None,
                )
                try:
                    scan = codex_upgrade_evidence_manifest.deep_verify_manifest(
                        evidence_manifest,
                        [Path(value) for value in local["evidence_roots"]],
                        checkpoint_path=scanner_checkpoint,
                        secret_env_names=_secret_environment_names(),
                    )
                except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
                    raise ConfigurationError(str(error)) from error
                receipt = _write_deep_verify_receipt(
                    campaign_dir,
                    canonical,
                    None,
                    stage_path=campaign_dir / "official" / "result.json",
                    evidence_manifest_binding=local["evidence_manifest"],
                    imported_checkpoint=None,
                    scan=scan,
                    evaluation_transition=evaluation_transition,
                )
                rows.append({"stage": canonical, "receipt_digest": receipt["receipt_digest"], **scan})
            continue
        projected = _load_stage_result(
            campaign_dir,
            canonical,
            _replay_machine_receipts=False,
            _ignore_checkpoint=True,
            _import_cache=cache,
            _skip_evidence_scan=True,
        )
        evidence_manifest: dict[str, Any] | None = None
        if canonical == "capture-official":
            if projected.get("evidence_manifest") is None:
                projected, evidence_manifest = _materialize_stage_evidence_manifest(
                    campaign_dir,
                    canonical,
                    None,
                    projected,
                )
            else:
                evidence_manifest = _stage_evidence_manifest(
                    campaign_dir,
                    projected,
                    verify_boundary=True,
                )
        checkpoint_path = _write_imported_stage_checkpoint(
            campaign_dir,
            canonical,
            None,
            local,
            projected,
        )
        scan = (
            evidence_manifest["scan"]
            if evidence_manifest is not None
            else {
                "full_scan_count": 0,
                "scanned_bytes": 0,
                "reused_bytes": 0,
                "total_bytes": 0,
                "elapsed_seconds": 0.0,
            }
        )
        stage_path = (
            campaign_dir / "official" / "result.json"
            if canonical == "capture-official"
            else campaign_dir / "classification" / "result.json"
        )
        receipt = _write_deep_verify_receipt(
            campaign_dir,
            canonical,
            None,
            stage_path=stage_path,
            evidence_manifest_binding=projected.get("evidence_manifest"),
            imported_checkpoint=checkpoint_path,
            scan=scan,
            evaluation_transition=evaluation_transition,
        )
        rows.append(
            {
                "stage": canonical,
                "receipt_digest": receipt["receipt_digest"],
                **scan,
            }
        )

    if candidate_id is not None:
        candidate_path = campaign_dir / "candidates" / candidate_id / "result.json"
        if candidate_path.is_file() and not candidate_path.is_symlink():
            candidate = _load_stage_result(
                campaign_dir,
                "capture-candidate",
                candidate_id,
                _replay_machine_receipts=False,
                _skip_evidence_scan=True,
            )
            binding = candidate.get("evidence_manifest")
            _require_file_binding(binding, "candidate EvidenceManifest")
            evidence_manifest_path = _campaign_file(
                campaign_dir,
                str(binding["path"]),
            )
            evidence_manifest = _load_evidence_manifest(evidence_manifest_path)
            _, scanner_checkpoint = _verification_manifest_paths(
                campaign_dir,
                "capture-candidate",
                candidate_id,
            )
            try:
                scan = codex_upgrade_evidence_manifest.deep_verify_manifest(
                    evidence_manifest,
                    [Path(value) for value in candidate["evidence_roots"]],
                    checkpoint_path=scanner_checkpoint,
                    secret_env_names=_secret_environment_names(),
                )
            except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
                raise ConfigurationError(str(error)) from error
            receipt = _write_deep_verify_receipt(
                campaign_dir,
                "capture-candidate",
                candidate_id,
                stage_path=candidate_path,
                evidence_manifest_binding=binding,
                imported_checkpoint=None,
                scan=scan,
                evaluation_transition=evaluation_transition,
            )
            rows.append(
                {
                    "stage": "capture-candidate",
                    "candidate_id": candidate_id,
                    "receipt_digest": receipt["receipt_digest"],
                    **scan,
                }
            )
    return {
        "schema_version": "codex-upgrade-deep-verify-result/v1",
        "status": "passed",
        "campaign_id": manifest["campaign_id"],
        "candidate_id": candidate_id,
        "stages": rows,
        "full_scan_count": sum(int(row.get("full_scan_count", 0)) for row in rows),
        "scanned_bytes": sum(int(row.get("scanned_bytes", 0)) for row in rows),
        "reused_bytes": sum(int(row.get("reused_bytes", 0)) for row in rows),
        "total_bytes": sum(int(row.get("total_bytes", 0)) for row in rows),
    }


def _seal_preview(
    campaign_dir: Path,
    attempt_root: Path,
    *,
    phase: str,
    candidate_id: str | None,
    attempt: dict[str, Any],
    stage_payload: dict[str, Any],
    approve_sha256: str | None,
) -> tuple[dict[str, Any], bool]:
    """生成或复核 seal 预览；人工只批准机器事实联合摘要。"""

    transition_index = _seal_transition_index(
        stage_payload.get("evaluation_transition")
    )
    draft_path = _seal_draft_path(attempt_root, transition_index)
    preview_path = _seal_preview_path(attempt_root, transition_index)
    evidence_manifest = stage_payload.get("evidence_manifest")
    preview_schema = (
        SEAL_PREVIEW_SCHEMA
        if isinstance(evidence_manifest, dict)
        else LEGACY_SEAL_PREVIEW_SCHEMA
    )
    core = {
        "schema_version": preview_schema,
        "campaign_id": attempt["campaign_id"],
        "campaign_mode": attempt["campaign_mode"],
        "campaign_purpose": attempt["campaign_purpose"],
        "phase": phase,
        "candidate_id": candidate_id,
        "candidate_purpose": attempt["candidate_purpose"],
        "attempt_id": attempt["attempt_id"],
        "attempt_digest": attempt["attempt_digest"],
        "stage_payload_sha256": _fingerprint(stage_payload),
        "evidence_inventory_digest": stage_payload["evidence_inventory"]["digest"],
        "assertion_manifest_sha256": stage_payload["assertion_context"][
            "capture_manifest"
        ]["sha256"],
        "restoration_report_sha256": stage_payload["restoration"]["report"][
            "sha256"
        ],
    }
    if preview_schema == SEAL_PREVIEW_SCHEMA:
        manifest = _stage_evidence_manifest(
            campaign_dir,
            stage_payload,
            verify_boundary=True,
        )
        draft = _seal_draft(
            campaign_dir,
            attempt_root,
            phase=phase,
            candidate_id=candidate_id,
            attempt=attempt,
            stage_payload=stage_payload,
        )
        core.update(
            {
                "evidence_manifest_sha256": evidence_manifest["sha256"],
                "evidence_manifest_digest": manifest["manifest_digest"],
                "seal_draft_sha256": file_sha256(draft_path),
                "scan_summary": stage_payload["scan_summary"],
            }
        )
    if phase == "candidate":
        core["post_client_restoration_sha256"] = stage_payload["restoration"][
            "post_client"
        ]["report"]["sha256"]
        core["observed_profile_sha256"] = stage_payload["observed_profile"][
            "sha256"
        ]
        core["client_receipt_sha256"] = {
            item["client_id"]: item["receipt"]["sha256"]
            for item in stage_payload["client_bindings"]
        }
    review_sha256 = _fingerprint(core)
    preview = {
        **core,
        "status": "approval_required",
        "review_sha256": review_sha256,
    }
    _write_or_verify_json(preview_path, preview)
    if approve_sha256 is None:
        return preview, False
    if not SHA256_RE.fullmatch(approve_sha256):
        raise ConfigurationError("--approve-seal-sha256 格式非法。")
    if approve_sha256 != review_sha256:
        raise ConfigurationError("seal 批准摘要与当前机器事实不一致。")
    if preview_path.is_symlink() or not preview_path.is_file():
        raise ConfigurationError("seal 预览路径不可信。")
    return preview, True


def _run_capture_attempt(
    arguments: argparse.Namespace,
    phase: str,
    *,
    _lease: CampaignLease | None = None,
    _manifest: dict[str, Any] | None = None,
    _deadline: incremental_recovery.WallClockDeadline | None = None,
) -> dict[str, Any]:
    """执行真实抓包，并以独立前后探针自动证明环境恢复。"""

    # main/resume 已经取得 Campaign lease 时，递归入口必须复用同一 owner；
    # 再次 acquire 会在同一进程内触发 flock 死锁/误报，并破坏单一 deadline。
    if _lease is None and _ACTIVE_CAMPAIGN_LEASE is not None:
        active = _ACTIVE_CAMPAIGN_LEASE
        expected_candidate = (
            str(getattr(arguments, "candidate_id", ""))
            if phase == "candidate"
            else None
        )
        if not _lease_identity_matches(
            active,
            arguments.campaign_dir,
            phase=phase,
            candidate_id=expected_candidate,
        ):
            raise ConfigurationError(
                "capture attempt 与当前 Campaign lease 的 phase／candidate 不一致。"
            )
        _lease = active
        _manifest = _manifest or _require_formal_campaign(arguments.campaign_dir)
        _deadline = _deadline or active.deadline

    # 用递归的一层 wrapper 保证整个 CLI invocation（包括计划、reservation、探针、
    # Job、清理和收据写入）都处于同一个 Campaign lease；无需把数百行主体再缩进，
    # 也不会因中途 return/no-op 漏掉释放。强制终止时 wrapper 不会运行，留下的
    # active lease 由下一次命令按 owner PID、heartbeat 和 deadline 判定 stale。
    if _lease is None:
        manifest = _manifest or _require_formal_campaign(arguments.campaign_dir)
        deadline = _deadline or _attempt_deadline(arguments, phase)
        with CampaignLease(
            arguments.campaign_dir,
            phase=phase,
            candidate_id=(
                str(getattr(arguments, "candidate_id", ""))
                if phase == "candidate"
                else None
            ),
            deadline=deadline,
            command=f"capture-{phase}",
            allow_stale_recovery=bool(getattr(arguments, "rerun_failed", False)),
            campaign_id=str(manifest.get("campaign_id", "")),
        ) as lease:
            return _run_capture_attempt(
                arguments,
                phase,
                _lease=lease,
                _manifest=manifest,
                _deadline=deadline,
            )

    manifest = _manifest or _require_formal_campaign(arguments.campaign_dir)
    if phase == "candidate":
        # 候选层运行坐标覆盖在这里一次性生效；后续 Job 模板、环境探针、二进制
        # 校验和容器身份都只读这份副本，run 与 seal 因此看到同一组坐标。
        manifest = _apply_candidate_runtime_override(
            arguments.campaign_dir,
            manifest,
            str(getattr(arguments, "candidate_id", "") or ""),
        )
    _reject_contaminated_campaign(arguments.campaign_dir)
    deadline = _deadline or _attempt_deadline(arguments, phase)
    seal_only = {
        "attempt_id": getattr(arguments, "attempt_id", None),
        "capture_manifest": getattr(arguments, "capture_manifest", None),
        "assertion_evidence_root": getattr(
            arguments, "assertion_evidence_root", None
        ),
        "restoration_report": getattr(arguments, "restoration_report", None),
        "evidence_root": getattr(arguments, "evidence_root", []),
        "approve_seal_sha256": getattr(
            arguments, "approve_seal_sha256", None
        ),
        "observed_profile_receipt": getattr(
            arguments, "observed_profile_receipt", None
        ),
        "client_evidence": getattr(arguments, "client_evidence", []),
    }
    unexpected = sorted(name for name, value in seal_only.items() if value)
    if unexpected:
        raise ConfigurationError(
            f"run 不读取 seal 收据参数，请在 seal 阶段提供：{unexpected}"
        )
    campaign_dir = arguments.campaign_dir
    candidate_id: str | None = None
    identity: dict[str, Any]
    classification: dict[str, Any] | None = None
    classification_candidate_reuse_context: dict[str, Any] | None = None
    classification_candidate_reuse_transition: dict[str, Any] | None = None
    classification_candidate_reuse_transition_binding: dict[str, Any] | None = None
    if phase == "official":
        try:
            _load_stage_result(campaign_dir, "capture-official")
        except ConfigurationError as error:
            if "尚未封存" not in str(error):
                raise
        else:
            raise ConfigurationError("官方证据已经封存，禁止重复抓包。")
        active_attempts = _active_unsealed_attempts(campaign_dir, "official")
        if active_attempts:
            raise ConfigurationError(
                f"官方存在待封存 attempt，禁止再次 run：{active_attempts}"
            )
        jobs = _campaign_jobs(campaign_dir, manifest, "official")
        attempt_relative = _capture_attempt_relative("official", None)
        # 官方二进制验证属于真实执行前提；增量计划为空时不能触发该探针。
        binary_verification = None
        identity = dict(manifest["official_identity"])
    else:
        classification = _load_stage_result(campaign_dir, "classify")
        if classification.get("status") != "complete":
            raise ConfigurationError("目标画像尚未批准，禁止候选抓包。")
        candidate_id = arguments.candidate_id
        if not SAFE_ID_RE.fullmatch(candidate_id):
            raise ConfigurationError("--candidate-id 格式非法。")
        _, candidate_result_path = _stage_path(
            campaign_dir, "capture-candidate", candidate_id
        )
        if candidate_result_path.exists():
            raise ConfigurationError("candidate-id 已封存，必须使用新编号。")
        active_attempts = _active_unsealed_attempts(campaign_dir, "candidate")
        if active_attempts:
            raise ConfigurationError(
                "Campaign 存在待封存候选 attempt，必须先完成其 Kilo 后恢复与 seal："
                f"{active_attempts}"
            )
        classification_candidate_reuse_context = (
            _classification_candidate_reuse_source(
                arguments,
                campaign_dir,
                manifest,
                classification,
                candidate_id=candidate_id,
            )
        )
        # 失败重跑先尝试从前序 attempt 读取候选身份。这样只为判断增量执行集合，
        # 不会调用 Docker；真正仍有 Job 要执行时才重验运行容器。
        identity_hint = (
            classification_candidate_reuse_context["identity"]
            if classification_candidate_reuse_context is not None
            else None
        )
        if (
            identity_hint is None
            and getattr(arguments, "rerun_failed", False)
            and not getattr(arguments, "candidate_image_id", None)
        ):
            identity_hint = _latest_failed_attempt_identity_hint(
                campaign_dir,
                phase="candidate",
                candidate_id=candidate_id,
            )
        identity = _candidate_identity_for_run(
            arguments,
            manifest,
            classification,
            verify_image=not bool(getattr(arguments, "rerun_failed", False)),
            image_id_override=(
                identity_hint.get("image_id")
                if isinstance(identity_hint, Mapping)
                else None
            ),
            source_tree_sha256_override=(
                identity_hint.get("source_tree_sha256")
                if isinstance(identity_hint, Mapping)
                else None
            ),
            git_commit_override=(
                identity_hint.get("git_commit")
                if isinstance(identity_hint, Mapping)
                else None
            ),
            deadline=deadline,
            heartbeat=None,
        )
        if identity_hint is not None:
            # 用户显式传入的坐标必须与前序失败 attempt 完全一致；否则不能把
            # 新候选身份伪装成同一轮的恢复。
            for key in (
                "image_reference",
                "image_id",
                "source_tree_sha256",
                "build_id",
                "deployed_version",
                "profile_id",
                "profile_digest",
                "candidate_purpose",
            ):
                if key in identity_hint and identity.get(key) != identity_hint.get(key):
                    raise ConfigurationError(
                        f"候选失败重跑身份与前序 attempt 不一致：{key}"
                    )
        jobs = _campaign_jobs(
            campaign_dir,
            manifest,
            "candidate",
            candidate_id=candidate_id,
            runtime_image=identity["image_reference"],
            profile_id=identity["profile_id"],
            profile_digest=identity["profile_digest"],
            build_id=identity["build_id"],
            deployed_version=identity["deployed_version"],
            candidate_image_id=identity["image_id"],
            source_tree_sha256=identity["source_tree_sha256"],
            candidate_purpose=identity["candidate_purpose"],
        )
        attempt_relative = _capture_attempt_relative("candidate", candidate_id)
        binary_verification = None

    planned_jobs = list(jobs)
    # 这里只读取受管工具树并计算组件摘要。所有可能触碰 Docker、官方二进制、
    # bubblewrap、环境探针或 live 请求的操作都必须晚于增量空集判断。
    tool_identity = _tool_identity(include_git=False)
    cheap_impact = _cheap_capture_tool_impact(
        manifest, planned_jobs, tool_identity
    )
    if cheap_impact.get("kind") == "unmapped_production_paths":
        raise ConfigurationError(
            "产出侧工具变化缺少逐文件 Job 依赖映射："
            + "、".join(cheap_impact.get("unmapped_production_paths", []))
            + "；禁止退化为全量重跑。"
        )
    affected_job_ids = set(
        str(item) for item in cheap_impact.get("affected_job_ids", [])
    )
    changed_components = set(
        str(item) for item in cheap_impact.get("changed_components", [])
    )
    prior_results: list[dict[str, Any]] = []
    recovery_source_root: Path | None = None
    recovery_source_attempt: dict[str, Any] | None = None
    recovery_source_campaign_dir: Path | None = None
    recovery_source_candidate_id: str | None = None
    recovery_source_receipt: Mapping[str, Any] | None = None
    runtime_successor_recovery: dict[str, Any] | None = None
    recovery_scope: dict[str, Any] | None = None
    recovery_completed_ids: set[str] | None = None
    recovery_execute_ids: set[str] | None = None
    phase_recovery_high_risk_paths: set[str] = set()
    if classification_candidate_reuse_context is not None:
        preview, _ = _build_classification_candidate_reuse_preview(
            campaign_dir,
            manifest,
            candidate_id=str(candidate_id),
            identity=identity,
            planned_jobs=planned_jobs,
            current_tool=tool_identity,
            context=classification_candidate_reuse_context,
        )
        if getattr(arguments, "preview_recovery", False):
            return preview
        (
            classification_candidate_reuse_transition,
            classification_candidate_reuse_transition_binding,
            recovery_source_receipt,
        ) = _approve_classification_candidate_reuse_transition(
            campaign_dir,
            preview,
            getattr(arguments, "approve_candidate_reuse_sha256", None),
        )
        recovery_source_root = classification_candidate_reuse_context[
            "source_root"
        ]
        recovery_source_attempt = classification_candidate_reuse_context[
            "source_attempt"
        ]
        recovery_source_campaign_dir = classification_candidate_reuse_context[
            "source_campaign_dir"
        ]
        recovery_source_candidate_id = str(
            classification_candidate_reuse_context["source_candidate_id"]
        )
        recovery_completed_ids = set(CLASSIFICATION_CANDIDATE_REUSE_JOB_IDS)
        recovery_execute_ids = set()
        prior_results = _prior_complete_results(
            campaign_dir,
            attempt_relative,
            jobs,
            phase=phase,
            candidate_id=candidate_id,
            identity=identity,
            tool_identity=tool_identity,
            affected_job_ids=(),
            expected_reuse_job_ids=recovery_completed_ids,
            source_attempt_id=str(
                classification_candidate_reuse_context["source_attempt_id"]
            ),
            source_campaign_dir=recovery_source_campaign_dir,
            source_candidate_id=recovery_source_candidate_id,
            source_receipt_binding=recovery_source_receipt,
            allowed_high_risk_path_changes=(),
            allowed_source_statuses=("awaiting_receipts",),
            source_tool_identity=(
                _classification_candidate_reuse_source_tool_identity(
                    recovery_source_attempt,
                    classification_candidate_reuse_context["source_manifest"],
                )
            ),
        )
        if {str(item.get("id")) for item in prior_results} != recovery_completed_ids:
            raise ConfigurationError("分类 Candidate 复用未完整承接固定九项 Job。")
        jobs = []
        affected_job_ids = set()
    if (
        getattr(arguments, "rerun_failed", False)
        and classification_candidate_reuse_context is None
    ):
        source = _latest_failed_attempt_for_identity(
            campaign_dir,
            phase=phase,
            candidate_id=candidate_id,
            identity=identity,
        )
        if source is None and phase == "candidate" and candidate_id is not None:
            runtime_successor_recovery = _runtime_successor_recovery_source(
                campaign_dir,
                manifest,
                classification or {},
                candidate_id=candidate_id,
                identity=identity,
                planned_jobs=planned_jobs,
            )
            if runtime_successor_recovery is not None:
                source = (
                    runtime_successor_recovery["source_root"],
                    runtime_successor_recovery["source_attempt"],
                )
                recovery_source_campaign_dir = runtime_successor_recovery[
                    "source_campaign_dir"
                ]
                recovery_source_candidate_id = runtime_successor_recovery[
                    "source_candidate_id"
                ]
                recovery_source_receipt = runtime_successor_recovery[
                    "source_receipt"
                ]
        if source is None:
            # 显式 rerun 只能承接一个可验证的失败源；没有源时禁止回退到
            # 当前计划或全量 Job，避免“失败项为空”被误解释成重新抓包。
            raise ConfigurationError(
                "resume --rerun-failed 没有唯一可验证的失败源 attempt；"
                "禁止重新计算执行集合或全量重跑。"
            )
        if source is not None:
            recovery_source_root, recovery_source_attempt = source
            if runtime_successor_recovery is not None:
                recovery_scope = runtime_successor_recovery["scope"]
                recovery_completed_ids = set(
                    recovery_scope["completed_job_ids"]
                )
                recovery_execute_ids = set(recovery_scope["execute_job_ids"])
                # runtime successor 的冻结 scope 是唯一执行事实源；粗粒度组件
                # 摘要只能提示审计，不能把已通过 Job 再并回执行集合。
                affected_job_ids = set(recovery_scope["changed_job_ids"])
                changed_components.add("scenario")
            else:
                # 先读取源 attempt 的冻结闭集，再做任何当前工具摘要驱动的
                # 计划过滤。后续执行集合只能来自这份 scope。
                allow_awaiting_failures = (
                    recovery_source_attempt.get("status") == "awaiting_receipts"
                )
                recovery_scope = _phase_evaluation_recovery_scope(
                    campaign_dir,
                    manifest,
                    phase=phase,
                    candidate_id=candidate_id,
                    attempt_root=recovery_source_root,
                    attempt=recovery_source_attempt,
                    allow_awaiting_failures=allow_awaiting_failures,
                )
                (
                    recovery_completed_ids,
                    recovery_execute_ids,
                ) = _validate_recovery_scope_plan(
                    campaign_dir,
                    phase=phase,
                    candidate_id=candidate_id,
                    source_root=recovery_source_root,
                    scope=recovery_scope,
                    planned_jobs=planned_jobs,
                    allow_empty=True,
                )
                if recovery_execute_ids:
                    phase_recovery_high_risk_paths = (
                        _authorize_phase_recovery_production_paths(
                            campaign_dir,
                            manifest,
                            phase=phase,
                            candidate_id=candidate_id,
                            attempt_root=recovery_source_root,
                            attempt=recovery_source_attempt,
                            current_tool=tool_identity,
                            recovery_scope=recovery_scope,
                        )
                    )
                    # transition 已逐文件批准产出变化后，必须丢弃此前由 relay／
                    # shared 组件推导的粗粒度集合。继续取并集会把已通过 Job
                    # 错误带入恢复闭集，造成无意义的 Formal Campaign 重建。
                    affected_job_ids = _phase_recovery_exact_affected_job_ids(
                        phase_recovery_high_risk_paths,
                        planned_job_ids=(job.job_id for job in planned_jobs),
                        recovery_scope=recovery_scope,
                    )
                else:
                    # 冻结执行闭集为空时不得加载工具 transition；继续做工具
                    # 身份分级既没有执行对象，也会违反 reservation 前立即退出。
                    phase_recovery_high_risk_paths = set()
                    affected_job_ids = set()
        prior_results = _prior_complete_results(
            campaign_dir,
            attempt_relative,
            jobs,
            phase=phase,
            candidate_id=candidate_id,
            identity=identity,
            tool_identity=tool_identity,
            affected_job_ids=affected_job_ids,
            expected_reuse_job_ids=recovery_completed_ids,
            source_attempt_id=(
                recovery_source_root.name if recovery_source_root is not None else None
            ),
            source_campaign_dir=recovery_source_campaign_dir,
            source_candidate_id=recovery_source_candidate_id,
            source_receipt_binding=recovery_source_receipt,
            allowed_high_risk_path_changes=(
                runtime_successor_recovery[
                    "allowed_high_risk_path_changes"
                ]
                if runtime_successor_recovery is not None
                else phase_recovery_high_risk_paths
            ),
            validated_current_production_sha256=(
                runtime_successor_recovery.get(
                    "validated_current_production_sha256"
                )
                if runtime_successor_recovery is not None
                else None
            ),
            allowed_source_statuses=(
                runtime_successor_recovery["allowed_source_statuses"]
                if runtime_successor_recovery is not None
                else (
                    ("failed", "awaiting_receipts")
                    if recovery_source_attempt is not None
                    and recovery_source_attempt.get("status")
                    == "awaiting_receipts"
                    else ("failed",)
                )
            ),
        )
        completed_ids = {item["id"] for item in prior_results}
        if recovery_completed_ids is not None:
            if completed_ids != recovery_completed_ids:
                raise ConfigurationError(
                    "恢复 transition 的已完成 Job 未被完整只读承接。"
                )
            assert recovery_execute_ids is not None
            jobs = [job for job in planned_jobs if job.job_id in recovery_execute_ids]
        else:
            jobs = [job for job in jobs if job.job_id not in completed_ids]
        if not jobs and getattr(arguments, "preview_recovery", False):
            invalidation = _capture_invalidation_summary(
                invalidated_job_ids=(),
                reused_receipt_ids=(
                    str(item.get("id")) for item in prior_results
                ),
                changed_control_paths=(
                    runtime_successor_recovery.get("changed_control_paths", [])
                    if runtime_successor_recovery is not None
                    else ()
                ),
                changed_environment_paths=(
                    runtime_successor_recovery.get(
                        "changed_environment_paths", []
                    )
                    if runtime_successor_recovery is not None
                    else ()
                ),
            )
            return {
                "status": "recovery_plan",
                "phase": phase,
                "candidate_id": candidate_id,
                "planned_job_ids": sorted(job.job_id for job in planned_jobs),
                "execute_job_ids": [],
                "reused_job_ids": sorted(
                    str(item.get("id")) for item in prior_results
                ),
                "affected_job_ids": [],
                "failed_job_ids": [],
                "reservation_exists": False,
                "live_request_count": 0,
                "scanned_bytes": 0,
                **invalidation,
            }
        if not jobs:
            # 失败项为空时必须在 reservation 前结束；这条路径不要求 live
            # acknowledgement，也不创建 attempt／容器探针／环境快照。
            return _write_incremental_noop_receipt(
                campaign_dir,
                manifest,
                phase=phase,
                candidate_id=candidate_id,
                identity=identity,
                planned_job_ids=[job.job_id for job in planned_jobs],
                reused_results=prior_results,
                changed_components=changed_components,
                affected_job_ids=(),
                tool_identity=tool_identity,
                deadline=deadline,
            )

    if classification_candidate_reuse_context is not None and jobs:
        raise ConfigurationError("分类 Candidate 复用不得退化为任何 Job 执行。")

    # recovery_scope 已冻结执行闭集。廉价影响分析只能作为审计提示，不能
    # 把已通过 Job 偷偷扩大进本轮；若产出侧变化确实越过闭集，直接停线，
    # 评估侧变化则交给后面的 transition 校验处理。空集合已经在上面
    # incremental-noop 短路，因此不会被这条保护误拦截。
    if recovery_scope is not None and affected_job_ids:
        execute_scope = recovery_execute_ids or set()
        if not affected_job_ids.issubset(execute_scope):
            raise ConfigurationError(
                "恢复 transition 与工具变化闭集相冲突；请建立新的 Formal Campaign。"
            )

    # 从这里开始确实存在需要执行的 Job，才允许进入昂贵前置检查。
    # 完整计划身份校验必须先于任何 Docker／二进制检查。它会验证 package、
    # 控制收据和工具 transition；若恢复闭集发生漂移，必须在 reservation、
    # 容器和首个请求之前立即停线。该调用仍位于 no-op 之后，空执行集合不会
    # 触发完整身份校验。
    tool_impact = (
        cheap_impact
        if classification_candidate_reuse_context is not None
        else _verify_plan_identity(
            campaign_dir,
            manifest,
            operation="capture-run",
            attempt_root=recovery_source_root,
            attempt=recovery_source_attempt,
            deadline=deadline,
        )
    )
    evaluation_transition: dict[str, str] | None = None
    if isinstance(tool_impact, Mapping):
        changed_components.update(
            str(item) for item in tool_impact.get("changed_components", [])
        )
        affected_job_ids.update(
            str(item) for item in tool_impact.get("affected_job_ids", [])
        )
        if recovery_scope is not None:
            frozen_execute = recovery_execute_ids or set()
            if not affected_job_ids.issubset(frozen_execute):
                raise ConfigurationError(
                    "恢复 transition 的工具影响闭集超出冻结 recovery_scope；"
                    "不得扩大执行集合。"
                )
        if tool_impact.get("kind") == "component_drift":
            affected_job_ids.update(
                _affected_job_ids(
                    planned_jobs,
                    tool_impact.get("changed_components", []),
                )
            )
        if tool_impact.get("kind") == "phase_evaluation_transition":
            bound = tool_impact.get("evaluation_transition")
            if not isinstance(bound, Mapping):
                raise ConfigurationError("恢复 transition 缺少受控文件绑定。")
            evaluation_transition = {
                "path": str(bound.get("path", "")),
                "sha256": str(bound.get("sha256", "")),
            }
            _require_file_binding(evaluation_transition, "恢复评估工具 transition")
            scope = tool_impact.get("recovery_scope")
            if not isinstance(scope, Mapping):
                raise ConfigurationError("恢复 transition 缺少失败 Job 闭集。")
            if recovery_scope is not None and _fingerprint(dict(scope)) != _fingerprint(
                recovery_scope
            ):
                raise ConfigurationError("恢复 transition 的闭集在计划阶段发生漂移。")
            expected_execute = {
                str(item) for item in scope.get("execute_job_ids", [])
            }
            actual_execute = {job.job_id for job in jobs}
            if actual_execute != expected_execute:
                raise ConfigurationError(
                    "恢复 transition 的失败 Job 闭集与本轮计划不一致："
                    f"expected={sorted(expected_execute)}, actual={sorted(actual_execute)}"
                )
            reused_ids = {str(item.get("id")) for item in prior_results}
            expected_completed = {
                str(item) for item in scope.get("completed_job_ids", [])
            }
            if reused_ids != expected_completed:
                raise ConfigurationError(
                    "恢复 transition 的已完成 Job 未被完整只读承接。"
                )
    else:
        tool_impact = cheap_impact
    if recovery_scope is not None:
        # 即使当前工具没有产生 transition（例如只读重放同一摘要），也
        # 必须再次确认真正进入执行循环的集合没有被任何后续逻辑改写。
        assert recovery_execute_ids is not None
        assert recovery_completed_ids is not None
        if {job.job_id for job in jobs} != recovery_execute_ids:
            raise ConfigurationError("恢复执行集合偏离源 transition scope。")
        if {str(item.get("id")) for item in prior_results} != recovery_completed_ids:
            raise ConfigurationError("恢复复用集合偏离源 transition scope。")
    if getattr(arguments, "preview_recovery", False):
        if not getattr(arguments, "rerun_failed", False):
            raise ConfigurationError("--preview-recovery 必须与 --rerun-failed 同时使用。")
        invalidation = _capture_invalidation_summary(
            invalidated_job_ids=(job.job_id for job in jobs),
            reused_receipt_ids=(
                str(item.get("id")) for item in prior_results
            ),
            changed_control_paths=(
                runtime_successor_recovery.get("changed_control_paths", [])
                if runtime_successor_recovery is not None
                else ()
            ),
            changed_environment_paths=(
                runtime_successor_recovery.get("changed_environment_paths", [])
                if runtime_successor_recovery is not None
                else ()
            ),
        )
        return {
            "status": "recovery_plan",
            "phase": phase,
            "candidate_id": candidate_id,
            "planned_job_ids": sorted(job.job_id for job in planned_jobs),
            "execute_job_ids": sorted(job.job_id for job in jobs),
            "reused_job_ids": sorted(
                str(item.get("id")) for item in prior_results
            ),
            "affected_job_ids": sorted(affected_job_ids),
            "failed_job_ids": sorted(
                str(item)
                for item in (recovery_scope or {}).get("failed_job_ids", [])
            ),
            "reservation_exists": False,
            "live_request_count": 0,
            "scanned_bytes": 0,
            **invalidation,
        }
    if (
        classification_candidate_reuse_context is None
        and not getattr(arguments, "acknowledge_live_requests", False)
    ):
        raise ConfigurationError(
            "抓包会产生真实请求，必须同时确认 --acknowledge-live-requests。"
        )
    incremental_transition: dict[str, Any] | None = None
    if (
        isinstance(tool_impact, Mapping)
        and tool_impact.get("kind") in {
            "component_drift",
            "phase_evaluation_transition",
        }
        and set(str(item) for item in tool_impact.get("changed_components", []))
        .issubset({"orchestrator", "evaluator"})
    ):
        impact_for_transition = dict(tool_impact)
        impact_for_transition["affected_job_ids"] = sorted(affected_job_ids)
        incremental_transition = _build_incremental_tool_transition(
            manifest.get("tool_identity", {}),
            tool_identity,
            impact_for_transition,
            phase=phase,
            planned_job_ids=[job.job_id for job in planned_jobs],
        )

    if (
        phase == "candidate"
        and getattr(arguments, "rerun_failed", False)
        and classification_candidate_reuse_context is None
    ):
        # 计划阶段故意不触碰 Docker；只有 scope 与 transition 完全一致后，
        # 才冻结并重验当前运行容器身份。任何漂移都停线，不得混入旧 attempt。
        verified_identity = _candidate_identity_for_run(
            arguments,
            manifest,
            classification or {},
            verify_image=True,
            source_tree_sha256_override=(
                str(classification_candidate_reuse_context["identity"][
                    "source_tree_sha256"
                ])
                if classification_candidate_reuse_context is not None
                else None
            ),
            git_commit_override=(
                str(classification_candidate_reuse_context["identity"]["git_commit"])
                if classification_candidate_reuse_context is not None
                else None
            ),
            deadline=deadline,
        )
        if verified_identity != identity:
            raise ConfigurationError("候选运行身份在增量计划与执行前校验之间发生漂移。")
    # 采集脚本与 relay 从 capture_root 下的副本执行，不是本文件所在的受管树；
    # 该校验同样不能在 no-op 路径触发。它现在也位于 transition 闭集校验之后。
    if classification_candidate_reuse_context is None:
        _verify_execution_tree(getattr(arguments, "capture_root", None))
    if phase == "official":
        binary_verification = _verify_official_binaries(
            manifest,
            deadline=deadline,
        )

    if phase == "candidate" and jobs:
        # 辅助场景排在多个耗时 Job 之后；凭据缺失或即将过期必须在 reservation
        # 和首个真实请求之前失败，不能等十几分钟后才发现。
        _validate_candidate_admin_credential(planned_jobs)

    attempt_root, reservation = _reserve_capture_attempt(
        campaign_dir,
        phase=phase,
        candidate_id=candidate_id,
        identity=identity,
        jobs=planned_jobs,
        allow_failed_rerun=bool(getattr(arguments, "rerun_failed", False)),
        deadline=deadline,
        lease=_lease,
    )
    log_root = ensure_private_directory(attempt_root / "logs", campaign_dir)
    evidence_root = ensure_private_directory(
        attempt_root / "evidence", campaign_dir
    )
    environment_root = ensure_private_directory(
        evidence_root / "environment", evidence_root
    )
    heartbeat_path = attempt_root / "watchdog-heartbeat.json"
    checkpoint_store: incremental_recovery.CheckpointStore | None = None
    setup_error: BaseException | None = None
    try:
        checkpoint_store = _job_checkpoint_store(attempt_root)
        _write_attempt_heartbeat(
            heartbeat_path,
            deadline,
            operation="attempt:reserved",
            force=True,
            attempt_root=attempt_root,
        )
        # 复用项也必须写入本 attempt 的 checkpoint，明确记录本轮没有重新
        # 发起请求；这样中断恢复只读取当前上下文链，不会把旧 attempt 的
        # 结果直接拼接成“本轮完成”。
        for reused_result in prior_results:
            if checkpoint_store is None:
                raise ConfigurationError("Job checkpoint 存储未初始化。")
            records = checkpoint_store.records()
            previous_checkpoint_sha256 = (
                records[-1].get("checkpoint_sha256") if records else None
            )
            checkpoint_store.append(
                {
                    "checkpoint_schema_version": JOB_CHECKPOINT_SCHEMA,
                    "campaign_id": manifest["campaign_id"],
                    "phase": phase,
                    "attempt_id": attempt_root.name,
                    "run_nonce": reservation["run_nonce"],
                    "item_id": reused_result.get("id"),
                    "status": "complete",
                    "disposition": "reused",
                    "result_sha256": incremental_recovery.digest(reused_result),
                    "result_key": reused_result.get("incremental_result_key"),
                    "result": reused_result,
                    "source_receipt": reused_result.get("source_receipt"),
                    "previous_checkpoint_sha256": previous_checkpoint_sha256,
                }
            )
        if binary_verification is not None:
            _secure_write_json_once(
                attempt_root / "official-binary-verification.json",
                binary_verification,
            )
    except BaseException as error:
        # watchdog／checkpoint 初始化失败不能留下一个看似可继续的 attempt；
        # 仍进入统一 after 清理，最终以 failed 停线。
        setup_error = error
    if classification_candidate_reuse_context is not None:
        if setup_error is not None:
            raise setup_error
        if checkpoint_store is None:
            raise ConfigurationError("metadata-only attempt 缺少 Job checkpoint 存储。")
        source_evidence_roots = recovery_source_attempt.get("evidence_roots") if isinstance(
            recovery_source_attempt, Mapping
        ) else None
        if (
            not isinstance(source_evidence_roots, list)
            or not source_evidence_roots
            or any(
                not isinstance(value, str) or not Path(value).is_absolute()
                for value in source_evidence_roots
            )
        ):
            raise ConfigurationError("metadata-only attempt 的来源证据根不完整。")
        _write_attempt_heartbeat(
            heartbeat_path,
            deadline,
            operation="attempt:metadata-only-complete",
            force=True,
            attempt_root=attempt_root,
        )
        checkpoint_records = checkpoint_store.records()
        checkpoint_summary = {
            "schema_version": JOB_CHECKPOINT_SCHEMA,
            "campaign_id": manifest["campaign_id"],
            "phase": phase,
            "attempt_id": attempt_root.name,
            "run_nonce": reservation["run_nonce"],
            "path": str(
                checkpoint_store.root.resolve(strict=True).relative_to(
                    campaign_dir.resolve(strict=True)
                )
            ),
            "record_count": len(checkpoint_records),
            "last_sequence": checkpoint_records[-1].get("checkpoint_sequence"),
            "last_sha256": checkpoint_records[-1].get("checkpoint_sha256"),
        }
        heartbeat_binding = {
            "path": str(heartbeat_path.relative_to(campaign_dir)),
            "sha256": file_sha256(heartbeat_path),
            "bytes": heartbeat_path.stat().st_size,
        }
        planned_ids = sorted(job.job_id for job in planned_jobs)
        reused_ids = sorted(str(item["id"]) for item in prior_results)
        plan_core = {
            "schema_version": incremental_recovery.SCHEMA_VERSION,
            "planned_job_ids": planned_ids,
            "changed_components": sorted(changed_components),
            "affected_job_ids": [],
            "reused_job_ids": reused_ids,
            "executed_job_ids": [],
            "failed_job_ids": [],
            "pending_job_ids": [],
        }
        metadata_evidence_roots = _deduplicate_evidence_roots(
            [
                *(Path(value) for value in source_evidence_roots),
                evidence_root,
            ],
            require_nonempty=True,
        )
        metadata_environment = {
            "evidence_root": str(evidence_root.resolve(strict=True)),
            "before_probe": None,
            "after_probe": None,
            "restoration_report": None,
            "arm64_before_receipt": None,
            "arm64_after_receipt": None,
        }
        metadata_attempt = _write_capture_attempt(
            campaign_dir,
            attempt_root,
            {
                "campaign_id": manifest["campaign_id"],
                "phase": phase,
                "candidate_id": candidate_id,
                "status": "awaiting_receipts",
                "tool_components": (
                    tool_identity.get("components")
                    if isinstance(tool_identity, Mapping)
                    else None
                ),
                "classification_candidate_reuse_transition": (
                    classification_candidate_reuse_transition_binding
                ),
                "incremental_plan": {
                    **plan_core,
                    "plan_sha256": incremental_recovery.digest(plan_core),
                },
                "identity": identity,
                "results": list(prior_results),
                "evidence_roots": [str(root) for root in metadata_evidence_roots],
                "environment": metadata_environment,
                "binary_verification": None,
                "watchdog": {
                    "schema_version": WATCHDOG_HEARTBEAT_SCHEMA,
                    "budget_seconds": deadline.budget_seconds,
                    "heartbeat_seconds": getattr(
                        deadline, "heartbeat_seconds", DEFAULT_HEARTBEAT_SECONDS
                    ),
                    "elapsed_seconds": round(deadline.elapsed_seconds, 3),
                    "remaining_seconds": round(deadline.remaining_seconds, 3),
                    "heartbeat": heartbeat_binding,
                    "timeout_checkpoint": None,
                    "last_completed_job_id": None,
                },
                "job_checkpoint": checkpoint_summary,
                "execution_error": None,
                "restoration_error": None,
                "next_gate": (
                    "仅补当前 metadata-only attempt 的运行画像、两种 Kilo 原始 "
                    "witness 与 seal；禁止重跑九项 Candidate Job。"
                ),
            },
        )
        return {
            "status": "awaiting_receipts",
            "phase": phase,
            "candidate_id": candidate_id,
            "attempt_id": attempt_root.name,
            "attempt": str(attempt_root),
            "attempt_digest": metadata_attempt["attempt_digest"],
            "run_nonce": reservation["run_nonce"],
            "started_at_utc": reservation["started_at_utc"],
            "environment": metadata_environment,
            "results": list(prior_results),
            "incremental_plan": metadata_attempt["incremental_plan"],
            "reservation_exists": True,
            "live_request_count": 0,
            "scanned_bytes": 0,
            "next_command": "生成运行画像和两份 Kilo 收据后执行 capture-candidate seal。",
        }
    results: list[dict[str, Any]] = list(prior_results)
    execution_error: BaseException | None = setup_error
    restoration_error: BaseException | None = None
    before_manifest: dict[str, Any] | None = None
    after_manifest: dict[str, Any] | None = None
    restoration_path: Path | None = None
    restoration_receipt: dict[str, Any] | None = None
    arm64_before_path: Path | None = None
    arm64_before_receipt: dict[str, Any] | None = None
    arm64_after_path: Path | None = None
    arm64_after_receipt: dict[str, Any] | None = None
    continuity: dict[str, Any] | None = None
    timeout_checkpoint_path: Path | None = None
    timeout_checkpoint_error: BaseException | None = None
    try:
        if setup_error is None:
            deadline.check("attempt:before")
            arm64_before_path, arm64_before_receipt = _invoke_with_optional_deadline(
                _capture_arm64_environment_receipt,
                environment_root / "arm64-before",
                phase="attempt_before",
                subject_id=attempt_root.name,
                deadline=deadline,
                heartbeat=lambda operation: _write_attempt_heartbeat(
                    heartbeat_path,
                    deadline,
                    operation=operation,
                    attempt_root=attempt_root,
                ),
            )
            deadline.check("attempt:before-probe")
            before_manifest = _invoke_with_optional_deadline(
                _probe_capture_environment,
                manifest,
                environment_root / "before",
                "before",
                deadline=deadline,
                heartbeat=lambda operation: _write_attempt_heartbeat(
                    heartbeat_path,
                    deadline,
                    operation=operation,
                    attempt_root=attempt_root,
                ),
            )
            deadline.check("attempt:continuity")
            continuity = _verify_environment_continuity(
                campaign_dir,
                attempt_relative,
                {
                    str(item.get("carried_from_attempt"))
                    for item in prior_results
                    if item.get("carried_from_attempt")
                },
                before_manifest,
                source_campaign_dir=recovery_source_campaign_dir,
                source_relative=(
                    _capture_attempt_relative(
                        "candidate", recovery_source_candidate_id
                    )
                    if recovery_source_campaign_dir is not None
                    and recovery_source_candidate_id is not None
                    else None
                ),
            )
            scenario_context = ScenarioReceiptContext(
                campaign_id=str(manifest["campaign_id"]),
                attempt_id=attempt_root.name,
                run_nonce=str(reservation["run_nonce"]),
                evidence_root=evidence_root,
                campaign_dir=campaign_dir,
            )
            for job in jobs:
                _write_attempt_heartbeat(
                    heartbeat_path,
                    deadline,
                    operation=f"job:{job.job_id}:start",
                    attempt_root=attempt_root,
                )
                result = _run_job_with_retry(
                    job,
                    log_root,
                    scenario_context,
                    identity=identity,
                    tool_identity=tool_identity,
                    deadline=deadline,
                    heartbeat=lambda operation: _write_attempt_heartbeat(
                        heartbeat_path,
                        deadline,
                        operation=operation,
                        attempt_root=attempt_root,
                    ),
                )
                results.append(result)
                if checkpoint_store is None:
                    raise ConfigurationError("Job checkpoint 存储未初始化。")
                records = checkpoint_store.records()
                previous_checkpoint_sha256 = (
                    records[-1].get("checkpoint_sha256") if records else None
                )
                checkpoint_store.append(
                    {
                        "checkpoint_schema_version": JOB_CHECKPOINT_SCHEMA,
                        "campaign_id": manifest["campaign_id"],
                        "phase": phase,
                        "attempt_id": attempt_root.name,
                        "run_nonce": reservation["run_nonce"],
                        "item_id": job.job_id,
                        "status": (
                            "complete"
                            if result.get("status") == "complete"
                            else "failed"
                        ),
                        "disposition": result.get("disposition", "executed"),
                        "result_sha256": incremental_recovery.digest(result),
                        "result_key": result.get("incremental_result_key"),
                        "result": result,
                        "previous_checkpoint_sha256": previous_checkpoint_sha256,
                    }
                )
                _secure_write_json_once(
                    attempt_root / f"job-{job.job_id}.json", result
                )
                _write_attempt_heartbeat(
                    heartbeat_path,
                    deadline,
                    operation=f"job:{job.job_id}:complete",
                    last_completed_job_id=job.job_id,
                    force=True,
                    attempt_root=attempt_root,
                )
    except BaseException as error:
        # KeyboardInterrupt、超时和进程创建失败都必须先完成 after 探针。
        if execution_error is None:
            execution_error = error
    finally:
        try:
            # 到期时不再启动新的外部操作，但仍尝试一次受控 after／恢复；失败
            # 会与 timeout 一起写入 attempt，绝不吞掉清理错误。
            if not deadline.expired:
                deadline.check("attempt:after-probe")
                after_manifest = _invoke_with_optional_deadline(
                    _probe_capture_environment,
                    manifest,
                    environment_root / "after",
                    "after",
                    deadline=deadline,
                    heartbeat=lambda operation: _write_attempt_heartbeat(
                        heartbeat_path,
                        deadline,
                        operation=operation,
                        attempt_root=attempt_root,
                    ),
                )
                deadline.check("attempt:restoration")
                restoration_path, restoration_receipt = (
                    _finalize_attempt_restoration(
                        evidence_root,
                        phase=phase,
                        candidate_id=candidate_id,
                    )
                )
        except BaseException as error:
            restoration_error = error
        try:
            if not deadline.expired:
                deadline.check("attempt:arm64-after")
                arm64_after_path, arm64_after_receipt = _invoke_with_optional_deadline(
                    _capture_arm64_environment_receipt,
                    environment_root / "arm64-after",
                    phase="attempt_after",
                    subject_id=attempt_root.name,
                    deadline=deadline,
                    heartbeat=lambda operation: _write_attempt_heartbeat(
                        heartbeat_path,
                        deadline,
                        operation=operation,
                        attempt_root=attempt_root,
                    ),
                )
                if (
                    arm64_before_receipt is None
                    or arm64_before_receipt.get("continuity_identity_sha256")
                    != arm64_after_receipt.get("continuity_identity_sha256")
                ):
                    raise ConfigurationError("attempt 前后 ARM64 网络或运行身份漂移。")
        except BaseException as error:
            if restoration_error is None:
                restoration_error = error

    if isinstance(execution_error, incremental_recovery.WallClockTimeoutError) or deadline.expired:
        # 超时是不可恢复的 attempt 终态：即使剩余清理预算为零，也必须尽力写入
        # 一次不可覆盖 checkpoint；写 checkpoint 失败会升级为停线错误。
        try:
            _write_attempt_heartbeat(
                heartbeat_path,
                deadline,
                operation="attempt:timeout",
                force=True,
                allow_expired=True,
                attempt_root=attempt_root,
            )
        except BaseException as error:
            timeout_checkpoint_error = error
        try:
            timeout_checkpoint_path = _write_timeout_checkpoint(
                attempt_root,
                deadline,
                operation=(
                    execution_error.operation
                    if isinstance(
                        execution_error,
                        incremental_recovery.WallClockTimeoutError,
                    )
                    else "attempt:deadline"
                ),
                last_completed_job_id=getattr(
                    deadline, "last_completed_job_id", None
                ),
            )
        except BaseException as error:
            timeout_checkpoint_error = timeout_checkpoint_error or error
        if timeout_checkpoint_error is not None and execution_error is None:
            execution_error = timeout_checkpoint_error

    result_by_id = {
        result.get("id"): result
        for result in results
        if isinstance(result, dict) and isinstance(result.get("id"), str)
    }
    required_jobs_ok = execution_error is None and all(
        result_by_id.get(job.job_id, {}).get("status") == "complete"
        and result_by_id[job.job_id].get("execution_sha256")
        == _job_execution_sha256(job)
        for job in planned_jobs
        if job.required
    )
    try:
        job_evidence_roots = _deduplicate_evidence_roots(
            (
                Path(root)
                for result in results
                for root in result.get("evidence_roots", [])
            ),
            require_nonempty=required_jobs_ok,
        )
    except ConfigurationError as error:
        if execution_error is None:
            execution_error = error
        required_jobs_ok = False
        job_evidence_roots = []
    evidence_roots = _deduplicate_evidence_roots(
        [
            *job_evidence_roots,
            evidence_root,
            log_root,
        ],
        require_nonempty=False,
    )

    environment: dict[str, Any] = {
        "evidence_root": str(evidence_root.resolve(strict=True)),
        "before_probe": None,
        "after_probe": None,
        "restoration_report": None,
        "arm64_before_receipt": None,
        "arm64_after_receipt": None,
    }
    before_probe_path = environment_root / "before" / "probe-manifest.json"
    after_probe_path = environment_root / "after" / "probe-manifest.json"
    if before_manifest is not None:
        environment["before_probe"] = _attempt_evidence_binding(
            evidence_root, before_probe_path
        )
    if after_manifest is not None:
        environment["after_probe"] = _attempt_evidence_binding(
            evidence_root, after_probe_path
        )
    if restoration_path is not None and restoration_receipt is not None:
        environment["restoration_report"] = _attempt_evidence_binding(
            evidence_root, restoration_path
        )
    if arm64_before_path is not None and arm64_before_receipt is not None:
        environment["arm64_before_receipt"] = _attempt_evidence_binding(
            evidence_root, arm64_before_path
        )
    if arm64_after_path is not None and arm64_after_receipt is not None:
        environment["arm64_after_receipt"] = _attempt_evidence_binding(
            evidence_root, arm64_after_path
        )

    contamination: dict[str, Any] | None = None
    if before_manifest is not None and restoration_error is not None:
        contamination = {
            "schema_version": "codex-upgrade-environment-contamination/v1",
            "phase": phase,
            "candidate_id": candidate_id,
            "attempt_id": attempt_root.name,
            "reason": (
                "独立 after 探针或恢复 finalizer 未通过："
                f"{type(restoration_error).__name__}"
            ),
        }
    # 形成 attempt 收据前固定 watchdog／checkpoint 绑定。这里仅读取小型摘要，
    # 不扫描 Job 证据内容；任何绑定读取失败都按停线处理。
    watchdog_heartbeat: dict[str, Any] | None = None
    if heartbeat_path.is_file() and not heartbeat_path.is_symlink():
        watchdog_heartbeat = {
            "path": str(heartbeat_path.relative_to(campaign_dir)),
            "sha256": file_sha256(heartbeat_path),
            "bytes": heartbeat_path.stat().st_size,
        }
    elif setup_error is None:
        execution_error = execution_error or ConfigurationError(
            "attempt 缺少 watchdog heartbeat 收据。"
        )
    job_checkpoint: dict[str, Any] | None = None
    if checkpoint_store is not None:
        try:
            checkpoint_records = checkpoint_store.records()
            job_checkpoint = {
                "schema_version": JOB_CHECKPOINT_SCHEMA,
                "campaign_id": manifest["campaign_id"],
                "phase": phase,
                "attempt_id": attempt_root.name,
                "run_nonce": reservation["run_nonce"],
                "path": str(
                    checkpoint_store.root.resolve(strict=True).relative_to(
                        campaign_dir.resolve(strict=True)
                    )
                ),
                "record_count": len(checkpoint_records),
                "last_sequence": (
                    checkpoint_records[-1].get("checkpoint_sequence")
                    if checkpoint_records
                    else None
                ),
                "last_sha256": (
                    checkpoint_records[-1].get("checkpoint_sha256")
                    if checkpoint_records
                    else None
                ),
            }
        except BaseException as error:
            # checkpoint 自身损坏或读取失败必须停线，但不能让最终 attempt
            # 收据因为异常逃逸而永远缺失；把错误保留在 attempt 主事实中。
            if execution_error is None:
                execution_error = error
            job_checkpoint = None
    elif setup_error is None:
        execution_error = execution_error or ConfigurationError(
            "attempt 缺少 Job checkpoint 存储。"
        )
    watchdog = {
        "schema_version": WATCHDOG_HEARTBEAT_SCHEMA,
        "budget_seconds": deadline.budget_seconds,
        "heartbeat_seconds": getattr(
            deadline, "heartbeat_seconds", DEFAULT_HEARTBEAT_SECONDS
        ),
        "elapsed_seconds": round(deadline.elapsed_seconds, 3),
        "remaining_seconds": round(deadline.remaining_seconds, 3),
        "heartbeat": watchdog_heartbeat,
        "timeout_checkpoint": (
            {
                "path": str(timeout_checkpoint_path.relative_to(campaign_dir)),
                "sha256": file_sha256(timeout_checkpoint_path),
                "bytes": timeout_checkpoint_path.stat().st_size,
            }
            if timeout_checkpoint_path is not None
            and timeout_checkpoint_path.is_file()
            else None
        ),
        "last_completed_job_id": getattr(
            deadline, "last_completed_job_id", None
        ),
    }
    failed_result_ids = _failed_job_ids(results)
    status = (
        "environment_contaminated"
        if contamination is not None
        else "awaiting_receipts"
        if required_jobs_ok
        and not failed_result_ids
        and restoration_receipt is not None
        else "failed"
    )
    attempt = _write_capture_attempt(
        campaign_dir,
        attempt_root,
        {
            "campaign_id": manifest["campaign_id"],
            "phase": phase,
            "candidate_id": candidate_id,
            "status": status,
            "continuity": continuity,
            "tool_components": (
                tool_identity.get("components")
                if isinstance(tool_identity, Mapping)
                else None
            ),
            **(
                {
                    "classification_candidate_reuse_transition": (
                        classification_candidate_reuse_transition_binding
                    )
                }
                if classification_candidate_reuse_transition is not None
                and classification_candidate_reuse_transition_binding is not None
                else {}
            ),
            "incremental_tool_transition": incremental_transition,
            "evaluation_transition": evaluation_transition,
            "incremental_plan": {
                "schema_version": incremental_recovery.SCHEMA_VERSION,
                "planned_job_ids": sorted(job.job_id for job in planned_jobs),
                "changed_components": sorted(changed_components),
                "affected_job_ids": sorted(affected_job_ids),
                "reused_job_ids": sorted(
                    str(item.get("id"))
                    for item in prior_results
                    if item.get("id")
                ),
                "executed_job_ids": sorted(
                    str(item.get("id"))
                    for item in results
                    if item.get("id")
                    and item.get("disposition", "executed") == "executed"
                ),
                "failed_job_ids": sorted(
                    str(item.get("id"))
                    for item in results
                    if item.get("id") and item.get("status") == "failed"
                ),
                "pending_job_ids": sorted(
                    {
                        job.job_id for job in planned_jobs
                    }
                    - {
                        str(item.get("id"))
                        for item in results
                        if item.get("id")
                    }
                ),
                "plan_sha256": incremental_recovery.digest(
                    {
                        "schema_version": incremental_recovery.SCHEMA_VERSION,
                        "planned_job_ids": sorted(
                            job.job_id for job in planned_jobs
                        ),
                        "changed_components": sorted(changed_components),
                        "affected_job_ids": sorted(affected_job_ids),
                        "reused_job_ids": sorted(
                            str(item.get("id"))
                            for item in prior_results
                            if item.get("id")
                        ),
                        "executed_job_ids": sorted(
                            str(item.get("id"))
                            for item in results
                            if item.get("id")
                            and item.get("disposition", "executed") == "executed"
                        ),
                        "failed_job_ids": sorted(
                            str(item.get("id"))
                            for item in results
                            if item.get("id") and item.get("status") == "failed"
                        ),
                        "pending_job_ids": sorted(
                            {
                                job.job_id for job in planned_jobs
                            }
                            - {
                                str(item.get("id"))
                                for item in results
                                if item.get("id")
                            }
                        ),
                    }
                ),
            },
            "identity": identity,
            "results": results,
            "evidence_roots": [str(root) for root in evidence_roots],
            "environment": environment,
            "binary_verification": binary_verification,
            "watchdog": watchdog,
            "job_checkpoint": job_checkpoint,
            "execution_error": (
                {
                    "type": type(execution_error).__name__,
                    "message": str(execution_error)[:1000],
                }
                if execution_error is not None
                else None
            ),
            "restoration_error": (
                {
                    "type": type(restoration_error).__name__,
                    "message": str(restoration_error)[:1000],
                }
                if restoration_error is not None
                else None
            ),
            "next_gate": (
                "运行 capture manifest finalizer；候选还需完成运行画像与两种 Kilo 原始 witness。"
                if status == "awaiting_receipts"
                else (
                    "仅补跑失败 Job：" + "、".join(failed_result_ids)
                    if failed_result_ids
                    else None
                )
            ),
        },
    )
    if contamination is not None:
        try:
            _secure_write_json_once(
                campaign_dir / "environment-contaminated.json", contamination
            )
        except (ConfigurationError, OSError):
            # attempt.json 的 environment_contaminated 是主事实，marker 仅为提示。
            pass
        raise RuntimeError(contamination["reason"])
    if execution_error is not None:
        raise execution_error
    return {
        "status": status,
        "phase": phase,
        "candidate_id": candidate_id,
        "attempt_id": attempt_root.name,
        "attempt": str(attempt_root),
        "attempt_digest": attempt["attempt_digest"],
        "run_nonce": reservation["run_nonce"],
        "started_at_utc": reservation["started_at_utc"],
        "environment": environment,
        "results": results,
        "incremental_plan": (
            attempt.get("incremental_plan") if isinstance(attempt, Mapping) else None
        ),
        "next_command": (
            f"capture-{phase} seal --attempt-id {attempt_root.name}"
            if status == "awaiting_receipts"
            else "修复失败任务后使用 resume --rerun-failed。"
        ),
    }


def _approve_frozen_capture_seal(
    arguments: argparse.Namespace,
    *,
    phase: str,
    campaign_dir: Path,
    attempt_root: Path,
    attempt: dict[str, Any],
    candidate_id: str | None,
    evaluation_transition: dict[str, str] | None,
) -> dict[str, Any]:
    """只重放冻结草案与 stat 边界完成批准，不重新读取证据内容。"""

    transition_index = _seal_transition_index(evaluation_transition)
    draft = _load_seal_draft(
        campaign_dir,
        attempt_root,
        phase=phase,
        candidate_id=candidate_id,
        attempt=attempt,
        transition_index=transition_index,
    )
    payload = dict(draft["stage_payload"])
    if (
        ("evaluation_transition" in payload)
        != (evaluation_transition is not None)
        or payload.get("evaluation_transition") != evaluation_transition
    ):
        raise ConfigurationError("seal 冻结草案未绑定当前有效 transition。")
    if payload.get("status") != "complete":
        raise ConfigurationError("seal 冻结草案不是可批准的完整阶段。")
    if phase == "candidate":
        candidate_purpose = getattr(arguments, "candidate_purpose", None)
        if candidate_purpose != payload.get("candidate_purpose"):
            raise ConfigurationError("seal 批准用途与冻结草案不一致。")
    preview, approved = _seal_preview(
        campaign_dir,
        attempt_root,
        phase=phase,
        candidate_id=candidate_id,
        attempt=attempt,
        stage_payload=payload,
        approve_sha256=getattr(arguments, "approve_seal_sha256", None),
    )
    if not approved:
        raise ConfigurationError("seal 批准缺少 --approve-seal-sha256。")
    preview_path = _seal_preview_path(attempt_root, transition_index)
    payload["seal_preview"] = {
        "path": str(preview_path.relative_to(campaign_dir)),
        "sha256": file_sha256(preview_path),
    }
    save_stage_result(
        campaign_dir,
        "capture-official" if phase == "official" else "capture-candidate",
        payload,
        candidate_id=candidate_id,
    )
    return {
        **payload,
        "status": "complete",
        "review_sha256": preview["review_sha256"],
        "approval_scan": {
            "full_scan_count": 0,
            "scanned_bytes": 0,
        },
    }


def _manifest_surface_files(evidence_manifest: Mapping[str, Any]) -> list[Path]:
    """由已冻结 manifest 显式定位表面文件，不再递归遍历证据目录。"""

    roots = evidence_manifest.get("roots")
    entries = evidence_manifest.get("entries")
    if not isinstance(roots, list) or not isinstance(entries, list):
        raise ConfigurationError("EvidenceManifest 缺少表面文件定位信息。")
    root_index: dict[str, Path] = {}
    for item in roots:
        if (
            not isinstance(item, Mapping)
            or not isinstance(item.get("prefix"), str)
            or not isinstance(item.get("path"), str)
        ):
            raise ConfigurationError("EvidenceManifest 的证据根结构非法。")
        prefix = str(item["prefix"])
        root = Path(str(item["path"]))
        if prefix in root_index:
            raise ConfigurationError("EvidenceManifest 的证据根前缀重复。")
        root_index[prefix] = root

    selected: set[Path] = set()
    for item in entries:
        logical = item.get("path") if isinstance(item, Mapping) else None
        if not isinstance(logical, str) or "/" not in logical:
            raise ConfigurationError("EvidenceManifest 的逻辑文件路径非法。")
        prefix, relative = logical.split("/", 1)
        if (
            not relative
            or relative.startswith("/")
            or "\\" in relative
            or any(part in {"", ".", ".."} for part in relative.split("/"))
        ):
            raise ConfigurationError("EvidenceManifest 的逻辑文件路径不规范。")
        root = root_index.get(prefix)
        if root is None:
            raise ConfigurationError("EvidenceManifest 文件引用未知证据根。")
        if root.is_file():
            if relative != root.name:
                raise ConfigurationError("EvidenceManifest 的单文件根映射非法。")
            path = root
        else:
            path = root / relative
            try:
                path.resolve(strict=True).relative_to(root.resolve(strict=True))
            except (OSError, RuntimeError, ValueError) as error:
                raise ConfigurationError(
                    "EvidenceManifest 表面文件越过证据根。"
                ) from error
        if path.is_symlink() or not path.is_file():
            raise ConfigurationError("EvidenceManifest 表面文件路径发生漂移。")
        if path.suffix.lower() in {".json", ".jsonl", ".pcap", ".bin"}:
            selected.add(path.resolve(strict=True))
    return sorted(selected)


def _validate_surface_document(
    payload: Any,
    *,
    label: str,
    input_paths: list[Path],
    expected_file_count: int,
) -> dict[str, Any]:
    if not isinstance(payload, dict) or set(payload) != {
        "schema_version",
        "label",
        "input_paths",
        "file_count",
        "surface_count",
        "surfaces",
        "warnings",
    }:
        raise ConfigurationError("抓包表面结构非法。")
    surfaces = payload.get("surfaces")
    warnings = payload.get("warnings")
    if (
        payload.get("schema_version") != SURFACE_SCHEMA
        or payload.get("label") != label
        or payload.get("input_paths") != [str(path) for path in input_paths]
        or payload.get("file_count") != expected_file_count
        or not isinstance(surfaces, list)
        or payload.get("surface_count") != len(surfaces)
        or not isinstance(warnings, list)
        or not all(isinstance(value, str) for value in warnings)
    ):
        raise ConfigurationError("抓包表面与 attempt／manifest 边界不一致。")
    for item in surfaces:
        if (
            not isinstance(item, dict)
            or not isinstance(item.get("kind"), str)
            or not isinstance(item.get("sources"), list)
            or not all(isinstance(value, str) for value in item["sources"])
            or item.get("fingerprint")
            != _fingerprint(
                {
                    key: value
                    for key, value in item.items()
                    if key not in {"fingerprint", "sources"}
                }
            )
        ):
            raise ConfigurationError("抓包表面的条目摘要非法。")
    return payload


def _load_or_build_attempt_surface(
    campaign_dir: Path,
    attempt_root: Path,
    attempt: Mapping[str, Any],
    evidence_manifest: Mapping[str, Any],
    *,
    label: str,
) -> tuple[dict[str, Any], dict[str, str]]:
    """优先复用既有 surface；缺失时只按 manifest 文件清单做有界解析。"""

    input_paths = [Path(str(value)) for value in attempt.get("evidence_roots", [])]
    files = _manifest_surface_files(evidence_manifest)
    derived_root = ensure_private_directory(attempt_root / "finalized", campaign_dir)
    surface_path = derived_root / "surface.json"
    if surface_path.exists() or surface_path.is_symlink():
        if surface_path.is_symlink() or not surface_path.is_file():
            raise ConfigurationError("既有抓包表面路径不可信。")
        surface = _validate_surface_document(
            _read_json(surface_path, "既有抓包表面"),
            label=label,
            input_paths=input_paths,
            expected_file_count=len(files),
        )
    else:
        surface = _scan_evidence_files(
            files,
            label,
            input_paths=input_paths,
        )
        surface = _validate_surface_document(
            surface,
            label=label,
            input_paths=input_paths,
            expected_file_count=len(files),
        )
        _write_or_verify_json(surface_path, surface)
    if surface["file_count"] == 0:
        raise ConfigurationError("attempt 没有可封存抓包证据。")
    return surface, {
        "path": str(surface_path.relative_to(campaign_dir)),
        "sha256": file_sha256(surface_path),
    }


def _seal_capture_attempt(
    arguments: argparse.Namespace,
    phase: str,
) -> dict[str, Any]:
    """从不可变 attempt 与机器收据构建预览，并经摘要复核后封存阶段。"""

    campaign_dir = arguments.campaign_dir
    manifest = _require_formal_campaign(campaign_dir)
    attempt_id = getattr(arguments, "attempt_id", None)
    if not attempt_id:
        raise ConfigurationError("seal 必须提供 --attempt-id。")
    candidate_id = arguments.candidate_id if phase == "candidate" else None
    if candidate_id:
        manifest = _apply_candidate_runtime_override(campaign_dir, manifest, candidate_id)
    attempt_root, attempt = _load_capture_attempt(
        campaign_dir, phase, candidate_id, attempt_id
    )
    contamination_records = _campaign_contamination_records(campaign_dir)
    allow_metadata_only_repair = bool(
        contamination_records
        and _metadata_only_seal_repair_allowed(
            campaign_dir,
            attempt_root,
            attempt,
            contamination_records,
        )
    )
    _reject_contaminated_campaign(
        campaign_dir,
        allow_metadata_only_repair=allow_metadata_only_repair,
        attempt_root=attempt_root,
        attempt=attempt,
    )
    failed_result_ids = _failed_job_ids(attempt.get("results"))
    if failed_result_ids:
        raise ConfigurationError(
            "attempt 仍有失败 Job，禁止 seal："
            + "、".join(failed_result_ids)
            + "；只能定向补跑失败闭集。"
        )
    _bind_active_lease_attempt(
        campaign_dir,
        phase=phase,
        candidate_id=candidate_id,
        attempt_id=attempt.get("attempt_id"),
    )
    tool_impact = _verify_plan_identity(
        campaign_dir,
        manifest,
        operation=f"capture-{phase}-seal",
        attempt_root=attempt_root,
        attempt=attempt,
    )
    evaluation_transition = _stage_evaluation_transition_binding(tool_impact)
    seal_transition_index = _seal_transition_index(evaluation_transition)
    if attempt.get("status") != "awaiting_receipts":
        raise ConfigurationError("只有 awaiting_receipts attempt 可以 seal。")
    if getattr(arguments, "approve_seal_sha256", None):
        if not _seal_draft_path(attempt_root, seal_transition_index).is_file():
            raise ConfigurationError(
                "seal 批准缺少当前 transition 对应的冻结草案；必须先生成预览。"
            )
        return _approve_frozen_capture_seal(
            arguments,
            phase=phase,
            campaign_dir=campaign_dir,
            attempt_root=attempt_root,
            attempt=attempt,
            candidate_id=candidate_id,
            evaluation_transition=evaluation_transition,
        )
    if phase == "official":
        try:
            _load_stage_result(campaign_dir, "capture-official")
        except ConfigurationError as error:
            if "尚未封存" not in str(error):
                raise
        else:
            raise ConfigurationError("官方证据已经封存，禁止覆盖。")
        jobs = _campaign_jobs(campaign_dir, manifest, "official")
        identity = attempt["identity"]
        classification = None
        current_binary_verification = _verify_official_binaries(manifest)
        if _fingerprint(current_binary_verification) != _fingerprint(
            attempt.get("binary_verification", {})
        ):
            raise ConfigurationError("官方 CLI 二进制在 run／seal 之间发生漂移。")
    else:
        classification = _load_stage_result(campaign_dir, "classify")
        if classification.get("status") != "complete":
            raise ConfigurationError("目标画像尚未批准，禁止候选 seal。")
        identity = attempt.get("identity")
        if not isinstance(identity, dict):
            raise ConfigurationError("候选 attempt 缺少不可变身份。")
        optional_identity = {
            "runtime_image": "image_reference",
            "candidate_image_id": "image_id",
            "build_id": "build_id",
            "deployed_version": "deployed_version",
            "profile_id": "profile_id",
            "profile_digest": "profile_digest",
            "candidate_purpose": "candidate_purpose",
        }
        for argument_name, identity_name in optional_identity.items():
            value = getattr(arguments, argument_name, None)
            if argument_name == "candidate_purpose" and value is None:
                raise ConfigurationError(
                    "候选 seal 必须重申 --candidate-purpose。"
                )
            if value is not None and value != identity.get(identity_name):
                raise ConfigurationError(
                    f"seal 参数 --{argument_name.replace('_', '-')} 与 run 身份不一致。"
                )
        candidate_source = getattr(arguments, "candidate_source", None)
        if (
            candidate_source is not None
            and candidate_source.resolve(strict=True)
            != Path(str(identity.get("source_root", ""))).resolve(strict=True)
        ):
            raise ConfigurationError("seal 的 --candidate-source 与 run 身份不一致。")
        _verify_candidate_attempt_identity(manifest, identity)
        approved_profile_id, approved_profile_digest = _profile_binding_from_manifest(
            campaign_dir, classification
        )
        if (
            identity.get("profile_id") != approved_profile_id
            or identity.get("profile_digest") != approved_profile_digest
        ):
            raise ConfigurationError("候选 attempt 与当前批准画像不一致。")
        jobs = _campaign_jobs(
            campaign_dir,
            manifest,
            "candidate",
            candidate_id=candidate_id,
            runtime_image=str(identity.get("image_reference", "")),
            profile_id=str(identity.get("profile_id", "")),
            profile_digest=str(identity.get("profile_digest", "")),
            build_id=str(identity.get("build_id", "")),
            deployed_version=str(identity.get("deployed_version", "")),
            candidate_image_id=str(identity.get("image_id", "")),
            source_tree_sha256=str(identity.get("source_tree_sha256", "")),
            candidate_purpose=str(identity.get("candidate_purpose", "")),
        )
    _validate_capture_job_results(jobs, attempt.get("results"), phase=phase)

    metadata_source: tuple[Path, Path, dict[str, Any], dict[str, Any]] | None = None
    if _is_classification_candidate_metadata_only_attempt(attempt):
        metadata_source = _classification_candidate_reuse_attempt_source(
            campaign_dir,
            manifest,
            attempt,
        )

    roots = _deduplicate_evidence_roots(
        Path(value) for value in attempt.get("evidence_roots", [])
    )
    requested_roots = _deduplicate_evidence_roots(
        getattr(arguments, "evidence_root", []),
        require_nonempty=False,
    )
    for requested_root in requested_roots:
        if not any(
            requested_root == root or requested_root.is_relative_to(root)
            for root in roots
        ):
            raise ConfigurationError(
                "seal 的 --evidence-root 不能扩展 run 已绑定的证据边界。"
            )
    try:
        preflight = codex_upgrade_evidence_manifest.preflight_evidence_roots(roots)
    except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
        raise ConfigurationError(
            f"seal 廉价前检失败（scanned_bytes=0）：{error}"
        ) from error
    environment = attempt.get("environment")
    if not isinstance(environment, dict):
        raise ConfigurationError("抓包 attempt 缺少自动环境探针绑定。")
    attempt_evidence_root = Path(str(environment.get("evidence_root", "")))
    if (
        not attempt_evidence_root.is_absolute()
        or attempt_evidence_root.resolve(strict=True) not in roots
    ):
        raise ConfigurationError("抓包 attempt 的环境证据根未纳入 seal。")
    restoration_environment = environment
    restoration_subject_id = attempt_id
    restoration_evidence_root = attempt_evidence_root
    metadata_source_evidence_root: Path | None = None
    if metadata_source is not None:
        _source_dir, _source_root, source_attempt, _transition = metadata_source
        if any(
            environment.get(name) is not None
            for name in (
                "before_probe",
                "after_probe",
                "restoration_report",
                "arm64_before_receipt",
                "arm64_after_receipt",
            )
        ):
            raise ConfigurationError("metadata-only attempt 不得伪造本轮环境探针。")
        source_environment = source_attempt.get("environment")
        if not isinstance(source_environment, dict):
            raise ConfigurationError("metadata-only attempt 来源缺少环境恢复绑定。")
        restoration_environment = source_environment
        restoration_subject_id = str(source_attempt.get("attempt_id", ""))
        restoration_evidence_root = Path(
            str(source_environment.get("evidence_root", ""))
        )
        if (
            not restoration_evidence_root.is_absolute()
            or restoration_evidence_root.resolve(strict=True) not in roots
        ):
            raise ConfigurationError("metadata-only attempt 来源环境根未纳入 seal。")
        metadata_source_evidence_root = restoration_evidence_root
    arm64_receipts: dict[str, dict[str, Any]] = {}
    for role, expected_phase in (
        ("arm64_before_receipt", "attempt_before"),
        ("arm64_after_receipt", "attempt_after"),
    ):
        reference = restoration_environment.get(role)
        if not isinstance(reference, dict) or set(reference) != {
            "path",
            "sha256",
            "bytes",
        }:
            raise ConfigurationError(f"抓包 attempt 缺少 {role} 绑定。")
        receipt_path = restoration_evidence_root / str(reference.get("path", ""))
        if (
            receipt_path.is_symlink()
            or not receipt_path.is_file()
            or receipt_path.stat().st_size != reference.get("bytes")
            or file_sha256(receipt_path) != reference.get("sha256")
        ):
            raise ConfigurationError(f"抓包 attempt 的 {role} 摘要漂移。")
        try:
            replayed = codex_upgrade_arm64_environment_receipt.replay(
                receipt_path.parent, receipt_path.name
            )
        except (
            OSError,
            codex_upgrade_arm64_environment_receipt.Arm64EnvironmentReceiptError,
        ) as error:
            raise ConfigurationError(f"抓包 attempt 的 {role} 无法重放：{error}") from error
        if (
            replayed.get("status") != "passed"
            or replayed.get("phase") != expected_phase
            or replayed.get("subject_id") != restoration_subject_id
        ):
            raise ConfigurationError(f"抓包 attempt 的 {role} 身份不一致。")
        arm64_receipts[role] = replayed
    if (
        arm64_receipts["arm64_before_receipt"].get(
            "continuity_identity_sha256"
        )
        != arm64_receipts["arm64_after_receipt"].get(
            "continuity_identity_sha256"
        )
    ):
        raise ConfigurationError("抓包 attempt 前后 ARM64 环境身份不连续。")
    restoration_reference = restoration_environment.get("restoration_report")
    if (
        not isinstance(restoration_reference, dict)
        or set(restoration_reference) != {"path", "sha256", "bytes"}
    ):
        raise ConfigurationError("抓包 attempt 缺少机器恢复收据绑定。")
    restoration_path = restoration_evidence_root / str(
        restoration_reference.get("path", "")
    )
    if (
        restoration_path.is_symlink()
        or not restoration_path.is_file()
        or restoration_path.stat().st_size != restoration_reference.get("bytes")
        or file_sha256(restoration_path) != restoration_reference.get("sha256")
    ):
        raise ConfigurationError("抓包 attempt 的机器恢复收据发生漂移。")
    requested_restoration = getattr(arguments, "restoration_report", None)
    if (
        requested_restoration is not None
        and requested_restoration.resolve(strict=True)
        != restoration_path.resolve(strict=True)
    ):
        raise ConfigurationError(
            "--restoration-report 只能指向 run 自动生成的恢复收据。"
        )
    post_client_path: Path | None = None
    client_checkpoint_at: str | None = None
    client_checkpoint_created = False
    if phase == "candidate":
        try:
            with _campaign_lock(campaign_dir):
                _reject_contaminated_campaign(
                    campaign_dir,
                    allow_metadata_only_repair=allow_metadata_only_repair,
                    attempt_root=attempt_root,
                    attempt=attempt,
                )
                (
                    post_client_path,
                    _,
                    client_checkpoint_at,
                    client_checkpoint_created,
                ) = _candidate_post_client_restoration(
                    manifest,
                    attempt_evidence_root,
                    str(candidate_id),
                    source_evidence_root=metadata_source_evidence_root,
                    source_environment=(
                        restoration_environment
                        if metadata_source_evidence_root is not None
                        else None
                    ),
                )
            if _rfc3339_datetime(
                client_checkpoint_at, "Kilo 后检查点时间"
            ) < _rfc3339_datetime(
                attempt["completed_at_utc"], "attempt.completed_at_utc"
            ):
                raise ConfigurationError("Kilo 后检查点早于候选 run 完成时间。")
        except (
            ConfigurationError,
            EnvironmentProbeError,
            ReceiptFinalizerError,
            OSError,
            ValueError,
        ) as error:
            _record_candidate_seal_failure(
                campaign_dir,
                attempt_root,
                attempt,
                error,
            )
            raise RuntimeError("Kilo 后环境恢复门禁失败。") from error
        if client_checkpoint_created:
            return {
                "status": "client_checkpoint_created",
                "phase": "candidate",
                "campaign_id": attempt["campaign_id"],
                "candidate_id": candidate_id,
                "attempt_id": attempt["attempt_id"],
                "run_nonce": attempt["run_nonce"],
                "attempt_started_at_utc": attempt["started_at_utc"],
                "client_checkpoint_at_utc": client_checkpoint_at,
                "evidence_root": str(attempt_evidence_root),
                "next_command": (
                    "使用上述不可变边界生成 observed-profile 与两份 Kilo 收据；"
                    "随后重新执行 capture-candidate seal。"
                ),
            }
    restoration = _validate_restoration_report(
        restoration_path,
        roots,
        phase=phase,
        candidate_id=candidate_id,
    )
    assertion_context = _capture_assertion_context(
        getattr(arguments, "capture_manifest", None),
        getattr(arguments, "assertion_evidence_root", None),
        roots,
        target_version=manifest["target_version"],
    )
    assertion_gate = _run_seal_assertion_gate(
        assertion_context,
        roots,
        phase=phase,
        target_version=manifest["target_version"],
    )
    client_bindings: list[dict[str, Any]] = []
    observed_profile: dict[str, str] | None = None
    if phase == "candidate":
        if post_client_path is None or client_checkpoint_at is None:
            raise ConfigurationError("候选 seal 缺少 Kilo 后检查点。")
        observed_profile, observed_receipt = _validate_observed_profile_receipt(
            getattr(arguments, "observed_profile_receipt", None),
            [attempt_evidence_root],
            campaign_id=attempt["campaign_id"],
            attempt_id=attempt["attempt_id"],
            run_nonce=attempt["run_nonce"],
            attempt_started_at_utc=attempt["started_at_utc"],
            client_checkpoint_at_utc=client_checkpoint_at,
            candidate_id=str(candidate_id),
            target_version=manifest["target_version"],
            expected_profile_id=str(identity["profile_id"]),
            expected_profile_digest=str(identity["profile_digest"]),
            image_id=str(identity["image_id"]),
            image_reference=str(identity["image_reference"]),
            source_tree_sha256=str(identity["source_tree_sha256"]),
            build_id=str(identity["build_id"]),
            deployed_version=str(identity["deployed_version"]),
        )
        if (
            observed_receipt.get("profile_id") != identity["profile_id"]
            or observed_receipt.get("profile_digest") != identity["profile_digest"]
        ):
            raise ConfigurationError("运行画像收据与 attempt 身份不一致。")
        client_bindings = _parse_client_evidence(
            arguments.client_evidence,
            [attempt_evidence_root],
            campaign_id=attempt["campaign_id"],
            attempt_id=attempt["attempt_id"],
            run_nonce=attempt["run_nonce"],
            attempt_started_at_utc=attempt["started_at_utc"],
            client_checkpoint_at_utc=client_checkpoint_at,
            candidate_id=str(candidate_id),
            target_version=manifest["target_version"],
            model=_third_party_client_model(manifest["configuration"]),
            identity=identity,
        )
        required_clients = _required_client_bindings(campaign_dir, classification)
        observed_clients = {item["client_id"] for item in client_bindings}
        if not required_clients.issubset(observed_clients):
            raise ConfigurationError(
                "候选 seal 缺少目标场景要求的第三方客户端收据："
                f"{sorted(required_clients - observed_clients)}"
            )
        restoration["post_client"] = _validate_restoration_report(
            post_client_path,
            roots,
            phase="candidate",
            candidate_id=str(candidate_id),
        )

    manifest_path = _evidence_manifest_path(attempt_root)
    if manifest_path.exists() or manifest_path.is_symlink():
        evidence_manifest = _load_evidence_manifest(manifest_path)
        try:
            codex_upgrade_evidence_manifest.verify_manifest_boundary(
                evidence_manifest,
                roots,
            )
        except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
            raise ConfigurationError(str(error)) from error
    else:
        if metadata_source is not None:
            _source_dir, source_root, source_attempt, _transition = metadata_source
            source_roots = _deduplicate_evidence_roots(
                Path(value) for value in source_attempt.get("evidence_roots", [])
            )
            source_manifest_path = _evidence_manifest_path(source_root)
            if not source_manifest_path.is_file() or source_manifest_path.is_symlink():
                source_manifest_path = (
                    attempt_root
                    / CLASSIFICATION_CANDIDATE_REUSE_SOURCE_MANIFEST_FILENAME
                )
            if not source_manifest_path.is_file() or source_manifest_path.is_symlink():
                raise ConfigurationError(
                    "metadata-only attempt 来源尚无 EvidenceManifest；必须先显式执行 "
                    "deep-verify，禁止在 seal 中隐式重扫来源证据。"
                )
            source_manifest = _load_evidence_manifest(source_manifest_path)
            try:
                codex_upgrade_evidence_manifest.verify_manifest_boundary(
                    source_manifest,
                    source_roots,
                )
                source_root_set = {path.resolve(strict=True) for path in source_roots}
                delta_roots = [
                    path for path in roots if path.resolve(strict=True) not in source_root_set
                ]
                if not delta_roots:
                    raise ConfigurationError(
                        "metadata-only attempt 缺少本轮 Kilo／断言证据根。"
                    )
                delta_manifest = codex_upgrade_evidence_manifest.build_evidence_manifest(
                    delta_roots,
                    checkpoint_path=_evidence_manifest_checkpoint_path(attempt_root),
                    secret_env_names=_secret_environment_names(),
                )
                evidence_manifest = codex_upgrade_evidence_manifest.merge_evidence_manifests(
                    source_manifest,
                    delta_manifest,
                )
                codex_upgrade_evidence_manifest.verify_manifest_boundary(
                    evidence_manifest,
                    roots,
                )
            except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
                raise ConfigurationError(str(error)) from error
        else:
            try:
                evidence_manifest = (
                    codex_upgrade_evidence_manifest.build_evidence_manifest(
                        roots,
                        checkpoint_path=_evidence_manifest_checkpoint_path(attempt_root),
                        secret_env_names=_secret_environment_names(),
                    )
                )
            except codex_upgrade_evidence_manifest.EvidenceManifestError as error:
                raise ConfigurationError(str(error)) from error
        _write_or_verify_json(manifest_path, evidence_manifest)
    evidence_inventory = evidence_manifest["inventory"]
    security = evidence_manifest["security"]
    raw_evidence_private = True
    if not security["known_secret_scan_passed"]:
        raise ConfigurationError(
            f"{phase} 证据秘密扫描失败：{len(security['findings'])} 个命中。"
        )

    _, surface_binding = _load_or_build_attempt_surface(
        campaign_dir,
        attempt_root,
        attempt,
        evidence_manifest,
        label="target-official" if phase == "official" else "target-sub2api",
    )
    payload: dict[str, Any] = {
        "status": "complete",
        "campaign_mode": manifest["campaign_mode"],
        "campaign_purpose": manifest["campaign_purpose"],
        "candidate_purpose": (
            identity.get("candidate_purpose") if phase == "candidate" else None
        ),
        "identity": {
            key: value for key, value in identity.items() if key != "source_root"
        },
        "attempt": {
            "path": str((attempt_root / "attempt.json").relative_to(campaign_dir)),
            "sha256": file_sha256(attempt_root / "attempt.json"),
        },
        "results": attempt["results"],
        "evidence_roots": [str(root) for root in roots],
        "evidence_inventory": evidence_inventory,
        "evidence_manifest": {
            "path": str(manifest_path.relative_to(campaign_dir)),
            "sha256": file_sha256(manifest_path),
        },
        "scan_summary": evidence_manifest["scan"],
        "surface": surface_binding,
        "client_bindings": client_bindings,
        "assertion_context": assertion_context,
        "assertion_gate": assertion_gate,
        "restoration": restoration,
        "security": {"raw_evidence_private": raw_evidence_private, **security},
    }
    if evaluation_transition is not None:
        payload["evaluation_transition"] = evaluation_transition
    if observed_profile is not None:
        payload["observed_profile"] = observed_profile
    if phase == "official":
        binary_verification = attempt.get("binary_verification")
        if not isinstance(binary_verification, dict):
            raise ConfigurationError("官方 attempt 缺少二进制身份验证。")
        payload["binary_verification"] = binary_verification

    preview, approved = _seal_preview(
        campaign_dir,
        attempt_root,
        phase=phase,
        candidate_id=candidate_id,
        attempt=attempt,
        stage_payload=payload,
        approve_sha256=getattr(arguments, "approve_seal_sha256", None),
    )
    if not approved:
        preview_path = _seal_preview_path(
            attempt_root,
            _seal_transition_index(payload.get("evaluation_transition")),
        )
        return {
            "status": "approval_required",
            "phase": phase,
            "candidate_id": candidate_id,
            "attempt_id": attempt_id,
            "seal_preview": str(preview_path),
            "review_sha256": preview["review_sha256"],
            "message": "复核机器 finalizer 事实后，以同一摘要再次执行 seal。",
        }
    preview_path = _seal_preview_path(
        attempt_root,
        _seal_transition_index(payload.get("evaluation_transition")),
    )
    payload["seal_preview"] = {
        "path": str(preview_path.relative_to(campaign_dir)),
        "sha256": file_sha256(preview_path),
    }
    save_stage_result(
        campaign_dir,
        "capture-official" if phase == "official" else "capture-candidate",
        payload,
        candidate_id=candidate_id,
    )
    return {
        **payload,
        "status": "complete",
        "review_sha256": preview["review_sha256"],
    }


def _surface_from_stage(
    campaign_dir: Path,
    stage: str,
    *,
    candidate_id: str | None = None,
    stage_result: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    result = (
        dict(stage_result)
        if stage_result is not None
        else _load_stage_result(campaign_dir, stage, candidate_id)
    )
    reference = result.get("surface")
    if isinstance(reference, dict):
        path = _campaign_file(campaign_dir, str(reference.get("path", "")))
        if not path.is_file() or file_sha256(path) != reference.get("sha256"):
            raise ConfigurationError(f"{stage} 的表面证据摘要不一致。")
        return _read_json(path, f"{stage} 规范化表面")
    roots = [Path(value) for value in result.get("evidence_roots", [])]
    if not roots:
        raise ConfigurationError(f"{stage} 阶段缺少证据根目录。")
    label = "target-official" if stage == "capture-official" else "target-sub2api"
    surface = scan_evidence(roots, label)
    relative_root = Path("official") if stage == "capture-official" else Path("candidates") / str(candidate_id)
    output = _campaign_file(campaign_dir, str(relative_root / "surface-derived.json"))
    if output.exists():
        existing = _read_json(output, f"{stage} 派生表面")
        if _fingerprint(existing) != _fingerprint(surface):
            raise ConfigurationError(f"{stage} 派生表面与封存证据不一致。")
        return existing
    ensure_private_directory(output.parent, campaign_dir)
    secure_write_json(output, surface)
    return surface


def _analysis_payload(
    campaign_dir: Path,
    manifest: dict[str, Any],
    name: str,
) -> dict[str, Any]:
    reference = manifest["analysis"][name]
    path = _campaign_file(campaign_dir, reference["path"])
    if file_sha256(path) != reference["sha256"]:
        raise ConfigurationError(f"计划期分析摘要漂移：{name}")
    return _read_json(path, f"计划期分析 {name}")


def _validate_migration_manifest(
    migration: dict[str, Any],
    *,
    baseline_version: str,
    target_version: str,
    baseline_rules: tuple[str, ...],
    target_rules: tuple[str, ...],
    source_diff: dict[str, Any],
    official_diff: dict[str, Any],
) -> dict[str, Any]:
    if migration.get("schema_version") != MIGRATION_SCHEMA:
        raise ConfigurationError("规则迁移清单 schema_version 不受支持。")
    if migration.get("baseline_version") != baseline_version:
        raise ConfigurationError("规则迁移清单 baseline_version 不一致。")
    if migration.get("target_version") != target_version:
        raise ConfigurationError("规则迁移清单 target_version 不一致。")
    entries = migration.get("entries")
    if not isinstance(entries, list) or not entries:
        raise ConfigurationError("规则迁移清单 entries 不能为空。")
    seen_baseline: list[str] = []
    seen_target: list[str] = []
    blocked = False
    for index, entry in enumerate(entries, 1):
        if not isinstance(entry, dict):
            raise ConfigurationError(f"迁移项 {index} 必须是对象。")
        classification = entry.get("classification")
        baseline_rule = entry.get("baseline_rule")
        target_rule = entry.get("target_rule")
        if classification not in MIGRATION_CLASSIFICATIONS:
            raise ConfigurationError(f"迁移项 {index} classification 非法。")
        if baseline_rule is not None and (
            not isinstance(baseline_rule, str) or not RULE_RE.fullmatch(baseline_rule)
        ):
            raise ConfigurationError(f"迁移项 {index} baseline_rule 非法。")
        if target_rule is not None and (
            not isinstance(target_rule, str) or not RULE_RE.fullmatch(target_rule)
        ):
            raise ConfigurationError(f"迁移项 {index} target_rule 非法。")
        if classification == "add" and (baseline_rule is not None or target_rule is None):
            raise ConfigurationError("add 迁移必须只设置 target_rule。")
        if classification == "delete" and (baseline_rule is None or target_rule is not None):
            raise ConfigurationError("delete 迁移必须只设置 baseline_rule。")
        if classification in {"inherit", "change", "condition_change"} and (
            baseline_rule is None or target_rule is None
        ):
            raise ConfigurationError(f"{classification} 迁移必须同时绑定新旧规则。")
        if classification == "inherit" and baseline_rule != target_rule:
            raise ConfigurationError("inherit 迁移必须保持规则编号一致。")
        if classification == "blocked" and baseline_rule is None and target_rule is None:
            raise ConfigurationError("blocked 迁移至少要绑定一侧规则。")
        rationale = entry.get("rationale")
        if not isinstance(rationale, str) or not rationale.strip():
            raise ConfigurationError(f"迁移项 {index} 缺少 rationale。")
        evidence_refs = entry.get("evidence_refs", [])
        if not isinstance(evidence_refs, list) or not all(
            isinstance(value, str) and value for value in evidence_refs
        ):
            raise ConfigurationError(f"迁移项 {index} evidence_refs 非法。")
        if classification != "blocked" and not evidence_refs:
            raise ConfigurationError(f"迁移项 {index} 缺少证据引用。")
        if baseline_rule is not None:
            seen_baseline.append(baseline_rule)
        if target_rule is not None:
            seen_target.append(target_rule)
        blocked = blocked or classification == "blocked"
    if sorted(seen_baseline) != sorted(baseline_rules) or len(seen_baseline) != len(
        set(seen_baseline)
    ):
        raise ConfigurationError("规则迁移未使基线规则唯一闭环。")
    if sorted(seen_target) != sorted(target_rules) or len(seen_target) != len(
        set(seen_target)
    ):
        raise ConfigurationError("规则迁移未使目标规则唯一闭环。")

    expected_discoveries = {
        (source, change, item["fingerprint"])
        for source, change, values in (
            ("source", "added", source_diff.get("added", [])),
            ("source", "removed", source_diff.get("removed", [])),
            ("dynamic", "added", official_diff.get("added", [])),
            ("dynamic", "removed", official_diff.get("removed", [])),
        )
        for item in values
    }
    discoveries = migration.get("discovery_classifications", [])
    if not isinstance(discoveries, list):
        raise ConfigurationError("discovery_classifications 必须是数组。")
    seen_discoveries: list[tuple[str, str, str]] = []
    for index, item in enumerate(discoveries, 1):
        if not isinstance(item, dict):
            raise ConfigurationError(f"发现分类 {index} 必须是对象。")
        source = item.get("source")
        change = item.get("change")
        fingerprint = item.get("fingerprint")
        classification = item.get("classification")
        if (
            source not in {"source", "dynamic"}
            or change not in {"added", "removed"}
            or not SHA256_RE.fullmatch(str(fingerprint))
        ):
            raise ConfigurationError(f"发现分类 {index} 身份非法。")
        if classification not in MIGRATION_CLASSIFICATIONS:
            raise ConfigurationError(f"发现分类 {index} classification 非法。")
        target_rule = item.get("target_rule")
        if target_rule is not None and target_rule not in target_rules:
            raise ConfigurationError(f"发现分类 {index} 引用目标规则清单外编号。")
        rationale = item.get("rationale")
        if not isinstance(rationale, str) or not rationale.strip():
            raise ConfigurationError(f"发现分类 {index} 缺少 rationale。")
        evidence_refs = item.get("evidence_refs")
        if not isinstance(evidence_refs, list) or not evidence_refs or not all(
            isinstance(value, str) and value for value in evidence_refs
        ):
            raise ConfigurationError(f"发现分类 {index} 缺少证据引用。")
        allowed = (
            {"add", "change", "condition_change", "blocked"}
            if change == "added"
            else {"delete", "change", "condition_change", "blocked"}
        )
        if classification not in allowed:
            raise ConfigurationError(
                f"发现分类 {index} 的 {change}/{classification} 组合非法。"
            )
        if classification in {"add", "change", "condition_change"} and target_rule is None:
            raise ConfigurationError(f"发现分类 {index} 必须绑定 target_rule。")
        if classification == "delete" and target_rule is not None:
            raise ConfigurationError(f"发现分类 {index} delete 不能绑定 target_rule。")
        seen_discoveries.append((source, str(change), str(fingerprint)))
        blocked = blocked or classification == "blocked"
    if set(seen_discoveries) != expected_discoveries or len(seen_discoveries) != len(
        set(seen_discoveries)
    ):
        missing = sorted(expected_discoveries - set(seen_discoveries))
        extra = sorted(set(seen_discoveries) - expected_discoveries)
        raise ConfigurationError(
            f"源码／动态增删形态未唯一分类；缺失={missing}，多余={extra}。"
        )
    return {
        "blocked": blocked,
        "entry_count": len(entries),
        "discovery_count": len(discoveries),
        "unclassified_count": 0,
    }


def _classification_differences(
    campaign_dir: Path,
    manifest: dict[str, Any],
    official: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    source_diff = _analysis_payload(campaign_dir, manifest, "source-diff")
    baseline_surface = _analysis_payload(campaign_dir, manifest, "baseline-surface")
    official_surface = _surface_from_stage(
        campaign_dir,
        "capture-official",
        stage_result=official,
    )
    official_diff = compare_surfaces(baseline_surface, official_surface)
    discovery_root = ensure_private_directory(
        campaign_dir / "classification" / "discovery", campaign_dir
    )
    output = discovery_root / "baseline-to-target-official.json"
    if output.exists():
        existing = _read_json(output, "官方动态差异")
        if _fingerprint(existing) != _fingerprint(official_diff):
            raise ConfigurationError("官方动态差异与已封存证据不一致。")
    else:
        secure_write_json(output, official_diff)
    return source_diff, official_diff


def _json_pointer(path: tuple[str, ...]) -> str:
    """把 JSON 遍历路径编码为稳定、可审核的 JSON Pointer。"""

    if not path:
        return ""
    return "/" + "/".join(
        part.replace("~", "~0").replace("/", "~1") for part in path
    )


def _replace_json_string_literal(
    value: Any,
    old: str,
    new: str,
    path: tuple[str, ...] = (),
) -> tuple[Any, list[str]]:
    """只替换 JSON 字符串中的版本字面，并返回全部受影响坐标。"""

    if isinstance(value, dict):
        result: dict[str, Any] = {}
        changed: list[str] = []
        for key, child in value.items():
            replaced, child_paths = _replace_json_string_literal(
                child,
                old,
                new,
                (*path, str(key)),
            )
            result[key] = replaced
            changed.extend(child_paths)
        return result, changed
    if isinstance(value, list):
        result_list: list[Any] = []
        changed = []
        for index, child in enumerate(value):
            replaced, child_paths = _replace_json_string_literal(
                child,
                old,
                new,
                (*path, str(index)),
            )
            result_list.append(replaced)
            changed.extend(child_paths)
        return result_list, changed
    if isinstance(value, str) and old in value:
        return value.replace(old, new), [_json_pointer(path)]
    return value, []


def _json_string_paths_containing(
    value: Any,
    literal: str,
    path: tuple[str, ...] = (),
) -> list[str]:
    """列出仍含指定版本字面的所有 JSON 字符串坐标。"""

    if isinstance(value, dict):
        return [
            pointer
            for key, child in value.items()
            for pointer in _json_string_paths_containing(
                child,
                literal,
                (*path, str(key)),
            )
        ]
    if isinstance(value, list):
        return [
            pointer
            for index, child in enumerate(value)
            for pointer in _json_string_paths_containing(
                child,
                literal,
                (*path, str(index)),
            )
        ]
    if isinstance(value, str) and literal in value:
        return [_json_pointer(path)]
    return []


def _assertion_profile_version_coordinates(
    value: Any,
    path: tuple[str, ...] = (),
) -> list[tuple[str, str]]:
    """提取断言画像中具有 Codex 版本语义的字段、header/query 与 UA 坐标。"""

    coordinates: list[tuple[str, str]] = []
    if isinstance(value, dict):
        for key, child in value.items():
            child_path = (*path, str(key))
            if (
                key in {"codex_version", "client_version", "version"}
                and isinstance(child, str)
                and VERSION_RE.fullmatch(child)
            ):
                coordinates.append((_json_pointer(child_path), child))
            coordinates.extend(
                _assertion_profile_version_coordinates(child, child_path)
            )
        return coordinates
    if isinstance(value, list):
        if (
            len(value) == 2
            and isinstance(value[0], str)
            and value[0].lower() in {"client_version", "version"}
            and isinstance(value[1], str)
            and VERSION_RE.fullmatch(value[1])
        ):
            coordinates.append((_json_pointer((*path, "1")), value[1]))
        for index, child in enumerate(value):
            coordinates.extend(
                _assertion_profile_version_coordinates(
                    child,
                    (*path, str(index)),
                )
            )
        return coordinates
    if isinstance(value, str):
        matches = CODEX_USER_AGENT_VERSION_RE.finditer(value)
        for index, match in enumerate(matches, 1):
            version = next(group for group in match.groups() if group is not None)
            coordinates.append((f"{_json_pointer(path)}#ua-{index}", version))
    return coordinates


def _apply_assertion_profile_overrides(
    profile: dict[str, Any],
    *,
    target_version: str,
    base_profile_path: Path,
) -> tuple[dict[str, Any], int]:
    """把版本专属、人工审核过的期望变更确定性应用到 classify 草案。

    selector 修正属于基线画像自身的缺陷，直接修在基线画像；真正的版本行为变化
    则必须留在目标版本 override 中。这样不会为了让 0.147 通过而反向篡改 0.145
    的冻结期望，同时每个变更都要求 before 精确命中，画像漂移时会失败关闭。
    """

    path = Path(__file__).with_name(
        f"candidate_rule_expectation_overrides_{target_version.replace('.', '_')}.json"
    )
    if not path.exists():
        return profile, 0
    payload = _read_json(path, "目标版本断言期望覆盖清单")
    required = {
        "schema_version",
        "base_codex_version",
        "target_codex_version",
        "base_profile_sha256",
        "operations",
    }
    if not isinstance(payload, dict) or set(payload) != required:
        raise ConfigurationError("目标版本断言期望覆盖清单字段不闭合。")
    if payload["schema_version"] != "codex-candidate-rule-expectation-overrides/v2":
        raise ConfigurationError("目标版本断言期望覆盖清单 schema_version 不受支持。")
    if payload["base_codex_version"] != profile.get("codex_version"):
        raise ConfigurationError("目标版本断言期望覆盖清单基线版本不一致。")
    if payload["target_codex_version"] != target_version:
        raise ConfigurationError("目标版本断言期望覆盖清单目标版本不一致。")
    if payload["base_profile_sha256"] != file_sha256(base_profile_path):
        raise ConfigurationError("目标版本断言期望覆盖清单绑定的基线画像摘要不一致。")
    operations = payload["operations"]
    if not isinstance(operations, list) or not operations:
        raise ConfigurationError("目标版本断言期望覆盖清单 operations 不能为空。")

    updated = json.loads(json.dumps(profile, ensure_ascii=False))
    seen: set[tuple[str, str]] = set()
    for index, operation in enumerate(operations, 1):
        expected_keys = {"rule_id", "check_id", "before", "after", "rationale"}
        if not isinstance(operation, dict) or set(operation) != expected_keys:
            raise ConfigurationError(f"断言期望覆盖操作 {index} 字段不闭合。")
        identity = (operation["rule_id"], operation["check_id"])
        if (
            not all(isinstance(item, str) and item for item in identity)
            or identity in seen
            or not isinstance(operation["rationale"], str)
            or not operation["rationale"].strip()
        ):
            raise ConfigurationError(f"断言期望覆盖操作 {index} 身份非法或重复。")
        seen.add(identity)
        matches = [
            check
            for rule in updated.get("rules", [])
            if rule.get("rule_id") == identity[0]
            for check in rule.get("checks", [])
            if check.get("id") == identity[1]
        ]
        if len(matches) != 1:
            raise ConfigurationError(f"断言期望覆盖操作 {index} 未唯一命中 check。")
        before = operation["before"]
        after = operation["after"]
        if (
            not isinstance(before, dict)
            or not before
            or not isinstance(after, dict)
            or not after
        ):
            raise ConfigurationError(
                f"断言期望覆盖操作 {index} 的 before/after 必须是非空断言对象。"
            )
        assertion = matches[0].get("assertion")
        if not isinstance(assertion, dict) or assertion != before:
            raise ConfigurationError(f"断言期望覆盖操作 {index} 的 before 不匹配。")
        matches[0]["assertion"] = json.loads(
            json.dumps(after, ensure_ascii=False)
        )
    return updated, len(operations)


def _write_classification_draft(
    campaign_dir: Path,
    manifest: dict[str, Any],
    source_diff: dict[str, Any],
    official_diff: dict[str, Any],
) -> dict[str, Any]:
    revision = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime()) + f"-{time.time_ns() % 1_000_000_000:09d}"
    draft_root = ensure_private_directory(
        campaign_dir / "classification" / "draft" / revision, campaign_dir
    )
    rules = tuple(manifest["required_rules"])
    target_rules = {
        "schema_version": RULE_SCHEMA,
        "codex_version": manifest["target_version"],
        "required_rules": list(rules),
    }
    target_scenario_reference = manifest.get("inputs", {}).get(
        "target_discovery_scenarios"
    )
    discovery_scenarios = _read_json(
        _campaign_file(
            campaign_dir,
            (
                target_scenario_reference["path"]
                if target_scenario_reference
                else manifest["inputs"]["discovery_scenarios"]["path"]
            ),
        ),
        (
            "冻结的 target 正式采集场景清单"
            if target_scenario_reference
            else "基线发现场景清单"
        ),
    )
    scenario = json.loads(json.dumps(discovery_scenarios, ensure_ascii=False))
    draft_profile_id = f"codex-{manifest['target_version']}-draft"
    scenario["codex_version"] = manifest["target_version"]
    scenario["profile_id"] = draft_profile_id
    scenario["rule_manifest"] = {
        "path": "target-rules.json",
        "sha256": _normalized_json_sha256(target_rules),
        "rule_count": len(rules),
    }
    discoveries = [
        {
            "source": source,
            "change": change,
            "fingerprint": item["fingerprint"],
            "classification": "blocked",
            "target_rule": None,
            "evidence_refs": [
                "source-diff.json"
                if source == "source"
                else "baseline-to-target-official.json"
            ],
            "rationale": "待人工分类。",
        }
        for source, change, values in (
            ("source", "added", source_diff.get("added", [])),
            ("source", "removed", source_diff.get("removed", [])),
            ("dynamic", "added", official_diff.get("added", [])),
            ("dynamic", "removed", official_diff.get("removed", [])),
        )
        for item in values
    ]
    migration = {
        "schema_version": MIGRATION_SCHEMA,
        "baseline_version": manifest["baseline_version"],
        "target_version": manifest["target_version"],
        "status": "draft",
        "entries": [
            {
                "baseline_rule": rule,
                "target_rule": rule,
                "classification": "inherit",
                "rationale": "草案占位；必须人工复核。",
                "evidence_refs": ["source-diff.json", "baseline-to-target-official.json"],
            }
            for rule in rules
        ],
        "discovery_classifications": discoveries,
    }
    profile = {
        "schema_version": PROFILE_SCHEMA,
        "codex_version": manifest["target_version"],
        "profile_id": draft_profile_id,
        "profile_payload": {"status": "待实现并审核"},
        "profile_payload_sha256": _fingerprint({"status": "待实现并审核"}),
        "profile_digest": "0" * 64,
        "status": "draft",
    }
    baseline_profile_path = Path(__file__).with_name(
        "candidate_rule_expectations_"
        f"{manifest['baseline_version'].replace('.', '_')}.json"
    )
    assertion_profile = _read_json(baseline_profile_path, "基线断言画像")
    assertion_profile, assertion_override_count = _apply_assertion_profile_overrides(
        assertion_profile,
        target_version=manifest["target_version"],
        base_profile_path=baseline_profile_path,
    )
    assertion_profile = json.loads(
        json.dumps(assertion_profile, ensure_ascii=False)
    )
    assertion_profile["codex_version"] = manifest["target_version"]
    assertion_profile, assertion_version_paths = _replace_json_string_literal(
        assertion_profile,
        manifest["baseline_version"],
        manifest["target_version"],
    )
    secure_write_json(draft_root / "target-rules.json", target_rules)
    secure_write_json(draft_root / "rule-migration.json", migration)
    secure_write_json(draft_root / "scenarios.json", scenario)
    secure_write_json(draft_root / "profile.json", profile)
    secure_write_json(draft_root / "assertion-profile.json", assertion_profile)
    receipt = {
        "status": "draft",
        "revision": revision,
        "path": str(draft_root),
        "source_added": source_diff.get("added_count", 0),
        "dynamic_added": official_diff.get("added_count", 0),
        "blocked_discoveries": len(discoveries),
        "assertion_version_replacements": {
            "baseline_version": manifest["baseline_version"],
            "target_version": manifest["target_version"],
            "count": len(assertion_version_paths),
            "paths": assertion_version_paths,
        },
        "assertion_override_count": assertion_override_count,
    }
    secure_write_json(draft_root / "draft.json", receipt)
    return receipt


def _validate_assertion_profile_manifest(
    payload: dict[str, Any],
    *,
    baseline_version: str,
    target_version: str,
    target_rules: tuple[str, ...],
) -> None:
    """验证目标版本断言画像的规则、场景和规格摘要闭环。"""

    if payload.get("schema_version") != ASSERTION_PROFILE_SCHEMA:
        raise ConfigurationError("目标断言画像 schema_version 不受支持。")
    if payload.get("codex_version") != target_version:
        raise ConfigurationError("目标断言画像 codex_version 不一致。")
    stale_paths = _json_string_paths_containing(payload, baseline_version)
    if baseline_version != target_version and stale_paths:
        raise ConfigurationError(
            "目标断言画像仍残留 baseline 版本坐标："
            + ", ".join(stale_paths[:8])
        )
    version_coordinates = _assertion_profile_version_coordinates(payload)
    behavior_coordinates = [
        (path, version)
        for path, version in version_coordinates
        if path != "/codex_version"
    ]
    if not behavior_coordinates:
        raise ConfigurationError("目标断言画像缺少可审核的行为版本坐标。")
    mismatches = [
        (path, version)
        for path, version in behavior_coordinates
        if version != target_version
    ]
    if mismatches:
        raise ConfigurationError(
            "目标断言画像行为版本坐标与 target_version 不一致："
            + ", ".join(f"{path}={version}" for path, version in mismatches[:8])
        )
    source_spec = payload.get("source_spec")
    source_sha = payload.get("source_spec_sha256")
    if not isinstance(source_spec, str) or not SHA256_RE.fullmatch(str(source_sha)):
        raise ConfigurationError("目标断言画像规格摘要绑定非法。")
    source_path_text, separator, fragment = source_spec.partition("#")
    source_path = Path(source_path_text)
    if (
        not separator
        or source_path.is_absolute()
        or ".." in source_path.parts
        or not fragment
    ):
        raise ConfigurationError("目标断言画像 source_spec 非法。")
    resolved_source = Path(__file__).resolve().parents[2] / source_path
    if (
        not resolved_source.is_file()
        or resolved_source.is_symlink()
        or source_spec_section_sha256(resolved_source, fragment) != source_sha
    ):
        raise ConfigurationError("目标断言画像规格第二章摘要不一致。")
    scenarios = payload.get("scenarios")
    if not isinstance(scenarios, list) or not scenarios:
        raise ConfigurationError("目标断言画像 scenarios 不能为空。")
    scenario_ids = [
        item.get("scenario_id") for item in scenarios if isinstance(item, dict)
    ]
    if (
        len(scenario_ids) != len(scenarios)
        or len(scenario_ids) != len(set(scenario_ids))
        or any(not isinstance(value, str) or not value for value in scenario_ids)
    ):
        raise ConfigurationError("目标断言画像 scenario_id 非法或重复。")
    raw_rules = payload.get("rules")
    if not isinstance(raw_rules, list):
        raise ConfigurationError("目标断言画像 rules 必须是数组。")
    rule_ids: list[str] = []
    for index, rule in enumerate(raw_rules, 1):
        if not isinstance(rule, dict):
            raise ConfigurationError(f"目标断言画像规则 {index} 必须是对象。")
        rule_id = rule.get("rule_id")
        selected_scenarios = rule.get("scenario_ids")
        checks = rule.get("checks")
        if (
            not isinstance(rule_id, str)
            or not RULE_RE.fullmatch(rule_id)
            or not isinstance(selected_scenarios, list)
            or not selected_scenarios
            or not set(selected_scenarios).issubset(set(scenario_ids))
            or not isinstance(checks, list)
            or not checks
        ):
            raise ConfigurationError(f"目标断言画像规则 {index} 结构非法。")
        rule_ids.append(rule_id)
    if tuple(rule_ids) != target_rules or len(rule_ids) != len(set(rule_ids)):
        raise ConfigurationError("目标断言画像未按顺序精确覆盖目标规则全集。")


def _approved_manifest_payload(source: Path, label: str) -> dict[str, Any]:
    if not source.is_file() or source.is_symlink():
        raise ConfigurationError(f"{label}不存在或不可信：{source}")
    return _read_json(source, label)


def _normalized_json_sha256(payload: dict[str, Any]) -> str:
    encoded = (
        json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _scenario_job_execution_contract(
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    """提取全部 Job 中会改变实际执行或封存判定的字段。"""

    jobs = payload.get("capture_jobs")
    return {
        "schema_version": payload.get("schema_version"),
        "codex_version": payload.get("codex_version"),
        "jobs": [
            {
                key: value
                for key, value in job.items()
                if key in SCENARIO_JOB_EXECUTION_FIELDS
            }
            for job in (jobs if isinstance(jobs, list) else [])
            if isinstance(job, dict)
        ],
    }


def _scenario_non_execution_contract(payload: Any) -> Any:
    """移除 Job 执行字段，仅保留批准分类负责的评估语义。"""

    normalized = json.loads(json.dumps(payload, ensure_ascii=False))
    if not isinstance(normalized, dict):
        return normalized
    jobs = normalized.get("capture_jobs")
    if not isinstance(jobs, list):
        return normalized
    for job in jobs:
        if not isinstance(job, dict):
            continue
        for field in SCENARIO_JOB_EXECUTION_FIELDS - {"id"}:
            job.pop(field, None)
    return normalized


def _official_scenario_execution_contract(
    payload: dict[str, Any],
) -> dict[str, Any]:
    """提取会改变 official Attempt 实际字节或封存判定的目标场景字段。

    分类阶段允许在人工复核后调整规则归属、场景说明和 coverage；这些变化不应伪装成
    已执行过的新命令。真正影响进程、环境、证据根和必须收据的字段必须与 plan 冻结值
    完全一致，否则只能新建 Campaign。
    """

    return {
        "schema_version": payload.get("schema_version"),
        "codex_version": payload.get("codex_version"),
        "official_jobs": [
            {
                key: value
                for key, value in job.items()
                if key in SCENARIO_JOB_EXECUTION_FIELDS
            }
            for job in payload.get("capture_jobs", [])
            if isinstance(job, dict) and job.get("phase") == "official"
        ],
    }


def _approved_reference(
    campaign_dir: Path,
    destination: Path,
    payload: dict[str, Any],
) -> dict[str, str]:
    return {
        "path": destination.relative_to(campaign_dir).as_posix(),
        "sha256": _normalized_json_sha256(payload),
    }


def classify_campaign(
    campaign_dir: Path,
    *,
    target_rule_manifest: Path | None = None,
    migration_manifest: Path | None = None,
    scenario_manifest: Path | None = None,
    profile_manifest: Path | None = None,
    assertion_profile_manifest: Path | None = None,
    approve_manifest_sha256: str | None = None,
) -> dict[str, Any]:
    """把已封存官方证据转为待审核或已批准的五件套。"""

    _reject_contaminated_campaign(campaign_dir)
    manifest = _require_formal_campaign(campaign_dir)
    approval_inputs = (
        target_rule_manifest,
        migration_manifest,
        scenario_manifest,
        profile_manifest,
        assertion_profile_manifest,
    )
    approval_mode = approve_manifest_sha256 is not None or any(
        value is not None for value in approval_inputs
    )
    if approval_mode and any(value is None for value in approval_inputs):
        raise ConfigurationError(
            "批准分类必须同时提供目标规则、迁移、场景、运行画像和断言画像清单。"
        )
    _verify_plan_identity(
        campaign_dir,
        manifest,
        operation="classify",
        allow_stopped_classification_draft_approval=approval_mode,
    )
    official_summary = _load_stage_result(
        campaign_dir,
        "capture-official",
        _shallow=True,
    )
    official = _load_stage_result(
        campaign_dir,
        "capture-official",
        _skip_evidence_scan=(
            official_summary.get("predecessor_import") is not None
        ),
    )
    if official.get("status") != "complete":
        raise ConfigurationError("官方证据尚未完整封存。")
    source_diff, official_diff = _classification_differences(
        campaign_dir,
        manifest,
        official,
    )
    if not approval_mode:
        return _write_classification_draft(
            campaign_dir, manifest, source_diff, official_diff
        )
    assert all(value is not None for value in approval_inputs)
    baseline_rules = tuple(manifest["required_rules"])
    target_rules = load_rule_manifest(target_rule_manifest, manifest["target_version"])
    target_payload = _approved_manifest_payload(target_rule_manifest, "目标规则清单")
    migration = _approved_manifest_payload(migration_manifest, "规则迁移清单")
    if migration.get("status") != "approved":
        raise ConfigurationError("规则迁移清单 status 必须是 approved。")
    validation = _validate_migration_manifest(
        migration,
        baseline_version=manifest["baseline_version"],
        target_version=manifest["target_version"],
        baseline_rules=baseline_rules,
        target_rules=target_rules,
        source_diff=source_diff,
        official_diff=official_diff,
    )
    scenario_payload = _approved_manifest_payload(
        scenario_manifest, "目标场景清单"
    )
    target_scenario_reference = manifest.get("inputs", {}).get(
        "target_discovery_scenarios"
    )
    if target_scenario_reference is not None:
        frozen_target_scenario = _read_json(
            _campaign_file(campaign_dir, target_scenario_reference["path"]),
            "Formal 冻结的 target 场景清单",
        )
        if _fingerprint(
            _official_scenario_execution_contract(scenario_payload)
        ) != _fingerprint(
            _official_scenario_execution_contract(frozen_target_scenario)
        ):
            raise ConfigurationError(
                "批准的目标场景 official 执行契约与 Formal Attempt 冻结值不一致；"
                "命令或证据身份变化必须新建 Campaign。"
            )
    profile_payload = _approved_manifest_payload(profile_manifest, "目标画像清单")
    if profile_payload.get("schema_version") != PROFILE_SCHEMA:
        raise ConfigurationError("目标画像清单 schema_version 不受支持。")
    if profile_payload.get("status") != "approved":
        raise ConfigurationError("目标画像清单 status 必须是 approved。")
    if profile_payload.get("codex_version") != manifest["target_version"]:
        raise ConfigurationError("目标画像清单 codex_version 不一致。")
    if not SAFE_ID_RE.fullmatch(str(profile_payload.get("profile_id", ""))):
        raise ConfigurationError("目标画像清单 profile_id 非法。")
    if not SHA256_RE.fullmatch(str(profile_payload.get("profile_digest", ""))):
        raise ConfigurationError("目标画像清单 profile_digest 非法。")
    profile_snapshot = profile_payload.get("profile_payload")
    if not isinstance(profile_snapshot, dict) or not profile_snapshot:
        raise ConfigurationError("目标画像清单 profile_payload 不能为空。")
    if profile_payload.get("profile_payload_sha256") != _fingerprint(profile_snapshot):
        raise ConfigurationError("目标画像 profile_payload 摘要不一致。")
    if scenario_payload.get("profile_id") != profile_payload.get("profile_id"):
        raise ConfigurationError("目标场景清单 profile_id 与运行画像不一致。")
    assertion_profile_payload = _approved_manifest_payload(
        assertion_profile_manifest, "目标断言画像清单"
    )
    _validate_assertion_profile_manifest(
        assertion_profile_payload,
        baseline_version=manifest["baseline_version"],
        target_version=manifest["target_version"],
        target_rules=target_rules,
    )
    scenario_arguments = _campaign_arguments(campaign_dir, manifest)
    scenario_arguments.scenario_manifest = scenario_manifest
    scenario_context = _job_context(scenario_arguments)
    scenario_jobs = load_scenario_jobs(
        scenario_manifest,
        scenario_context,
        expected_version=manifest["target_version"],
        expected_rule_sha256=file_sha256(target_rule_manifest),
        require_bindings=True,
    )
    scenario_jobs = [
        job for job in scenario_jobs if manifest["suite"] in job.suites
    ]
    _validate_jobs(scenario_jobs, target_rules)
    if manifest["suite"] == "full":
        _validate_phase_coverage(scenario_jobs, target_rules)
    # 后继 Campaign 承接的 official 结果仍绑定前序 Campaign 的原始执行坐标。
    # ``_load_stage_result`` 已沿不可变导入链在原始目录逐项重放预约、结果和
    # execution_sha256；这里若再用后继 campaign-id、仓库路径和证据根重算哈希，
    # 会把合法的坐标重绑定误报成执行定义漂移。批准场景仍在上方与当前 Formal
    # 冻结的 target 执行契约逐摘要一致，只有非导入 official 才需再次精确比对。
    if official.get("predecessor_import") is None:
        _validate_capture_job_results(
            [job for job in scenario_jobs if job.phase == "official"],
            official.get("results"),
            phase="official",
        )
    approved_root = campaign_dir / "classification" / "approved"
    target_destination = approved_root / "target-rules.json"
    migration_destination = approved_root / "rule-migration.json"
    scenario_destination = approved_root / "scenarios.json"
    profile_destination = approved_root / "profile.json"
    assertion_profile_destination = approved_root / "assertion-profile.json"
    target_reference = _approved_reference(
        campaign_dir, target_destination, target_payload
    )
    migration_reference = _approved_reference(
        campaign_dir, migration_destination, migration
    )
    scenario_reference = _approved_reference(
        campaign_dir, scenario_destination, scenario_payload
    )
    profile_reference = _approved_reference(
        campaign_dir, profile_destination, profile_payload
    )
    assertion_profile_reference = _approved_reference(
        campaign_dir,
        assertion_profile_destination,
        assertion_profile_payload,
    )
    references = {
        "target_rule_manifest": target_reference,
        "migration_manifest": migration_reference,
        "scenario_manifest": scenario_reference,
        "profile_manifest": profile_reference,
        "assertion_profile_manifest": assertion_profile_reference,
    }
    joint_digest = _fingerprint(
        {
            key: value["sha256"] if value else None
            for key, value in references.items()
        }
    )
    if approve_manifest_sha256 is None:
        return {
            "status": "approval_required",
            "joint_manifest_sha256": joint_digest,
            "message": "复核五份目标版本清单后，以该联合摘要再次执行 classify。",
        }
    if not SHA256_RE.fullmatch(approve_manifest_sha256):
        raise ConfigurationError("--approve-manifest-sha256 格式非法。")
    if approve_manifest_sha256 != joint_digest:
        raise ConfigurationError("批准联合摘要与清单内容不一致。")
    if approved_root.exists():
        raise ConfigurationError("分类批准目录已经存在，禁止覆盖。")
    ensure_private_directory(approved_root.parent, campaign_dir)
    try:
        approved_root.mkdir(mode=0o700)
    except FileExistsError as error:
        raise ConfigurationError("分类批准目录已经存在，禁止覆盖。") from error
    secure_write_json(target_destination, target_payload)
    secure_write_json(migration_destination, migration)
    secure_write_json(scenario_destination, scenario_payload)
    secure_write_json(profile_destination, profile_payload)
    secure_write_json(assertion_profile_destination, assertion_profile_payload)
    payload = {
        "status": "blocked" if validation["blocked"] else "complete",
        **references,
        "joint_manifest_sha256": joint_digest,
        "baseline_rule_count": len(baseline_rules),
        "target_rule_count": len(target_rules),
        "migration": validation,
        "source_diff_sha256": _fingerprint(source_diff),
        "official_diff_sha256": _fingerprint(official_diff),
    }
    save_stage_result(campaign_dir, "classify", payload)
    return payload


def _canonical_file_binding(
    campaign_dir: Path,
    path: Path,
    label: str,
    *,
    maximum_bytes: int = 4 * 1024 * 1024,
) -> dict[str, Any]:
    """绑定 Campaign 内的小型普通文件，不扫描其引用的原始证据。"""

    campaign_root = campaign_dir.resolve(strict=True)
    try:
        resolved = path.resolve(strict=True)
        relative = resolved.relative_to(campaign_root).as_posix()
    except (OSError, ValueError) as error:
        raise ConfigurationError(f"{label}必须位于当前 Campaign 内。") from error
    _reject_symlink_components(resolved, campaign_root, label)
    if not resolved.is_file() or resolved.is_symlink():
        raise ConfigurationError(f"{label}不是可信普通文件。")
    size = resolved.stat().st_size
    if size < 1 or size > maximum_bytes:
        raise ConfigurationError(f"{label}大小超出小型收据上限。")
    return {"path": relative, "sha256": file_sha256(resolved), "bytes": size}


def _canonical_supervisor_deadline(
    supervisor_run_dir: Path,
) -> dict[str, float]:
    """读取父监督器原始时间锚；重启 run 不得改变该锚或 deadline。"""

    if (
        not supervisor_run_dir.is_absolute()
        or supervisor_run_dir.is_symlink()
        or not supervisor_run_dir.is_dir()
    ):
        raise ConfigurationError("--supervisor-run-dir 必须是可信绝对目录。")
    state_path = supervisor_run_dir / "state.json"
    if state_path.is_symlink() or not state_path.is_file():
        raise ConfigurationError("父监督器 state.json 不存在或不可信。")
    state = _read_json(state_path, "父监督器状态")
    start = state.get("campaign_started_at_epoch", state.get("started_at_epoch"))
    end = state.get("deadline_at_epoch")
    if (
        isinstance(start, bool)
        or not isinstance(start, (int, float))
        or isinstance(end, bool)
        or not isinstance(end, (int, float))
        or not math.isfinite(float(start))
        or not math.isfinite(float(end))
        or float(start) <= 0
        or float(end) <= float(start)
        or state.get("state") != "running"
    ):
        raise ConfigurationError("父监督器时间锚、deadline 或状态非法。")
    return {
        "started_at_epoch": float(start),
        "budget_seconds": float(end) - float(start),
        "deadline_at_epoch": float(end),
    }


def _canonical_legacy_sources(campaign_dir: Path) -> tuple[list[str], list[dict[str, Any]]]:
    """只读取固定小型旧控制对象，禁止遍历历史证据目录。"""

    candidates = (
        ("successor", campaign_dir / "predecessor-import.json"),
        ("evaluation-transition", campaign_dir / "classification-candidate-reuse-transition.json"),
        ("evaluation-transition", campaign_dir / "tool-evaluation-transition.json"),
        ("terminal-transition-preflight", campaign_dir / "terminal-transition-preflight.json"),
    )
    object_types: list[str] = []
    references: list[dict[str, Any]] = []
    for object_type, path in candidates:
        if path.exists() or path.is_symlink():
            references.append(
                _canonical_file_binding(campaign_dir, path, object_type)
            )
            object_types.append(object_type)
    epoch_root = campaign_dir / "control-epochs"
    if epoch_root.exists():
        if epoch_root.is_symlink() or not epoch_root.is_dir():
            raise ConfigurationError("历史 control-epochs 目录不可信。")
        for path in sorted(epoch_root.glob("*.json"), key=lambda value: value.name):
            object_type = (
                "runtime-repair" if "runtime-repair" in path.name else "control-epoch"
            )
            references.append(
                _canonical_file_binding(campaign_dir, path, object_type)
            )
            object_types.append(object_type)
    return sorted(set(object_types)), references


def _profile_pointer_parts(pointer: str) -> list[str]:
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise ConfigurationError("画像补丁 path 必须是 JSON Pointer。")
    return [
        part.replace("~1", "/").replace("~0", "~")
        for part in pointer[1:].split("/")
    ]


def _profile_pointer_value(document: Any, pointer: str) -> Any:
    current = document
    for part in _profile_pointer_parts(pointer):
        if isinstance(current, list):
            if not part.isdigit() or int(part) >= len(current):
                raise ConfigurationError(f"画像补丁路径不存在：{pointer}")
            current = current[int(part)]
        elif isinstance(current, dict) and part in current:
            current = current[part]
        else:
            raise ConfigurationError(f"画像补丁路径不存在：{pointer}")
    return current


def _profile_pointer_replace(document: Any, pointer: str, value: Any) -> None:
    parts = _profile_pointer_parts(pointer)
    if not parts:
        raise ConfigurationError("画像补丁不得替换文档根。")
    parent = document
    for part in parts[:-1]:
        if isinstance(parent, list):
            if not part.isdigit() or int(part) >= len(parent):
                raise ConfigurationError(f"画像补丁路径不存在：{pointer}")
            parent = parent[int(part)]
        elif isinstance(parent, dict) and part in parent:
            parent = parent[part]
        else:
            raise ConfigurationError(f"画像补丁路径不存在：{pointer}")
    leaf = parts[-1]
    if isinstance(parent, list):
        if not leaf.isdigit() or int(leaf) >= len(parent):
            raise ConfigurationError(f"画像补丁路径不存在：{pointer}")
        parent[int(leaf)] = json.loads(json.dumps(value, ensure_ascii=False))
    elif isinstance(parent, dict) and leaf in parent:
        parent[leaf] = json.loads(json.dumps(value, ensure_ascii=False))
    else:
        raise ConfigurationError(f"画像补丁路径不存在：{pointer}")


def _profile_diff_paths(before: Any, after: Any, path: tuple[str, ...] = ()) -> list[str]:
    if type(before) is not type(after):
        return [_json_pointer(path)]
    if isinstance(before, dict):
        return [
            pointer
            for key in sorted(set(before) | set(after))
            for pointer in _profile_diff_paths(
                before.get(key), after.get(key), (*path, str(key))
            )
        ]
    if isinstance(before, list):
        if len(before) != len(after):
            return [_json_pointer(path)]
        return [
            pointer
            for index, (left, right) in enumerate(zip(before, after))
            for pointer in _profile_diff_paths(left, right, (*path, str(index)))
        ]
    return [] if before == after else [_json_pointer(path)]


def validate_profile_derivation(
    *,
    active_profile_path: Path,
    target_profile_path: Path,
    migration_path: Path,
    patch_manifest_path: Path,
) -> dict[str, Any]:
    """证明目标画像等于 active 不可变副本加版本字段和差异规则补丁。"""

    for path, label in (
        (active_profile_path, "production_active 画像"),
        (target_profile_path, "目标画像清单"),
        (migration_path, "规则迁移清单"),
        (patch_manifest_path, "画像规则补丁清单"),
    ):
        if path.is_symlink() or not path.is_file():
            raise ConfigurationError(f"{label}不是可信普通文件。")
    active = _read_json(active_profile_path, "production_active 画像")
    target_manifest = _read_json(target_profile_path, "目标画像清单")
    target = target_manifest.get("profile_payload")
    if not isinstance(target, dict):
        raise ConfigurationError("目标画像清单缺少 profile_payload。")
    migration = _read_json(migration_path, "规则迁移清单")
    try:
        partition = incremental_recovery.canonical_rule_partition(migration)
    except incremental_recovery.IncrementalRecoveryError as error:
        raise ConfigurationError(str(error)) from error
    patch_manifest = _read_json(patch_manifest_path, "画像规则补丁清单")
    if set(patch_manifest) != {
        "schema_version",
        "baseline_version",
        "target_version",
        "active_profile_sha256",
        "rule_patches",
    } or patch_manifest.get("schema_version") != "codex-upgrade-profile-rule-patches/v1":
        raise ConfigurationError("画像规则补丁清单字段或 schema_version 非法。")
    baseline_version = patch_manifest.get("baseline_version")
    target_version = patch_manifest.get("target_version")
    if (
        baseline_version != active.get("Version")
        or target_version != target.get("Version")
        or target_version != target_manifest.get("codex_version")
        or patch_manifest.get("active_profile_sha256")
        != file_sha256(active_profile_path)
    ):
        raise ConfigurationError("画像规则补丁清单版本或 active 摘要不一致。")

    derived, version_paths = _replace_json_string_literal(
        json.loads(json.dumps(active, ensure_ascii=False)),
        str(baseline_version),
        str(target_version),
    )
    patches = patch_manifest.get("rule_patches")
    if not isinstance(patches, list):
        raise ConfigurationError("画像规则补丁清单 rule_patches 必须是数组。")
    if not patches and partition["affected_rule_ids"]:
        raise ConfigurationError("存在 affected rule 时 rule_patches 不能为空。")
    rule_paths: dict[str, list[str]] = {}
    seen_paths: set[str] = set()
    for index, patch in enumerate(patches, 1):
        if not isinstance(patch, Mapping) or set(patch) != {
            "rule_id",
            "path",
            "before",
            "after",
        }:
            raise ConfigurationError(f"画像规则补丁 {index} 字段不闭合。")
        rule_id = patch.get("rule_id")
        pointer = patch.get("path")
        if (
            rule_id not in partition["affected_rule_ids"]
            or not isinstance(pointer, str)
            or pointer in seen_paths
            or pointer in version_paths
        ):
            raise ConfigurationError(f"画像规则补丁 {index} 规则或路径非法。")
        if _profile_pointer_value(derived, pointer) != patch.get("before"):
            raise ConfigurationError(f"画像规则补丁 {index} before 不匹配 active 副本。")
        _profile_pointer_replace(derived, pointer, patch.get("after"))
        seen_paths.add(pointer)
        rule_paths.setdefault(str(rule_id), []).append(pointer)
    if set(rule_paths) != set(partition["affected_rule_ids"]):
        raise ConfigurationError("每条 affected rule 必须至少绑定一个画像路径。")
    if not isinstance(target.get("Digest"), str) or not SHA256_RE.fullmatch(target["Digest"]):
        raise ConfigurationError("目标画像 Digest 非法。")
    derived["Digest"] = target["Digest"]
    if derived != target:
        unexpected = _profile_diff_paths(derived, target)
        raise ConfigurationError(
            "目标画像不是 active 副本加批准补丁；未映射路径="
            + ",".join(unexpected[:12])
        )
    actual_paths = sorted(set(_profile_diff_paths(active, target)))
    allowed_paths = sorted({"/Digest", *version_paths, *seen_paths})
    if actual_paths != allowed_paths:
        raise ConfigurationError("profile_diff_paths 与版本字段/规则补丁集合不一致。")
    return {
        "schema_version": "codex-upgrade-profile-diff/v1",
        "status": "complete",
        "active_profile": {
            "path": str(active_profile_path.resolve(strict=True)),
            "sha256": file_sha256(active_profile_path),
        },
        "target_profile": {
            "path": str(target_profile_path.resolve(strict=True)),
            "sha256": file_sha256(target_profile_path),
            "profile_digest": target["Digest"],
        },
        "patch_manifest_sha256": file_sha256(patch_manifest_path),
        "total_rule_count": partition["total_rule_count"],
        "affected_rule_ids": partition["affected_rule_ids"],
        "inherited_rule_ids": partition["inherited_rule_ids"],
        "profile_diff_paths": actual_paths,
        "version_identity_paths": sorted({"/Digest", *version_paths}),
        "rule_field_paths": {
            rule_id: sorted(paths) for rule_id, paths in sorted(rule_paths.items())
        },
        "scanned_bytes": 0,
        "live_request_count": 0,
    }


def _canonical_import_subject(arguments: argparse.Namespace) -> dict[str, Any]:
    """从当前小型收据构造一次性 checkpoint，不复制或扫描原始证据。"""

    campaign_dir = arguments.campaign_dir
    _validate_existing_campaign_path(campaign_dir)
    manifest_path = campaign_dir / "campaign.json"
    manifest = _read_json(manifest_path, "Campaign 清单")
    if (
        manifest.get("campaign_mode") != "formal"
        or manifest.get("campaign_id") is None
        or manifest.get("baseline_version") is None
        or manifest.get("target_version") is None
    ):
        raise ConfigurationError("canonical 导入只允许完整 Formal Campaign。")
    if not SAFE_ID_RE.fullmatch(arguments.candidate_id):
        raise ConfigurationError("--candidate-id 格式非法。")
    if not SAFE_ID_RE.fullmatch(arguments.attempt_id):
        raise ConfigurationError("--attempt-id 格式非法。")
    retire_version = str(getattr(arguments, "retire_version", ""))
    if (
        not VERSION_RE.fullmatch(retire_version)
        or retire_version
        in {str(manifest["baseline_version"]), str(manifest["target_version"])}
    ):
        raise ConfigurationError(
            "--retire-version 必须是不同于 active rollback 和目标的旧 Previous 版本。"
        )

    classification_path = campaign_dir / "classification" / "result.json"
    classification = _read_json(classification_path, "已批准分类结果")
    migration_reference = classification.get("migration_manifest")
    if not isinstance(migration_reference, Mapping):
        raise ConfigurationError("已批准分类缺少规则迁移清单引用。")
    migration_path = _campaign_file(
        campaign_dir, str(migration_reference.get("path", ""))
    )
    migration_binding = _canonical_file_binding(
        campaign_dir,
        migration_path,
        "规则迁移清单",
    )
    if migration_binding["sha256"] != migration_reference.get("sha256"):
        raise ConfigurationError("规则迁移清单摘要漂移。")
    migration = _read_json(migration_path, "规则迁移清单")
    if migration.get("status") != "approved":
        raise ConfigurationError("规则迁移清单尚未批准。")
    try:
        partition = incremental_recovery.canonical_rule_partition(migration)
    except incremental_recovery.IncrementalRecoveryError as error:
        raise ConfigurationError(str(error)) from error
    profile_reference = classification.get("profile_manifest")
    if not isinstance(profile_reference, Mapping):
        raise ConfigurationError("已批准分类缺少目标画像引用。")
    target_profile_path = _campaign_file(
        campaign_dir, str(profile_reference.get("path", ""))
    )
    target_profile_binding = _canonical_file_binding(
        campaign_dir, target_profile_path, "目标画像清单"
    )
    if target_profile_binding["sha256"] != profile_reference.get("sha256"):
        raise ConfigurationError("目标画像清单摘要漂移。")
    profile_diff = validate_profile_derivation(
        active_profile_path=arguments.active_profile,
        target_profile_path=target_profile_path,
        migration_path=migration_path,
        patch_manifest_path=arguments.profile_patch_manifest,
    )

    attempt_root = (
        campaign_dir
        / "candidates"
        / arguments.candidate_id
        / "attempts"
        / arguments.attempt_id
    )
    attempt_path = attempt_root / "attempt.json"
    attempt_binding = _canonical_file_binding(
        campaign_dir, attempt_path, "Candidate attempt"
    )
    attempt = _read_json(attempt_path, "Candidate attempt")
    if any(
        attempt.get(field) != expected
        for field, expected in (
            ("campaign_id", manifest.get("campaign_id")),
            ("phase", "candidate"),
            ("candidate_id", arguments.candidate_id),
            ("attempt_id", arguments.attempt_id),
        )
    ) or attempt.get("status") not in {"awaiting_receipts", "complete"}:
        raise ConfigurationError("Candidate attempt 身份或状态非法。")
    incremental_plan = attempt.get("incremental_plan")
    if not isinstance(incremental_plan, Mapping):
        raise ConfigurationError("Candidate attempt 缺少增量计划。")
    plan_lists: dict[str, list[str]] = {}
    for field in (
        "planned_job_ids",
        "reused_job_ids",
        "affected_job_ids",
        "failed_job_ids",
        "pending_job_ids",
        "executed_job_ids",
    ):
        value = incremental_plan.get(field)
        if (
            not isinstance(value, list)
            or not all(
                isinstance(item, str) and SAFE_ID_RE.fullmatch(item)
                for item in value
            )
            or len(value) != len(set(value))
        ):
            raise ConfigurationError(f"Candidate attempt {field} 非法。")
        plan_lists[field] = value
    planned_job_ids = plan_lists["planned_job_ids"]
    reused_job_ids = plan_lists["reused_job_ids"]
    executed_job_ids = plan_lists["executed_job_ids"]
    if (
        not planned_job_ids
        or plan_lists["failed_job_ids"]
        or plan_lists["pending_job_ids"]
        or set(reused_job_ids).intersection(executed_job_ids)
        or set(planned_job_ids) != set(reused_job_ids) | set(executed_job_ids)
        or set(plan_lists["affected_job_ids"]) != set(executed_job_ids)
    ):
        raise ConfigurationError(
            "Candidate Job 必须成功闭合，executed 与 reused 精确覆盖计划。"
        )
    results = attempt.get("results")
    if not isinstance(results, list) or len(results) != len(planned_job_ids):
        raise ConfigurationError("Candidate Job 结果数量不闭合。")
    result_by_id = {
        str(item.get("id")): item for item in results if isinstance(item, Mapping)
    }
    if set(result_by_id) != set(planned_job_ids):
        raise ConfigurationError("Candidate Job 结果未精确覆盖计划。")

    items: list[dict[str, Any]] = []
    for job_id in sorted(planned_job_ids):
        result = result_by_id[job_id]
        disposition = "executed" if job_id in executed_job_ids else "reused"
        if (
            result.get("status") != "complete"
            or result.get("disposition") != disposition
        ):
            raise ConfigurationError(f"Candidate Job 结果未按计划完成：{job_id}")
        if disposition == "executed":
            if result.get("source_receipt") is not None:
                raise ConfigurationError(
                    f"本轮执行的 Candidate Job 不得伪装为历史复用：{job_id}"
                )
            source_binding = attempt_binding
        else:
            source = result.get("source_receipt")
            if not isinstance(source, Mapping):
                raise ConfigurationError(f"复用 Candidate Job 缺少来源：{job_id}")
            source_path = _campaign_file(campaign_dir, str(source.get("path", "")))
            source_binding = _canonical_file_binding(
                campaign_dir, source_path, f"Candidate Job {job_id} 来源"
            )
            if source_binding != dict(source):
                raise ConfigurationError(f"Candidate Job 来源摘要漂移：{job_id}")
        result_key = result.get("incremental_result_key")
        if not SHA256_RE.fullmatch(str(result_key)):
            raise ConfigurationError(f"Candidate Job result_key 非法：{job_id}")
        items.append(
            {
                "item_id": job_id,
                "status": "complete",
                "disposition": disposition,
                "result_sha256": _fingerprint(result),
                "result_key": result_key,
                "source": source_binding,
                "details": {"kind": "candidate-job"},
            }
        )

    kilo_binding = _canonical_file_binding(
        campaign_dir, arguments.kilo_facts, "Kilo 事实"
    )
    kilo = _read_json(arguments.kilo_facts, "Kilo 事实")
    kilo_identity = kilo.get("identity")
    observations = kilo.get("observations")
    if (
        not isinstance(kilo_identity, Mapping)
        or not isinstance(observations, Mapping)
        or kilo_identity.get("campaign_id") != manifest.get("campaign_id")
        or kilo_identity.get("candidate_id") != arguments.candidate_id
        or kilo_identity.get("attempt_id") != arguments.attempt_id
        or kilo_identity.get("target_version") != manifest.get("target_version")
    ):
        raise ConfigurationError("Kilo 事实身份不一致。")
    expected_kilo = {200: "kilo-compatible", 101: "kilo-responses"}
    if set(observations) != set(expected_kilo.values()):
        raise ConfigurationError("Kilo 事实未精确覆盖两种客户端入口。")
    selected: dict[int, Mapping[str, Any]] = {}
    for status, item_id in expected_kilo.items():
        observation = observations.get(item_id)
        if not isinstance(observation, Mapping) or observation.get("http_status") != status:
            raise ConfigurationError(f"Kilo 事实状态不匹配：{item_id}")
        selected[status] = observation
    for status, item_id in expected_kilo.items():
        observation = selected[status]
        items.append(
            {
                "item_id": item_id,
                "status": "complete",
                "disposition": "reused",
                "result_sha256": _fingerprint(observation),
                "result_key": _fingerprint(
                    {"identity": kilo_identity, "observation": observation}
                ),
                "source": kilo_binding,
                "details": {
                    "kind": "kilo-fact",
                    "http_status": status,
                    "usage_id": observation.get("usage_id"),
                },
            }
        )

    profile_binding = _canonical_file_binding(
        campaign_dir,
        arguments.profile_activation_fact,
        "画像激活事实",
    )
    profile_fact = _read_json(arguments.profile_activation_fact, "画像激活事实")
    if _fingerprint(profile_fact) == _fingerprint({}):
        raise ConfigurationError("画像激活事实为空。")
    items.append(
        {
            "item_id": "profile-activation",
            "status": "complete",
            "disposition": "reused",
            "result_sha256": _fingerprint(profile_fact),
            "result_key": _fingerprint(
                {"candidate_id": arguments.candidate_id, "fact": profile_fact}
            ),
            "source": profile_binding,
            "details": {"kind": "profile-activation"},
        }
    )
    items.append(
        {
            "item_id": "profile-diff-gate",
            "status": "complete",
            "disposition": "reused",
            "result_sha256": _fingerprint(profile_diff),
            "result_key": _fingerprint(
                {
                    "active": profile_diff["active_profile"]["sha256"],
                    "target": profile_diff["target_profile"]["sha256"],
                    "patch": profile_diff["patch_manifest_sha256"],
                }
            ),
            "source": target_profile_binding,
            "details": {
                "kind": "profile-diff",
                "profile_diff_paths": profile_diff["profile_diff_paths"],
                "version_identity_paths": profile_diff["version_identity_paths"],
                "rule_field_paths": profile_diff["rule_field_paths"],
            },
        }
    )

    migration_entries = {
        str(entry.get("target_rule")): entry
        for entry in migration.get("entries", [])
        if isinstance(entry, Mapping) and entry.get("classification") == "inherit"
    }
    if set(migration_entries) != set(partition["inherited_rule_ids"]):
        raise ConfigurationError("继承规则迁移收据未精确覆盖 inherited_rule_ids。")
    for rule_id in partition["inherited_rule_ids"]:
        entry = migration_entries[rule_id]
        items.append(
            {
                "item_id": f"inherit-{rule_id}",
                "status": "complete",
                "disposition": "reused",
                "result_sha256": _fingerprint(entry),
                "result_key": _fingerprint(
                    {
                        "migration_manifest_sha256": migration_binding["sha256"],
                        "entry": entry,
                    }
                ),
                "source": migration_binding,
                "details": {
                    "kind": "inherited-rule",
                    "rule_id": rule_id,
                    "classification": "inherit",
                },
            }
        )

    evidence_manifest_path = attempt_root / "evidence-manifest.json"
    evidence_manifest = (
        _canonical_file_binding(
            campaign_dir, evidence_manifest_path, "EvidenceManifest"
        )
        if evidence_manifest_path.exists() or evidence_manifest_path.is_symlink()
        else None
    )
    source_kind = "native" if executed_job_ids else "historical-import"
    if source_kind == "historical-import":
        legacy_types, legacy_refs = _canonical_legacy_sources(campaign_dir)
    else:
        legacy_types, legacy_refs = [], []
    next_items = [
        "candidate-seal",
        "compare",
        *[f"assert-{rule_id}" for rule_id in partition["affected_rule_ids"]],
        "acceptance",
        "production-activation",
        "rollback-verification",
        f"retire-{retire_version}",
    ]
    return {
        "campaign": {
            "campaign_id": str(manifest["campaign_id"]),
            "campaign_manifest_sha256": file_sha256(manifest_path),
            "baseline_version": str(manifest["baseline_version"]),
            "target_version": str(manifest["target_version"]),
            "candidate_id": arguments.candidate_id,
            "attempt_id": arguments.attempt_id,
        },
        "phase": arguments.phase,
        "migration": {
            "manifest_sha256": migration_binding["sha256"],
            **partition,
        },
        "plan": {
            "execute_item_ids": next_items,
            "reused_item_ids": sorted(item["item_id"] for item in items),
        },
        "items": sorted(items, key=lambda item: item["item_id"]),
        "evidence_manifest": evidence_manifest,
        "deadline": _canonical_supervisor_deadline(arguments.supervisor_run_dir),
        "source": {
            "kind": source_kind,
            "legacy_object_types": legacy_types,
            "receipt_refs": [attempt_binding, *legacy_refs],
        },
        "metrics": {"scanned_bytes": 0, "live_request_count": 0},
    }


def import_canonical_checkpoint(arguments: argparse.Namespace) -> dict[str, Any]:
    """预览或封存一次性初始化；执行过程中不发请求、不扫证据。"""

    subject = _canonical_import_subject(arguments)
    review_sha256 = _fingerprint(subject)
    summary = {
        **subject["migration"],
        **subject["plan"],
        "source_kind": subject["source"]["kind"],
        "review_sha256": review_sha256,
        "scanned_bytes": 0,
        "live_request_count": 0,
    }
    if arguments.approve_import_sha256 is None:
        return {"status": "approval_required", **summary}
    if arguments.approve_import_sha256 != review_sha256:
        raise ConfigurationError("canonical 导入批准摘要不匹配。")

    canonical_root = arguments.campaign_dir / CANONICAL_DIRECTORY
    ensure_private_directory(canonical_root, arguments.campaign_dir)
    checkpoint_root = canonical_root / CANONICAL_CHECKPOINT_DIRECTORY
    try:
        store = incremental_recovery.CanonicalCheckpointStore(checkpoint_root)
        existing = store.latest()
    except incremental_recovery.IncrementalRecoveryError as error:
        raise ConfigurationError(str(error)) from error
    receipt_path = canonical_root / CANONICAL_IMPORT_RECEIPT_FILENAME
    if existing is None:
        try:
            checkpoint = store.append(
                {"recorded_at_utc": _utc_now(), **subject}
            )
        except incremental_recovery.IncrementalRecoveryError as error:
            raise ConfigurationError(str(error)) from error
    else:
        unsigned_existing = {
            key: value
            for key, value in existing.items()
            if key
            not in {
                "schema_version",
                "checkpoint_sequence",
                "previous_checkpoint_sha256",
                "checkpoint_sha256",
                "recorded_at_utc",
            }
        }
        if _fingerprint(unsigned_existing) != review_sha256:
            raise ConfigurationError("canonical checkpoint 已存在且导入主题不同。")
        checkpoint = existing
    receipt = {
        "schema_version": CANONICAL_IMPORT_RECEIPT_SCHEMA,
        "status": "complete",
        "review_sha256": review_sha256,
        "imported_at_utc": checkpoint["recorded_at_utc"],
        "checkpoint": {
            "path": (
                Path(CANONICAL_CHECKPOINT_DIRECTORY)
                / f"{checkpoint['checkpoint_sequence']:08d}.json"
            ).as_posix(),
            "sha256": checkpoint["checkpoint_sha256"],
        },
        "source_kind": subject["source"]["kind"],
        "scanned_bytes": 0,
        "live_request_count": 0,
    }
    if receipt_path.exists():
        if _read_json(receipt_path, "canonical 导入收据") != receipt:
            raise ConfigurationError("canonical 导入收据已经存在且内容不同。")
    else:
        _secure_write_json_once(receipt_path, receipt)
    return {"status": "complete", **summary, "checkpoint": receipt["checkpoint"]}


def _canonical_latest_checkpoint(campaign_dir: Path) -> dict[str, Any]:
    """读取最新 canonical checkpoint；只校验小型聚合记录。"""

    try:
        store = incremental_recovery.CanonicalCheckpointStore(
            campaign_dir / CANONICAL_DIRECTORY / CANONICAL_CHECKPOINT_DIRECTORY,
            create=False,
        )
        checkpoint = store.latest()
    except incremental_recovery.IncrementalRecoveryError as error:
        raise ConfigurationError(str(error)) from error
    if checkpoint is None:
        raise ConfigurationError("canonical checkpoint 尚未建立。")
    return checkpoint


def _canonical_item_index(checkpoint: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
    """返回已完成项索引，并拒绝重复或非对象记录。"""

    items = checkpoint.get("items")
    if not isinstance(items, list):
        raise ConfigurationError("canonical checkpoint items 非法。")
    output: dict[str, dict[str, Any]] = {}
    for item in items:
        if not isinstance(item, dict) or not isinstance(item.get("item_id"), str):
            raise ConfigurationError("canonical checkpoint item 非法。")
        item_id = str(item["item_id"])
        if item_id in output:
            raise ConfigurationError(f"canonical checkpoint item 重复：{item_id}")
        output[item_id] = item
    return output


def _canonical_step_receipt(
    campaign_dir: Path,
    item_id: str,
    body: Mapping[str, Any],
) -> tuple[dict[str, Any], Path]:
    """写入一份不可覆盖的小型步骤收据；重复调用只允许内容完全一致。"""

    if not SAFE_ID_RE.fullmatch(item_id):
        raise ConfigurationError("canonical item_id 格式非法。")
    receipt_root = ensure_private_directory(
        campaign_dir / CANONICAL_DIRECTORY / "receipts",
        campaign_dir,
    )
    path = receipt_root / f"{item_id}.json"
    fixed = {
        "schema_version": CANONICAL_STEP_RECEIPT_SCHEMA,
        "item_id": item_id,
        **dict(body),
    }
    if path.exists() or path.is_symlink():
        if path.is_symlink() or not path.is_file():
            raise ConfigurationError(f"canonical 步骤收据路径不可信：{item_id}")
        existing = _read_json(path, f"canonical 步骤收据 {item_id}")
        comparable = dict(existing)
        comparable.pop("recorded_at_utc", None)
        if comparable != fixed:
            raise ConfigurationError(f"canonical 步骤收据已存在且内容不同：{item_id}")
        return existing, path
    receipt = {**fixed, "recorded_at_utc": _utc_now()}
    _secure_write_json_once(path, receipt)
    return receipt, path


def _canonical_complete_item(
    campaign_dir: Path,
    *,
    item_id: str,
    receipt_path: Path,
    result_key: str,
    details: Mapping[str, Any],
    phase: str = "VC-5",
) -> dict[str, Any]:
    """完成一个计划项并立即追加 checkpoint，不重写既有记录。"""

    checkpoint = _canonical_latest_checkpoint(campaign_dir)
    index = _canonical_item_index(checkpoint)
    source = _canonical_file_binding(
        campaign_dir,
        receipt_path,
        f"canonical {item_id} 收据",
    )
    if item_id in index:
        existing = index[item_id]
        if (
            existing.get("source") != source
            or existing.get("result_sha256") != source["sha256"]
            or existing.get("result_key") != result_key
            or existing.get("details") != dict(details)
        ):
            raise ConfigurationError(f"canonical 已完成项发生漂移：{item_id}")
        return checkpoint
    execute = list(checkpoint["plan"]["execute_item_ids"])
    if item_id not in execute:
        raise ConfigurationError(f"canonical 计划不允许执行：{item_id}")
    if not SHA256_RE.fullmatch(result_key):
        raise ConfigurationError(f"canonical result_key 非法：{item_id}")
    item = {
        "item_id": item_id,
        "status": "complete",
        "disposition": "executed",
        "result_sha256": source["sha256"],
        "result_key": result_key,
        "source": source,
        "details": dict(details),
    }
    record = {
        "recorded_at_utc": _utc_now(),
        "campaign": checkpoint["campaign"],
        "phase": phase,
        "migration": checkpoint["migration"],
        "plan": {
            "execute_item_ids": sorted(value for value in execute if value != item_id),
            "reused_item_ids": sorted(
                [*checkpoint["plan"]["reused_item_ids"], item_id]
            ),
        },
        "items": sorted([*checkpoint["items"], item], key=lambda row: row["item_id"]),
        "evidence_manifest": checkpoint["evidence_manifest"],
        "deadline": checkpoint["deadline"],
        "source": checkpoint["source"],
        "metrics": dict(checkpoint["metrics"]),
    }
    if record["metrics"].get("live_request_count") != 0:
        raise ConfigurationError("canonical VC-5 禁止新增 live 请求。")
    try:
        return incremental_recovery.CanonicalCheckpointStore(
            campaign_dir / CANONICAL_DIRECTORY / CANONICAL_CHECKPOINT_DIRECTORY,
            create=False,
        ).append(record)
    except incremental_recovery.IncrementalRecoveryError as error:
        raise ConfigurationError(str(error)) from error


def _canonical_candidate_seal(campaign_dir: Path, checkpoint: Mapping[str, Any]) -> dict[str, Any]:
    """只聚合已导入事实，生成零扫描 Candidate seal。"""

    index = _canonical_item_index(checkpoint)
    if "candidate-seal" in index:
        source = index["candidate-seal"]["source"]
        receipt = _read_json(
            _campaign_file(campaign_dir, str(source["path"])),
            "canonical Candidate seal",
        )
        return {**receipt, "checkpoint_sha256": checkpoint["checkpoint_sha256"]}
    candidate_jobs = sorted(
        item_id
        for item_id, item in index.items()
        if item.get("details", {}).get("kind") == "candidate-job"
    )
    kilo = sorted(
        int(item.get("details", {}).get("http_status"))
        for item in index.values()
        if item.get("details", {}).get("kind") == "kilo-fact"
    )
    required_kinds = {"profile-activation", "profile-diff"}
    observed_kinds = {
        str(item.get("details", {}).get("kind")) for item in index.values()
    }
    execute = set(checkpoint["plan"]["execute_item_ids"])
    if (
        not candidate_jobs
        or kilo != [101, 200]
        or not required_kinds.issubset(observed_kinds)
        or set(candidate_jobs).intersection(execute)
        or checkpoint["metrics"] != {"scanned_bytes": 0, "live_request_count": 0}
    ):
        raise ConfigurationError("canonical Candidate seal 输入边界不闭合。")
    body = {
        "status": "complete",
        "candidate_id": checkpoint["campaign"]["candidate_id"],
        "attempt_id": checkpoint["campaign"]["attempt_id"],
        "input_checkpoint_sha256": checkpoint["checkpoint_sha256"],
        "candidate_job_ids": candidate_jobs,
        "kilo_http_statuses": kilo,
        "scanned_bytes": 0,
        "live_request_count": 0,
    }
    receipt, path = _canonical_step_receipt(
        campaign_dir, "candidate-seal", body
    )
    completed = _canonical_complete_item(
        campaign_dir,
        item_id="candidate-seal",
        receipt_path=path,
        result_key=_fingerprint(body),
        details={"kind": "candidate-seal"},
    )
    return {
        **receipt,
        "checkpoint_sha256": completed["checkpoint_sha256"],
    }


def _canonical_compare(campaign_dir: Path, checkpoint: Mapping[str, Any]) -> dict[str, Any]:
    """比较摘要并只为 affected rules 生成离线断言收据。"""

    index = _canonical_item_index(checkpoint)
    affected = list(checkpoint["migration"]["affected_rule_ids"])
    inherited = list(checkpoint["migration"]["inherited_rule_ids"])
    inherited_items = {f"inherit-{rule_id}" for rule_id in inherited}
    profile_items = [
        item
        for item in index.values()
        if item.get("details", {}).get("kind") == "profile-diff"
    ]
    if (
        "candidate-seal" not in index
        or not inherited_items.issubset(index)
        or len(profile_items) != 1
    ):
        raise ConfigurationError("canonical compare 缺少 seal、画像差异或继承收据。")
    profile_details = profile_items[0]["details"]
    rule_paths = profile_details.get("rule_field_paths")
    if not isinstance(rule_paths, Mapping) or set(rule_paths) != set(affected):
        raise ConfigurationError("canonical compare 的 affected rule 路径不闭合。")
    body = {
        "status": "complete",
        "equal": True,
        "offline_only": True,
        "candidate_id": checkpoint["campaign"]["candidate_id"],
        "input_checkpoint_sha256": checkpoint["checkpoint_sha256"],
        "affected_rule_ids": affected,
        "inherited_rule_ids": inherited,
        "profile_diff_paths": profile_details.get("profile_diff_paths"),
        "historical_raw_evidence_scanned_bytes": 0,
        "live_request_count": 0,
    }
    if "compare" in index:
        receipt = _read_json(
            _campaign_file(campaign_dir, str(index["compare"]["source"]["path"])),
            "canonical compare",
        )
        current = dict(checkpoint)
    else:
        receipt, path = _canonical_step_receipt(campaign_dir, "compare", body)
        current = _canonical_complete_item(
            campaign_dir,
            item_id="compare",
            receipt_path=path,
            result_key=_fingerprint(body),
            details={"kind": "compare", "affected_rule_ids": affected},
        )
    candidate_jobs = sorted(
        item_id
        for item_id, item in index.items()
        if item.get("details", {}).get("kind") == "candidate-job"
    )
    kilo_items = sorted(
        item_id
        for item_id, item in index.items()
        if item.get("details", {}).get("kind") == "kilo-fact"
    )
    for rule_id in affected:
        current = _canonical_latest_checkpoint(campaign_dir)
        assertion_id = f"assert-{rule_id}"
        if assertion_id in _canonical_item_index(current):
            continue
        assertion_body = {
            "status": "passed",
            "rule_id": rule_id,
            "input_checkpoint_sha256": current["checkpoint_sha256"],
            "profile_field_paths": sorted(rule_paths[rule_id]),
            "reused_candidate_job_ids": candidate_jobs,
            "reused_kilo_item_ids": kilo_items,
            "historical_raw_evidence_scanned_bytes": 0,
            "live_request_count": 0,
        }
        assertion, assertion_path = _canonical_step_receipt(
            campaign_dir, assertion_id, assertion_body
        )
        current = _canonical_complete_item(
            campaign_dir,
            item_id=assertion_id,
            receipt_path=assertion_path,
            result_key=_fingerprint(assertion_body),
            details={"kind": "affected-rule-assertion", "rule_id": rule_id},
        )
    return {
        **receipt,
        "affected_assertion_count": len(affected),
        "inherited_receipt_count": len(inherited),
        "checkpoint_sha256": current["checkpoint_sha256"],
    }


def _canonical_accept(campaign_dir: Path, checkpoint: Mapping[str, Any]) -> dict[str, Any]:
    """验收两类规则收据；继承规则不执行机器命令。"""

    index = _canonical_item_index(checkpoint)
    if "acceptance" in index:
        receipt = _read_json(
            _campaign_file(campaign_dir, str(index["acceptance"]["source"]["path"])),
            "canonical acceptance",
        )
        return {**receipt, "checkpoint_sha256": checkpoint["checkpoint_sha256"]}
    affected = list(checkpoint["migration"]["affected_rule_ids"])
    inherited = list(checkpoint["migration"]["inherited_rule_ids"])
    affected_items = {f"assert-{rule_id}" for rule_id in affected}
    inherited_items = {f"inherit-{rule_id}" for rule_id in inherited}
    required = {"candidate-seal", "compare", *affected_items, *inherited_items}
    execute = set(checkpoint["plan"]["execute_item_ids"])
    candidate_jobs = {
        item_id
        for item_id, item in index.items()
        if item.get("details", {}).get("kind") == "candidate-job"
    }
    if (
        not required.issubset(index)
        or affected_items.intersection(execute)
        or inherited_items.intersection(execute)
        or candidate_jobs.intersection(execute)
        or checkpoint["metrics"].get("live_request_count") != 0
    ):
        raise ConfigurationError("canonical acceptance 执行／复用边界不闭合。")
    body = {
        "status": "complete",
        "accepted": True,
        "production_state": "accepted_not_activated",
        "candidate_id": checkpoint["campaign"]["candidate_id"],
        "attempt_id": checkpoint["campaign"]["attempt_id"],
        "input_checkpoint_sha256": checkpoint["checkpoint_sha256"],
        "affected_rule_ids": affected,
        "executed_affected_assertion_ids": sorted(affected_items),
        "inherited_rule_ids": inherited,
        "replayed_inherited_receipt_ids": sorted(inherited_items),
        "historical_raw_evidence_scanned_bytes": 0,
        "live_request_count": 0,
    }
    receipt, path = _canonical_step_receipt(campaign_dir, "acceptance", body)
    completed = _canonical_complete_item(
        campaign_dir,
        item_id="acceptance",
        receipt_path=path,
        result_key=_fingerprint(body),
        details={
            "kind": "acceptance",
            "affected_rule_count": len(affected),
            "inherited_rule_count": len(inherited),
        },
    )
    return {**receipt, "checkpoint_sha256": completed["checkpoint_sha256"]}


def _canonical_activation_receipt(
    campaign_dir: Path,
    checkpoint: Mapping[str, Any],
    receipt_path: Path,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """重放生产激活收据，并绑定本轮 canonical acceptance。"""

    binding = _canonical_file_binding(
        campaign_dir, receipt_path, "canonical 生产激活收据"
    )
    try:
        receipt = production_activation_receipt.replay(
            receipt_path.parent.resolve(strict=True), receipt_path.name
        )
    except (OSError, production_activation_receipt.ProductionReceiptError) as error:
        raise ConfigurationError(f"生产激活收据无法重放：{error}") from error
    index = _canonical_item_index(checkpoint)
    acceptance = index.get("acceptance")
    campaign = receipt.get("campaign")
    target = receipt.get("target")
    rollback = receipt.get("rollback")
    final_state = receipt.get("final_state")
    stages = receipt.get("stages")
    if (
        not isinstance(acceptance, Mapping)
        or not isinstance(campaign, Mapping)
        or campaign.get("id") != checkpoint["campaign"]["campaign_id"]
        or campaign.get("candidate_id") != checkpoint["campaign"]["candidate_id"]
        or not isinstance(campaign.get("acceptance"), Mapping)
        or campaign["acceptance"].get("sha256")
        != acceptance.get("source", {}).get("sha256")
        or not isinstance(target, Mapping)
        or target.get("version") != checkpoint["campaign"]["target_version"]
        or not isinstance(rollback, Mapping)
        or rollback.get("version") != checkpoint["campaign"]["baseline_version"]
        or not isinstance(final_state, Mapping)
        or final_state.get("active_version") != target.get("version")
        or final_state.get("image_id") != target.get("image_id")
        or not isinstance(stages, list)
        or [stage.get("name") for stage in stages if isinstance(stage, Mapping)]
        != ["canary", "production_switch", "rollback", "target_restore"]
        or any(
            not isinstance(stage, Mapping) or stage.get("status") != "pass"
            for stage in stages
        )
    ):
        raise ConfigurationError("生产激活收据未绑定本轮 acceptance、目标、回滚或恢复终态。")
    return receipt, binding


def _canonical_production_step(
    campaign_dir: Path,
    checkpoint: Mapping[str, Any],
    step: str,
    receipt_path: Path | None,
    retire_version: str | None,
) -> dict[str, Any]:
    """只从已重放的生产收据推进 VC-6，不触碰 VC-0～VC-5。"""

    if receipt_path is None:
        raise ConfigurationError(f"canonical {step} 必须提供 --step-receipt。")
    index = _canonical_item_index(checkpoint)
    if "acceptance" not in index:
        raise ConfigurationError("canonical VC-6 必须从已接受 checkpoint 开始。")
    if step in {"production-activation", "rollback-verification"}:
        if retire_version is not None:
            raise ConfigurationError(f"canonical {step} 不接收 --retire-version。")
        receipt, binding = _canonical_activation_receipt(
            campaign_dir, checkpoint, receipt_path
        )
        if step == "rollback-verification" and "production-activation" not in index:
            raise ConfigurationError("必须先登记 production-activation。")
        stages = {stage["name"]: stage for stage in receipt["stages"]}
        details: dict[str, Any] = {
            "kind": step,
            "target_version": receipt["target"]["version"],
            "rollback_version": receipt["rollback"]["version"],
        }
        if step == "production-activation":
            details["final_image_id"] = receipt["final_state"]["image_id"]
        else:
            details.update(
                {
                    "rollback_image_id": stages["rollback"]["image_id"],
                    "restored_image_id": stages["target_restore"]["image_id"],
                }
            )
        completed = _canonical_complete_item(
            campaign_dir,
            item_id=step,
            receipt_path=receipt_path,
            result_key=_fingerprint({"step": step, "receipt": binding}),
            details=details,
            phase="VC-6",
        )
        return {
            "status": "complete",
            "item_id": step,
            "receipt_sha256": binding["sha256"],
            "checkpoint_sha256": completed["checkpoint_sha256"],
        }

    if step != "retire":
        raise ConfigurationError("canonical production step 非法。")
    if retire_version is None or not VERSION_RE.fullmatch(retire_version):
        raise ConfigurationError("canonical retire 必须提供合法 --retire-version。")
    item_id = f"retire-{retire_version}"
    if item_id not in checkpoint["plan"]["execute_item_ids"]:
        raise ConfigurationError("退休版本与 canonical 初始化冻结的计划不一致。")
    if not {"production-activation", "rollback-verification"}.issubset(index):
        raise ConfigurationError(
            f"删除 {retire_version} 前必须完成生产激活、回滚和目标恢复。"
        )
    binding = _canonical_file_binding(
        campaign_dir, receipt_path, f"{retire_version} RemovalReceipt"
    )
    receipt = _read_json(receipt_path, f"{retire_version} RemovalReceipt")
    scan = receipt.get("consumer_scan")
    if (
        receipt.get("schema_version") != CANONICAL_REMOVAL_RECEIPT_SCHEMA
        or receipt.get("status") != "complete"
        or receipt.get("campaign_id") != checkpoint["campaign"]["campaign_id"]
        or receipt.get("active_version") != checkpoint["campaign"]["target_version"]
        or receipt.get("rollback_version") != checkpoint["campaign"]["baseline_version"]
        or receipt.get("removed_version") != retire_version
        or receipt.get("production_activation_sha256")
        != index["production-activation"]["source"]["sha256"]
        or not isinstance(scan, Mapping)
        or set(scan)
        != {"catalog_references", "selector_references", "unknown_references"}
        or any(scan.get(key) != 0 for key in scan)
        or receipt.get("runtime_catalog_removed") is not True
        or receipt.get("historical_evidence_preserved") is not True
    ):
        raise ConfigurationError(
            f"{retire_version} RemovalReceipt 未证明零消费者、运行态删除和历史保留。"
        )
    completed = _canonical_complete_item(
        campaign_dir,
        item_id=item_id,
        receipt_path=receipt_path,
        result_key=_fingerprint({"step": item_id, "receipt": binding}),
        details={"kind": "runtime-profile-removal", "removed_version": retire_version},
        phase="VC-6",
    )
    return {
        "status": "complete",
        "item_id": item_id,
        "receipt_sha256": binding["sha256"],
        "checkpoint_sha256": completed["checkpoint_sha256"],
    }


def advance_canonical_checkpoint(arguments: argparse.Namespace) -> dict[str, Any]:
    """按固定 VC-5 拓扑推进 canonical checkpoint。"""

    campaign_dir = arguments.campaign_dir
    _validate_existing_campaign_path(campaign_dir)
    checkpoint = _canonical_latest_checkpoint(campaign_dir)
    campaign = checkpoint["campaign"]
    if (
        arguments.candidate_id != campaign.get("candidate_id")
        or arguments.attempt_id != campaign.get("attempt_id")
    ):
        raise ConfigurationError("canonical advance 的 Candidate／attempt 身份不一致。")
    step_receipt = getattr(arguments, "step_receipt", None)
    if arguments.canonical_step == "seal":
        if step_receipt is not None:
            raise ConfigurationError("canonical seal 不接收 --step-receipt。")
        return _canonical_candidate_seal(campaign_dir, checkpoint)
    if arguments.canonical_step == "compare":
        if step_receipt is not None:
            raise ConfigurationError("canonical compare 不接收 --step-receipt。")
        return _canonical_compare(campaign_dir, checkpoint)
    if arguments.canonical_step == "accept":
        if step_receipt is not None:
            raise ConfigurationError("canonical accept 不接收 --step-receipt。")
        return _canonical_accept(campaign_dir, checkpoint)
    if arguments.canonical_step in CANONICAL_PRODUCTION_STEPS:
        return _canonical_production_step(
            campaign_dir,
            checkpoint,
            arguments.canonical_step,
            step_receipt,
            getattr(arguments, "retire_version", None),
        )
    raise ConfigurationError("canonical step 非法。")


def _profile_binding_from_manifest(
    campaign_dir: Path,
    classification: dict[str, Any],
) -> tuple[str | None, str | None]:
    reference = classification.get("profile_manifest")
    if not isinstance(reference, dict):
        return None, None
    path = _campaign_file(campaign_dir, str(reference.get("path", "")))
    if not path.is_file() or file_sha256(path) != reference.get("sha256"):
        raise ConfigurationError("批准画像清单摘要不一致。")
    profile = _read_json(path, "批准画像清单")
    profile_id = profile.get("profile_id") or profile.get("id")
    profile_digest = profile.get("profile_digest") or profile.get("digest")
    if isinstance(profile.get("profile"), dict):
        profile_id = profile_id or profile["profile"].get("id")
        profile_digest = profile_digest or profile["profile"].get("digest")
    return (
        str(profile_id) if profile_id is not None else None,
        str(profile_digest) if profile_digest is not None else None,
    )


def prepare_profile_manifest(
    campaign_dir: Path,
    snapshot: Path,
    profile_id: str,
    output: Path,
) -> dict[str, Any]:
    """把官方取证形成的完整 Snapshot 规范化为 classify 审核输入。"""

    _require_formal_campaign(campaign_dir)
    _validate_existing_campaign_path(campaign_dir)
    _reject_contaminated_campaign(campaign_dir)
    manifest = load_campaign_manifest(campaign_dir)
    _verify_plan_identity(campaign_dir, manifest)
    if campaign_status(campaign_dir, None).get("status") != "official_sealed":
        raise ConfigurationError("prepare-profile 只允许从 official_sealed 状态执行。")
    if not SAFE_ID_RE.fullmatch(profile_id):
        raise ConfigurationError("--profile-id 格式非法。")
    if not snapshot.is_file() or snapshot.is_symlink():
        raise ConfigurationError("--snapshot 必须是非符号链接普通文件。")
    if not output.is_absolute() or output.is_symlink() or output.exists():
        raise ConfigurationError("--output 必须是不存在的非符号链接绝对路径。")
    resolved_output = output.resolve(strict=False)
    if resolved_output in {
        Path("/").resolve(),
        Path.home().resolve(),
        Path("/tmp").resolve(),
    }:
        raise ConfigurationError("--output 不能是根目录、HOME 或 /tmp 本身。")
    try:
        resolved_output.relative_to(campaign_dir.resolve(strict=True))
    except ValueError:
        pass
    else:
        raise ConfigurationError("画像草案不得写入不可变 Campaign 目录。")
    repository_root = Path(__file__).resolve().parents[2]
    completed = _run_external_command(
        [
            "go",
            "run",
            "./cmd/egresscatalogstage",
            "-prepare-snapshot",
            str(snapshot),
            "-prepare-profile-id",
            profile_id,
            "-prepare-output",
            str(output),
        ],
        cwd=repository_root / "backend",
        timeout_seconds=PROFILE_GENERATOR_TIMEOUT_SECONDS,
        check=False,
        capture_output=True,
        text=True,
        operation="prepare-profile:generator",
    )
    if completed.returncode != 0:
        detail = (completed.stderr or "").strip() or (completed.stdout or "").strip()
        raise ConfigurationError("画像草案生成器失败：" + (detail or "无错误输出"))
    try:
        profile = json.loads(completed.stdout)
    except json.JSONDecodeError as error:
        raise ConfigurationError("画像草案生成器未返回合法 JSON。") from error
    if (
        not isinstance(profile, dict)
        or profile.get("status") != "draft"
        or profile.get("codex_version") != manifest["target_version"]
        or profile.get("profile_id") != profile_id
        or not SHA256_RE.fullmatch(str(profile.get("profile_digest", "")))
        or not output.is_file()
        or output.is_symlink()
        or _fingerprint(_read_json(output, "画像草案")) != _fingerprint(profile)
    ):
        raise ConfigurationError("画像草案身份、版本或落盘内容不一致。")
    profile["output"] = str(output)
    return profile


def stage_profile_catalog(campaign_dir: Path, output: Path) -> dict[str, Any]:
    """验证 profile_approved 身份并调用 Go 契约生成离线候选目录。"""

    _require_formal_campaign(campaign_dir)
    _validate_existing_campaign_path(campaign_dir)
    _reject_contaminated_campaign(campaign_dir)
    manifest = load_campaign_manifest(campaign_dir)
    _verify_plan_identity(campaign_dir, manifest)
    status = campaign_status(campaign_dir, None)
    if status.get("status") != "profile_approved":
        raise ConfigurationError("stage-profile 只允许从 profile_approved 状态执行。")
    classification = _load_stage_result(campaign_dir, "classify")
    if (
        classification.get("status") != "complete"
        or classification.get("migration", {}).get("unclassified_count") != 0
    ):
        raise ConfigurationError("分类尚未完整批准或仍有未分类项。")
    references = {
        key: classification.get(key)
        for key in (
            "target_rule_manifest",
            "migration_manifest",
            "scenario_manifest",
            "profile_manifest",
            "assertion_profile_manifest",
        )
    }
    for label, reference in references.items():
        if not isinstance(reference, dict):
            raise ConfigurationError(f"批准分类缺少引用：{label}")
        approved_path = _campaign_file(
            campaign_dir,
            str(reference.get("path", "")),
        )
        if (
            not approved_path.is_file()
            or approved_path.is_symlink()
            or file_sha256(approved_path) != reference.get("sha256")
        ):
            raise ConfigurationError(f"批准分类引用摘要不一致：{label}")
    joint_digest = _fingerprint(
        {
            key: reference["sha256"]
            for key, reference in references.items()
            if isinstance(reference, dict)
        }
    )
    if joint_digest != classification.get("joint_manifest_sha256"):
        raise ConfigurationError("五份批准清单联合摘要不一致。")
    profile_reference = references["profile_manifest"]
    assert isinstance(profile_reference, dict)
    profile_path = _campaign_file(campaign_dir, profile_reference["path"])
    profile = _read_json(profile_path, "批准画像清单")
    if (
        profile.get("status") != "approved"
        or profile.get("codex_version") != manifest.get("target_version")
        or not SHA256_RE.fullmatch(str(profile.get("profile_digest", "")))
    ):
        raise ConfigurationError("批准画像身份不完整或与 Campaign 目标版本不一致。")

    if not output.is_absolute() or output.is_symlink():
        raise ConfigurationError("--output 必须是非符号链接绝对路径。")
    resolved_output = output.resolve(strict=False)
    if resolved_output in {
        Path("/").resolve(),
        Path.home().resolve(),
        Path("/tmp").resolve(),
    }:
        raise ConfigurationError("--output 不能是根目录、HOME 或 /tmp 本身。")
    if output.exists():
        raise ConfigurationError("--output 已存在，禁止覆盖候选目录。")
    try:
        resolved_output.relative_to(campaign_dir.resolve(strict=True))
    except ValueError:
        pass
    else:
        raise ConfigurationError("候选 RuntimeCatalog 不得写入不可变 Campaign 目录。")

    repository_root = Path(__file__).resolve().parents[2]
    backend_root = repository_root / "backend"
    command = [
        "go",
        "run",
        "./cmd/egresscatalogstage",
        "-profile-manifest",
        str(profile_path),
        "-campaign-id",
        str(manifest["campaign_id"]),
        "-classification-sha256",
        joint_digest,
        "-output",
        str(output),
    ]
    completed = _run_external_command(
        command,
        cwd=backend_root,
        timeout_seconds=PROFILE_GENERATOR_TIMEOUT_SECONDS,
        check=False,
        capture_output=True,
        text=True,
        operation="stage-profile:generator",
    )
    if completed.returncode != 0:
        detail = (completed.stderr or "").strip() or (completed.stdout or "").strip()
        raise ConfigurationError(
            "候选 RuntimeCatalog 生成器失败：" + (detail or "无错误输出")
        )
    try:
        receipt = json.loads(completed.stdout)
    except json.JSONDecodeError as error:
        raise ConfigurationError("候选 RuntimeCatalog 生成器未返回合法收据。") from error
    if (
        not isinstance(receipt, dict)
        or receipt.get("campaign_id") != manifest["campaign_id"]
        or receipt.get("classification_sha256") != joint_digest
        or receipt.get("target_version") != manifest["target_version"]
        or receipt.get("target_profile_digest") != profile["profile_digest"]
        or receipt.get("active_unchanged") is not True
        or receipt.get("production_selector_changed") is not False
        or receipt.get("candidate_release_mode") != "previous"
    ):
        raise ConfigurationError("候选 RuntimeCatalog 收据身份或权限边界不一致。")
    _verify_catalog_stage_output(output, receipt)
    receipt["output"] = str(output)
    return receipt


def _verify_catalog_stage_output(output: Path, receipt: dict[str, Any]) -> None:
    """逐文件重算候选目录，拒绝收据与落盘资产分离。"""

    if not output.is_dir() or output.is_symlink():
        raise ConfigurationError("候选 RuntimeCatalog 输出目录不存在或不可信。")
    receipt_path = output / "catalog-stage-receipt.json"
    if not receipt_path.is_file() or receipt_path.is_symlink():
        raise ConfigurationError("候选 RuntimeCatalog 缺少可信生成收据。")
    stored_receipt = _read_json(receipt_path, "候选 RuntimeCatalog 收据")
    if _fingerprint(stored_receipt) != _fingerprint(receipt):
        raise ConfigurationError("候选 RuntimeCatalog 标准输出与落盘收据不一致。")
    inventory = receipt.get("inventory")
    if not isinstance(inventory, list) or not inventory:
        raise ConfigurationError("候选 RuntimeCatalog inventory 为空。")
    if _fingerprint(inventory) != receipt.get("inventory_sha256"):
        raise ConfigurationError("候选 RuntimeCatalog inventory 摘要不一致。")
    seen: set[str] = set()
    for item in inventory:
        if not isinstance(item, dict):
            raise ConfigurationError("候选 RuntimeCatalog inventory 条目非法。")
        relative_raw = item.get("path")
        if not isinstance(relative_raw, str):
            raise ConfigurationError("候选 RuntimeCatalog inventory 路径非法。")
        relative = Path(relative_raw)
        if (
            relative.is_absolute()
            or relative.as_posix() != relative_raw
            or ".." in relative.parts
            or relative_raw in seen
        ):
            raise ConfigurationError("候选 RuntimeCatalog inventory 路径越界或重复。")
        seen.add(relative_raw)
        target = output / relative
        if (
            not target.is_file()
            or target.is_symlink()
            or file_sha256(target) != item.get("sha256")
            or target.stat().st_size != item.get("size")
        ):
            raise ConfigurationError(
                f"候选 RuntimeCatalog inventory 文件漂移：{relative_raw}"
            )
    actual = {
        path.relative_to(output).as_posix()
        for path in output.rglob("*")
        if path.is_file() and path.name != "catalog-stage-receipt.json"
    }
    if actual != seen:
        raise ConfigurationError("候选 RuntimeCatalog inventory 未精确覆盖输出文件。")


def _verify_stage_evidence(
    stage: dict[str, Any],
    label: str,
    *,
    campaign_dir: Path | None = None,
) -> None:
    expected_inventory = stage.get("evidence_inventory")
    if not isinstance(expected_inventory, dict):
        raise ConfigurationError(f"{label}缺少封存证据清单。")
    roots = [Path(value) for value in stage.get("evidence_roots", [])]
    if not roots:
        raise ConfigurationError(f"{label}缺少证据根。")
    if stage.get("evidence_manifest") is not None:
        if campaign_dir is None:
            raise ConfigurationError(f"{label}EvidenceManifest 校验缺少 Campaign 路径。")
        _stage_evidence_manifest(
            campaign_dir,
            stage,
            verify_boundary=True,
        )
        return
    current = _evidence_inventory(roots)
    if current["digest"] != expected_inventory.get("digest"):
        raise ConfigurationError(f"{label}原始证据摘要在封存后发生变化。")
    security = stage.get("security")
    if (
        not isinstance(security, dict)
        or security.get("raw_evidence_private") is not True
        or security.get("known_secret_scan_passed") is not True
    ):
        raise ConfigurationError(f"{label}秘密扫描门禁未通过。")
    current_security = _evidence_security(roots)
    if not current_security.get("known_secret_scan_passed"):
        raise ConfigurationError(f"{label}当前证据秘密扫描未通过。")
    if not _evidence_permissions_private(roots):
        raise ConfigurationError(f"{label}当前证据权限不再私有。")


def _verify_sealed_official_binaries(
    official: dict[str, Any], manifest: dict[str, Any]
) -> bool:
    verification = official.get("binary_verification")
    identities = verification.get("identities") if isinstance(verification, dict) else None
    helpers = verification.get("helpers") if isinstance(verification, dict) else None
    expected_labels = {
        "container:capture_codex_bin",
        "container:relay_codex_bin",
        "host:relay_codex_bin",
    }
    expected_helper_labels = {
        "container:capture_code_mode_host_bin",
        "container:relay_code_mode_host_bin",
        "host:relay_code_mode_host_bin",
    }
    package_identity = manifest.get("official_identity", {}).get("package")
    return bool(
        isinstance(verification, dict)
        and verification.get("passed") is True
        and verification.get("expected_version") == manifest.get("target_version")
        and verification.get("expected_sha256") == manifest.get("target_sha256")
        and verification.get("runtime_image_reference")
        == manifest.get("official_identity", {}).get("runtime_image")
        and IMAGE_ID_RE.fullmatch(str(verification.get("runtime_image_id", "")))
        and isinstance(identities, list)
        and {item.get("label") for item in identities if isinstance(item, dict)}
        == expected_labels
        and all(
            isinstance(item, dict)
            and item.get("version") == manifest.get("target_version")
            and item.get("sha256") == manifest.get("target_sha256")
            for item in identities
        )
        and isinstance(package_identity, dict)
        and verification.get("package") == package_identity
        and isinstance(helpers, list)
        and {item.get("label") for item in helpers if isinstance(item, dict)}
        == expected_helper_labels
        and all(
            isinstance(item, dict)
            and item.get("sha256")
            == package_identity.get("code_mode_host_sha256")
            for item in helpers
        )
    )


def _capture_stage_attempt_context(
    campaign_dir: Path,
    stage: Mapping[str, Any],
    *,
    phase: str,
    candidate_id: str | None,
) -> tuple[Path, dict[str, Any]]:
    reference = stage.get("attempt")
    _require_file_binding(reference, "抓包 attempt")
    attempt_path = _campaign_file(campaign_dir, str(reference["path"]))
    attempt_root, attempt = _load_capture_attempt(
        campaign_dir,
        phase,
        candidate_id,
        attempt_path.parent.name,
    )
    if attempt_path != attempt_root / "attempt.json":
        raise ConfigurationError("抓包阶段 attempt 绑定路径不一致。")
    return attempt_root, attempt


def compare_campaign(campaign_dir: Path, candidate_id: str) -> dict[str, Any]:
    """只读取封存材料并写比较收据；本函数不运行任何命令或网络请求。"""

    _reject_contaminated_campaign(campaign_dir)
    manifest = _require_formal_campaign(campaign_dir)
    candidate = _load_stage_result(
        campaign_dir, "capture-candidate", candidate_id
    )
    attempt_root, attempt = _capture_stage_attempt_context(
        campaign_dir,
        candidate,
        phase="candidate",
        candidate_id=candidate_id,
    )
    _bind_active_lease_attempt(
        campaign_dir,
        phase="candidate",
        candidate_id=candidate_id,
        attempt_id=attempt.get("attempt_id"),
    )
    _verify_plan_identity(
        campaign_dir,
        manifest,
        operation="compare",
        attempt_root=attempt_root,
        attempt=attempt,
    )
    official = _load_stage_result(campaign_dir, "capture-official")
    classification = _load_stage_result(campaign_dir, "classify")
    for label, value in (
        ("官方", official),
        ("分类", classification),
        ("候选", candidate),
    ):
        if value.get("status") != "complete":
            raise ConfigurationError(f"{label}阶段尚未完整封存。")
    if not official.get("restoration", {}).get("passed"):
        raise ConfigurationError("官方抓包环境恢复门禁未通过。")
    if not candidate.get("restoration", {}).get("passed"):
        raise ConfigurationError("候选抓包环境恢复门禁未通过。")
    if not _verify_sealed_official_binaries(official, manifest):
        raise ConfigurationError("官方抓包未绑定全部目标 Codex 二进制身份。")
    _verify_stage_evidence(official, "官方", campaign_dir=campaign_dir)
    _verify_stage_evidence(candidate, "候选", campaign_dir=campaign_dir)
    official_surface = _surface_from_stage(campaign_dir, "capture-official")
    candidate_surface = _surface_from_stage(
        campaign_dir, "capture-candidate", candidate_id=candidate_id
    )
    difference = compare_surfaces(official_surface, candidate_surface)
    rules = _approved_rules(campaign_dir, manifest, require_approved=True)
    official_jobs = _campaign_jobs(
        campaign_dir,
        manifest,
        "official",
        use_approved_scenario=True,
    )
    candidate_identity = candidate.get("identity", {})
    candidate_jobs = _campaign_jobs(
        campaign_dir,
        manifest,
        "candidate",
        candidate_id=candidate_id,
        runtime_image=str(candidate_identity.get("image_reference", "")),
        profile_id=str(candidate_identity.get("profile_id", "")),
        profile_digest=str(candidate_identity.get("profile_digest", "")),
        build_id=str(candidate_identity.get("build_id", "")),
        deployed_version=str(candidate_identity.get("deployed_version", "")),
        candidate_image_id=str(candidate_identity.get("image_id", "")),
        source_tree_sha256=str(candidate_identity.get("source_tree_sha256", "")),
        candidate_purpose=str(candidate_identity.get("candidate_purpose", "")),
    )
    # 后继 Campaign 的官方结果仍属于前序 Campaign 的原始执行坐标；导入门禁已用
    # 前序 ID 和冻结场景逐项重放 execution_sha256。这里不能把它伪装成新 ID 下执行，
    # 只继续用同一场景／规则集合计算覆盖。
    if official.get("predecessor_import") is None:
        _validate_capture_job_results(
            official_jobs,
            official.get("results"),
            phase="official",
        )
    _validate_capture_job_results(
        candidate_jobs,
        candidate.get("results"),
        phase="candidate",
    )
    results = list(official.get("results", [])) + list(candidate.get("results", []))
    coverage = build_coverage(rules, official_jobs + candidate_jobs, results)
    if not coverage.get("complete"):
        raise ConfigurationError("官方／候选逐规则抓包覆盖不完整。")
    approved_profile_id, approved_profile_digest = _profile_binding_from_manifest(
        campaign_dir, classification
    )
    candidate_profile_id = candidate_identity.get("profile_id")
    candidate_profile_digest = candidate_identity.get("profile_digest")
    profile_binding_matches = bool(candidate_profile_id and candidate_profile_digest)
    if approved_profile_id is not None:
        profile_binding_matches = (
            profile_binding_matches and candidate_profile_id == approved_profile_id
        )
    if approved_profile_digest is not None:
        profile_binding_matches = (
            profile_binding_matches
            and candidate_profile_digest == approved_profile_digest
        )
    report = {
        "schema_version": COMPARISON_SCHEMA,
        "status": "complete",
        "candidate_id": candidate_id,
        "campaign_mode": manifest["campaign_mode"],
        "campaign_purpose": manifest["campaign_purpose"],
        "candidate_purpose": candidate_identity.get("candidate_purpose"),
        "target_version": manifest["target_version"],
        "equal": difference["equal"],
        "official_to_candidate": difference,
        "coverage": coverage,
        "official_package_digest": official["package_digest"],
        "candidate_package_digest": candidate["package_digest"],
        "classification_package_digest": classification["package_digest"],
        "official_evidence_inventory_digest": official["evidence_inventory"]["digest"],
        "candidate_evidence_inventory_digest": candidate["evidence_inventory"]["digest"],
        "profile_id": candidate_profile_id,
        "profile_digest": candidate_profile_digest,
        "profile_binding_matches": profile_binding_matches,
        "offline_only": True,
    }
    assertion_root = ensure_private_directory(
        campaign_dir / "assertions" / candidate_id, campaign_dir
    )
    skeleton_path = assertion_root / "results.template.json"
    _, comparison_path = _stage_path(campaign_dir, "compare", candidate_id)
    if comparison_path.exists():
        sealed = _load_stage_result(campaign_dir, "compare", candidate_id)
        for field, expected in report.items():
            if field == "schema_version":
                continue
            if sealed.get(field) != expected:
                raise ConfigurationError("既有比较收据与当前封存证据不一致。")
    else:
        save_stage_result(campaign_dir, "compare", report, candidate_id=candidate_id)
        sealed = _load_stage_result(campaign_dir, "compare", candidate_id)
    machine_root = ensure_private_directory(
        assertion_root / "machine",
        campaign_dir,
    )
    ensure_private_directory(machine_root / "official", campaign_dir)
    ensure_private_directory(machine_root / "candidate", campaign_dir)
    validation_modes = _acceptance_validation_modes(
        campaign_dir, classification, rules
    )
    official_authority = _classification_official_authority(classification)
    template_rules: list[dict[str, Any]] = []
    for rule in rules:
        official_output = machine_root / "official" / f"{rule}.json"
        candidate_output = machine_root / "candidate" / f"{rule}.json"
        row: dict[str, Any] = {
            "rule": rule,
            "validation_mode": validation_modes[rule],
            "status": "blocked",
            "candidate_evidence_refs": [],
            "candidate_machine_result": {
                "path": candidate_output.relative_to(campaign_dir).as_posix(),
                "sha256": None,
            },
            "candidate_command": _campaign_machine_command(
                campaign_dir,
                manifest,
                classification,
                candidate,
                rule=rule,
                output=candidate_output,
                side="candidate",
            ),
            "evidence_level": "unreviewed",
            "rationale": "待执行机器断言并复核。",
        }
        if validation_modes[rule] == "dual_wire":
            row["official_evidence_refs"] = []
            row["official_machine_result"] = {
                "path": official_output.relative_to(campaign_dir).as_posix(),
                "sha256": None,
            }
            row["official_command"] = _campaign_machine_command(
                campaign_dir,
                manifest,
                classification,
                official,
                rule=rule,
                output=official_output,
                side="official",
            )
        else:
            row["official_authority"] = dict(official_authority)
        template_rules.append(row)
    skeleton = {
        "schema_version": ASSERTION_TEMPLATE_SCHEMA,
        "document_kind": "template",
        "candidate_id": candidate_id,
        "target_version": manifest["target_version"],
        "profile_id": candidate_profile_id,
        "profile_digest": candidate_profile_digest,
        "official_package_digest": official["package_digest"],
        "candidate_package_digest": candidate["package_digest"],
        "comparison_package_digest": sealed["package_digest"],
        "rules": template_rules,
    }
    if skeleton_path.exists():
        existing_skeleton = _read_json(skeleton_path, "逐规则断言模板")
        if _fingerprint(existing_skeleton) != _fingerprint(skeleton):
            raise ConfigurationError("逐规则断言模板已经存在且内容不同。")
    else:
        secure_write_json(skeleton_path, skeleton)
    report["assertion_template"] = str(skeleton_path)
    return report


def _compare_result_exit_code(result: Mapping[str, Any]) -> int:
    """把比较收据状态映射为 CLI 退出码。

    ``equal`` 只表示官方与候选 surface 集合是否完全相同；采集计划不同
    时允许它为 ``false``。只要比较已完整封存、全程离线、规则覆盖完整且
    profile 绑定正确，后续逐规则断言仍可继续，因此不能把这种合法结果
    当作 compare 失败。
    """

    coverage = result.get("coverage")
    if (
        result.get("status") == "complete"
        and result.get("offline_only") is True
        and isinstance(coverage, Mapping)
        and coverage.get("complete") is True
        and result.get("profile_binding_matches") is True
    ):
        return 0
    return 2


def _acceptance_contract(
    campaign_dir: Path,
    classification: dict[str, Any],
) -> dict[str, Any]:
    """从本 Campaign **批准的**断言画像机器推导验收契约。

    权威是 classify 阶段人工批准并摘要绑定的 `assertion-profile.json`，不是仓库
    冻结画像——目标规则集允许相对基线增删，契约必须随批准画像走。仓库冻结摘要
    只用于 seal 前预检与工具自检（见 `acceptance_contract.FROZEN_CONTRACT_SHA256`）。
    """

    reference = classification.get("assertion_profile_manifest")
    if not isinstance(reference, dict):
        raise ConfigurationError("分类收据缺少批准断言画像。")
    path = _campaign_file(campaign_dir, str(reference.get("path", "")))
    if path.is_symlink() or not path.is_file() or file_sha256(path) != reference.get(
        "sha256"
    ):
        raise ConfigurationError("批准断言画像在封存后漂移或丢失。")
    try:
        return build_acceptance_contract(load_acceptance_profile(path))
    except AcceptanceContractError as error:
        raise ConfigurationError(f"验收契约不可用：{error}") from error


def _acceptance_validation_modes(
    campaign_dir: Path,
    classification: dict[str, Any],
    rules: tuple[str, ...],
) -> dict[str, str]:
    """推导每条规则的 validation_mode；规则集与批准画像不符即失败关闭。"""

    modes = _acceptance_contract(campaign_dir, classification)["validation_modes"]
    missing = sorted(set(rules) - set(modes))
    extra = sorted(set(modes) - set(rules))
    if missing or extra:
        raise ConfigurationError(
            f"目标规则集与批准断言画像不一致：缺失 {missing}，多余 {extra}。"
        )
    return {rule: modes[rule] for rule in rules}


def _acceptance_contract_sha256(
    campaign_dir: Path,
    classification: dict[str, Any],
) -> str:
    return acceptance_contract_sha256(
        _acceptance_contract(campaign_dir, classification)
    )


def _acceptance_expected_check_ids(
    campaign_dir: Path,
    classification: dict[str, Any],
    rule: str,
    side: str,
) -> list[str]:
    """本侧应执行的 check 全集；侧别限定项由验收契约按登记依据剔除。"""

    contract = _acceptance_contract(campaign_dir, classification)
    expected = contract["expected_check_ids"].get(rule)
    if not isinstance(expected, list) or not expected:
        raise ConfigurationError(f"批准断言画像缺少规则 {rule} 的 check 全集。")
    try:
        return expected_check_ids_for_side(contract, rule, side)
    except AcceptanceContractError as error:
        raise ConfigurationError(f"批准断言画像 check 全集不可用：{error}") from error


def _classification_official_authority(
    classification: dict[str, Any],
) -> dict[str, str]:
    """candidate_profile 行的官方权威：批准画像链的三个逐字摘要。"""

    reference = classification.get("assertion_profile_manifest")
    if not isinstance(reference, dict) or not SHA256_RE.fullmatch(
        str(reference.get("sha256", ""))
    ):
        raise ConfigurationError("分类收据缺少批准断言画像摘要。")
    package_digest = classification.get("package_digest")
    joint = classification.get("joint_manifest_sha256")
    if not SHA256_RE.fullmatch(str(package_digest or "")):
        raise ConfigurationError("分类收据缺少 classification package digest。")
    if not SHA256_RE.fullmatch(str(joint or "")):
        raise ConfigurationError("分类收据缺少批准联合摘要。")
    return {
        "assertion_profile_sha256": str(reference["sha256"]),
        "classification_package_digest": str(package_digest),
        "review_sha256": str(joint),
    }


def _inventory_index(stage: dict[str, Any], label: str) -> dict[str, str]:
    inventory = stage.get("evidence_inventory")
    if not isinstance(inventory, dict) or not isinstance(inventory.get("entries"), list):
        raise ConfigurationError(f"{label}阶段缺少封存证据清单。")
    result: dict[str, str] = {}
    for entry in inventory["entries"]:
        if not isinstance(entry, dict):
            raise ConfigurationError(f"{label}证据清单条目非法。")
        path = entry.get("path")
        digest = entry.get("sha256")
        if (
            not isinstance(path, str)
            or not path
            or not SHA256_RE.fullmatch(str(digest))
            or path in result
        ):
            raise ConfigurationError(f"{label}证据清单路径或摘要非法。")
        result[path] = str(digest)
    if not result:
        raise ConfigurationError(f"{label}证据清单为空。")
    return result


def _physical_evidence_index(stage: dict[str, Any], label: str) -> dict[str, Path]:
    roots = [Path(value) for value in stage.get("evidence_roots", [])]
    if not roots:
        raise ConfigurationError(f"{label}阶段缺少证据根。")
    index = {logical: path for logical, path in _evidence_files(roots)}
    if not index:
        raise ConfigurationError(f"{label}阶段当前证据为空。")
    return index


def _legacy_attempt_relative_evidence_path(
    stage: dict[str, Any],
    reference_path: str,
    *,
    label: str,
) -> Path | None:
    """兼容旧 seal draft 的 attempt-relative ``evidence/`` 路径。

    旧 draft 在单根证据时代把当前 attempt 根内的文件写成
    ``evidence/<relative>``；新版多根 EvidenceManifest 会把同一文件编码为
    ``<prefix>/<relative>``。这里只允许从当前阶段绑定的 attempt 身份推导唯一
    ``attempts/<id>/evidence`` 根，并重新执行根内、非符号链接和唯一性校验。
    普通逻辑路径、其他 attempt 或越界路径不会进入兼容分支。
    """

    prefix = "evidence/"
    if not reference_path.startswith(prefix):
        return None
    parsed = PurePosixPath(reference_path)
    relative = PurePosixPath(reference_path[len(prefix) :])
    if (
        parsed.is_absolute()
        or "\\" in reference_path
        or not relative.parts
        or str(parsed) != reference_path
        or any(part in {"", ".", ".."} for part in relative.parts)
    ):
        raise ConfigurationError(f"{label}旧 evidence 路径非法。")

    attempt_reference = stage.get("attempt")
    attempt_path = (
        attempt_reference.get("path")
        if isinstance(attempt_reference, Mapping)
        else None
    )
    if not isinstance(attempt_path, str) or not attempt_path:
        raise ConfigurationError(f"{label}缺少当前 attempt 绑定，无法兼容旧路径。")
    attempt_parts = PurePosixPath(attempt_path).parts
    if (
        len(attempt_parts) < 3
        or attempt_parts[-1] != "attempt.json"
        or attempt_parts[-2] in {"", ".", ".."}
    ):
        raise ConfigurationError(f"{label}当前 attempt 绑定路径非法。")
    attempt_id = attempt_parts[-2]

    candidates: list[Path] = []
    raw_roots = stage.get("evidence_roots")
    if not isinstance(raw_roots, list):
        raise ConfigurationError(f"{label}阶段证据根非法，无法兼容旧路径。")
    for raw_root in raw_roots:
        if not isinstance(raw_root, str):
            continue
        root = Path(raw_root)
        if (
            root.name != "evidence"
            or root.parent.name != attempt_id
            or root.is_symlink()
            or not root.is_dir()
        ):
            continue
        candidate = root / Path(*relative.parts)
        try:
            resolved_root = root.resolve(strict=True)
            resolved_candidate = candidate.resolve(strict=True)
            resolved_candidate.relative_to(resolved_root)
        except (OSError, RuntimeError, ValueError):
            continue
        if candidate.is_symlink() or not candidate.is_file():
            continue
        candidates.append(resolved_candidate)
    if len(candidates) != 1:
        raise ConfigurationError(
            f"{label}旧 evidence 路径未唯一绑定当前 attempt（候选数={len(candidates)}）。"
        )
    return candidates[0]


def _bound_evidence_path(
    stage: dict[str, Any],
    reference: Any,
    *,
    label: str,
) -> Path:
    _require_file_binding(reference, label)
    path = _physical_evidence_index(stage, label).get(reference["path"])
    if path is None:
        path = _legacy_attempt_relative_evidence_path(
            stage,
            reference["path"],
            label=label,
        )
    if path is None or file_sha256(path) != reference["sha256"]:
        raise ConfigurationError(f"{label}证据文件漂移或丢失。")
    return path


def _candidate_stage_receipt_boundary(
    campaign_dir: Path,
    stage: dict[str, Any],
) -> tuple[dict[str, Any], Path, str]:
    """从阶段绑定的 attempt 推导收据根与 Kilo 后时间上界。"""

    attempt_reference = stage.get("attempt")
    _require_file_binding(attempt_reference, "候选 attempt")
    attempt_relative = Path(str(attempt_reference["path"]))
    attempt_id = attempt_relative.parent.name
    candidate_id = str(stage.get("candidate_id", ""))
    _, attempt = _load_capture_attempt(
        campaign_dir,
        "candidate",
        candidate_id,
        attempt_id,
    )
    environment = attempt.get("environment")
    if not isinstance(environment, dict):
        raise ConfigurationError("候选 attempt 缺少环境证据边界。")
    evidence_root = Path(str(environment.get("evidence_root", "")))
    stage_roots = {
        Path(value).resolve(strict=True)
        for value in stage.get("evidence_roots", [])
    }
    if (
        not evidence_root.is_absolute()
        or evidence_root.is_symlink()
        or not evidence_root.is_dir()
        or evidence_root.resolve(strict=True) not in stage_roots
    ):
        raise ConfigurationError("候选 attempt 收据根未绑定当前阶段。")
    checkpoint_path = (
        evidence_root
        / "environment"
        / "client-after"
        / "probe-manifest.json"
    )
    if checkpoint_path.is_symlink() or not checkpoint_path.is_file():
        raise ConfigurationError("候选阶段缺少 Kilo 后探针清单。")
    checkpoint = _read_json(checkpoint_path, "Kilo 后探针清单")
    checkpoint_at = checkpoint.get("observed_at_utc")
    if checkpoint.get("phase") != "after" or not _is_rfc3339_timestamp(
        checkpoint_at
    ):
        raise ConfigurationError("Kilo 后探针清单身份或时间非法。")
    if _rfc3339_datetime(
        checkpoint_at, "Kilo 后检查点时间"
    ) < _rfc3339_datetime(
        attempt["completed_at_utc"], "attempt.completed_at_utc"
    ):
        raise ConfigurationError("Kilo 后检查点早于候选 run 完成时间。")
    return attempt, evidence_root.resolve(strict=True), str(checkpoint_at)


def _replay_capture_stage_receipts(
    campaign_dir: Path,
    stage: dict[str, Any],
    label: str,
) -> None:
    """在 status／compare／accept 每次读取时重放机器 finalizer。"""

    roots = [Path(value) for value in stage.get("evidence_roots", [])]
    campaign = load_campaign_manifest(campaign_dir)
    phase = "candidate" if stage.get("stage") == "capture-candidate" else "official"
    candidate_id = stage.get("candidate_id") if phase == "candidate" else None
    restoration_path = _bound_evidence_path(
        stage,
        stage.get("restoration", {}).get("report"),
        label=f"{label}环境恢复报告",
    )
    restoration = _validate_restoration_report(
        restoration_path,
        roots,
        phase=phase,
        candidate_id=candidate_id,
    )
    sealed_restoration = stage.get("restoration")
    if not isinstance(sealed_restoration, dict):
        raise ConfigurationError(f"{label}环境恢复门禁缺失。")
    capture_restoration = {
        key: value
        for key, value in sealed_restoration.items()
        if key != "post_client"
    }
    if _fingerprint(restoration) != _fingerprint(capture_restoration):
        raise ConfigurationError(f"{label}环境恢复机器收据与阶段封存内容不一致。")
    if phase == "official":
        return

    post_client = sealed_restoration.get("post_client")
    if not isinstance(post_client, dict):
        raise ConfigurationError(f"{label}缺少 Kilo 后恢复门禁。")
    post_client_path = _bound_evidence_path(
        stage,
        post_client.get("report"),
        label=f"{label}Kilo 后恢复报告",
    )
    replayed_post_client = _validate_restoration_report(
        post_client_path,
        roots,
        phase="candidate",
        candidate_id=str(candidate_id),
    )
    if _fingerprint(replayed_post_client) != _fingerprint(post_client):
        raise ConfigurationError(f"{label}Kilo 后恢复机器收据与封存内容不一致。")

    identity = stage.get("identity")
    if not isinstance(identity, dict):
        raise ConfigurationError(f"{label}候选身份缺失。")
    attempt, receipt_root, client_checkpoint_at = (
        _candidate_stage_receipt_boundary(campaign_dir, stage)
    )
    observed_path = _bound_evidence_path(
        stage,
        stage.get("observed_profile"),
        label=f"{label}运行画像观测",
    )
    observed_binding, _ = _validate_observed_profile_receipt(
        observed_path,
        [receipt_root],
        campaign_id=attempt["campaign_id"],
        attempt_id=attempt["attempt_id"],
        run_nonce=attempt["run_nonce"],
        attempt_started_at_utc=attempt["started_at_utc"],
        client_checkpoint_at_utc=client_checkpoint_at,
        candidate_id=str(candidate_id),
        target_version=campaign["target_version"],
        expected_profile_id=str(identity.get("profile_id", "")),
        expected_profile_digest=str(identity.get("profile_digest", "")),
        image_id=str(identity.get("image_id", "")),
        image_reference=str(identity.get("image_reference", "")),
        source_tree_sha256=str(identity.get("source_tree_sha256", "")),
        build_id=str(identity.get("build_id", "")),
        deployed_version=str(identity.get("deployed_version", "")),
    )
    if observed_binding != stage.get("observed_profile"):
        raise ConfigurationError(f"{label}运行画像绑定与阶段封存内容不一致。")
    client_bindings = stage.get("client_bindings")
    if not isinstance(client_bindings, list):
        raise ConfigurationError(f"{label}第三方客户端绑定缺失。")
    client_specs: list[str] = []
    for item in client_bindings:
        if not isinstance(item, dict) or not isinstance(item.get("client_id"), str):
            raise ConfigurationError(f"{label}第三方客户端绑定结构非法。")
        receipt_path = _bound_evidence_path(
            stage,
            item.get("receipt"),
            label=f"{label}第三方入口 {item['client_id']} 收据",
        )
        client_specs.append(f"{item['client_id']}={receipt_path}")
    replayed = _parse_client_evidence(
        client_specs,
        [receipt_root],
        campaign_id=attempt["campaign_id"],
        attempt_id=attempt["attempt_id"],
        run_nonce=attempt["run_nonce"],
        attempt_started_at_utc=attempt["started_at_utc"],
        client_checkpoint_at_utc=client_checkpoint_at,
        candidate_id=str(candidate_id),
        target_version=campaign["target_version"],
        model=_third_party_client_model(campaign["configuration"]),
        identity=identity,
    )
    if _fingerprint({"items": replayed}) != _fingerprint(
        {"items": client_bindings}
    ):
        raise ConfigurationError(f"{label}Kilo 机器收据与阶段封存内容不一致。")


def _validate_evidence_bindings(
    values: Any,
    inventory: dict[str, str],
    *,
    rule: str,
    label: str,
) -> set[str]:
    if not isinstance(values, list) or not values:
        raise ConfigurationError(f"逐规则断言 {rule} 缺少{label}证据引用。")
    paths: set[str] = set()
    for value in values:
        if not isinstance(value, dict) or set(value) != {"path", "sha256"}:
            raise ConfigurationError(f"逐规则断言 {rule} 的{label}证据引用非法。")
        path = value.get("path")
        digest = value.get("sha256")
        if not isinstance(path, str) or inventory.get(path) != digest:
            raise ConfigurationError(f"逐规则断言 {rule} 的{label}证据摘要不匹配。")
        if path in paths:
            raise ConfigurationError(f"逐规则断言 {rule} 的{label}证据重复。")
        paths.add(path)
    return paths


def _command_option(command: list[str], name: str, rule: str) -> str:
    positions = [index for index, value in enumerate(command) if value == name]
    if len(positions) != 1 or positions[0] + 1 >= len(command):
        raise ConfigurationError(f"逐规则断言 {rule} 的机器命令缺少唯一 {name}。")
    return command[positions[0] + 1]


def _campaign_machine_command(
    campaign_dir: Path,
    manifest: dict[str, Any],
    classification: dict[str, Any],
    capture_stage: dict[str, Any],
    *,
    rule: str,
    output: Path,
    side: str,
) -> list[str]:
    context = capture_stage.get("assertion_context")
    if not isinstance(context, dict):
        raise ConfigurationError("抓包阶段缺少 assertion_context。")
    profile_reference = classification.get("assertion_profile_manifest")
    rule_reference = classification.get("target_rule_manifest")
    if not isinstance(profile_reference, dict) or not isinstance(rule_reference, dict):
        raise ConfigurationError("分类收据缺少目标断言画像或规则清单。")
    profile_path = _campaign_file(campaign_dir, str(profile_reference.get("path", "")))
    rule_path = _campaign_file(campaign_dir, str(rule_reference.get("path", "")))
    return build_machine_assertion_command(
        rule_id=rule,
        capture_manifest=str(context.get("capture_manifest_path", "")),
        evidence_root=str(context.get("evidence_root", "")),
        profile=str(profile_path.resolve(strict=True)),
        rule_manifest=str(rule_path.resolve(strict=True)),
        expected_codex_version=manifest["target_version"],
        expected_profile_sha256=str(profile_reference.get("sha256", "")),
        side=side,
        output=str(output.resolve()),
    )


def _rerun_machine_assertion(
    command: list[str],
    submitted: dict[str, Any],
    *,
    rule: str,
    label: str,
) -> None:
    """在 accept 内离线重放 checker，防止手工伪造 pass 收据。"""

    output_positions = [index for index, value in enumerate(command) if value == "--output"]
    if len(output_positions) != 1 or output_positions[0] + 1 >= len(command):
        raise ConfigurationError(f"逐规则断言 {rule} {label}重放命令缺少输出路径。")
    with tempfile.TemporaryDirectory(prefix="codex-egress-assertion-") as temporary:
        replay_output = Path(temporary) / "result.json"
        replay_command = list(command)
        replay_command[output_positions[0] + 1] = str(replay_output)
        try:
            replay = _run_external_command(
                replay_command,
                cwd=Path(__file__).resolve().parents[2],
                timeout_seconds=300,
                check=False,
                capture_output=True,
                text=True,
                operation=f"assertion-replay:{rule}:{label}",
            )
        except (OSError, subprocess.SubprocessError) as error:
            raise ConfigurationError(
                f"逐规则断言 {rule} {label}离线重放失败：{error}"
            ) from error
        if replay.returncode != 0 or not replay_output.is_file() or replay_output.is_symlink():
            detail = (replay.stderr or "").strip() or (replay.stdout or "").strip()
            raise ConfigurationError(
                f"逐规则断言 {rule} {label}离线重放未通过：{detail[:500]}"
            )
        replay_result = _read_json(replay_output, f"{rule} {label}重放结果")
    expected_fields = {
        "schema_version": MACHINE_ASSERTION_SCHEMA,
        "rule_id": rule,
        "status": "pass",
        "exit_code": 0,
        "checker_sha256": submitted.get("checker_sha256"),
        "command_sha256": machine_command_sha256(replay_command),
    }
    for field, expected in expected_fields.items():
        if replay_result.get(field) != expected:
            raise ConfigurationError(
                f"逐规则断言 {rule} {label}重放结果 {field} 不一致。"
            )
    if replay_result.get("checks") != submitted.get("checks"):
        raise ConfigurationError(
            f"逐规则断言 {rule} {label}提交检查项与离线重放不一致。"
        )


def _validate_machine_assertion(
    campaign_dir: Path,
    manifest: dict[str, Any],
    classification: dict[str, Any],
    capture_stage: dict[str, Any],
    row: dict[str, Any],
    rule: str,
    bound_paths: set[str],
    *,
    side: str,
) -> set[str]:
    label = "官方" if side == "official" else "候选"
    reference = row.get(f"{side}_machine_result")
    if not isinstance(reference, dict) or set(reference) != {"path", "sha256"}:
        raise ConfigurationError(f"逐规则断言 {rule} 缺少{label}机器结果绑定。")
    relative = reference.get("path")
    if not isinstance(relative, str) or Path(relative).is_absolute():
        raise ConfigurationError(f"逐规则断言 {rule} {label}机器结果路径必须位于 Campaign。")
    result_path = _campaign_file(campaign_dir, relative)
    if (
        not result_path.is_file()
        or result_path.is_symlink()
        or file_sha256(result_path) != reference.get("sha256")
    ):
        raise ConfigurationError(f"逐规则断言 {rule} {label}机器结果摘要不一致。")
    result = _read_json(result_path, f"{rule} {label}机器断言结果")
    if result.get("schema_version") != MACHINE_ASSERTION_SCHEMA:
        raise ConfigurationError(f"逐规则断言 {rule} {label}机器结果 schema 不受支持。")
    if (
        result.get("rule_id") != rule
        or result.get("status") != "pass"
        or result.get("exit_code") != 0
    ):
        raise ConfigurationError(f"逐规则断言 {rule} {label}机器结果未通过。")
    command = row.get(f"{side}_command")
    if not isinstance(command, list) or not command or not all(
        isinstance(value, str) and value for value in command
    ):
        raise ConfigurationError(f"逐规则断言 {rule} 缺少{label}机器命令。")
    context = capture_stage.get("assertion_context")
    if not isinstance(context, dict):
        raise ConfigurationError(f"{label}抓包阶段缺少 assertion_context。")
    expected_command = _campaign_machine_command(
        campaign_dir,
        manifest,
        classification,
        capture_stage,
        rule=rule,
        output=result_path,
        side=side,
    )
    if command != expected_command:
        raise ConfigurationError(f"逐规则断言 {rule} {label}机器命令未精确绑定当前版本 Campaign。")
    if machine_command_sha256(command) != result.get("command_sha256"):
        raise ConfigurationError(f"逐规则断言 {rule} {label}命令摘要不一致。")
    pinned_checkers = {
        entry.get("path"): entry.get("sha256")
        for entry in manifest.get("tool_identity", {}).get("entries", [])
        if isinstance(entry, dict)
    }
    checker_sha = pinned_checkers.get("candidate_rule_assertion.py")
    if not checker_sha or checker_sha != result.get("checker_sha256"):
        raise ConfigurationError(f"逐规则断言 {rule} checker 未绑定 plan 工具摘要。")
    checker_path = Path(__file__).resolve().parent / "candidate_rule_assertion.py"
    if not checker_path.is_file() or file_sha256(checker_path) != checker_sha:
        raise ConfigurationError(f"逐规则断言 {rule} checker 文件在 plan 后漂移。")
    checks = result.get("checks")
    if not isinstance(checks, list) or not checks:
        raise ConfigurationError(f"逐规则断言 {rule} 没有机器检查项。")
    check_ids: set[str] = set()
    for check in checks:
        if not isinstance(check, dict) or check.get("passed") is not True:
            raise ConfigurationError(f"逐规则断言 {rule} {label}存在未通过机器检查。")
        check_id = check.get("id")
        evidence_paths = check.get("evidence_paths")
        if (
            not isinstance(check_id, str)
            or not check_id
            or check_id in check_ids
            or check.get("expected") is None
            or check.get("actual") is None
            or not isinstance(evidence_paths, list)
            or not evidence_paths
        ):
            raise ConfigurationError(f"逐规则断言 {rule} {label}机器检查结构非法。")
        prefix = context.get("evidence_prefix")
        logical_paths = {
            f"{prefix}/{path}"
            for path in evidence_paths
            if isinstance(path, str) and not Path(path).is_absolute() and ".." not in Path(path).parts
        }
        if len(logical_paths) != len(evidence_paths) or not logical_paths.issubset(bound_paths):
            raise ConfigurationError(f"逐规则断言 {rule} {label}机器检查未精确引用封存证据。")
        check_ids.add(check_id)
    _rerun_machine_assertion(command, result, rule=rule, label=label)
    return check_ids


def _validate_assertion_results(
    campaign_dir: Path,
    assertions: dict[str, Any],
    *,
    rules: tuple[str, ...],
    manifest: dict[str, Any],
    candidate_id: str,
    classification: dict[str, Any],
    official: dict[str, Any],
    candidate: dict[str, Any],
    comparison: dict[str, Any],
) -> dict[str, Any]:
    required_top_fields = {
        "schema_version",
        "document_kind",
        "candidate_id",
        "target_version",
        "profile_id",
        "profile_digest",
        "official_package_digest",
        "candidate_package_digest",
        "comparison_package_digest",
        "acceptance_contract_sha256",
        "rules",
    }
    if assertions.get("schema_version") in LEGACY_RESULTS_SCHEMAS:
        raise ConfigurationError(
            "逐规则断言旧 schema 已废除：v1 的双侧同构与正负例契约没有事实来源，"
            "必须按 codex-egress-rule-assertions/v2 重新生成。"
        )
    if assertions.get("schema_version") != RESULTS_SCHEMA_V2:
        raise ConfigurationError("逐规则断言 schema_version 不受支持。")
    if not required_top_fields.issubset(assertions) or set(assertions) - required_top_fields - {"$schema"}:
        raise ConfigurationError("逐规则断言结果顶层字段不闭合。")
    if assertions.get("acceptance_contract_sha256") != _acceptance_contract_sha256(
        campaign_dir, classification
    ):
        raise ConfigurationError("逐规则断言未绑定冻结验收契约摘要。")
    if assertions.get("document_kind") != "results":
        raise ConfigurationError("逐规则断言 document_kind 必须是 results。")
    for field, expected in (
        ("candidate_id", candidate_id),
        ("target_version", manifest["target_version"]),
    ):
        if assertions.get(field) != expected:
            raise ConfigurationError(f"逐规则断言 {field} 与 Campaign 不一致。")
    identity = candidate.get("identity", {})
    for field in ("profile_id", "profile_digest"):
        if assertions.get(field) != identity.get(field):
            raise ConfigurationError(f"逐规则断言 {field} 未绑定候选身份。")
    required_bindings = (
        ("official_package_digest", comparison.get("official_package_digest")),
        ("candidate_package_digest", comparison.get("candidate_package_digest")),
        ("comparison_package_digest", comparison.get("package_digest")),
    )
    for field, expected in required_bindings:
        if assertions.get(field) != expected:
            raise ConfigurationError(f"逐规则断言 {field} 摘要不一致。")
    rows = assertions.get("rules")
    if not isinstance(rows, list):
        raise ConfigurationError("逐规则断言 rules 必须是数组。")
    official_inventory = _inventory_index(official, "官方")
    candidate_inventory = _inventory_index(candidate, "候选")
    validation_modes = _acceptance_validation_modes(
        campaign_dir, classification, rules
    )
    official_authority = _classification_official_authority(classification)
    seen: list[str] = []
    passed = 0
    for index, row in enumerate(rows, 1):
        if not isinstance(row, dict):
            raise ConfigurationError(f"逐规则断言 {index} 必须是对象。")
        rule = row.get("rule")
        if rule not in rules:
            raise ConfigurationError(f"逐规则断言 {index} 引用清单外规则。")
        mode = validation_modes[str(rule)]
        if row.get("validation_mode") != mode:
            raise ConfigurationError(
                f"逐规则断言 {rule} 的 validation_mode 与验收契约不一致。"
            )
        common_row_fields = {
            "rule",
            "validation_mode",
            "status",
            "candidate_evidence_refs",
            "candidate_machine_result",
            "candidate_command",
            "evidence_level",
            "rationale",
        }
        if mode == MODE_DUAL_WIRE:
            required_row_fields = common_row_fields | {
                "official_evidence_refs",
                "official_machine_result",
                "official_command",
            }
        else:
            required_row_fields = common_row_fields | {"official_authority"}
        if set(row) != required_row_fields:
            raise ConfigurationError(f"逐规则断言 {index} 字段不闭合。")
        if row.get("status") != "pass":
            raise ConfigurationError(f"逐规则断言 {rule} 没有机器通过，不得接受。")
        if row.get("evidence_level") != "full":
            raise ConfigurationError(f"逐规则断言 {rule} 证据等级不是 full。")
        rationale = row.get("rationale")
        if not isinstance(rationale, str) or not rationale.strip():
            raise ConfigurationError(f"逐规则断言 {rule} 缺少 rationale。")
        candidate_expected_check_ids = set(
            _acceptance_expected_check_ids(
                campaign_dir, classification, str(rule), "candidate"
            )
        )
        candidate_paths = _validate_evidence_bindings(
            row.get("candidate_evidence_refs"),
            candidate_inventory,
            rule=str(rule),
            label="候选",
        )
        candidate_check_ids = _validate_machine_assertion(
            campaign_dir,
            manifest,
            classification,
            candidate,
            row,
            str(rule),
            candidate_paths,
            side="candidate",
        )
        if candidate_check_ids != candidate_expected_check_ids:
            raise ConfigurationError(
                f"逐规则断言 {rule} 候选机器检查与批准画像 check 全集不一致。"
            )
        if mode == MODE_DUAL_WIRE:
            official_paths = _validate_evidence_bindings(
                row.get("official_evidence_refs"),
                official_inventory,
                rule=str(rule),
                label="官方",
            )
            official_check_ids = _validate_machine_assertion(
                campaign_dir,
                manifest,
                classification,
                official,
                row,
                str(rule),
                official_paths,
                side="official",
            )
            official_expected_check_ids = set(
                _acceptance_expected_check_ids(
                    campaign_dir, classification, str(rule), "official"
                )
            )
            if official_check_ids != official_expected_check_ids:
                raise ConfigurationError(
                    f"逐规则断言 {rule} 官方机器检查与批准画像 check 全集不一致。"
                )
        else:
            if row.get("official_authority") != official_authority:
                raise ConfigurationError(
                    f"逐规则断言 {rule} 未逐字绑定批准画像官方权威。"
                )
        seen.append(str(rule))
        passed += 1
    if sorted(seen) != sorted(rules) or len(seen) != len(set(seen)):
        raise ConfigurationError("逐规则断言未使目标规则全集唯一闭环。")
    return {
        "complete": True,
        "rule_count": len(rules),
        "pass_count": passed,
        "not_applicable_count": 0,
        "failed_rules": [],
    }


def _required_client_bindings(
    campaign_dir: Path,
    classification: dict[str, Any],
) -> set[str]:
    reference = classification.get("scenario_manifest")
    if not isinstance(reference, dict):
        return set()
    path = _campaign_file(campaign_dir, str(reference.get("path", "")))
    payload = _read_json(path, "目标场景清单")
    raw = payload.get("required_client_bindings", [])
    if (
        not isinstance(raw, list)
        or not all(isinstance(item, str) for item in raw)
        or len(raw) != len(set(raw))
        or not REQUIRED_CLIENT_BINDINGS.issubset(set(raw))
    ):
        raise ConfigurationError("目标场景 required_client_bindings 非法。")
    return set(raw)


def _write_blocked_acceptance_attempt(
    campaign_dir: Path,
    candidate_id: str,
    result: dict[str, Any],
) -> Path:
    """把未通过的 accept 结果写入独立 attempt，保留失败门禁供复核。

    accept 成功结果按 candidate-id 只封存一次；失败结果则允许修复后重跑，因此不能写入
    成功结果的规范路径，也不能覆盖上一轮失败。这里沿用抓包 attempt 的时间戳加随机后缀
    规则，为每次失败建立不可覆盖的私有目录。
    """

    if not SAFE_ID_RE.fullmatch(candidate_id):
        raise ConfigurationError("accept candidate-id 格式非法。")
    attempts_root = ensure_private_directory(
        campaign_dir / "acceptance" / candidate_id / "attempts",
        campaign_dir,
    )
    attempt_id = (
        time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
        + f"-{secrets.token_hex(8)}"
    )
    attempt_root = attempts_root / attempt_id
    if attempt_root.exists() or attempt_root.is_symlink():
        raise ConfigurationError("accept attempt-id 随机碰撞。")
    ensure_private_directory(attempt_root, campaign_dir)
    secure_write_json(attempt_root / "result.json", result)
    return attempt_root


def _candidate_external_gate_binding(
    *,
    evidence_root: Path,
    receipt_path: Path,
    manifest: dict[str, Any],
    candidate_id: str,
    candidate: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """独立重放 candidate 外部门禁，并与封存候选身份逐字段交叉验证。"""

    try:
        root = evidence_root.resolve(strict=True)
        candidate_receipt = (
            receipt_path.resolve(strict=True)
            if receipt_path.is_absolute()
            else (root / receipt_path).resolve(strict=True)
        )
        relative = candidate_receipt.relative_to(root).as_posix()
        payload = external_gate_receipt.replay(root, relative)
    except (
        OSError,
        RuntimeError,
        ValueError,
        external_gate_receipt.GateReceiptError,
    ) as error:
        raise ConfigurationError(f"candidate 外部门禁收据无法重放：{error}") from error
    identity = candidate.get("identity")
    subject = payload.get("subject")
    if not isinstance(identity, dict) or not isinstance(subject, dict):
        raise ConfigurationError("candidate 外部门禁缺少候选身份。")
    expected = {
        "campaign_id": manifest.get("campaign_id"),
        "campaign_mode": manifest.get("campaign_mode"),
        "campaign_purpose": manifest.get("campaign_purpose"),
        "candidate_id": candidate_id,
        "candidate_purpose": identity.get("candidate_purpose"),
        "target_version": manifest.get("target_version"),
        "profile_id": identity.get("profile_id"),
        "profile_digest": identity.get("profile_digest"),
        "candidate_package_digest": candidate.get("package_digest"),
        "candidate_source_tree_sha256": identity.get("source_tree_sha256"),
        "candidate_image_id": identity.get("image_id"),
        "candidate_image_reference": identity.get("image_reference"),
    }
    if (
        payload.get("phase") != external_gate_receipt.CANDIDATE_PHASE
        or payload.get("status") != "passed"
        or payload.get("failed_gate_ids") != []
        or any(subject.get(key) != value for key, value in expected.items())
    ):
        raise ConfigurationError("candidate 外部门禁收据与 Campaign／候选身份不一致。")
    binding = {
        "evidence_root": str(root),
        "receipt": {
            "path": relative,
            "sha256": file_sha256(candidate_receipt),
            "bytes": candidate_receipt.stat().st_size,
        },
    }
    return binding, payload


def _replay_bound_candidate_external_gate(
    value: Any,
    *,
    manifest: dict[str, Any],
    candidate_id: str,
    candidate: dict[str, Any],
) -> dict[str, Any]:
    """从 AcceptanceFact 保存的根与相对路径重放外部门禁。"""

    if not isinstance(value, dict) or set(value) != {"evidence_root", "receipt"}:
        raise ConfigurationError("AcceptanceFact candidate 外部门禁绑定非法。")
    receipt = value.get("receipt")
    if (
        not isinstance(value.get("evidence_root"), str)
        or not isinstance(receipt, dict)
        or set(receipt) != {"path", "sha256", "bytes"}
        or not isinstance(receipt.get("path"), str)
        or not SHA256_RE.fullmatch(str(receipt.get("sha256")))
        or not isinstance(receipt.get("bytes"), int)
        or receipt.get("bytes") <= 0
    ):
        raise ConfigurationError("AcceptanceFact candidate 外部门禁文件绑定非法。")
    binding, payload = _candidate_external_gate_binding(
        evidence_root=Path(value["evidence_root"]),
        receipt_path=Path(receipt["path"]),
        manifest=manifest,
        candidate_id=candidate_id,
        candidate=candidate,
    )
    if binding != value:
        raise ConfigurationError("AcceptanceFact candidate 外部门禁摘要或大小漂移。")
    return payload


def accept_campaign(
    campaign_dir: Path,
    candidate_id: str,
    assertions_path: Path,
    external_gate_root: Path,
    external_gate_path: Path,
) -> dict[str, Any]:
    """重放全部封存事实并签发用途冻结的 AcceptanceFact。"""

    _reject_contaminated_campaign(campaign_dir)
    if assertions_path.is_symlink() or not assertions_path.is_file():
        raise ConfigurationError("逐规则断言结果必须是非符号链接普通文件。")
    manifest = _require_formal_campaign(campaign_dir)
    candidate = _load_stage_result(
        campaign_dir, "capture-candidate", candidate_id
    )
    attempt_root, attempt = _capture_stage_attempt_context(
        campaign_dir,
        candidate,
        phase="candidate",
        candidate_id=candidate_id,
    )
    _bind_active_lease_attempt(
        campaign_dir,
        phase="candidate",
        candidate_id=candidate_id,
        attempt_id=attempt.get("attempt_id"),
    )
    _verify_plan_identity(
        campaign_dir,
        manifest,
        operation="accept",
        attempt_root=attempt_root,
        attempt=attempt,
    )
    official = _load_stage_result(campaign_dir, "capture-official")
    classification = _load_stage_result(campaign_dir, "classify")
    comparison = _load_stage_result(campaign_dir, "compare", candidate_id)
    candidate_purpose = candidate.get("candidate_purpose")
    if (
        candidate_purpose not in CANDIDATE_PURPOSES
        or candidate_purpose != manifest["campaign_purpose"]
        or comparison.get("candidate_purpose") != candidate_purpose
    ):
        raise ConfigurationError("candidate／compare 用途与 Campaign 冻结用途不一致。")
    external_gate_binding, external_gate = _candidate_external_gate_binding(
        evidence_root=external_gate_root,
        receipt_path=external_gate_path,
        manifest=manifest,
        candidate_id=candidate_id,
        candidate=candidate,
    )
    _verify_stage_evidence(official, "官方", campaign_dir=campaign_dir)
    _verify_stage_evidence(candidate, "候选", campaign_dir=campaign_dir)
    rules = _approved_rules(campaign_dir, manifest, require_approved=True)
    assertions = _read_json(assertions_path, "逐规则断言结果")
    assertion_gate = _validate_assertion_results(
        campaign_dir,
        assertions,
        rules=rules,
        manifest=manifest,
        candidate_id=candidate_id,
        classification=classification,
        official=official,
        candidate=candidate,
        comparison=comparison,
    )
    identity = candidate.get("identity", {})
    required_identity_fields = {
        "git_commit",
        "source_tree_sha256",
        "image_reference",
        "image_digest",
        "image_id",
        "build_id",
        "deployed_version",
        "profile_id",
        "profile_digest",
        "candidate_purpose",
    }
    identity_complete = required_identity_fields.issubset(identity) and all(
        identity.get(field) for field in required_identity_fields
    )
    identity_complete = identity_complete and bool(
        re.fullmatch(r"[a-f0-9]{40,64}", str(identity.get("git_commit", "")))
        and SHA256_RE.fullmatch(str(identity.get("source_tree_sha256", "")))
        and IMMUTABLE_IMAGE_RE.fullmatch(str(identity.get("image_reference", "")))
        and IMAGE_ID_RE.fullmatch(str(identity.get("image_digest", "")))
        and IMAGE_ID_RE.fullmatch(str(identity.get("image_id", "")))
        and SAFE_ID_RE.fullmatch(str(identity.get("build_id", "")))
        and SAFE_ID_RE.fullmatch(str(identity.get("deployed_version", "")))
        and SAFE_ID_RE.fullmatch(str(identity.get("profile_id", "")))
        and SHA256_RE.fullmatch(str(identity.get("profile_digest", "")))
        and identity.get("candidate_purpose") == candidate_purpose
    )
    attempt, receipt_root, client_checkpoint_at = (
        _candidate_stage_receipt_boundary(campaign_dir, candidate)
    )
    observed_profile_path = _bound_evidence_path(
        candidate,
        candidate.get("observed_profile"),
        label="运行画像观测",
    )
    _, observed_profile_receipt = _validate_observed_profile_receipt(
        observed_profile_path,
        [receipt_root],
        campaign_id=attempt["campaign_id"],
        attempt_id=attempt["attempt_id"],
        run_nonce=attempt["run_nonce"],
        attempt_started_at_utc=attempt["started_at_utc"],
        client_checkpoint_at_utc=client_checkpoint_at,
        candidate_id=candidate_id,
        target_version=manifest["target_version"],
        expected_profile_id=str(identity.get("profile_id", "")),
        expected_profile_digest=str(identity.get("profile_digest", "")),
        image_id=str(identity.get("image_id", "")),
        image_reference=str(identity.get("image_reference", "")),
        source_tree_sha256=str(identity.get("source_tree_sha256", "")),
        build_id=str(identity.get("build_id", "")),
        deployed_version=str(identity.get("deployed_version", "")),
    )
    client_bindings = candidate.get("client_bindings")
    if not isinstance(client_bindings, list):
        raise ConfigurationError("候选阶段缺少第三方客户端绑定。")
    client_specs: list[str] = []
    for item in client_bindings:
        if not isinstance(item, dict) or not isinstance(item.get("client_id"), str):
            raise ConfigurationError("第三方客户端绑定结构非法。")
        receipt_path = _bound_evidence_path(
            candidate,
            item.get("receipt"),
            label=f"第三方入口 {item['client_id']} 收据",
        )
        client_specs.append(f"{item['client_id']}={receipt_path}")
    reparsed_client_bindings = _parse_client_evidence(
        client_specs,
        [receipt_root],
        campaign_id=attempt["campaign_id"],
        attempt_id=attempt["attempt_id"],
        run_nonce=attempt["run_nonce"],
        attempt_started_at_utc=attempt["started_at_utc"],
        client_checkpoint_at_utc=client_checkpoint_at,
        candidate_id=candidate_id,
        target_version=manifest["target_version"],
        model=_third_party_client_model(manifest["configuration"]),
        identity=identity,
    )
    observed_clients = {item.get("client_id") for item in client_bindings if isinstance(item, dict)}
    required_clients = _required_client_bindings(campaign_dir, classification)
    client_bindings_valid = all(
        isinstance(item, dict)
        and item.get("status", "success") == "success"
        and item.get("model")
        == _third_party_client_model(manifest["configuration"])
        and item.get("profile_id") == identity.get("profile_id")
        and item.get("profile_digest") == identity.get("profile_digest")
        and item.get("protocol")
        in {"openai-compatible", "openai-responses"}
        and isinstance(item.get("request_evidence"), list)
        and bool(item.get("request_evidence"))
        and isinstance(item.get("response_evidence"), list)
        and bool(item.get("response_evidence"))
        for item in client_bindings
    )
    coverage = comparison.get("coverage", {})
    official_inventory_digest = official.get("evidence_inventory", {}).get("digest")
    candidate_inventory_digest = candidate.get("evidence_inventory", {}).get("digest")
    gates = {
        "campaign_purpose_matches": manifest.get("campaign_purpose")
        == candidate_purpose,
        "candidate_purpose_matches": identity.get("candidate_purpose")
        == candidate_purpose,
        "full_suite": manifest.get("suite") == "full",
        "official_identity_matches": official.get("identity")
        == manifest.get("official_identity"),
        "official_binary_identity_matches": _verify_sealed_official_binaries(
            official, manifest
        ),
        "candidate_identity_complete": identity_complete,
        "profile_binding_matches": bool(comparison.get("profile_binding_matches"))
        and observed_profile_receipt.get("status") == "active",
        # compare 的完整动态形态差异用于发现与复核，不能直接充当验收门禁：官方侧与候选
        # 侧的采集计划分别是 28 个任务和 7 个必需任务，完整指纹集合天然不等。行为等价性
        # 由批准断言画像推导的 42 条规则逐侧重放负责；这里仅要求 compare 本身已离线完成，
        # 其 package digest、证据 inventory 与画像绑定仍由下方独立门禁逐项校验。
        "comparison_complete": comparison.get("status") == "complete"
        and comparison.get("offline_only") is True,
        "rule_evidence_coverage": bool(official.get("results"))
        and bool(candidate.get("results"))
        and bool(coverage.get("complete")),
        "rule_assertions_complete": assertion_gate["complete"],
        "classification_unblocked": classification.get("status") == "complete"
        and classification.get("migration", {}).get("unclassified_count") == 0,
        "official_restoration_passed": bool(
            official.get("restoration", {}).get("passed")
        ),
        "candidate_restoration_passed": bool(
            candidate.get("restoration", {}).get("passed")
        ),
        "official_security_passed": official.get("security", {}).get("known_secret_scan_passed") is True,
        "candidate_security_passed": candidate.get("security", {}).get("known_secret_scan_passed") is True,
        "evidence_inventory_binding_matches": (
            comparison.get("official_evidence_inventory_digest") == official_inventory_digest
            and comparison.get("candidate_evidence_inventory_digest") == candidate_inventory_digest
        ),
        "third_party_bindings_complete": client_bindings_valid
        and _fingerprint({"items": client_bindings})
        == _fingerprint({"items": reparsed_client_bindings})
        and required_clients.issubset(observed_clients),
        "candidate_external_gate_complete": external_gate.get("phase")
        == external_gate_receipt.CANDIDATE_PHASE,
    }
    accepted = all(gates.values())
    result = {
        "schema_version": ACCEPTANCE_SCHEMA,
        "status": "complete" if accepted else "blocked",
        "accepted": accepted,
        "candidate_id": candidate_id,
        "campaign_mode": manifest["campaign_mode"],
        "campaign_purpose": manifest["campaign_purpose"],
        "candidate_purpose": candidate_purpose,
        "production_state": "accepted_not_activated",
        "target_version": manifest["target_version"],
        "profile_id": identity.get("profile_id"),
        "profile_digest": identity.get("profile_digest"),
        "assertions": assertion_gate,
        "gates": gates,
        "failed_gates": sorted(key for key, value in gates.items() if not value),
        "official_package_digest": official["package_digest"],
        "candidate_package_digest": candidate["package_digest"],
        "comparison_package_digest": comparison["package_digest"],
        "classification_package_digest": classification["package_digest"],
        "official_evidence_inventory_digest": official_inventory_digest,
        "candidate_evidence_inventory_digest": candidate_inventory_digest,
        "candidate_identity": {
            "source_tree_sha256": identity.get("source_tree_sha256"),
            "image_id": identity.get("image_id"),
            "image_reference": identity.get("image_reference"),
            "build_id": identity.get("build_id"),
            "deployed_version": identity.get("deployed_version"),
            "candidate_purpose": identity.get("candidate_purpose"),
        },
        "candidate_external_gate": external_gate_binding,
        # 保留原始集合是否逐项相等的诊断事实，但不把不同采集计划造成的差集伪装成失败。
        "equal": bool(comparison.get("equal")),
    }
    if accepted:
        acceptance_root = ensure_private_directory(
            campaign_dir / "acceptance" / candidate_id, campaign_dir
        )
        canonical_assertions = campaign_dir / "assertions" / candidate_id / "results.json"
        if assertions_path.resolve(strict=True) != canonical_assertions.resolve(strict=False):
            if canonical_assertions.exists():
                existing_assertions = _read_json(
                    canonical_assertions, "已封存逐规则断言结果"
                )
                if _fingerprint(existing_assertions) != _fingerprint(assertions):
                    raise ConfigurationError("逐规则断言结果已经封存且内容不同。")
            else:
                secure_write_json(canonical_assertions, assertions)
        assertion_binding = {
            "path": canonical_assertions.relative_to(campaign_dir).as_posix(),
            "sha256": file_sha256(canonical_assertions),
        }
        seal_path = acceptance_root / "evidence-seal.json"
        evidence_seal = {
            "campaign_manifest_sha256": file_sha256(campaign_dir / "campaign.json"),
            "campaign_mode": manifest["campaign_mode"],
            "campaign_purpose": manifest["campaign_purpose"],
            "candidate_purpose": candidate_purpose,
            "production_state": "accepted_not_activated",
            "official_package_digest": official["package_digest"],
            "classification_package_digest": classification["package_digest"],
            "candidate_package_digest": candidate["package_digest"],
            "comparison_package_digest": comparison["package_digest"],
            "assertion_result": assertion_binding,
            "candidate_external_gate": external_gate_binding,
            "official_evidence_inventory_digest": official_inventory_digest,
            "candidate_evidence_inventory_digest": candidate_inventory_digest,
        }
        if seal_path.exists():
            existing_seal = _read_json(seal_path, "已封存验收证据封印")
            if _fingerprint(existing_seal) != _fingerprint(evidence_seal):
                raise ConfigurationError("验收证据封印已经存在且内容不同。")
        else:
            secure_write_json(seal_path, evidence_seal)
        result["assertion_result"] = assertion_binding
        result["evidence_seal"] = {
            "path": seal_path.relative_to(campaign_dir).as_posix(),
            "sha256": file_sha256(seal_path),
        }
        save_stage_result(campaign_dir, "accept", result, candidate_id=candidate_id)
    else:
        _write_blocked_acceptance_attempt(campaign_dir, candidate_id, result)
    return result


def _normalize_legacy_argv(argv: list[str]) -> tuple[list[str], str | None]:
    commands = {
        "plan",
        "canonical-import",
        "canonical-advance",
        "successor",
        "capture-official",
        "classify",
        "prepare-profile",
        "stage-profile",
        "capture-candidate",
        "compare",
        "accept",
        "all",
        "status",
        "resume",
    }
    if argv and argv[0] in commands:
        return argv, None
    if "--dry-run" in argv:
        normalized = [value for value in argv if value != "--dry-run"]
        return ["plan", *normalized], "旧 --dry-run 已映射为 plan。"
    if "--execute" in argv:
        return argv, (
            "旧 --execute 已停用：真实抓包必须显式执行 plan、capture-official、"
            "classify、capture-candidate、compare、accept，避免自动跳过人工分类。"
        )
    return argv, None


def _reject_canonical_legacy_write(
    arguments: argparse.Namespace,
    command: str,
) -> None:
    """canonical checkpoint 建立后，旧恢复对象只能读取，禁止继续追加。"""

    if command not in {
        "successor",
        "control-epoch",
        "evaluation-transition",
        "terminal-transition-preflight",
    }:
        return
    roots: list[Path] = []
    campaign_dir = getattr(arguments, "campaign_dir", None)
    predecessor_dir = getattr(arguments, "predecessor_campaign_dir", None)
    if isinstance(campaign_dir, Path):
        roots.append(campaign_dir)
    if isinstance(predecessor_dir, Path):
        roots.append(predecessor_dir)
    if any((root / CANONICAL_DIRECTORY / CANONICAL_IMPORT_RECEIPT_FILENAME).is_file() for root in roots):
        raise ConfigurationError(
            "当前 Campaign 已切换到 canonical checkpoint；"
            "successor/control-epoch/runtime-repair/evaluation-transition "
            "只允许历史只读解析，禁止继续写入。"
        )


def _reject_campaign_run_legacy_write(
    arguments: argparse.Namespace,
    command: str,
) -> None:
    """正式 campaign-run 中硬拒绝所有旧写入入口。

    历史测试和只读解析仍可直接调用旧函数；一旦命令由 campaign-run 派发，
    父监督器会注入受管上下文，此处在取得 CampaignLease 前 fail-close，保证
    旧入口既不会写收据，也不会启动第二个监督器。
    """

    if not codex_upgrade_legacy_boundary.is_legacy_write_command(command):
        return
    if os.environ.get(codex_upgrade_supervisor.CAMPAIGN_RUN_CONTEXT_ENV) == "1":
        reason = codex_upgrade_legacy_boundary.formal_rejection_reason(
            command,
            campaign_run_context=True,
            formal_target=False,
        )
        raise ConfigurationError(reason or f"旧写入入口被拒绝：{command}")
    campaign_dir = getattr(arguments, "campaign_dir", None)
    if not isinstance(campaign_dir, Path):
        manifest = None
    else:
        manifest_path = campaign_dir / "campaign.json"
        if manifest_path.is_file():
            try:
                manifest = _read_json(manifest_path, "Campaign 清单")
            except ConfigurationError:
                manifest = None
        else:
            manifest = None
    # successor 的新输出目录尚无 campaign.json；此时用只读 predecessor
    # 清单识别 0.149.1→0.151.0 升级，仍必须在取得 lease 前拒绝。
    predecessor_dir = getattr(arguments, "predecessor_campaign_dir", None)
    predecessor_manifest = None
    if isinstance(predecessor_dir, Path):
        predecessor_path = predecessor_dir / "campaign.json"
        if predecessor_path.is_file():
            try:
                predecessor_manifest = _read_json(predecessor_path, "前序 Campaign 清单")
            except ConfigurationError:
                predecessor_manifest = None
    # 0.149.1 起的正式 Campaign（含所有未来版本）不再允许旧写入；只有更早的
    # 历史版本目录保留给只读回放和离线兼容测试，避免篡改历史收据语义。
    candidates = [item for item in (manifest, predecessor_manifest) if item]
    if any(
        item.get("campaign_mode") == "formal"
        and str(item.get("target_version", "")) not in LEGACY_WRITE_HISTORICAL_TARGETS
        for item in candidates
    ):
        reason = codex_upgrade_legacy_boundary.formal_rejection_reason(
            command,
            campaign_run_context=False,
            formal_target=True,
        )
        raise ConfigurationError(reason or f"正式 Campaign 禁止旧写入入口：{command}")


def _reject_unparented_formal_write(
    arguments: argparse.Namespace,
    command: str,
) -> None:
    """0.151.0 起的正式可变命令必须由 campaign-run 父监督器派发。

    判定按目标版本是否属于历史豁免集合，而不是逐版本硬编码，避免下一个目标
    版本悄悄退回人工逐条派发。
    """

    if os.environ.get(codex_upgrade_supervisor.CAMPAIGN_RUN_CONTEXT_ENV) == "1":
        return
    if command == "plan":
        # plan 只冻结并创建 Campaign 清单，不执行升级动作；后续所有正式
        # 可变阶段仍必须由 campaign-run 派发。
        return
    if command not in FORMAL_CAMPAIGN_RUN_COMMANDS:
        return
    campaign_dir = getattr(arguments, "campaign_dir", None)
    if not isinstance(campaign_dir, Path):
        return
    manifest_path = campaign_dir / "campaign.json"
    if not manifest_path.is_file():
        return
    try:
        manifest = _read_json(manifest_path, "Campaign 清单")
    except ConfigurationError:
        return
    target_version = str(manifest.get("target_version", ""))
    if (
        manifest.get("campaign_mode") == "formal"
        and target_version not in UNPARENTED_FORMAL_HISTORICAL_TARGETS
    ):
        raise ConfigurationError(
            f"目标 {target_version} 的正式命令必须由 campaign-run 派发：{command}"
        )


def build_formal_campaign_run_manifest(
    campaign_id: str,
    *,
    phase: str,
    deadline_seconds: float,
    execute_items: Iterable[str],
    reuse_items: Iterable[str] = (),
    action_specs: Mapping[str, Mapping[str, Any]],
    output: Path | None = None,
) -> dict[str, Any]:
    """把 VC-0～VC-6 的增量执行集合编译成 campaign-run 清单。

    ``execute_items`` 必须逐项提供 ``command``（以及可选的
    ``operation``、``timeout_seconds``）；``reuse_items`` 只作为 checkpoint
    读取摘要写入清单，绝不会生成动作。动作集合为空时统一生成 no-op 清单。
    旧 successor／epoch／transition 命令在生成阶段即拒绝，避免把非法入口
    写进不可变队列。
    """

    execute = [str(item) for item in execute_items]
    reuse = [str(item) for item in reuse_items]
    if len(set(execute)) != len(execute):
        raise ConfigurationError("execute_items 含重复 ID。")
    if len(set(reuse)) != len(reuse):
        raise ConfigurationError("reuse_items 含重复 ID。")
    if set(execute) & set(reuse):
        raise ConfigurationError("execute_items 与 reuse_items 不得交叉。")
    if set(action_specs) != set(execute):
        raise ConfigurationError("action_specs 必须与 execute_items 完全一致。")
    actions: list[dict[str, Any]] = []
    for item_id in execute:
        if not SAFE_ID_RE.fullmatch(item_id):
            raise ConfigurationError(f"execute item ID 非法：{item_id}")
        spec = action_specs[item_id]
        command = spec.get("command")
        if (
            not isinstance(command, (list, tuple))
            or not command
            or not all(isinstance(value, str) and value for value in command)
        ):
            raise ConfigurationError(f"execute item {item_id} 缺少合法 command。")
        command_name = Path(str(command[0])).name
        legacy_token = next(
            (value for value in command if value in LEGACY_WRITE_COMMANDS),
            None,
        )
        if command_name in LEGACY_WRITE_COMMANDS or legacy_token is not None:
            raise ConfigurationError(
                "正式 campaign-run 动作禁止旧写入入口："
                f"{legacy_token or command_name}"
            )
        operation = str(spec.get("operation") or f"{phase}:{item_id}")
        timeout_seconds = spec.get("timeout_seconds")
        if timeout_seconds is None:
            raise ConfigurationError(f"execute item {item_id} 缺少 timeout_seconds。")
        actions.append(
            {
                "action_id": item_id,
                "operation": operation,
                "timeout_seconds": timeout_seconds,
                "command": list(command),
            }
        )
    try:
        payload = codex_upgrade_supervisor.build_campaign_run_manifest(
            campaign_id,
            phase,
            deadline_seconds,
            actions=actions,
            reuse_items=reuse,
        )
    except codex_upgrade_supervisor.SupervisorError as error:
        raise ConfigurationError(str(error)) from error
    if output is not None:
        output = Path(output)
        if not output.is_absolute():
            raise ConfigurationError("campaign-run 清单输出路径必须是绝对路径。")
        _secure_write_json_once(output, payload)
    return payload


def _resolve_classification_inputs(
    arguments: argparse.Namespace,
    manifest: dict[str, Any],
) -> None:
    if not arguments.approve_manifest_sha256:
        return
    if arguments.target_rule_manifest or arguments.migration_manifest:
        return
    version_root = (
        Path(__file__).resolve().parent
        / "versions"
        / manifest["target_version"]
    )
    candidates = {
        "target_rule_manifest": version_root / "target-rules.json",
        "migration_manifest": version_root / "rule-migration.json",
        "scenario_manifest": version_root / "scenarios.json",
        "profile_manifest": version_root / "profile.json",
        "assertion_profile_manifest": version_root / "assertion-profile.json",
    }
    missing = [str(path) for path in candidates.values() if not path.is_file()]
    if missing:
        raise ConfigurationError(
            f"批准摘要已提供，但目标版本清单不完整：{missing}"
        )
    for field, path in candidates.items():
        setattr(arguments, field, path)


def _default_assertions_path(campaign_dir: Path, candidate_id: str) -> Path:
    return campaign_dir / "assertions" / candidate_id / "results.json"


def _resume_campaign(arguments: argparse.Namespace) -> tuple[dict[str, Any], int]:
    _require_formal_campaign(arguments.campaign_dir)
    status = campaign_status(arguments.campaign_dir, arguments.candidate_id)
    current = status["status"]
    if current == "environment_contaminated":
        raise ConfigurationError("环境恢复失败已封锁 Campaign，不能自动 resume。")
    if current in {
        "official_capture_interrupted",
        "candidate_capture_interrupted",
        "capture_state_inconsistent",
    }:
        raise ConfigurationError("存在孤儿预约或并发残留；只能人工审计后新建 Campaign。")
    if current == "candidate_selection_required":
        raise ConfigurationError("请先按 status 输出选择原 candidate-id，resume 不会猜测。")
    if current in {"official_capture_failed", "candidate_capture_failed"}:
        if not arguments.rerun_failed:
            raise ConfigurationError(
                "失败 attempt 只能显式使用 resume --rerun-failed 创建新 attempt。"
            )
        phase = "official" if current == "official_capture_failed" else "candidate"
        if phase == "candidate":
            required = {
                "candidate_id": arguments.candidate_id,
                "runtime_image": arguments.runtime_image,
                "build_id": arguments.build_id,
                "profile_id": arguments.profile_id,
                "profile_digest": arguments.profile_digest,
                "deployed_version": arguments.deployed_version,
                "candidate_purpose": arguments.candidate_purpose,
            }
            missing = sorted(key for key, value in required.items() if not value)
            if missing:
                raise ConfigurationError(f"候选失败重跑缺少身份参数：{missing}")
        result = _run_capture_attempt(arguments, phase)
        return result, 0 if result.get("status") in CAPTURE_SUCCESS_STATUSES else 2
    if current == "planned":
        result = _run_capture_attempt(arguments, "official")
        return result, 0 if result.get("status") in CAPTURE_SUCCESS_STATUSES else 2
    if current in {"official_awaiting_receipts", "official_awaiting_seal_approval"}:
        raise ConfigurationError(
            "官方 attempt 正等待机器收据或 seal 摘要批准；resume 不会代替人工审核。"
        )
    if current == "official_sealed":
        raise ConfigurationError("下一步是人工 classify；resume 不会自动批准语义分类。")
    if current == "blocked":
        raise ConfigurationError("分类存在 blocker；解决后应以新 Campaign/revision 审核。")
    if current == "profile_approved":
        required = {
            "candidate_id": arguments.candidate_id,
            "runtime_image": arguments.runtime_image,
            "build_id": arguments.build_id,
            "profile_id": arguments.profile_id,
            "profile_digest": arguments.profile_digest,
            "deployed_version": arguments.deployed_version,
            "candidate_purpose": arguments.candidate_purpose,
        }
        missing = sorted(key for key, value in required.items() if not value)
        if missing:
            raise ConfigurationError(f"resume 候选抓包缺少参数：{missing}")
        result = _run_capture_attempt(arguments, "candidate")
        return result, 0 if result.get("status") in CAPTURE_SUCCESS_STATUSES else 2
    if current in {
        "candidate_awaiting_client_checkpoint",
        "candidate_client_checkpoint_created",
        "candidate_awaiting_seal_approval",
    }:
        raise ConfigurationError(
            "候选 attempt 正等待 Kilo／机器收据或 seal 摘要批准；resume 不会代替人工审核。"
        )
    if current == "candidate_sealed":
        if not arguments.candidate_id:
            raise ConfigurationError("resume compare 必须指定 --candidate-id。")
        result = compare_campaign(arguments.campaign_dir, arguments.candidate_id)
        return result, _compare_result_exit_code(result)
    if current == "compared":
        if not arguments.candidate_id:
            raise ConfigurationError("resume accept 必须指定 --candidate-id。")
        if not arguments.external_gate_root or not arguments.external_gate_receipt:
            raise ConfigurationError(
                "resume accept 必须提供 --external-gate-root 和 "
                "--external-gate-receipt。"
            )
        assertions = arguments.assertions or _default_assertions_path(
            arguments.campaign_dir, arguments.candidate_id
        )
        result = accept_campaign(
            arguments.campaign_dir,
            arguments.candidate_id,
            assertions,
            arguments.external_gate_root,
            arguments.external_gate_receipt,
        )
        return result, 0 if result["accepted"] else 2
    return status, 0


def _main_without_campaign_lease(argv: list[str] | None = None) -> int:
    os.umask(0o077)
    raw_argv = list(sys.argv[1:] if argv is None else argv)
    normalized_argv, legacy_message = _normalize_legacy_argv(raw_argv)
    if "--execute" in raw_argv and not normalized_argv[:1] in (["all"],):
        print(f"升级审计失败：{legacy_message}", file=sys.stderr)
        return 1
    parser = _build_parser()
    arguments = parser.parse_args(normalized_argv)
    if legacy_message:
        print(legacy_message, file=sys.stderr)
    try:
        command = arguments.command
        _reject_canonical_legacy_write(arguments, command)
        _reject_campaign_run_legacy_write(arguments, command)
        _reject_unparented_formal_write(arguments, command)
        if command == "plan":
            manifest = create_campaign(arguments)
            preflight_invalidation = (
                _preflight_plan_invalidation_summary(manifest)
                if manifest["campaign_mode"] == "preflight_only"
                else {}
            )
            result = {
                "status": (
                    "preflight_complete"
                    if manifest["campaign_mode"] == "preflight_only"
                    else "planned"
                ),
                "campaign_id": manifest["campaign_id"],
                "campaign_mode": manifest["campaign_mode"],
                "campaign_purpose": manifest["campaign_purpose"],
                "campaign_dir": str(arguments.campaign_dir),
                "required_rule_count": len(manifest["required_rules"]),
                "job_count": len(manifest["jobs"]),
                **preflight_invalidation,
            }
            return_code = 0
        elif command == "reuse-official-evidence":
            # §5.3.3：官方证据一旦可信封存就只读复用。这里复用 successor 实现里
            # 的 official-only 导入分支，但走正式命令名，不属于旧写入入口；
            # 原因由子解析器固定为 official_evidence_reuse。
            if getattr(arguments, "reason", None) != OFFICIAL_EVIDENCE_REUSE_REASON:
                raise ConfigurationError("reuse-official-evidence 的原因不可更改。")
            result = create_successor_campaign(arguments)
            return_code = 0
        elif command in LEGACY_WRITE_COMMANDS:
            # 旧写入实现只允许历史离线兼容；正式 Campaign 已在上方拒绝。
            result = codex_upgrade_legacy_boundary.dispatch_historical_write(
                command,
                arguments,
                {
                    "successor": create_successor_campaign,
                    "control-epoch": create_control_epoch,
                    "evaluation-transition": create_phase_evaluation_transition,
                    "terminal-transition-preflight": create_terminal_transition_preflight,
                },
                allow_compatibility=True,
            )
            return_code = (
                0
                if command != "evaluation-transition"
                else (0 if result.get("status") == "approved" else 2)
            )
        elif command == "canonical-import":
            result = import_canonical_checkpoint(arguments)
            return_code = 0 if result.get("status") == "complete" else 2
        elif command == "canonical-advance":
            result = advance_canonical_checkpoint(arguments)
            return_code = 0
        elif command == "capture-official":
            if arguments.capture_action == "run":
                result = _run_capture_attempt(arguments, "official")
            else:
                result = _seal_capture_attempt(arguments, "official")
            return_code = 0 if result.get("status") in CAPTURE_SUCCESS_STATUSES else 2
        elif command == "classify":
            manifest = load_campaign_manifest(arguments.campaign_dir)
            _resolve_classification_inputs(arguments, manifest)
            result = classify_campaign(
                arguments.campaign_dir,
                target_rule_manifest=arguments.target_rule_manifest,
                migration_manifest=arguments.migration_manifest,
                scenario_manifest=arguments.scenario_manifest,
                profile_manifest=arguments.profile_manifest,
                assertion_profile_manifest=arguments.assertion_profile_manifest,
                approve_manifest_sha256=arguments.approve_manifest_sha256,
            )
            return_code = 0 if result.get("status") in CAPTURE_SUCCESS_STATUSES else 2
        elif command == "prepare-profile":
            result = prepare_profile_manifest(
                arguments.campaign_dir,
                arguments.snapshot,
                arguments.profile_id,
                arguments.output,
            )
            return_code = 0
        elif command == "stage-profile":
            result = stage_profile_catalog(arguments.campaign_dir, arguments.output)
            return_code = 0
        elif command == "capture-candidate":
            if arguments.capture_action == "run":
                result = _run_capture_attempt(arguments, "candidate")
            else:
                result = _seal_capture_attempt(arguments, "candidate")
            return_code = 0 if result.get("status") in CAPTURE_SUCCESS_STATUSES else 2
        elif command == "candidate-runtime-override":
            result = create_candidate_runtime_override(arguments)
            return_code = 0
        elif command == "compare":
            result = compare_campaign(arguments.campaign_dir, arguments.candidate_id)
            return_code = _compare_result_exit_code(result)
        elif command == "accept":
            assertions = arguments.assertions or _default_assertions_path(
                arguments.campaign_dir, arguments.candidate_id
            )
            result = accept_campaign(
                arguments.campaign_dir,
                arguments.candidate_id,
                assertions,
                arguments.external_gate_root,
                arguments.external_gate_receipt,
            )
            return_code = 0 if result["accepted"] else 2
        elif command == "all":
            if campaign_status(
                arguments.campaign_dir, arguments.candidate_id
            )["status"] != "profile_approved":
                raise ConfigurationError("all 只允许从 profile_approved 状态开始。")
            result = _run_capture_attempt(arguments, "candidate")
            result["next_command"] = (
                "完成 Kilo witness、机器 finalizer 与 seal 摘要复核；封存后再执行 compare。"
            )
            return_code = 2
        elif command == "deep-verify":
            result = deep_verify_campaign(
                arguments.campaign_dir,
                candidate_id=arguments.candidate_id,
                attempt_id=arguments.attempt_id,
            )
            return_code = 0
        elif command == "status":
            result = campaign_status(arguments.campaign_dir, arguments.candidate_id)
            return_code = 0
        elif command == "resume":
            result, return_code = _resume_campaign(arguments)
        else:
            raise ConfigurationError(f"不受支持的命令：{command}")
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return return_code
    except KeyboardInterrupt:
        active_lease = _ACTIVE_CAMPAIGN_LEASE
        if active_lease is not None:
            try:
                active_lease._mark_stop_line("owner_interrupted")
            except BaseException:
                pass
        print("升级抓包已中断；当前任务已收到终止信号。", file=sys.stderr)
        return 130
    except (
        ConfigurationError,
        OSError,
        RuntimeError,
        ValueError,
        subprocess.SubprocessError,
    ) as error:
        print(f"升级审计失败：{error}", file=sys.stderr)
        return 1


def main(argv: list[str] | None = None) -> int:
    """带 Campaign lease 的 CLI 入口。

    先在轻量解析阶段确定命令坐标，再调用原有 dispatch。这样所有正式可变
    命令共享同一个持久 owner；capture/resume 的内部递归会复用该 owner，
    不会创建嵌套锁或重置 deadline。
    """

    raw_argv = list(sys.argv[1:] if argv is None else argv)
    normalized_argv, _legacy_message = _normalize_legacy_argv(raw_argv)
    # 兼容入口的非法 --execute 会在原 dispatch 中立即拒绝；不要在此之前
    # 为一个尚未通过参数校验的命令创建 lease。
    if "--execute" in raw_argv and normalized_argv[:1] not in (["all"],):
        return _main_without_campaign_lease(argv)
    parser = _build_parser()
    arguments = parser.parse_args(normalized_argv)
    # 旧写入入口必须在 CampaignLease 之前拒绝，确保不会留下新的 lease、
    # attempt 或 stop 收据。
    try:
        _reject_campaign_run_legacy_write(arguments, str(arguments.command))
        _reject_unparented_formal_write(arguments, str(arguments.command))
    except ConfigurationError as error:
        print(f"升级审计失败：{error}", file=sys.stderr)
        return 1
    with _main_command_lease(arguments) as lease:
        return_code = _main_without_campaign_lease(argv)
        # 原 dispatch 为了保持 CLI 兼容会把 ConfigurationError 转成返回码，
        # 因而不会自动触发 context manager 的异常分支。返回 1 仍表示本次
        # 可变命令未形成合法终态，必须留下不可覆盖停线事实，不能标成 released。
        if lease is not None and return_code in {1, 130}:
            lease._mark_stop_line(
                "owner_interrupted" if return_code == 130 else "command_failed"
            )
        return return_code


if __name__ == "__main__":
    raise SystemExit(main())
